INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '운좋게 사람없는 날과 시간을 맞춰왔나보다 미술관을 대여한 느낌이 들어서 좋다. 커피 맛은 좋은편인데다 공간이 주는 힘이 있어서 더 맛있게 느껴진다. 오늘과 같은 날 올 수 있다면 혼자 한번 더 오고싶다.', 5, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
