INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '날씨 진짜 좋은날 오니까 더 좋네용 지난번에 왔을때더 좋았지만 오늘 더 좋네요 ㅎㅗㅎ 커피가 아주 만족스러워요! 근데 새로 나온 메뉴가 있어서 주문했는데 아이스크림이 조금 아쉬웠어용 ㅠ 항상 올때마다 친절하시고 쾌적해서 좋아요!', 68, 15, NULL, SYSTIMESTAMP);
