INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '커피에 진심인  곳입니다. 곳곳에 작품을 보는 듯한 인테리어에 편안한 BGM이 흘러나와 마음이 편안해 지고 쉼을 느낄 수 있는 공간입니다.', 50, 8, 'GOOD', SYSTIMESTAMP);
