INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '내면의 발견이라는 이름 처럼 저의 내면을 돌보는 시간을 가지면서 편안하게 있다가 갈 수 있는 곳이었어요 !! 전시회 같은 느낌도 들었고 루프탑도 있어서 사진 찍을 것도 다양했어요 ~ ㅎ 무엇보다 음료가 정말 맛있었고 정성스럽게 만드신 느낌이 많이 들었어요 외국인 친구분들께도 강추드려요 !! 👍🏻', 32, 5, 'GOOD', SYSTIMESTAMP);
