INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '길가다가 외관이 멋져서 들어와봤는데 안에가 미로처럼 3층까지 인테리어가 멋지게 되어있어요 중간중간 힐링 문구도 들어있고 바리스타분들이 친절하고 전문적인 포스가 뿜뿜 나네요! 티라미수를 시켰는데 이렇게 이쁘게 나올 줄 몰랐어요 받자마자 너무 감동~~!! 디카페인(메이플시럽) 시켰는데 부드럽고 풍미가 좋아요 😀 😍', 17, 10, 'GOOD', SYSTIMESTAMP);
