INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '친구의 추천으로 따라왔는데 공간도 너무 멋지고 음료도 특색있고 맛이 조화로웠어요! 이런 공간을 경험할 수 있다는 것 자체로 매우 만족스러운데 음료, 디저트 메뉴, 음악 모든 것이 잘 어우러졌습니다. 또 오고 싶은 곳이에요!', 9, 3, 'GOOD', SYSTIMESTAMP);
