INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '차분한 분위기에 고급스러워서 데이트하기 넘 좋아요 나만 알고싶은 공간이에요 !! 사장님도 세상 친절하셔서 기분좋게 먹고갑니다 다음에 또올거에요 완전 제취향 ㅎㅎ', 29, 2, 'GOOD', SYSTIMESTAMP);
