INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), 'ㅡㅁ악ㄷ비오는 수요일 음악도 인테리어도 너무 좋은 곳 발견이라는 단어 가 주는 신선함이 좋고 차와 어울리는 도서 추천 정말좋네요 다음 방문때는 또 어떤 발견이 있을지 기대되는곳^^ 오늘도 잘 머물다 갑니다', 34, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대입구 감성 카페 내면의 발견에 다녀왔어요 분위기부터 감성이 끝내주고 잔잔한 음악 속에서 커피 시음부터 완벽했습니다. 포토존이 가득하고 초록초록한 플랜테리어에 아늑해서 사진 찍기 좋고 센스있는 커피와 독특한 디저트까지! 맛도 끝내줬어요 시끄럽지 않고 잔잔한 공간 속에서 여유롭게 티타임하고 사진까지 알차게 찍고 싶다면 내면의 발견에 다녀오시길 바랍니다. 혼자 다녀와도 힐링 그 자체입니다. 사장님 친절하셔서 이용하는 내내 편했어요! 다음에 또 올게요~', 111, 23, 'GOOD', SYSTIMESTAMP);
