INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '스파이스라떼 달달하면서도 알싸함이 퍼져서 입맛에 잘 맞아 마지막 한모금까지 맛있게 마셨어요! 티라미숲 진한 에스프레소가 느껴져 반했어요~ 카페 구석구석 좋은 글귀도 있고 자연을 느낄 수 있어 좋았어요😊', 51, 11, 'GOOD', SYSTIMESTAMP);
