INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '이렇게 모든 공간이 예쁘고 대형 카페인곳이 주변에 많지 않은데 숨겨진 공간을 발견한것 같아 기분이 좋습니다:) 심지어 화장실까지 전시회같아요ㅎㅎ 다만 카공할수있는 높이의 테이블은 많지 않아 카공보다는 대화하러 오기에 더 적합한곳 같아요', 31, 3, 'GOOD', SYSTIMESTAMP);
