INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '서교동에 엄청난 카페가 나왔네요ㅎㅎ 규모도 엄청크고 전시회 온듯한 감성 공간들이 많아서 구경하는 재미까지 있어서 좋았어요^^ ☕️ 커피맛도 굿!!', 0, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '이름이 마음에 들어서 왔는데 인테리어가 너무 예술이에요... 커피도.. 디저트도... 분위기도........ 번창하세요 다음에 또 올래요... 내면의 발견 시그니처 커피가 조아요', 10, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대 잎 걸어가다 우연히 발견한 이색카페 들어오는 순간부터 갤러리에 온줄 착각이 들정도로 건축의 미학을 느끼는 순간이었네요 내면 발견이 주제인 세상에서 하나뿐인 카페이자 힐링공간입니다', 28, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '* 저는 팝업으로 방문한거라 평소 방문하실 때랑 사진 다를 수 있음! 1층 카페 공간엔 머무르진 못했고, 그 외에 2층이나 3층 공간 위주로 말하자면 규모는 작지만 아기자기하게 잘 꾸며져 있었어요! 그리고 두 분 다 친절하셨음 :) 2층 한 켠은 거울로 되어 있어 특이했고 햇빛 들어오니 👍 반대편은 아늑한 느낌의 인테리어고 옥상 개방되어 있으면 올라가 보시길! 6시~7시 이쯤 올라갔는데 더위 좀 풀리고 바람 솔솔 불어서 되게 좋았음..💕 길 따라 쭉 늘어진 전구? 빛이랑 식물들 덕에 힐링하는 기분이랄까 그리고 8주년 팝업 디저트 세트 (화장실 다녀온 사이 다 녹음ㅜ 제 실수) 예쁘게 담아주셨는데, 위에 올라간 아이스크림이 맛있었음! 음료는 양이 작아서 놀랐지만..🙃 단거 좋아하는데 밀크티 먹을걸 흑흑', 12, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '분위기가 너무나 묘하고, 좋은 카페였어요 엄청규모도큰데... 마치 요가원처럼 마음이 편해지는 느낌을 받았어요.너무 시끄럽지않은 느낌을 좋아하는분은 진짜 맘에 들어하실것같아요. 커피도 굉장히 색다르네요.', 16, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '공간 구성이 특이한 카페 매장 입장부터 자리 착석까지의 동선이 재미나요. 시그니쳐 커피인 ‘맛의 발견‘ 이 산미가 있는 쥬스형태의 커피라 상쾌하고 깔끔한 맛이 여름의 청량함으로 느껴져요!', 70, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '전시공간 같아요! 기획력이 돋보이는 공간이라 도심 속 힐링하고 싶으면 이곳으로 와보시는걸 추천! 음료도 너무 특색있고 하나하나 세심하게 신경쓴게 느껴져요🥰', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '아름다운 공간과 디저트가 있는 곳이에요. 음료를 주문하고 위층의 공간들을 둘러보는 재미가 있습니다. 천천히 여유롭게 즐겨보시길 추천드려요. 저는 티라미수를 주문했는데, 익숙하지만 특별한 맛을 즐기실 수 있어 추천드리고 싶어요. 편안히 혼자, 또는 휴양지에 들러 만난 카페처럼 가보시길 바래요.', 36, 8, 'GOOD', SYSTIMESTAMP);
