INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '드립커피 맛집이라고 해서 방문했어요 사장님 너무 친절하시고 무엇보다 커피에 얼마나 진심이신지 보여서 마시는 내내 너무 맛있게 잘 마셨습니다..🙊🩷 전시회장 같은 분위기에 대화하기도 너무 좋고 다음에 또 방문하고 싶네요 이런 공간 만들어 주셔서 감사합니다_!🐈‍⬛♥🍀', 127, 25, 'GOOD', SYSTIMESTAMP);
