INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '서울지인이 소개해서 다녀갑니다 :) 제가 간 날은 전시회가 없어서 아쉬웠지만 공간만으로도 충분히 만족했습니다 더욱이 메뉴마다 정성스런 안내까지~ 대접받는 느낌이였어요 :)', 61, 15, 'GOOD', SYSTIMESTAMP);
