INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '매장이 너무 예쁘고 전시회 같아요 대형카페라 3층까지 있고 사진 너무 잘나와요 커피가 너무 고급져서 놀랐어요… 실내 데이트 카페로 최고', 39, 4, 'GOOD', SYSTIMESTAMP);
