INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '들어설 때부터 예뻐서 기분이 좋아지는 미로같은 입구가 있어요 분위기와 음악도 좋고 서비스도 좋아요 오늘의 커피도 시음하게 해주셨는데 좋은 맛이어서 커피를 마실 생각이 없었는데 커피를 마시게 됐어요 느낌이 좋은 곳입니다 :)', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '들어서는 것만으로도 위로와 응원을 받는 기분이었습니다 :). 시음 커피와 곳곳의 문구들, 백일장 선물까지 ! 일상의 정성이라는 감정을 전달해주셔서 감사해요!', 34, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '분위기의 공간으로, 혼자 공부하거나 대화를 나누기에 적합한 곳입니다.  좌석이 다양하고 공간이 넓어 붐비는 시간을 피하면 쾌적하게 이용할 수 있습니다. 유사 전시회에 온 것 같은 기분이 들어 평일에 온다면 여유로운 시간을 보내실 수 있을 것 같아요', 22, 10, 'GOOD', SYSTIMESTAMP);
