INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '전시도 구경하고, 브루잉 커피도 마실 수 있는 곳 내면의 발견. 공간이 넓고, 분리가 되어 있어서 마음에 드는 공간을 찾아 앉을 수 있어요. 작가들과 연계하여 전시도 하는데 전시 보는 걸 좋아하신다면 방문해서 시간 보내시는 것도 좋을 거 같아요!', 55, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '아아니 서울에 이런 곳이 있었다니...! 엄청난 발견했어요오 💓 인테리어 넘 감각적이구 공간 자체가 전시를 하고 있어서 예술 작품 속에 들어와 커피 마시는 느낌이에요✨ 한 번쯤 방문해보시길 추천합니다!', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '점심시간에 산책하다가 들렀는데 매장이 너무 멋져요! 빈브라더스 원두사용한다고 해서 믿고 들어왔는데, 라떼 맛집이네요😌 분위기도 좋고 사장님도 친절하세요! 자주 들를게요~!🤍', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '비오는날 지나가다가 외관에 끌려서 방문했어요 독특한 구조의 카페인데 갤러리같이 꾸며져있어서 좋았어요 길게 세워진 벽이 일상과 단절되는 느낌이라 좋네요 여유로운 분위기에서 커피한 잔 즐길 수 있는 곳이라 한번씩 들릴 예정이에요', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '서울 커피맛집 열심히 찾다가 온 카페인데 진짜 만족스러워요! 매장도 전시회 보는 것처럼 완전 분위기 있고,, 뭔가 제주도 감성 카페 같은?ㅎㅎ 드립커피랑 티라미숲 먹었는데 드립커피야 커피전문점 답게 진짜 맛있었고 티라미수도 정통적인 맛이라 좋았어요!! 넘 최고👍 담에도 찾아오고 싶어용🥰', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '마치 인사동에 있을 법한 작은 갤러리 같은 카페 내면의 발견 카페 컨셉 자체가 일상 속에서 색다른 경험을 할 수 있는 공간이다 그래서 그런지 입구에 들어서면서부터 자아를 찾기 위한 여정이 시작 되는데..... 시그니처 음료인 맛의 발견은 이름처럼 지금 까지 느껴 본 적 없는 향긋함과 달콤함이 느껴진다. 평소 달달한 커피를 싫어 하는 나도 끈적함 없는 청량한 달콤함에 홀짝 홀짝 계속 마셨다. 독특한 컨셉의 카페를 좋아 하거나 카페 사진 촬영 하는 걸 좋아 하는 사람들이라면 내면의 발견 추천한다.', 32, 2, 'GOOD', SYSTIMESTAMP);
