INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '공간이 정말 이뻐요! 시음으로 주셨던 커피도 정말 맛있어요☺️ 친절한 설명과 안내도 감동이어요. 고요하고 깨끗한 감성카페여요🥰 집 근처여서 자주 올 것 같네요!! 홍대 카페로 ’내면발견‘ 강추!!!☺️☺️', 120, 25, 'GOOD', SYSTIMESTAMP);
