INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '일단 음료도 맛나고, 정성이 많이 들어가있음을 느낍니다. 항상 매월 새로운 이벤트를 하시는 모습에 참 멋진 공간이라고 생각이 듭니다. 많이 번창하시길!', 26, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '서교동에 신상카페 ‘ 내면의 발견 ’ 이 오픈했습니다 이끼와 돌 , 수공간 등 으로 만들어진 정원이 멋져요 도심속의 오아시스 같은 공간입니다 이색적이에요 명상하기도 좋을것 같은 분위기 입니다 커피맛집이에요', 49, 8, 'GOOD', SYSTIMESTAMP);
