INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '이름이 마음에 들어서 방문했는데 공간은 더더 마음에 들어요..🖤 층 마다 분위기가 사뭇 다른게 포인트! 커피도 맛있는데 사장님이 내어주신 디저트가 진짜,,너무 맛있었습니다!!!!! 자주 오겠습니다••••🖤', 25, 2, 'GOOD', SYSTIMESTAMP);
