INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '망원에 힙한 카페가 생긴거같아요!! 인테리어가 전시회같은 분위기이고요~ 공간 구석구석 보는재미가있어요ㅎㅎ 커피도 정말 맛있고 고급스러운 느낌이 납니다! 데이트하러 오기 딱 좋은곳입니다~^^', 85, 17, 'GOOD', SYSTIMESTAMP);
