INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '재방문했습니다! 오후에 가만히 앉아서 보는 서교동 풍경이 멋져요 🥹 맛있는 커피 홀짝대면서 흘러나오는 잔잔한 음악 듣다가, 어디서 나는지 모를 좋은 향기도 맡다가, 바람에 흔들리는 나무를 보다보면 한결 편안한 마음으로 이곳을 나가게 되는 것 같아요 🫶🏻 올 때마다 좋은 경험 감사합니다 ☺️', 11, 5, 'GOOD', SYSTIMESTAMP);
