INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '공간이 너무 감각적이라 들어와서 까암짝 놀랐어요. 제주도 어딘가에 와있는 느낌도 들고. 들어오는 입구는 평범한데 카페로 향하는 계단과 중간에 꾸며진 곳이 너무 멋져요. 커피도 맛있어요.', 85, 14, 'GOOD', SYSTIMESTAMP);
