INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '멋진 공간입니다. 만드신 분들이 궁금해져요. 서비스커피를 비롯하여 제가 주문한 라떼도 (아몬드밀크 무료) 맛있었고, 판나코타도 단맛과 산미의 조화가 적절했어요.', 33, 3, 'GOOD', SYSTIMESTAMP);
