INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '벌써 4번째 방문이지만 리뷰를 드디어 써보네요 가오픈 전부터 오래 공실이었던 곳이 공사하는 걸 봐서 기대하고 있다가 가오픈한 후에 기회가 되어 방문하게 됐습니다 💓💓😭 공간 하나하나가 전시 공간 느낌이었고 어디를 가서도 보지 못했던 공간들이 가득해서 보는 눈들이 즐거웠습니다 내면의 발견.. 이름값하는 카페였어요.. 뭔가 나올 때 공자가 된 느낌 ㅎㅎ 전에 방문해서 먹은 유자민트티랑 커피도 맛있고 시그니처 커피 신세계였습니다 나머지 음료도 도장깨기 해볼게요~ 앞으로 주민으로서 단골될 듯  호호👍👍', 42, 7, 'GOOD', SYSTIMESTAMP);
