INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '새로 오픈했다고하여서 방문했는데 카페디자인전문성을 물씬풍기는 공간의여유성을 충분히 느끼게 해주었어요.딸이랑같이 방문했는데 옥상 까지있어서 눈치보지않고 콩콩콩 거릴수있고 심심하지않고 느긋한시간을 아주 잘보내고왔어요.디져트도 더더더 추가했으면좋겠다는생각이에요.왕추천합니다.', 78, 12, 'GOOD', SYSTIMESTAMP);
