INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '회사가 이 근처라 한번 와봐야지 지나치고 하다가 첫 방문. 조용히 작업하거나 티타임 약속잡기에 딱 좋은 공간. 미술관처럼 잘 가꿔진 공간에 깔끔한 음료. 비오는 날 유자 민트티 달콤상쾌해요 🌿🙌 다음엔 추천해주시는 이곳 커피를 꼭 마셔보는 걸로~ 😉', 42, 9, 'GOOD', SYSTIMESTAMP);
