INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '작은 현대 미술관을 온 느낌입니다. 작은 현대 미술관을 온 느낌입니다. 마음이 심란할 때 청정을 찾고 명상을 하는 데도 좋습니다. 지역 명소로서 손색이 없습니다.', 37, 4, 'GOOD', SYSTIMESTAMP);
