INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친구가 홍대가면 꼭 들러야한다고해서 방문했는데 인생 역사상 제일 진한 초콜릿 영접했습니다ㅎㅎ 일요일 오전 12시 30분 기분 바로 입장 가능하였고 직원분께 메뉴 추천해달라고 했더니 친절하게 설명해 주셨습니다. 노멀은 달달하고 매니아 초콜릿이 확실히 더 씁쓸한 맛이 강합니다ㅎㅎ그리고 너무 꾸덕한 초콜릿이 싫은 분들은 탄산수 꼭 추가하시길!!!! 러스크는 선택이 아니라 필수이니 초콜릿 음료 주문할때 꼭 같이 먹어보세용 완전 맛남', 63, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '''지금까지 이런 초콜릿은 없었다.'' 홍대에서 유명한 블루리본 초콜릿 가게입니다. 밸런타인 데이를 맞아 6구 초콜릿을 사러 갔어요. 예전 방문 때는 경의선숲길 근처였는데 지금은 골목 안쪽에 멋진 건물로 이사를 하셨어요. 평일 오후 3시  넘어 방문했는데 카페 앞에 웨이팅 하시는 분들이 어림잡아 10분 계셨어요. 전 포장이라 바로 매장 안으로 들어갔어요. 러키한게 제가 초콜릿을 딱 사고나니 품절 안내문이 붙었어요 ㅎㅎ 초콜릿은 역시나 괜히 유명한게 아닌 맛이에요. 이때까지 먹었던 초콜릿과 확실히 다른 퀄리티의 맛이에요. 한 입에 먹기 매우 아까운 맛이에요. 입에 넣으면 사르르 녹으면서 초콜릿 특유의 짙은 향이 거의 나지 않은 채 은은하게 맛있어 제대로 취향저격이에요. 이정도 초콜릿이라면 당뇨가 걸려도 좋아요', 16, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '케이크는 우유크림? 때문인지 연한 느낌! 역시 진짜 진한 초코가 더 진해요 다음에는 초코말고 음료도 시켜볼까봐요 여름에 아이스크림 먹으러 또올게요!', 41, 7, 'GOOD', SYSTIMESTAMP);
