INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜진한초코 노멀(쓴&단맛 같이 있는거)이랑 러스크, 탄산수 이렇게 주문했어요~ 전 원래 느끼한걸 잘 못 먹는데(크림빵도 못 먹어요) 여기서는 탄산수를 같이 주문할 수 있게 되어 있어서, 초콜릿 먹는 중간중간 입가심하면서 먹어서 정말 끝까지 맛있게 잘 먹었어요 😄 러스크도 딱 적절하게 바삭하고 안 달아서 초코랑 먹기에 딱이었어요~ 맛있게 잘 먹고 갑니다 다음엔 친구들이랑 오고 싶어요~', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '케이크가 품절이라 조금 아쉬웠어요 다음에 재방문 해서 꼭 케이크 먹어볼래요........🥲 러스크도 맛있고 진짜 진한 노멀 시켰는데 정말 진합니다 목구멍으로 초콜릿이 진하게 내려가는 맛....', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '인생 초코 빙수, 17도씨 현장 웨이팅만 가능하고 11시 반부터 대기걸 수 있어요. 11시 반 맞춰서 방문했더니 1번째였어요 초콜릿 빙수 오리지널 / 진짜 진한 초콜릿 음료 노멀로 주문했어요. 빙수는 먼저 얼음 맛본 후 취향에 따라 토핑 얹어먹으면 된다고 설명해주셨어요. 토핑은 초코 소스 / 아몬드 슬라이스 / 초코볼이 나와요. 초코라서 해서 엄청 달 줄 알았는데 전혀 아니에요,, 많이 먹어도 부담없는 초코맛! 입에 넣자마자 사르르 녹는 우유 얼음에 고급스러운 초코맛이 👍 진짜 진한 초콜릿 음료는 이름처럼 엄청 진해서 중탕한 초콜릿 퍼먹는 거 같아요 꾸덕 그 자체 살짝 산미 있는 초코맛이라 제 스타일은 아니었어요 재방문하면 초코빙수만 먹을 예정! 직원분들 엄청 친절하시고 깔끔해서 강추해요', 122, 21, 'GOOD', SYSTIMESTAMP);
