INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '시즌 메뉴인 초콜릿 빙수 먹었는데 가게에서 파는 부드럽고 진한 초콜릿 아이스크림을 빙수로 만든 맛입니다. 아몬드, 초코볼, 초코소스 등을 얹으면 다양한 맛을 즐길 수 있습니다. 선물로 초콜릿 단품도 샀습니다. 무척 부드러운 맛으로 고급스러워서 선물로 좋습니다. 개인 추천은 소금캬라멜과 산딸기.', 48, 6, 'GOOD', SYSTIMESTAMP);
