INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '초코빙수 먹으러 오는 단골집이예요 빙수와 아이스크림은 역시 보장된맛이고 커피도 맛있어요~ 여름마다 빙수와 아이스크림 기다려지는 곳입니다! 직원들도 친절해서 기분이 좋아지는곳이예요', 18, 10, 'GOOD', SYSTIMESTAMP);
