INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '초코빙수 맛집이라고 해서 웨이팅 감수하고 방문해봤어요 👍 녹진한 초코맛이 진하게 느껴져서 넘넘 좋았어요🥹💗 밀크맛 먹었는데 담에는 다크맛도 도전해보려구요😆👍', 229, 67, 'GOOD', SYSTIMESTAMP);
