INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '진짜 진한 초코, 노말로 마셨어요! 탄산수가 진짜 깔끔하게 싹 내려줘서 다마시고 입가심하기 좋아요. 친구가 정말 맘에 들어해요. 최고의 초콜릿이래요 ㅋㅋ', 48, 1, 'GOOD', SYSTIMESTAMP);
