INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '초코빙수가 진짜 맛있어요 싸구려 초코 아니고 진짜 달달하면서 진한 초코 맛인데 무겁지는 않은 정말 딱 적당한 맛이에요 진짜진한초코는 이름대로 정말 진한 맛인데 씁쓸하면서 달콤한 듯 하다가 묵직하게 떨어지는게 한 번쯤은 먹어볼 만 합니다 초코빙수 추천!', 90, 18, 'GOOD', SYSTIMESTAMP);
