INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '초콜릿 전문점 처음 가보는데 맛있어요 친구가 좋아해서 가봤는데 초코 좋아하시면 추천 케이크는 특별하진 않았지만 무난히게 맛있어요', 19, 4, 'GOOD', SYSTIMESTAMP);
