INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), 'sns에서 보고 갔는데 다양한 토핑으로 맛을 즐길 수 있어서 좋아요. 인기가 너무 많아져서 대기 시간이 길긴 했지만 주변에 다른 볼거리나 구경할게 많아서 기다리다 보면 금방 먹을 수 있어요', 79, 15, NULL, SYSTIMESTAMP);
