INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '다시 한번 진짜 진한 초콜릿도 마시고 원래 하절기에만 파시는 초코 아이스크림도 먹었습니다. 둘다 초코맛도 진하고 맛있게 먹었습니다. 츄로스에 초콜릿 찍어먹는 건 매번 행복해지는 맛이네요', 9, 3, 'GOOD', SYSTIMESTAMP);
