INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '대표 메뉴인 진짜 진한 초콜릿을 먹었습니다. 추러스, 생크림, 탄산수 추가! 된다면 세개 전부 추가하시는게 좋아요. 매니아로 주문했는데 씁쓸하면서 산미가 느껴지는데 정말 진하고 걸쭉해서 맛있었습니다. 츄러스 찍어먹고 달달한 생크림 곁들여 먹고 시나몬 뿌려먹기도 했습니다. 찐한 초콜릿 한 잔 비우면서 탄산수로 입가심하면 입안이 깔끔하게 정리돼서 좋았습니다. 사장님 메뉴 센스가 대단하시다고 생각되었습니다. 너무 즐거운 시간이었습니다.', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '오랜만에 들러본 17도씨! 처음 와본다는 친구들과 함께 즐거운 시간 보내고왔어요 서빙해주시면서 시나몬을 곁들여도 좋다셔서 중간부터 살짝 뿌려서 함께 떠먹었는데 색다른 풍미를 즐길 수 있어서 만족했습니다😋', 30, 8, 'GOOD', SYSTIMESTAMP);
