INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '진짜 진한 초콜릿 음료에 곁들여 먹는 갓 구운 츄러스가 별미였습니다. 개인적으로 초콜릿을 좋아하는 편이라 무척 만족스러운 카페였습니다.', 115, 23, 'GOOD', SYSTIMESTAMP);
