INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아이스크림이 마냥 달지않고 씁쓸한 카카오 맛이에요 초콜릿봉봉은 산딸기 맛을 먹었는데 생각보다 산딸기 맛이 강해 밀크를 먹을걸하고 조금 후회했어요', 10, 10, NULL, SYSTIMESTAMP);
