INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '드디어 17도씨의 츄러스와 초코를 먹어봤어요 단 정도를 선택할수 있어서 좋았어요 츄러스는 좀더 바삭했으면 좋겠습니다 더 튀기면 식감이 더 살아날거라고 생각해요', 12, 0, NULL, SYSTIMESTAMP);
