INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '충격 진또배기 초콜릿 음료 실존! 츄러스랑 꼭 같이 드시길 추천합니다 그냥 먹으니까... 빵같은 디저트가 계속 생각났어요ㅋㅋㅋㅋ', 69, 15, NULL, SYSTIMESTAMP);
