INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '와 빙수 못먹었으면 억울했을뻔... 초코에 진심인 가게라서 초코초코가 아주 엄청나다 블루리본?이거 잇던데 이런게 잇는줄 첨알았다 ''0'' 와우', 7, 7, 'GOOD', SYSTIMESTAMP);
