INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '여기를 가게 된다면 초코는 꼭 먹어야해요! 진짜 어디가서 못먹을 그런 초코입니다! 만약 2명이상 같이간다면 아메리카노 한잔 같이 시키세요 ㅋㅋㅋ 초코먹고 아메리카노마시면 더 맛있어요 ㅎㅎ', 48, 9, 'GOOD', SYSTIMESTAMP);
