INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '맛있고 제대로 만드는 봉봉 쇼콜라를 구매할 수 있습니다! 입안에서 싹 녹아서 남는 끈적임이나 찝찔함 없이 사르르 사라져요 ㅎㅎ 제대로 하는 집이네요 ㅎㅎ 그리고 친절하시고 좋아요 ㅎㅎ', 16, 1, 'GOOD', SYSTIMESTAMP);
