INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '빙수가 너무 궁금해서 가봤는데 생각보다 더 맛있어요. 초콜릿이라지만 너무 달지 않고, 쌉싸름하면서도 카카오 특유의 새콤한 맛이 느껴집니다.', 0, 3, 'GOOD', SYSTIMESTAMP);
