INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '초콜릿 음료 땡기는 날에는 무조건 17도씨. 초콜릿의 진심인 가게라는 것은 메뉴판을 보면 알 수 있다. 단연코 서울에서 제일 초콜릿에 진심인 가게라 생각한다.', 43, 10, 'GOOD', SYSTIMESTAMP);
