INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '진짜진한쵸콜릿음료 먹고싶어서 방문!이런쵸콜릿 너무 먹고싶었거든요!너무 맛있었고 기대하지 않았던 빙수도 너무 맛있었어요!카페 인테리어나 분위기는 그냥 동네 커피숍처럼 별건없는데 깔끔해요.초코 좋아하는분들은 연남동 방문하실때 꼭한번 드셔보세요!울집옆에 있어서 쵸콜렛 맨날 퍼먹고싶다ㅠ', 22, 8, 'GOOD', SYSTIMESTAMP);
