INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '버터링 다크 한개 남아서 골랐어요. 선물 주려고 샀는데 기대돼요 초코음료는 진하고 맛있어요. 키오스크 주문이라 여러 메뉴 보고 고를 수 있어요.', 28, 0, 'GOOD', SYSTIMESTAMP);
