INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '하.. 사진보니까 또 먹고싶어져요.. 첫입에 너무 달아서 눈 딱 떠졌는데.. 너무 단데 좋아요ㅋㅋㅋㅋ 약간 고디바 초콜릿? 같이 진한 초콜릿맛 나용', 12, 5, 'GOOD', SYSTIMESTAMP);
