INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '2018년부터 꾸준히 들르는 초코 맛집… 여름엔 꼬옥 초코빙수 먹어주면 돼… 음료도 맛있고 빼빼로데이때 나오는 빼빼로도 짱 맛있고 초코씌운 버터링도 맛있음 ㅠㅠ', 5, 6, 'GOOD', SYSTIMESTAMP);
