INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '여태 방문했어도 홀케이크 판매 하는건 몰랐는데ㅠ 우연히 홀케이크 판매를 보고 마침 가족 생일이라 주문했습니다~ 초콜렛만 최고인줄 알았는데.. 여태 먹은 초코케이크중 가장 최고입니다😲', 54, 13, NULL, SYSTIMESTAMP);
