INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '다크 초코 빙수를 시켰는데 진짜 맛이 진하더라고요! 차 종류도 많아서 좋았습니다! 차랑 먹으니 완전 좋았어요ㅋㅋㅋ초코 종류도 많아서 날 덥지 않을 때 가면 초코 쌓아두고 먹고싶어요ㅋㅋ 사람이 많은 탓인지 가게가 시원하진 않았던 아쉬움이 있어요ㅠㅠ', 11, 9, NULL, SYSTIMESTAMP);
