INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '매년매년 먹는 십칠도씨 초코빙수! 화장실 위생상태 최상 몇년째 음식양 불변 단 한가지 인기에 비해 가게가 좁다는 점 외엔 아쉬운점 없고 얼그레이 핫초코 추천합니다', 4, 5, 'GOOD', SYSTIMESTAMP);
