INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '분위기 좋아요. 핫초코도 맛있다고 하네요. 전 단 것을 안좋아해서 마르코폴로 홍차 먹었는데 향도 좋고 적당히 달짝지근해서 완전 맛나요~~~', 67, 12, 'GOOD', SYSTIMESTAMP);
