INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '한번씩 핫초코 생각날때마다 들르는 카페. 수제 초코들도 정말 많은, 초코 특화 카페입니다. 핫초코 진하기도 선택할 수 있어 특히 매력적인데 오늘은 80퍼 핫초코를 마셨어요. 에스프레소 같이 작은 잔에 걸쭉한 느낌의 핫초코가 담겨있었는데 살짝 찬바람 부는 오늘 같은 날에 딱이라고 생각했습니다.', 30, 3, NULL, SYSTIMESTAMP);
