INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '가게 사장님이랑 직원분이 엄청 친절하셨어요 조용히 카페 즐기고 왔어요 당분 충전하기 넘 좋은곳이네요 친구들하고 또 갈께요 초콜릿은 집에오니 또 생각나는 맛이예요~~', 50, 3, 'GOOD', SYSTIMESTAMP);
