INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '말차빙수가 녹으면 물이 되는게 아니라 우유 또는 녹은 초콜릿처럼 돼요 그래서 진짜 너무너무너무너무 맛있었어요ㅜㅜ 같이 주문한 아메리카노는 한번씩 입안을 중화시켜줘서 좋았어요', 23, 0, 'GOOD', SYSTIMESTAMP);
