INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '3년전 우연히 방문했다가 초코빙수가 너무 맛있어서 반했는데 첫사랑은 이루어지지않는다는말이 맞듯 맛이 점점 변합니다. 매년 여름마다 방문했는데 우선 작년초코빙수는 빙질이 안 좋고 맛이 진하지가 않아서 방문을 안하고 올해 다시했으나 3년전 그 맛이 아님 가격도 비싼편인데 초코빙수 양이 적고 다크초코렛빙수도 있었는데 사라지고.... 이렇게 좋아하던 가게들이 바뀌어갑니다. 한번가고 말 가게가 아니었는데..', 11, 2, 'BAD', SYSTIMESTAMP);
