INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '크림브릴레 수플레랑 아아 먹었어요 일단 아아 맛있어요 👍 수플레는 처음 먹어보는데 한입 먹자마자 건강에 안 좋겠다 싶은 맛 🫢 한입 한입이 위험하게 느껴졌어요 양은 많습니다!!!', 25, 1, 'GOOD', SYSTIMESTAMP);
