INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '수플레 먹고싶어서 갔어요. 종류가 2가지에요. 부드럽고 아주 달지 않아서 먹기 편해요~ 수플레 전문접은 아니구 나오는데 30분정도 기다렸어요.', 14, 6, 'GOOD', SYSTIMESTAMP);
