INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '수플레가 진짜 미쳤어요 완전 댑악.. 엄청 부드럽고 퐁실퐁실 맛있구 크림이랑 바닐라뷔릴레로 딱 잘 어우러지게 맛있구 상콤한 귤??? 도 올라가있어서 밸런스가 딱 맞아요 아니 진짜 수플레가 와 진짜로 너무 맛있어요 ㄹㅇ 녹아요 녹는데 부드럽고 막..이건 꼭 먹어뵈야함요 ㅇㅇ 뜨아랑 같이 먹었는데 커피도 맛있어욤', 12, 8, 'GOOD', SYSTIMESTAMP);
