INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '메뉴가 나오는대로 가져다 주시구 다 먹은 후에는 자리에 그대로 놔두고 가면 되더라구요 ! 사장님 굉장히 친절하시구요 ¨̮ 밀크티 꽃향이 많이 나는 건 아니지만 달달하니 제 취향에 잘 맞았어요 ! 수풀레 계란맛이 낭낭하게 느껴지며 퐁신퐁신 좋아요 크림브륄레 치고 카라멜라이징은 부족하지만 수풀레와 크림 자체가 괜찮아서 크림브륄레를 기대하고 먹기보다 수플레 자체를 기대하고 먹는게 좋을 듯 해요 (앗다른 리뷰보니 그때그때 카라멜라이징 정도가 다른 것 같아요 ... !! 제가 먹었을 땐 부족한 편이었습니다 !)💗 앗 인테리어 깔끔하고 분위기 조용하니 좋았어요 !', 36, 4, 'GOOD', SYSTIMESTAMP);
