INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '와 너무..맛잇었오요!! ㅠ 한창 유행할때 못먹고 이제서야 먹게된 수풀레 케이크 ㅠ 크림뷔릴레 형식으로 하셔서 그런지 더 달콤 폭신~ 순식간에 먹게됩니다 ㅠ 주문 밀려있으셔서 30분 기다려야 한다고 하셨는데 수다떨면서 기다리니까 그렇게 기다리는지도 모르겠고 먹으니까 사르르 고소~ 달큰! ㅎㅎ 또 갈거에요 ㅎㅎ', 88, 17, 'GOOD', SYSTIMESTAMP);
