INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '여기 이제 제 인생 수플레원탑 ! 오래기다려서 아껴먹고 싶었는데,, 뭐 순삭,,, 넘 부드러워서 신생아도 먹을 수 있을정도에요><ㅋㅋㅋㅋ', 113, 25, 'GOOD', SYSTIMESTAMP);
