INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '수플레 가격대가 좀 있긴 하지만 너무 맛있어요!!! 직원분도 정말 친절하셨던 것 같아요 ㅎㅎ 수플레 먹으러 담에 또 오려구요!', 102, 20, 'GOOD', SYSTIMESTAMP);
