INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '꿀자몽 비주얼 장난 아니에오!! 우연히 걷다가 외부가 너무 좋아보이고 언뜻 보이는 내부도 좋아보여서 들어왔는데 비주얼 갑인 수플레와 꿀자몽!! 그리고 아인슈페너 까지!! 다들 ego 꼭 오세용', 16, 6, 'GOOD', SYSTIMESTAMP);
