INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '주문하자마자 구워주셔서 따듯하고 부들부들하고 퐁신퐁신해요 ㅠㅠㅠㅠ 진심 수플레 맛집이에요!! 음료도 너무 퀄리티 좋아서 놀랐어요 ㅎㅎ', 27, 5, 'GOOD', SYSTIMESTAMP);
