INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '이건 아니다싶어 한마디씁니다 수플레는 밑바닥이 다 타서나왔네요 탄거 가리려고 뒤집어서 나왔는지는 몰라도 진짜 성의없네요;; 수플레 모양도 엉망이고 안이쁘고 옆에는 다 터지고 퍼지고...;;맛도 겉은 탄맛나고 속은 익지도 않았어요. 16000원이 아까워서 꾸역꾸역 먹었습니다 진짜 최악인 수준. 개선할 필요가 충분하고 장사 넘 쉽게 하시는것같네요. 적어도 타거나 모양이 이상하면 팔지 마시든지 다시 정성들여 만들든지 하세요.', 61, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '웬만하면 이런말 안하는 사람이지만 아닌건 아닌거같아서 리뷰 남깁니다. 우선 앞에 주문이 없었는데도 수플레는 나오는데 30분이 넘게 걸렸습니다. 주문시 앞에 쓰여 있기도 하니까 특별한 문제가 발생한게 아니여도 기본적으로 그 정도 걸리는 듯합니다. 수플레 주문이 몇개만 들어와도 한시간은 걸릴듯 하니..이는 판매 방식이 잘못된것 같습니다. 맛은 수플레의 부드러움이라기 보단 덜익고 기포많은 물반죽의 느낌이었습니다. 평균적인 수플레가격인 16,000원에 비해 양은 많았지만 개선이 필요하다고 생각합니다. 커피는 향도 바디감도 없이 탄맛만 나는 완전히 잘못내린 샷이었어요... 이런 음식과 커피를 먹자니 연예인 홍보관에 온건지 카페에 온건지 모르겠습니다. 카페의 본질을 잊으신거 같아요', 16, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '객수 많은데 마감시간 가까워져서 예민한건 알겠는데 10시반까지만 매장 이용하라고 이제부턴 포장만 된다고 악을 쓰면서 소리를 지르니 주문하기전부터 기분만 상하네요 외국인들이 키오스크 결제 서툴러서 오래걸리면 도와줘서 줄을 빼던가하지 카운터 안에서 화난 표정으로 소리만 지르면 해결이 되나요?', 33, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '다른매장과같은 콘 이아닌 와플로 제공이되면서 가격은 다른매장보다 더 비싸요 와플로 무조건해야되요 원하지 않는데 와플로 무조건먹으면서 가격까지 올리니 가고싶지 않아요 점주입장에서는 남는 장사겠죠? 원래있는직원 틈틈히 돌려 외플만들게 하고 돈은 소비자한테 더 받을수있으니깐요 1시간 인건비에 맥스를 뽑아내면서요', 23, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '덕분에 즐거운 파티했어요 감사합니다:) 사장님 친절하시고 홀 공간에 앉을 좌석도 넉넉해서 좋아요. 주변에 술집이 많아 3차로 아이스크림 해장하기에 딱입니당', 29, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '와 귀 너무 아파요 번호부르는 직원분 목소리와 띵동울리는 배달음과 매장음악의 콜라보가 …😣 그리고 와플때문에 매장에 찌든냄새가 나네요ㅠㅠ 코와 귀를 잃고 왔..', 70, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '콘이 기본싱글에 추가돼서 가격이 비싸졌네요.. 근데 막 그닥 맛있진 않았어여.. 아쉽)) 그래두 호떡아이스크림 맛있게 잘 먹구 갑니당', 26, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아무리 바빠도 인상 팍팍쓰고 무시하며 응대하시니 기분이 안좋았어요 스푼 하나 여분은 구매해야한대서 구매하면 그만인데 귀찮다는듯 진상취급 느껴져서 어디 값싼 아이스크림 사먹어도 이러지는 않을듯해요 베스킨실망...', 18, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), 'ㅈ같은 키오스크 외국인들 엄청 헤메서 10분 이상 걸리는데 카운터에서 주문받던지 좀 간편하게 해주던지. 근데 내가 써보고 알았다. 다음 다음 누르다가 마지막에 다음 누를 자리에 결제 취소가 있어서 홈으로 돌아가는 사태 발생. 왤케 헤맸는지 알겠다. 와플콘이라 해서 종이컵안쓰는 것도 아니고 환경에 도움되는 것도 아닌데 기본 옵션이여서 비싸게 먹어야 하는 것도 이해가 안된다. 언제 만든건지 엄청나게 눅눅하다.', 22, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '키오스크 주문이 어려워서 카운터가서 물어보니 귀찮다는 말투로 키오스크로 주문하라고 하네요. 사람 있는공간에서 너무 뻘쭘 했습니다. 와플굽고있는 덩치조금 있는여자분이네요. 심지어 키오스크에는 카운터에서 주문할수있다고 되어 있던데요... 참으로 안타깝습니다.', 89, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '베스킨라빈스 마카롱 생각보다 더 맛있어요~~^^  위치가 상상마당 앞 신호등 건너면 베스킨라빈스가 있어요. 위치가 좋아서 아이스크림이나 마카롱 먹으면서 시간 보내기 좋아요~~^^', 35, 6, 'GOOD', SYSTIMESTAMP);
