INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '처음보는 타르트라 기대했는데 오❤️❤️ 역쉬 복숭아가 최고입니다👍🏻 밑 부분은 엄청 딱딱해서 먹기가 불편했는데 윗 부분은 맛있었어요!! 다음번엔 멜론맛도 도전해봐야징~', 9, 7, NULL, SYSTIMESTAMP);
