INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '쿼터 4가지맛 시켰는데 메뉴가 완전 다른게 왔네요 번호를 불렀을때 제가 가지고 있던 영수증번호를 불러 번호까지 확인후 받아와서 열었는데 같은맛이 하나도 없엇습니다!! 진짜싫어하는 민트가 들어있었습니다 주실때 메뉴를 확인을 안하신건지 의심이 들정도 였습니다 초코나무숲을 먹고 싶어 가서 사온건데 진짜 황당 그자체였습니다!!!!!(아이스크림 먹은거 아니고 뚜껑에 저만큼이 떨어져 나갔습니다)', 0, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '흑 아빠는 딸바봉 다시 나와서 너무 행복해요.. 없어졌던 2년간 배라 맛 방황했는데 다시 정착할 수 있을 것 같아요 여전히 맛있네요 딸바봉 단종 안됐으면 좋겠어요🥹', 88, 11, 'GOOD', SYSTIMESTAMP);
