INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '여기에 리뷰는 꼭 써야겠다고 생각했어요 정량이 바뀐건지 아니면 바쁘셔서 그런건지 원래 꾹꾹 눌러 담아주시는 베라가 너무 좋았는데 뚜껑이 휙 열릴정도에 아이스크림끼리도 빈공감이 많아 떠서 먹을때 힘들정도였습니다 아무리 바빠도 적은돈도 아니고 돈내고 먹는건데 너무 속상하네요ㅠㅠ', 73, 16, 'BAD', SYSTIMESTAMP);
