INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '홍대 근처 10여개 되는 스벅카페 중 유일한 R매장⭐️. 가장 세련된 분위기. 대로변 출입구를 통해 들어가면 스페셜티 커피 카운터가 있고 그 주변으로 다양한 구성의 테이블들. ▪️ 싱글오리진 원두 커피는 다음에 하기로 하고 오늘은 오랜 만에 카페아메리카노 한 잔. 산미 없이 씁쓸한 맛을 특징으로 하는 ''스타벅스 오리지널''😉... 잘 모를 땐 이게 제일 입맛에 맞다고 생각했는데 이젠 더 매력적인 커피가 많다는 걸 알아버림:-) ▪️ 건물 지하에 주차 가능함🚗. 일정 액수 이상 팔아드리면 무료주차.', 28, 2, 'GOOD', SYSTIMESTAMP);
