INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 근처 스벅 중 한군데 들렀습니다. 크리스마스라 좌석이 거의 풀이더군요~ 다행이 한개 테이블이 딱 비어서 여유있게 시간 보내고 왔습니다!', 75, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '한잔에 10,500원하는커피판매하면서 청결한위생상태 유지했으면합니다 아침에 본사직원 점검?하러오신듯한데  매장한번 대충이라도 안훑어보시드라구요 에쏘내리고 여기저기 지저분하게정리안된채방치 테이블에 음식가루들 기구들에 얼룩자국 한번 헹구어내시도않고 그냥그대로 내리드라구요 그냥 안보고 테이크아웃하는게 나을듯요 보고는 안올듯 스타벅스 매장만늘릴게 아니라 위생관리 파트너관리 서비스관리  품질관리 필요!!!', 39, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '창가자리에 친구들이랑 앉아서 노트북 작업도 하고 사람들 지나가는 것도 보고 창가에 앉으면 시간이 흐르는게 잘 느껴져서 좋아요☺️', 41, 1, 'GOOD', SYSTIMESTAMP);
