INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '얼그레이바닐라티라떼 품절이라 밀크티 마셨는데 맛있네요. 홍대 다른 카페 갔다가 자리가 없어서 왔는데 의자도 편하고 대화하기 좋아요^^', 80, 14, 'GOOD', SYSTIMESTAMP);
