INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '울 막내와 책과의 데이트! 설레이고 작가와의 만남은 가장 행복하고 소중한 시간으로 나에게 힐링이 되게해준 공간… 달달한 디저트도 맘에 들었당^^', 45, 2, 'GOOD', SYSTIMESTAMP);
