INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대역에서 합정 방향에 있는 스타벅스 리저브 매장. 깔끔하면서 고급스러운 인테리어가 맘에 듭니다. 스탭 분들도 친절하시고요. 커피도 웬지 더 맛있는 듯해요.', 55, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '리저브는 처음이라 잘 모르지만 초콜릿도 맛있고 커피가 되게 묵직하네요 저는 맘에 들었습니다 직원분들도 정말 친절하시고 다 좋은데 화장실이.. 스타벅스 내에 있는게 아니고 건물화장실인데 깨끗한 스벅화장실(?) 기대하시면 좀 당황스러우실 수도 있겠네요 주말 점심시간대인데 생각보다 안 혼잡하구요(앉을 수 있을 정도) 와이파이 kt와이파이 말고 kt_starbucks로 꼭 연결하세요!!', 47, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'WIFI');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '평일 오전에 계셨던 직원언니분들이 넘 친절하셔서 하루를 기분좋게 시작할 수 있었습니다:) 회사 바로 옆이라 자주 가는데 대부분 친절하신거같아요~음료도 다른 스타벅스보다 더 맛있습니다! 원래 스타벅스는 공간때문에 가는데 여기는 커피맛으로도 가기 아쉽지않아요👍🏻😊😊', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '일요일 오후4시쯤 방문하였습니다. 매장도 넓고 직원분들도 완전친절하셔서 기분좋게 커피랑 디저트 먹었습니다. 홍대입구역에서 도보로 3분거리라 약속장소로 굉장히 좋은곳으로 생각됩니다.', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대역 주변에 스타벅스가 진짜 많아요 리저브는 2번째 방문이예요 매장이 넓고 특 히 리저브 바가 넓네요 디카페인 기계를 청소중이라 그냥 라일락 블라썸 티로 마셔요 맛이 괜찮음요', 25, 8, NULL, SYSTIMESTAMP);
