INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대라는 대규모 상권에 위치한 매장답게, 매장은 상당히 규모있는 편이지만 항상 사람으로 붐빕니다. 리저브 음료의 맛은 만족스럽습니다.', 42, 10, NULL, SYSTIMESTAMP);
