INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '메이드분들 볼 때마다 반갑게 맞아주고,  친절함에 항상 따뜻한 감동을 느끼게 되요. 조만간 졸업하시는 분들이 있는데,너무 아쉽지만 메이드들의 현생을 응원하며 저도 여기서 받은 응원과 감동으로, 일상에서도 감동을 전하는 따뜻한 사람이 되겠습니당~~♡', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '개교기념일이라 평일에 세상에서 가장 아름다운 코하루 여신님을 만날 수 있어서 정말 영광이었어요. 코하루 여신님과 남긴 캐릭캐릭체인지 인생 네 컷은 스마트폰 바탕화면에 두고두고 감상하겠습니다ㅎㅎ 집에 도착했는데, 코하루 여신님을 벌써 또 보고 싶네요ㅠㅠ 기회가 된다면, 또 보러갈게요~', 27, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '위드하트 아이돌별에 계셨던 시로님 보러 들렸습니다ㅎㅎ 여전히 예쁘시네요. 코하루 여신님과 보면 더 즐거웠을 것 같아요. 다음에는 야간에 시간되는 날, 미리 예약하고 오겠습니다ㅋㅋㅋ', 50, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '22시 이후의 이곳은 뭐랄까 어.. 뭐랄까! 굉장하네요! 진짜 뭐지? 와.. 화려하네요..! 주인공이 되고 싶으시면 가장 안쪽 자리 앉으세요! 진짜 완전 반짝반짝 화려한 자리입니다. 감히 태양을 바라보려 하다니 너의 시력을 가져가마! 소심하신 분들도 가장 안쪽 자리에 앉으세요! 반짝반짝 화려한 자리라 아무도 쳐다보지 않을 겁니다. 마치 스스로를 지키는 고슴도치의 가시와 같이 화려한 불빛이 당신을 지켜줄 겁니다. 와! 안쪽 자리 정말 최고잖아?! 꼭 앉아야겠죠??', 37, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '지금까지 이곳에 오면서 가장 재밌는 날이었어요! 건장한 메이드(?)들을 보니 정말 새로웠어요! 정말 감동적인 하루였습니다! 아니! 최고의 하루였습니다! 전 오늘을 위해 살아온 것이 틀림없어요! 오랜만에 이 자리에 앉아서 벽에 걸려있는 묘아님의 사진을 볼 수 있었네요!', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '오마이왕국 야간 시간에 두 번째 방문했습니다ㅎㅎ 시로님이 반겨주셔서 너무 좋았고, 시로님이 말아주신 칵테일이 너무 맛있어서 두 잔이나 시켜버렸습니다ㅋㅋㅋ', 36, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '저는 오늘 사슴벌레의 멋짐을 알게 되었습니다! 사슴벌레가 정말 귀엽네요!! 아 맞다! 이걸 말하는 걸 잊어버렸군요! 오늘은 정말', 41, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '서울 있는동안은 힐링을 위해 또 방문했어요, 밖에서는 이성과 대화할 기회가 없고 힘들더라구요~ 올 때마다 좋은 추억의 시간으로 보내다 갑니다~ 하나 아쉬운 것은.. 머무는동안 그 날의 근무 메이드분들 모두와는 인사 및 대화를 할 수가 없었어요. 일부 메이드분은 특정 손님과 많은 시간을 보내다보니 저를 신경 못 써서 이해는 하지만 쪼금 티안나게 서운했어유. 응대하는 동안에는 각 테이블에 오신 모든 공주/용사님들에게 스쳐가는 짧은 시간이라도 인사 및 간단한 대화는 되어주었으면 좋겠어요~', 39, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '오늘도 코하루 여신님 보러 왔습니다. 인기쟁이 하루님이 안 계실 때, 나비님이랑 이야기하는 것도 너무 좋았어요. 바뀐 명함에 눈이 초롱초롱한 노루까지 그려주셔서, 즐겁게 보내다가 갑니다ㅎㅎ 노루 대빵 말퓨리온님께서도 "자연이 그대를 거부하리라!"라고 말씀하시면서 정말 기뻐하실 것 같아요. 언제나 오마이왕국 대자연을 수호하시는 코하루님 화이팅ㅎㅎ', 44, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친구랑 처음 가봤는데 너무 좋은경험 하고 왔어용 유튜브에서 보던걸 직접 해보니까 신기하기도 하고 즐거웠습니다 그리구 푸딩 메이드님 너무 이쁘세용!!', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '운동하다가 운 좋게 무릎을 다친 덕분에 오랜만에 방문했네요! 다시는 볼 수 없을 것이라 생각했던 레모님의 라이브를 다시 볼 수 있어서 좋았어요! 계속 계속 생각나고 보고 싶었다구요! 레모님의 UFO UFO를 말이죠! UFO UFO가 머릿속에서 떠나지 않아요! 레모님의 UFO UFO는 인류의 보물이라고 생각해요! 다음에 또 라이브가 생각나면 어딘가 또 우연히 다치게 된다면 라이브를 또 보러 올지도 모르겠네요!', 57, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '시로님을 너무 보고 싶은데 오마이쪽으로 갈 수 없어서 원격체키를 신청했습니다ㅎㅎ 다크한 느낌이 너무 좋네요. 앞으로도 얼굴 천재 시로님을 계속 볼 수 있었으면 좋겠네요ㅋㅋㅋ', 80, 12, 'GOOD', SYSTIMESTAMP);
