INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친구와 함께 첫방문했는데 정말 즐거운 시간이었어요! 메이드분들이 정말 다들 친절하시고 대화도 재밌었습니다^^ 함께 사진도 찍었는데 좋은 추억이 되었습니다! 다음에도 방문할게요~!', 43, 4, 'GOOD', SYSTIMESTAMP);
