INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '콜키지로 삼겹살 먹었는데, 메이드분들과 조금 더 친해질 수 있는 계기가 된것 같아 좋았습니다. 다음엔 의견반영하여 더 맛난 음식으로 대접하게씀다~', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대의 밤은 위험해요! 만약 막차를 놓쳤다면 왕국에서 안전하게 있다가 떠나시는 것을 추천드립니다! 저는 분명 강해졌다 생각했지만 바깥 세상이 조금 더 강했을 뿐이네요.', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '혼자가도 외롭지않아요ヽ(*´▽)ノ♪ 재밌게 놀아주고 말걸어 주고 귀여운 그림도 그려주고 재미있는 카페에요😆 오므라이스도 맛있고 그림도 귀엽게 그려줍니다👍🏻 오므라이스 배고프면 꼭 먹어보라한 이유를 알겠어요🤭 맛있어지는 마법의 주문이 함께하니 더 맛있어진 기분🍛 큐트하고 친절한 메이드분들이랑 게임도 할 수 있고, 사진도 찍을 수 있었어요🫣 다음에는 지인들과 함께 방문하고싶어요 츄츄🩷', 35, 1, 'GOOD', SYSTIMESTAMP);
