INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '평일에는 시간 추가가 시간당 5천원씩이라서 타 매장들보다 저렴한 것 같아서 좋아요~^^ 음료도 맛있고 다들 친절하셔서 자주 들립니다. 커플들이나 친구들끼리 방문하기도 하는데 혼자와도 괜찮은 것 같습니다. 입구가 좀 부담스럽긴한데 그거만 이겨내서 입장한다면 즐거운 체험 가능하실 것이라고 생각합니다. 강력 추천^^!!!!', 80, 12, 'GOOD', SYSTIMESTAMP);
