INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여러 메이드들이 쉬지 않고 방치되지 않게 케어해주셔서 정말 잘 놀고 갑니다.특히 부점장 히나님,뱀파이어 메이드 리츠링 잘 놀아주셔요', 22, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '메이드분들이 넘 이뿌시고 귀여우시고 넘 좋으세용ㅎㅎㅎ 진짜 친구 처럼 수다도 떨어주시고 제가 쿠로미 좋아한다니까 오므라이스 아트로 쿠로미를 그려주시는 센스!!!굿👍🧡 자주 이용할 예정입니당🧡🧡', 59, 17, 'GOOD', SYSTIMESTAMP);
