INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '친구랑 너무 궁금해서 가봤어요ㅋㅋ 메이드님들 너무 귀엽고 열심히 친절히 해주셔서 황송했어요 ㅠㅠ 내가 이런걸 받을 자격이 있나..?...ㅋㅋㅠ좀 재밌었던건 친구랑 저랑 민망해하는 포인트가 달랐네요ㅋㅋ 전 주문할때가 제일 힘들었는데 친구는 용사역할 고를때 힘들었다고...ㅋㅋㅋ여튼 민망함을 무릅쓸 각오는 필요하지만.. 호기심해결+심심풀이로 가보기 좋은것같습니다', 75, 14, 'GOOD', SYSTIMESTAMP);
