INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '주변에서 재밌다는 말듣고 메이드카페 처음 왔는데 인원에 비해 메이드 수가 부족했고 다들 계속 움직이고 계셨던걸  알고 설명도 들었지만 1시간동안 혼자 멍만때리다 왔어요 . 소개는 몇명들었고 직원들은 친절하셨어요', 42, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '진짜 메이드 카페에서 이렇게 기분 나쁜적은 처음이에요 8시 반 입장이라고  8시 10분부터 40분 될때까지 기다리게 해놓고 나갈때에는 9시 20분부터 빨리 나가라고 하면 이용 하는 입장에서는 이게 뭐지?? 싶으면서 입장권을 왜 받는건가 싶네요', 121, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '오마이 왕국 메이드카페 너무 좋았어요.다들 잘 말해주시고  특히 리츠님 볼수 있어서 좋았어요.담에 또가면  체키꼭 찍을 거에요  감사했어요 .너무 행복했어요.👍👍', 117, 26, 'GOOD', SYSTIMESTAMP);
