INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '메이드분들 너무 친절하셨구 특히 미캉 메이드님!! 너무 즐거웠어욥 ㅎㅎ 폴라로이드도 너무 잘 꾸며주셨구 마루 그려주신거 너무 귀여워욥 ㅎ.ㅎ 다음에 올 수 있다면 또 오겠습니당 냥냥😺', 13, 3, 'GOOD', SYSTIMESTAMP);
