INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대에서 가장 공들여서 오픈하고 영업을 이어 나가고 있는 메이드 카페라고 생각합니다. 추신: 유메님 고생 많았어요 잘 지내세요...!🥲', 125, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '고양이 그려 달라고 했는데 진짜 너무 귀엽게 잘 그려 주셔서  좋았어요😍😍 메이드 공주님들 너무😍😍 친절 하고 매니저 분들도 너무 친절해서 자주 이용을 많이 하는데 갈때마다 너무 재미있고 좋아요 또 가고 싶네요 😭😭😭  보고싶다 공주님들 매니저분들 😭😭', 46, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '친구들끼리 처음가본 메이드카페였는데 재밌는 경험하고 갑니다! 친구들의 질문에 대답도 잘해주시고 악어게임도 하고 사탕도 받고 다들 너무 친절했습니다 특히 모카,크림 메이드님 감사합니다!', 17, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '너무너무 다들 친절 하시고 꿈만 같은 일이 일어나는 곳 정말 갈때마다 너무 좋고 신나요❤️❤️ 너무너무 좋은 추억 만들어 주셔서 고마워요오❤️❤️', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '2024년 3월 7일 메이드카페 첫 방문! 오목을 잘하시는 그분한테 처참하게 패배했었죠! 그리고 시간이 흘러.. 정말 많은 시간이 흘러.. 2024년 6월 23일 저는 제 목표였던 그분을 드디어 쓰러뜨렸습니다! 저 지금 너무 기뻐서 눈물이 흐를 것만 같아요!! 저는 이 순간을 위해 살아온 것이 분명해요! 우와아아아아ㅏ아아아아아아아ㅏ아아ㅏㅏ 이겼다ㅏ아아아아ㅏ아아아아!!!!!!!', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대점에서 친구랑 같이 갔습니다 포션 정말 이쁘게 잘 나오구 메이드분들이 밝고 텐션이 높으셔서 각자 개성있으셔요 친구와 휴일에 놀러가니 재미있어요', 20, 1, 'GOOD', SYSTIMESTAMP);
