INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '다들 너무 친절하시고 음식도 기대 이상으로 맛잇어요! 처음에는 컨셉때문에 많이 고민되고 그랬는데 다들 넘 귀여우시고 얘기도 잘해주시고 해서 즐겁게 있다 갑니다 특히 고죠사토루 그려주신 유키님 넘 감사합니다❤️❤️❤️', 80, 17, 'GOOD', SYSTIMESTAMP);
