INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '너무 귀여운 루나큥~~ 오늘도 루나큥 보러왔어요 ㅎㅎ 앞으로도 루나큥 보러 자주 와야겠어요 정말 친절하고 귀여운 딸기왕국 메이드 루나님 언제나 루나님과 이야기 하고 체키 찍는게 즐거워요', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '성격이 조용한데 여기서 엄청 환영을 받아서 너무너무 좋았어요 시설도 너무 깔끔하고 직원분들도 엄청 친절하시고 스트레스가 확 날라가는 느낌이에요!! 다음에 여기는 또 방문할것 같아요', 41, 2, 'GOOD', SYSTIMESTAMP);
