INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '제가 도착한 시간에 우연히 라이브 공연이 시작되었습니다. 정말 화려하더라구요! 디저트와 유자차는 언제나 맛있습니다! 오늘의 오목은 아슬아슬하게 이겼습니다!! 정말 마지막에 마지막까지 가서 한 끗 차이로 이겼어요! 역시 이곳엔 오목 고수들이 많습니다. 다음에 다시 도전하면 분명 저는 패배하겠죠! 한번 방문에 여러번 도전해도 되는지는 모르겠지만 저는 하루에 한 번만 도전하고 있습니다!', 47, 0, 'GOOD', SYSTIMESTAMP);
