INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '카레가 정말 맛있었습니다. 최강의 요정 유미님한테 당당하게 오목을 신청했다가 2연패를 당하고 세상은 넓고 오목 고수는 많구나 라는 생각이 들었고 저는 오목왕의 꿈을 접었습니다. 이제 난 젠가만 할거야!', 50, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '메이드분들 너무 예쁘시고 친절하게 말 걸어주셧어요!! 바쿠고 생카 특전 올려둿더니 히로아카 좋아하냐고 물어봐주셔서 행복하게 대화도 햇어요 쪼금 비싸긴하지만 그럴 값어치가 잇는 거 같고 한 번씩 올만한 거 같아요!!!!❤️❤️❤️⭐️✨⭐️⭐️⭐️✨✨', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '메이드분들 너무 친절하고 귀엽고 컨셉이 확실해서 너무 좋았어요❤️ 용사님들이 오는 컨셉이 너무 좋았습니다 😆❤️ 메이드복 체험도 하고 공연도 보고 너무 좋았습니다', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '너무너무 즐거운 경험과 앞으로도 오 마이 메이드 카페 자주 이용 할 것 같아요😊😊 직원분들과 메이드분들도 다들 친절 하고 혼자 가도 부끄럼 없이 재미있게 즐기고 올 수 있습니다 😊😊 또 가고 싶어요 ㅜㅜ 너무너무 감사합니다 ❤️❤️', 61, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '다들 너무 귀엽구 제가 좀 낯을 가리는데 말도 잘 걸어주시고 너무 좋았어요!! 다음엔 더 재밌게 시간 보내고 싶어여 에리웅니가 특히 너무 잘해주셨어서 좋앗어요 💖', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '혼자 서울 올라와서 할거 없었는데 전부터 가보고 싶었던 메이드카페 예약을 해서 한번 가봤는데 가자마자 귀엽고 이쁜 메이드들과 신입 메이드 네코땅이 반겨줘서 디게 머쓱했지만 상당히 반가운 느낌이였음 컨셉도 뭔가 독특하고 상당히 재밌고 재밌고 메이드 들도 디게 활발하고 걍 음식 퀄 라이브 이런게 걍 말할 필요가 없음 걍 진짜 최고였음 신입 메이드 네코땅이랑 사진도 찍고 라이브도 1인 직관 했는데 진짜 잘춰서 디게 놀랐음 만약 본인이 여기 갈까 말까 고민중이라면 진짜 가는걸 추천!! 가도 후회는 없음', 41, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '메이드카페 처음와봤는데 음식이 넘 맛있어요!!!!! 카페는 아기자기 공주풍테마에 메이드분들 완전 귀여우세요🩷🩷 일부러 한산할 거 같은 날 골라서 월요일에 왔는데 생각보다 손님도 많으시더라구요 오늘 새로오신 메이드분이랑 체키 찍었는데 특별한 기억으로 남을 것 같아요😊😊 재밌게 놀다가용💓', 0, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '오늘은 오므라이스와 팬케이크 둘 다 먹어봤습니다. 굉장히 배가 불렀지만 후회는 없습니다. 둘 다 맛있었거든요! 특히 팬케이크 옆에있는 아이스크림 정말 맛있어요 그리고 저는 승리했습니다. 이곳의 오목 고수를 저는 쓰러뜨렸습니다..! 다음엔 백돌로 이겨보겠습니다!', 43, 10, 'GOOD', SYSTIMESTAMP);
