INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '태어나서 처음으로 방문한 메이드카페! 맨날 유튜브로만 접했었는데 이렇게 한번 와보네요! 여자 둘이 방문했고 금요일 저녁 8시 예약하고 갔는데 사람들이 많이 대기하고 있더라구요. 저희는 예약해서 바로 입장했습니다! 그래서 만약 방문할 계획이라면 꼭 예약을 하시는것을 추천드려요! 입장하면 귀여운 메이드 언니들이 반겨주시고 음료추천도 잘 해주십니당 ㅎㅎ 핫케이크를 주문했는데 금손 메이드님이 넘 귀엽게 그려주셨어요 ❤️ 다양한 체험이랑 놀거리가 있습니당! 포토존에서 사진도 찍고 머리띠랑 악세사리 대여도 하고 셀카 찍고 라이브 공연도 했습니다! 즐거운 시간 👍이색 체험을 하시고 싶으신분들 방문하시는거 추천드려요!', 14, 5, 'GOOD', SYSTIMESTAMP);
