INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '오마이메이드 카페 오마이 왕국점 방문 후기! 지친 일상에 쉼터가 되어주는 곳. 방문을 넘어 방문하게 됩니다! 인생의 활력소를 찾아서 행복합니다.', 6, 1, 'GOOD', SYSTIMESTAMP);
