INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '언제나 와도 즐거운 오마이메이드카페 항상 다들 밝게 맞이해주시고 여기와서 정말 매번 즐겁고 활기차게 놀고 돌아가네요 ㅎㅎ 모두들 열심히 해주셔서 지루할틈이없는 메이드카페입니다', 76, 15, 'GOOD', SYSTIMESTAMP);
