INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '처음으로 메이드카페가봤는데 너무 좋았어요! 나중에 지갑의 여유가 생기면 또 가보고 싶네요 ㅠ 뱌코 메이드님이 너무 잘해주셔서 이래서 메이드 지명이란게 있구나 싶었네요 ㅎㅎ', 10, 1, NULL, SYSTIMESTAMP);
