INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '항마력을 갖추지 못한 자 너흰 아직 준비가 안 됐다. 하지만 나아갈지어다 자상한 메이드쨩의 조력으로 담금질된 심장은 어떠한 고난도 이겨낼지니.', 45, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '메이드님들도 너무 친절하시고 말도 너무 친절하게 해주셔서 너무 좋은 시간이였어요!!🩷 메이드님들도 다 이쁘시고 착하시고 기분 좋게 말씀해주세요☺️ 진짜 즐거운 시간이였습니다!! 🩷🩷', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '너무 재밌고 ㅠㅠ 너무 이쁘고 ㅠㅠ 다들 완벽하시고 ㅠㅠ 계속 자리 와주셔서 심심할 틈이 없고 진짜 존잼 꿀잼 개존잼 ㅠ 진짜 미침 다음에도 또 올꺼에요 ㅠ 하 개존잼 미쳣어 진짜', 173, 38, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '소문으로만듣던항상 메이드스타가는길에보여한번쯤은 가야갰다생각했다 결국정들었던메이드의졸업으로 반항심?으로 다른메이드카페를가게돠었다 오마이도그중하나 유튜브와방송의소개로 첫방문이지만상당히친숙했다 넓은매장과잘꾸며진인테리어 그리고평일이지만 많은메이드들(모에뀽정도는비빌듯?) 주문은1인풀세트 세트구성은다른곳과동일 빠르게모든음식이나오고 빠르게그리고,주문하고 딱여기까지가2시30분 이제먹어야하는데 자기소개만5분이온다ㅋ 와주면좋지만시간은가고 남은체키랑라이브도있어서 많은메이드카페를갔던나도 빠듯한데진짜처음인분들은힘들거다 그사이체키랑라이브는마무리 아직다못먹었다그때 5분남았으니가라고하네 난2시넘어서방문인데 이걸정각으로끊어서체크를하니 다음에오고싶은오고아님말라는건가? 영수증리뷰하면1시간공짜 명성에비해좀실망했다 재방문은힘들듯?', 89, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '친구가 같이 오자고 할 때는 가서 시간이 별로 안갈거 같아 걱정이 많이 되었는데, 실제로 와보니 시간이 굉장히 빨리가고 음료도 색감이 예뻐 마시는데도 즐거웠던것 같습니다. 만일 다시온다면 다른 친구들도 끌고오면 더 재밌을 것 같다는 생각입니다. ^^', 323, 47, 'GOOD', SYSTIMESTAMP);
