INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '메이드카페가 너무 가고 싶었는데 마침 괜찮은 곳을 찾아서 와봤어요! 메이드분들이 친절하고 음식이랑 음료가 너무 맛있어요... 첫 메이드카페인데 너무 행복해서 죽을거 같아요...😢 또 오고 싶은 메이드카페... 단골이 될거 같아요~~😳', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '한 번 오게 되면 또 오게되더라구요ㅜㅜ 여기 언니들 너무 이쁘고 다들 착해요 !! 음식도 맛있고 가격도 나쁘지 않아요ㅜㅜ 다들 와보세용!! 💗', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '너무 재미있어요 ~~ 공주님이라고 해주셔서 너무 좋아요 ㅎㅎ ㅋㅋ 다음에 또 오고싶어요 ~~~ 리츠링이랑 하치님 너무 친절하시고 좋아요 ~~ 최고예요 이런 경험 또 해보고싶어요~', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '다 괜찮았지만 1시간으로 여유있게 이용하긴 좀 짧은 느낌 2시간있게 여유있을때 가시면 좋고 뭐 어떤 메뉴를 시켜도 좋지만 라이브 하프타임이라도 꼭 주문하시길', 36, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '진짜진짜 너무 힐링 그 자체였어요 놀거리도 엄청 많았고 특히 개인적으로 미니게임 벌칙이 되게 재밌었어용!!!! 꼭 주말마다 갈곳 이미 확정~ 신속포션 먹으러 출동!!!', 118, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '처음에는 기대안하고왔었는데 음료나 음식들도 맛있고 재밌어요! 흥미가 생겼다면 옆 왕국도 들려보시는걸 추천해요 이렇게 텐션이 높고 기분이 엄청 좋았던적이 많지않았는데 덕분에 더 힘을 얻어갈수있는것같아요 감사합니다 더 살아야겠어요~~', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '친구랑 왔는데 메이드분들 다 너무 친절하시고 예쁘세요! 각자 직업을 고르고 입장한다는게 신박했구 음식들도 맛있었어요! 사진도 함께 찍었는데 폴라로이드인데도 뽀샤시하게 잘 나오고 함께 찍은 메이드분이 예쁘고 귀엽게 꾸며주셨어요!! 병아리왕국의 아리 메이드님 ㄹㅇ금손입니다!! 다른 분이 라이브쇼 주문해주셔서 라이브쇼도 봤는데 춤도 엄청 잘 추세요!!', 16, 5, 'GOOD', SYSTIMESTAMP);
