INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '삶의 첫 메이드카페에 ''메이지''로써 전직해서 다녀왔습니다. 다들 너무 친절하시고, 재밌으시고 적극적으로 맞이해주셔서 너무 재밌었습니다. 라이브도 진짜 최고였습니다. 숭배할 수 밖에 없는 곳이였습니다. 킹아~!', 2, 5, 'GOOD', SYSTIMESTAMP);
