INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '진짜 재미있었어요 (((o(*ﾟ▽ﾟ*)o))) 메이드분들이 진절하고 진짜이쁘고 귀여우세요>< 오자마자 심쿵-♡!!!합니다 전에 친구랑도 한번왔었는데 그때랑 지금이랑 많이다라졌는데도 기억해주셔서 놀랐어요!!(거의 한달전..)진짜 이런거 거부감없다? 그럼 꼭 오세요 행복해용..♡⁺◟(●˙▾˙●)◞⁺♡ 말 못하고 혼자있으면 말걸어주시고 대화주도해주시고..넘 고맙고 감사했어용... (엄비티아이 i라서 부끄러워서 쭈볗거렸음) 진짜 홍대 와볼일있으면 한번꼭 오세요! 오실땐 예약하고 오는걸 추천해요! (예약 안하고 오면 사람많아서 현장예약 어려움..ㅠㅠ) 그리고 오면 라이브는 꼭보세요 진짜 천국구경이따로없습니다...♡ 오타쿠소녀는 오늘하루 매우행복해습니다..♡ 다음에 또갈거에요-!(╭￣3￣)╭♡', 10, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '이런 곳(?) 처음 왔는데 직원분이 편하게 해주셔서 재밌게 즐기다 갑니다~ 음식도 괜찮고 그림이 미친놈 입니다. 꼭 그림 그려달라고 하세요', 90, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '처음 호기심으로 와봤는데... 너무너무 친절하고 예쁘고 귀엽고 생각보다 맛도 있어요... 가끔씩 주시는 관심이 부끄럽지만 좋아요... 저는 다음에 또 올거같아요!!!! 사람들이 왜 빠지는지 알겠어용', 11, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '친구랑 같이 방문 해보았어요! 처음에는 항마력이 딸려서 어떡하지 생각했는데 메이드분들께서 너무 친절히 잘 적응 할수 있도록 친절히 응대해주셔서 너무 즐거운 시간이였습니다! 다음에 또 방문 하겠습니다 ! 냥냥 !', 88, 12, 'GOOD', SYSTIMESTAMP);
