INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '다른 메이드카페보다 컨셉에 집중해주셔서 좋았어요 특히 후리후리 샤카샤카 너무 만족스러웠습니다! 특제음료? 꼭 도전해보세요 그리고 메이드복도 입어볼 수 있어서 좋았어요 남여 상관없이 입고 노는데 옆테이블 구경하는 재미도 있었네요ㅋㅋㅋ', 8, 5, 'GOOD', SYSTIMESTAMP);
