INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '초보 용사로 전직(?)한 뒤 마음의 고향인 모에 왕국을 떠나 오마이 왕국으로 첫 귀환 아닌 귀환을 했읍니다... 성문이 닫히기 전에 들리는 거라서 메이드 분들이 많이 바쁘셨는데 진짜 친절하게 대해주시고 힐링시켜주셔서 고마워요!! 그리고 라이브도 업그레이드 되어서 눈호강도 했어유ㅜㅜㅠ... 담번에두 예약하고 또 방문하겠습니다!!!💕💕💕', 31, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '그동안 엄청 가고 싶었던 메이드카페인데 진짜 다들 너무 이쁘세요.. 친절하시고! 근데 진짜로 냥냥을 해야지 오시더라구용.. 살짝 부끄러웠지만 그래도 너무 재밌었어요! 메이드 언니랑 사진도 찍고 다들 이쁘다고 해주셔서 기분 좋게 즐기다 왔습니당,,,🫣🤍 메이드카페에 빠져서 자주 갈 거 같아요..', 75, 16, 'GOOD', SYSTIMESTAMP);
