INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '나이가 드니 이런 곳에 오기가 힘든데 아리따운 아가씨들이 만아 조앗읍니다 기분 전환하기 아주 조은곳입니다 많은 사람들이 오셧으면 조겟읍니다•••', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '현장 입장도 바로 가능하고 메이드들도 테이블로 자주 들려둬서 좋았어요 너무 귀여워요... 그림 주문하면 뭐든 상상한 이상으로 귀엽게 그려주십니다ㅠ.ㅠ 가격도 괜찮아요!', 42, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '친절하셔서 너무 기분 좋게 있다가 간 카페예요! 노래도 좋았고 직원분들 모두 예쁘고 상냥하세요. 다음에 또 오고 싶을 정도로 좋았습니다.', 78, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '메이드카페는 처음 와보는데 생각보다 정말 친절하셔서 좋았습니다. 특히 레미라는 메이드분이 라이브 공연도 엄청 잘해주셨고  불편한 기색 하나 없이 정말 즐겁게 응대해주셔서 재방문 의사가 돋아나는 경험이었습니다. 오타쿠라면 정말 행복한 경험을 할 수 있는 장소라 생각하고, 오타쿠가 아니더라도 즐거운 체험을 하며 추억을 쌓을 수 있는 곳이라 생각합니다.', 108, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '메이드 카페 처음 가봤는데 메이드분들이 친절하시고 색다른 경험이었어요 °ε♡з° 혼자있는 저를 위해 본인들의 분신 (인형)들을 주셨는데 너무 귀엽고 감사했어요 ෆ⸒⸒ 아 그리고 하치님이 귀여워요 ˚✧₊⁎', 12, 1, NULL, SYSTIMESTAMP);
