INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '너무 재밌어요ㅎㅎ 다들 꼭 오는걸 추천합니다ㅎㄹ 다양한 컨텐트와 친절하신 메이드분들 덕에 재밌게  놀고갑니다ㅎㅎ 또 놀러 올께요~', 21, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '친구들과 한번 와봤어요^ㅅ^ 처음이지만 잘 알려주시고 컨텐츠가 너무 재미있었어요 홍대놀러올때 한번쯤은 방문해도 좋을것같은! 메이드분들도 다 아름답고 친절해서 최고😍', 22, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '너무나 유익한 시간이었읍니다. 메뉴도 맛있었읍니다. 추천합니다. 홍대 최고의 카페. 나 97년생인디 내 동년배들 다 메이드카페 온다.', 59, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '음식이 맛있고 메이드 분들이 너무 친절하고 재밌으세요 !! 모에모에큥 또 오고 싶어요!! 옷도 입고 같이 사진찍고 기념품으로 남길수도 있어요. 시간 나실때 오세요.', 20, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '오므라이스 진짜 맛있어요 내가 살면서 먹은 오므라이스 중 제일 맛있어요 메이분들이 진짜 친절하시고 너무 이쁘세요!!!!!!!😍😍😍😍😍😍', 35, 0, 'GOOD', SYSTIMESTAMP);
