INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '저렴하고 양 많아서 종종 들르는 메가커피! 홍대점은 처음인데 주말에 날씨도 더워서 그런지 사람이 많았어요. 그래도 음료는 빠르게 나왔답니다.', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '신메뉴로 크레페가 나왔다고 해서 궁금해서 방문했습니다 다. 키오스크에서 주문 후 더위를 피하기 위해 안으로 들어와서 기다리려고 하는데 데 들어오자마자 직원분께서 " 아 크레페 들어 왔어" 라고 한숨을 쉬셨고, 또 다른 직원 분께서 " 아 안돼" 이러셨습니다. 키오스크에서 주문한 사람은 저희밖에 없었고 분명 저희가 주문했다는 것을 알았을텐데 그렇게 말씀하신거면 들으라고 하신 건가요? 굉장히 불친절 하시네요..? 그렇게 손님한테 대놓고 불평하실거면 메뉴를 빼세요.', 28, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '오늘은 햇살이 뜨거워서 아아 땡기네요~~ 한글날이라 대기 손님도 많지만  빠르게 주문 음료 나와서 좋아요 커피맛도 션하고 진해서 좋아요', 40, 5, 'GOOD', SYSTIMESTAMP);
