INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '갈때마다 뭔 아메를 10~20분씩 기다리게됨; 사람개많은데 직원은 두명뿐. 사장님 인간적으로 직원좀 더뽑으세요.. 다른리뷰도 다 오래걸린다소리하잖아요.. 그리고 오래걸리는건 그렇다쳐도 왜 똑같은 메가리카노시켰는데 뒷사람메가리카노가 더 빨리나오나요? 그분만 급한가요? 결국 커피 못받고 출근했다가 커피받으러 다시나왔답니다.. 개선좀해주세요 메가좋아해서 자주오는데 올때마다 이러니..', 48, 5, 'BAD', SYSTIMESTAMP);
