INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '와우. .홍대는기본10분이상기다려요. . 프렌차이즈카페중 수박쥬스가젤맛이없어요 ㅠ. .. 수박시럽을쓰는데 시럽서 밤맛이 느껴지는기분..인공적인맛인강?수박쥬스안싼데. .', 216, 68, 'BAD', SYSTIMESTAMP);
