INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '매장 쥐콩만 해요 결제하는 안쪽이 너무 불편해요 키오스크 주문 하는데 새로운 고객 주문하러 들어오는데 뭐 주문하다가 화면에서 비켜서 줘야함', 6, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '일하시는 분들이 진짜 많이 계세요. 주문이 밀려들 때는 좀 기다려야 합니다. 나중에 알았죠. 어플로 사전 주문이 가능하다는 것을... 요즘은 시간대 보고  어플로 주문하네요.', 17, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '싸서 갑니다. 친절도 하고요... 근데 커피맛은...음..... 싼거에 만족하고 있습니다. 다른음료는 안먹어봐서 모르겠네용...', 80, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '3500원으로 즐긴 메가커피의 딸기라떼 양도 혜자롭고 맛도 좋아서 순삭했어요!!! 생딸기도 듬뿍 넣어줘서 씹히는 맛도 있어서 좋았어요~~ 앞으로도 자주 애용할것 같아요♥️', 12, 1, 'GOOD', SYSTIMESTAMP);
