INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '베이글이 이렇게 맛있다니 ㅋㅋ 진짜 너무 맛있었어요 ㅠㅠ 다음에 종류별로 사서 먹고싶어용!!! 베이글 담백하면서 쫀득부드러운데 진짜 존맛탱구리구리~ 스프링어니언크림도 진짜 맛있어용 ㅠㅠ 사람도 짱많구 분위기도 외쿡 🗽 느낌 st ㅋㅋㅋ 매번 홍대 지나다니면서 보다가 이제왓는데 진작 와볼껄그랫어용 ㅠㅠ ㅋㅋㅋ', 60, 17, 'GOOD', SYSTIMESTAMP);
