INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '와 홍대 자주오는데 이런 멋진 인테리어랑 분위기의 베이글맛집이 있는지 전혀 몰랐네요 ㅠㅠㅠㅠ 역 가까이 있었는데 왜째서;;;.. 사진찍기도 좋고 베이글 종류도 다양하고 커피도 맛있어요 ㅜㅜ 나중에 배 덜 찼을 때 와서 여러 종류 맛보고 싶네용 좋은 곳 발견해서 해피해피❤️❤️❤️👍 친구랑 와도 사진 찍을 것이나 거울이 많아서 좋겠어용', 44, 5, 'GOOD', SYSTIMESTAMP);
