INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '맛집 목록에 저장해뒀던 베이글랜드를 이제야 와보네용☺️ 저장한 게 아깝지 않게 연어 샌드위치 너무 맛있어요...🩷 아침을 안 먹어서 샌드위치 종류를 먹었지만 다음엔 꼬옥 온리 베이글을 먹어보겠습니다👍', 1, 4, 'GOOD', SYSTIMESTAMP);
