INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대를 그렇게 많이왔는데도 여기는 첫 방문이에요ㅠㅜㅜ 인스타에서 엄청 핫하길래 방문햇는데 진짜 맛도리 베이글 천지에요!!! 매장도 꽤 넓고 쾌적해서 너무 좋구 매장 자체가 조용하고 좋은 것 같아요 담에는 남자친구랑 올듯용❤️❤️', 75, 14, 'GOOD', SYSTIMESTAMP);
