INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '베이글 종류도 많고 진짜 너무 맛있어요!!! 베이글 샌드위치 만들어서 주문도 가능하고 베이글 다 맛있어요~ 외국 온 느낌이라 더 좋아요', 21, 10, 'GOOD', SYSTIMESTAMP);
