INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대 베이글랜드  다녀왔어요 시그니처 두바이 베이글 맛있어요😄 쫄깃한 식감이 정말 좋았고,  커피랑 함께 먹으니 든든한 브런치로 딱이었어요. 홍대에서 색다른 베이글 찾으신다면 추천합니다👍👍👍', 46, 10, 'GOOD', SYSTIMESTAMP);
