INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '베이글 쫀쫀해서 넘 맛있어요ㅠ🥰 여기는 특별하게 직접 데워먹을 수 있어서 좋아요 두바이는 넘 먹고싶었지만 솔드아웃,,🥹 베이글, 크림치즈 종류가 다양해서 뭐 먹을지 완전 고민되네요ㅎㅎ 특히 크림브륄레 베이글 진짜 존맛‼️ 담에 두바이 꼭 먹겠어요,,,,😙💓', 74, 15, 'GOOD', SYSTIMESTAMP);
