INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '유명하다고 해서 와봤는데 진짜 역시 최고입니다 직원분들도 너무 친절하고 맛있어요 유명한 이유가 있는집 최고입니다 힐링하고 가요!', 29, 3, 'GOOD', SYSTIMESTAMP);
