INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '빵이 너무 맛있어요. 고구마, 페페로니 추천이요. 호불호가 갈릴수도 있지만 바질도 짱 좋았습니당. 다음에는 두바이초콜릿과 솔트 프렛즐 도전할것니다!! 매장 청결하고 사진 찍기도 좋아요. 인테리어도 너무 제 스타일이에요. 데이트 하기도 짱~~🥯☕️🍵 그리고 직원분이 너무너무 친절 그 자체!! 아니 제가 글쎄 비닐봉투가 아까워서 그냥 빵봉지채 가지고 가려고 자리에서 일어나는 순간 요정처럼 나타나셔서 비닐봉투를 챙겨주셔서 너무너무 강동이였어요. 그리고 비닐봉투까지 챙겨주시는 센스까지 너무 배우고 싶습니당.', 29, 8, 'GOOD', SYSTIMESTAMP);
