INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대에서 뉴욕 감성을 느낄 수 있는 베이글 전문 카페예요. 쪽파 베이글샌드는 쫄깃한 식감에 크림치즈와 쪽파 풍미가 어우러져 든든한 한 끼로 딱이에요. 아이스 아메리카노는 산미 적고 고소해서 베이글과 찰떡궁합이었어요. 매장은 넓고 깔끔해요. 혼카페나 데이트 장소로도 좋을 것 같아요. 다음엔 다른 베이글도 도전해보고 싶은 곳이에요!', 8, 7, 'GOOD', SYSTIMESTAMP);
