INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '블루베리베이글은 케익같아요 빵 쫀득~ 크림도 맛있고요 블루베리 양도 많아서 맛있었어요 인테리어도 이쁘네요 단지 주차는 공용주차장에ㅜ', 91, 24, NULL, SYSTIMESTAMP);
