INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대에 이런. 베이글 맛집이 있었네요. 오늘 베이글에 커피가 땡겨서 검색해서 왔는데 분위기도 좋고 음악도 좋은 곳이었습니다. 무엇보다 맛난 베이글 메뉴가 다양하고 뉴욕 풍의 분위기가 정말 좋았습니다. 베이글, 커피 혹은 간단한 디저트 원하시는분에게 강추!!', 112, 22, 'GOOD', SYSTIMESTAMP);
