INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '베이글이 너무 맛있어서 재방문했어요 샌드위치 속재료도 신선하고 풍부해서 진짜 맛있게 먹었습니다 아메리카노도 고소하니 산미를 싫어하는 저에겐 딱 좋았습니다 베이글이 생각나면 또 방문하고싶어요!', 27, 8, 'GOOD', SYSTIMESTAMP);
