INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '베이글이 튼튼하고 아주 맛있어요. 먹었을때 포만감도 있어서 오랜시간 든든해요. 야채도 많이 들어있고 파슬리가 많이 뿌려져있어요. 자유의 여신상도 있어서 미국분위기가 물씬나요. 조용하고 혼밥하기도 괜찮아요.', 38, 7, 'GOOD', SYSTIMESTAMP);
