INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '베이글 맛집이라고 해서 방문했어요~ 음료도 맛있고, 베이글이 쫀득하니 커피와 함께 마시니 좋았어요~ 홍대 인근에 왔다가 가족들과 맛있는 시간 보내고 갑니다~ 인테리어가 독특하고, 좌석이 많아서 좋았습니다. 플레인 베이글도 좋아하는데 어니언과 갈릭 베이글을 주문해서 먹었어요. 오븐에 살짝 데워 먹으니 더 먹기 좋았습니다~', 75, 13, 'GOOD', SYSTIMESTAMP);
