INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '베이글 랜드는 끝내주는 연어 샌드위치 맛집이라는 점🥺 진짜 중독되는 맛도리예요. 직원 분들도 항상 너무 친절하셔서 기분 좋게 다녀가요. 베이글 종류도 다양해서 좋아요 헤헤☺️', 3, 1, 'GOOD', SYSTIMESTAMP);
