INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '바질 베이글에 견과류와 크림치즈 들어 있어 맛있고 시나몬베이글은 굵은시나몬설탕 입자가 씹혀서 맛나요. 트러플크림치즈 선택했는데 트레플향이 굿입니다.', 32, 8, 'GOOD', SYSTIMESTAMP);
