INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '다양한 베이글이 많고 샌드위치류도 있어서 정말 좋아요 맛있어서 또왔어요 크림치즈는 레몬커스타드고 바질리코타 베이글이예요 오븐이나 전자렌지에서 자유롭게 데워먹을 수 있어서 편해요', 23, 2, 'GOOD', SYSTIMESTAMP);
