INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '찻 방문인데 베이글 종류도 샌드위치 부터해서 너무 다양하고  매장 안에서 먹을 수 있게 인테리어도 잘 되있어서 너무 좋습니다!', 82, 17, 'GOOD', SYSTIMESTAMP);
