INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대에 있는 베이글랜드에 방문했습니다! 저녁 시간대에 방문했는데 매장도 넓고 쾌적하게 즐길 수 있었어요! 베이글 종류도 많고 샌드위치도 다양해서 취향에 맞게 즐기실 수 있어요! 치킨샌드위치 기대한 대로 맛있게 먹었습니다!', 12, 4, NULL, SYSTIMESTAMP);
