INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '겉은 바삭·속은 쫀득해서 한입 베어물면 식감이 좋아요 매장 한쪽에 토스터와 오븐이 있어 바로 데워 먹을 수 있고, 좌석 간격이 넓어 노트북 작업도 편해보였습니다. 두바이 베이글은 주말 이른오후에 바로 품절이네요. 다음에 먹어보고 싶어요.', 31, 4, 'GOOD', SYSTIMESTAMP);
