INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '자주 와서 힐링합니다~ 베이글 마시쒀요 저는 샌드위치랑 크림치즈 자주 먹는데 플레인 크림치즈도 마시꼬 바질크림치즈도 마시써요 초코 베이글은 제가 먹어야해서 추천 많이 안하고 제가 데려갈껍니다.', 18, 1, NULL, SYSTIMESTAMP);
