INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '넘나리 좋아하는 베이글... 홍대에 베이글 카페가 있다 해서 와봤는데, 베이글 종류도 다양하고 분위기도 좋아서 감동이었습니다..! 제가 먹은 고구마크림치즈베이글, 베이글의 쫀듯한 맛과 부드러운 고구마+크림치즈가 조화로워서 대만족이었습니다! 다음에는 블루베리크림치즈를 꼭 먹어봐야겠어용!!!', 13, 2, 'GOOD', SYSTIMESTAMP);
