INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '베이글만 보고 왔는데 커피도 너무 맛있어요 🥯☕️ 크림치즈랑 블루베리 가득하고 달달한 베이글에 커피가 고소하니까 조합이 너무 좋네요🩷 매장 인테리어랑 분위기도 너무 좋아요. 팝송도 좋지만 음악을 약간 클래식한 재즈로 바꾸면 매장 특유의 분위기랑 더 잘맞을거같아요', 31, 9, 'GOOD', SYSTIMESTAMP);
