INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '항상 지나는 길에 포장만 하다가 처음 매장 이용해 봤는데 생각보다 편안하게 이용하기 좋네요 빵은 언제나 맛있구요~ 곳곳에 뉴욕 느낌 가득한 소품 구경하는 재미도 있어요~', 122, 24, NULL, SYSTIMESTAMP);
