INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '베이글 종류가 많아서 골라 먹는 재미가 있어요. 게다가 선택해서 먹은 두 종류 모두 너무 맛있고, 매장 크기에 비해서 많이 시끄럽지않으편이었어요. 그리고 제가 커피에 진심인데, 커피도 매우 맛있었습니다!', 15, 1, 'GOOD', SYSTIMESTAMP);
