INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '저번에 저장해놨었는데 아쉽게 못 와서 이번에 방문하게 됐어요! 메뉴를 보자마자 연어 베이글이랑 머쉬룸 스프 조합을 먹고 싶었는데 진짜 너무 맛있었어요 최고🥺👍 다음에는 더 다양한 베이글들을 맛 보러 다시 와야겠어요~ㅎㅎ', 29, 7, NULL, SYSTIMESTAMP);
