INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '남편이랑 저랑 베이글을 좋아해서 찾아오게  됐어요. 밥을 먹고와서 배부른데도 땡기는 맛있는 베이글~~ 커피에 하나만 먹기로하고 나머지는 포장했네요. 담에는 밥 먹지말고 와서 더 마니 먹어야겠어요~^^', 75, 18, 'GOOD', SYSTIMESTAMP);
