INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '너무 맛있고 엄청 친절하십니다. 외국인 언니가 한국말도 엄청 유창하시고!!! 와 베이글진짜 탑이에요 탑 너무 맛있고 쫀득 쫀득 최고 ㅜㅜ', 104, 23, 'GOOD', SYSTIMESTAMP);
