INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '베이글맛집👍 베이글랜드 넘 좋아요! 인테리어도 완벽하고 베이글 쫀쫀한게 완전 제스탈✨ 직원분들도 너무 친절하고 인테리어가 넘 예뻐서 어디서 사진을 찍어도 다 잘나옵니다 💕', 110, 21, 'GOOD', SYSTIMESTAMP);
