INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '베이글이 먹고싶어서 왔어요! 기본부터 독특한 베이글까지 종류가 다양해요 매장 인테리어도 이국적이어서 좋고 외국인들도 많네요 샌드위치도 맛있어요😊', 6, 9, 'GOOD', SYSTIMESTAMP);
