INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '인스타에서 보고 궁금해서 와봤는데 내부 인테리어가 정말 이쁘고 베이글도 맛있어요 크림브륄레 베이글 궁금해서 먹었는데 베이글 자체가 쫄깃쫄깃해서 플레인 베이글도 맛있을 것 같아여 집 갈 때 부모님 드릴 베이글도 사서 가야겟어요:>', 68, 13, 'GOOD', SYSTIMESTAMP);
