INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '베이글 종류가 엄청 많습니다! 좌석도 많고 매장도 큽니다 인기가 많아서 재고가 빠르게 소진되어서 신선한 베이글이 계속 만들어져서 진열됩니다 👍', 125, 26, 'GOOD', SYSTIMESTAMP);
