INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '뉴욕베이글 처음와봤는데 인테리어가 예쁘고 베이글도 맛있어서 하루를 기분좋게 시작할 수 있었어요. 베이글 종류도 다양하고 쫄깃한 식감이 잘 느껴져셔 좋았습니당! 토요일 아침에오니 사람이 없어서 한적하게 즐길수 있었어요 다음에 또 방문할 것 같습니당', 18, 9, 'GOOD', SYSTIMESTAMP);
