INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '연어 샌드위치 존맛탱.. 입 엄청 크게 벌이도 개걸스럽게 먹을 사이즈 일줄 알고 긴장했는데 조신하게 먹을 수 있더라구요 다행쓰^^;; 커피도 맛있어요~', 114, 24, 'GOOD', SYSTIMESTAMP);
