INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '저번엔 친구랑 왔다가 이번이 두번째 방문인데 진짜 다리도 못뻗을만큼 답답하게 좁은 카페들만 가득한 홍대에서 드물게 넓고 쾌적해서 혼자 오기도 좋아요👍 베이글 광인인데 베이글도 맛있습니당 추천', 42, 4, 'GOOD', SYSTIMESTAMP);
