INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오후1시쯤 왔을땐 사람이 많이 없엇는데 3시되니까 바글바글하네요!! 종류도 많고 다 맛있어 보여요 ㅠㅠㅠ 커피랑 티도 기본 이상의 맛을 하는거 같아요! 집갈때 사가려구요😁 두바이 초콜릿 베이글은 당떨어졌을 때 딱이에요♥️', 105, 21, 'GOOD', SYSTIMESTAMP);
