INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '분위기가 너무 좋아서 기분이 좋아져여 베이글 진짜 너무너무 맛있어서 완전 자주 올 것 같아요 직원분들도 다 너무 친절하시고 음료도 맛있고 가격도 나쁘지 않아서 친구들이랑 함께 오신다면 인스타 사진 하나 찍고 가실 수 있으실거에여', 9, 7, 'GOOD', SYSTIMESTAMP);
