INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '베이글 너무 맛있어요😍 특히 뭐랄까 요리를 잘 했다는 느낌? 진짜 오늘 지나고도 종종 생각날 것 같습니다 ㅎㅎ 직원분도 친절해서 좋았어요', 8, 10, 'GOOD', SYSTIMESTAMP);
