INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '북적이고 시끄러운 홍대거리에서 여유를 가질 수 있는 몇 안되는 공간. 넓은 공간에 음악소리가 크지 않아도 다른 테이블 소리가 시끄럽지 않고 책 읽기 좋은 상태다. 베이글은 치즈올리브 추천. 치즈맛은 은은한 편이나 올리브의 맛과 식감이 참 맛있었다.', 22, 1, 'GOOD', SYSTIMESTAMP);
