INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '맛있다고 소문 자자해서 방문했어요. 매장이 아주 넓고 쾌적하고 베이글 종류가 정말 많아요. B E.L.T 베이글 샌드위치 주문했는데 먹기 좋은 온도로 데워 나와요. 크림치즈와 샌드위치 내용물 맛 조합이 너무 좋네요. 직원들도 무척 친절해요.', 4, 6, 'GOOD', SYSTIMESTAMP);
