INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '친구가 베이글집이라고 하니까 싫다고 하는걸 여긴 다른곳과 다르다고 해서 델꾸 왔는데 너무 맛있고 분위기가 좋다고 저보다 더좋아해요♡ 자주오고싶은 곳입니다^^', 14, 4, 'GOOD', SYSTIMESTAMP);
