INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '다른 까페에서 브런치 먹으려고 찾아가는 길에 발견한 베이글까페!! 베이글 좋아해서 일단 들어갔어요. 사람 진짜 많고... 그래서 10분정도 기다렸다가 먹을 수 있었지만...! 맛은 진짜 기다린게 후회가 안될정도였답니당>< 종류도 다양해서 골라먹기 좋아요.', 16, 1, 'GOOD', SYSTIMESTAMP);
