INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '가게도 넓고 인테리어도 예뻐서 앉아서 이야기하기 좋았구 블루베리 베이글이 잼도 딱 너무 안달게 있고 생블루베리가 많아서 안물리고 먹을수있었어요 그리고 직원분이 외국분이신데 한국말도 엄청 잘하시고 제가 더워하니까 자기 손선풍기도 주셨어요 엄청 친절하세용🩷🩷', 21, 7, 'GOOD', SYSTIMESTAMP);
