INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '우연히 지나가다 냄새에 이끌려 들어와서 먹었어요! 너무 분위기 좋은 내부에 친절한 스태프들 덕에 한끼 맛있게 먹고 갑니다! 너무 배고파서 생각없이 먹다가 급 생각이 들어 조금 남은 베이글이라도 찍어 봤어요!', 62, 18, 'GOOD', SYSTIMESTAMP);
