INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '베이글 샌드위치 먹어보고 싶어서 방문했어요! 손님 많을까 봐 걱정했지만,, 평일 12시쯤 오면 5테이블정도 앉을 자리 있네용 베이글 종류 많고, 쫄깃한 식감이 너~~~무 좋아요 카페 분위기도 좋아서 무조건 추천합니다 !!🙌🏻', 65, 15, 'GOOD', SYSTIMESTAMP);
