INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '불고기샌드위치 맛있어요 아점으로 샌드위치먹으러왔는데 베이글들이 너무 맛있어보여서 고구마랑 크림브릴뤠사가려구요~~ 테이블도 많고 베이글종류도 많고 맛집으로 추천합니다', 71, 18, 'GOOD', SYSTIMESTAMP);
