INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '세번째 방문한 홍대 베이글랜드예요. 딸이랑 두번오고 이번엔 혼자 홍대화방에 들렀다가, 베이글이 먹고 싶어 또 찾아갔네요. 플레인베이글은 본연의 쫄깃한 맛으로 자꾸 땡겨요. 발라먹어도 좋지만 커피랑 같이 먹어도 맛있어요. 종이봉지에 기름이 묻어 걱정하니 직원분이 비닐봉지를 더 포장해주어서 잘 갖고 올수 있었어요. 햐~ 다음날 딸도 좋아하는데, 너무 쫄깃하고 담백해서 음.. 다 먹어버렸네요. ~^^', 29, 10, 'GOOD', SYSTIMESTAMP);
