INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '베이글과 빵을 좋아해 이전부터 저장해둔 플레이스였는데 우연히 지나가다 딱 발견해 운명이다 하고 바로 방문했어요! 정말 이전부터 너무도 먹어보고 싶었던 베이글향해 전진후 바로 먹어봤는데 두바이는 고소롬달달하구 블루베리는 마치 블루베리시루베이글처럼 가득한 블루베리에 새콤달달히 너무 맛나게 잘 먹었어요!!! 분위기 좋은 인테리어에 넓구 쾌적한 매장에서 맛있는 베이글과 커피와 함께 힐링 가득하구 갑니당!!☺️', 37, 9, 'GOOD', SYSTIMESTAMP);
