INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '지나가다가 얼떨결에 와보고 계속 생각나서 또 왔어요! 타지역 사람이라 자주는 못오지만 서울 올때마다 오고있어요! 여기 피자 베이글이 진짜 맛도리인데.. 다른 맛도 도장깨기중이라,, 다들 피자베이글 꼭 드셔보세요!!!ㅔ 직원분도 친절하시구 다른 지역에도 체인점 내주세요ㅠㅠ', 42, 2, 'GOOD', SYSTIMESTAMP);
