INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '베이글 먹고싶으면 가끔 오는 곳이에요! 종류도 진짜 많고 깔끔해서 너무 좋아요❤️ 오늘은 감자랑 고구마 베이글 도전이었는데 최고였어요👍 다음엔 다른 베이글도 도오오전 할게욥', 62, 16, 'GOOD', SYSTIMESTAMP);
