INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), 'B.E.L.T + 아메리카노 세트로 먹었는데 바로 나와서 그런지 엄청 따끈하고 너무 맛있었어요 주문 할 때 직원도 엄청 친절해서 좋았고 매장도 넓고 분위기도 너무 좋아서 그런지 너무 맛있게 잘 먹고 갑니다 ㅎㅎ 서울에 일정이 있어서 왔는데 숙소가 근처라 돌아갈 때 재방문해서 포장해서 가족이랑 지인 나눠 주려구요 ㅎㅎ', 114, 19, 'GOOD', SYSTIMESTAMP);
