INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '먹고 나서 작성하는 리뷰입니다 베이글칩은 맛보기 서비스로 넣어주셨는데 담백해요 :) 연어는 훈제향이 짙고 딱 적당히 푸짐하게 넣어줘서 느끼하다는 느낌은 없습니다! 크림치즈랑 토마토 약간의 상추가 들어가있는데 구성은 딱 맛있는 연어베이글입니다 아침메뉴위주인 느낌인 베이글집이라 그런지 아침에 사람이 많이 오시는 것 같지만 그래도 자리가 널널해요', 50, 3, 'GOOD', SYSTIMESTAMP);
