INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '베이글 종류가 너무 많아요! 너무 다 맛있어보였는데 시즌메뉴 선택해서 먹어보니 역시나... 너무 맛있어서 테이크아웃도 할 예정이에요 :)', 6, 1, 'GOOD', SYSTIMESTAMP);
