INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '브런치도 11시부터 영업이라 이른시간 보내려 왔는데 맛집인가 봐요 포장 손님도 계속 들어오시고 빵도 아직 안 먹어봤지만 맛있을 거 같아요 🤣🤣', 21, 10, 'GOOD', SYSTIMESTAMP);
