INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '포장하실 분들은 대기 없이 바로 이용가능해요☺️ 베이글종류도 다양합니당 매장도 좌석이 넉넉한 편이지만 주말에 오시면 사람이 많아서 이용하시기 어려우실수도있어용👍 베이글 좋아하시는 분들은 포장해서 드셔보시길 추천드립니당', 0, 8, NULL, SYSTIMESTAMP);
