INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '베이컨 맛집!! 쫄깃한 베이글에 짭짤한 소금 토핑이 입맛을 돋워줘요.두툼하게 들어간 버터가 고소하고, 담백하게 즐기기 좋은 메뉴예요.', 44, 2, 'GOOD', SYSTIMESTAMP);
