INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '맛, 분위기, 인테리어 다 너무 좋아요~! 베이글 종류도 많고 음료도 맛있어용🩷 Belt샌드위치 모양도 넘 예쁘고 맛있어여😳 쪽파크림치즈베이글도 조화롭고 맛있어용 수박주스는 완전 생과일 먹는 거 같아요🍉💕', 31, 10, 'GOOD', SYSTIMESTAMP);
