INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '연어베이글 맛있어서 또 왔어요. 연어 비린맛없고 부드럽고 정말 맛있어요! 오늘은 잠봉버터샌드위치도 먹었는데 적당히 짭짤한 햄과 고소한 버터가 조화롭게 어울렸어요. 같이 주시는 베이글칩도 하나씩 집어먹으면 순삭이네요. 인테리어도 뉴욕스타일~~노란빛조명이 사진찍으면 예쁘게 나와요ㅎ 홍대오면 또 들릴께요~', 222, 74, 'GOOD', SYSTIMESTAMP);
