INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '베이글 쫀득하고 완전 맛있어용 특히 크림브륄레 베이글이 진짜 맛있어요 크림치즈가 물리지도 않고 느끼하지도 않고 완전 맛있어용ㅎㅎ 벌써 3번째 방문이에여', 5, 7, 'GOOD', SYSTIMESTAMP);
