INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '베이글 좋아해서 찾아왔데 인테리어도 깔끔하고 베이글들이 다 맛있을것 같아요^ 커피는 마시고 가고 베이글들은 테이크아웃했는데 비주얼도 좋고 얼른 집가서 먹어 봐야겠어요^^', 67, 16, 'GOOD', SYSTIMESTAMP);
