INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '출근길에 들른 베이글집! 베이글 샌드위치 먹고 싶었는데 정말 맛있네요. 연어베이글 샌드위치 신선하고 소스도 적당하니 맛있어요! 오전9시에 방문했는데 외국님 손님들이 대부분이시라 놀랐어요 ㅎㅎ 진짜 맛집인가봅니다 ~ 담에 또 올게요!', 91, 21, 'GOOD', SYSTIMESTAMP);
