INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '베이글이 나온지 얼마되지않아 데우지않아도 따뜻,촉촉행노! 페퍼로니 베이글도 맛있고 크렌베리베이글도 호두가 들어있어 고소하고 맛있었습니다. 라테도 좋아요^^', 109, 25, 'GOOD', SYSTIMESTAMP);
