INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '지난번 방문 후 맛있어서 재방문했어요. 직원분들 여전히 친절하시고 매장 깨끗하고 좋아요. 이번에는 샌드위치와 베이글 포장했어요.', 35, 6, 'GOOD', SYSTIMESTAMP);
