INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '와이프와 홍대 돌다가 발견한 베이글 맛집이내요. 분위기도 좋고 시원하고, 직원분이 외국분인데 한국어도 잘하시고, 엄청 친절합니다. 런던베이글만 있는줄 알았더니, 뉴욕 베이글도 종류도 많고 엄청 맛있습니다. 분위기 좋고 맛좋은 베이글 집에서 맛있게 먹고 쉬고 가내요, 담에 홍대올때 또 들려야 겠어요.', 2, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '출근길마다 사먹어요 오늘은 매장에서 먹고 가서 리뷰를 남겨봅니다... 다른 유명 베이글보다 여기 베이글이 전 제일 맛있오요ㅠㅠㅠ아침에 갓나온 크랜베리호두베이글에 메이플크림치즈 발라먹으면 을매나 맛있게요', 61, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '정말 너무 맛있어요… 불고기 샌드위치 환상이에요… 제가 그리고 유명한 수박주스 깐깐인데 수박주스가 완전 달콤하니 맛있어요.ᐟ.ᐟ 베이글이랑 잘어울려서 한 잔 더 시켜마셨어요 그동안 베이글이 너무 먹고 싶었는데 베이글랜드에 해소 다 하고 갑니다🥹 베이글 도장깨기하러 다시 방문할게요♡', 86, 16, 'GOOD', SYSTIMESTAMP);
