INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '다양한 베이글로 눈이 호강하는 곳 입니다 ㅎㅎ 두바이 베이글이 있다고 해서 방문했는데 그 밖에도 종류가 많아서 즐기기좋을거같아요!', 34, 9, NULL, SYSTIMESTAMP);
