INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대역이랑도 가깝고 베이글 종류도 진짜 많아요!! 에이드랑 스무디도 시켰는데 맛있어요! 베이글 질기지 않고 너무 맛있어요! 다음에 또 오려구요!', 19, 8, 'GOOD', SYSTIMESTAMP);
