INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '날씨가 좋아서 여기저기 걷다가 유명한곳인줄 모르고 들어왔는데 잘 한 선택이었어요. 간만에 맛있는 베이글 샌드위치에 커피 맛있게 잘 먹었습니다. 베이글에 연어 처음으로 같이 먹을 생각을 한 사람은 정말 천재에요. 포장 하실거면 기왕이면 베이글 6개에 크림치즈 2개 같이 들어있는 세트로 하시는걸 추천드려요. 저는 결제하고나서야 확인해서 아쉬웠네요. 베이글 칩도 빠삭하니 맛있어서 신경 안쓰면 커피랑 같이 먹으면서 무한정 흡입 할 수 있을것 같아요ㅋㅋ 시간이 애매한 타이밍에 와서 그런지는 몰라도 자리도 넉넉해서 좋았어요.', 1, 7, 'GOOD', SYSTIMESTAMP);
