INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '베이글도 맛있고 인테리어도 멋져요!! 딸이랑 홍대나들이 나왔다가 들렀는데 딸이 너무 쫄깃하고 맛있다고 하네요. 매장도 넓고 쾌적해서 더운 여름 쉬어가기도 좋았습니다.', 41, 10, 'GOOD', SYSTIMESTAMP);
