INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '홍대에 방문할 때마다 들리는 곳이에요! 특히 잠봉뵈르랑 초코베이글이 너무 맛있는🤤🤤 그리고 사장님이 너무 친절해서 올 때마다 기분이 좋아져요😆😀', 34, 5, 'GOOD', SYSTIMESTAMP);
