INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '가족들과 서울 나들이중 홍대에맛집인 베이글랜드에 일어나자마자 바로 왔습니다 아침먹으러 고고~ 이른 오픈시간에 너무 좋았고 종류별로 다양한 베이글에 시선을 빼앗겼습니다 우와~ 맛도 너무너무 내스타일~ 사장님 친절설명과 쾌적하고 멋진 실내!! 또또 오겠습니다~~', 86, 13, 'GOOD', SYSTIMESTAMP);
