INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '청포도, 복숭아 에이드랑 고구마, 크림브륄레 베이글을 시켰는데 에이드가 너무 맛있었어요 항상 다른가게에서는 부족했던 맛을 채워서 제 마음의 1등 음료! 베이글 한번도 안먹어봐서 맛있을까 의문이 들었는데 정말 맛있어서 다음에 친구나 가족들을 데리고와야겠어요', 4, 8, 'GOOD', SYSTIMESTAMP);
