INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '오늘도 역시 실패 없는 베이글맛집인 베이글 랜드 🥯 쫄깃한 베이글에 듬뿍 올라간 크림치즈가 진짜… 입안에서 사르르 녹아요. 특히 고구마 베이글은 처음 먹어봤는데 고소하면서도 달콤한 맛이 완전 제 취향! 매장 분위기도 아늑하고, 직원분들도 친절해서 기분 좋게 다녀왔어요. 베이글이 이렇게 맛있을 일인가요? 다음에 또 오겠습니다. 추천해요💛', 90, 11, 'GOOD', SYSTIMESTAMP);
