INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '커피도 맛있구 베이글은 완전 더 맛있어요!! 종류도 진짜 많고 무엇보다 매장이 넓어서 대기없이 편하게 이용 가능한게 너무 좋았어요!!', 9, 8, 'GOOD', SYSTIMESTAMP);
