INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '베이글 맛집이라는 소문 듣고 방문했어요. 매장도 넓고 쾌적해서 편하게 머무르기 좋았고, 베이글 종류가 다양해 고르는 재미도 있었어요. 제가 선택한 베이글은 치즈가 듬뿍 올라가 있어 고소했고, 커피와의 조합도 훌륭했어요. 전체적으로 만족스러운 방문이었습니다 😊', 54, 18, 'GOOD', SYSTIMESTAMP);
