INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '베이글랜드 아메리카노는 산미가 적당하고 뒷맛이 깔끔했습니다. 살몬 샌드위치는 베이글이 쫄깃하고 훈제 연어와 크림치즈 조합이 풍성하게 어울렸습니다. 전체적으로 재료 퀄리티가 높고 든든한 한 끼로 만족스러웠습니다.', 104, 20, 'GOOD', SYSTIMESTAMP);
