INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '와 고구마 베이글 진짜 너무 맛있어요!!! 달달한 고구마무스에 베이글과 어울리게해주는 크림치즈가 들어가있어요 그냥 너무맛있어요 고구마 러버들에게 추천해요 따로 크림치즈 추가할 필요없다고 직원분이 추천해주신 대로 먹었는데, 정말 이건 따로 추가적으로 바르지 않고 먹는게 킥이에요 전자레인지 돌려먹었는데 30초 돌리니까 너무… 부드럽고 따숩.. 행복해요ㅠ', 43, 10, 'GOOD', SYSTIMESTAMP);
