INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '뉴욕 관련된 아기자기한 소품이 많네요~ 아침 일찍 왔는데도 사람들이 꽤 있었지만 조용한 편이였어요. 열한시 되어가니까 이제 좀 시끌벅적 하네요. 맛있는 베이글 먹으면서 좋은 시간 보내고 갑니다~', 93, 19, 'GOOD', SYSTIMESTAMP);
