INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), 'BELT 세트 메뉴로 먹었는데 진짜 든든하고 맛있었어요! 외국인 직원분이 응대하셨는데 한국말이 아주 유창하시고 친절하셔서 좋았습니다. 다음에 홍대 오면 또 오고싶어요.', 40, 4, 'GOOD', SYSTIMESTAMP);
