INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '베이글을 선호하지않았던 제게 친구가 부탁을 해서 포장했던 게 처음이였고 호기심이 많은 저에겐 너무 궁금해 다시와서 먹어본 게 페페로니 베이글. 먹어보고 반해서 서울 오게될때면 아침에 꼭들려서 브런치 겸 점심 먹을 겸 오는데 갈릭베이글이 증말 맛있음 이거 먹고 반했음 오늘 두번째 먹음. 쥰맛.', 80, 13, 'GOOD', SYSTIMESTAMP);
