INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '우연히 지나가다 외관이 너무 이뻐서 들어왔는데, 내부도 너무 예쁘고 무엇보다 베이글 종류가 엄청 많고 맛도 좋아서 자주 오려고 합니다👍🏻🩷 외국인 직원분이 너무 친절하세요!!!', 26, 10, 'GOOD', SYSTIMESTAMP);
