INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '매장이 정말 넓고 쾌적합니다 솔직히 외관이 별로라 기대를 안 했는데 내부 인테리어는 분위기가 괜찮네요 베이글 종류도 많고 샌드위치 종류도 많이 구비해놓고 있어서 좋았어요', 13, 3, 'GOOD', SYSTIMESTAMP);
