INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '샌드위치랑 커피가 맛있었고 베이글칩 주는곳도 별로 없는데 잘 먹었습니다! 베이글 종류도 다양하고 평소에 잘 못보던 황치즈 베이글도 있어서 좋았어요 다음에 또 방문할께요!', 52, 14, 'GOOD', SYSTIMESTAMP);
