INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '잠봉 베이글 샌드위치와 아이스 아메리카노 시켰어요! 매장 내부 시원하고, 자리가 많지만 인기도 많은 것 같습니다! 참고해서 오시면 좋을 것 같아요 :) 직원 분들도 친절하시고, 다음에 재방문 의향 완전 있어요! 인테리어도 유럽에 온 것 같아서 좋아요!', 35, 7, 'GOOD', SYSTIMESTAMP);
