INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대에 베이글집이 이렇게 크게 있는지 오늘 알았어요. 직원분도 친절하고 복닥복닥 주말 홍대에서 웨이팅 없이 여유롭게 샌드위치 먹을 수 있어 좋습니다 ദ്ദി˶﻿ˆ꒳ˆ˵)', 2, 10, 'GOOD', SYSTIMESTAMP);
