INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '베이컨 베이글 처음 시켜서 먹어봤는데 진짜 소스도 베이컨이랑 빵이랑 잘 어울리고 베이컨 양도 좀 있어서 더 감칠 맛이 났습니다!😭❤️ 빵 자체도 딱딱한 편이 아니라 부드러워서 먹기 더 편했습니다!😊❤️ 직원 분도 친절하시고 매장 노래도 너무 제 스타일이라 담에 또 방문 할 것 같아요!✨', 45, 3, 'GOOD', SYSTIMESTAMP);
