INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '맛보고 싶었던 두바이초콜릿베이글은 아쉽게도 다 판매된 것 같더라구용! 대신 맛본 크림브륄레베이글 느끼하지않구 맛ㅣ진짜 맛있네요!!! 블루베리크림베이글도 나중에 꼭 맛봐야겠어요!!!', 41, 5, 'GOOD', SYSTIMESTAMP);
