INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '와 베이글이 5천원이 안넘는게 오랜만이라 기분좋게 픽했지만... 페퍼로니 없는건 아쉬우니 담에 꼭 와서 먹어볼게용 공간이 테이블과 계산대와 간단하게 나뉘어져있어 별 신경 안쓰고 먹을 수 있을거같아요. 매번 지나가기만 했는데 첨 사먹는 맛이 어떨지 기대돼요 ㅎㅎ', 15, 4, 'GOOD', SYSTIMESTAMP);
