INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '우연히 들렀는데 매장도 너무이쁘고 베이글종류도 많았어요 카운터의 외국인직원이 인상깊네요 한국말너무잘하시고요 베이글은 가격대가 꽤 있어요 베이글샌드위치종류가 진짜많아요', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '클램차우더를 먹으러 갈 것인가... 베이글을 먹으러 갈 것이냐... 그것이 문제로다~~ 리뷰 검색해보니 인테리어도 이국적이고, 베이글샌드위치 맛도 궁금하고~ㅎ 해서 낙점 된 베이글랜드~🥯ㅡ 와~ 진쫘~!!! 뉴욕~ 뉴욕~~~~스럽다~ㅋ 자유의 여신상이 한 몫 제대로 하고 있다는.. 뉴욕 느낌 더하기 베이글~~이라니~~~!!! 분위기 쩔고~ 카푸치노 맛나고, 좋아하는 시나몬베이글은 최고~👍 시나몬향이랑 아작아작 씹히는 설탕 식감 미쳤다 잠봉버터랑 연어 사이에서 갈등하던 일행은 연어베이글샌드위치에 흠뻑 빠졌다 한국말 유창한 외국인 직원분 진짜 너무 친절해서 좋았고, 그래서 외국인 손님들이 많은건가..?? 은근 중요한 카페선택의 기준인 화장실도 깨끗해서 10점 만점에 10점~!!!', 34, 5, 'GOOD', SYSTIMESTAMP);
