INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '바질과 바질에 조합이 너무 맛도리에여 다음에 또 올만하네요! 극추!! 카페 분위기도 좋고 데이트 하기 좋은 베이글 맛집! 느좋 카페', 63, 18, 'GOOD', SYSTIMESTAMP);
