INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '넓고 시원하고 모던한 분위기에서 편안하게 대화하며 좋은시간이었어요 치즈올리브 베이글은 건강하게 즐길수 있으며 함께한 캐모마일 티와도 아주 잘어울렸고, 갈릭 베이글의 부드럽고 달콤함에 빠져드는 순간도 좋았어요 베이글 홍대점에 다시 오고싶어요 ^^', 23, 6, 'GOOD', SYSTIMESTAMP);
