INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대 베이글 맛집 인졍이에오🔥❤️❤️ 쫀득하구 쫀쫀하구💕💕 데이트 필수 코스가 될 것 같아요💐💛 직원분들도 다들 친절하시구 완전 행복한 하루입니다🍀💚💚', 69, 17, 'GOOD', SYSTIMESTAMP);
