INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '연어베이글샌드위치랑 두바이초코베이글 먹었는데 둘 다 너무너무 맛있었어요~!!! 질깃한 베이글이 아니라 쫀득하고 말랑한 베이글이라 좋았어요🤤🤤', 67, 15, 'GOOD', SYSTIMESTAMP);
