INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '베이글 정말 좋아하는데 샌드위치도 맛있고 기본 베이글도 맛있어요! 직원분께서 친절하게 베이글을 어떻게 데우는지 안내해주세요. 공간도 넓고 좌석도 많아서 편하게 있다 갑니다', 3, 8, 'GOOD', SYSTIMESTAMP);
