INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '1L망고보다 이게 난 더 취향임 망고쥬스 L사이즈 2900원 한개 다 먹으면 버렸던 속을 되살려주고 망고맛이 진짜 한가득이여서 대만족임 후식으로 아쉬운 배를 달래주기엔 충분해서 좋았음 ㅎㅎ 건강하면서 깔끔하게 먹고 싶으면 망고쥬스ㄱㄱ 생크림안좋아해서 1L망고는 별로였음 차라리 이걸로 XL사이즈로 변경해먹는걸 추천함', 14, 9, 'GOOD', SYSTIMESTAMP);
