INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '식후땡 망고 마셨는데 넘 달달하고 맛있어요!ㅎㅎ 가볍게 마시기에 크기도 적당한 것 같고 (좀 작아요) 잘 마셨습니당😊 진한 슬러시 같아요!', 47, 2, 'GOOD', SYSTIMESTAMP);
