INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '소프트아이스크림 최애💕 고망고 있음 꼭 사먹는 믹스 소프트아이스크림. 일행 뜨아 샷 추가 주문. 다크로스팅 인듯. 탄맛이 강한 뜨아입니다. 컵홀더가 과일포장재같아요!', 57, 16, 'GOOD', SYSTIMESTAMP);
