INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '항상 사람이 많아서 그냥 지나쳤는데 오늘 도전해봤어요~망고 이렇게 많이들어있는데 3500원 이라니 진짜 대박이네요~😀얼음에 시럽 더 뿌려주심 맛있을꺼 같아용', 81, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '사람들이 손에 뭘 다 들고있길래 뭐지?! 했는데 여기더라구요! 바로 가서 식후망고 먹어봤는데 생과일 망고를 간 것 처럼 꾸덕해서 너무 좋았어요! 생과일주스 먹으면 다른거랑 배합해서 더 맛이 별로였는데 이건 진짜 꾸덕한 망고맛에 1800원이라니 ㅎㅎ 혜자네요👍🏻 오늘 또 갈 예정입니다👍🏻👍🏻💕💕', 5, 10, 'GOOD', SYSTIMESTAMP);
