INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '연남동 올 때마다 망고주스 가게에 줄이 너무 많아서 정말 궁금했어요! 제가 갔을 때 밖에 줄이 없기도 하고 더워서 딱 지금 가보기로 했습니다! 망고주스 제일 저렴한 게 있어서 스벅 레귤러 사이즈인줄 알알는데 그거보다 더 작은 사이즈에요! 다섯입 정도 후루룩 먹으면 다 끝납니다 찐득한(?) 느낌이라 완전 망고만 가득 든 것 같아요! 달달하고 엄청 큰 컵으로 가득 먹고 싶어요.. 안에 주문은 키오스크로 하면 되고 밖에 줄 서 있다가 번호 부르면 받으러 가면 됩니다! 번호 확인하고 주스 주셔서 다른 거 가져갈 일 없습니닷! 굿굿 줄이 길고 오래 걸리는 거만 아니면ㅠ흑', 23, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '망딸코 컵빙수 너무 맛있어요. 이 가격 실화예요..? 너무 저렴하고 양도 많고 가운데에 있는 아이스크림이 코코넛 맛이었는데 코코넛 아이스크림 이렇게 맛있는 건 줄 몰랐어요 홍대 연남 올 때마다 먹으려고요 !! 후식으로 가볍게 입가심하며 먹기 완전 딱이에요..', 9, 5, 'GOOD', SYSTIMESTAMP);
