INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '가성비 망고주스 한 잔! 홍대 나가서 친구와 술 한 잔 하고 입 깔깔할 때 입가심으로 가볍게 한 잔하기 딱 좋아서 자주 애용합니다^^', 17, 8, 'GOOD', SYSTIMESTAMP);
