INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '외국인 내국인 포함 줄이 길지만 금방 빠져요 가성비 너무 좋고 혼자 먹을 양이 아니에요 2인용입니다 ㄷㄷ 😱 연남 맛도리 망고빙수  😎', 39, 9, 'GOOD', SYSTIMESTAMP);
