INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '가성비 최고인듯...? 생각보다 저렴해서 좋아욬ㅋㅋㅋㅋㅋㅋㅋㅋ 망고 좋아하시면 가볼만 한거 같아요~😆 매장이 작고 손님은 많지만 이유있는 기다림...ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 다 테이크아웃이라 음료 들고 걸어다니면서 마시거나 앞에 의자에서 먹어야해욥🤔 배부를때 먹으면 진짜 양 많게 느껴지는 양이에요~', 52, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대입구역 코앞에 있는 고망고🥭 사람들이 엄청 북적여서 봤더니 다들 망고주스 기다리고계시더라구요! 점심 먹고나서 입가심할거 찾았는데 마침 식후땡 망고주스가있어서 마셨어요! 메뉴명 그대로 식후에 시원하게 마시기 딱 좋은 망고주스입니당ㅎㅎ', 78, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '가성비 미쳤네요. 앞 벤치에서 드시는 분들 많아서 사봤는데 아래 얼음은 좀 싱겁지만 더울 때 시원하게 먹기 좋아요. 이게 3,500원입니다', 22, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '알바분께서 많이 바빠보이긴 했지만.. 주문은 키오스크 방식이고 고망고 퍙소에도 너무 좋아해서 맛있개 잘 먹었어요!! 사고펄이랑 타피오카 펄 조합도 괜찮으니 몇 백원 더 내서 시켜보는 거 추천해용', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '가성비 극강 고망고 ~~~ 홍대 갈때마다 꼭 들려서 한잔 마십니다. 전보다 조금 묽어진 느낌은 있지만 여전히 가성비 생각하면 이만한데가 없지요. 작은 식후땡 망고는 1500원. 망고주스 커피집 라지 사이즈 정도가 2900원이면 일단 먹어봐야죠 ㅎㅎㅎ 강추 ~~~', 6, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여기서 망고 신세계 제대로 즐겼어요🥹 망고도 엄청 큼지막하게 올려주시는데 가격도 핵착함 ㅋㅋㅋㅋ 깍두기처럼 생긴 망고 먹어봤는데 달달구리하구 양도 많아서 최고ㅠㅠㅠㅠㅠ 연남동 갈때마다 항상 들림✌🏻 📌더 자세한 리뷰 : 인플루언서 푸드조하 개인계정 https://www.instagram.com/food_zohaa https://youtube.com/@food_zohaa https://www.tiktok.com/@food_zohaa', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '고망고에서 망고와 딸기 아이스크림이 들어간 망딸코컵빙수를 맛보았어요. 넘 좋아요. 망딸코컵빙수를 들고 홍대역 근처를 돌아다니니 괜히 힐링이 되네요. 여유도 한껏 즐긴것 같구요. 부담없는 가격에 힐링을 느껴보세요.', 43, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '식후땡 망고(1800원) 먹었어요. 되게 맛있어요!! 가성비 너무 좋고 양도 적은 것 같은데 밥 먹고 먹으니까 은근 많더라고요. 다음엔 빙수 먹어보고 싶어요ㅎㅎ 테이크아웃만 되는 건 좀 아쉬움ㅜ', 36, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '크게 기대하지않고 주문했는데, 재료가 생망고로만? 들어간 것 같아서, 건강하면서도 너무 맛있었어요~!!💛🧡 그리고 개인적으로 작은 사이즈 음료를 좋아하는데, 앙증맞은 딱 적당한 사이즈라서 밥먹고 나서도 바로~ 부담없이 먹기 좋을 것 같아요!👍💗 그런데 맛있어서 다음에 가면 망고 큰사이즈로 주문할 것 같아요~!!😆', 65, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '망고철이 끝났나봐요ㅠ 당도가 엄청 약해졌네요😭😭 보통 먹었을때보다 당도가 한 20프로 정도 되는것같은데 너무 밍숭맹숭해서 좀 아쉬웠어욥 주문이 많이 밀려있는데도 불구하고 음료는 빨리 나와서 좋았습니다!', 16, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '고망고 연남점에서만 판매 중인 깍두기망고빙수!! 달달하면서도 시원하니 정말 맛있었습니다. 평소에는 먹어보지 못하는 맛이라고 해야 할까요.. 식후땡 망고도 달달하고 슬러쉬같은 느낌이 들어서 좋았어요!! 카페전문 유튜브 유리소리TV', 27, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '1리터망고 드디어 먹어보았어용👍 크기가 진짜 후덜덜해여 망고쥬스에 생크림,아이스크림,망고까지 망고아이스크림 보들보들 넘 맛있어여😍 1리터망고 4800원! 코코넛젤리 500원 추가해서 5300원! 갓성비 대박! 매장도 노랑노랑 너무 이쁘져^^ 먹다보니 양이 너무 많은데 언제 다 먹나요😆😆 홍대입구역 3번출구에서 조금만 걸으시면 있어요 담에 또 먹으러 올래여😍', 48, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '망고사고랑 코코넛 망고 주스 맛있어여! 근데 사고는 생각보다 너무 달았어여😭 그래두 한번쯤 먹어볼만합니당~ 사람들이 정말 많은데 금방금방 빠져서 괜찮았어여', 58, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '망고가 이렇게 맛이 없군요. 세상 모양만 예쁘고 맛이 너무 밍밍해요. 단맛이 거의 없는 망고에요 망고 조각도 냉동 망고인데 단맛 없구요 아이스크림만 조금 달아요 아래 깔린 망고색상 물은 뭔지 모르겠어요 망고 맛도 안나고 무슨 맛인지도 모를... 이걸 줄 서서 먹을 이유가 없어요 먹는 사람들이 다 맛있지는 않네? 바로 옆 프랑스 분들도... 쎄빠 봉...? 안좋대요.. 진짜 가장 빛 좋은 개살구이네요 황당해서 리뷰 남겨요', 2, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '요즘은 고망고만 먹어요 가성비 최고👍🏻❤️ 메뉴도 다 맛있고 테이크아웃 전문점인데도 직원분들도 항상 친절하세요😍 빙수, 망딸바 식후땡 망고 특히 넘 맛있어요 강추강추', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '매장이 비좁다못해 공간이 거의 없는 수준인것에 비해 사람이 많아 어수선하고 대기도 조금 있지만 요즘같이 더운 날씨에 시원하개 먹기 좋습니다. 박리다매인지 가격도 너무 싸서 가성비가 좋네요…', 11, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '컵빙수 엄청 커요 혼자먹기엔 많은 양이고 둘이 먹음 좋아요 더워지는 날씨에 고망고 자주 가야겠어요 가성비 최고+시원하고 맛있어요', 44, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '망고사고 처음 먹어보는데 그냥 식감이 공차 펄 같이 쫄깃한데 사이즈만 작은버젼 이네영 ㅎ 더울때 팥빙수 처럼 후루룩 먹기 좋은거 같아영!', 28, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '망고사고 + 1L 망고 + 식후땡 망고 를 먹었어요 !! 확실히 핫플이라 사람들도 많고 음료도 맛있더라구요 ~ 다음에는 깍두기 망고? 꼭 먹어보러 와야겠어요 (^^)b', 111, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '언 망고여서 망고는 그닥 맛있진 않았고 비주얼이 좋았고 아이스크림이 맛있었어요 3500원짜리 망고빙수 먹는 느낌이라 가성비는 좋았습니다', 71, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '좀 많이 단데 맛있어요! 연남점은 망고토핑 여러개 있는데 망원점은 완전 양도 조금 토핑도 한두개? 뿐이었는데 왤케 지점마다 다른지ㅠㅜ 연남점에서만 먹을래요!!!!!', 50, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '내돈내산 고망고 첫영접 망고 코코넛 짱맛있네요 달기는 엄청 단데 자극적인 단맛이아니라 건강한 과일의 단맛이 좋아요 코코넛크림이랑도 잘어울렸는데 입에서 살살 녹는맛이네요ㅠㅠ 칼로리가 걱정되지만 먹는순간만큼은 행복합니다 당분간 엄청 사먹을것같아요😊', 19, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '망고사고 먹었는데 공차에 비해서는 너무 달아서 입에 살짝 물린거 말고는 쫄깃쫄깃하고 맛있게 먹었어용 알바분들 바쁜데도 친절하셔요!!', 27, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '자주 방문했던 고망고에서 망고사고가 나왔다는 소식을 듣고 달려갔어요. 저에겐 정말 맛있었은데 호불호가갈린다고 했어요 근데 다른 지점에서 먹었던 망고보다 연남점이 제일 맛있는 듯 합니다', 45, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '여기만 특별한 메뉴가 있어요!!! 망고사고랑 망고깍밥 그런디 망고사고 너무 맛있어요!!! 꼭 생각나는 맛이예요~ 동남아 안가도 즐기는 망고♡', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '이렇게나 예쁜 망고 가득한 음료와 디저트들이 너무나도 저렴해서 놀라고 맛있어서 또한번 놀라게되는 고망고! 방콕여행 갔을때 먹고 반했던 망고밥이 계속 생각났었는데 이제는 그 망고밥을 고망고에서도 만나볼수가 있어서 너무 좋았어요! 코코넛 들어간 찰밥과 망고의 조화 진짜 예술이고 아이스크림과 망고 딸기 코코넛젤리까지 추가한 거대사이즈의 망딸바 역시 최고! 귀여운 망고만쥬 역시 망고잼이 들어가 너무 맛났어요. 조만간에 다시 찾을 듯 합니다! 엄청 바쁜데도 직원분들 에너지 넘치시고 친절한 모습 너무 보기 좋았습니다!', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대입구역 3번 출구에서 5분거리에 있는 고망고 연남점! 테이크아웃만 가능! 바로 앞 연트럴파크에서 많이들 앉아서 드시네요. 가성비 좋은 망고디저트가게로 유명! 봄여름에는 웨이팅이 장난아님! 12월에도 시원달달한 걸 좋아하는 분들이 줄을 잇는 디저트맛집! 요즘 딸기철이라 1리터 망딸바로 주문했으며, 1l 망딸바에는 망고뿐만 아니라 딸기, 바나나까지 같이 들어있어서 풍부한 맛을 맛볼수 있습니다. 그러나 딸기는 냉동임요~~ 망고아이스크림 진짜 맛있네요. 달달하고 꾸덕한게 역시 맛있었어요. 생바나나랑 냉동 망고도 달달하고 맛있어요. 근데 냉동 딸기는 딱딱하고 맛이 없어서 녹은 후에도 먹지 않고 결국 버렸어요ㅜ.ㅠ 딸기없는 걸로 드시는걸 추천 ㅋ ㅋ 딸기망고스무디는 맛있었어요. 추운 겨울에에도 완전추천!', 29, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '티에서 단맛이 날 수 있다는게 놀라워요. 다음번에 사장님께 믈어봐야겠어요. 티에 망고 시럽을 첨가하는 건지… 아님 티백만으로도 이런 맛이 나는건지요. 급 궁금해집니다. 식사 후 후식으로 좋은데 여긴 포장만 가능하답니다. 차 마실 수 있는 곳으로 이동해야해요~', 43, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '평소 망고 코코넛을 너무 맛있게 먹어서 이번엔 리얼 코코넛에 도전했는데 코코넛 향이 별로 안 진해서 조금 아쉬웠어요🥲 코코넛보다는 바닐라 향이 강한 음료이자 아이스크림처럼 느껴졌구요. 코코넛 젤리도 기본으로 들어가니 참고하셔야 할 것 같아요. 망고 코코넛에 들어가는 코코넛이 훨씬 더 맛있어요..ㅎㅎ😊', 46, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '점심시간에 밥먹고 식후땡 망고를 가끔 먹습니다. 맛은 있는데, 직원분이 피곤하신건지 불친절하셔서 기분이 좋지 않았습니다. 인도에 가있으라고 짜증내셔서 가있느라 음료가 나왔는지 잘 안보여서 좀 늦게갔는데, 짜증내시며 음료를 노룩패스하듯이 던지셨어요', 70, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대입구역 7번 출구 앞에 고망고 연남점 진짜 가성비 쩌는 망고 맛집이다. 밥 먹고 식후땡 망고한 잔이면 세상 다 가진 거지 ㅋㅋ', 31, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '한참 잘 마셨지만 오랜만에 마시니 너무 맹탕이라 실망스러웠습니다. 이날만 그랬길 바랍니다. 그동안 인근의 타지점들 보다 연남점이 훨씬 맛이 좋았는데 걱정됩니다. 어플로 스탬프를 적립하면 아메리카노 쿠폰을 받을 수 있고 그걸로 다른 음료도 추가 금액을 지불하면  변경 가능해서, 게다가 키오스크에서 가능해서 편하고 좋습니다.', 87, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '진짜 미친 갓성비... 이렇게 저렴한 디저트집이 연남에 있다니 너무 좋네요ㅠㅠ 망고코코넛은 달달하니 맛있고 망고밀크티는 밀크티에 망고향이 도는데 되게 독특했어요 망고밥은 신기해서 구매해봤는데 밑에 찰밥이 있고 달달하고 쫀뜩한 맛이 납니다!!', 50, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '🍀나만의 또간집🍀 🥭망고티 2,500원 ⭐️추운날엔 망고티, 더운날엔 식후땡망고 다들 차가운것만 먹는데 추운날에 망고티 드셔보세욤 망고티 쟁기고싶음!! - 먹을곳없음(테이크아웃)', 34, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '가성비 과일음료로 고망고 추천이요!! 주로 대학가에 있어서 동네에선 찾기 힘든데 홍대입구역에 있어서 반가워서 하나 겟!!! 달콤달콤 그 자체😁😀입가심용으로 먹으면 좋아요!', 26, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '드디어 먹어 본 망고 연유 밥! 항상 먹어보고 싶었는데 먹어 봄 근데 냉동을 해놓는건지 바로 주시더라구요 밥이 살 얼어서 서걱거리는 느낌이 좀 별로였는데 망고랑 같이 먹으니 존맛 밥이 차갑지 않고 좀 더 떡 같았음 진짜 맛있었을텐데 아쉽 코코넛이랑 연유도 좀 더 많이 들어야 좋을 거 같음', 20, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '망고가 이렇게 맛잇엇다니요,,? 동남아 생각나는 망고맛이라고요!~~~ 큰거 하나하서 회사팀 4명이랑 나눠먹엇어요 ㅋㅋㅋㅋ아니 진짜 가성비 너무 좋은거 아니냐구요,,🥹🥹 감사합니다 또올게요💓💓', 264, 88, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '존맛탱입니다! 너무 맛있어서 순식간에 먹어버렸어요😋 가격도 착하고 망고도 신선한맛! 진짜 식후 커피보다 식후 망고땡입니다. 저는 2900원 짜리 망고 코코넛,제 취향입니다. 코코넛이랑 잘 어우러져 망고의 신원한 맛과 코코넛의 우유맛이 반반으로 궁합이 잘 맞습니다. 진짜진짜 맛있습니다. 가성비도 최고구요. 다음에 또 먹을거에요,중독되는 맛이라구요. 다음메뉴는 망난희 망고도 먹을거에요. 진짜 망고토핑으로 하고 아이스크림은 빼서 먹는 메뉴 있으면 좋겠습니다. 오늘도 맛집 성공!', 78, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '연남에 있는 고망고! 망고를 좋안하는 편은 아닌데, 젊은 분들이(?)  많이 들어가길래 궁금해서 가봤어요! 일단 가격이 정말 착하네요. 식후땡망고는 컵은 작지만 가격이 저렴하고, 일반 저가커피에서도 이가격보단 더 받을꺼 같은데 암튼 가격보고 놀랐네요! 맛은 쏘쏘 길가다 재미로 먹긴 나쁘지 않았어요', 49, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '1리터망고 4800원 대박이지 않나요? 홍대오면 고망고는 무조건필수!!! 진짜 맛있고 저위에 올라간 망고아이스크림도 느므 맛있어요^^', 28, 3, 'GOOD', SYSTIMESTAMP);
