INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '양이 상당하네요!! 초딩2 어른1명이 먹기도 많아요! 찬걸 안 좋아해서 그랬는데 맛났어요!! 근데 옆에 쓰레기통 하나 두셔야겠어요!! 옆에서 같은거 먹던 아저씨들도 왜 먹고있는데 양이 늘어나냐고ㅋㅋ 맛나고 양 많고~', 79, 14, 'GOOD', SYSTIMESTAMP);
