INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대역 고망고연남점 망난희 컵빙수 3,500원 싸고 양많아 더울 때 먹으면 짱이겠는데 10월중순 갑자기 추워져 ㄷㄷㄷ 얼음은 안먹고 아이크림과 망고만 먹음', 98, 23, NULL, SYSTIMESTAMP);
