INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '1L리터 망고주스를 먹어봤는데 양이 저렇게 많을 줄 몰랐어요~~. 한손으로 들기 벅찰 정도로ㅎㅎ. 망고맛이 진해서 좋았는데 생크림 양이 너무 많아서 생크림 양만 조금 줄였음 좋겠어요~.', 61, 12, NULL, SYSTIMESTAMP);
