INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '2000원 아이스크림 먹었는데 옆에 3500원 거대한 망고빙수 보고 후회했어요 맛은 다 좋아요 ㅎㅎㅎ 경의선 숲길에서 맛있게 냠냠', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '올때 마다 저게 궁금 했었는데 먹진 못했어요 근데 이번에 연휴때 나들이 나왔다가 이번엔 먹어 보자 하고 가격도 저렴 하고 양도 많아 보여서 먹어 봤는데 개뿔ㅋㅋㅋㅋㅋ 어이없는 맛ㅡㅡ 끝까지 먹지 말걸 먹은 내가 바보지 진짴ㅋㅋㅋㅋㅋ 냉동망고일줄은 알았지만 좀 녹여서 주던가 아니면 설탕이라도 뿌려 주던가 이건뭐 먹다 바로 뱉어 버림 기분나쁨 아이스크림이라고 해야하나? 저건 그나마 먹을만 함 도저히 못먹어서 반도 못먹고 그냥 다시 가게로 가서 버려 달라고 하고 옴 그냥 사진찍는용일뿐 먹는건 그냥 내 입을 불쾌 하게 만드는것', 44, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '우유빙수가 아니고 일반얼음빙수 정말 오랜만에 먹어봅니다! 아이스크림은 코코넛아이스크림이라 참고해주세요! 얼음빙수라 시원하긴 시원하네요 :)', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '늘 연남동에 오면 사람이 북적여서 궁금했던 곳이에요. 이번엔 사먹어봤는데 꾸덕~ 리얼 맹고🫰🏻💜 여기가 벳남인가요~~~👍🏻👍🏻👍🏻', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '1리터짜리 즁간에 생크림이 잔뜩 들어있지만 그래도 가성비 대비 짱이에요! 망고도 완전 냉동맛이나 쥬스도 시럽맛 나는거 아니구요! 동네에 있움 자쥬 갈듯:)', 34, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '연남 센트럴파크에서 다들 망고 부케 들고 다니길래 나도 갖고 싶었잖아~~~망고빙수에 코코넛 젤리 추가해도 4000원?가성비 레알 갑!!이제 연남동 갈때마다 망고쥬스. 빙수는 무조건 고망고♡', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '지나가다가 망고컵빙수 사드시는 분들 보고 홀리듯 주문했어요 ㅎㅎㅋㅋㅋㅋ 3500원에 이만한 망고방수라니 가성바 너무 좋아요!! 더웠는데 더위가 싸악 사라지는 시원함이고 위에 올려진 아이스크림이 부드러워서 진짜 맛있어요 ㅎㅎ 밑에 딸기청까지 섞으먹으면 상큼달달 맛있니다! 아메리카노도 맛있어요 ㅎㅎ', 60, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '맛은 있는데 장사에 기본이 안되어있다 오픈시간이 11시면 그전에 재료준비가 끝나있어야 되는거아닌가 ㅡㅡ 11시반에가도 음료가 안되는게 엄청 많다 한두번도 아니고 사장님은 알바 교육 다시 시키셔야할듯요 진짜 일부로 가는데 짜증나서 이제 안갈란다 음료 전문인데 죄다 품절이래 무슨', 459, 91, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '가성비가 좋은 디저트 가게입니다. 국내에 디저트들이 쓸데없이 넘 비싸서 항상 불만이었는데, 여기는 대박날 수 밖에 없는 가격대인 것 같아요. 컵빙수의 얼음은 곱게 갈린 것이 아니고 전체적으로 맛있지는 않지만 가성비 때문에 만족스러웠어요. 식후 디저트로 음료 종류들을 더 추천드리고 싶어요.', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '웬일로 대기줄 없길래 바로 달려가서 주문! 바로 줄이 생기더라그요 ㅎㅎㅎ 넘 신선하구 진하고 깊은 망고주스 💓 또 생각날듯요 ㅎㅎㅎ', 26, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '와... 진짜 이가격에 이맛은 말이 안되쥬!! 딸기 시럽 들어가있는 망고 컵빙수인데 아이스크림이 코코넛이라 진짜진짜 맛있어요! 여름내내 먹을듯~~♡', 49, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '인테리어 간판도 너무 귀요운데 음료도 빨리 나오고 맛있어요!!! 1500원짜리는 딱 입가심으로 좋은듯... 컵홀더 귀여워요...귀엽다...', 31, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '망고를 이렇게 저렴한 가격에 먹을 수 있는 것도 좋았고 그게 또 맛있어서 좋았어요! 다만 생크림 양이 조금 적게 들어갔으면 좋겠어요ㅠ 상큼하게 마무리 하고 싶었는데 약간 묵직해지고 느끼해져버린 속...ㅎ', 45, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '연남동 핫플레이스 고맹고우~ 다들 빙수를 드시던데 배가 부른 나머지,, 갓성비 이색메뉴를 주문해보았으나,,, 짜망고는 별루였읍니다ㅠ 쪼끄만 식후땡 망고쥬스는 우리가 상상하는 맛!', 87, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '얼마전에도 다녀갔는데 고망고 가성비 짱 !!! 최고에요ㅎ 연남동 입궁에 있어서 찾아가는것도 쉽고 너무 맛있어요 가성비 최고!!!', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '연남동에서 꼭 먹어줘야하는 망고주스 저렴하고 밥먹고 공원에 앉아 먹기 딱 좋아유 다 마신 컵은 가져다 드리면 치워주시니 아무데나 버리지 맙시다~', 52, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '양에 놀라고 맛에 놀랐어요 ㅎㅎ 진짜 맛있어요! 딸기는 냉동같이 조금 딴딴하긴 해요 망고랑 바나나 맛있고 근데 뚜껑이 없어서 녹으면 마실 때 불편해져요ㅠ 플라스틱 수저는 녹기전까진 좋은데 녹으면 소용이 없어지는ㅋ 윗부분은 조금느끼~ 중간은 맛있고 마지막은 아쉬운 맛! 코코넛 젤리는 안하는게 나은듯합니다! 둘이서 하나 먹어야 될거 같아요 엄청 배부름', 17, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '요즘 천오백원으로 무얼 하나요...? 고망고는 가능합니다. 한번 갈린 망고가 씹히면서 식후로 먹기 좋은...🤤 오래전부터 알고는 있었지만 항상 대기줄이 길어서 미루다가 첨 와봤는데 최고네요! 🩵🫶🏻🩵🫶🏻', 9, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '🔹메뉴추천 : 식후땡망고 🔹개인적 의견 : 식후땡 망고 1500원짜리 한 잔이면 태국 가는 비행기값 아낄 수 있음. 이렇게 맛나고 달달한 망고주스를 ... 1500원에 먹을 수 있다니 진짜 미친거 아닌지🫢.. 살면서 뭘 차리고 싶다고 생각한 적 잘 없는데 고망고는 진짜 없는 곳 내가 다 차리고 싶다🥹 곧 여름인데 상큼한 망고 주스 진짜 최고인듯🥭🥭🥭🥭🥭❤️ 망고주스 한 잔 테이크아웃해서 경의선숲길이랑 연트럴파크 걸으면 그것이 바로 소확행🎵 💙장길동의 맛도리로드 팔로우하면 전국 맛집 다 알지롱💙', 2, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '대기공간이 따로 없어서 밖에서 기다려야됨 대기번호가 LED화면에 딩동 뜨고 1500원짜리 망고주스 식후땡 사이즈 진짜 작음 10모금내로 끝나는듯 찐 망고에 물에 설탕 넣은 맛(?)', 49, 0, 'BAD', SYSTIMESTAMP);
