INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '망고밥, 컵빙수,망고스트로베리 다 양도 많은데 망고관련된 음료 파는 곳이라 그런지 망고가 맛나네요 망고밥도 이색적이고 컵빙수 양보고 놀랐어요! 양많고 맛나요', 39, 10, 'GOOD', SYSTIMESTAMP);
