INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '음료가 마시고 싶은데 가격이 부담되거나 식사하고 뭔가 아쉬울때 생각나는 고망고! 평소에는 싱후땡망고를 즐겨 마시는데 오늘은 망고코코넛마셨어요. 망고도 너무 맛있지만 코코넛크림?이 부드러워서 진자 맛있어요. 소리날때까지 계속 빨게돼요ㅎㅎㅎ 다음엔 아이스크림이나 다른 메뉴도 먹어보려구요🩷', 5, 3, 'GOOD', SYSTIMESTAMP);
