INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대 가면 꼭 먹어요 밥먹고 후식으로 사서 앞에서 막기 넘 좋습니다 1리터 사면 둘이 나눠 먹을만큼 양도 많아요 망고 아니스크림 부드럽고 안에 크림도 맛있어요 갈아진. 말고는 말할필요도 없이 맛있어요', 5, 0, 'GOOD', SYSTIMESTAMP);
