INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '짱 빨리 나왔어요! 처음 주문이였는데, 왕맛있게다하고 왕 큰거 시켯더니 너무 욕심을 부렸어요 ㅠㅠ 양이 넘 많아서 다 못 먹었답니다 데헷🤭', 2, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '1500원짜리 가성비! 근데 온리 망고만 들어간거 같지는 않아요 망고랑 바나나아니면코코넛을 좀 넣은거같은 부드러움이 있는 맛입니다', 42, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대에서 연남동 가는 거리에 있는 디저트 가게. 망고를 주원료로 하고 있는데, 망고 좋아하시는 분들은 합리적인 가격에 즐길 수 있는 곳입니다. 내부에 좌석이 없어서 바깥에 철길에 앉아가지고 얘기를 하면서 먹을 수 있는 곳입니다.', 7, 2, 'GOOD', SYSTIMESTAMP);
