INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '원래는 1,800원 아메리카노를 마시지만 오늘은 텀블러를 챙겨와서 일리터를 마셨어요 ! . 일리터 텀블러에 넣으니 딱이였어요 😊 얼음도 많이 넣어달라고 부탁드렸는데 많이 넣어주셔서 하루종일 마실 수 있을 것 같아요 😊 오늘 하루도 고망고 커피로..카페인 수혈 해보겠습니당', 46, 3, 'GOOD', SYSTIMESTAMP);
