INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '[식후땡 망고] - 크기가 작은 망고주스 - 이름 그대로 식후에 먹기 좋음 [망고 스트로베리] - 딸기랑 생크림이 올라간 망고주스 - 맛이 없을 수 없는 조합 - 사진이랑 너무 달라서 문제;;', 44, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '사이즈가 좀 작긴 하지만 식후망고라는 이름에 걸맞게 딱 입이 즐거운 정도에요. 동네에 이런 집 하나 있음 진짜 좋을 거 같아요', 77, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '리뷰 사진으로 공간을 보고 인테리어에 반해서 오늘은 무조건 여기다 하고 왔는데 입구쪽에 비치되어 있는 의자마저 감성 있어보이는 것 뭐죠 .. 🥹 공간 사진만 찍으러 가도 충분히 좋을 것 같은데 음료잔도 너무 귀엽더라구요 또 찰칵찰칵.. 산미가 있는 원두인 것 같아요! 향이 독특해서인지 라떼가 일반적이지 않아서 신기하다고 하면서 마셨어요 사장님도 친절하세요', 109, 25, 'GOOD', SYSTIMESTAMP);
