INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '와이파이가? 따로 없다고 하네요.. 이런 카페는 처음이라 당황했습니다.. 그럼에도 노트북 작업하시는 분들 꽤 있어요 레몬 마들렌 맛있고 아메리카노 산미 있는 편이에요 무난~ 제가 갔을 땐 강아지는 없었습니다!', 12, 3, NULL, SYSTIMESTAMP);
