INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '일단 커피가 정말 맛있어요 ㅜㅜ 사장님 진짜 커피에 진심이신 것 같아요!!!! 그리고 프렌치 토스트 너무 퐁신퐁신해서 입에서 살살 녹아요🤤 그리고! 키루🤍🖤 다음에 또 와야지><', 67, 15, 'GOOD', SYSTIMESTAMP);
