INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '오픈샌드위치 너무 맛있게 먹었어요! 무화과도 잔뜩 있어서 더 좋았습니다. 아메리카노는 산미가 느껴졌는데 맛있었어요. 플랫화이트도 맛있어요! 새로 바뀐 공간도 멋있네요!!', 16, 3, 'GOOD', SYSTIMESTAMP);
