INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '브루잉 커피와 계절 오픈샌드위치 주문했습니다 :) 4가지 원두가 있었는데, 사장님께서 원두별로 설명해 주셔서 산미 없는 원두 선택하였습니다 😺 요근래 먹은 드립 커피 중 가장 맛있게 먹은 것 같아요! 오픈샌드위치는 다채로운 맛이었어요. 안 어울릴 것 같은 재료들이 한데 어울려져서 은근하게 맛있었습니다. 오픈샌드위치를 먹으면서 커피 한 모금하니 아주 좋았습니다.. 메뉴 기다리면서 빈티지 가구 구경도 하고, 귀여운 키루도 보는 재미가 쏠쏠합니다. 카페에 나오는 음악이 다른 곳과 달리 재즈류가 나와서 오히려 책 읽거나 사색하기에 좋았습니다  :) 다음에 또 방문하려구요!  ☺️', 17, 10, 'GOOD', SYSTIMESTAMP);
