INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '프렌치토스트가 먹고싶어서 방문했어요:) 토스트가 넘 몽글몽글 맛있어요~ 키루가 너무귀여워욬ㅋㅋㅋㅋㅋㅋ 처음에 조금 놀라긴했지만 아늑하고 따스합니다 다음에 또 오고싶어요:)', 12, 8, 'GOOD', SYSTIMESTAMP);
