INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '따뜻한 밀크티 주문했습니다 단 맛이 없는 밀크티 같아서 본연의 향 맡으면서 삼삼하게 마시기 좋았어요 = ) 저녁의 하우스 키루도 매우 좋네요 서비스로 주신 커피, 빵 잘 먹었습니다  :)', 61, 16, 'GOOD', SYSTIMESTAMP);
