INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '런치콤보 궁금해서 방문했는데 분위기도 힙하고 친절하시고 음식까지 맛있어서 행복한 외출입니다! 리갈레토 익힘도 딱 좋고 스프 굿이예요:) 주문하실때 카운터로 가셔서 콤보에 들어갈 메뉴 정하시면되요.', 32, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '런치 시간이 11:00~15:00 래요. 5분 전에 도착해서 점심세트 안되나 했는데 친절하게 받아주셔서 감사했습니다! 오늘의 수프는 양송이 수프였고 오늘의 주스는 오렌지주스였는데 착즙이었는지 맛이 너무 좋았어요. 다음에 친구들이랑 재방문하고 싶어요♡', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '브런치 맛집 검색해서 찾아온 곳입니다^^ 역시 친절하고, 맛도 너무 좋아요. 아보카도 샌드위치도 맛잇고, 볼로네미트볼 파스타도 좋아요~ 오픈 타임에 맞춰 평일 방문 했는데, 외국인 손님들도 많이 찾아오는 소문난 맛집이네요~~ 맛있는 음식 먹게 해주셔서 감사합니다^^ 참! 가성비 맛집이기도 해용', 45, 8, 'GOOD', SYSTIMESTAMP);
