INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '분위기도 너무 힙하고! 브런치 먹으러 왔는데, 생각보다 식사메뉴가 다양해서 양껏 먹고왔어요 ㅋㅋㅋㅋㅋ 친구 생일날 맛있게 잘 먹고 갑니다!', 39, 0, 'GOOD', SYSTIMESTAMP);
