INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '분위기는 힙하고 깔끔한 브런치카페 맛집! 전체적으로 맛있었지만 특히나 스크램플토스트, 콘치즈프라이 최고였습니다☺️ 점심 시간 사람이 끊이지 않더라구요 홍대 들르신다면 추천드립니다 : ) 🅿️주차는 근처 노상 공영주차장 이용했어요', 30, 5, 'GOOD', SYSTIMESTAMP);
