INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대에서 디저트카페 찾다가 방문한 곳이에요 이색 메뉴 갈레트도 맛볼수 있고 생각보다 넓은매장에 힙한 인테리어로 되어있어요 식사하기도 커피커피마시기에 좋은 곳이에요!', 26, 8, 'GOOD', SYSTIMESTAMP);
