INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '오랜만에 나온 홍대나들이..신중하게 선택한 훌리건,아주 굿이었습니다~친절한서비스와 무엇보다 맛있는 음식들 중학샐 딸아이와도 함께였는데 자리간격도 넓고 조용한편이어서 더 좋았습니다~', 23, 7, 'GOOD', SYSTIMESTAMP);
