INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '지인들과 모임하러 예약 후 방문했어요! 여럿이 함께 모임하는데도 장소가 예쁘고 넓어서 좋았고, 메뉴를 여러가지 시키다보니 어려울 수 있었는데 메뉴 사진과 안내가 잘 되어있었고 직원분들 친절하셔서 좋았어요!', 41, 3, 'GOOD', SYSTIMESTAMP);
