INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '복숭아 갈레트의 복숭아가 향이 좋고 당도가 있어서 디저트로 너무 좋았어요! 복숭아 티도 향이 은은하고 가볍게 마시기 좋았고, 아이스크림 라떼도 맛있었어요! 카페 분위기도 좋아서 친구랑 즐겁게 이야기 하다가 갑니다! 또 올게요😍', 31, 2, 'GOOD', SYSTIMESTAMP);
