INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '주말에 예약없이 왔는데 10분 안되서 자리에 앉았구요, 핫플이라 그런지 외국인들이 정말 많더라구요! 카메라 든 분들도 많아서 다들 한번씩 사진도 찍어가는데 와보시면 누구나 카메라 꺼내들게됩니다ㅎㅎ 좋은 데이트장소로는 추천하는데 노래소리가 조금 커용', 6, 7, NULL, SYSTIMESTAMP);
