INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '진짜 진짜 진짜 친절한 직원분들이 계신 곳..😊 종종 올 때마다 마음이 충만해집니당 팩스어피치 단 맛 하나도 안 나는 복숭아향 차라 맛있어요! 올 때마다 기분 좋아지는 공간이에요 ''U''', 43, 4, 'GOOD', SYSTIMESTAMP);
