INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '홍대 브런치 맛집 완전 인정!! 스테이크 봄바 진짜 너무 맛있어요 ㅠㅠㅠ 아니 고기가 너무 부드러워서 입에서 살살 녹는데 어떻게 구우신건지 ㅜㅜ 바게트는 바삭하고 고기는 부드러워서 식감 미쳐버려요 ㅠㅠ 안에있는 소스랑 너무 잘어울림 제발 드세여 ㅠㅠ 토마토 아보카도 플레이트는 너무 신선 건강한 맛 ㅜㅜ 하나는 바질맛 하나는 블루베리 콩피 맛이라 다른맛 주신것도 너무 좋고 썬드라이토마토 듬뿍 얹어주셨는데 진짜 최고 ㅠㅠ 음료도 진짜 시킨 족족 맛있네여...ㄷㄷㄷ', 10, 0, 'GOOD', SYSTIMESTAMP);
