INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대 브런치 카페 훌리건 커피는 데이트하기 좋아요. 실내공간도 넓고 남녀화장실도 분리되어 있어 맘에 들어요. 애쉬라떼, 마카다미아 크림라떼는 이 곳에서만 맛볼 수 있는 음료에요. 미트볼 볼로네제 파스타와 스테이크봄바, 흑임자 크림 갈레트까지 먹고나니 배가 터질 것 같아요. 브런치가 맛있는 감각적인 카페 찾는 분께 추천해요!', 40, 8, 'GOOD', SYSTIMESTAMP);
