INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '친구가 지방에서 올라와서 어디를 같이 가야 좋은 기억을 줄까 하다가 찾은 브런치 맛집입니당!! 공간도 편해서 마음껏 이야기 할수있고 메뉴도 다양해서 좋아요~😄 홍대 브런치카페라면 여기 1등으로 떠요~ 다음에는 남자친구랑 올게요!!', 190, 30, 'GOOD', SYSTIMESTAMP);
