INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '브런치 즐기기 좋은 홍대 카페 입니다 식사부터 디저트 음료까지 한큐에 딱임 분위기도 좋고요 스테이크 붐바 부드럽고 넘 맛나용 미트볼 파스타는 예상한 그 맛이긴 하지만 역시 맛 좋습니당 커피도 적당한 바디감에 좋아요', 68, 15, 'GOOD', SYSTIMESTAMP);
