INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '커피, 쉐이크, 길티플레이트 브런치로 맛있게 먹고 갑니다~ 고기가 엄청 부드러워요! 위치가 메인거리 살짝 안쪽에 있는데 쾌적해요~', 33, 8, 'GOOD', SYSTIMESTAMP);
