INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '여기에 오신다면 스테이크 봄바를 진짜 꼭 먹어보셔야합니다 이거 안 먹어보면 그냥 훌리건을 안 온거라 하셔도 과언이 아닐 정도로... 저번에 이거 먹으러 이틀 연속 왔던 적도 있어요... 뢰전드 개맛잇음', 48, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '디자인도 너무 이쁘고 공간도 생각보다 넓고 너무 좋아요 처음에 카페도 가기로 해서 고민했는데 오길 너무 잘한들  브런치 카페 느낌이 강해요 ! 너무 좋습니당', 33, 4, 'GOOD', SYSTIMESTAMP);
