INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '넘 맛있어요 💛💛🥹🥹 플레이트도 넘 예뿌게 잘해주시고 당여니 맛도 끝내줘요.. 홍대에 이런 감성 브런치카페가 있다니!! 자주 올게요 ㅎㅎ', 67, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '친구랑 브런치먹으러 왔는데 너무 좋아요! 다 너무 맛있고  양도 푸짐해요 ㅎㅎ 평일런치 메뉴 정말 좋아요 다음에 또 와야겠어요 ㅎ', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '음식이 맛있고 가격도 합리적인거같아용!!! 리뷰이벤트로 주는 치즈그라탕?도 너무 맛있어요 오늘의 스프가 다 떨어져서 티라미수로 주셨는데 오히려 디저트까지 식사구성으로 좋았오용!!!', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '친구가 가고 싶다고 해서 방문~~~ 가격에 비해 맛은 흔히 아는 그저 그런 맛~~  딱히 맛있지도 맛없지도~~~ 한번 가봤으면... 되었음 ...', 51, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '훌리건 커피 재방문입니다. 예전에도 왔다가 늘 생각나는 식당 또 오네요 ㅎ.ㅎ 분위기 너무 좋고 음식도 맛있고 직원분들 친절하십니다 근데 시간대가 조금 늦었으면 자리 없었어요.. 역시 인기맛집!', 37, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '음악도 대화하기 좋은 음악에. 커피가 너무맛있어요!! 따뜻한 카페라떼가 텁텁하지않아요ㅜㅜ 아주조으다... 근데 메뉴가  좀 늦게나와여 ㅎㅎ', 2, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친절하게 안내해주시고 이야기해주세요! 사진도 잘 나오구 크림소스가 진짜 꾸덕하니 마싯고 토마토소스는 엄청 자극적이기보다 본연의 향과 맛이 잘 살아서 조화로워서 너무 마싯었어요! 그리고 콘치즈감튀는 꼭꼭 드세용 다음에 또 올께연', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '친구가 여기 가보재서 와본건데 진짜 너무 맛있게 먹고 가요 매장 분위기도 너무 좋고 음식도 맛있어요!! 재방문 의사 완전 이씀🌟😍😻❤️', 130, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '두명이서 먹고싶은 게 달라 각각 다른 런치세트로 먹었는데 진짜 가성비 미쳤습니다ㅠㅠ 양도 많고 이정도 가성비는 서울에 더 없을 거 같아요 너무 맛있고 특히 저 콘치즈 감자튀김이랑 샌드위치 최고입니당 다음번에 또 올게요 ~', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '점심 해결하러 왔는데 음식이 넘 예쁘고 맛있어요 카페 내부 분위기도 최고… 홀리건 기념 티셔츠랑 컵 구매할 수도 있어요 글고 음악 선곡이 맛깔나네요 ㅎ.ㅎ', 126, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '촌년 서울와서 홍대 놀러왔는데~~~처음온 훌리건커피!어제 저녁 폭풍검색 후 왔는데 정말 잘온것같아요~~~분위기가 일단 너무 좋은데요?? 맛도 당연히 쵝오!!!!!좋은시간 보내고갑니당~~~♡', 1, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), 'I’ve been here many times and the food is always so good! I love the music and the vibes here. I would always recommend this place 😊', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '🎠커피맛있는 홍대힙한카페 🗽그레놀라와 아이스크림 딸기 크레이프와 반죽?중간의 빵과 다함께먹어요 🌾얘기나누기좋고 커피 참 맛있음', 30, 4, 'GOOD', SYSTIMESTAMP);
