INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '분위기가 너무 좋아서 편안하게 즐겼습니당😊❤️ 주문했던 스크램블과 에그인헬도 다 맛있더라구용~! 사장님도 친절하시고 기회가 된다면 다음에 또 방문할 것 같습니다아~!', 56, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '평일 런치세트 주문하였습니다 (미트볼, 콘치즈, 스크램블 토스트, 자몽에이드) 리뷰 이벤트로 콘치즈 후라이 추가해서 먹었습니다 딸기 시즌메뉴로는 음료 변경이 안된다고 합니다 생각보다 양이 많고 파스타가 정말 맛있었습니다 나중에 또 온다면 파스타만 시켜먹을거같습니다', 82, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '일요일 낮 12:40쯤 왔고 15-20분쯤 기다려서 들어갔어요 ! 아보카도 샌드위치 너무 맛있고 스테이크봄바는 맛있는데 소스류가 적어서 살짝 뻑뻑해요 그리고 전체적으로 직원분들이 바쁜 느낌이예요 참고하세요 ~', 43, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '음식이 다양해서 오래걸릴 줄 알았는데 생각보다 빨리 나와서 배고팠는데 살았습니다ㅜㅠㅎㅎ 음료도 맛있고  음식도 맛있어요~! 카페에서 밥과 디저트 까지 해결! 뒤에 먹을 갈래트도 너무 기대되네용', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '매장 분위기가 넘 좋아요 커피 라떼 전부 맛있고 특히 고디바 밀크 맛있어요!!!! 갈레트도 달콤하고 맛있어서 다음에 또 방문할 것 같습니다 ♡', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '오늘 예랑이랑 데이트로 훌리건으로 점심 다녀왔어요☺️!인스타에서 보고 갔을 때 두판이 나오길래 2인분 시켰을때 두판은 나오지 않을까 살짜쿵 기대하고 갔는데..? 넘나 아쉽게두 그건 아니었다는…😂 그래도 무난하게 먹을만 했어용!!', 25, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '처음 방문해봤는데 주문할때 조금 어려웠지만 직원분이 너무 친절하셨습니다!  음식도 진짜 맛있고 양이 많아요 특히 이 블루베리 디저트가 진짜 존맛탱! 🫐 나중에 또 방문 하고싶어요 🍞🍟🍝 다먹고 나갈때 까지 친절하게 해주셔서 기분 좋았습니다 :) 세트메뉴 진짜 가성비 좋아요👍🏻', 99, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '가성비 진짜 대박... 이렇게 해서 2만원도 안넘는다는게 놀라워요 엄청 와보고싶던 곳인데 평일에 브런치 먹으러 방문했어요!! 메뉴 하나하나 다 맛있고 정성이 느껴져서 추천합니당 다음엔 다른 조합으로 먹으려구요 ㅎㅎ', 40, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '점심에 들러 커피랑 브런치 먹기 너무 좋아요 세트메뉴구성도 좋아서 맛있고 특히 커피가 맛있어서 좋네요~ 친구랑 즐겁게 먹고 시간 보내고 왔어여 잘먹고 갑니다', 42, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '오픈하자마자 갔는데 직원분이 바로 너무 친절하게 주문 받아주셨고 메뉴도 하나하나 정말 맛있었어요 특히 콘치즈 프라이는 사이드메뉴인데도 메인메뉴만큼 맛있었고 남자친구도 저도 너무 만족했습니다🥰', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '이 레스토랑의 분위기가 좋고 서비스도 친절했어요. 바질 파스타를 주문했는데, 소스가 진하고 면이 쫄깃해서 정말 맛있었어요. 음료도 맛있었고, 전체적으로 만족스러운 식사 경험이었어요!', 80, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '오랜만에 홍대왔다가 방문했습니다! 지하도 있고 1.5층 같은 곳도 있어서 생각보다 자리가 많아요! 분위기가 힙하고 음악도 좋고 맛있어보이는 음식도 많습니다:) 먹었던 모든 음식 다 맛있었어요!! 볼로네제는 짜지 않고 맵찔이인 저에게 약간 매콤하긴 했지만 그래도 매콤해서인지 정말 맛있었어요! 스테이크 봄바는 빵이 딱딱하지 않고 고기도 질기지 않아서 입천장 안까지고 편하게 먹을 수 았었어요~~ 같이 나온 감자튀김도 기름지지 않고 바삭바삭하니 지인짜 맛있더라구요ㅠㅠ 커피도 맛있고 후식으로 나온 갈레트도 싹싹 긁어먹을 정도로 푸짐하게 잘 먹었습니다!! 다음에 다른 메뉴들 또 먹으러 갈게요!! 홍대에 맛집 찾은거 처음인 것 같아요!', 49, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대 브런치 카페는 처음이에요 !! 분위기 음악 음식 다 좋아요 💥🎶 그런데,,, 음식 나오는 시간이 꽤 걸립니다 .. 주말 점심(13시) 기준 ! 참고하세용 ➿', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '오랜만에 홍대 나들이 겸 방문하게 되었습니다. 런치 콤보 먹고 싶어서 기대하며 방문 하였습니다. 기대한 만큼 메뉴가 나오자마자 감탄사가 먼저 나왔습니다. 비쥬얼이면 비쥬얼 맛이면 맛 정말 이 가격으로 홍대에서 맛있는 브런치를 즐길 수 있다는 것에 너무 행복합니다. 재 방문 의사 100프로 입니다. 홍대 오면 종종 방문 할 거 같습니다 ㅎㅎ', 22, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '파스타만 먹으려고 왔는데 주문 대기하면서 커피 내리는 모습보고 궁금해서 커피도 시켜봤는데 커피도 파스타도 다 맛있네요 🥰 잘 먹을게요', 86, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아~~~~~~~~디져트 미쳤음?! 또 갈래~~!~!~! 디저트가 살짝 가격대가 있지만, 한 플레이트에 나오는 모든 요소가 다 너무 잘 어울리고 다 맛있다. 빵도 독특하고 달콤상콤시언~부드럽~다 있잖씀. 음료도 맛있고. 좌석도 갠츈. 야외석도 있는거 같음. 일요일인데도 2팀?정도 밖에 없었음. 무튼, 가벼운 끼니도 판매하고있어서 브런치 먹으러 가기도 좋을듯. 디저트 맛있어요~!~!~!', 8, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대 데이트 점심겸 카페로 온 훌리건 커피입니다! 오늘 처음와서 런치콤보 2인 먹었어요~ 음식이 다 너무 맛있습니다! 음식들이 다 완전 맛있게 생겼는데, 그것보다도 훨씬 맛있었어요!!! 커피도 너무 좋았고, 다음에또 다른메뉴 먹으러 올거같습니다~~', 6, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '포르투갈 친구랑 같이 왔는데 아보카도랑 드라이토마토가 잘 어우러져서 맛있다고 하네요 ㅎㅎ 블루베리 갈레트도 맛있어요 조금 달긴 한데 왠지 단게 먹고싶은날 추천해요! 솔직히 말하면 리뷰 작성해야 콘치즈 받을수 있다고 해서 한건데 블루베리 갈레트 진짜 너무 심하게 달고, 아보카도도 그냥 쏘쏘 전반적으로 가격에 비해서는 좀 부실합니다', 20, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '친구랑 오랜만에 애들 놔두고 둘이서 오붓하게 브런치라니🙈🙈 너무 행복한데 음식까지 맛있으니 더 행복하네요 복숭아아이스티가 제가 아는 복숭아티가 아니예요 너무 달콤하고 맛있어요 무화과 갈레트는 시즌메뉴니까 꼭 드시고 스테이크봄바도 넘 맛있으니 꼭 드세요 두번 드세요 ㅋㅋㅋ완전 추천합니다😋😋😋', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대브런치맛집으로 유명해서 놀러왔는데 건강한 토마토아보카도 플레이트와 콘치즈가 올라간 감튀 조합이 넘 좋았어요🩷🩷 분위기도 좋고 혼브런치 하기 좋아 재방문의사있습니다 ㅎㅎ', 37, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '에그인헬 다른 곳은 양이 너무 많아서 혼자 먹을 때 시키기 고민이 많았는데 이곳은 양도 적당하고 혼지 먹을 수 있어서 너무 좋앗다는 ㅎㅎ', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대에서 가성비 좋은 브런치 먹기 좋아요❗️ 특히 많이 못 먹어서 다양한 음식 못 즐기는 분들은 다양한 메뉴를 적당한 양으로 즐길 수 있어요 음료도 커피 말고 주스로 추가금 없이 변경 가능해서 굿‼️ 그리고 리뷰 이벤트 참여해서 감자튀김 꼭 업그레이드하세요 맛있어요', 35, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '일단 아이스크림이 파스퇴르인지 엄청 고소하고 담백한 맛이나고 파스타는 먹늠 맛이 아주 좋습니다 스테이크는 못 찍었는데 진짜 맛있어요 부드럽고 데이트하기에 아주 좋을 거 같습니다 추천해여', 39, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '매장구조가 되게 특이했던 브런치 카페. 아보카도도 신선하고 특히 스테이크 붐바가 정말 맛있었습니다. 같이 나오는 소스도 고소하고 좋았어요! 다만 음악소리가 너무 커서 귀가 좀 아프고 편하게 대화하긴 힘들었습니다ㅠ', 33, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '브런치가 맛있어보여서 방문했었는데요 !!! 볼로네제 파스타, 스테이크 봄바, 아메리카노 두잔을 시켜봤는데 볼로네제 파스타의 미트볼도 작지 않고 정말 맛있게 잘 먹었고 스테이크 봄바도 빵이 구워져서 나와서 그 안에 스테이크랑 같이 먹었을때 조합이 말해뭐해.. 너무 맛있게 잘 먹었습니다! 아메리카노도 산미가 없어서 브런치랑 먹었을때 더 잘 어울렸던것 같아요~!', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '자극적이고 맛있어요 아보카도 선호하지 좋아하는데도 바질, 블루베리 스프레드랑 정말 조화로워서 맛있게 먹었어요 미트볼 볼로네제는 딱 아는 맛있는 맛이에요 소스 듬뿍듬뿍 찍어서 드세요!', 33, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '친구랑 수능 끝나구 기분전환하러 왔어요 음악이 너무 좋고ㅠ 대기 없이 바로 입장해서 알차게 시간 보냈어용 아보카도 진짜 맛있어요ㅠ.ㅠ', 66, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '갈레트 처음먹어봤는데 너무 맛있어요~~! 아이스크림도 진하고 블루베리크림도 맛있습니당🫶 마카다미아 크림 라떼도 강추에욥🔥 콘치즈 프라이 알림받기하고 받았는데 크고 양도 많고 넘 맛있어여🥰 직원분들도 다 친절하시고 매장이 시원하고 커서 좋았어요💛', 7, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '맛집 리스트에 저장했던 곳인데, 친구랑 드디어 다녀왔네요~ 매뉴구성도 좋은데 가격까지 착하니 말모! 브런치를 편하게 즐길 수 있는 곳이에요~', 17, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '런치 세트 메뉴 구성도 내부 인테리어 컨셉도 독특한 ‘훌리건 커피’ 평일에만 가능한 런치 콤보 메뉴가 있고 - 미트볼 볼로네제 파스타, 아보카도 토스트, 후렌치후라이, 스프랑 음료로 구성으로 주문함! 다른 메뉴들은 막 엄청 맛있거나 특색이 있진 않았는데 슬라이스한 복숭아가 통째로 들어있는 괴산 피치스 음료는 아주 맛있었음! 내부 공간이 되게 힙한 독특한 컨셉이라 한 번 와볼만한 듯! 주차공간은 없음 ㅠ', 49, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '연남동까지 가긴 싫고 홍대 근처로 카페 찾아보다가 왔는데 무슨일이죠???? 여기 카페 인테리어도 기깔나고 맛도 가성비도 끝장 납니다👍👍👍홍대카페추천이용!!', 305, 88, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '1인 14900원 아름다운 곳이에요!!‘ 합리적인데 맛도 있어요 ㅠㅠㅠㅠ 분위기도 음악도 아주 만족스럽습니다!!! 파스타 네가지 다 맛있어요 ㅠㅠㅠㅠ 아무거나 시커도 성공입니다!!', 50, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '맛있는 식사에  좋은 분위기, 거기에 근사한 음악에 능숙한 직원들과 안정적인 시스템까지... 주말이라도 12시 전에 방문했기에 둘이지만 여유로운 자리에 앉을수 있었고 3인 세트메뉴에 욕심껏 추가메뉴까지...블로그에서 본 맛있게 생긴메뉴들은 카테고리별로 거의 다 주문했음.  어느새 길게 줄이 늘어섬. 아무래도 세트조합을 일일이 선택해서 구성해야하는데 카운터에서 태블릿으로 하다보니 한팀만 선택에 시간 걸리면 바로 뒤로 줄이 길어져 압박감에 더 쩔쩔매면서 오래걸리는악순환이있다. 포스기던 테이블 주문이던 요즘 트랜드를 생각해 볼 일이다.  조금 오래걸려 랜덤으로 나오는 음식은 하나하나 맛있었고 플레이팅도  예뻤으며 음료도 찐하고 맛있었다. 사이드도 양이 많아서 메인 같았다. 단품 완성도가 매우 좋았다.', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대에서 만오천원도 안되는 금액에 메뉴3개 커피까지 구성이라니 너무 알차잖아요. 메뉴 나올때부터 냄새도 너무 좋고 매장도 쾌적해서 잘 이용했습니당!', 61, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '스크램블이 먹고 싶어서 찾아왔는데 모든 메뉴가 기대 이상으로 너무 맛있었어요! 수제 아이스티인 괴산 피치스 꼭 드셔보시구, 스크램블이랑 아보카도 시푸드 봄바도 꼭 먹어보시길...! 요새 시즈널로는 복숭아 갈레트인데 달달하고 너무 맛나요 😋😋 재방문 의사 100000000%', 79, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '밥 먹기 애매해서 온 브런치 카페 외관이 굉장히 세련된 느낌이라 여기가 맞나? 했는데 맞았어요! 엄청 트렌디하게 생겨서 사진 찍을 맛 나요ㅠㅠ 음식도 눈으로 먹고 입으로 먹고 장난아니었네요 기본적으로 소품, 분위기가 너무 좋아서 눈으로 보고 입도 즐거워서 좋았습니다!', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '평일 브런치 세트 구성이 좋다고 해서 오픈런으로 방문했습니다! 아보카도 오픈 샌드위치는 맛의 조화가 좋았고 아보카도가 넉넉해서 좋았어요. 파스타는 미트볼 볼로네제로 선택했는데 소스와 면의 조화가 좋았고 미트볼이 커서 배가 불러요 ㅎ 감자튀김은 옥수수 크림 치즈(?) 추가했는데 옥수수 맛이 진해서 파스타와 단짠의 조화를 이루었습니다. 스테이크 봄바 고기는 부드러웠고 바게트 빵도 맛있네요. 디저트로는 복숭아 갈레트를 먹었는데 여러가지 식감과 상큼 달콤 새콤 약간의 짭짤함이 어우러졌어요. 양도 많아서 배부르게 먹고 왔습니다 :)', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '엄마랑 나들이로 브런치먹으러왓어요! 가게가 반지하랑 지상이랑 반지상?처럼 넓어서 대기 아주잠깐하고 들어왔습니다 ㅎㅎ 메뉴가 네이버메뉴에잇는거말고도 엄청많아요! 직원분들도 친절하시고 매장분위기도 좋아서 엄마도 만족하셨어요👍3인세트로 식사메뉴3개+디저티메뉴1개에 음료3잔으로 73000정도라 가성비도조아요 ㅎㅎ', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '주말 오픈런햇는데 역시나 사람많앗지만 붐비지 않앗고 음식은 역시나 훌륭 주문한 사람들 얼굴 기억하고 테이블에 갖다주시는 직원들도 너무 쏘 카인드!!! 평일엔 가성비가 좋으나 주말엔 또 그렇게 싸진 않아요 그래도 음악과 음식을 여유롭게 즐기고 싶다면 저는 계속 올듯여 ㅋㅋㅋ', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '힙한 분위기의 홍대 카페인데 커피가 맛있어요! 스페셜티 원두라 그런가 깔끔고소해서 맛있었어요😍 그리고 갈레트 위에 올라간 우유 아이스크림이 아주 찐해서 맛있었어요', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '괴산 피치스는 뭔가 복숭아청?으로 한것처럼 적당히 달고 고급지게 맛있었고 스테이크 봄바랑 피치 갈레트 다 너무 맛있었어요!! 다음에 또 방문할게용', 31, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '길티플레이트랑 고르곤졸라 크림 파스타 둘다 너무 맛있어요!! 크림 파스타가 정말 맛있었는데, 양이 일단 좀 적어요… 그리거 수저가 없어서 크림 팍팍 떠먹고 싶은데 못해서 아쉬웠어요ㅋㅋㅠ 음식은 주문하면 테이블로 가져다 주시고, 반납은 직접 가져다 드리면 됩니다. 내부가 넓게 느껴지고 좌석이 뭔가 많은것같은데 사람이 다들 앉아있어서 사람 많은 시간대에 오면 웨이팅 하셔야 할것같아요.', 44, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '파스타랑 아보카도? 먹었는데 파스타가 진짜 너무너무 맛있었어요!!!! 🥹 음악도 좋고 대화하면서 먹기 너무 좋습니다 ㅎㅎ 음식 플레이트가 너무 예뻐요🩷', 44, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '오랜만에 만나는 친구들에게 맛있는걸 대접하고 싶어서 방문했습니다😎 훌리건 브런치 메뉴는 진짜 하나하나 다 맛있어서 시키지 못한 다른 메뉴도 궁금할 정도예요. 사진엔 없지만 쉬림프 파스타도 새우가 오버쿡 되지않고 탱글하니 딱 좋게 익어서 친구들이 깜짝 놀랐어요. 이렇게 제대로 조리하는데 첨본다고🤣🤣🤣 브런치 후에 갈레트도 달달하니 넘 좋았고, 음료들도 너무너무 맛있었어요! 특히 따뜻한 라떼파인 친구에게 인정받은 훌리건 라떼!! 진짜 디들 라떼 따뜻한 걸로 드셔보세요. 츄라이츄라이😘', 18, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '헐 존맛이에용 간도 딱맞고 우와..... 우와.... 존맛 다음에 기회되면 런치세트 먹어보고싶어요 고르곤졸라는 꾸덕하고 우유향이 많이 나서 좋았고 에그인헬은 처음 먹어보는 메뉴 였는데 살짝 매콤해 두가지 조합이 좋았습니당 콘치즈포테이토.. 진짜 베스트...!!! 그리고 산미가 강하지 않고 진한 커피맛 그리고 복숭아 그 잡채인 복숭아 에이드! 무엇하나 빠지지 않는 맛집 ㅠㅠ', 77, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '메뉴가 다양해서 좋아요!!! 파스타 안에 새우도 탱글탱들 맛있고 튀김도 바삭바삭 맛있습니다! 스테이크 굽기도 적당라고 맛나오!!', 53, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '저는 브런치를 가끔 먹고싶은데 남자친구가 입맛 흥선대원군입니당. 근데 처음으로 “웩-(대충 맘에 안든다는 표현인듯)” 없이 먹른 브런치 에용 ㅋㅋㅋㅋ 미트볼 볼로네제 = 흥선대원군을 만족시켰따!! ㅠㅠ 넘 추천하는 브런치 집에용! 꼭 먹어보세용 생각보다 양 많아서 식사할 생각 아니라면 둘이서 음료 하나에 메뉴 하나도 괜찮을 거 같애요. 참참, 감자 모시기도 참 맛납니다! 꼭 드셔보세용! 담엔 다른 메뉴도 먹으러올게요! 전 바 자리에서 먹엇는데, 바자리도 좋았어서 추천합니다.', 8, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대에서 맛있는 브런치가 먹고싶어 찾아봤어요. 인테리어도 힙하고 외국인 손님들도 많네요. 파스타를 시킬까하다가 에그인헬을 시켜봤는데 정말 베스트 초이스였네요~ 스테이크도 맛있었고 곁들여나온 소스맛이 좀 특이했어요. 치즈감자후라이도 너무 맛있더라구요. 양이 많아 보이진 않았는데 생각보다 되게 배불렀어요~', 70, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '예전부터 가고 싶었던 곳이었는데 드디어 방문했어요! 평일 점심이라 웨이팅 없이 들어왔습니다! 런치콤보로 먹으면 종류를 다양하게 먹을 수 있어서 너무 좋은 것 같아요!! 콘치즈 프라이가 진짜 맛있었고 고르곤졸라 크림 파스타도 맛있었어요!! 친구들이랑 다음에 또 오고 싶어요☺️☺️', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대의 브런치 카페 중 음식 구성이 다양하고, 플레이팅과 맛이 뛰어난 카페에요😊😊 리뷰 이벤트 포테이토가 없어도 메뉴 두개로 남 녀 둘이서 배부름 아점 이였습니다💕💕 담백한 스크램블브레드와 토마토베이스의 미트볼로제가 짭짤하니 궁합이 좋아요😗😚😗😚', 16, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '이것저것 다 먹고싶은 욕심쟁이들을 위한 가성비 맛집 훌리건. 샌드위치, 파스타, 사이드에 아메리카노 까지 풀코스로 먹어도 만오천원 내면 백원을 거슬러주네요. 오픈 초기보다 더  맛있어진 건 안비밀. 평일에도 점심시간에는 만석/웨이팅이 있을 수 있으니 ''나는 오늘 홍대에서 맛있는 브런치를 꼭 먹을것이다!'' 하는 분들은 오픈런을 추천합니다. 매일 11:00-21:00 런치 콤보 ₩14,900 (평일)', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '평일에 시간이나서 브런치먹으러왔는데 런치눈 마감이라 아쉽게 못먹었지만 올데이메뉴가 있어서 맛잇게먹었어요😝😝홍대입구역이랑 가까워서 너무 좋고 인테리어 너무 이뻐여😎😎', 48, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '토마토 아보카도 플레이트와 블루베리 갈레트 주문했는데 너무 맛있어요. 토마토 아보카도 플레이트의검정색 소스는 블루베리인데 조합이 👍 커피는 원샷 인데, 원두 자체는 좀 강한편이데 쓴맛은 아니에요. 아이스가 더 맛있을거 같고, 갈레트는 크레페에 크림 얹어 주는데 너무 맛나요. 매장은 작은 편인데 음악 힙하고 비 안오는날 다시 오고 싶어요. 분위기 굿!', 24, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '커피가 고소하게 맛있고 음식도 맛있어요! 둘이서 세트 하나 단품 하나 시켰는데 양도 많았어요🩷🤍💛🧡 쉬림프 로제 파스타에 새우가 엄청 탱글탱글해요ㅎㅎㅎ 맛집이라서 그런지 11시반에 갔는데 자리 별로 없었어요ㅠㅠㅠㅠ 주말이면 웨이팅 해야할지도..!!', 22, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '남편생일을 맞이해서 특별한 맛집을 찾아오게되었어요 메뉴 하나하나에 정성과 사장님의 연구가 묻어있습니다 메뉴도 커피도 맛있었습니다 장소도 이색적이고 특별하네요👍', 79, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '메인 시간에는 웨이팅이 있는 가게입니다. 벙커형 반층 구조가 매력적이고 외국인 관광객도 많이 오더라고요. 망고관련 다양한 메뉴도 많고 세트로 먹으면 3~4가지 음식을 가성비 있게 맛 볼 수 있어요. 데이트 코스로 강추요', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '런치콤보로 가성비좋고 맛있는 브런치 먹었습니다. 구석진곳에 있어서 택시타고 내려서 좀 찾아헤멨네요~ 사람이많아서 지하에서 먹었는데 지하는뷰가없고 테이블이 좁아서 좀답답한 느낌입니다.', 27, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '두번째 방문이에요! 일단 스테이크 봄바는 꼭 추천드려요! 스테이크가 질기지 않고 부드럽고 알싸한 소스 맛이 질리지않고 먹을 수 있어요😋 맛을 고려했을 때 커피랑 식사메뉴 홍대에서 가성비가 정말 좋습니다.', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '너무 친절하셨습니다! 지인을 기다리는데 늦게 와서 음식이 식을 때 쯤 다시 데워주셨어요!ㅠㅠ감동 메뉴나 구성이 혼밥하기에도 좋았고! 혼자 앉는 테이블도 있어서 혼자와서 즐기기 좋아보였습니다! 파스타, 토스트, 갈레트 다 맛있었어요! ◡̈ෆ', 78, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대에 이런 곳이 있는지 처음 알았어요ㅜ 인스타에 올라오는 사진들 보고 기대하면서 왔는데 인테리어도 예쁘고 음식도 맛있었어요 !! 대.만.족💖 남자친구도  맛있다며 만족했고, 직원분들도 친절해서 너무 좋았어요🥺❤️ 다음에 또 오고 싶어요 !!', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '오랸만에 홍대 와서 친구들이랑 브런치가게 찾다가 오게되었어요😀 특히 스크램블플레이트가 맛있었습니다. 부들부들한 스크램블이 좋았습니다. 담음에 또 방문할거 같아요!', 41, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대쪽으로 오랜만에 왔는데 브런치 찾다가 음식이 맛있어보여서 방문했어요! 실제로 너무 맛있었습니다~ 그리고 비가 와서 실내를 이용했는데 실내도 인테리어 이쁘고 분위기 좋았습니다! 다음에는 비 안 오는 날에 밖에서!', 46, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '별스타에서 사진보고 지도에 저장해놨다가 연차낸 평일날 드디어 방문했어요😚 런치 콤보는 평일만 가능해서 너무 궁금했는데 비주얼 진짜 장난 아닙니다🫶 같이 나오는 커피는 산미가 강서 라떼로 마시면 더 맛있을꺼같았어요💛 아보카도 샌드위치는 은근 매콤하면서 아보카도 한가득이었어서 아보카도 러버면 꼭주문하세요🥑🥑', 379, 85, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '런치 2인메뉴 시켰는데 구성이 정말 좋더라구요! 그리고 피치 에이드 정말 취향입니다! 아쉬운건 월요일인데도 사람이 정말 많아요!! 메뉴가 한번에 다양하게 나와서 오래걸리는 것 같아요! 될 수 있으면 오픈런 하시는게 좋아보입니다! 맛있어용! 다음에 또 올것같아용', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '3인 세트 시켰는데 후식진짜 존맛.. 다른음식도 다 맛있어요 조금 늦게나오긴하지만 음식먹으니 사르르 녹음 다음에 홍대올일있으면 또 방문하려구요', 71, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '인스타 보고 오게 됐어요!! 파스타,스테이크 붐바, 시즈널 갈레트, 콘치즈 프라이까지 주문했는데 4개 다 성공했습니다ㅎㅎ 가격은 좀 나갔지만..! 그만한 가치가 있습니당☺️', 2, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '점심시간에 사람이 많네요 런치콤보 메뉴 구성도 좋고 가격도 좋아요! 무엇보다 직원분 바쁜데 엄청 친절하고 서빙도 착착 잘해주십니다. 에그인헬 너무 맛있어서 빵추가까지 해서 싹싹 긁어먹었습니다.', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '가성비 너무 좋은 브런치! 1인 세트메뉴 구성 맛 모두 최고입니다 그리고 직원분들 엄청 친절하고 커피도 맛있어요~~세트메뉴는 인원수 주문이라고하니 참고해주세용~:) 2인세트도 있어요 가성비 굿굿', 64, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '진짜 너~무 맛있고, 음식도 생각보다 빨리 나와요! 브런치로 추천합니당 음식은 진짜 다 맛있어서 어떤 걸 시키든 만족하실 거에여! 재방문 의사 200% 입니다👍🏻', 18, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '가성비 브런치 메뉴로 유명한 홍대 카페 훌리건 나는 디저트를 부시고왔다👍 흑임자 갈레트랑 망고사고라니 ❤️ 진심 맛있게 먹고 온 카페였다 다음엔 꼭 브런치도 먹어봐야징', 70, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '11시 문 여는 시간 맞춰 갔어요. 런치 세트 14,900원 구성 좋네요 🫶 아보카도 토스트 아보카도 좋아하신다면 꼭 드셔보세요 💚💚💚', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '갈레트가 정확히 뭔지 모르고 방문했으나 한 입 먹자마자 완벽 이해,, 크레페 보따리 안에 작게 컷팅한 케이크빵이 크림과 섞여있는? 그런 디저트에요. 일단 흑임자 크림이랑 아이스크림이 너무너무 맛있고.. 크레페 반죽이 쫄깃쫄깃 중독성있어요🥹 또 갈 거에요 -!!', 41, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대 가면 무조건 홀리건 커피!! 진짜 맘에 드는 카페 찾았네요!! 인테리어 진짜 힙하고, 공간 자체도 구석구석 참 멋지게 꾸며져 있네요. 직원분들도 넘 친절하고요! 미트볼 파스타와 딸기 갈레트 시켰는데.. 둘다 맛났어요. 원래도 리가토니면 좋아하는데 리가토니면 딱 알맞게 삶아져 있구요. 소스도 시판 아닌 것 같아요. 직접 만드셨다는 미트볼 큼직한데 씹는 맛도 있고, 감칠맛도 넘치네요~ 자, 여러분들!! 훌리건 커피 가시면 무조건 갈레트 시키세요! 저 갈레트가 이렇게 맛난 건지 첨 알았어요. 캬라멜 향도 은은히 나고!! 맛있게 구워진 크레이프에 그래놀라, 퐁신한 큐브 브레드 들어가 있는데.. 배가 하나도 안고프고 평소 단 것도 싫어하는데 바닥 긁고 나왔어요. 커피도 밸런스 좋아서 갈레트와 딱 어울려요', 122, 22, 'GOOD', SYSTIMESTAMP);
