INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '남자친구랑 브런치 먹으러 비를 뚫고 다녀왔어요 🌧️ 비주얼도 예쁘고 맛도 짱,,, 가성비도 좋아용 ◡̈ 다음엔 디저트 먹으러 와야지〰️〰️', 11, 3, 'GOOD', SYSTIMESTAMP);
