INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '인테리어도 감각적이고 음식도 정갈하구 맛나요~~~꼭 브런치 아니더라도 그냥 작업하러 오기에도 좋은것 같습니다! 그리고 귀여운 굿즈들도 팔아용 :)', 42, 0, 'GOOD', SYSTIMESTAMP);
