INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '너무 먹어보고 싶었던 흑임자 갈레트 먹으러 왔어요✨ 매장 인테리어 너무 힙하고 곳곳에 사진찍기 너무 좋은 자리도 있고 분위기와 맛이 다 있는 곳이였어요☺️ 갈레트는 기대했던대로 아이스크림이랑 떡이랑 과자 등 다양한 재료가 있어서 식감도 좋고 당충전 하기 딱 좋은 메뉴 💕 음료도 넘 달다구리 하고 맛있어요 !!', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '트렌디하고 힙한 카페 훌리건 커피 홍대입구에서는 다양한 카페와 브런치 등 파는 곳이 많아 각자의 개성이 없으면 살아남지 못하는 치열한 공간! 그런 공간에서 훌리건 커피만의 개성으로 멋있게 만들고 있고 기본적으로 브런치 비주얼이 좋으며 제가 먹은 스테이크 봄바 단백질이 가득해 포만감 상당해 주고 맛이 정말 좋았던 브런치 카페였습니다. - 자세한 내용은 육식하마 블로그 참고 -', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '엄청 오고 싶었는데 드디어 왔어요 !!! 갈레트 맛 별로 다 먹어 보고 싶어여 .. 무화과 시즌이라 먹어 봤는데 신기하고 맛있었어요 인테리어가 특색 있어서 새로워요! 직접 가져다 주시고 친절하세요 ~~', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '매장이 넓은데다가 인테리어가 아주 힙하고 사장님도 너무 친절하세요 브런치랑 디저트 메뉴까지 다양하게 있어서 다음에는 디저트도 먹어보고싶네용 스크램블 플레이트와 스테이크붐바 먹었는데 둘 다 너무 맛있었습니다 ㅎㅎ 배도 꽤 차는 편이었고 넘 맘에 들었어요', 3, 10, 'GOOD', SYSTIMESTAMP);
