INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '인테리어 소품 하나 하나 구경하는 재미는 덤이에요 감각적이고 멋진 공간! 커피맛도 훌륭합니다 갈레트도 꼭 시켜 드시길 바라요^^', 29, 5, 'GOOD', SYSTIMESTAMP);
