INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '엄마랑 오늘 간 곳인데, 음료도 너무 달지 않아 너무 맛있게 드셨대용! 저도 마카다미아 크림 라떼 너무 밋있어서 홀짝홀짝 다 마셨구욤! 블루베리 갈레트도 굉장히 맛있었어요! 크레페 사이에 빵이랑 블루베리 크림이 적당하게 들어가서 너무 맛있게 먹고왔습니다 :) 훌리건 크루의 모토대로 눈, 입 그리고 귀! 오감으로 느낄 수 있는 곳이었어요 !', 63, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '브런치 먹으러 갔는데 완전 반해버림!! 스테이크 봄바 넘 맛있고 오믈렛도 짱이예요! 재료를 좋은것만 쓴다는 느낌이 확확 와닿았어요 ㅎㅎ 같이 먹은 에이드도 과일잔뜩 올라가있고 퀄리티 있어서 좋아요 ㅎㅎ 노래도 감각적이고 힙해서 힙한 카페 가고싶은 분들께 추천합니다🙋‍♀️', 102, 25, 'GOOD', SYSTIMESTAMP);
