INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '훌리건 커피에서 아보카도플레이트 먹었는데 완전 취향저격이에요!! 부드러운 아보카도와 토마토 으깬것이 섞인 샌드위치는 한끼 식사로  충분해요 아이스크림라떼도 쌉싸름하고 달콤해요. 언니는 고디바밀크를 마셨는데 완전 맛있다고 좋아해요. 완전 재방문각입니다 . 다시 오고싶은 카페 1위로 등극했어요. 홍대입구역카페로ㅡ 완전 추천드려요.', 27, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '힙한 브런치 카페!! -남자 둘이 와서 먹어도 남길만큼 양도 먹을만 했어요. 아메리카노 기준 연하지 않아서 좋았습니다. 넓은 만큼  사람들이 많음에도 나름 프라이빗했다! 맛있어요! -스테이크 온도가 미지근 했고 사람이 많아 음식 나오는 시간이 좀 걸렸습니다. 그래서 사진 찍으려면 아이스크림은 안 시키는 편이 나을 거 같아요 (다만 좀 더워서 아쉬웠지만, 매장이 넓어 에어컨이 원활하지 않았다.)', 8, 9, NULL, SYSTIMESTAMP);
