INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대 골목에 숨어져있는 완전 힙한분위기의 카페입니다! 홍대디저트 맛집으로 소문난 대는 다 이유가 있는 것 같아요. 직원분들도 친절하시고 브런치메뉴, 갈레트메뉴 다 너무 맛있어요💕 분위기도 최고에요!', 4, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '매장이 생각보다 작긴 한데 그래도 공간 활용이 잘 되어있어서 은근 자리가 꽤 있어요! 인테리어도 예쁘고 청결해서 좋네용 ㅎㅎ 스테이크 봄바도 너무 맛있어요!! 다음에 또 오고 싶은 곳이에요 ( ⸝⸝•ᴗ•⸝⸝ )੭⁾⁾', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '오랜만에 친구랑 만났는데, 매장 분위기도 힙하고 깔끔해요. 어중간한 시간에 왔는데, 브런치겸 음료도 함께 먹을 수 있어서 더 좋은거같아요. 음식도 맛있고 커피도 맛있어요! ^_^*', 71, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '매장 분위기가 엄청 힙하고 커피도 특이하고 색다른 커피로 너무 맛있습니다 개인적으로 애쉬라떼 커피 색감도 예쁘고 쌉싸름하면서 달달한 콩맛 느낌?? 애쉬라떼 완전 딱 제취향이네요~ 흑임자 갈레트 디저트도 비주얼이 일단 너무 예쁘고 흑임자의 고소함과 달달함에 너무 잘 어울리는 아이스크림 크레페! 바삭한 크런치한 과자까지 흑임자 크림과 찍어먹는 맛이 있네요~ 마카다미아 크림라떼도 고소한 아인슈페너 맛이네요:) 감성사진 찍기에도 좋은 홍대 커피맛집이네요', 21, 4, 'GOOD', SYSTIMESTAMP);
