INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '힙한 분위기의 브런치카페였어요 콘치봄바 달달한 크림소스와 옥수수가 잘 어울리고 트리플베리에이드가 엄청 상큼해서 조합이 좋았습니다 양도 푸짐해서 한끼식사로도 충분해여 재방문의사 있습니다:)', 44, 9, 'GOOD', SYSTIMESTAMP);
