INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대 골목에 위치해있어요 사람 많은 쪽 바로 앞이 아니라서 조용해서 좋고 완전 힙한 분위기에 디저트도 음료도 다 맛있어요 ! 사진은 마카다미아라떼, 복숭아에이드, 마카다미아 갈레트고 셋 다 추천합니다 😎', 35, 4, 'GOOD', SYSTIMESTAMP);
