INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대에서 숨은 맛집 발견… 재료가 넘 신선하고 아낌없이 팍팍 넣어주시구 아보카도퀸들은 여기로 당장 달려가세요 분위기도 미쳤어욤 커피도 맛있고 사장님도 멋있고 친절하세요! 강추!!!', 0, 7, 'GOOD', SYSTIMESTAMP);
