INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '브런치 맛집 홍대 카페 찾다가 훌리건 커피를 발견해서 길티 플레이트와 트러플베리 에이드를 먹었어요! 한주 받았던 업무 스트레스가 싹 날아가는 맛~~ 분위기도 너무 좋아서 퇴근하고 자주 갈 거 같아요!!! 다음에는 디저트도 혼내주러 갈예정입니다!', 44, 8, 'GOOD', SYSTIMESTAMP);
