INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '쾌적하고 깔끔한 카페에요 음료 랑 메뉴 질문해도 친절히 알랴주시고 홍대 주변에서 구경하고 놀다가 커피마시고 시플때 오면 조을거가타요🤍', 37, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '골목에 이런 브런치집이 있는 줄 몰랐어요! 맛있었고 특히 같이 간 친구들 모두 씨푸드아보카도봄바가 제일 맛있다고 했어요😀 추천추천', 40, 8, 'GOOD', SYSTIMESTAMP);
