INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '진짜 존맛탱.. 사실 카페 음악이 좀 커서 조용히 즐기실 분들은 좀 힘드실 수 있지만 그거 말고는 모든게 완벽합니당 맛도 있고 커피도 맛있고 음료도 굿~~ 진짜 존맛탱입니다.. 또 오고싶어요', 80, 13, 'GOOD', SYSTIMESTAMP);
