INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '힙한 분위기도 좋고, 커피에 봄바 조합이 정말 좋았어요! 특히 크림 라떼의 크림이 쫀쫀했는데 에스프레소랑 정말 잘 어울렸답니다(•ө•)♡ 홍대 카페로 추천드려요🫧💖', 26, 10, 'GOOD', SYSTIMESTAMP);
