INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '가게 인테리어가 너무 제스타일이에여ㅠㅠㅠㅠ 찾기 어렵지도않고 역에서 가까운 편이라 자주 올꺼같아요!! 음식도 맛있고 음료도 제가 좋아하는 원두 맛입니당 완전 추천드려요!❤️', 61, 12, 'GOOD', SYSTIMESTAMP);
