INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '커피뿐만 아니라 브런치 메뉴도 다양해서 약속장소로 손색이 없어요~커리치즈봄바 블루베리갈레트 맛깔스럽고 전반적으로 맛이 조화로워요^^ 분위기도 좋고 다음번에 다른 메뉴 먹으러 또 가고 싶네요!', 37, 0, 'GOOD', SYSTIMESTAMP);
