INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '리뷰 잘 안쓰는데 올때마다 너무 친절하시고 브런치 진짜 퀄리티 좋고 맛있음. 새로 만드신 컵도 이뻐서 흰색 검정색 하나씩 삼😉', 21, 0, 'GOOD', SYSTIMESTAMP);
