INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '매장이 생각보다 넓고 예뻐요 ㅎㅎ 앉아서 이야기 하기도 편하고 사장님 직원님 모두 친철하세요! 친구들이랑 방문했는데 재밌고 좋았습니다 . 디저트도 맛있었어요! 원두는 약간 산미가 있어서 산미 좋아하지 않은 분이라면 조금 시다고 생각하실 수 있을 것 같아요', 42, 0, 'GOOD', SYSTIMESTAMP);
