INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '디저트 별로 안좋아하는데 너무 맛있어요... 새콤달콤 진짜 블루베리 크림치즈 먹고 눈물흘릴뻔 오늘 또왔어요... 최고에요 서비스도 체고 깔끔하고 예뻐요!!!💜💜', 12, 9, 'GOOD', SYSTIMESTAMP);
