INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '짱 맛있어요~!! 안쪽에 있어서 좋고 매장이 넓진 않은데 공간이 이뻐요! 자리도 은근 많고 맘에 듭니다! 사람이 많아도 대화하기 좋음', 39, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '시끌벅적한 홍대지만 골목 안에 있어서 아늑하고 음악도 장소도 훌륭해서 편안하게 시간 보내기 좋아요! 커피도 너무 맛있고 이곳만의 디저트 갈레트는 재료를 직접 다 만들어 쓰신다고 하는데 너무 훌륭합니다. 최고 🫶', 47, 5, 'GOOD', SYSTIMESTAMP);
