INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '여기 정말 너무 좋아요-!! (단골찜ㅎㅎ) 전부터 와보고 싶었던 곳인데 갈레트가 진짜 맛있고 음료도 너무 맛있어요 사실 보기에만 예쁜 곳들도 정말 많았는데 여기는 디저트랑 커피, 에이드까지 다 맛있어요 그리고 사장님이 엄청 친절하십니다:) 서비스까지 주시고 너무 감사합니당 ◡̈', 9, 6, 'GOOD', SYSTIMESTAMP);
