INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커피는 약간 산미있게 맛있었고, 시즈널 갈레트 딸기 먹었는데 진짜 너무 맛있었다. 비주얼도 맛있어 보이는데 먹으면 더 맛있음. 매장도 좌석이 넓게 퍼져있어서 쾌적하게 이용할 수 있고 무엇보다 직원들이 굉장히 친절하다👍', 42, 8, 'GOOD', SYSTIMESTAMP);
