INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대에 갈레트 맛집이 있다고 해서 다녀왔어요. 역시 소문대로 맛있어요 ! 흑임자 갈레트도, 시즌 갈레트도, 음료도, 커피도 모두 맛있었어요 ! 그리고 분위기도 넘 좋고 사장님도 친절하시네요 :)', 27, 9, 'GOOD', SYSTIMESTAMP);
