INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '내부 인테리어가 홍대답게 힙하고 무채색이라 너무 예뻤어요! 홀리건 카페를 대표하는 캐릭터도 귀엽구 커피도 맛있었습니닷💗 1층 2층 지하 이렇게 나뉘어져 있는데 지하층엔 소리가 좀 울리는 경향이 있었어요ㅜ 사진 너무 잘 나오고 (화장실까지도 무채색이라는 사실) 안 비밀입니다. 그리고 사진 맛집... 여기서 인생샷 건짐요', 4, 0, 'GOOD', SYSTIMESTAMP);
