INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '시즈널 갈레트가 딸기 갈레트라고 해서 먹으러 왔어요~ 매장도 넓고 인테리어도 깔끔해서 좋았구 직원분도 너무 친절하셨어요ㅎㅎㅎ 갈레트는 처음인데 너무 맛있게 싹싹 먹고 왔습니다ㅎㅎ 커피도 너무 시지 않고 고소해서 좋았어요!! 짱!! 다른 갈레트 또 먹으러 오겠습니다 ㅎㅎ', 7, 2, 'GOOD', SYSTIMESTAMP);
