INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '딸기갈레트는 메뉴판에는 없는 시즌한정메뉴인데.. 진짜 맛있어요.. 일단 아이스크림이 완전 모짜렐라치즈 처럼 쭉 늘어나고 쫀득해요! 그리고 밑에 크레이프 안에 카스테라,시리얼? 같은게 들어있어서~~ 다같이 먹으면 엄청 맛있어요. 러피안 에스프레소는 엄청 꾸덕하고 달달하고 에스프레소가 진해서 맛있어요 피치바질에이드는 엄청 특이해요! 섞어보려고 했는데 잘 안섞이길래 그냥 빨대로 쭉 마셨는데, 처음에 황도같은향이 느껴지면서 마지막에 바질향이 훅 들어와요 ㅋㅋ 다른데서는 먹어본적없는 특이한맛! 깔끔해서 좋아요~~ 엄청 달진 않아요!! 다음에는 초코갈레트 먹으러 오고싶어요 ㅎㅎㅎ', 0, 4, 'GOOD', SYSTIMESTAMP);
