INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '흑임자를 좋아해서 검색하다가 찾았는데.... 정말 흑임자 맛집이에요.. 흑임자크림라떼랑 흑임자갈레트 전부 꼬수하고 달달하고 최고였어요👍🏻👍🏻', 32, 7, 'GOOD', SYSTIMESTAMP);
