INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '갈레트 정말정말 맛있어요..🥺 쫀득바삭 식감도 재밌고 흑임자가 제가 여태껏 먹어본것중에 제일 진하고 맛있어요! 저는 말차라떼 먹었는데 달지않고 말차 맛이 진해 좋았어요😳❤️ 서울 놀러오면 재방문 꼭 할거에요 짱', 120, 24, 'GOOD', SYSTIMESTAMP);
