INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '생긴 지 얼마 안된 것 같고 사람도 얼마 없는데 여길 찾은 나 자신에게 칭찬을...♥ 갈레트라는 걸 처음 먹어봤는데 흑임자 맛 정말 강하고 꼬숩고 음료도 맛있고 카페 로고도 너무 귀엽고 직원분들도 친절하시고 행복.....!', 63, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아니 사장릠 말차라떼 말차 너무 찐하구 맛있어요ㅠㅠㅠㅠ아메리카노도 꼬숩고 맛있어요 대박적,,💚 근데 말차라떼가 진짜 저 카페가면 말차라떼만 먹는데 역대급 말차라떼에요,,', 27, 4, 'GOOD', SYSTIMESTAMP);
