INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '애쉬 커피랑 바질 피치 에이드 먹었는데 둘다 음료가 독특했지만 맛있었어요. 애쉬 커피는 초콜릿이 베이스가 되었는데 쌉싸름하면서도 향이 아주 독특하고 좋았고, 바질피치 에이드는 바질향이 강한데 맛은 복숭아의 달콤함이 느껴져서 좋았습니다. 무채색 인더스트리얼 분위기고 지하층은 공간도 넓은데 테이블 간격이 넓어서 좋았어요.', 10, 2, 'GOOD', SYSTIMESTAMP);
