INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '식사도 가능하고 디저트도 커피도 같이 마실수 있는곳이라 좋은것 같아요! 내부는 힙한 인테리어로 꾸며놓으셨고 사진도 이쁘게 잘 나와 좋았어요~', 89, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대 신상카페 훌리건 방문했어요 🕊️ 처음 먹어보는 디저트, 블루베리 크림치즈 갈레트🫐 커피랑 조합이 좋아요! 비주얼 말모~ 밀크티는 향이 굉장히 좋고 달달한거 좋아하시는 분들께 추천!! 라떼 꼬숩고 진해서 맛있어요🫶🏻', 33, 0, 'GOOD', SYSTIMESTAMP);
