INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '갈레트 첨 먹어봤는데 맛있네용 그릇도 컵도 귀여워요 음악 소리 작아서 대화할 때 말소리 잘 들려서 좋았습니다!! 가게가 구석에 있어서 안쪽으로 들어와 잘 찾아야 해욤', 4, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '플레이팅도  너무 이쁘고 스테이크봄바 흑임자 크림 갈레트 마카다미아크림 라떼 전부 다 너무 맛있어요~^^ 이런 멋진 곳에서 식사하니 행복하네요~음식도 신선하고 직원분이 굉장히 친절합니다', 55, 14, 'GOOD', SYSTIMESTAMP);
