INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '홍대 골목에 무채색 카페가 생겨서 무채색 인간은 행복함니다 ..🖤 공간도 넓고 낮에는 햇빛이 너무 잘 들어서 좋더라구요 사장님도 너무 친절하시구 시그니처 디저트인 갈레트 너무 맛있어서 지금 쓰면서도 침 흘리고 있어요 ..🤤 다음엔 다른 종류로 먹으러 올게요 사장님 번창 하세요 ~🤍', 29, 10, 'GOOD', SYSTIMESTAMP);
