INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '갈레트라는 디저트는 처음봐서 시켜봤는데 너무 맛있어요!!! 매장도 너무 이뻐서 전체적으로 만족했습니다🥲다음에 홍대 방문하게되면 또 올 것 같아요!!', 129, 24, 'GOOD', SYSTIMESTAMP);
