INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '너무 맛있어서 컵속으로 들어갈 뻔 했어요 😓😓 앞으로 계속 올 것 같네요!! 자리배치도 널찍해서 답답한거 안좋아하시는 분들 가면 좋을거 같아요👍👍', 5, 9, 'GOOD', SYSTIMESTAMP);
