INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '여기 디저트 맛나서 2개나 시켜먹었어요 무화과 팔레트의 무화과 신선하니 진짜 맛있었어요 블루베리 팔레트는 그래놀라랑 블루베리 조합이 진짜 좋았어요 굿굿', 13, 0, 'GOOD', SYSTIMESTAMP);
