INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '갈레트라는 메뉴을 처음 봤는데 너무너무 맛있었어요!!! 직원분들도 너무 친절하시고 생각보다 자리도 많아서 친구들과 즐거운 시간 보냈습니다🤤💗', 29, 9, 'GOOD', SYSTIMESTAMP);
