INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '갈레트를 처음 접했는데 너무 맛있었어요!! 에이드랑 차랑 같이 먹으니까 존맛 그 자체🤍 담에도 또 올게요 사장님 최고 짱짱맨😻', 85, 16, 'GOOD', SYSTIMESTAMP);
