INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '첫방문때 너무 좋은시간 보내서 다른 친구와 같이 재방문 했습니다! 무화과 철이 이제 막바지라 해서 일부러 시간 내서 왔는데 못 먹었으면 큰일날뻔했어요 제철 맞은 무화과도 무화과지만 직접 개발하셨다는 크림이 정말 너무 맛있는거에요 제가 느끼한거 잘 못먹그든요 케익도 한조각 다 못먹는데 이 크림은 손이 멈추질 않아요 크림만 따로 사서 집에가서 빵에 발라먹고싶더라구요ㅠ 매년 요거 먹으러 꼭 와야겠어요! 아 그리구 그사이 지하에 빔 프로젝트를 설치하셨네요?! 귀여운 톰과제리가 은근 시선강탈 ㅋㅋ 이번에도 친구랑 좋은 시간 보내고 왔습니다! 또 봬요 싸장님🙌🏻', 37, 10, 'GOOD', SYSTIMESTAMP);
