INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '블로그보고 와보고싶어 방문했는데.사진으로 보는것보다 실제로 보니 더 힙한인테리어네요:) 깔끔하고 청결해서 아무자리일단 착석 ㅋ.ㅋ 먹어보고싶엇던 피치에이드 진짜 맛있어요 과육들어가잇고 한잔더 마시고싶은맛 ㅋ.ㅋ 홍대 디져트 맛집이라해서  디져트도 같이 시켯는데 넘맛있네요 흑임자안좋아하는데 여기건맛있었어요!! 사진도 잘나와서 셀키꾼은 좋아할곳 ㅋ.ㅋ', 52, 13, 'GOOD', SYSTIMESTAMP);
