INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오후 4-5시경 방문했는데 채광이 너무좋아요 전체적인 분위기가 넘나 예뻐요~ 커피맛 좋아요 바닐라라떼에 수제아이스크림들어가고! 아메리카노도 입맛에 맞네요 고급 원두를 사용하는것 같아요! 다음에 또 방문할께요~ (>_<)', 28, 6, 'GOOD', SYSTIMESTAMP);
