INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '아이스라떼가 딱 고소하게 맛있어요 우유의 고소함과 커피의 맛이 적당히 잘 어울립니다 호텔 내에 있는 매장이라 깔끔하고 규모가 크지않아도 천정이 높고 분위기가 좋습니다', 7, 4, 'GOOD', SYSTIMESTAMP);
