INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '광화문 삼청동이 가까운데 홍대팝업 소식 3월 듣자마자 가야지하다가 드디어 방문 1시간 주차도 되고 매장 깔끔함 무엇보다 친절하게 다 답해주고 계산하면서 기분좋음 한정판매라는 쿠키선물도 구입(에코 파우치 포함) 진한 초코지만 막 달지 않음, 내가 좋아하는 느낌의 쿠키는 아니나 나쁘지 않음 간 김에 원두필터 얼른 사고 텀블러는 6년전 일본서 사왔던 블루보틀 기본이 오래되서 손잡이 있는걸로 구매 팝업카페 일단 9월까지 예정이라고 하니 종종 갈 듯', 193, 28, 'GOOD', SYSTIMESTAMP);
