INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '연남동에서 한 템포 쉬어가기 좋은 아늑한 공간, 낙랑파랑. 귀엽고 맛있는 디저트와 분위기 있는 커피 타임을 원하신다면 꼭 한 번 들러보시길 추천드립니다.', 9, 1, 'GOOD', SYSTIMESTAMP);
