INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대역 근처 스콘 맛집♡ 주말이면 지하층, 1층 그리고 2층까지 자리가 꽉 차는 핫플인데 운 좋게 자리가 나서 커피 & 스콘 주문 성공~갠적으론 유자스콘의 고급진 맛 최고 👍 커피는 신맛과 부드러움이 조화롭고, 시그니처인 낙랑크렘도 맛있다.', 66, 12, 'GOOD', SYSTIMESTAMP);
