INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '지하, 1층, 2층이 있어서 공간이 넓고 방도 여러개라 원하는 공간에서 작업하고 여유롭게 시간 보내기 너무 좋아요! 아늑하고 창문도 많아서 따듯한 분위기가 넘 좋았어요. 홍대에서 좋아하는 카페 리스트 추가🌼', 122, 22, 'GOOD', SYSTIMESTAMP);
