INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '저번 이후로 재방문 여전히 맛있는 내 취향저격 땅콩라떼🙃🙂 이번 디저트는 에그타르트와 저게 뭐더라 크림치즈 스콘이었나 단짠해서 좋았움 하지만 내가 제일 맛있게 먹은 것은 전에 케이쿠였다,,', 93, 25, 'GOOD', SYSTIMESTAMP);
