INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '빗방울이 제법 굵어 신발이 다 젖으니 어딘가 들어가야 할것 같아 후다닥 들어온 곳 들어와 앉아 주섬주섬 챙긴 디저트 이리 맛난 디저트는 처음 달달한듯 아닌듯 보드라운 식감에 편안함이 넘치는 갈색톤의 분위기 다시오려고 기억에 남기려고 리뷰를 쓰고 있는 나^^', 14, 8, 'GOOD', SYSTIMESTAMP);
