INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '저는 에스프레소☕️ 먹었어요! 첫입먹고 많이 쓰길래 각설탕 통째로 녹여서 먹었는데.. 이렇게 먹는게 아니었나봅니다.. 😂 분위기 내는 데이트 할때 가면 좋을 것 같아요! 인테리어 예뻐요🧸', 25, 10, 'GOOD', SYSTIMESTAMP);
