INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '🌰 낙랑 알밤라떼 (HOT) 6500원 // 따뜻한 밤라떼가 생각날때마다 들리는 곳... ♡ 밤 좋아하면 꼬옥 시키세요 저는 아이스보다 핫이 더 좋았어요!! 콘센트도 있고 과제하러 오기 좋아용.!!', 6, 7, 'GOOD', SYSTIMESTAMP);
