INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '카페가 포근하고 수다떨기 좋아요! 당근케이크도 너무 맛있고 라떼랑 아아도 고소하고 맛납니다. 밤라떼라고 신기한 메뉴있어서 먹어봤는데 달달하고 너무 맛있네요~ 그릇들도 이뻐서 사진찍기 너무 좋아요! 지하층이랑 2층까지있어서 넓습니다.', 67, 17, 'GOOD', SYSTIMESTAMP);
