INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '친구가 여기 유명하대서 왔는데 디저트도 맛있고 커피도 넘 맛있어요 근데 여자 직원분은 넘 친절하신데 남자분 넘 ... ..네 ..', 108, 24, NULL, SYSTIMESTAMP);
