INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '딸기초코라떼와 딸기라떼 디져트까지 시켰어요 전에 친구가 방문했는데 디저트를 못먹어봤다고 하여 디저트주문했는데 여기 크림맛집입니다 디저트에 올라간 생크림 너무 달지도않고 꾸덕한 그런크림 딸기라떼에 들어간 우유 크림도 장난 없음 진짜 맛있었어요!!! 크림이 짱짱인 카페였습니당', 40, 5, 'GOOD', SYSTIMESTAMP);
