INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '홍대 연남동 분위기 좋은 카페 낙랑파라입니다! 카페가고싶어서 길가다가 우연히 발견했어요 외관이 넘 이뻐서 가게되었는데 내부는 더 분위기 있어요 소품들이 곳곳에 있어서 구경하는 재미도 있고 맛있는 디저트와 커피도 다양해서 넘 좋았어요 또 방문하고 싶어요!', 43, 9, 'GOOD', SYSTIMESTAMP);
