INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '진~~짜 예전에 갔다가 오랜만에 갔는데 여전히 카페 분위기 너무 예쁘고 수다떨기도 좋아요 ㅎㅎ 토요일 1시?쯤 갔는데 자리 꾀 있어서 바로 앉았구요 점점 사람많아져서 꽉찬거 같아요! 글구 주문받는 직원분이 되게 상냥하셨어용', 19, 7, 'GOOD', SYSTIMESTAMP);
