INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '케이크 맛있는데 가격에비해 많이 작은거같아요! 그리구 검정머리에 눈크시고 앞머리 내리신분은 일하기 싫으시면 다른직종 알아보시는건 어떠신지... 휘낭시에 샀는데 음료랑 같이 트레이에 주는거도 아니고 계산후 아무말도없이 저한테 빵 가져가라고 손으로 미는모습 잘 봤습니다ㅎㅎ 대우받으려고 하는게 아니라, 기본적인 서비스업에서 인사도 안하는모습은 대단하네요 ! 저 뿐만 아니라 리뷰에 불친절하다는 이야기가 많은데도 개선이 안되는 듯 하네요', 128, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '생각보다 라떼는 괜찮았어요. 빈티지잔이나 인테리어는 예뻤는데 연남동 카페 그 느낌정도입니다. 직원분들이 웃고 얘기하는 건 좋은데 주문을 기다리게 하는 건 좀 아닌 것 같아요', 41, 10, NULL, SYSTIMESTAMP);
