INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '1930년대 느낌의 연남동 인기 카페, 낙랑파라. 평일 저녁 9시쯤에도 손님이 많아서 근처에서는 젤 인기 많은 곳 같았음. ‘낙랑파라‘라는 이름이 되게 생소한데,1931년 한국인이 운영한 최초의 카페 이름에서 따온 것이라함. (고구려에 함락된 낙랑+ 응접실을 뜻하는 ''parlour''를 일본식 발음인 ''파라''로 붙여 만든 합성어) 안에 ‘낙랑상점’도 있는데 1930-70년대 유럽,미국의 빈티지 제품들을 살 수 있음. 낙랑 크렘(아인슈페너) 먹엇는데 크림도 커피도 다른데서 먹던 거 보다 연한 느낌이었음. 같이 시킨 레몬쿠키도 굳굳!!', 0, 7, 'GOOD', SYSTIMESTAMP);
