INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '내맘대로 카페투어- 친구들이랑 카페투어 왔어요~ 연남동에 위치했는데 골목길 안쪽에 위치해있어요 평일이라서 여유있고 대화하기 좋았어요^^ 혼자와도 좋은 분위기의 카페인거같아요 1층과 2층으로 되어있어요 좁은줄 알았는데 안에 들어가보니 좌석도 많고 생각보다 넓었어요 땅콩라떼랑 아아 시켰는데 아아는 늘 우리가 아는맛이고 땅콩라떼는 라떼에 땅콩이 들어있어 입안에서 씹혀요~ 맛은 무난합니다 주차가 어려우니 대중교통이용 추천합니다', 23, 0, NULL, SYSTIMESTAMP);
