INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '낙랑파라 우리나라 최초의 카페 컨셉을 따라라던데 분위기 좋아요! 밖에서 걷다 맘에들어 방문했는데 시그니처 땅콩라떼 식사후라 배불러 못먹은게 아쉽네요 아메리카노도 맛있었어요! 리필도 되고 좋네요', 144, 86, 'GOOD', SYSTIMESTAMP);
