INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '(맛집만리뷰남김) 연희동에 데이트하기 딱 좋은 커피숍 낙랑파라! 분위기도 좋고 위치도 좋고 커피도 맛있습니다~ 오랫동안 있는 집이라 연희동 가면 자주 들려요', 49, 10, 'GOOD', SYSTIMESTAMP);
