INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '제법 진하고 향 좋은 아이스티 - 데코인 듯 꽂은 허브는 매 모금 마실 때마다 싱그러움을 더해주었다. posted by @oz.d.ls / insta', 79, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '근처에 볼일이 있어 오픈시간에 맞춰 아이스커피테이크아웃하는데 커피는 누구나 마시기 무난한 맛이고 공간이 아기자기하니 재미있어요:)', 30, 7, 'GOOD', SYSTIMESTAMP);
