INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '연남동 초입 카페 지나가며 궁금했었는데 3년만에 와보았어요. 지나갈 때마다 사람이 많았는데 지하에도 좌석이 있고 내부에도 좌석이 넉넉해서 편하게 이용했어요. 빈티지 아이템들도 판매 중이어서 구경하는 맛도 났고 음료도 맛있게 마셨어요. 아메리카노와 밤 라떼 주문했어요. 커피가 텁텁하지 않고 깔끔하더라구요. 산미가 어느정도 있는 맛이었어요. 산미 있는 커피 좋아해서 입맛에 맞았어요. 밤라떼는 꼬숩고 달달하니 부드러웠어요. 맛있게 먹고 갑니다. 여러 명이서 연남동 놀러오면 와볼만할 것 같아요. 대형 테이블도 있어서 괜찮을 것 같네요.', 14, 10, 'GOOD', SYSTIMESTAMP);
