INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '생각보다 내부가 커서 넓은 공간에서 대화하기 좋았어요. 음료는 괜찮았어요. 소품의 아기자기함이 눈길을 끌어 한참 둘러 보았어요', 93, 22, NULL, SYSTIMESTAMP);
