INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '가격은 비싸지만 연남동 카페가 다 그래서 별로 놀랍지도 않음. 땅콩라떼 안달게 부탁드렸는데 정말 하나도 안달게 잘해주시고 달지 않은데 땅콩맛도 진하고 맛있어서 놀라움.', 24, 10, 'GOOD', SYSTIMESTAMP);
