INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '매장은 볼거리가 많았는데 커피는... 왜... 텀블러 태아크아웃 할인 안받았으면 갱장히 아까울뻔 .. 직원분들 출근해서 커피맛안보나? 싶은 너낌 하...', 44, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '매장이 조용하고 신기한 메뉴가 있어요. 땅콩카라멜은 고소하고 달콤해서 추운 겨울에 잘 어울리는 음료예요. 지하도 2층도 있어서 생각보다 자리가 많아요!', 61, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '우연히 발견한 곳인데 너무 예쁘고 음료도 맛있어요,, 시그니처 메뉴 꼭 드셔보세요! 또 롤케이크도 달달하니 음료랑 먹기 좋았어요~ 재방문 의사 있습니다!', 206, 100, 'GOOD', SYSTIMESTAMP);
