INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '연남동에 진짜 연휴 낀 주말에 카페 자리가 없어서 방황하다가 겨우 찾았던 오아시스같은 빈 자리 였는데 음료도 괜찮았고 매장 인테리어도 깔끔했어요!', 17, 7, 'GOOD', SYSTIMESTAMP);
