INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '지나가다가 우연히 들렀는데 커피 맛있어요.디저트도 무난하고~~ 2천원 내면 아아메 리필 가능! 신기하게 외국인 손님이 많더라구요? 화장실은 내부에 있고 깨끗하고 좋습니당', 130, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '빈티지 제품이 인상적인 카페입니다! 1층은 다소 울려서 대화하기 쉽지 않네요! 조용한 분위기를 원한다면 2층으로! 커피 외의 메뉴들도 맛있네요👍🏻', 29, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '인테리어가 멋져요! 대화하기 좋고 소품이 감각적입니다.! 커피도 맛있어욥! 지하는 약간 추워욥 그리구 하수구냄새인지.. 화장실냄새인지 ㅠ 괜찮다가 중간에 갑자기 냄새가 엄청 심하게 나서 좀 놀랐어여 ㅠ', 35, 9, 'BAD', SYSTIMESTAMP);
