INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '새로 이사온 주민인데 예쁜 카페 잘 찾은거 같아요 ! 집을 개조해서 만든 깔끔한 느낌에 엔틱 두방울 떨어뜨려놓은 느낌! 먼저 이 집 시그니처 메뉴인 땅콩라떼 넘 맛있었어요 은은한 땅콩 맛이 퍼지면서 끝은 커피향 ! 아메리카노는 가벼운 산미 맛입니다 :))', 16, 6, 'GOOD', SYSTIMESTAMP);
