INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '땅콩카라멜라떼 별로에요. 걍 땅콩잼에 우유 섞으시던데 잼 하나도 안섞이고 뭉쳐있어요. 근데 6000원이나 해요...^^;분위기는 인정~', 27, 6, 'BAD', SYSTIMESTAMP);
