INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '내부는 깔끔하고 예쁜 접시도 팔더라구요. 주스랑 아.아. 마셨는데 맛있었어요. 그런데 양이 조금 적어서 아쉬웠어요ㅠㅠ 그렇지만 위치가 위치인만큼 이해할 수 있어요. 지하에서 마셨는데 안 좋은 냄새가 나는 거 같더라구요. 하수도가 지나가는걸까요~? 다음 손님들을 위해 확인해주시면 좋을 거 같아요.', 37, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '주택을 개조한 카페. 3층에 실제로 거주인이 살고있어서 이곳의 마스코트인 대형견과 산책을 마치고 올라가심.일단 인테리어와 작은 소품들로 엄청 잘 꾸며져 있고 한쪽에는 책들도 많이 있어서 심심할때 하나씩 꺼내보는 재미도 있고 1층에서는 엔틱한 소품들을 판매해서 구경하는 재미도 쏠쏠.에어컨 빵빵하고 사실 좀 추워서 담요가 필요할 정돜ㅋㅋ좌석이 넉넉하고 넓직하고 쾌적해서 너무 좋았어요', 82, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '조용하고 넓은 분위기 소품? 같은것도 판매하고있고 가격이 좀 있지만 분위기도 좋고 커피와이커리가 예쁘고 맛이 좋았음 시간대에따라 다를지 모르겠으나 조용한 데이트나 혼자 사색하러 가기에 좋아보임', 120, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '진동벨 울려서 받으러 가니 메뉴가 잘못나와 있어서 메뉴 다시 확인하는 동안 “포크 두개 드릴까요”를 빨리 대답하라는 식으로 두 번 이나 크게 소리치시더라구요. 당황스러웠습니다.. 그리고 저는 티 시켰는데 티 팟에 수세미 실 뭉치 같은 게 같이 끼어있어서 기분이 좋진 않았습니다.  케익류는 공산품 냉동으로 받아서 쓰시는 듯 했고 맛은 별로였어요. 엔틱한 소품들이 많긴 많은데 그에 더해 피규어까지 너무 많아서 정신이 좀 없는 곳이 었습니다. 지하, 1층, 2층으로 된 생각보다 큰 까페였고 티나 커피 종류 무난했어요. 하지만 재방문의사 0', 28, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '분위기는 짱 좋아요. 그런데 ㅋㅋ 주인인지 알바생이신지 ㅋㅋ 넘 불친절.. 커피도 넘 맛 없어요 흑 ㅠㅠ 그래도 분위기와 인테리어 깡패!! ㅋ 음악도 좋으네요~^^', 11, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '빈티지 편집샵겸 카페예요~ 분위기 좋고 구경거리도 많아요~ 손님들이 다양한 메뉴들을 먹음 망고빙수는 가격대비 망고 양과 맛이 쏘쏘.', 18, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '분위기 좋고 괜찮았어요 밀크티가 좀 연한거 빼고. 빈티지한 컵이나 장식품 같은 것도 많았는데 너무 비싸요. 그리고 아무리 빈티지래도 먼지가 가득.. 빈티지가 아니고, 그냥 더럽... 별로 사고싶지는 않았습니다.', 9, 6, 'BAD', SYSTIMESTAMP);
