INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '빈티지커피잔도 팔구요. 반지하 층도 분위기좋구요. 지상층도 느낌 있어요. 커피도 빈티지한 잔에  담아주니 더맛있게 느껴집니다.', 55, 18, 'GOOD', SYSTIMESTAMP);
