INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '가격대비 별로라 저는 다음엔 다른 곳 방문하려구요 겉에서 보기에 이쁘이긴한데 맛은 그닥 없었어요 망고빙수 유명하긴하던데 그걸 안먹어서 그런가 여튼 여기 밀크티는 제 입맛에 별로였어요', 35, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '망고치즈빙수 가성비 최고! 1인 1빙수 좋아요~ 날씨가 무척 더워서 들어왔어요. 1층이라 찾기 편한 위치이고, 실내 테이블 깨끗해요', 33, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '집들어가는 길에 빙수가 먹구싶어서 생각하다가 망고 바스켓 생각나서 네이버 주문하구 받아왔어요~! 중간중간 코코넛크림도 있어서 너무 맛있게 먹었어요!', 23, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '으앙! 스탬프 적립 제외 매장입니다ㅋㅋㅜㅜ 전화번호 정성스레 적었는데 나온 문구가 저거라 너무웃겼음... 여기 아메리카노는 맛있었어요', 19, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '식샤를 좀 남겼는데 금방 허기져서..🫠 잠깐 앉아서 과제도 할겸 고!MANGO🥭로 들어왔듬ㅎㅅㅎ 빙수로 시켜봤는데, 아이스크림이랑 큐브 망고까지 푸짐하게 쟐 나오네여~매장에서 먹으니 더 맛나요✨️', 34, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '3.8/5 망고쥬스 3200원 XL사이즈 업그레이드 1천원 망고젤리 500원 총 4700원 시원하고 맛있음 밖에 비와서 잠깐 들려서 목축이고 감', 36, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '사람들이 너무 많아서 대기시간은 있었는데 양도 많고 아이스크림도 맛있었어요 나오자마자 의자 있길래 앉아서 냠냠했어요 강추합니다 ~', 62, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대근처에서 점심을 먹고 망고빙수가 맛있다는 고망고에 들르게 되었어요~ 홍대라서 그런지 손님이 정말 많았어요. 키오스크에서 주문하고 기다리고 있다가 번호가 뜨면 받아가면 되는데 손님들이 밀려서 좀 기다렸어요. . 망난희컵빙수 2개를 주문했는데 생각보다 커서 조금 놀랐어요 ㅎㅎㅎ 그리고 1개에 3,500원이면 가성비도 좋은것 같아요.어른2아이1명이 망난희 컵빙수2개를 먹는데 배불렀어요. 동네에도 있어서 배달시켜 먹어봤는데 홍대점이 망고도 많이 주고 훨씬 맛있네요. 홍대 갈일 있으신분들은 고망고 홍대입구역점에 꼭 가보시길 추천드려요 :)', 65, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대 놀러올 때마다 들리는 마지막 코스임. 가격 넘 혜자임. 이 가격에 이런 맛의 퀄리티라니.. 카페 가고 밥집 가고 마무리로 깔끔하게 고망고 먹어주면 끝임.', 18, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '홍대에도 고망고있는줄 여태 몰랐네요 연남점만 있는줄ㅠㅠ 최근에 먹었던 연남점보다 망고 당도가 높아서 좋았어요 망고코코넛은 사랑입니당 아이스크림도 많이 있던데 다음엔 아이스크림을 먹어볼게용 ❣️', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '망고소프트아이스크림(1.8), 식후땡망고쥬스(1.8)을 주문했습니다! 점심먹은후라 배가 부를때 가볍게 입가심하기 좋네요! 소프트아이스크림은 망고맛이 많이 나지는 않아 망고맛을 기대말고 드시고 개인적으로 상큼 달달한 망고쥬스를 더 추천합니다! 전체적으로 가성비가 너무 너무 좋아요😵', 130, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '고망고 처음 와봤는데 완전 만족합니다! 컵빙수 주문했는데 양 엄청 많고 망고도 많이 주셨어요! 이 가격에 이 양이 맞는건지? 개인적으로 망딸코보다 망난희빙수가 더 맛났습니다 주방이랑 가까운 자리에 앉아 우연히 봤는데 주방 진짜 깨끗했어요! 저가형 음료 매장은 관리가 잘 안된다는 느낌을 많이 받았었는데 요기는 관리가 엄청 잘 돼서 좋았습니다. 외국인 손님이 팁 주시는 것도 안 받으시길래 엄청 양심적으로 운영하시는구나..! 했습니다', 13, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '고망고는 음료 빙수 판매점 중에서 가장 가성비가 좋다고 생각합니다. 망고를 직접 공수온다는 홍보에 걸맞다고 생각이 드는데요, 3-4000원으로 상대적으로 가성비 있으면서도 맛있었습니다. 다만 다들 이걸 아는 만큼 홍대에 그만큼 이곳에 사람이 조금 몰리는 편이고 어떨 땐 앉을 자리가 부족할수 있어요. 가게의 크기 자체는 작습니다.그럼에도 값싸고 맛있는 망고 브랜드입니다.', 36, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '고망고망고 오늘도 역시나 식후땡 망쥬를 먹었다! 그리고 빙수를 먹었는데,,, 위에 코코넛 아이스크림이 맛있었다!! 밑으로 갈 수록 넘 밍숭맹숭 😵‍💫😵‍💫', 44, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '색도 이뿌고 맛도 좋고 가격도 좋고^^ 너무 더웠었는데 닭살을 느끼며 나왔습니다. 망고와 소프트아이스크림의 조화 너무 찰떡이에요💕', 7, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '목이 말라 간단하게 마시고 싶어서 식후땡 시켰어요! 1800원에 망고주스 먹을 수 있어서 행복해요🥰🥰 홀더도 과일 스티로폼 느낌이라 생과일 느낌이 나는 것 같아요! 완전 아이디어 대박👍🏻', 81, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '저녁시간엔 매장이 조금 혼잡해보였어요ㅠㅠ 그래도 메뉴는 주문하면 빨리 나오고 다른 카페보다 가성비 좋아서 요즘처럼 날 더울때 하나 들고다니면서 먹으면 달달하니 좀 시원해져서 좋아용', 46, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '망고주스는 맛 진하고 시원하고 너무 맛있어요 😋 다만, 처음에 아이스크림 시켰는데 기계가 고장났으면 말씀을 해주셔야지,,, 기다리다가 너무 안나와서 여쭤보니 그제서야 말씀해주시네요 🥲', 47, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '망고 좋아하는 사람이라면 좋아할만한 곳이에요 ~ 뭣보다 가성비가 좋아서 간단하게 디저트먹기 좋은거 같아요😊😊 망고사고 먹고싶었는데 이제 안팔길래 망고초코아이스크림 먹었어요 좀 밍밍한데 그래도 만족합니다:)', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '망고 라임 페션흐르츠티 날씨 때문인지 연속 따뜻한 것만 찾게 되네요. 점심 먹고 나서 달달한 게 땡길때 만족스러운 티인것 같아요. 달고 상큼한 맛이 제 입맛에는 딱입니다. 가까이서 자주 이용할 수 있어 감사합니다!', 65, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '역시 이만한 가성비가 없어요 냉동이긴 하지만 망고가 한주먹보다 더 올라가고 밑에 깔린 주스도 꽤 많은데 3900원이라니 역시 고망고 훌륭합니다', 44, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '진짜 존맛~~~~~~💖💖 망고 + 망고 아이스크림 + 생크림 + 망고주스까지!!!! 너무 맛있어요ㅎㅎㅎ 망고 좋아하시면 꼭 드세요! 욕심부려서 1리터 샀는데 다음엔 한단계 작은 사이즈로 살 거 같아요.', 77, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '가게는 작아서 테이블은 많이 없어요. 메뉴자체가 가성비가 너무 좋고 너무 달지 않고 양도 충분하고 너무 덥고 지쳤었는데 충전 되네요', 27, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '와.. 여기 망소주스 지인짜 맛있네요👍👍 제가 먹어본 주스중에서 역대급으로 맛있는 주스입니다 체고체고 다음에 또 오려구요💛 꼭 한번 드셔보시길 추천드립니다😍', 4, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '없는 메뉴도 많고 품절도 너무 많고, 심지어 망고사고도 안 하는 매장.. 망고사고가 제일 지금 핫한데 아쉬워요. 그리고 주문이 너무 많아서 한 15분을 넘게 기다려서 메뉴 받으러 갔더니 두 잔 중에 하나만 되어 있었어요. 바쁜 매장이라 이해하긴 하나 사과 한 마디 없이 기다리라고 해서 재방문 의사 없습니다.', 18, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '🥭달콤하고 맛있는 망고를 저렴한 가격에 마음껏 먹을 수 있는 곳 고망고입니다! :)💖✨ 처음 방문해본건데 가격보고 진짜 충격받았어요! 진짜 엄청 저렴하고 천원대 이천원대 음료가 정말 많아서 대박이더라고요!🥰💖 가격은 저렴한데 양도 많아서 진짜 가성비 갑입니다👍 홍대에서 가장 저렴한 카페라고 소개해드리고 싶은 곳이에요~ ✨망고요거트 단돈 2,500원밖에 안하는데 양도 많고 진짜 맛있으니 꼭 드셔보시는거 추천드려요!🥰👍', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '점심 식사 후 자주 이용합니다. 주로 따뜻한 망고 티를 마시는데 향도 맛도 정말 좋습니다. 티백만으로 그렇게 단 맛을 낼 수 있다는 게 정말 신기하네요~ 망고 빙수는 생각지도 못한 사이즈라 많이 당황스러웠네요. 다 먹느라 애 썼지요. ㅎㅎ', 47, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '왕맛있는 망고 아이스크림🥭 믹스로 먹었는데 생각보다 너뮤 맛있어서 놀랬음✨ 약간 동남아에서 먹던 그 맛 나욬ㅋㅋㅋㅋㅋㅋ 주스는 째끔 밍밍하지만 그래도 맛있습니다', 1, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '1리터망고랑 딸기라떼 주문했어요 사진에는 둘에 크기차이가 별로 나지않아보였는데 진짜 깜짝놀랬네요. 고망고 아이스크림 좋아해서 영하 3도에도 지나치질못하고 또들어왔네요 ㅎㅎ 맛있오용', 53, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '가성비는 좋은데 빙수는 포장이 안 되네요. 포장주문이 가능해서 시켰더니 포장이 안 된다고 해서 곤란했습니다. 사전에 안내를 주시는 게 좋을 것 같아여. 그리고 망고 심이 자꾸 씹힙니다. 좀 많이 씹혀요.', 30, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '약한 망고 시럽맛이 아니고 찐 망고 꾸덕한 맛이에요 ㅎㅎ 얼음 있는 음료를 안 좋아하는데 이건 원래 없어서 너무 좋더라구요 다음 번에 다른 메뉴도 먹어볼 생각이에요~~', 67, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대에서 이 맛에 이 가격이라니 신선한 충격이에요! 다른 카페에서 나오는 냉동망고랑 차원이 다르네요. 영업 마감에 가까운 시간에 매장에서 먹었는데도 친절하시고 빨리 나와요! 잘먹었습니다☺️', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '인근에 술마시고 잠깐 들른 가게입니다. 많이 달지 않는 진짜 망고를 갈아서 쓰기에 남자들도 무난히 먹기 좋고 술마시고 수분감이 부족하거나 조금 텁텁할때 가기 좋습니다. 프렌차이즈지만 홍대에서 술마시고 가기 딱인 장소입니다.', 14, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '시럽같은거 안쓰고 생망고로 하는곳이라는데 맛도 있고 친절하고 좋았어용 지점이 많이 없어서 계속 못먹다가 우연히 발견해서 잘먹구 갔오용 :)', 58, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '고망고 집 근처에 생겨서 넘 좋아요🤍 연남쪽은 줄 너무 길어요ㅜㅜ 언제 먹어도 꾸덕꾸덕 달달하고 맛있는 고망고 무조건 코코넛 젤리 넣어 먹어야 맛있어용', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '빙수도 주스도 맛있어요! 주스 완전 망고 갈아서 만든 맛 그 잡채 🥹🥹그리고 엄청 친절하시고 가격도 저렴해서 조아요 자주 올게요~~🥹🥹🥹🥹😻', 44, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '망고주스 진짜 찐하고 맛있어요😍😄 망딸코 빙수도 먹었는데 망고 신선하고 딸기 시럽이 적당히 달아서 맛있었어요!! 위에 아이스크림이 코코넛 맛인데 고소하니 잘 어울렸어요 잘 먹고 갑니다👍', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '고망고 노란색의 예쁜인테리어에 가성비에 맛까지 최고!! 망고코코넛도 맛있고 패션후르츠에이드도 상큼달달 ~~망딸코 컵빙수는 친구가 완전 맛있다고~ 매장서 마카롱 하나 맛보구 20개 사들고 집으로 왔어요 하나하나 먹다보니 금방 다 먹을듯', 89, 13, 'GOOD', SYSTIMESTAMP);
