INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '벌써 여름 입니다…… 여름엔 팥빙수를 먹어줘야죠!!! 눈내리는 숲, 설레임…… 상호가 무척 깁니다. 이름만 들어도 시원 합니다. 빙수 종류가 많이 있는데, 딸기빙수와 말차빙수, 식혜를 주문!! 요즘들어 식혜가 많이 좋습니다. 많이 달지 않으면서도 갈증이 해소 될꺼같은 맛이 였습니다. 얼음동동도 인상적~~~ 다소곳한 실내 인테리어가 편안함을 주네요. 그러나, 우리는 야외에서 살랑살랑 불어오는 바람을 맞으며, 빙수들을 순삭!!!! 지나다니는 외국인들이 신나서 웃는표정들을 보는 재미도 있습니다. 힐링되는 간식타임 이였습니다.', 8, 0, 'GOOD', SYSTIMESTAMP);
