INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대입구역이랑 상수역 중간에 위치되어있어요! 빙수를 1인 / 2인양 선택 할수있어서 좋았어요. 한라봉 요거트 우유빙수 진짜 베스트. 시원하고 맛있어요💜', 14, 4, 'GOOD', SYSTIMESTAMP);
