INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아는 지인통해서 빙수 맛집이라고 유명해서 부산에서 찾아 왔는데 진짜 .. 너무 맛있네요 .. 사실 놀랬어용 ㅋㅋㅋㅋ!! 👍🏻 빙수에 얼음이 진짜 맛있네욥 ㅠㅠㅠ 흑 왜 혼자와서 1인 빙수만 먹은지 참 아쉽네요 ㅠ카페 분위기도 너무 좋고 또 홍대 놀러오면 무조건 올꺼같아요 사장님도 너무너무 친절하시고 빙수하나만 먹고가기 너무 아쉬워서 담에 또 올땐 배 좀 꺼트리고올게요 .. 완그릇하고가요 ~~~ 잘먹었습니다 !!! ㅎㅎㅎ', 15, 2, 'GOOD', SYSTIMESTAMP);
