INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '제가 매일 출근 길에 커피 사먹는 커피 맛집 입니다. 맛있어서 가격 그 이상의 가치가 있는 곳이에요. 오늘 들렀는데 붕어빵을 출시 하셨더라구요. 오늘부터 하나하나 맛별로 먹어 볼 생각입니다. 제일 기대되는 맛 명란 마요⭐️⭐️⭐️⭐️⭐️', 48, 0, 'GOOD', SYSTIMESTAMP);
