INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '근처에서 야식으로 땀 뻘뻘 흘리면서 라멘 한그릇 때리고나니, 시원-한 빙수가 먹고 싶어 방문한 곳🧊 인절미 팥빙수를 주문했는데 크기가 꽤나 컸고, 우유 빙수라 꼬숩고 맛있게 먹음! 1인 1메뉴 정책이라, 빙수 말고 다른걸 하나 더 주문해야만 했는데 너무 배가 불러서 크로플을 테이크아웃 함! (너무 현명한 선택👏🏻👏🏻) 늦은 시간까지 영업 하는지라, 술먹고 빙수로 해장하기에도 아주 딱인 곳! 추천✨', 105, 26, 'GOOD', SYSTIMESTAMP);
