INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '식후 디저트. 홍대를 돌다 편안하게 쉬면서 수다를... 빙수 달지 않고 좋았습니다. 외국인 분이 많았고요. 외국분이 이것에 저희 아이에게 예쁜 인형을 주었습니다.', 11, 9, 'GOOD', SYSTIMESTAMP);
