INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '1인1빙 맛있게 잘하고 왔습니다. 빙수 맛있는거야 둘째치고 주말 오후에 계셨던 남자분. 사장님? 이 정말 너무너무 친절하세요. 정말 기분 좋게 다녀왔어용!', 25, 7, 'GOOD', SYSTIMESTAMP);
