INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '8.18 오후1시쯤 방문했습니다 중국에서 친구가 처음 한국 놀러온거라 신중하게 찾고찾고 찾아서 방문한 곳이였는데요 나온 빙수? 좋았어요 비주얼이며 맛이며 다 좋았어요 주문한 차도 만족스러웠고요 근데 직원분 응대가 제일 아쉽네요 원래 귀찮아서라도 이런 리뷰 안쓰는 사람이고 저도 알바 많이 해봤어요 현직 서비스직 종사자고요 들어갔는데 아무도 없고 조용하길래 사장님 지금 돼요? 했는데 빼꼼 나왔다 다시 주방쪽 들어가시길래 못들으셨나보다 하고 다시 재차 질문드렸을때 된다고 말씀드렸는데요? 하고 되게 퉁명스럽게 대답하시더라구요 제가 못들은거겠죠 근데 제가 어려운거 여쭤본거 아니잖아요.. 중국인 친구가 못들은것같아 다행인데 좀 아쉬웠네요 커피랑 빙수, 매장 분위기 비주얼은 다 만족스러워요', 17, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '무척 더운 날이었는데 시원하고 맛있는 한라봉 빙수 잘 먹었습니다! 직원분들도 엄청 친절하세요!! 다음에는 또 다른 빙수 먹으러 가볼게요 ♡̆̈', 36, 2, 'GOOD', SYSTIMESTAMP);
