INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '너무 별로였어요 알바생이신지 모르겠지만 일하시는 여성분 뭐가 그렇게 화가 나신건지..너무 바빠 보이셔서 주문하는 곳에서 기다리고 있었는데 이야기를 하셔야 알아요 하며 굉장히 퉁명스럽고 불쾌하게 말씀해주시고 메뉴 주문 할 때도 안 들려요라고 불친절하게 말씀하시고 다신 안 갈 것 같은데 이건 좀 아닌 것 같아서 리뷰 남겨요.', 38, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '딸기 빙수 먹으러 간건데..인절미에 반하고 왔어요.. 딸기빙수는 일단 빙수 양이 너무 많았어요ㅠㅠ 그래서 딸기랑 같이 빙수를 즐긴 것 보다 밍숭한 우유빙수만 퍼먹어서 나중에 반 이상 남겼던건 아쉬운 부분이에요 ㅠㅡㅠ 하지만 인절미는 따끈한데 아이스크림이랑 같이 먹으면 천상의 맛✨이라 딸기 빙수의 아쉬움을 달랠 수 있었어요', 27, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '좌식 자리가 있어서 전 더 좋았어요👍🏻 앉아서 편하게 먹을 수 있음! 빙수가 되게 작은 접시에 나오긴하지만 내용물이 알차서 맛있어요~~', 39, 1, 'GOOD', SYSTIMESTAMP);
