INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대빙수맛집, 홍대크로플맛집이에요! 우연히 들어갔는데 빙수가 고소하니 맛있었고 맛도 맛이지만 1인용, 2인용 양을 선택할 수 있는 점이 너무 좋았습니다! 인절미크로플은 쫀득고소하니 넘 맛있어서 아아랑 먹든, 빙수랑 먹든 어떤 거에 먹든 강추드리고 싶은 디저트예요:)', 49, 4, 'GOOD', SYSTIMESTAMP);
