INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '푸딩 파르페 진짜 맛있어요!!!! 푸딩이 맛있어서 그런건지 너무 부드럽고 적당히 달아서 배불렀는데도 계속 들어갔어요 홍대 푸딩 1티어인듯요🤤', 79, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '매장이 밖에서 보는거보다 훨씬 넓구 따뜻한 분위기에 아기자기한 소품이 많아서 너무 즐거웠어요. 말차 푸딩은 많이 달지 않았고 부드러우면서 탱글한 식감이 좋아 맛있었어요. 망고 파르페도 여름이라 상큼달달해서 좋았어요. 다른 맛들도 맛있을 거 같아요!', 28, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '메론소다랑 초코푸딩 먹었어요! ꒰ ɞ̴̶̷ ·̮ ɞ̴̶̷ ꒱ 🩵 푸딩이 탱탱하고 카페가 귀엽습니다.. 다음에 올 때는 파르페도 먹어보고 싶어용.. 인형 사진 찍기도 귀여워요!!!', 18, 2, 'GOOD', SYSTIMESTAMP);
