INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '메론소다 너무 귀여움~!!!!!!! 푸딩도 먹을만합니다 웨이팅도 5분정도밖에 안했어요 곰돌이 라떼 시켰는데 귀여운 병에 안주네요 아쉽 매장 너무 시원함 밖에서 더워 죽을뻔 레트로티비 씨씨티비(?) 있는데 사진찍기 아주 굿이요', 45, 5, 'GOOD', SYSTIMESTAMP);
