INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '매장이 청결하고 음식들이 너무 귀여워요! >< 돈만 있으면 시간 날때마다 오고 싶을정도네요! 푸딩 먹고 기절할 뻔했어요  상상그이상입니다! 푸딩맛집 추천입니다!', 25, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '비주얼이 우선 대박인데 진짜 먹기아까울 정도로 넘넘 귀여워요!! 매장이 작긴한데 앉을 자리는 많아서 바로 앉을수 있었습니다ㅎㅎ 저는 팥푸빙이 젤 취향이었습니닷', 36, 7, 'GOOD', SYSTIMESTAMP);
