INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대는 처음이라 이곳저곳 찾아봤어요 근처에 외관이 귀여운 카페가 있어 와봤어요! 달달한 망고 푸딩 파르페부터 메론 소다까지 // 반했습니다 푸딩은 여러 종류 중에 하나를 선택할 수 있어 좋았어요! 엄마랑 즐기다 갑니다 ~~', 7, 5, 'GOOD', SYSTIMESTAMP);
