INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '두번째방문! 저번엔 파르페먹었는데 오늘은 음료랑 푸딩 먹으러왔어요 푸딩이 맛있어서 푸딩 생각나가지고 먹으러 들렀습니더 저녁시간 돼서 방문하니까 자리도 여유있고 좋네요 ㅎㅎ 3시쯤 오면 웨이팅 필수입니다', 129, 19, 'GOOD', SYSTIMESTAMP);
