INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '아이들이랑 홍대 나들이.지나는 길에 우연히 들렀는데 여러 종류의 푸딩 모두 맛있고 알록달록 예쁜 색감의 음료와 매장 분위기까지!! 아이들 취향 저격 입니다♡ 스모어멜팅쿠키 너무 귀엽고 맛나다고 추가,추가 주문으로 8개나 먹고 갑니다♡', 11, 0, 'GOOD', SYSTIMESTAMP);
