INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '탱탱푸딩~ 탱글푸딩~ 하도 인터넷에서 문익점푸딩으로 바이럴 많이봐서 택배로 시켜먹으려는 찰나..ㅎ 비싼 택뱌비에 공구러들 모으다가 오프라인매장이 잇는것을 보고 방문예정.. 확실히 맛도리상큼하내요 ㅎ 전 우유푸딩은 그냥 맛있었고 커스터드가 존마탱이네요. 저날 푸파하느라 힘들고지치고배불러서 푸딩을 사올까말까 오만번 고민하다 원래 디저트를 잘 먹지않는 저라 사먹고 까머글까바 안사옴 그양 ㅜ 후회중입니다', 213, 42, 'GOOD', SYSTIMESTAMP);
