INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '지나가다가 귀여운 카페 모습에 이끌려 들어왔어요. 매장도 청결하고 깔끔하고 직원도 친절해요. 오랜만에 말차라떼 너무 맛있네요 ㅇ멜론썸 스무디도 너무 맛나요!!', 6, 3, 'GOOD', SYSTIMESTAMP);
