INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '주디마리 백화점 팝업이랑 온라인 스토어로만 먹어봤었는데 카페가 있었다니,,🫧🩷 냉큼 캐치테이블 줄서기 하구 30분 정도 기다렸다가 입장했어요 푸딩 파르페 8500원 왕가성비,,🍀 츄러스랑 초코디핑도 넘넘 맛있었어요 좀 덥고 답답하다는거랑 화장실 한 칸인거 빼구 다 조아씁니당😇🪽🤍', 60, 11, 'GOOD', SYSTIMESTAMP);
