INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '주변 카페 검색하다가 우연히 발견해서 방문하게 되었는데 최고의 선택이었던 것 같아요!! 푸딩도 너무너무 맛있구 카페 분위기나 인테리어도 너무 키치하고 귀여워서 더 좋았던 것 같습니다 ㅎㅎ 사장님도 너무 친절하시고 매장도 깨끗하고 부족함 없는 카페였던 것 같아요🥹🥹', 22, 2, 'GOOD', SYSTIMESTAMP);
