INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '전부터 꼭 와보고 싶던 곳이라 와봤어요!! 푸딩 크기가 생각보다 크고 매뉴 가격이 홍대임에도 싼편이에요 공간이 귀엽게 잘 꾸며져 있어서 사진 찍기도 좋아요 ㅎㅎ', 115, 24, 'GOOD', SYSTIMESTAMP);
