INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '인테리어가 아기자기하고 예뻐요 다양한 소품이 많고 안쪽에 작게 소품샵도 있어서 디저트도 맛있고 가게 가체가 편안한 분위기라 즐거워요', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '푸딩 먹고 싶어서 왔어요! 오랜만에 오니 ‘푸딩온탑’이라는 메뉴가 생겼더라고요. 디저트 먹을 때 아메리카노 꼭 필요한 사람을 위한 최고의… ✨ 푸딩은 역시나 맛있어요 매일 매끼니마다 먹고 싶어요 🤤🤤', 76, 17, 'GOOD', SYSTIMESTAMP);
