INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '문익점 푸딩이 이젠 홍대에서도 먹을 수 있어서 너무 행복ミ > 。o ミ🍮 다들 푸딩은 꼭 주디마리 기억해야해~! 그리고 여긴 꼭 최소 1인 1푸딩하셔서 손해보지않길', 78, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '너무 맛있습니다 ㅠㅠ 친구랑 길 가다가 분위기가 좋아보이고 맛있는 메뉴를 많이 팔길래 왔는데, 정말 잘 온 것 같습니다 음식도 전부 맛있고 카페 분위기도 아늑하니 좋았습니다 사장님께서 엄청 친절하셨습니다 재방문 의사 100! 맛있는 감성카페 찾으시면 추천드립니다', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '푸딩이 젤리 같은 푸딩이 아니라 쫀쫀한 푸딩이라 너무 좋아요🥰 라즈베리 푸딩 존맛.. 손님도 많고 바쁘실텐데 친절하고 최고최고', 11, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '카페가 너무 귀여워요 🥹🥹 인테리어 귀염 뽀짝하고 안에 굿즈들도 있어서 구경하기 조아요~~ 푸딩이랑 크로플도 넘 맛있었습니다😆😆', 105, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '드디어 먹은 푸딩 온탑! 푸딩의 진함과 탱탱함은 여전했다 시원 쌉싸름한 아메리카노 달달 부드러운 푸딩의 조합 후식 디저트로 제대로 마무리 했다', 12, 4, 'GOOD', SYSTIMESTAMP);
