INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '인테리어가 너무 귀여워서 좋아요 쿠키도 너무 귀엽습니다. 그리고 다른 카페랑 비교했을 때 가격도 좋은 편 같아요! 푸딩 종류가 많아서 좋아요', 40, 2, NULL, SYSTIMESTAMP);
