INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '가게가 아기자기해서 너무 예쁘고 사진도 짱잘나와요🩷 푸딩이랑 쿠키도 존맛탱이라 처음엔 ''귀여워서 어떻게 먹어ㅜㅜ'' 하다가 한입먹고 너무 맛있어서 바로 흡입했습니다ㅎ,, 12월에만 파는 초코트리푸딩 꼭 드셔보세요 말차맛 엄청 찐하게 느껴져서 최고예요... 최애푸딩집 등극했어요', 37, 10, 'GOOD', SYSTIMESTAMP);
