INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '딸기푸딩파르페 먹으러 와써요❤️ 근데 파르페가 생각보다 작고 귀여워요 헷 그리규 정수기가 고장나서 에스프레소 샷에다가 얼음만 받았오요 🥹ㅎㅎㅎ', 1, 10, NULL, SYSTIMESTAMP);
