INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '푸딩이 탱글탱글하고 쫀쫀하고 달달해서 완존완존 맛있어요! 대박이에요! 오늘은 친구랑 왔지만 다음엔 연인과 와보려구요! 강추강추', 45, 6, 'GOOD', SYSTIMESTAMP);
