INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오타쿠 투어하다가 우연히 봐서 들어왔는데 인테리어가 진짜 귀여워요ㅜㅜ 웨이팅할 때 카톡을 잘 확인해야해요!!!!! 완전 친절하시고 음식도 감성있고 너무 좋아요!!', 10, 6, 'GOOD', SYSTIMESTAMP);
