INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '주디마리 푸딩 지금까지 포장해서 먹어봤는데 처음으로 가게에서 먹어봤어요!! 가게가 넓고 좌석이 귀여워서 편하게 머물 수 있어용 😁 홍대에서 푸딩 먹고 싶을 때 추천합니다 편하게 있다갈 수 있어요♪(*^^)o∀*∀o(^^*)♪', 54, 14, 'GOOD', SYSTIMESTAMP);
