INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '푸딩 너무너무너무 먹고싶어서 주디마리로 왔어요!!!! 가게 외관은 아기자기한데 내부는 엔티크한 벽지... 넘 예뿌네요... 파르페도 예쁘고 맛있어요 재방문 의사 잇음!!!!!😍😍', 46, 5, 'GOOD', SYSTIMESTAMP);
