INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '동화같은 카페네요. 좋아하는 푸딩과 파르페의 조합이라니! 넘 완소에요! 크리스마스와 레트로 감성 낭낭한 주디마리에서 맛있는 디저트 즐기러 오세요! 쿠키와 도넛도 넘 귀엽네요.', 13, 6, 'GOOD', SYSTIMESTAMP);
