INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '분위기 좋은 카페라고 해서 와봤는데 너무너무 귀엽더라구요ㅠㅠ 푸딩 파르페도 이것저것 있어서 좋았습니다ㅎㅎㅎ 다음에는 다른 것두 시켜먹어볼려구요!☺️', 39, 2, 'GOOD', SYSTIMESTAMP);
