INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '카라멜 커스터드 푸딩이랑 라즈베리 푸딩, 블루소다, 곰돌이 밀크티를 주문했어욤 푸딩은 찰랑찰랑거리고 되게 탱글한데 입안에서 부드럽게 녹을 정도로 맛있습니당 카라멜 커스터드 푸딩은 카라멜 소스에서 메이플 시럽과 같은 달달한 향이나고 쓴맛이 전혀 없어욤 커스터드 부분은 크리미한 맛으로 많이 달지 않아서 좋았네욤 라즈베리 푸딩은 라즈베리 콩포트의 상큼한 맛과 톡톡 씹히는 식감이 재밌는데, 우유 푸딩의 부드럽고 담백한 우유 향과 넘 잘어울립니당 블루소다는 익숙한듯 신비한 맛으로 청량감있게 달달한데 탄산이 강하지 않아서 아이스크림 토핑과 잘어울릴거 같았어욤 밀크티도 얼그레이향이 부드러워서 맛있었네욤 사장님도 정말 친절하시고 아기자기하게 꾸며져 있어서 소녀감성 충전하기 너무 좋습니당 ㅎㅎ', 38, 5, 'GOOD', SYSTIMESTAMP);
