INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '너무 맛있었어요!! 인형들이랑 사진 찍기도 좋고 저는 특히 푸딩보다 저 곰돌이 보틀이 너무 탐나서 저걸로 마셨어요!!! 친절하게 얼음도 주셔서 시원하게 먹을 수 있었어요!! 푸딩은 라즈베리보단 기본이 더 맛있었던 것 같아요 🥹 담엔 우유푸딩을 먹어봐야지..', 14, 3, 'GOOD', SYSTIMESTAMP);
