INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '푸딩파르페가 너무너무 먹고싶어서 방문했어요 역시 유명한 이유가 다 있군요... 파르페 진짜 너무맛있게먹었어요 하... 또가고싶다 진짜 오직 파르페.만을 위해서라도 다시가고싶어요...(물론다른것도맛있었음) 푸딩이 생각보다 더 탱글했어요!! 망고아이스티도 생망고를 쓰셨나?? 말랑하고 달달해서 빨대로 호로롭 먹어져요 블루소다도 아이스크림 추가해서 먹으면 딱이에요...👍 글고 인테리어가 진짜 귀여웠어요', 16, 8, 'GOOD', SYSTIMESTAMP);
