INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '푸딩을 좋아해서 들어가 봤는데 안에 인테리어가 너무 귀엽고 예뻐서 먹는 동안 기분이 좋았어요!ㅎㅎ 그리고 푸딩 생긴 것도 귀여운데 맛도 만족스러웠습니다. 부서질 것 같아서 귀여운 쿠키는 못 샀는데 다음에 오면 꼭 사갈 거예요. 쿠키들도 그렇고 디저트들이 너무 귀여워요.ㅠㅠ', 76, 17, 'GOOD', SYSTIMESTAMP);
