INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '주디마리 매장에 직접 와서 먹어본 건 처음이었어요. 공간이 되게 아기자기하고 컵이랑 그릇도 귀여웠어요. 커스터드 카라멜 푸딩이 제일 맛있어요.', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '푸딩이 맛있어보여서 방문했는데 정말 맛있었어요!!😋 뿐만 아니라 인테리어도 너무 아기자기해서 구경하는 재미가 쏠쏠했어요🩷 우유푸딩과 커스터드 푸딩은 품절 돼서 못 먹어봤는데, 다음에 또 방문하고 싶습니다! 판매중인 굿즈들도 너무너무 귀여웠어요 인테리어에 공을 들이지 않은 공간이 없는, 동화책 속 같은 카페였어요🩷', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '주디마리가 홍대에 생겼다고 해서 방문해봤어요~~! 본점에서 먹었던 것처럼 다른곳에서는 느낄수없는 주디마리만의 쪼온득하면서 부드러운 그 맛... 너무 맛있었습니다...ദ്ദി◍•ᴗ•◍)', 7, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '근처 카페 찾다가 인테리어도 예쁘고 분위기도 좋아서 왔는데 아늑하고 수다떨기도 딱 조아요 다음에 또 홍대오면 와서 먹고싶어요🥰', 45, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '작지만 생각보다 테이블 많고 테이블간 거리도 나쁘지 않아요! 내부 넘 아기자기하고 귀엽고 디저트도 맛있어요💚 도넛세트 미니도넛 5개인데 추천합니다! 푸딩은 꼭 드세요. 밀도높은 단단한 푸딩인데 크리미함이 떨어지지도 않고 맛있어요. 커스터드푸딩은 너무 달지않아서 좋았고 민트초코푸딩 진짜 맛있었어요🥺', 80, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '-`♡´-푸딩을 사랑한다면 시키지 않을 수가 없다.-`♡´- 테이블 간격도 널널하고 각 자리마다 느낌도 다르게 꾸며 놓은 가게입니다. 화장실도 내부에 따로 있어서 좋아요. 직원분도 엄청 친절하십니다!', 37, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '라떼랑 푸딩프라페 먹었어요!! 원래 푸딩을 별로 안좋아하는데 여기 초코푸딩은 너무 맛있더라구요.....가게 분위기도 너무 귀엽고 아래에 깔린 시리얼도 너무 맛있었습니다!!!', 32, 3, 'GOOD', SYSTIMESTAMP);
