INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '잠시 주문을 받을 수 없는 상황이었음에도 친절히 상황 설명과 응대를 해주셔서 마음 편히 기다릴 수 있었습니다! 푸딩 너무 맛있어서 항상 푸딩하면 이곳에 왔었는데 더더욱 좋은 기억이 남아 다른 곳 못 갈 거 같아요💕', 88, 11, 'GOOD', SYSTIMESTAMP);
