INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '분위기도 좋고 너무 맛있어요 푸딩 조아하는데 또 올게요 !!ㅕ 근데 화장실 앞쪽 테이블 앉았는데 하수구 냄새..? 역한 냄새가 너무 심해서 오래 못 있었어요…. ㅠㅜㅜㅜㅜ 이건 좀 아쉬워요', 31, 9, 'BAD', SYSTIMESTAMP);
