INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '나왔다 내 인생푸딩집..................제가 3년전에 주디마리 하나만을 위해서 서울에서 광주까지 갔던게 어제같은데 이제 서울에도 생기고ㅠㅠㅠㅠ 너무 행복해요 그 어떤 푸딩집을 가도 주디마리만큼 맛있는 집이 없어요..... 일단 3년전부터 제 푸딩의 기준은 주디마리가 되어버렸어요ㅠㅠ 언제가도 항상 맛있어서 감동이에요... 서비스로 주신 푸딩도 너무 잘먹었어요!!!!!!!🍮 매번 시간 없어서 못왔는데 오랜만에 연휴에 방문했는데도 열려있어서 슈퍼감동.... 늦은 시간에 가는거라 걱정돼서 전화드렸는데 정상 영업한다고 하셔서 달려왔어요!!! 그릇도 너무 귀엽고 매장분위기도 귀엽고 아늑하고 푸딩이랑 소다는 진짜.... 천국이에요 내 인생맛집ㅠ 늘 번창하세요 사장님 시원한 연휴 보내시고 다음에 또올게요!🍮🍮', 47, 7, 'GOOD', SYSTIMESTAMP);
