INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '카페 안이 아기자기하고 이뻐요! 디저트들도 특이하게 이뻐서 다 먹어보고 싶은 생각이 드는 곳이었습니다. 포근한 분위기 속의 카페라서 마음이 편한 곳 같아요. 친구랑 약속 있으면 또 올 것 같아요!!!', 26, 10, 'GOOD', SYSTIMESTAMP);
