INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '우선 바깥에서부터 안쪽까지 인테리어가 너무 아기자기하고 예뻐서 진짜 제대로 눈요기했어요ㅜㅜ 합리적인 가격에 생망고 들어간 푸딩 파르페라니… 푸딩 맛도 넘 맛있어서 깜짝 놀랐고, 같이 주문한 밀크티가 고소하고 맛있었어요. 재방문 의사 200%', 23, 5, 'GOOD', SYSTIMESTAMP);
