INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '그 유명한 푸딩맛집을 드뎌ㅠㅠ 🩵🩵 합정간 김에 들렸는데 진짜 역대급 푸딩이에요.. 하도 맛잇다맛잇다해서 그게그거겟지 햇으나 그게그게아니네요 ㅋㅋㅋㅋ 인테리어컨셉도 독특하고 뭔가 사장님 갬성이충만한 느낌!!  아줌마가 가도 반겨주시고 포토존도 넘좋네요 ㅋㅋ 예쁘게 포장도 해주셔서 대량구매해왔읍니다~~!  번창하세용', 53, 16, 'GOOD', SYSTIMESTAMP);
