INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '여기 근처에 맛집 찾으러 왔다가 가게 인테리어랑 분위기가 신기해서 방문하게 됐어요☺️ 매장 전체적인 분위기는 되게 아기자기 하고 디즈니 여아 캐릭터가 살 것만 같은 분위기에 카페였어요! 메뉴는 직접 와서 드셔봐야 알 것 같고 (맛있어요!) 전체적인 분위기들이 마음에 들었습니다☺️', 36, 10, 'GOOD', SYSTIMESTAMP);
