INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '오늘 빵 땡겨서 근처 배회하다가 크로플이 3800원? 너무 저렴하길래 여기서 점심도 해결하고 업무도 해결하려고 들렀어요. 푸딩 맛집인건 알고 있었는데 크로플까지 쫀득바삭 맛있을줄이야... 주말에는 엄청 붐비는 느낌이었는데 오전에 방문하니 업무나 공부하기 좋으네요 ♥ 멜팅캣 고양이쿠키도 귀엽고 ㅎㅎ 근처 사는데 앞으로 오전에 자주 방문해야겠어요>.<', 63, 16, 'GOOD', SYSTIMESTAMP);
