INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '지나가다가 느낌이 좋아서 들어왔어요... 푸딩도 맛잇고 인테리어가 너무 귀여워요😍 직원 분들도 친절하셔서 좋네요 친구랑 와서 기분 좋게 잘 먹고 갑니다!!', 11, 2, 'GOOD', SYSTIMESTAMP);
