INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '주말에 방문했는데 사람도 많고 분위기 맛집 카페인가봐요 ㅎㅎㅎ 인테리어도 너무 이쁘고 주말 직원분들 다 너무 친절하시고 웃음이 가득하셔서 저까지 기분 좋아지는 하루네요 ㅎㅎㅎ 다음에 또 방문할게요!! 근데 진짜 푸딩 맛집입니다 여러분들…. 푸딩먹고 반해버렸어요 저..🍮 다음에 또 방문해야겠어요 !!!!', 3, 10, 'GOOD', SYSTIMESTAMP);
