INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '인테리어, 디저트, 음료 뭐 하나 안 예쁜 게 없는 곳이에요!! 특히 푸딩이 진짜 맛있는데다 사장님도 친절하셔서 담에 또 오려구요', 34, 8, 'GOOD', SYSTIMESTAMP);
