INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '🍮순우유푸딩: 말캉말캉하면서도 우유의 고소한 미가 살살나면서 혀로 눌러도 부셔지는 식감을 갖고 있다. 환장하게 달정도가 아니라서 단 거를 비선호한다면 이걸 추천한다. 🍮커스터드푸딩: 기본적인 그 맛. 일본편의점에서 파는 커스터드 푸딩과 다르게 살짝 더 단단한 느낌이지만 맛은 똑같다. 굳굳 🥄🥄🥄🥄재방문 의사가 있으나 카페에서 여유롭게 먹기보다는 포장하러 갈 것 같다. 화장실 깨끗하고, 직원분들도 친절하셔서 좋다.', 22, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '푸딩 너무 달달하고 점원분이 너무 상냥하셨어요~!!! 여럿이서 갔는데 대응도 친절하시고 너무 좋았습니다 재밌게 잘놀고 갑니다!', 36, 8, 'GOOD', SYSTIMESTAMP);
