INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '푸딩파르페만을 바라고 미친듯이 달려왔습니다.. 비주얼끝장나고요..크로플이 너무 부드러워용 바닐라라떼는 바닐라뿐인 달디달고달디단 음료구요 푸딩파르페도 달아서 이제 더이상 단맛을 제외한 맛을 느낄수없어요 요거트스무디나 커피와 함께드시는걸 추천드립니다❣️', 4, 0, NULL, SYSTIMESTAMP);
