INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '친구랑 홍대데이트로 왔는데 너무 만족스러운 디저트 카페였습니다...🥹 사장님이 직접 연구한 밀크티 푸딩이랑 파르페는 진짜 말해뭐해 최고입니다.. 꼭 딸기시즌 끝나기전에 딸시 파르페 드셔주세요🍓🍓🍓🍓', 76, 13, 'GOOD', SYSTIMESTAMP);
