INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '와보고 싶었던 푸딩 맛집! 주디마리 홍대점 🍮 인테리어가 너무 아기자기하니 귀엽고 바나나 푸딩 파르페 먹었는데 넘넘 맛있었어요~ 카라멜 커스터드 푸딩 하나 포장해서 집에서도 먹었는데 ㅜ 극락 ... ㅜ 또 먹고 싶어요! 사장님 번창하세요 <3', 21, 0, 'GOOD', SYSTIMESTAMP);
