INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '매일 지나가다가 봤는데 들어온 건 처음..  분위기가 키치하고 귀여웠습니다 😍 디저트도 많은데 딸기가 품절이라 안돼수 아쉬웟어요 ㅠㅠ 그래도 바나나누텔라+우유푸딩 필승..ㅠ 너무 맛있어요 소다는 처음 마셔봤는데 최고예요 🥺 매장도 예쁘고 사장님도 친절하시구 너무너무 좋습니다', 44, 6, 'GOOD', SYSTIMESTAMP);
