INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '주디마리 홍대점 두근두근 기여운 외관에 한번 심쿵 내부 인테리어도 또 한번 심쿵 갬성있는 홍대 카페!! 푸딩파르페도 맛잇구 시즌메뉴인 딸기푸딩도 굳굳굳 크로플로 바삭바삭 촉촉 맛잇어요!! 음료도 가성비 값~!~!😘', 68, 15, 'GOOD', SYSTIMESTAMP);
