INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '분위기 아주 좋고 인테리어도 완전 아기자기하구 이뻐용🥰 무엇보다 사장님덜 완전 친절 그 자체..😊 완전 민초파로써 민초 푸딩 주문했는데 완전 쫀맛이에용 커스터드 푸딩도 완전 맛 굿굿 부들 부들 맛 죠아용~🫠🫠', 30, 8, 'GOOD', SYSTIMESTAMP);
