INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '아기자기한 분위기와 친절한 사장님이 좋은 곳이예요. 문익점 푸딩을 먹으러 왔는데 먹기도 전에 기분이 좋은 가게예요😊 홍대역에서 안 멀어서 추천드려요🥰', 24, 7, 'GOOD', SYSTIMESTAMP);
