INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '파르페가 너무 이뻐서 방문하게 되었는데 너무 귀여운 쿠키들이 많아요!! 외관부터 너무 귀엽고 안쪽 인테리어도 너무 귀여워요ʚ ‪ᕱ‬ ‪ᕱ 주문 받아주시는 직원분도 너무 친절하셔서 너무 기분이 좋습니다!!ᙏ̤̫ 음료랑 디저트도 너무 귀여워서 힐링하구 갑니다!!˘ᗜ˘', 50, 4, 'GOOD', SYSTIMESTAMP);
