INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '문익점 푸딩으로 입소문 탈 때부터 먹어보고 싶었는데 이번에 홍대에 생겨서 드디어 먹어봤어요🍮🧡 탱글/쫀쫀 푸딩입니다. 기본 커스터드랑 순우유 당연히 맛있고, 초코가 의외로 진짜 맛있어서 또 먹고 싶고, 라즈베리는 순우유에 잼 올린거 같은데 텁텁함 없이 산뜻하게 맛있고, 민초는 살짝 취향탈 것 같아요. 홀린듯이 10개 넘게 결제하고 나왔어요..🫶 *1인 1음료 주문 필수인데, 커피 산미 없이 괜찮았어요.', 4, 7, 'GOOD', SYSTIMESTAMP);
