INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '푸딩 너무 맛있는데 푸딩 시켜도 음료 시키라고 하는게 좀 별로였어요 푸딩을 인원수보다 많이 시켰는데도요 그리고 매장에서 하수도 냄새가 좀 심해요ㅠ 포장이 베스트 직원분들은 친절하세요', 34, 2, NULL, SYSTIMESTAMP);
