INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '평일 점심에 가니 예약없이 입장했어요! 주디마리 푸딩은 처음 먹어보는데 너무 맛있었어요 인테리어도 귀엽고 직원 분들도 친절 하셔서 다음에 또 방문 할 것 같아요 .', 19, 10, 'GOOD', SYSTIMESTAMP);
