INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '압구정 갤러리아에서 처음 먹어보고 너무 맛있어서 요즘 중독됐어요ㅎㅎ 파르페 때문에 홍대점 들렀는데 웨이팅이 65분.. ㄷㄷ 맛있고 예쁜 카페에요', 111, 19, 'GOOD', SYSTIMESTAMP);
