INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '너무너무 귀엽고 파르페 너무너무 맛있오요… 🤤 가게 자체가 넘 아기자기 귀엽고 사랑스러워서 또 오고 싶어용 푸딩도 넘 맛잇오요… 🫳🫳', 6, 2, 'GOOD', SYSTIMESTAMP);
