INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '처음 방문한건데 공간이 너무 귀엽고 푸딩이 너무 맛있어요😭 탱글포동한 푸딩식감 좋아하시는 분이라면 무조건 방문해봐야 하는 푸딩가게예요ㅜㅜ 사장님도 너무 친절하셔서 기분 좋게 방문 했습니다>.<🩷', 44, 5, 'GOOD', SYSTIMESTAMP);
