INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '매장 너무 귀엽고 자리도 은근 많아용! 푸딩 생각 이상으로 맛나고 안 느끼해서 좋아요🫶 앞으로 홍대 놀러와서 디저트 먹고 싶으면 여기 올려고용💕', 23, 9, 'GOOD', SYSTIMESTAMP);
