INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '전에 팝업으로 알게되어서 이번엔 매장으로 찾아왔어요! 지금까지 제가 찾던 푸딩맛이라 너무 좋은 거 같아요ㅠㅠ (일본 푸딩과 유사한 맛,,🍮💛) 종류도 많고 이번엔 프라페도 먹고 갑니다 너무 맛있고 생각날 때 또 올 거 같아요ㅠ💜', 103, 24, 'GOOD', SYSTIMESTAMP);
