INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '푸딩 맛집이라길래 가봤는데 카페 내부도 진짜 아기자기 하고 이쁘고 푸딩도 🍮쫜득쫜득 탱글탱글하고 맛있어요!! 막 너무 달지도 않고 적당해서 물리지 않고 잘 먹을 수 있었어요!! 파르페에 올라가는 푸딩은 다른 맛으로 변경가능하니까 참고하시면 좋을 것 같아요!!😀😀', 19, 1, 'GOOD', SYSTIMESTAMP);
