INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '푸딩 생각 날 때마다 항상 오는 맛집.. 🧎‍♀️🫰🏻 부드럽고 푸딩하면 생각나는 바로 그 맛이에용~ 스토리 올릴 때마다 친구들이 항상 어디냐구 물어봐요 우리학교 앞에 문익점푸딩이 있어서 참 좋아요 ~.~ ♡', 6, 3, NULL, SYSTIMESTAMP);
