INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '너무너무 가고싶었던 주디마리~!! 서울에도 생겨서 좋아요 가게 입구부터 넘 아기자기하구 인테리어도 귀여운 분위기 완전 굳~♡ 푸딩은 명불허전이라 엄청 사갔어요🍮 카스타드, 초코 추천해요', 52, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '푸딩 좋아하는 사람들은 들어봤다는 주디마리가 홍대에 있다는 걸 오늘 알자마자 바로 다녀왔습니다! 엄청 기대하면서 포장해서 사왔는데 너무 젤리 같은 식감보단 좀 꾸덕한 푸딩을 좋아하는데 엄청 꾸덕도 아니고 딱 적당한 꾸덕함? 커스터드는 단거 안 좋아하는 사람들도 좋아할만큼 많이 달진 않았어요 시럽이랑 같이 먹으면 딱 적당한? 딱 뭔가 기본인 느낌 초코가 기대이상으로 너무 맛있었어요 ㅋㅋㅋ 보통 초코는 진짜 모 아님 도 인데 다크초코 좋아하는데 약간 그런맛? ㅎㅎㅎ 얼그레이는 첫 입에 조금 당황 ㅋㅋㅋㅋ 평소에 얼그레이, 밀크티 엄청 좋아하는데 조금 도전적인 맛? 얼그레이 맛이 완전 잘 나는데 푸딩으로 접하니 묘한 맛 다른 맛도 맛보러 재방문하려구요 푸딩이 세상을 지배한당 🍮', 46, 7, NULL, SYSTIMESTAMP);
