INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '두 번째 방문을 했어요! 평일이라 기다림 없이 바로 이용할 수 있었고 푸딩과 파르페가 너무 만족스러웠어요~!!!! 아기자기한 카페 분위기에 잘 쉬다 갑니당❤️👍', 46, 3, 'GOOD', SYSTIMESTAMP);
