INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '혼자서도 먹으러 올 정도로 맛있는 푸딩……. 기포 없기로 유명한 문익점 푸딩 광주에만 있을 때부터 먹으러 다녔는데 서울에 생겨서 너무너무 조음…✨', 55, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '2~30분 정도 웨이팅 하고 들어갔어요! 매장이 생각보다 넓고 인테리어가 아기자기 너무 귀여워요! 그리고 딸기 푸딩 파르페 너무 가성비 좋고 맛있어요❤️ 자주 올 거 같아요😍', 81, 14, 'GOOD', SYSTIMESTAMP);
