INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '말차푸딩  딸기푸딩  블루소다에  아이스크림 추가까지 ㅎ.   푸딩이 넘  예뻐서  먹는거에  시간이  걸렸다는 사실 ㅋ  분위기도  좋고  혼자  와서  먹어도   불편함없이. 편안하게 잘 먹고 왔어요. 맛은 설명 할 필요 없이 👍', 46, 2, 'GOOD', SYSTIMESTAMP);
