INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '디저트 맛있고 인테리어도 너무 이뻐요🥰 다음에는 다른 메뉴도 먹어볼려구 합니다!! 푸딩 좋아하시는 분들은 한 번쯤 와도 좋을 거 같아요~', 61, 11, 'GOOD', SYSTIMESTAMP);
