INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '주디마리 광주점만 있을 때 인스타로 배달만 시켜먹다 홍대점 생기고 처음 와봤는데 와 진짜 달달하고 느끼하지도 않고 맛있어요!! 생크림에 푸딩, 아이스크림 조합도 좋고 블루 소다도 시원하고 맛있어용 푸딩 가게는 주디마리만 올 것 같아용', 90, 11, 'GOOD', SYSTIMESTAMP);
