INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '말랑말랑말랑말랑 포근포근 😭 갈 수 없는 갤러리아 제외하고는 멀어서 아쉬웠는데 홍대점에 새로 생겨서 한 시간 반(그래도 왕복 세 시간 ㅎ...)으로 그나마 다른 지방 지역으로 찾아가는 것보다는 접근성이 편해진 것 같다 말로만 듣던 그렇게 맛있다던 푸딩 입문자도 기다리게 만든 언젠가 만나고 싶었던 주디마리 푸딩... 영상 안 찍는 사람인데 일부러 찍은 저 말랑포동 대박임 안에서 먹으려면 1인 1음료 필수래서 이건 모르고 갔다가 시킴 ㅎㅎ ㅠ 맛있으면 한두 개 더 사가야지... 🤩🍮☕️', 25, 1, 'GOOD', SYSTIMESTAMP);
