INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '크림이 아닌 탱글탱글한 푸딩이 너무 먹고 싶었는데, 너무 탱글탱글하고 부드러워요☺ 뒷맛이 깔끔한 느낌! 시즌한정인 딸기푸딩도 너무 맛있지만 커스타드 푸딩이 근본 그 자체!!', 38, 8, 'GOOD', SYSTIMESTAMP);
