INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '파르페도 너무 맛있구 분위기도 넘 조아써요-！！ 선곡도 좋구... 다음에 또 방문해서 다른 메뉴도 먹어보려구요!! 사장님도 친절하셨어요♥', 75, 18, 'GOOD', SYSTIMESTAMP);
