INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '너무 커여운 곳이에요...사장님 왕 친절하시고 스티커 산 거 꺼내서 보고 있었는데 사장님께서도 예쁜 스티커 가져오셔서 보여주시면서 자랑하시구 ㅠㅠㅋㅋㅋㅋㅋㅋㅋㅋ 넘 귀여웠듭니다 또 오고 싶은 곳🍮💕💕', 74, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '서울에 지점 없을 때 택배로 푸딩 종종 주문해서 먹던 곳이에요. 실제 매장은 처음 방문했는데 인테리어도 너무 귀엽고 푸딩은 말할 것도 없이 맛있어요ㅜㅜㅜㅜ', 15, 0, 'GOOD', SYSTIMESTAMP);
