INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '우잉 ㅠㅠ 인테리어 너무 귀여워여 ㅠㅠ 화장실 글씨마저 귀여운 곳 ... ♥ 인스타 느낌 낭낭 >_< 푸딩 종류도 다양하고 직원분들도 너무 친절하세요 !! 인형의 집에 온 것 같은 느낌 ✨❤️', 6, 4, 'GOOD', SYSTIMESTAMP);
