INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '친구가 여기 푸딩 맛있다고 해서 푸딩 포장도 하고 음료도 마시려고 왔는데 가게 인테리어가 일단 너무 예쁘고👀🩷 음료도 맛있을것 같아서 기대됩니다 ㅎ_ㅎ', 22, 3, 'GOOD', SYSTIMESTAMP);
