INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '젤라틴 푸딩집입니다 참고하세요! 인테리어 예뻐요 딸기푸딩파르페 먹으러 온 건데 딸기가 안 달고 구성도 별로였어요 ㅜㅜ 다른 파르페집 가세요 푸딩은 우유푸딩은 생각보다 우유맛이 안 진해서 별로였고, 초코푸딩은 초xx몽처럼 진해서 초코 좋아하면 딱 일 거 같아용. 모르고 방문했는데 개인적으로 젤라틴 푸딩은 불호고 젤라틴 안 들어간 부들부들 푸딩 취향이라 재방문 의사없습니다 웨이팅도 있어요 ... 🍮', 44, 1, 'BAD', SYSTIMESTAMP);
