INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '외관이 눈에 띄어서 남팅구랑 걷다가 구경만하자구 들어왔는데 푸딩이 넘나 맛있어보여서 시켰어용 직원분 넘나 친절하셔서 처음 방문했다니까 서비스 푸딩 하나 더 주셨어용 감사합니당💓', 36, 0, 'GOOD', SYSTIMESTAMP);
