INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '카페도 너무 예쁘고 라떼순이인데 라떼가 진짜 고소하고 넘 마싯서요.. ㅠ 합정카페 유목민이였는데 자주 오려구요옹 혼자오기도 친구랑 오기도 좋아용 🫶🏻', 11, 0, 'GOOD', SYSTIMESTAMP);
