INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '전에 있을 때도 편한 분위기에 맛있는 커피 잠봉뵈흐까지 있어서 자주갔었는데 옮기셨네요! 역시 좋아요... 특유의 편안한 분위기는 커져도 그대로네요.', 35, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대 2층 공간으로 확장이전한 LP카페🎶 작은 아지트같던 LP카페 바이앤드커피가 최근 2층 규모의 멋진 건물의 더 넓은 공간으로 이전했어요🥳 외국 주택에 온 듯한 이국적인 내부 공간, 화이트톤 인테리어로 화사한 기운이 감돌며 감각적인 음악을 들으며 쉬기 좋았던 카페! 준비된 LP는 금, 토, 일요일 마다 틀어주신다고 하니 LP 음악을 듣고 싶다면 주말에 방문해보세요😄', 44, 0, 'GOOD', SYSTIMESTAMP);
