INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '확장하기 전엔 빈티지한 느낌이었는데 지금은 살고싶은 유럽 주택같아요! 분위기 너무 좋고 커피 맛은 말모..!!! 친절하십니다 ㅎㅎㅎ 또 올게요!!', 36, 9, 'GOOD', SYSTIMESTAMP);
