INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '매장 이전 전부터 라떼가 맛있어서 진짜 자주 갔는데 새로 오픈한 매장 진짜 넓고 해도 잘 들고 넘넘 좋습니다🥹💛💛 커피 맛은 말뭐말뭐 다들 바이앤드라떼 드세요', 3, 10, 'GOOD', SYSTIMESTAMP);
