INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대에 이런 느낌있는 카페❤️❤️ 너무 좋아요~~~ 크로플 위에 엑설런트 너무 사랑하고요💓 치즈케이크도 꾸덕한데 많이 안달고 맛있어요🔥 에스프레소 판나 캐슈넛 밤크림도 쌉살부들고소하니 좋았고 아아도 산미없이 너무 좋았어요~ 공간 분위기 너무 좋고 남지친구랑 재밌게 이야기 도란도란하며 잘 머물다 왔어요~ 바이앤드커피 최고👍', 74, 15, 'GOOD', SYSTIMESTAMP);
