INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어며 디저트 맛이며 커피까지 정말 모든게 완벽했던 곳!! 특히 고소한 우유맛이 진하게 느껴지는 라떼는 왜 이곳 시그니처 메뉸지 알겠더라구요 완전 라떼 맛집🩵🩵라떼 마시고 싶을때 마다 방문할거 같아요🥰', 11, 10, 'GOOD', SYSTIMESTAMP);
