INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '사장님이 바이닐 LP판으로 직접 선곡해 주는 아늑한 감성카페! 라떼와 디저트류가 맛있어요. 인테리어 이쁘고 노래도 좋아서 여유롭게 시간 보내기 좋네요. 노래 듣다가 궁금하면 카운터 옆에 꽂혀 있는 앨범 보면 됩니다', 19, 10, 'GOOD', SYSTIMESTAMP);
