INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '카페 분위기 너무 좋는거 아니냐구요~ 공간이 넓지는 않은데 뭔가 좁다는 생각은 하나도 안드는것 같아요 인테리어 갬성 터져서 구경할것 투성이입니다 엘피판 틀어주셔서 더 느낌있는것 같아요 귀하다 귀해 엑셀런트 크로플 주문해서 커피랑 했는데 크로플 바삭하니 너무 맛있었어요 시그니처 커피도 막 달기만 한게 아니라 고소한 맛이 깊게 올라와서 독특하고 매력적이였어요👍', 45, 1, 'GOOD', SYSTIMESTAMP);
