INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여기 초당옥수수라떼 엄청나요 라떼달달하고 고소하고 맛있어요! 위에 올라간 옥수수는 좀 신기한(?)맛 이었는데 제 취향은 아니었어욬ㅋ 파운드케익은 정말 맛있고 달달해서 기분좋아졌어요 그리고 직원분이 친절하셔서 더좋았구요', 35, 1, 'GOOD', SYSTIMESTAMP);
