INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '합정에 볼일보러갔다가 갈증해소하러간 카페 이른 아침 부터 손님이 많길래 너무 궁금했는데 역시 아아먹자마자 맘에 쏙들고 아기자기한 가게안이 너무 힙하고 예쁜듯 사장님도 예쁘신데 친절하기까지하니 더맘에들도 깨알소품들이 디저트와 커피나오기전에 구경하기좋고 잠봉베르에 아아먹엇는데 넘 맛잇으 ~ 치즈케잌에 라떼도 너무 잘어울려서 모두 맛잇는걸로 ~ 조만간 근처가면 또먹어야지~', 94, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '합정역카페~합정역디저트카페 바이앤드커피!커피도 맛있고 잠봉뵈르 샌드위치 바스크치즈케이크 디저트맛집 카페답게 디저트 가성비 좋고 맛있네요', 27, 2, 'GOOD', SYSTIMESTAMP);
