INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '바이앤드커피 시그니처 커피가 찐이에요❤️ 디카페인으로 먹어도 존맛이에요 ㅠㅠ 산미없고 고소하고 깊은 유크림맛! 찐으로 맛있는 커피 ❤️ 바스크 치즈케이크는 꼭 드셔보세요👍👍👍 개인카페지만 오래머물기 좋았어요!! 조만간 커피마시러 또 가야겠어요 🧐 (테이크아웃은 천원이나 할인)', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '사장님은 맛잘알 찐천재이신게 분명합니다 음료나 디저트나 진짜 너어어어어무 맛있어요!! 바이앤드라떼는 시그니처딥게 맛있었는데 바이앤드커피만 세잔 연속 먹고싶을만큼 정말 찐찐으로 맛있었어요!! 디저트도 비주얼 다 미쳤고 맛도 미쳤으니 합정가면 바이앤드 무조건 가세요!!!', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '평소 커피 안먹고 먹어도 맛 그닥 모르겠는 사람인데, 여기서 바이앤드라떼 한번 먹어보고 일주일에 한 번은 먹으러 와요😋😋 고 카페인을 못먹어서 디카페인으로 했는데도 맛있습니다!!!! 뭔가 라떼인데 달진 않은데, 고소하고 달달 할랑말랑 이라고 할까요…🥺 우선 먹으러 한 번 와보세요.', 58, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '이 근처 자주 지나가는데 이런 까페가 있는 줄 몰랐어요. 커피 맛있고, 바리스타분 굉장히 친절하십니다. 더운 날이었는데 에어컨 빵빵하게 틀어주셔서 너무 시원했고, 레코드 가게를 연상시키는 인테리어도 독특해요. 작지만 대부분 테이크아웃 손님들이어서 자리는 여유가 있는 듯 합니다. 다음에는 매장에서 먹어보고 싶어요.', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '로투스에  캐러맬소스 가득 뿌린 치즈케이크는 처음 먹어봤어요! 카페가 쪼꼬맣긴 한데 인테리어 넘 이쁘고 조명도 딱 아이폰으로 찍으면 예쁜 조명💡알바분들도 넘 친절하시구 얘기 나누기도 좋았어요🤓🖤', 40, 8, 'GOOD', SYSTIMESTAMP);
