INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '맛있은 커피가 마시고 싶어서 골라 들어왔는데 운좋게 라떼맛집을 찾았네요~ 아아는 조금 연한 느낌이 있어요! 바스크치즈케이크는 카라멜향이 진하게 나요!', 6, 6, 'GOOD', SYSTIMESTAMP);
