INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '음료 너무 맛있어요! 전에는 커피 마셔봤는데 커피가 너무 맛있어서 에이드도 맛있을것 같아서 이번에 시켜봤어요 역시 실망시키지 않음🤤 분위기는 언제나 좋구 이뻐요!!!', 60, 17, 'GOOD', SYSTIMESTAMP);
