INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '인테리어에 신경을 많이 쓴 느낌. 특히 인테리어용 화분 흙이 원두콩이었던 부분 너무 좋았다. 딥 초코라떼 (ice) : 초코맛이 덜하진 않지만 조금 더 달면 좋을 것 같음.', 52, 18, 'GOOD', SYSTIMESTAMP);
