INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '가장먼저 가게가 이뻐서 사진이 정말 잘나와요! 사장님도 너무 친절하시고 무엇보다 커피가 너무 맛나요!!흑임자 파운드 케잌 너무 맛있어요~! 흑임자 크림올려주시는데, 직접만드셔서 그런지 담백하고 커피랑 잘 어울려요!!저는 시그니쳐 커피 먹었는데, 라떼 좋아하시면 추천드립니다!!! 😁👍', 52, 13, 'GOOD', SYSTIMESTAMP);
