INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '카라멜숏이 달달꼬소한 게 맛있어서 또 먹으러 왔는데 커피 말고 다른 메뉴도 너무 맛있어요. 자몽에이드랑 로얄밀크티 완전 추천! 그리고 사장님 너무 친절하세요 :)', 64, 13, 'GOOD', SYSTIMESTAMP);
