INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빨콩커피 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '전부터 신경쓰였던 블루베리우유 마셔봤는데 심하게 달지 않아서 좋았고 미리 섞어서 메뉴가 나와서 바로 마시기 좋았습니다 사장님도 매우 친절하시고 빙수메뉴가 인기 많아보여서 다음엔 빙수를 먹어봐야겠어요ㅎㅎ 완전 추천합니다', 31, 5, 'GOOD', SYSTIMESTAMP);
