INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빨콩커피 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '연트럴파크 지나다가 날이 너무 더우니까 빙수가 눈에 띄어서 들어갔는데 빙수 이렇게 맛있어두 되나요~? 각자 취향에 맞게 1인 1컵빙수~💕 솜사탕빙수 같구만🙂🤣', 42, 4, 'GOOD', SYSTIMESTAMP);
