INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빨콩커피 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '약속이 생겨서 잠시 들른곳인데 산미있는 맛있는 커피를 2000원에 먹었네요 집만 가까우면 매일 오겠어요 남자직원분 굉장히 친절하세요', 44, 10, 'GOOD', SYSTIMESTAMP);
