INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '서울 3대 도넛 맛집! 올드페리도넛😋 우유크림을 먹고 싶었지만ㅠㅠ 품절이슈로…. 두번째로 먹고 싶었던! 크림브륄레 도넛 먹기☺️ 안에 크림이 엄청 달달구리한 맛! 위에 코팅은 완전 빠삭달달♡ 매장 안은 완전 깨끗하고! 넓고 시원해서 너무 좋아용 모임하러 많이들 오시는 거 같더라구요!!', 7, 9, 'GOOD', SYSTIMESTAMP);
