INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '피넛도너츠가 맛있는 올드페리도넛. 식감이 쫄깃하고 묵직한맛. 아메리카노와 잘 어우러져요.주말이라그런지 테이블이 꽉 찼네요.맛있고 달콤한 도넛예요.', 8, 1, 'GOOD', SYSTIMESTAMP);
