INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '매번 궁금했는데 마침 근처에 지나가게 되서 테이크아웃해서 먹어봤는데 버터피스타치오 꾸덕하고 달콤하고 너무 맛있네요 😋💚 다음엔 다른 도넛 먹어보려는데 기본 도넛 종류가 다 솔드아웃이라 아쉬웠어요 🥲', 95, 19, 'GOOD', SYSTIMESTAMP);
