INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '컬리에도 있어서 고민하다가 직접 방문 했는데, 괜히 올드페리 도넛이 아니에요! 비싸긴한데 그만큼 크기도 크고 안에 크림도 충분하며 당충전 제대로 됩니다. 사이즈가 크다보니 개별 포장 해주시더라구여~! 맛이 섞이지 않아 좋아요!😋', 33, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '매징 마스코트가 너무 귀여워요. 지인 추천으로 우연히 알게 되었는데 인생 도넛이 되었습니다. 지방사는데 서울 올때마다 꼭들러요 👍', 17, 5, 'GOOD', SYSTIMESTAMP);
