INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '내 입맛에 가장 잘 맞는 올드페리도넛. 나른한 오후에 달달한게 생각날때 먹기 좋은 피스타치오. 우유의 고소함이 가득한 우유크림도넛. 도넛 안에 달콤한 크림이 가득해서 음료는 깔끔한 아메리카노와 함께하는것을 추천합니다.', 47, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '전처럼 줄 안서는게 너무 좋음... 🍀 다양한 도넛 많이 먹었는데 올드페리만에 빵쫄깃함은 남다른거같아요! 당연히 달지만 커피랑 먹으면 꿀맛💓👍', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '원래 자주가던 홍대ㅎㄹㅇㅈㄹ 도넛집이 없어져서 급하게 여기로 들어왔습니다 와서 먹고 친구들한테 사진보여주다가 유명한 곳임을 그때 알게 되었습니다 ㅋㅋ 어쩐지 맛있더라구요 . 일단 반죽 빵이 쫀득하고 맛있어요 제 입맛엔 피스타치오도넛이 특히 맛있었습니다 우유도넛도 호불호없을 맛이긴한데 좀 달아용 매장도 넓고 자리도 많아서 여유롭게 먹기 좋습니다 다만 2층은 히터를 안 트시는지 넘 추워서 외투입고있었네요  ㅠㅠ 1층은 따뜻해요', 6, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '크리스마스에 술 마시고 먹을 디저트로 샀습니다. 멀리서 오는 지인이 있는데, 거긴 올드페리는 없다고해서 ^^ 저도 오랜만에  먹었는데 단맛이 뒤통수를 때리네요... 일단 맛있어요, 빵은 얇은데 쫀득~ 크림이 고급스럽게 단 느낌. 비싼값을 충분히 합니다.', 29, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '연남동 거닐다가 대형카페라 시원할 거 같아 들어왔어요 ㅎㅎㅎ 크림브릴레, 쿠앤크, 피스타치오 크림 등 도너츠 종류가 정말 다양하고 커피가 맛있어요! 도너츠에 크림이 듬뿍 들어있어 묵직하고 달콤합니다 🍩 시그니처 곰돌이가 너무 귀엽고, 주황색 색감이 눈에 띄는 인테리어가 독특해요~ 테이블이 많아 자리가 널널하고 2층엔 노트북할 수 있는 공간이 있습니다 :) 도너츠를 박스채로 구매해가시는 포장 손님들도 많았어요!!', 77, 13, 'GOOD', SYSTIMESTAMP);
