INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '던킨이랑 올드뻬리는 제가 가장 좋아하는 도넛집 중에 하나에요. 특히 올드 페리는 크림이 많이 들어가 있는데도 느끼하지 않고 맛있어서 좋아요', 94, 19, NULL, SYSTIMESTAMP);
