INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '아이와 둘이서 방문해서 맛있는 도넛먹으며 좋은 시간 보냈어요😊 사장님도 친절하시고 매장도 넓고 깔끔해서 더 좋았어요! 다음에는 다른도넛먹으러 재방문해보려구요🤩', 40, 3, 'GOOD', SYSTIMESTAMP);
