INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '새로운 도넛 가게가 오픈해서 들려보았습니다.가정집을 개조한 곳인데 과거에는 일반 카페였었는데 새로운 도넛 가게가 들어왔네요. 시간이 없어 포장해서 집으로 가져왔습니다.  오~~~ 각 도너츠마다 반죽이 일단 다릅니다. 크림치즈도 제법 무게감이 있었고 적당한 당 조절과 식감이 정말 특이 했습니다. 꽤 내공이 있는 레시피이네요. 크림의 점도와 향이  아주 발란스 있게 느껴지네요. 도너츠 맛집 인정합니다.', 39, 4, 'GOOD', SYSTIMESTAMP);
