INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '주말엔 사람 많았는데 평일은 여유롭네요~ 솔직히 음료도 도넛도 무난해요 버터 피스타치오는 많이 달달해요~~ 어차피 도넛은 당충전이니 ~~ ㅎㅎ 매장이 넓고 실내 실외 다 예뻐서 사진 찍기 좋아하시는 분들께 좋은것 같아요', 75, 13, 'GOOD', SYSTIMESTAMP);
