INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '주말 오후에 방문해서 그런지 품절된 도넛이 많았어요. 특별한 맛은 아니고 더울 때 잠시 들어와서 쉬기 좋네요. 다른 유명 도넛집과 다르게 도넛 주문하면 음료는 하나만 주문해도 되니까 부담이 없어요.', 60, 15, NULL, SYSTIMESTAMP);
