INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '🍩 올드페리도넛 연남점 친구 추천으로 우연히 가게 된 도넛집 마감시간이 가까워져ㅠㅜ 재고가 많이 없었지만 보스턴 크림 도넛 맛도리 발견🫶 크림 진짜 왕가득하고 겉은 초코맛 진해서 조화가 좋아요😊', 66, 12, 'GOOD', SYSTIMESTAMP);
