INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '어제 월요일 오랜만에 국회의사당역갔다가 집으로 가기전 홍대에 올드페리 도넛에 처음가서  초코크런치와 피스타치오 버터 2가지 샀습니다 ㅎㅎ 초코크런치도 적당히 달고 맛있었고 아침에 피스타치오 크림도 맛있게 가족들과 먹었답니다~ 다음에는 피넛버터 도전합니다~', 97, 26, 'GOOD', SYSTIMESTAMP);
