INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '올드페리도넛 집 가까이 생겨서 친구 선물 사러 갔는데, 진짜 분위기 좋고 예쁘게 잘 꾸며놓았더라고요! 직원분들도 친절하세요~맛은 뭐 !! 피넛버터 무조건임🍩😭', 62, 16, 'GOOD', SYSTIMESTAMP);
