INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '올드페리 도넛 먹고 싶어서 찾아왔어요😃💜 한남동에 있는 올드페리보다 연남동이 훨씬 더 넓고 쾌적하며 인테리어가 멋져요👍🏻 👍🏻👍🏻 우유크림도넛, 피넛버터 먹어봤는데 꿀맛🥰🥰 다음 번에 또 오고 싶고 다른맛으로 먹어보고 싶네요~', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '매장 넓고 좋아요. 커피는 맛있는 산미있는 커피는 전혀 아님. 단 디저트 진짜 잘먹는 편인데 필링이 맛있게 단게 아니라 그냥 너무 달아요. 근데 도넛이 엄청 쫀쫀해서 재방문하면 차라리 베이직 맛으로 먹을 긋', 4, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '오리지널은 잘 모르겠구 보스톤크림 크림브륄레 피넛버터 버터피스타치오 우유크림도넛브래드 코코넛 전부 맛있어요 안에 크림이 듬뿍 들어있고 빵 자체도 맛있었던거같아요!', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '솔직히 전 올드페리보다 노티드파지만ㅠ 가끔은 올드페리의 묵직한 맛이 땡기거든요. 맛있게 먹었어요. 근데 다 도시락박스에 담아주시는건 아닌지 하나만 담아주시고 하나는 그냥 종이(?)에 감싸주셔서 들고가느라 조금 손이 시려웠다.. 당연 둘다 도시락박스일줄알고 봉투 필요없다했는뎅..', 3, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), 'Omg~~~ 나으 최애도넛~!!! 연남에도 생겨서 너무 좋음♡ 이제 가로수길까지 안가도 됨. 갠적으로 코코넛 도넛이랑 피스타치오가 탑이고 피넛버터도 은근 맛있고.. 참고로 떡볶이같은 매콤한걸 먹고 와서 쌉쌀한 아메리카노랑 먹으면 도넛을 최상으로 즐길 수 있음! 글구 매장이 주황 파랑해서 어울리는 옷 잘 입고가면 텐션 끌어올린 사진 찍을 수 있음.', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '도넛 사진은 매장 메뉴 사진과 정말 똑 같습니다. 싸이즈도 크고 가격에 맞도록 크림과 버터가 이렇게 넣어도 될까? 싶을 정도로 만족스러워요. 제가 생각하는 시그니처는 당연히 우유크림도넛브레드에요. 이 우유크림은 아무도 흉내 못내요. 다른 빵과 같이 먹어보면 금방 아네요. ‘고급’이란 이럴때 쓰는 단어라는 걸 알게됩니다. ㅋㅋ 피넛버터는 한통을 때려부은것 같아요. 시중 피넛버터 가격을 생각해보면 도넛가격도 합리적이다~ 싶어요. 시그니처 4개중 이 두개가 가장 맛있네요! 매장이 넓고 깨끗하고 유니크하답니다. 항상 포장만해서 아쉽네요~ 이제 안 먹어본 코코넛, 크림브륄레, 화이트초코세사미, 다음 방문에 만나보려고요~', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '올드페리도넛을 연남에서도 볼 수 있다니 넘 좋아요! 버터피스타치오, 피넛버터, 크림브륄레 너무 너무 맛있음! 커피랑만 어울릴 줄 알았는데 우유랑 진짜 잘어울림 ㅋㅋ 너무 줄서거나 테이크 아웃만 되는데가 많아서 아쉬웠었는데, 여기는 독채건물이라 장소자체도 넘 예쁘고 인테리어도 미국미국스러워서 사진찍기도 좋고 친구들이랑 앉아서 얘기하고 놀기에도 넘 좋았어용! 지나갈일 있음 무조건 들려야함!', 48, 7, 'GOOD', SYSTIMESTAMP);
