INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '드디어 연남에 올드페리도넛이!! 용산이나 한남동 갈때 먹어보고싶었는데 항시 빠른품절이라 못먹었는데 드디어 먹어봤습니다!! 전 노티드보다 더 맛있게 느껴지네요~', 22, 1, 'GOOD', SYSTIMESTAMP);
