INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '가게 골목 입구와 간판, 네이버 메뉴판에 제일 싼 크레페가 4900원이길래 찾아갔는데 제일 저렴한 메뉴는 7900원임. 자꾸 제일 비싼 메뉴 시켜 먹으라고 유도함. 영어 못하는 거 알고 7900원짜리 9900원으로 가격 부풀려서 결제하려고 함. >결제시도 했는데 내 카드에 잔액이 부족해서 못하게 됨. 잔액 부족 알림이 뜨기 전까지 9900원으로 결제하고 있었다는 걸 몰랐음. 크레페 시트도 직접 굽는 게 아니라 그냥 꺼내서 불판에 올려두고 데워서 주는 게 끝임.', 10, 9, 'BAD', SYSTIMESTAMP);
