INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '빵 종류도 많고 맛있어요! 매장도 1층 2층 좌석이 많아서 좋아요! 직원분도 친절하시고, 빵도 데워주셨어요😋 매장 음악은 의외로 힙합이 나왔어요! 그래서 수다떨기에도 부담없는 분위기예요!', 27, 2, 'GOOD', SYSTIMESTAMP);
