INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '배달로 시켜먹었던 곳인데 방문은 처음이에요! 여기 소금빵이 진짜 맛있어요 ㅠ 풍미가 진짜 좋아요!! 다른 빵들도 먹어봤던 거 다 맛있고, 전 커피를 못마시는데 디카페인도 있고 주스류가 많아서 좋아요. 매장 넓고 쾌적하고 사장님도 친절하시니 완전 추천입니당', 53, 14, 'GOOD', SYSTIMESTAMP);
