INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '합정역카페 올라운드 커피 멜버른 아이스커피와 아몬드 크루아상 맛있어요 매장이 넓고 나오는 음악도 좋고 직원분들이 넘넘 친절하시네요 모임하기에도 좋아보여요☺️', 27, 2, 'GOOD', SYSTIMESTAMP);
