INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '수박주스 6,500원 케일 파인 애플쥬스 6,500원 뺑오쇼콜라 4,500원 크루아상 4,000원 영수증 리뷰 소금빵 까지 여기서 도보 한 3분 거리에 카페폴리인가 거기랑 같은 사장님이신지 메뉴가 똑같음 카페 이름만 다르지 사람이 둘다 엄청 많은데 서울치고 괜찮은 가격과 깔끔함이 이유인듯 일단 더운데 이곳은 아주 시원하단거임 빵도 중상타침', 22, 0, 'GOOD', SYSTIMESTAMP);
