INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '데이트 겸 남편과 찾아간 올라운드커피!! 입구에 들어서자마자 너무예뻐서 눈이가네요~ 초록초록한게 물소리도 졸졸 들리구요ㅠㅠ 힐링 빵은 진짜 다맛있게생겨서 너무고민됐어요!! 소금빵이랑 크림브륄레 소금빵 두개 먹어봣는데 그냥 소금빵 진짜 너무맛잇어요ㅜㅜ 크림브륄레는 크림이 많아서 느끼한 부분은 있엇지만 그래도 존맛탱❤️❤️ 팥빙수를 사랑하는 남편은 진짜 맛잇다고 하네요!! 연유랑 팥을 넉넉히 더 주셔서 마지막까지 맛잇게 먹엇어요:)', 87, 18, 'GOOD', SYSTIMESTAMP);
