INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '가게 분위기와 소금빵 배너에 이끌려 들어온 곳입니다. 들어오자마자 우와 우와 남발하면서 딱🤩이 표정으로 빵 구경했네요 ㅎㅎ 정말 다양하고 맛좋아보이는 빵들이 한가득이라 빵순이로서 오늘 최고로 행복한 순간이었어요. 시식 코너도 있어서 사장님의 센스를 엿볼 수 있었습니다. 직원들 외모도 출중하시고,아주 친절하세요 송파구에도 생겼으면 좋겠네요! 다음에 합정에서 약속 잡히면 무조건 여기 재방문 입니다 ㅎㅎ', 47, 8, 'GOOD', SYSTIMESTAMP);
