INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '서울 나들이 왔는데 우연히 지나가면서 이뻐보여서 들어왔는데 더 이뻐서 만족해요!! 소금빵이 일단 기본적으로 넘 맛있어요!! 추천드려요~~👍', 7, 1, 'GOOD', SYSTIMESTAMP);
