INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '소금빵 너무 좋아하는데 지난번에 왔을때도 맛있어서 또왔어요 다른데는 항상 소금빵 품절인데 여긴 워낙 많이 계속 만드시는 것 같고 종류도 너무 다양해서 좋아요.... 공간도 엄청 넓고 카공하기도 괜찮아서 진짜 저만알고싶은데 너무 조아요 아무튼 다만 커피는 원두 고를 수 있는데 올라운드 원두는 좀 탄맛 많이 나요 다른건 안먹어봐서 모름 암튼 빵이너무 맛있어요 노래도 좋아요 그냥 여기 살고싶러요', 20, 8, 'GOOD', SYSTIMESTAMP);
