INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '합정역에서 가까워서 들어온 카페였는데 넓고 쾌적하고 무엇보다 빵이 지이이이이이인짜 많아요🥐 소금빵이 빠삭 쫀듯해서 맛있게 먹고 크림소금빵 추가로 시켜먹었는데 그것도 맛있었어요!!!! 다음에 다른 빵도 먹으러 오고싶어요😋', 38, 3, 'GOOD', SYSTIMESTAMP);
