INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '빵 종류가 정말 정말 많아요 !! 크기도 작지 않아서 대식가로서 굉장히 만족 ,, 제가 커피를 잘 안 마셔서 커피맛이 어떻다 말하기는 어렵지만 ..! 빵은 종류도 많고 크기도 커서 만족입니다! 치즈케이크 양 짱 많아여…!', 24, 0, 'GOOD', SYSTIMESTAMP);
