INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '합정 분좋카🍀 올라운드 커피 넓어서 더운데 안기다리고 바로 들어왔어요 🙌 디저트 종류도 많고 음료도 맛있어서 좋았어요 ㅎㅎ 특히 영업도 늦게까지 해서 친구들이랑 대화하기 조아요🥳 합정역에서 가까운 카페 찾으시면 추천합니다', 31, 6, 'GOOD', SYSTIMESTAMP);
