INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '합정역에 있는 올라운드커피 분위기며 맛!!!  하나도 빠짐없이 굿이네요 ㅎㅎ 빵도 종류가 많아서 굿입니다 ㅎ 플랫화이트는 달지않고 커피맛이 진해서 완전 굿굿!!! 아몬드크루와상은 고소함의 극치입니다 앙버터 소금빵은 깨듬뿍 번이라 눈으로도 감동할듯요 ㅎ', 90, 12, 'GOOD', SYSTIMESTAMP);
