INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '풍부한 커피 크레마가 기대를 부풀게 하더니 역시 넘 맛있네요!!! 넘버원 올라운더 원두인데 강추~~~ 케이크종류가 다양하지 않아서 아쉽지만 빵도 다 맛있고 근처에선 지하도 있고 넓은편이에요^^', 46, 3, 'GOOD', SYSTIMESTAMP);
