INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '커피랑 디저트 둘 다 맛있어요! 매장이 넓어서 옆테이블이랑 따닥따닥 붙어있지 않아서 너무 좋았어요😊😊 다음에 또 오려구 저장도 해놨습니당🫶', 31, 8, 'GOOD', SYSTIMESTAMP);
