INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '주변에 공연보러 왔다가 인테리어가 넘 이뻐서 들어가게 됐는데 인테리어 역시 너무 이쁘구! 음료도 너무 맛있었네요 사진 맛집!! 소금빵도 왕창 사갑니당 늦은 시간에 다시 들렸는데 서비스도 주시고ㅜㅜ 사장님 직원분 너무 친절해요 ㅜㅜ 🩷🩷', 15, 7, 'GOOD', SYSTIMESTAMP);
