INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '소금빵 뿐만 아니라 모든 빵들이 뭘 선택하든 🙌근본있는 맛🙌 커피도 원두를 고를 수 있어서 좋았는데 맛까지 좋아서 입이 너무 즐거웠움⭐️ 집에갈 때 아쉬워서 보틀까지 줍줍해버렸당..👍 개인적으로 크림브륄레 소금빵 꼭 드셔보시길..!!! 홀에서 먹고 또 빵을 포장해가니 소금빵1개 서비스까지👍 감사합니당🫶', 35, 8, 'GOOD', SYSTIMESTAMP);
