INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '1층 외에도 지하 1층도 있어서 공간이 넓습니다! 쾌적하게 쓰기 좋고, 디저트/베이커리 종류도 많아요. 음료도 달달하니 맛있게 먹었어요~', 82, 18, 'GOOD', SYSTIMESTAMP);
