INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피와 디저트 모두 맛있는 카페는 드문데 올라운드커피는 두 개다 만족스러운 곳임. 소금빵, 베이글, 크로와상 샌드위치 추천합니다. 즐겨마시는 플랫화이트도 넘 맛있어요🤗', 46, 4, 'GOOD', SYSTIMESTAMP);
