INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '친구 추천으로 왔는데 생각한 것 보다 더 좋았습니다. 소금빵 종류가 이렇게나 많고 맛있다니 완전 전문점 수준이고 직원분들이 모두 친절했어요!', 7, 2, 'GOOD', SYSTIMESTAMP);
