INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '퇴근길에 저녁으로 가족이랑 먹을 겸 들렸습니다. 규칙적으로 들린 게 아니다보니 매번 뵙는 분들이 달라졌는데, 여기서 뵌 직원분들은 다들 친절하셨습니다☺️ 빵도 늘 맛있구요! 빵순이라 빵 먹는걸 좋아하지만 여러 차례 들린 곳이 몇 안 되는데, 그중 하나가 올라운드커피예요! 카페 내 분위기도 좋아서 공부하기 좋고, 편히 쉬기 좋아요. 다음에 또 빵 사러 갈 예정입니다!', 104, 22, 'GOOD', SYSTIMESTAMP);
