INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '소금빵 좋아하는 사람으로서 들어와서 눈 돌아간 곳입니다😭🥹 소금빵 종류가 이렇게 다양하다니 명란감태랑 크림브릘레 소금빵 💕💕🥰 재방문해서 모든 빵을 맛 보고 싶은 곳입니다ㅠㅠ 커피도 향 너무 좋구 바틀로 파는 커피도 있어서 최고입니다☕️😃. 또또또 올게요!!', 20, 10, 'GOOD', SYSTIMESTAMP);
