INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '베이글 소금빵 등등 다 미친맛입니다 우연히 소금빵 선물 받아서 알게된 곳인데 찾아오기까지 했습니다!! 짱짱 와서 드셔보세요 크림브륄레 소금빵 미쳤습니다', 4, 1, 'GOOD', SYSTIMESTAMP);
