INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '베이커리 종류도 많고 맛있어보여요! 인테리어도 예쁘네요! 테이크아웃으로 사가는데 다음번엔 매장에서 먹어보고 싶은 곳이네요 :-)', 15, 7, 'GOOD', SYSTIMESTAMP);
