INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '소금빵 종류가 이렇게 많은 카페는 처음 봤어요! 다는 못 먹어봤지만 먹어본 거 다 맛있었어요...! 누룽지트러플소금빵 조합 어떻게 생각하신 거죠? 사장님이 맛잘알이신가봐요 커피랑 논커피 음료 종류도 많고 구움과자도 많아요. 디저트 좋아하시면 적극 추천드립니다', 27, 9, 'GOOD', SYSTIMESTAMP);
