INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '첫방문!! ㅎㅎ 분위기 너무 취향이여서 한번 가보았는데 커피는 찐 처음본 원두 윈터 블랜드를 시켜보았는데 향이 딸기 머금은 산미커피이지만 생각이상으로 잘 어울렸고 특히 블루베리 렝밍턴이 제 입맛에 잘 어울린듯ㅎㅎ(새콤달콤ㅎ) 하더라고요!! 그리고 딸기 머금은 커피와 딸기프레즐의 조합은 입에서 딸기다를 가득느꼈다ㅎ 매니저분도 친절하셔서 친구와 담에도 힐링하러 재방문 땅땅입니다!', 103, 21, NULL, SYSTIMESTAMP);
