INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피도 맛있고 빵도 너무 맛있네요 ㅜㅜ 빵 다 맛있고 와서 얘기나누기도 너무 좋은 분위기 + 맛 둘다 있는 맛집카페에요 합정 오면 두번에 한번은 꼭 들르는곳 !', 96, 24, 'GOOD', SYSTIMESTAMP);
