INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '지나가다가 그냥 들어와봤는데 음료도 빵도 너무 맛있어요! 맛있어서 가족들 디저트도 테이크아웃 해서 갑니다 다음에 또 올게요 :)', 8, 10, 'GOOD', SYSTIMESTAMP);
