INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '매장이 너무 예쁘고 감성있어서 좋아요 ! 분위기가 너무 좋아 작업하러 와도 될것같아요 :) 무엇보다 디저트•커피가 너무 맛있어요 ! 추천해요 🫶', 12, 5, 'GOOD', SYSTIMESTAMP);
