INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '합정역에서 카페 찾으신다면 꼭 추천하고싶어요 자리 넉넉하구 소금빵부터 베이글, 다른 베이커리류도 많답니다.  커피 원두도 종류별로 있고 테이블 간격 넓이 모두 완벽!! 무엇보다 역근처라 접근성이 좋아요~', 74, 16, 'GOOD', SYSTIMESTAMP);
