INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '가게 분위기, 매장크기, 맛, 편안한 노래 그리고 사장님의 친절함까지 하나도 빠짐 없이 완벽했습니다 요즘 서울 홍대합정쪽에서 이정도 가성비의 넓은 카페 찾기 정말 힘든데 인테리어도 예쁘고 친절하신 서비스에 정말 감동이였습니다. 그리고 사장님 잘생기셨어요', 68, 14, 'GOOD', SYSTIMESTAMP);
