INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '라떼가 대존맛입니다 ♡ㅎㅎㅎ 아매리카노도 당연 맛잇구여ㅎㅎㅎ 디저트 땡기는데, 커피 맛잇는것도 먹고프다!?하면 여기오면될거같아요! ㅎㅎㅎ', 46, 4, 'GOOD', SYSTIMESTAMP);
