INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '합정 연수왔다가 오전에 일찍 눈이 떠져서 프렌차이즈 커피싫어서 커피 찾으러나왔다 우연히 들어왔어요 입구부터 인테리어도 신경쓴게 보이네요 커피맛도 저는 깊고 좋은거같아요 호주식이 이 카페 시그니처래요 원두선택도 다양하고 오전 7시에 연다고 하니 참고하세요 :)', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '이거는 진짜진ㄴ짜 제주도에서 이거한개 먹으러 올라올 맛이고요 저 여기와서 10키로 찌고 갑니다 ㅜㅜ 40키로 안 넘으시는분은 여기와서 70키로 쌉가능입니다 여기 완전 맛있어욤 ㅜㅜ 사장님도 존잘!!!', 34, 7, 'GOOD', SYSTIMESTAMP);
