INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '어제 방문하고 반해서 하루만에 또 와서 포인트도 적립하고 리뷰도 씁니다! 빵들이.... 진짜 인생빵들이에요! 시식으로 먹어보고 맛있어서 기절할뻔.. 자주올게요♡', 17, 4, 'GOOD', SYSTIMESTAMP);
