INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아침 일찍부터 오픈하는 베이커리카페, 이른아침에 활기찬 에너지를 충전할 수 있는 곳이에요. 다양한 원두 초이스가 있어 취향껏 커피를 즐길 수 있는점이 넘 좋고 오늘은 안먹었지만 빵종류가 다양해요. 다 맛나보임! 추운날 어울리는 토마토수프가 메뉴에 있어서 주문해보았습니다. 꺄 요즘같은때 이보다 적절한 메뉴는 없스미에요.', 40, 0, 'GOOD', SYSTIMESTAMP);
