INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), 'JMT 합정 맨날 오는디 이런 베이커리 맛집이 있다니 인테리어도 좋고 걍 빵이 종류기 너무많아서 다먹어 보고싶어요ㅠㅠㅠ자주 오고싶음', 3, 1, 'GOOD', SYSTIMESTAMP);
