INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '여기 고구마 소금빵 너무 좋아해서 매번 배달 시켜먹었는데 다른 소금빵도 맛있네요ㅋㅋ 커피도 맛있고 매장이 넓고 좌석들 간격도 좋고 다인석 테이블도 많아서 단체모임 하기도 좋아요!!', 40, 5, 'GOOD', SYSTIMESTAMP);
