INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '주말 합정 어딜가나 붐며 겨우 한 자리 얻어냈어요. 베이커리 카페라 종류 다양하고 맛있어요. 소금빵이랑 메론 크림빵 두 개 주문했고 뭘 시켜고 크게 호불호 갈리지 않을 듯 합니다. 커피는 디카페인으로 타거나 쓰지 않았으나 진한 편입니다. 지하에도 자리가 있고 사람이 워낙 많은데다 주문도 받는 곳이라 테이블이 빨리 치워지지는 않아서 알아서 닦고 앉아 먹었어요. 화장실 내부 위치해서 괜찮아요.', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
