INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '베이글이랑 소금빵 종류도 진짜 많고 맛있어요!!! 특히 프레첼이 진짜 맛도리~~!! 소금빵에 버터 넣은 느낌인데, 꾸덕+짭조롬한 맛~~ 디저트 시식코너처럼 있는 카페 진짜 오랜만에 봤는데, 먹어보고 맛있는거 구매할 수 있어서 완전 좋습니다!!', 42, 10, 'GOOD', SYSTIMESTAMP);
