INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오늘도 출근전에 빵이 너무 땡겨서 들렸는데 다행히도 쪽파 베이글이랑 바질소금빵이 남아있었네요🥹 진짜 다행이다…ㅎ 아 얼른 집가서 빵 먹어야징 너무 신난당 😋 진짜 올라운드 썸머 블렌드랑 쪽파 베이글 바질 소금빵 최고의 조합이니 꼭 드셔보셔용👍🏻 강추!!', 44, 3, 'GOOD', SYSTIMESTAMP);
