INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '새로 생겨서 방문해봤는데 커피도 아주 괜찮고 베이커리 종류가 다양해서 좋아요 직접 베이킹 하더라구요 지하까지 좌석이 있어서 은근 좌석이 많아요 분위기도 좋고 재방문 의사 있어요 플랫화이트 맛있어요', 8, 2, 'GOOD', SYSTIMESTAMP);
