INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '카페가 참 이쁘고 넓어서 좋아요:) 많은 맛집 정보가 궁금하신 분들은 네이버에 후니맛블을 검색해보세요! https://m.blog.naver.com/seonghun39', 3, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '합정 최애카페로 저장📸 케일 파인애플 쥬스 킹킹 추천합니다 🍍🥬 멜번 아이스크림 커피도🍦☕️맛있습니다 (아이스크림라떼에욥) 인테리어도 힙해요.. 🙃 다음엔 빵도 먹어보려고요', 10, 2, 'GOOD', SYSTIMESTAMP);
