INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '파바가 문을닫아서 샌드위치 샐러드 키워드로 찾은 동네 카페 요즘 일부러 찾아간곳이 전부 실패해서 기대도 안했는데 맛있고 인테리어도 적당한곳을찾았다 가성비 또한 파바보다 나았다 그 가격에 아보카도가 듬뿍 이라니 소스도 신경 많이 쓴듯 깊이와 풍미가 있다 간편하고 만만해서 다니던 파바에서 이리로 옮겨 탈듯', 80, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '서교동 커피 맛집으로 알려진 커피폴리 사장님이 새로 오픈한 곳이라고 해서 점심시간에 다녀왔어요. 우앙!! 넘넘 예쁘쟈나🌈 통창 초록뷰는 못참지 체고체고,,, 사무실 동료는 커피 마시고 (내가 한입 뺏어머금ㅋㅋ) 저는 케일파인애플 주스 마셨어요. 테이크아웃  주문은 출입구 쪽 키오스크에서 바로 할 수 있고 -1000원 할인도 해줘요. 음료 기다리는 동안 포토스팟인 쁘띠정원?에서 동료를 모델로 사진 초ㅑ초ㅑ 찍어주고, 예쁜 소품이랑 테이블도 찍어주고, 베이커리 구경도 했어요. 초코생크림 잔뜩 들어간 빵이 먹음직했지만 점심 직후라 참았어요. 손님들이 많이 앉아 계셔서 사진은 못 찍었지만 테이블 간격도 넓어서 매장에서 먹어도 불편함이 없을 거 같았어요. 점심시간 나들이해서 기분 좋아 길게 쓴 리뷰😎🌸', 13, 9, 'GOOD', SYSTIMESTAMP);
