INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오늘도 다녀왔습니다…! 여자친구가 점심을 조금 먹더군요..빵 사오라고 눈치를 주는거 같았습니다 ㅎ 그래서 후다닥 올라운드 커피로 달려갔습니다 ㅋㅋ역시 빵 종류가 많아서 좋았지만 우리의 픽 바질 소금빵 쪽파 베이글 쇼콜라 소금빵 골랐네요 넘 맛도리…🥹', 39, 10, 'GOOD', SYSTIMESTAMP);
