INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '인테리어 리모델링해 새로 오픈한 느낌이었어요. 커피가 뒤끝이 탄맛나는 원두를 사용한거 같아요. 나름의 특유한 맛이 났어요. 갠적으로 괜찮았어요. 호불호는 있는거같아요.', 33, 5, NULL, SYSTIMESTAMP);
