INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '처음 와보는 카페인데 넓고 쾌적해서 좋네요ㅎㅎ 빵 종류도 많고 다 너무 맛있어보여서 고르는데 시간이 좀 걸리는…? 그리고 서비스로 맛있는 파운드케이크 하나 더 주셔서 괜시리 기분도 좋구 진짜 또 오고싶어요…분위기도 좋고 또 올 것 같아요! 제일 최고인건 넘 시원한거(중요!!!!)랑 지하에도 자리가 있어서 넓다는점…!!!', 3, 9, 'GOOD', SYSTIMESTAMP);
