INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '리뷰 이벤트가 있어도 리뷰 잘 안 쓰는데 집에 와서 먹자마자 너무 맛있어서 감동받고 리뷰 씁니다. 합정 갈 일 있어서 우연히 들르게 되었는데 내 자신이 너무 기특하네요ㅠ 소금빵이 먹고 싶은데 평범한 건 싫어서 레몬 소금빵 포장해왔습니다. 꽤 긴 시간을 들고 이동했는데도 글레이즈가 녹지 않았습니다!! 집에 와서 냉장고에 살짝 넣어뒀다가 먹었는데ㅠㅠ 너무 맛있어요ㅠ 레몬 글레이즈의 상큼함과 소금빵의 쫄깃함, 안에도 레몬 스프레드? 같은 게 들어있어서 레몬 맛이 계속 나고 너무 시지 않고 상큼하면서 달고 너무 맛있었어요ㅠ 합정 집에서 먼데ㅠㅠ 이거 다시 먹고 싶어서 가야될 것 같아요ㅠㅠ 사장님 진짜 오래 오래 장사해주세요❤️ (베이글이랑 뺑오쇼콜라는 선물용, 레몬소금빵만 먹어봤어요!!)', 78, 12, 'GOOD', SYSTIMESTAMP);
