INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '커피 맛집..출근전에 항상 들려야 하는 루틴이 생겨버린 나..오늘은 썸머 블랜드로 먹었습니당 어떻게 커피에서 멜론 향이 나죠 (?) 내일 또 가야쥐…🥹', 118, 26, 'GOOD', SYSTIMESTAMP);
