INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '근처 소금빵 먹고 싶어 일하다 중간에 왔는데 매장도 아늑하고 빵이 다양하게 많아서 너무 좋았어요🥰🥰 직원분들도 넘 친절하고 기분 좋게 나갑니당! 고르다보니 눈돌아서 많이 사버렸지 뭐에요 .. ㅎㅅㅎ 담에는 포장말고 매장에서 즐기고 싶은 맴~~! 또 방문 의사 x 1000 !!!', 82, 11, 'GOOD', SYSTIMESTAMP);
