INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '저녁으로 아침으로 먹을 도넛을 사가지고 옵니다, 홍대점은 홍대입구역 1번과 2번출구 사이에 있어서 항상 손님들이 많습니다,,,', 46, 0, NULL, SYSTIMESTAMP);
