INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '이 근방 여기기 젤 가까워 자주 이용하는데요, 매장 최근에 리뉴얼해서 깔끔해졌더라구요,  가지고 오다가 도너츠 다 쏟아버릴뻔 했어요, 아오 ㅠ 여긴 점주부터 불친절에 알바생들 줄줄이 불친절. 진짜 어쩔수 없는 경우에만 들리는데. 이놈의 동네 이거 달랑 하나에요.', 69, 12, 'BAD', SYSTIMESTAMP);
