INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '맛- 던킨도너츠 기본 맛 샤인머스캣 플라타 어릴적 먹었던 청포도 하드 맛 ㅎㅎ 추억의 맛 소환 청결- 기본 친절함- 기본 재방문- pass by', 33, 8, NULL, SYSTIMESTAMP);
