INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), 'skt... 비록 논란이 심하지만, 아직 쓰고 있음으로😂 t월드 혜택으로 50% 할인 받아서 간단 점심으로 포장해와봤어요! 맛있네요🩷', 42, 2, 'GOOD', SYSTIMESTAMP);
