INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '직원들 최악입니다. 귀찮아서 이런글 안남기는데 진짜 싸가지가 너무 없네요 그런식으로 응대할거면 일하지마세요 먹고가냐고해서 포장이라고했더니 빤히 쳐다보다 한숨쉬고 포장해주질 않나 다른날 방문했을 때 포장 따로 해달라그랬더니 하고있던 포장지 멈추고 한숨쉬고 포장 하질않나 제가 한게 무리한 요구인가요? 혹시 따로 비용을 내야하는건가 싶어 추가로 결제해야하냐 그랬더니 들리지도 않게 “아니요” 같은사람도 아니고 다른사람이 응대한건데 이렇게 통일성있게 싸가지가 없으면 교육을 잘못시킨듯하네요 매장리뉴얼하고 직원들 뇌도 같이 리뉴얼 된건가요? 아님 외국인 많고 장사 잘되서 걍 배째라하고 일하는건가요? 돈을 벌거면 똑바로 하던지 그딴식으로 할거면 일을 하지마셔요 눈감고 귀닫고 가실거믄 방문해보세요~', 36, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '던킨도너츠 너무 맛있어요. 특히 올리브츄이스티랑 카카오허니딥 완전 최애 도너츠입니다 ㅜ 던킨도너츠 40% 행사 자주 해주세요!', 13, 0, 'GOOD', SYSTIMESTAMP);
