INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '연구실 행사를 위해 영화관에 가기 전에 방문하여 간식 구매했습니다 주문한 메뉴도 다양하고 많았는데 그래도 빠르게 응대해주셔서 감사했습니다 친절하고 빠른 주문 대응 덕분에 좋은 시간 보냈습니다 감사합니다', 38, 4, 'GOOD', SYSTIMESTAMP);
