INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '마침 궁금하던 두바이 초코도넛이 있어 구매 기존 도넛보다 비싸지만 안에 피스타치오와 카다이프가 가득 들어 바삭하고 초코랑도 잘 어우러지는게 너무 맛있다 두바이 디저트 중 잘 만든 편 흑임자도넛은 흑임자 맛이 강하지않아 아쉽다', 56, 15, 'GOOD', SYSTIMESTAMP);
