INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '참 신기한 카페네요 주차장에 아무것도 없이 그냥 만든거 같은데 뭔가 꽉 차있습니다. 작은공간이라 앉아 있기도 버거울거 같은데 그런게 또 묘미네요 이 작은 공간안에 심지어 로스터기도 떡하니 자리잡아 있습니다. 사장님 두분도 카페만큼이나 개성있어 보이네요 우연히 이야기를 들어보니 정말 아무것도 없이 거의 무일푼으로 300만원짜리 로스터기 하나로 시작하셧다고 하는거 같습니다. 여전히 작아 보이긴 하지만 충분히 매력있는 공간입니다. 커피맛은  역시 좋습니다. 이런곳은 필터커피가 제격이죠 메뉴판도 손글씨네요 현관 문도 없어서 비닐을 내렷다 올렷다 하는데 겨울에 꼭 와봐야겟습니다. 저녁에서 분위기가 꽤나 좋을듯 싶네요 의외로 아메리카노를 많이 드시던데 다음엔 머신커피도 마셔야겠습니다.', 63, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '상수역 근처 커피 잘하는 카페 ☕️ 네요 !! 예전부터 궁금해서 들렸는데, 기대했던만큼 맛있었습니다 🫢 테이블이 많이 좁은 편이어서 ... 다음에 가면 그냥 테이크아웃으로 마실 것 같아요! 좋았습니다 ~~', 30, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '전부터 가보려고 저장해둔 카페여서 기대가 컸습니다! 다 맛보고 싶었는데 이미 품절된 원두도 있더라고요. 또 가야겠네요😁 맛있었고, 분위기도 좋았습니다. 외부에 자리가 있어서 앉아 있다가 실내 자리가 생겼을때 바로 안내해주셨어요. 얘기도 자연스럽게 걸어주시고 세상 친절하신 사장님들이셨습니다👍🏻', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '와… 커피맛이 예술입니다 ㅠㅠ 저는 케냐를, 지인은 에티오피아를 마셨는데 머신 커피에서 이런 맛이..?!? 커피 한 모금에 여행지에 온 듯한 느낌입니다. 일상의 텁텁함을 잊게 해주는 놀라운 맛이라 다른 원두도, 드립 커피도 몹시 궁금해집니다 ♥︎ 조만간 또 들를게요. 여기 커피가 도덕과 규범 그 자체입니다 😆', 104, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '오늘 처음 방문했는데 필터커피 너무 맛있었어요. 삥타이거님 영상에 봤던 분들 상당히 많이 봤는데 신기했어요. 하만진님? 삥타이거님 그리고 사장님 등등 신기 뭔가 사랑방 같은 느낌이었어요. 집만 가까웠어도 자주 갈텐데 ㅠ 종종 들리겠습니다.', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '현 시대의 사람들은 마치 카페인 중독자라도 된 듯, 아침이면 좀비마냥 아메리카노를 찾아 길거리를 서성인다 그러나 카페인을 한참 채운 뒤에도 우리는 무엇인가에 홀린 듯 더 많은 카페들을 찾는 데에 혈안이 되어있다 우리는 도대체 어떤 카페를 찾는 것일까? 사람들의 이야기가 끊이질 않는 이곳은 아지트라는 단어와 가장 잘 어울리는 공간이다 이 시대의 사람들에게 가장 필요했던건 사실 카페가 아닌 따뜻한 사람간의 교류가 아니었을까', 22, 6, NULL, SYSTIMESTAMP);
