INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '시어머님 생신겸 어버이날이라 카네이션케이크를 구매하러 방문했어요~ 케이크도 예쁘고 토퍼증정도해 만족스럽네요 구매할동안 건물옆 잠시 주차 가능했고 번화한곳 코너쪽에 위치하고있어 찾기 쉬웠어요 매장도 깔끔하고 직원분도 바로 준비해주셨습니다', 59, 15, 'GOOD', SYSTIMESTAMP);
