INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '🍓 딸기시즌 = 할리스 🩷 보기만해도 감성 넘치는 맛도리 케이크들이 가득🙏🏻 주말이어서 다소 분잡한 느낌이 있었지만 바쁜 와중에도 직원분도 친절하셨어요🥹 통신사 쿠폰도 잘되어있고 테라스 자리까지 있어서 날좋은날에 힐링하기 딱이네요👍🏻 혼잡한 분위기라 스터디하기에는 조금 어려울 것 같네요~~😭😭', 7, 8, NULL, SYSTIMESTAMP);
