INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '8,12 밤 11 23분 입장 들어오면 인사 안함 키오스크 가니까 하기 싫은티 머 내려놓는것도 소리 크게 내려놈 메뉴 주문하니까 한숨 들리게 쉬고 들어오고 나서 냉장고 쪽가서 햄드폰 한참 한뒤 메뉴 만듬 진짜 소비자 입장에서 욕 개나옴 진짜 다신 안옴 오지마세요 알바를 짜르던', 21, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '연트럴파크 바로 보이는 뷰라 너무 좋네요. 초록 초록 뷰 보며 마시는 아아는 꿀맛🫧 단발에 귀여우신 점장님 품절건 있다고 매우 친절하고 상냥하게 알려주셔서 기분 좋았어요 (대문자 F는 이런 부분에도 큰 감동을 느껴요..🫶) 잘 마셨습니다! 화장실도 깨끗했어요 (중요!)', 10, 9, 'GOOD', SYSTIMESTAMP);
