INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '정말 오랜만에 방문한 할리스. 매장이 넓고 환하다. 아메리카노와 라떼 그리고 핑크스토로베리머치 주문. 커피가 진해서 맛있고 라떼도 굿 👍 요새 딸기 가격을 생각하면 케익도 합리적 가격과 맛을 자랑♡', 67, 13, 'GOOD', SYSTIMESTAMP);
