INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '연남동 할리스 연트릴파크점 사람많았지만 이층테라스 자리가 좋아 아아 마시며 얘기나누기 좋았어요. 경의선 숲길 경치도 좋구요. 라떼는 soso', 66, 13, NULL, SYSTIMESTAMP);
