INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '연남동에 있는 커피숍에 왔어요 삼 층까지 있는데 홀리스 커피숍 입니다 지금 9시 반인데 손님이 꽉 차 있어요 장사가 잘 되는 것 같아요', 317, 69, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '테라스 자리 있어서 좋아보였어요. 저는 실내에 앉았지만, 외국인들은 테라스에 앉더군요 방문한 시간에는 자리 많았고, 2시간 지나니 꽉 차게 되었습니다. 청포도 스파클링은 쏘쏘', 50, 4, NULL, SYSTIMESTAMP);
