INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '연트럴파크 바로앞 할리스 들름. 음료 많이 달았지만 땀흘리고 마시니 천국의 맛, 옥수수빵은 겉이 물렁해서 살짝 당황했지만 풀빵같은 재질에 찹쌀떡처럼 쫄깃하고 달콤한 옥수수크림에 짭조름한 옥수수알갱이 조합에 맛있게 먹었음. 층고 높고 시원시원해서 좋았음.  키치해 보이는 컬러플한 보온병에 시선 뺏김.  음료종류, 디자트종류가 너무 많아서 구경하는 재미가 있었음.', 118, 26, 'GOOD', SYSTIMESTAMP);
