INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '여전히 맛있고, 여전히 친절하고, 여전히 사람 많아요. 운 좋게 가자마자 좋은 자리 앉을 수 있어서 통창으로 바깥 구경하면서 4시간 수다떨다 왔습니다. 휘낭시에도 정말 맛있어요. 커피도 진하고 부드럽고 깊은 맛이 예술입니다. 다음에 또 갈께요 ^^', 33, 3, 'GOOD', SYSTIMESTAMP);
