INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '매장이 커서 편하게 앉을 수 있었고 디카페인 먹었는데 산미있는 맛이었는데 깔끔해서 괜찮았어요. 새로 나온 바나나 푸딩맛 케익 먹었는데 무난했습니다. 푹쉬다가 갔습니다ㅎㅎ', 22, 0, 'GOOD', SYSTIMESTAMP);
