INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '유자청 감귤청 등 저렇게 둬서 그런지 주변에 날파리가 많이 날라다닙니다.. 감귤차 시켰는데 저었더니 벌레가 올라왔고 유자차 새로 결제해서 새로 받았는데 받자마자 또다른 검정 물체를 발견하여 다시 받았어요. 저런 보관방식이라 감귤청이든 유자청이든 전부 위생적이진 않아보입니다.', 76, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '진짜 세상에서 가장 더운 커피숍이예요. 땀 뻘뻘흘리면서 커피마시고있어요 시원할라고 들어갔다가 부채질만 열심히 하구있네요.  돈내고 힘써야 겨우앉아있을수있어요..매장에 너무덥다구 카운터전화드렸더니 여기가 통유리창이고 풀냉방이라고하시는데....바로 옆건물 커피숍은 같은 통유리커피숍인데 엄청시원해요. 에어컨을 고치시던지..뭔가 해결을 하지않으면 여름에 더위피하러들어온 고객들 컴플레인만 쌓일꺼같네요.. ㅜㅜ앉아있는 많은사람들이 다 더워서 부채질하고 에어컨가동되는지 손대러 보러오고.., 이미 후기에 덥다는내용이 있는데도 개선이 안된거네요.. 여름에 피하시는게 좋겠어요', 5, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '매장 엄청 크고 사람도 엄청 많아요. 운 좋게 2층 테라스 공간, 연남동 거리가 다 보이는 곳에 앉았어요! 날씨 좋아서 야외 앉으니 기분 좋았어요!', 2, 7, 'GOOD', SYSTIMESTAMP);
