INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '커피를 못 드시는 분이라면 달달한 파인 선셋 캐모마일티도 괜찮을것같다~(주황색) 청포도케일 착즙주스는..케일맛 탄산음료로 봐야할것같다', 35, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '폭염이 무섭긴 한듯 여기가 카페인지 찜질방인지 ㄷ ㄷ… 아포칼립스가 멀지 않았구만… 그건 그거지만 배는 고프니까 오늘도 애그마요 하나 클리어!', 38, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '오랜만에 바닐라 딜라이트 먹었어요🥰 할리스가 3층까지있고 4,5층은 몰랑이 팝업스토어가 있는 건물이더라구요! 3층까지 있는데도 평일 저녁인데도 사람이 많았어요. 저는 야외테이블에서 먹었는데 바람도 선선하고 너무좋더라구요. 날 더 더워지면 야외에서 먹긴 힘들것 같긴한데 요즘은 날씨가 좋아서 딱이네요. 직원분도 친절하신 편이고 음료도 맛있어요! 할리스는 어느지점을 가든 평타이상인듯해요. 재방문각👍', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '집앞에 할리스커피생겨서 넘좋아요.리모델링때부터 봐왔는데 뭐가 들어올까 궁금했는데,꺅~할리스라니.. 커피도 풍미가 있어서 좋고 케잌도 맛있죠~3층까지 있고 분위기도 짱~2층엔 루프탑도 있어서 날좋을땐 좋을거같아요.댕댕이존.넘 귀욤.댕댕이랑 산책하다가 들르기좋아요~오전8시오픈,오후11시마감. 15000원이상 구입시 머그컵주네요~', 85, 12, 'GOOD', SYSTIMESTAMP);
