INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '연남동에 핫플레이스로 거듭나는중 뷰도 좋구 맛있고 친절한데 위치가 일단 너무 좋음 여기서 커피한잔하고 경의선숲길까지 걷는 코스면 금일 데이트 끝남 ㅋㅋㅋㅋ', 30, 5, 'GOOD', SYSTIMESTAMP);
