INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '할리스 연트럴파크점, 산책하다 들르기 좋아요. 날씨가 따뜻해서 매장안은 한여름 같이 덥네요~아아에 딸기치즈케익 맛있어요. 요즘 물가 장난아닌데, 그래도 이정도면 착한 가격이예요~^^', 33, 7, 'GOOD', SYSTIMESTAMP);
