INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '새롭게 단장한 곳입니다. 깨끗해요. 좀더 여유롭게 이야기 할 수 있는 곳입니다. 연남동 나가면 자주 이용하게 될 것 같습니다.', 88, 18, 'GOOD', SYSTIMESTAMP);
