INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '여기 언제 생긴거에요? 오랜만에 연남동 갔는데 날도 좋았는데, 루프탑있어서 넘 좋았어요~연트럴파크 앞이라 뷰도 멋지고 실내 인테리어도 깨끗해요', 29, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '점심때 가끔 밥먹기 귀찮고 하면 갑니다. 많이 복잡하지 않고 좋아요. 다만 식사대용으로 할만한 브레드 종류는 약간~ 미비한 느낌? 샌드위치 종류도 나무 소량이고;; ㅎ 그것만 보충되면 좋겠어요~', 17, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '2/23 21시 안경쓰신 직원분 바쁘고 주문이 많다고 손님한테 짜증낼거면 바쁜 매장에서 일하시면 안되는 거 아닌가요..같이 일하시던 분은  같은 상황에서도 친절하시던데 핫초코는 그냥 스팀우유라고 해도 믿을만큼 밍밍하고 할리스 초코음료 좋아했는데 너무 실망스럽네요..', 100, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '오픈한지 얼마되지않아 깨끗합니다. 연트털파크쪽이라 창가쪽에 앉으면 뷰도 좋고 만족해요. 근데 점심시간에 갔는데 직원분 혼자계셔서 많이 힘들어 보이셨어요.', 11, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '오랜만에 연남동 갔는데 좋은 위치에 할리스 건물이 엄청 예쁘게 생겼길래 밥먹고 일부러 후식먹으러 방문함. 근데 만족도는 최악. 2층에 음료 엎질러져 있는 곳이 두 곳이나 있었는데 내내 치우지도 않고 화장실에는 페이퍼 타월도 없음. 건물만 예쁘지 아예 관리가 안 된다는 뜻. 내부 인테리어, 의자, 테이블도 생각보다 불편하고 별로임(건물 외부는 아주 멋진것에 비하면).', 46, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대 출판사 골목에 위치한 마인드비^^나의 최애 카페다. 학지사에서 운영하기에 당연히 책이 있는 카페. 운영을 맡으신 실장님의 친절함으로 벌써 4년 가까이 카페를 이용하고 있다. 분위기 있는 카페의 결정판이다. 자주 리뷰 올려야 겠다.', 41, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 인근 카페들이 대체로 사람에 치이는 편인데 조금 한가한 공간입니다. 의자도 대체로 편하고 좋은 편입니다. 커피 맛도 괜찮네요.', 1, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '이 주변 카페들중에서 가장 친절하신 사장님 ..🥹 좌석도 넓고 좋아서 항상 잘 이용하고 있어요 음료랑 디저트들도 너무 맛있어요 !!', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '시간이 남았는데 집에 그냥 가기싫어서 검색하고 우연히 들렀는데 매장분위기나 커피, 디저트 다 좋아요! 집근처라서 자주 올거같아요💕 사장님 친절하시구 디저트도 다른카페에서는 못본거라서 시도해봤는데 꿀맛🍯', 34, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대 북카페로 검색해서 방문했어요 학지사라는 출판사 건물에있네요 카페 내부에 심리학,교육한 등의 전공서적들이 많이 꽃혀있어요 열람용같지는 않아서 제목들 구경만 했어요. 토피넛라떼 주문했는데 담아져나오는 컵이 참 이쁘네요ㅎㅎ 맛도 달콤해서 공부하다 졸릴 때 마시면잠이 깨네요! 화장실은 카페랑 바로 연결되어 있고 남,여 구분되어있어요. 그리고 깔끔합니다 바 스타일 책상에 앉았는데 콘센트도 있어서 태블릿 충전시키면서 공부(강의듣기)도 잘 마쳤어요!', 6, 2, 'GOOD', SYSTIMESTAMP);
