INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '최애 카페...🫶🫶 공부할 때 가면 너무 좋구요! 회의할 때도 좋습니다. 음료도 맛있고 샌드위치랑 소금빵도 맛있어서 자주 먹어요. 안쪽 회의실도 예약해서 매번 잘 쓰고 있습니다! 사장님 정말 친절하셔요... 화장실도 매장 내에 있고 굉장히 깨끗합니다. 마인드비 짱...!!', 0, 8, 'GOOD', SYSTIMESTAMP);
