INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '커피가 고소하고 맛있어서 자주 이용합니다! 사장님도 너무 좋으세요. 책과 함께 조용하게 작업하기 좋습니다. 힐링되는 공간이에요!', 371, 54, 'GOOD', SYSTIMESTAMP);
