INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '오늘 노벨문학상 기념으로 20프로 할인을 하네요. 노벨문학상도 기분 좋은데 가게의 이벤트도 최고입니다. 이곳 분위기 넘나 좋아서 종종 와요~~', 25, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '진짜 자주오는데 이제야 리뷰 써보네요:) 음료랑 디저트가 맛있는건 당연하고 공간이 너무 좋아요. 회의실도 있어서 예약하면 여러명이서 집중해서 일하기 좋았어요. 사장님도 친절하셔서 이 동네 여기만한 카페 없는 것 같아요ㅎㅎ', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '쾌적한 공간에 다양한 음료, 맛있는 디저트, 친절한 사장님까지! 처음 방문했을 때 반해버려서 주기적으로 방문한 곳입니다. 카드내역 보니 벌써 열 번이 넘었네요...ㅋㅋㅋㅋ 커피류도 맛있고 라떼나 에이드도 잘하세요. 출출하시면 소금빵도 꼭 먹어보세요. 바로 데워서 내어주시는데 너무 촉촉하고 맛있어요!!!', 12, 1, 'GOOD', SYSTIMESTAMP);
