INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '경민이도 인정한 음료 맛집🥹🥹 레몬에이드 샷추가 맛있어요 (호불호 주의) 그밖에도 아샷추, 커피 맛있어요 사장님도 친절하셔요 최고~~', 114, 21, 'GOOD', SYSTIMESTAMP);
