INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '올때마다 친절하게 맞아주시고 음료도 너무 맛있는데 서교동 할인도 해주셔서 과제할 때는 무조건 여기로 옵니다~ 여기 아이스티랑 토피넛 라떼 맛있어요! 주변에서 젤 좋은 알짜배기 카페 입니다☺️', 28, 0, 'GOOD', SYSTIMESTAMP);
