INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '자주 가는 카페예요~ 휘낭시에도 맛있는데 제 최애는 밀크 페스츄리예요 많이 안 달고 생크림도 고소하고 맛있어요 강력추천! 커피도 항상 맛있는 곳입니다', 1, 9, 'GOOD', SYSTIMESTAMP);
