INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '매번 오지만 이제야 리뷰를 쓰네요 넘 맛있고 사장님 직원분들 다 친절하셔요... 늦게까지 해서 퇴근하고 일하거나 쉬다 가기 좋습니다 단체 모임에 최고!', 14, 7, 'GOOD', SYSTIMESTAMP);
