INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '신메뉴라고 오틀곡라떼 시음을 권해주셔서 먹어봤는데 너무 맛있었어요!!! 오틀곡라떼 꼭 드세요!!! 마음이 따뜻해지는 마인드비 감사합니다❤️', 3, 10, 'GOOD', SYSTIMESTAMP);
