INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '샌드위치가 맛있다고 해서 먹어봤는데 야채도 엄청 아삭아삭하고 빵이 너무 맛있어서 좋았어요! 아샷추랑 먹었는데 다른 곳보다 아샷추 너무 맛있네요…! 담에 오면 성격유형검사 해보려구요!!! 그걸 몰랐다니 아쉽…ㅠㅠ(그리고 여기 알바 잘생김🤓)', 49, 10, 'GOOD', SYSTIMESTAMP);
