INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '사장님이랑 알바분이 너무 친절하시고 커피랑 샌드위치 조합 최고에요! 음료만 시켰다가 샌드위치가 맛있어보여서 추가주문하고 잘 먹고 갑니다🤍', 17, 3, 'GOOD', SYSTIMESTAMP);
