INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '커피가 진짜 맛있는 곳이에요! 그리고 제 최애는 아샷추입니다ㅎ.ㅎ 늘 친절하신 사장님과 직원분들 덕에 기분까지 좋아지는 곳이에요! 밝고 조용한 분위기에 시간 보내기에도 좋아요~', 48, 10, 'GOOD', SYSTIMESTAMP);
