INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '지나가다가 까페인지 모르고 기웃거리다가 들어왔는데 여성 서버분께서 미소 가득 친절하시고 제게 딱 맞춤 서비스..디테일 하셔서, 맛있는 커피향과 감동향까지 모두 기억에 남기고 갑니다 일상의 행복을 느끼게 해주셔서 감사합니다', 19, 9, 'GOOD', SYSTIMESTAMP);
