INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '갈 때마다 항상 즐거운 기분으로 다녀옵니다ㅎㅎㅎ 음료도 맛있고 매장 분위기도 좋아요!! 책으로 둘러 쌓여 있어서 똑똑해지는 기분도 들고 좋습니다ㅎㅎ 직원분들도 모두 친절하고 세심하게 신경써주시는 거 같아요! 시설도 전부 깨끗하고 매장도 청결하게 운영하시는 거 같더라구용 커피 맛도 넘 좋습니다 가성비 최고예요ㅠㅠ 앞으로도 자주 갈 거 같습니다~', 17, 9, 'GOOD', SYSTIMESTAMP);
