INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '점심 먹고 항상 가는 카페에요! 분위기도 좋고 특히 초코리떼가 진짜 찐하고 맛있어서 단골이 되었네요 ㅎㅎ 사장님도 너무 친절하시고 가끔 하는 이벤트도 너무 좋아요 심리학 책이 많아서 그런 책에 관심 있는 분에게 강추!', 55, 17, 'GOOD', SYSTIMESTAMP);
