INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '바로 근처라 자주 들리는데 서비스 빵도 종종 주셔요! 커피도 맛있고 음료도 맛있고🥰🥰🥰 사장님이 너무 친절하셔서 방문할 때마다 기분 좋아요😍😍', 15, 2, 'GOOD', SYSTIMESTAMP);
