INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피가 정말 맛있고 사장님이 엄청 친절하세요. 내부 인테리어도 매장 분위기도 정말 좋아요. 여기서라면 어떤 책이든 앉은 자리에서 완독할 수 있을 것 같습니다. 🤤 또 오고 싶어요!', 48, 0, 'GOOD', SYSTIMESTAMP);
