INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아이스아메리카노 펄스 신맛 맛있어용~~ 원두 이름이 심리학자 이름이어서 재밌어요ㅎㅎㅎ 그리구 스무디종류 짱 맛있어요!!! 해장에는 망고 스무디 맛있다고 ㅎㅎㅎ 무엇보다 짱 친절하세요', 143, 83, 'GOOD', SYSTIMESTAMP);
