INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '거의 매일 아침마다 커피랑 사라다빵 먹으러 가는데 항상 친절하시고 맛있어서 좋아여❣️ 재료 아끼지 않고 듬뿍 넣어주신 사라다빵 너무 맛있어요💗 웃으며 맞아주셔서 기분좋게 하루 시작하고 있습니다!! 내일 또 갈게요😆', 25, 2, 'GOOD', SYSTIMESTAMP);
