INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '너무너무 아끼는 카페입니다 사장님이 엄청 친절하시고 커피가 맛있어요 ☕️ 개인적으로 펄스 원두를 추천합니다 베이커리도 정말 맛있는데 아침에 한정으로 판매하는 샐러드빵... 오전에 안가면 없습니다🥹 그리고 심리학 출판사에서 운영하는 카페라서 심리학 도서도 많고 성격검사도 무료로 할 수 있어요 ! 홍대근처에서 잠깐 커피한잔 하면서 시간보낼 곳 필요하면 추천합니다👍', 7, 0, 'GOOD', SYSTIMESTAMP);
