INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대 북카페 중 압도적입니다 안에 미팅룸도 있고, 정말 넓고 쾌적해요 메뉴도 짱 맛있구(특히 오렌지 비앙코, 단호박라떼 핫 추천) 사장님 너무너무너무 친절하고 상냥하세요♥️', 49, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
