INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '또온 디삼! 띠기! 존맛띠기! 리뷰이벤트 꼭하세용 쿠키가 진짜 맛있거든요 근데 리뷰이벤트 많이 하면 내가 먹을 쿠키가 사라지니까 적당히 해주세용😅😜😝', 117, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '신메뉴 느린마을 크림 라떼 정말 맛있어요🥹. 막걸리 맛이 나는 라떼인데 정말 최고에요.🤍 🤍 그리고 여기 크로칸슈도 정말 맛있어요. 커스터드 맛 크로컨슈를 다들 드셔보세요.💛 저렴하고 양도 많아요 그리고 실내가 굉장히 시원하답니다 그리고 리유저블 컵이 귀여워요🍀🍀', 32, 10, 'GOOD', SYSTIMESTAMP);
