INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '디저트 39 제가 정말 좋아하는 카페인데! 오늘도 저당 음료 잘 마시고 가요! 가장 큰 장점은!! 다양한 메뉴가 있는 것 같아요! 담에 또 올게요 ♡', 20, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '분위기가 너무 좋구 음악 맛집이에요ㅠㅠ 무엇보다 커피랑 디저트가 너무 맛있구 시끄러운 분위기가 아니라 너무 편안해서 자주 올 것 같아요ㅎㅎ', 50, 0, 'GOOD', SYSTIMESTAMP);
