INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '커피하고 오리지널 도쿄롤하고 같이 먹었는데 너무 맛있고 커피&디저트 조합은 뭘 먹어도 최고입니다👍 쓴맛이 없고 고소하고 진해서 커피도 맛있고 도쿄롤 빵안에 크림이 얼린상태에서 먹으니 아이스크림 먹는거같이 너무 맛있어요~~ 벽에 각종 소품으로 인테리어를 해놓으니 아기자기하고 전등색깔이 은은하고 예쁘며 전체적으로 안락하고 아늑해서 좋았어요~~^^', 75, 13, 'GOOD', SYSTIMESTAMP);
