INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '인테리어 깔끔하고 예쁘고 가성비 좋아요. 디저트랑 음료 모두 맛있는 곳♡ 딸기라떼 너무 맛있게 잘 먹었어요. 다음엔 꼭 친구랑 같이 오고 싶어요!', 26, 3, 'GOOD', SYSTIMESTAMP);
