INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '그레이톤의 인테리어와 책같은 소품이랑 곰돌이 인형같은 소품으로 꾸며놓으니 차분한 분위기가 느껴지고 아기자기하네요~^^ 길쭉한 거울도 있어서 포토존으로 사용하기 너무 좋을거같아요~ 그리고 여기 합정역점은 테라스까지 있어가지고 좋네요^^ 플레인 휘낭시에,카라멜 피칸 휘낭시에하고 커피하고 조합이 잘 어울리고 좋아요~^^ 휘낭시에 겉부분이 바삭하고 속에 빵부분이 촉촉해서 너무 맛있고 커피도 고소하고 진하고 맛있었어요~~^^', 67, 17, 'GOOD', SYSTIMESTAMP);
