INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '각종 소품으로 인테리어에다가 그레이톤에 인테리어 다 보니 아늑하고도 차분한 분위기이면서 주말인데도 조용하게 이용할수있는거 같아서 좋아요^^ 벽에도 소품으로 인테리어를 해놔서 그런지 아기자기하고 무드등 조명색깔도 너무 예쁘네요💗 외관 색깔도 예쁘고 커피도 고소하고 맛있어요^^ 게다가 따뜻하게도 이용할수있어서 너무 좋았어요^^', 14, 3, 'GOOD', SYSTIMESTAMP);
