INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '디저트39 딸기라떼가 제일 맛있어서 딸기라떼 먹고싶을깬 늘 디저트39로와요!! 특히 합정점이 새로생겼고 깔끔해서 더 좋은것같아요!', 114, 25, 'GOOD', SYSTIMESTAMP);
