INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '테이블 수도 많고 매장 공간도 넓으며 아늑해 음료 즐기기에 딱인 장소입니다. 음료도 디저트39 오면 항상 마시는 바나나우유 음료지만 마셔도 마셔도 질리지가 않네요! 두 음료(제로복숭아아이스티&바나나우유라떼) 모두 맛이 참 깔끔하고 달달해서 추천합니다:)', 14, 2, 'GOOD', SYSTIMESTAMP);
