INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '매장 들어오자마자 친절하게 맞아주시고, 인테리어가 힙해서! 자주 들리곤 합니다! 합정점은 깔끔하고 음료도 맛나서 추천이요!!🩷🥰', 55, 16, 'GOOD', SYSTIMESTAMP);
