INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '바나나우유라떼 주문했는데 달콤함과 부드러움을 동시에 느낄 수 있는 인기 메뉴입니다. 이 음료는 진한 바나나 라떼 베이스에 바나나 과자가 더해져 독특한 맛과 식감을 제공합니다. 특히 대용량으로 제공되어 가성비가 뛰어나며, 바쁜 일상 속에서 달콤한 여유를 찾는 소비자들에게 제격입니다. 바나나우유라떼는 빙그레 바나나맛 우유를 연상시키는 친숙한 맛을 가지고 있어 남녀노소 누구나 부담 없이 즐길 수 있습니다. 따뜻하게 마시면 더욱 부드럽고 진한 풍미를 느낄 수 있어, 추운 계절에 특히 어울리는 음료로 추천됩니다. 또한, SNS에서도 화제가 될 만큼 비주얼과 맛 모두 만족스러운 메뉴로, 디저트39의 디저트와 함께 곁들이면 더욱 풍부한 맛을 경험할 수 있습니다. 디저트들이 다 귀엽고 맛있어보여요!', 68, 11, 'GOOD', SYSTIMESTAMP);
