INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '다이어트 할 때 방문하기 좋은 프렌차이즈 카페! 합정역 디저트39는 더 예쁘게 인테리어 되어 있고 쾌적해서 좋은 거 같아요 ㅎㅎ', 39, 9, 'GOOD', SYSTIMESTAMP);
