INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '2번째 방문입니다!! 평일에 왔을때랑 다르게 사람들로 붐볐고, 제로 칼로리 음료시켰는데 달고 맛잇었어요!! 특히 딸기 누네띠네 따뜻하게 방금 나온거 먹은니까 커피랑 너무 조합이 좋아요!! 사장님도 친절하시고, 자주 올것같아요!!', 56, 11, 'GOOD', SYSTIMESTAMP);
