INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '항상 여기 오면 먹는 녹차라떼인데 여기 지점도 역시나 맛있어요 우유 변경도 있어서 라이트하게 먹기도 너무 좋고 큰사이즈로 먹을 수 있어서 오래 먹기 좋아요 녹차라떼 좋아하시는 분들은 좋아할 맛인 것 같아요', 34, 9, 'GOOD', SYSTIMESTAMP);
