INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '공간도 넓고 쾌적해서 집중하기 넘 좋습니다!! 사장님도 친절하시고, 음료도 양 많고 맛있어서 자주 방문할 거 같아요!! 합정 근처 카페 찾으시면 디저트39 합정점 추천합니다✨', 31, 10, 'GOOD', SYSTIMESTAMP);
