INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '메뉴도 굉장히 다양하고 특시 제로칼로리 음료를 3,4천원대에 마실 수 있습니다! 케익, 슈 등 다양한 디저트를 팔고 있으며 매장은 지하 1층까지 넓어서 공부 친목 등 목적으로 이용하기 쉽습니다!', 17, 4, 'GOOD', SYSTIMESTAMP);
