INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '약속이 있어서 방문했는데 매장이 정말 깔끔하고 인테리어도 너무 이쁘게 꾸며져 있어서 구경하는 재미도 가득했어요 ㅎㅎ 디저트 종류도 정말 많고 음료도 맛있는게 너무 많아서 한참 고민을 했어요 ㅎㅎ 커피도 맛있고 양도 장난아니고 디저트도 너무 맛있게 먹었어요 ^^', 12, 2, 'GOOD', SYSTIMESTAMP);
