INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '매장이 엄청 깔끔하고 앉을 자리도 많더라구요~ 매일 지나가면서 보기만 했었는데 들어오니까 완전 대 만족이였어요! 그리고 디저트39에 이렇게 많은 베이커리 류가 있는지 몰랐는데 다음번에는와서 베이커리류도 먹어봐야겠어요! 이쁜 리유저블 컵에 담아 더욱 만족스러운 디저트39였습니다~ 다음번에 또 방문할게요!', 9, 9, 'GOOD', SYSTIMESTAMP);
