INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '디저트39오면 항상 흑임자라떼에 샷추가해서 먹어요 ㅎㅎ너무 꼬소하고 맛있어요^^ 특히 합정점 인테리어 너무 이쁘고 깔끔하고 좋아요!!', 25, 9, 'GOOD', SYSTIMESTAMP);
