INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '합정에 볼일볼게있어서 왔다가 시간이 좀남아서 친구랑 디저트39에 왔습니다 ㅋㅋ 생각해보니까 디저트39에는 처음방문하는거였답니다 ㅋㅋ 커피도맛있고 디저트도 굿굿이었습니다🙃', 20, 7, 'GOOD', SYSTIMESTAMP);
