INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '다른지점도 자주 가는데 합정점은 정말 크고 유달리 깨끗하고 분위기가 좋은 것 같네요! 가볍게 작업하거나 대화하러 오기 좋을 것 같습니당😀', 30, 2, 'GOOD', SYSTIMESTAMP);
