INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '가게가 새로 생긴지 깔끔하고 인테리어도 너무 예뻤어요!! 매장이 생각보다 컸습니다!! 디저트39 평소에 좋아했는데 멀어서 배달로만 시켜먹었는데 근처에 생겨서 너무 좋아요 자주 방문하겠습니다!! + 사장님도 친절하셔요ㅎㅎ', 23, 1, 'GOOD', SYSTIMESTAMP);
