INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '디저트39 합정역점 깔끔하고 분위기 좋아요. 음료도 저렴하고 맛있어서 굿굿 합정역 점은 역이랑도 가깝고 친절하고 매장 넘 깔끔해서 좋아요!', 12, 6, 'GOOD', SYSTIMESTAMP);
