INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '제가 원래 리뷰 잘 안 다는 사람인데.. 너무 기분이 안 좋아서 리뷰 남겨요 ㅠㅠ 음료 키오스크로 주문하고 있는데 사장님께서 테이크 아웃 해야 한다고 말씀 하셨는데, 제가 쳐다보고 대답을 안 했어요 근데 이게 그렇게 화낼 일인가요..? 제가 음료 가지고 나가려는 찰나 사장님께서 저한테 말에 대답 안하면 기분 나쁘다고, 아까 못 알아들었냐고 엄청 소리를 지르시길래, 특히 사람들 다 있는데서 그러셔서 너무 놀라고 민망하고 당황스러웠네요.. 카페 한 번 갔다가 제가 뭔 큰 죄를 지은거 같은 기분? 억울해요 ㅜㅜ 카페 갔다가 이런 당혹스러움 느낀 적은 정말 처음이에요 ㅜㅜ 사장님 다른 분께는 이렇게 소리 지르시지 마세요.. 원래 여기 자주 오려 그랬는데 다음에도 사장님이 소리 지르실까봐 무서워서 못 오겠네요,,', 20, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '용량 큰것도 대박인데 제로 음료들도 다양해서 좋아요!! 자리 테이블도 넓고 의자 편해서 쉬다가는 느낌이에영 지하에도 자리있습니다!!', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '음료가 다양하고 넘 좋아요 다른 매장은 모르겠는데 합정점은 이렇게 스탬프 카드도 요청하시면 만들어주십니다 😆 저처럼 자주 오시는 분들은 이렇게 발급받으시는 것도 좋아요', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '제가 가본 디저트39중에 매장이 제일 이뻐요! 음식은 뭐 말해뭐해~ 디저트랑 음료 다 맛있고 디카페인 변경도 가능해서 선택의 폭이 넓어 좋아요!', 1, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '매장이 인테리어가 귀엽구 이뻐서 사진찍기두 좋구  의자도 너무 편해서 좋았어요! 그리고 자리도 적은인원부터 많은인원까지 앉을 수 있는 좌석들이 있어서 여럿오기도 좋은카페인거 같습니다. 그리고 프로틴관련음료 콜라겐 등등 몸생각하는 분들도 와서 드시면 좋을 메뉴가 많이 있더라구요!  운동시즌에난 프로틴음료먹으러 와야겠어욤!', 16, 10, 'GOOD', SYSTIMESTAMP);
