INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '자리도 넓고 음료도 디저트류도 다양해서 너무 좋습니다ㅎㅎ 깔라만시 스무디 등 다른 프랜차이즈 카페에는 없는 메뉴가 많아서 뭘 먹을지 고민되는 곳입니다ㅎㅎ 마치 ''너가 뭘 좋아할지 몰라 다 준비했어''인 카페네요🥹 정말 최고입니다👏👏', 49, 5, 'GOOD', SYSTIMESTAMP);
