INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '디저트39 크로칸슈가 맛있다고 해서 먹어봤는데 진짜 맛있었어요!! 오븐에 데워주셔서 겉은 바삭하고 안에는 아이스크림처럼 시원해요 ㅎㅎ 매장도 넓고 평일 저녁엔 조용하고 쾌적하네요~ 다 먹고 추가로 포장도 해갑니다', 23, 4, 'GOOD', SYSTIMESTAMP);
