INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '황치즈 슈크림 JMT 검정색 점은 바닐라빈인데 고급느낌 들고 걸쭉하니 진심 이름값하네 😭 대용량 사이즈도 있었음 좋겠네요 너~~무 맛있어요 ㅜㅜ 스탬프도 찍어주구.. 특색있고 음료종류도 다양해서 가고싶은 마음이 큼 🤩', 2, 5, 'GOOD', SYSTIMESTAMP);
