INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '알룰로스 사용한 음료가 있어서 부담없이 음료를 마실 수 있어요 너무너무 좋습니다. 매장도 관리가 잘 되었는지 청결해서 편안하게 쉬다 갈 수 있었습니다.', 107, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '어제 레드 리치슬림티에이드에 이어 깔라만시슬림티에이드 주문했는데 깔라만시도 맛있네요 👍 다만 사이즈가 고정된 사이즈로만 되어있어서 그점은 아쉬웠어요 황치즈슈크림jmt가 벤티사이즈밖에 안되서 😭 글고 오늘 세번째 방문인데 스탬프카드 찍어주셨어요 10개 적립 시 아아무료고 유효기간 1년이에요 자주오시는 분들 꼭 발급받으세요 😆', 45, 10, NULL, SYSTIMESTAMP);
