INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '토요일이라 시끌시끌하네요~😂 레드리치 슬림티에이드 주문했는데 대용량사이즈가 기본입니다 오 이거 요물이네요!! 넘 맛있고 레몬슬라이스도 있어서 보기에도 좋고 디자인도 이쁩니다 디저트39는 역시 대용량으로 먹어야쥬 😆 메뉴도 다양해서 다른 메뉴들도 도전해보고 싶은 마음입니다 ☺️', 140, 39, 'GOOD', SYSTIMESTAMP);
