INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '#아르기닌딸기요거트스무디JMT 기운 돋는 느낌? #황치즈크로칸슈 짭짤하니 맛있어요. #무료증정텀블러 한 달 동안 동일 매장에서 39,000원 이상 구매해서, 메리그린 돔 텀블러를 받았는데, 내 스타일은 아니라, 좀 아쉽네요. 이벤트 초기에 받은 지압은 이뻤는데…', 29, 0, NULL, SYSTIMESTAMP);
