INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '골목에 있어서 작을거라 생각했는데 공간도 넓고 매장이 아기자기한 소품들이 많아서 신선하네용! 메뉴종류도 많아서 다이어트 중인 분들도 고를 수 있는 음료 선택권이 넓어서 좋아요~~', 50, 7, 'GOOD', SYSTIMESTAMP);
