INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '디저트39 다른지점들도 많이 다녀봤는데 이곳이 인테리어가 가장 깔끔하고 직원분들도 너무친절하시네요. 디저트도 너무맛있고 조용히 티타임 갖거나 대화하기 좋은곳인듯 해요.', 1, 6, 'GOOD', SYSTIMESTAMP);
