INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '점심시간에 대화하기도 좋고 음악선정도 마음에 들어요🤍✨ 가성비 음료 맛있고 환경까지 생각하는 곳이라서 자주 오고 싶어지는..🫶🏻', 113, 20, 'GOOD', SYSTIMESTAMP);
