INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '절대비추. 디저트 드실거믄 걍 다른 디저트 카페 가세요. 얼어있는거 그대로 줍니다. 약간얼었네 가 아니라 걍 크림얼음임. 빵만 녹으면 주는듯', 66, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '입구에 커다란 핑크베어가 이끌려서 들어갔는데 다양한 디저트와 음료가 있어서 한번 또 놀랐어요🤪 녹차도쿄롤 정말 부드럽고 촉촉해서 너무 맛있게 잘 먹고 왔습니당 ! 매장도 깔끔하고 여기저기 감성소품이 많아서 사진찍기도 너무 좋아요👍👍 앞으로 합정디저트가 생각날땐 디저트39 합정역점으로 달려와야겠네요😆', 29, 4, 'GOOD', SYSTIMESTAMP);
