INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '마포카페 중 디저트39는 디저트가 진짜 너무 맛있어요 ~! 빵도 폭신하고 크림도 알맞게 달달해서 자꾸 생각나는 맛이에요💚💚 합정역점은 또 인테리어도 너무 깔끔하고 모던해서 사진도 잘나오고 자꾸 찾아오게되는 카페 입니다 :)', 84, 18, 'GOOD', SYSTIMESTAMP);
