INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '[마포 빵투어 후기 1탄] 감자 치아바타 3,900원 치아바타는 역시 크림치즈에 발라먹는게 맛도리 꼭 따뜻하게 데워드세요 노릇바삭촉촉🥐🥐 테이크아웃만 하러 온거라 녹을까봐 더티초코 구매는 못했지만 다음 빵투어 때 구매해보겠습니다 아우어 사랑혀,,,💛💛', 264, 61, NULL, SYSTIMESTAMP);
