INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '시드니에서 17일동안 밥 2번 외엔 빵만 먹다왔는데두 빵이 전혀 물리지가 않는 본투비빵순이로서 밥을 먹었지만 빵이 또 먹고싶은 이 현실...받아들여야죠 ㅎㅎㅎ 집에 오는길에 아우어가 보이길래 자연스럽게 들어가서 크로와상과 더티초코를 포장해서 집에 고이 들고왔어요 아우어는 음료보다는 빵을 특히 요 패스츄리류를 먹어야 합니다 아시죠? ^------^  제가 고른 크로와상과 더티초코 요2개가 젤 괜찮아요 나름 결이 디테일하게 살아있어요 글구 봉지가 이뻐서 ㅋㅋㅋ 포장해서 들고다닐때 더 기분좋아집니드아~~~~~', 12, 10, NULL, SYSTIMESTAMP);
