INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '팝업 구매 수량 제한이 있어서 좋았어요. MD상품 살 수 있어서 다행~^^ 근데 외국팬분들~~~ 그 많은 디저트와 음료 사서 어찌 처리하시려고 대량구매하시는지.. 아무리 랜덤 포카를 준다고 하지만... 음료는 그냥 버리는 모습도 봤는데 좋아보이지 않았어요. 케이크들도 버리시려나요?ㅠ 다른 팬분들을 위해 대량으로는 구매하지 말고 양보해요~ 버리는 것도 쓰레기 발생하는데.. 좋아하는 가수 이미지 생각하며 행동하는 팬들이 되길바라요~ (제가 간 타임과 바로 전 타임 외국팬분들 보고 남긴거예요. 다른 날은 안 그러길..)', 9, 8, 'BAD', SYSTIMESTAMP);
