INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '제 최애 빵집인데 최애빵만 골라봤어요 올리브 저거 진짜 부동의 1위 코코넛 크루아상 2위 나머지도 굿입니다 진짜 여기 빵집 이길 곳 없어요', 44, 3, 'GOOD', SYSTIMESTAMP);
