INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '가게가 큰줄 알았는데 작고 아래층은 앉아서 먹는곳이 없어서 계단을 좀 올라가야하네요 먹고 나가려니 바로 마감세일해서..ㅠㅜ 십여분차인데 아쉽네요..ㅠ', 12, 1, NULL, SYSTIMESTAMP);
