INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '원래 아우어베이커리 빵이랑 커피를 좋아해서 신촌에서도 들렀는데 원두 선택도 안되고 커피 맛이 생각보다 평범했어요 빵도 다른 곳에 비해 많지 않지만 뷰가 좋습니다. 직원분들이 조금 더 친절하시면 좋을 것 같아요.', 477, 53, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '빵알못인데 주변에 볼 일이 있어서 방문했다가 아우어베이커리가 있어서 시그니처인 더티초코와 빨미까레를 구입했습니다~ 사람이 많이서 먹고 갈거라면 좌석을 먼저 확인해야하는데 전 포장했어요~ 두 개 모두 맛있었어요! 다른 곳과 비교해본 건 아니라 특별히 더 맛있는지는 잘 모르겠지만 더티초코는 크로아상 사이사이에 초코칩도 있어서 씹히면 아주 맛있네요 :) 겉면에 코코아 파우더가 있어서 깔끔하게 먹기는 좀 힘들어요 입 주변에 파우더가 많이 묻..ㅎㅎ 맛있었습니다!', 77, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '빨미까레 생각나서 들렀어요. 아우어베이커리 빨미까레는 많이 달달해서 당충전하기 아주 좋습니다. 다른 빵들도 비닐 포장이나 덮개로 덮여 있으면 더 좋을 것 같아요!', 32, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '더티초코 포장 했어요~매장도 깔끔하고 예뻐요!!!빵도 보기 좋게 문 열자마자 보여서 좋았구 2층 매장도 탁 트인 풍경이 좋았습니당 ㅎㅎ', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '용산점에 빨미까레 요근래 구경도 못하다가 산책나온 신촌숲길점에 있길래 냉큼 구매하러 들어갔는데 레밍턴이 있더라고용. 빨미까레야 아우어 것이 맛있어서 더 말할것도 없는데.. 레밍턴도 맛있었습니다. 코코넛레밍턴 진짜 좋아하는데 다른곳에서 겨우 찾으면 딸기잼 들어가있고 이런게 너무 아쉬웠는데 요기는 딱 코코넛 맛으로 즐길 수 있어요. 맛있습니다.', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '아우어베이커리하면 더티초코! 오랜만에 그맛이 생각이 났고 신촌에 매장이 생겼길래 방문 했습니다 본점에서만 먹었어서 그런지 옛날이랑 맛이 달라진것 같습니다 처음먹었을때의 두눈 휘둥그레해지던 그맛은 없어진거 같아요 안에 빵결도 퍽퍽하고 초코양도 적고 특유의맛도 느끼기 미미합니다 그래도 맛있게 잘먹었습니다! 가격&퀄리티 대비 이정도의 빵오쇼콜라를 만들어내는 베이커리들이 많아져서 다음구매는 조금 고민하게 될것 같습니다', 0, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '슈톨렌 처음엔  가운데 초코인줄 알고 넘 달까봐 걱정했어요. 무화과 절인거고 많이 달지 않고 맛있네요 양이 조금 아쉽지만 선물용으로 케이스도 이쁘고 좋아요~', 3, 0, 'GOOD', SYSTIMESTAMP);
