INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '신규매장이라 2층 매장은 너무 시끄러워서 늘 포장합니다. 더티초코는 매번 품절이라 못먹어봤고 슈크림 단팥빵, 빨미까레  추천 퀸아망은 비추 합니다', 57, 15, NULL, SYSTIMESTAMP);
