INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '베이컨치토 베스트라고 되어 있어 주문해봤는데 크기와 맛 무엇....?이거진짜 베스트 맞음????????? 그리고 여긴 화장실이 지인짜 별로..', 56, 14, 'BAD', SYSTIMESTAMP);
