INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '(2인기준 1만1500원) 편안하고 음악 볼륨도 적당하고 친절하시고 좋아요^^ 화장실은 한칸이라 비좁네요ㅎㅎ 카페인에 약해서 디카페인라떼를 주로 먹는데 퍼스널옵 두유로 바꿔먹으면 짱맛있어요! 강추합니다~~♡', 38, 2, 'GOOD', SYSTIMESTAMP);
