INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '샐리?엘리?라는 이름 가지신분 너무 불친절하시네요 주문한 메뉴 확인 위해 다시한번 불러달라했더니 온갖 짜증을..ㅎ 이 분 빼고 다른분들은 너무 친절하세요', 19, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오디너리 아카이브'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '한겨울에 2명이서 방문했는데, 2명 중 다른 1명은 팬이 아니어서 주문을 안했죠. 결제한 1명이 안에 들어가서 빠르게 사진만 찍고 나올 거니까, 다른 1명은 입구에서 잠시만 기다려도 되느냐고 했더니 나가라네요. 그날씨에. ㅎㅎ대단하세요.', 16, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '철판 아이스크림 만들기 체험 쉽고 재밌어요~! 재료 준비 해주시는게 알차고 아이스크림 맛도 너무 맛있어요 시원하고 플레이 되는 음악 넘 즐거워서 신나게 놀다갑니다! 분위기가 넘 좋아요 감성 넘쳐요~!~! 또 오고 싶어요', 3, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
