INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '생각보다 조금 어려웠지만ㅋㅋㅋㅋ더운 여름에 시원하고 재밌게 체험할 수 있었어요!!! 9월까지 하기 때문에 일찍일찍 예약하셔서 체험하시길 추천드려요🍨 체험이 중심이니 맛은 크게 기대 안했는데 진짜 너무 맛있었어요,,,🥰🥰', 84, 14, 'GOOD', SYSTIMESTAMP);
