INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '분위기가 아늑하고 재료 구성도 알차서 가족 연인 친구와 방문해서 체험하기 좋은 것 같아요. 안내 영상도 30초 내외로 짧게 잘 안내되어있어 따라하기 편합니다. 겨울에는 다른 체험하러 오려구요 ㅎㅎ 재미있는 경험이었습니다~', 37, 3, 'GOOD', SYSTIMESTAMP);
