INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이색 데이트로 너무 좋았어요~~! 그리고 비쥬얼은 초보자가 만들어서 (끔찍) 했지만 맛은 전문가 저리가라였어요~~ 👍👍☺️ 그리고 양도 많아서 너무 좋았어요~! 총 3번 만들어 먹을 수 있고 저희는 노멀하게 초코, 우유, 요거트 조합 골랐어요~! 초보자분들은 강추!☺️', 28, 10, 'GOOD', SYSTIMESTAMP);
