INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '진짜 너무 즐거운 경험이었습니다. 철판 아이스크림을 3번 만들어 먹을 수 있는데 직접 만들어 먹으니까 사먹는 것보다 훨씬 맛있는거 같기도 하고 내부도 이뻐서 음식 포함해서 사진이 잘 나오니까 너무 행복해요. 연인 혹은 친구랑 놀러오기 좋은 곳입니다.', 33, 9, 'GOOD', SYSTIMESTAMP);
