INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '토핑 종류가 많아 여러가지 맛 아이스크림을 만들 수 있어서 좋았어요! 철판아이스크림 보기에는 쉬워보였는데 생각보다 넘 어려웠어유,, 근데 넘 재밌었습니다 !!😎🙌데이트로 넘넘 좋아요~', 38, 2, 'GOOD', SYSTIMESTAMP);
