INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '철판에 아이스크림을 만든다는 게 흔치 않은 경험인데 이렇게 접근성 쉽게 재밌는 체험을 해서 좋아요! 여자친구랑 같이 와서 재미나게 만들고 달달하고 시원한 아이스크림 맛있게 먹고 일석이조였어요!', 79, 12, 'GOOD', SYSTIMESTAMP);
