INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '너무 재밌게 놀다 가요~!! 기본으로 주시는 토핑 과자가 종류가 많아서 조합 고민해보는 것도 재밌어요 초코는 많이 달달하니 제일 마지막엔 요거트+과일 조합으로 입가심하시는 걸 추천드려요 :)', 14, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '너무 재밌었어요!! 영상에서만 보던 철판아이스크림을 직접 만들어보니 새로운 경험이었고, 더운 여름에 시원하게 충분히 양껏 아이스크림먹을 수 있어서 좋았어요!! 또 방문하고 싶어요ㅎㅎ 이색데이트로 추천합니다!!!👍🏻👍🏻', 50, 3, 'GOOD', SYSTIMESTAMP);
