INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '첫 철판아이스크림입니다~~! 남자친구랑 데이트로 놀러왔어요ㅎㅎㅎ 그동안 너무해보고싶었는데 알찬재료로 즐겁게 잘만들어먹구가요!! 간식거리가 다양해서 고를수있는 선택지가 많은게 가장좋았어요! 겨울에 타코야끼만들러 다시올게용', 8, 9, 'GOOD', SYSTIMESTAMP);
