INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '남자친구랑 이색데이트로 예약하고 이용했어요 세가지 맛에 과일토핑도 1가지 고를수잇고 이거저거 섞을 수 있는 과자 종류도 너무 다양해서 골라서 만드는 재미가 너무 좋았어요 겨울에 꼭 또오기로 했어요><', 6, 1, 'GOOD', SYSTIMESTAMP);
