INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '인스타에서 보고 예약 후 방문했는데 너무 색다른 경험이었고, 재밌었어요! 토핑 종류도 많고, 친절하게 잘 알려주셨어요 방법 모르면 동영상으로도 방법 설명되어있어 좋았습니다! 즐거운 시간 보내다 갑니다!', 38, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '좌식이고 기본 토핑들이 다양해요 ㅎㅎ 베이스도 밀크로 기본 하나 나오고 추가적으로 2개 선택할 수 있습니당 ㅎㅎ 그래서 총 철판 3개 아이스크림 만들 수 있어요!! 약간 체험형 위주라서 70분 지나면 나가야합니당🥹 완전 맛있었어요 🩷', 78, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '철판아이스크림을 직접 체험하면서 먹을 수 있어서 너무 재밌었어요. 처음은 실패했지만 두번째 세번째는 나름 성공😁 이색데이트 코스로 추천 아이스크림 존맛👍', 81, 12, 'GOOD', SYSTIMESTAMP);
