INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '저번엔 타코야끼였는데, 이번 여름엔 시원한 철판 아이스크림으로 바뀌었더라구요🍦❄️ 매장은 아담하고 아기자기해서 커플들끼리 데이트 장소로 딱이에요💕 분위기도 포근해서 잠깐 들르기에도 좋았어요☺️✨', 87, 18, 'GOOD', SYSTIMESTAMP);
