INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '철판 아이스크림을 직접 만들어볼 수 있다니! 정말 신기하고 즐거운 경험이었습니다! 친구랑 같이 방문했는데 서로 만드는 걸 보면서 비웃기도 하고 대화도 많이 나눌 수 있었어요! 생각보다 만드는 게 쉽진 않더라구요.. 그래두 이런 경험 아주 귀하고.. 좋았습니다! 강추합니다🤍', 2, 5, 'GOOD', SYSTIMESTAMP);
