INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '우유믹스 포함해서 총 3개의 믹스를 주고 과일도 선택가능해요! 과자도 엄청많이 주셔서 마음대로 끄미기 좋네여 저흰 너무 배불러서 다못머것어요 양 진짜 많구 너무재밌어욬ㅎㅋㅎㅎㅋ 담에 타코야끼 만들러놀게요', 40, 6, 'GOOD', SYSTIMESTAMP);
