INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '철판 아이스크림은 처음 만들어보는데 너무 이색적이고? 재밌었어용!! 홍대 코스로 추천합니다 👍🏻👍🏻 자리는 그 때 그 때 자리가 나면 나는대로 앉는 방식이구 담요 등 구비되어있어서 좋았어요~~', 32, 5, 'GOOD', SYSTIMESTAMP);
