INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '동생이랑 서울 놀러와서 방문했어용 ㅎ.ㅎ 유튜브에서만 보던 철판아이스크림 만들기를 직접 해볼 수 있다는 게 정말 특별하구 새로워요 !! 새롭기만 할 뿐 아니라 베이스 자체 맛도 너무 맛있었오요..♥ 겨울에 타코야끼 만들러 또 방문하겠슴니다아 ෆ˃̵͈̑ᴗ˂̵͈̑ෆ', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '아이스크림 종류도 3개나 만들었구, 주시는 토핑들도 넉넉해서 여자친구랑 행복하게 많이 먹구 놀다가요!!! 가격이 아깝지 않은 재미있는 경험이었습니다!~ 다음에 또 올게요 😋😊', 59, 11, 'GOOD', SYSTIMESTAMP);
