INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '데이트 하려고 예약 후 방문했어요 내부 인테리어도 예쁘고 재료도 많이 주셔서 배뷰르고 재밌게 놀다 가요 겨울에 다코야끼 할때도 오고싶어요!!', 72, 18, 'GOOD', SYSTIMESTAMP);
