INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '오자마자 인테리어가 너무 이뻐서 사진부터 찍었어요🫶🏻 재료도 엄청 많이 주시고 양도 많아서 시간가는줄모르고 만들었어요!! 덕분에 색다른 경험을 할 수 있어서 즐거웠어요ㅎㅎ', 42, 5, 'GOOD', SYSTIMESTAMP);
