INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '생각보다 예쁘게 만드는게 쉽지 않았는데, 세가지 맛으로 만들 수 있어서 마지막에 만들땐 예쁘게 만들기 성공했어요 ㅎㅎ 덥고 많이 걸어서 다리도 아팠는데, 시원한 곳에서 재밌고 맛난거 시간가는 줄 모르게 만들고 잘 쉬다가 왔어요 ! 담번엔 타코야키 만들러 오고싶어요 ◡̎', 19, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '아이와 예약하고 왔습니다^^ 아이가 기대한만큼 너무 재밌게 아이스크림 만들기 했습니다~^^*꽤 넉넉한 시간에 만드니 편안하게 즐길 수 있어서 좋았습니다~아이도 즐거워해서 행복했습니다^^', 75, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '직원분들도 친절하시고 공간도 아늑해서 좋았어요! 이런 이색체험 해볼 수 있는 곳 많이 없는데 서울여행 와서 도란도란에서 재밌는 체험하고 갑니당 😘', 16, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '철판아이스크림을 직접 만들어볼 수 있다는것이 정말 신기하고 재밌었고 맛있었어요!~친구랑 와도 즐거운데 연인이랑 같이 하면 더 재밌을것 같아요😆', 66, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '일본에서 온 친구랑 이색데이트하러 왔는데 완전 만족했어요👍🏻 아이스크림이랑 토핑 양도 완전 넉넉하고 처음이라 미숙해서 사장님께 여쭤보면 잘 알려주셨습니당 담에 기회가 생기면 또 오고싶어요! 덕분에 좋은 추억 쌓았습니다💓', 107, 23, 'GOOD', SYSTIMESTAMP);
