INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '재밌고 맛있고 인테리어도 아기자기하고 좋습니당ㅎㅎ 더운 여름에 실내 데이트로 추천해요! 구성도 알차고 둘이서 총 3번 할 수 있어서 충분하고 좋아요 겨울에 다코야끼도 하러 와보고 싶네용ㅎㅎ', 63, 16, 'GOOD', SYSTIMESTAMP);
