INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '아이가 유치원에서 친구에게 듣고와서 너무 가고싶다고 하더라구요 아이스크림을 좋아하는 아이인데도 만들 수 있는 아이스크임 양이 많아서 다 못먹겠다고 하더라구요😅 색다르고 재미있는 경럼이었어요', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '더운 여름에 이색적인 체험해 볼 수 있어서 너무 좋았어요!! 아이스크림 진짜 짱 맛있어요🍨🤤 다음에 또 오려고요! 리뷰이벤트 브라우니도 진짜 좋았어요🥴 좋은 추억 만들어주셔서 감사합니다😚', 0, 10, 'GOOD', SYSTIMESTAMP);
