INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '겨울에 타코야끼 했던 좋은 추억을 가지고 다시 방문했습니다!!! 철판아이스크림 한번쯤 만들어보고 싶었는데 너무너무 재밌었어요 ㅋㅋㅋㅋ 생각보다 어려운데 💕꿀팁은 한번에 쭉 밀고 너무 꽝꽝 얼기전에 밀기!!!!💕 진짜 이색데이트 중에 젤 신기했음 ㅋㅋㅋ', 139, 59, 'GOOD', SYSTIMESTAMP);
