INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '아이가 베트남에서 철판아이스크림을 먹어본 뒤로 자주 사달라했는데 파는 곳이 없어 선택한 체험이었는데 너무 재미있었다고 하네요. 감사합니다', 13, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '[리뷰사진 sns에 사용하셔도됩니다🥰🥰❤️] 진짜 신기한 경험이였어요. 철판아이스크림은 원래 좋아했는데 이렇게 직접 만들어보니까 신기하기도 하고.. 70분정도 진행되는데 애인이랑 같이 만드니까 더 신기하고 재밌더라구요!! 직원분들도 친절하시고, 예약해서 가면 더 좋아요^^ 세 번 시도해봤지만 한번도 똥글똥글하게 못 말았지만..ㅎㅎ 즐거웠습니다! 겨울에도 또 와보고 싶어요~~', 22, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '남자친구와 더운 날 시원하게 데이트 할 곳을 찾다 오게 되었어요! 아이스크림 맛은 우유맛, 선택2개 맛 총 3가지를 만들 수 있었구, 토핑도 굉장히 다양하고 맛있어서 각각의 맛에 어울리는 토핑들을 골라 아이스크림을 만들 수 있었어요 😊 처음엔 하는 방법이 서툴러 잘 만들지 못했는데, 두번째부터는 잘 만들어져서 기분도 되게 좋았어요! 데이트로도, 아이들과 시간 보내기도 매우 좋을 것 같습니다 🥰👍🏻👍🏻', 43, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '남자친구랑 데이트로 와서 만들어봤는데 생각보다 어려워서 이쁘게는 안만들어졌지만 너무 재밌었어요!! ㅋㅋㅋㅋ 데이트로도 좋고 친구랑 하는것도 좋은 경험이 될 것 같아요 추천합니다 !!', 31, 8, 'GOOD', SYSTIMESTAMP);
