INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '꽤 오래전에 예약성공해서 다녀왔어요 아기자기 넘 귀엽고 약간많이실패해도ㅋㅋ재밌네요 아이가 원하는 아이스크림을 아주실컷먹을수있어요', 484, 52, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '아이랑 아이스크림 만드는 경험하러 왔어요!! 만들기도 재미있고 토핑도 다양하고 직접 만들어서 먹으니 더 맛있네요! 아이랑 무더운 여름날 체험하기 좋은곳🤍', 62, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '철판 아이스크림 유행할 때 만들어 보고 싶었는데 너무 재밌는 경험이였어요 ! 토핑도 여러가지 많아서 고르는 재미가 있었어요 직원분들도 친절하시고 중간중간 잘만드는 꿀팁도 알려주셔서 너무 감사했어요~ 요즘 같이 더운날 실내 데이트 코스로 딱인것 같아요 추천합니당😻😻', 78, 14, 'GOOD', SYSTIMESTAMP);
