INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '여자친구랑 왔는데 너무 즐거운 데이트였어요~~ 맨날 한강이나 길거리에서 먹었는데 직접 해먹을 수 있어서 즐거웠습니다~~ 다만 첨이다보니 만드는게 어려웠었는데 직원분한테 도움요청하면 친절히 알려주셔서 다행이었어요~ 마지막에 겨우 동그랗게 마는데 너무 행복했어요~~ 담에도 또 방문할거 같아요😄', 14, 10, 'GOOD', SYSTIMESTAMP);
