INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '찰판 아이스크림  만들기 너무 재밌었어요 완전 처음 먹어봤는데  과자 넣어서 만드는 것도 넘 신기했구 직접 만드니까 더 맛있었습니당! 같이 만들어서 더 재밌는 이색체험이었어요 재방문 의사 100입니당!!', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '딸아이가 유튜브에서 발견하고 오고 싶다고 해서 오게 되었어요. 처음엔 주말에 예약 없이 왔다가 예약 마감으로 못 들어오고 다시 평일 오후에 예약하고 왔어요. 재미있게 아이스크림 만들고 좋은 시간 보냈어요. 체험 시간은 70분이고 아이스크림 3번 만들 수 있게 재료 주세요. 토핑용 과자가 다양해서 취향껏 만들 수 있어요', 439, 89, 'GOOD', SYSTIMESTAMP);
