INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '아이가 철판아이스크림을 만들어 보고 싶어해서 예약 후 방문했어요~ 돌돌 마는게 쉽지는 않았지만 만들기 과정이 재미있고 맛있어요. 더운 여름날 아이스크림을 직접 만들어 먹으며 아이와 특별한 추억을 만들 수 있어서 좋았어요:)', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '철판아이스크림 당일에 가려니까 예약 실패해서 1달전에 에약해놓고 드디어왔습니다!! 진짜 재밌고 기대했던만큼 신났는데 또 맛도있어서 행복햤습니다ㅎㅎ', 32, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '인기 많은 곳은 왜 많은지 알겠어요:) 컨셉도 재밌고 사장님도 친절하시고 아이랑 가서 걱정했는데 분위기도 아늑하고 사진 찍을 수 있는 소품도 있어 아이스크림 머리띠 끼고 아이랑 기분 내고 왔네요 ~ 좋은 경험이었어요. 감사합니다.', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '겨울에 타코야끼일때도 너무 재밌고 맛있었어서, 철판 아이스크림 한다길래 바로 예약하고 달려왔어요! 너무 아기자기하고 즐거운 시간 보내다갑니다~!', 19, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '특이한 컨셉에 눈길이 갔어요 !! 재료들도 귀엽구 다양하고 좋았구, 다들 친절하게 설명해주셔서 좋았어요 ! 아이스크림 쉽게 만들수 잇구 좋았네요 또 올게요', 114, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '아이스크림 맛은 2가지 고르고 토핑은 1가지 선택 가능한데 기본으로 주시는 토핑들도 많았어요! 하면서 손에 묻을 수밖에 없는데 물티슈도 주셔서 좋았습니당... 아이스크림도 어엄청 먹었네용 재밌었습니다!!!', 41, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '일덩 매우 재미있습니다! 공간도 매우 귀엽게 잘 꾸며져 있어요! 어려운줄 알았으나 밀대 위아래만 잘 구분한다면 생각보다 잘 말려요…', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '인스타에서 보고 예약했는데 너무 재밌었어요! 이래저래 조합을 만들어서 먹어보면 의외로 맛있는 조합도 있더라구요! 인테리어도 아기자기하고 만들어 먹는 재미도 있어요! 데이트 코스로 추천🌼', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '릴스에 철판아이스크림 만드는 곳이 떠서 재미있어보여서 친구랑 와봤는데 철판아이스크림 만드는 곳이라 신박하구 여름에 시원하게 있을수 있어서 너무 좋앗습니다!! 친구랑 수다 떨기도 좋고 만드는게 재미있어서 한번쯤 오시는 거 추천 드립니다👍', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '재밌었습니다! 총 3번 할수 있는 셋트로 나오는데 토핑은 넘치게 써도 충분했고 시간 순삭해요~! 첫번째시도는 실패해서 제대로 안말렸고 ㅠㅠ 두번째, 세번째는 좀더 보완해서 잘 된거같아요 ㅎㅎ 영상은 두번째시도의 영상이에요~! 동남아에서 먹었던 철판아이스크림 생각나고 그러네용 ㅎㅎ 색다른 경험이라 재밌긴했습니다! 재료만 생각하면 비싸다고 생각 할 수 있지만, 체험하는 부분으로 생각하고 나만의 DIY 아이스크림이라고 생각하면 가격대비 나쁘지 않다고 생각해요! ⭐️솔직리뷰⭐️', 33, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '너무 재밌어요 완전 이색데이트고 더운날 아이스크림까지 딱 먹으니까 진짜 좋았어요!! 재방문의사 100퍼!!!❤️❤️❤️❤️❤️', 12, 10, 'GOOD', SYSTIMESTAMP);
