INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '타코야끼에 이은 철판아이스크림!!! 직접 만들어 보고싶었는데 너무너무 재미있고 맛있었습니다!! 맛도 고를 수도 있어서 재밌던 체험이에요~❤️ 다음엔 토핑 안넣고 만들어 보려구용 히힣 담에 또 오겠슴돠아ㅏ아ㅏㅏ ^0^7', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '양도 많고 종류도 다양하게 마음대로 조합해 먹을 수 있는 철판아이스크림을 실제로 만들어 볼 수 있어서 좋아요!! 국내에 최초라고 해서 신기해써용 ㅎ 맛있어용', 108, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '재밌게 만들어 먹었어요! 토핑도 다양하고 같이 먹을 과자도 있어서 도란도란 앉아 이야기하며 만들어 먹었어요 하절기에 데이트하기 좋은 곳이에요!', 0, 3, 'GOOD', SYSTIMESTAMP);
