INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '어렸을 때부터 철판 아이스크림 만들기에 대한 로망이 있었는데 처음으로 해본것 같아서 너무 신나고 좋았어요💖 사장님도 너무 친절하시고 안내도 너무 잘해주셔서 재방문 의사 100프로입니다😍✨ 겨울에 타코야끼할 때도 다시 올게요😳💓', 29, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '두번째 방문인데 역시나 너무 좋았어요!! 집에서 할 수 없는 철판 아이스크림을 싸고 재밌있게 체험했어요!! 다음에 또 오겠습니다^__^', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '이색데이트 하기 좋은것 같아요~~ 토핑이랑 종류도 다양하고 맛있고 데코하는 재미도 있어용 🫶🏻✨ 완벽한 어른이들의 놀이터같습니당', 45, 4, 'GOOD', SYSTIMESTAMP);
