INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '친구랑 놀러왔다가 예약하고 왔는데 진짜 너무 잘 온거같아요 구성도 알차고 맛있고 아런 체험 너무 신선해서 좋았어요. 다음에 또 오고파요ㅠ😭 사장님설명 너무 친절해서 감덩❤️☁️ 또올게여☁️❤️', 5, 5, 'GOOD', SYSTIMESTAMP);
