INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '물이 먹고 싶어지는 달콤함에 절여질 것 같은 맛이었어요! 저희가 재료 너무 마구잡이로 넣어서 좀 맛이 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 웃겼는데 만드는거 자체로는 너무 재밌었고 한 번쯤 데이트로 오시기 좋아요~~', 51, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '타코야키할때 너무 재밌게 하고 가서 아이스크림도 기대하고 왔는데 진짜 재밌었어요!! 아이스크림도 사먹는 것보다 맛있고 토핑도 여러가지 많이 챙겨주십니당 홍대에서 이색체험 이색데이트 찾는다면 정말정말 좋은 것 같아요!! 재밌고 맛있는 경험 하구 갑니당~!!', 12, 1, 'GOOD', SYSTIMESTAMP);
