INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '최고의 철판 아이스크림 만드는 카페! 철판 아이스크림도 올리고 싶었지만 비주얼 이슈로 패스입니다…🤣 친구들이랑 함께 왔는데, 웃고 떠들고 너무 즐거웠어요! 게다가 기회도 3번이나 있어서 번갈아서 하고, 같이도 하고 좋더라고요. 무엇보다! 기본 제공되는 토핑이 많아서 만드는 재미가 아주 쏠쏠했어요. 친구들이랑 오기 너무 좋은 것 같아요. 도란도란, 최고! ps. 못하는 친구와 함께하면 재미가 더 배가 된답니다🥴', 45, 1, 'GOOD', SYSTIMESTAMP);
