INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '준비물 양말이 있습니더. 7세 아이와 했는데 생각보다 아이가 잘 할 수 있어요. 과자를 너무 많이 넣으면 잘 안말리니 적당히 넣는 걸 추천합니다🤣 아이와 할 땐 과일 한 종류만 넣는 게 잘 말립니다!!', 56, 18, 'GOOD', SYSTIMESTAMP);
