INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '철판 아이스크림 체험이라고 해서 여자친구랑 와봤는데 너무 재밌었습니다! 만들 수 있는 재료들도 많고, 하는 방법도 쉬워서 재밌게 만들고 맛있게 먹었습니다!', 30, 4, 'GOOD', SYSTIMESTAMP);
