INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '철판아이스크림 만드는 것도 재밌고 맛있어요! 과자도 그렇고 베이스도 달달한편이라 상큼한 베이스를 같이 하면 좋더라고요! 양이 많아서 디저트 안먹고 여기만 와도 좋을 둣해요!', 16, 2, 'GOOD', SYSTIMESTAMP);
