INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '여름 데이트로 딱인 것 같아요!! 토핑도 다양하고 처음해보는 거라 그런지 재밌었어요😋 다만 뒤로 갈수록 철판 온도가 확연하게 내려가서 아이스크림을 빨리 만들어야 할 것 같아요! 자꾸 깨지더라구요', 65, 13, 'GOOD', SYSTIMESTAMP);
