INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '철판아이스크림 만드는거 너무 재미있어요 토핑 많이 넣으면 너무 다니까 조심하세요 우유 초코유유 딸기우유 세잔인데 한잔당 철판아이스크림 하나씩 만들 수 있어요 토핑도 여러가지 종류가 많아서 먹고싶은 거 넣고 막 섞어서 만드는 과정이 정말 재미있었어요', 124, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '철판 아이스크림은 영상으로만 보다가 직접 만들어서 먹어보니 신기했어요! 손재주가 좋지 않아 만들긴 힘들었지만 ㅎㅎ 가게 분위기도 아기자기하고 직원분도 친절해서 기분 좋게 체험하고 왔습니다 데이트 장소로도 넘 좋을 것 같아요!', 22, 3, 'GOOD', SYSTIMESTAMP);
