INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '쉽게 접할 수 없는 체험을 해 볼 수 있어서 좋은 데이트였습니다. 맛도 다양하게 조합 할 수 있고 시간도 넉넉해서 만들기 좋아요!!', 34, 9, 'GOOD', SYSTIMESTAMP);
