INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '친구와 재밌는 거 뭐있나하고 고민해서 왔는데 과자도 엄청 많고 재밌고 진짜 맛있었어요!! 혈당 스파이크 온 것 같은데... 달달구리 수혈 제대로 했다....!!', 7, 2, 'GOOD', SYSTIMESTAMP);
