INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '철판아이스크림 만들기 처음 해봤는데 너무 재밌어요><아이스크림도 맛있고 토핑도 충분하게 주세요 생각보다 얇게 펴서 돌돌말기 어려워요ㅎㅎㅎ 겨울에 타코야끼 만들러 또 오고싶네용ㅎㅎ', 95, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '전부터 해보고싶어서 친구 꼬셔서 왔는데 재밌었어요🤗 근데 생각보다 롤 마는게 어렵긴 했는데 과자 종류도 많고 분위기도 좋아서 추천합니다👭', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '철판아이스크림 파는곳 잘없는데 이렇게 체험이랑 같이 해서 먹을수있어서 너무 좋았어요 사장님도 친절하시고 토핑도 많이 주셔서 데이트 목적으로 추천합니다!', 8, 1, 'GOOD', SYSTIMESTAMP);
