INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '컨셉이 독특하고 재밌어요🥺🩷 맛도 있고 구성도 알차서 이색 데이트로 최고에요! 겨울에는 와서 타코야끼 만들었는디 여름에는 철판아이스크림이라니 너무 좋아요!!', 36, 2, 'GOOD', SYSTIMESTAMP);
