INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '선택한 맛 말고도 기본으로 우유맛도 주시고, 토핑도 다양해서 좋아요! 토핑 다 못쓸정도로 많이주셔요 ㅋㅋ 좋은 체험 할 수 있게 해주셔서 감사합니다! 겨울에는 타코야끼 만들러 올게용!', 17, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '공간도 아늑하고 너무 시원해서 좋았어요!!! 철판아이스크림 만들기 너무 재미있어요~ 토핑도 많고 아이스크림양이 많아서 배불리먹고 왔네요^^ 아이와 함께 즐거운추억만들었습니다^^', 44, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '생각보다 양이 많아요! 세 번이나 할 수 있어요. 맛있기도 맛있고!! 토핑도 엄청 다양해요. 재미있는 경험이었습니다ㅎㅎㅎ 재능을 찾은 것 같아요(?)', 14, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '여자친구랑 오래 전부터 와보고싶었는데 기회가 돼서 처음 와봤어요! 만드는 방법도 사장님이 친절하게 알려주셔서 재밌게 만들 수 있었어요!! 아이스크림은 초코맛이 특히 맛있었습니다', 8, 0, 'GOOD', SYSTIMESTAMP);
