INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '직접 만든 거라 더 맛있는 느낌! 오랜만에 새로운 데이트 하고 가서 너무 좋았어요 어려워서 실패했지만 그래도 넘 잼슴ㅋㅋㅋㅎㅎ', 5, 2, 'GOOD', SYSTIMESTAMP);
