INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '지하 1층에 자리 잡은 도란도란은 마치 다락방 같은 아늑한 공간이었어요! 신발을 벗어야 들어가는 좌식 구조로, 소소한 복고 감성이 느껴지는 분위기 너무 좋았어요! 아기자기한 소품들과 담백한 조명 덕분에 체험하는 동안 계속해서 사진을 찍고 싶어지는 공간이었어요!', 108, 21, 'GOOD', SYSTIMESTAMP);
