INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '미리 예약 후 이용했어요! 처음이라 걱정했는데, 사장님께서 친절하게 안내해주셔서 편하게 만들고 맛있게 먹고 왔습니다! 여름 지나가기 전에 또 오려고요!', 74, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '예약하고 방문했는데 너모 재밌는 철판 아이스크림 만들기 체험이었어요! 양도 절대 적지 않고 토핑도 많아서 귀엽고 다양하게 만들 수 있었어용 완전 맛있었습니당!', 51, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '기본으로 우유 베이스가 하나 나오고 원하는 맛 2개와 토핑 1가지를 고를 수 있는데 3가지 베이스로 총 3번 해먹을 수 있으니까 양도 많았던거 같고, 베이스의 종류가 다양해서 좋았어요! 그리고 기본으로 나오는 토핑과 과자들도 잘 넣어서 맛있게 먹었습니다!', 0, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '남자친구가 저보다 재미있어했어요!!ㅋㅋㅋㅋㅋ 세판 만들 수 있는데 딱 적당하고 좋은 거 같아요 한번쯤 체험해보기 좋은 거 같아요😚', 50, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아이가 유튜브에서 보고 꼭 가보고 싶다 해서 예약하고 먼 길 왔어요ㅎㅎ생각보다 작고 아담한 공간에 아기자기 잘 꾸며놨네요. 이색적이고 귀여워요^^ 아이가 많이 좋아하네요 ㅎㅎ', 130, 26, 'GOOD', SYSTIMESTAMP);
