INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '철판아이스크림을 만들 수 있다니 아이디어 넘 조아요><,,,,남자친구랑 왔는데 사이가 더 좋아졌어요~~철판아이스크림 만드시는 분들 정말 대단해요!!👍', 83, 11, 'GOOD', SYSTIMESTAMP);
