INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '어릴 때 하던 철아따를 진짜 하다니 ㅠㅠ 너무 재밌었고 색다른 재미라서 좋았어요 데이트로도 친구랑 놀러와도 좋은 추억 쌓을 것 같아요 굿굿', 3, 5, 'GOOD', SYSTIMESTAMP);
