INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '내부가 아늑하고 사용법도 쉬워서 재밌게 만들어 먹을 수 있었어요~!! 처음 해보는 철판 아이스크림인데 이색체험으로 정말 재밌었습니다👍', 86, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '3가지 맛 철판아이스크림 만들 수 있어요!! 생각보다 어려워서 더 재밌게 만든거같아요 토핑도 많으서 주워먹는 재미도 있었습니당~~', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '남자칭구랑 겨울에 다코야끼 만들기 재밌게 했던 기억으로 칭구랑 같이 체험예약 하려보니까 여름메뉴로 바뀌었더라구요🤭 직접 만들어먹는 철판아이스크림이라니.. 어쩜 이런 생각을 하신건지👍🏻👍🏻👍🏻 맛도 3가지에 다양한 과자랑 과일도 있어서 여러가지 맛 조합으로 만들어 먹으니 시간가는줄 모르고 체험했어요😍 동남아 여행가서 먹었던 철판아이스크림 맛보다 100배 이상 맛있어요 얼음씹히는 맛 안나구 진짜 부드럽고 맛있더라구요😖 돌돌말릴때 쾌감이란!!!! 조만간 남자칭구랑 꼭 같이 또 방문하겠습니다!!', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '초등 4학년 딸이랑 방학이라 처음 와봤어요. 아이가 넘 좋아해서 저도 기쁘네요. ㅎㅎㅎ 재미도 있고 아이스크림도 맛있고. 무엇보다도 아이가 원하는대로 직접 선택해서 만들 수 있어서 더욱 좋았어요. ㅎㅎ', 73, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '방학기간에 특별한체험을 하려고 아이들과 다녀왔어요! 철판아이스크림 만드는건 색다르고 잼있게 잘만들었어요~ 다만 더운데 기다릴수있는 공간이 전혀없어서 좀 불편했고 직원분이 친절하진 않았습니다', 20, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아이가 가보고 싶다고 해서 예약 후 방문했습니다. 처음 해보는 건데 친절한 설명과 영상까지 있어서 하기에는 어렵지 않았습니다. 타코야끼 할 때 또 올게요^^', 110, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '알고리즘에 떠서 방문하게 되었습니다. 토핑 조합을 잘해야되겠더라고요,, 단 걸 많이 좋아하진 않는데 조합 실패해서 굉장히 달게 먹어서 조금 아쉬워요ㅠ 그치만 직접 다지고 마는데 너무 생소하고 재밌었어요! 알고보니 겨울에 코타츠, 타코야끼 만들기 체험할 수 있는 곳이더라고요? 올 겨울 데이트도 이곳으로 정해졌습니다', 21, 2, 'GOOD', SYSTIMESTAMP);
