INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '매장이 아늑해요. 아이스크림을 만들 수 있어서 재밌고 시간이 빨리 갑니다. 재료를 많이 주셔서 배부르게 먹고 가요!! 데이트 장소로 추천합니다 ㅎㅎ', 89, 13, 'GOOD', SYSTIMESTAMP);
