INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '딸기랑 초코맛했는데 딸기에 과일토핑 딸기추가해서 먹으면 너무너무너무 맛있어요 마지막쯤 마는 방법을 알아서 아쉬웠지만 ㅜㅜ 담에 또 올게요!', 30, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아이랑 같이 예약해서 방문했는데 재료구성도 알차고 재미있네요! 똥손이라 잘 만들지는 못했지만 맛도있고 재미있는 추억이 될것같습니다! 👍🏻', 84, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '철판아이스크림을 만드는 신박한 경험을 할 수 있어 너무 좋았아요 가게도 너무 예쁘고 분위기도 차분해서 함께 도란도란 이야기나누기도 좋았습니다. 다음에 다코야끼 만들러올게요!! :)', 5, 5, 'GOOD', SYSTIMESTAMP);
