INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '너무 재밌는 이색체험이었습니다! 철판아이스크림 먹어보고싶었는데 기회가없다가 이렇게 만들어먹을수있는곳이 생겨서 너무 좋았습니다 아이스크림 맛도 맛있고 토핑재료도 다양하게 많이주셔서 조합해서 먹기 좋았어요! 다음엔 타코야끼 만들러도 오고싶습니다!', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '데이트로 추천합니다!! 양도 은근 많아서 배부르니 밥먹기전에 오시길~ 그냥 재밌을것같아서 왔는데 아이스크림도 엄청 맛있고 토핑도 넉넉히주셔서 즐겁게 놀다갑니당🩷🩷', 40, 1, 'GOOD', SYSTIMESTAMP);
