INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '진짜 재밌어요!! 철판 장인이 된 기분!! 좀 달긴 한데 바닐라가 제일 맛있어요!! 바닐라에 초코 브라우니 넣으면 완전 맛있어요💖', 15, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '다양한 아이스크림을 만들 수 있었고 엄청 맛있었어요! 이번엔 여름이라 아이스크림 만들기를 했지만 다음엔 겨울에 남친과 함께 가서 타코야끼 만들어볼게요^^ 감사했습니당♡', 22, 7, 'GOOD', SYSTIMESTAMP);
