INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '은근 어려워요..! 그래도 이색데이트헤서 재밌었습니다~ 계속 먹다보니 좀 물리긴 했지만.. 겨울에도 와서 타코야끼 만들고 싶습니당', 85, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '잘 못만들까봐 걱정했는데 생각보다 그렇게 어렵지 않고 여자친구랑 번갈아 가면서 만드는데 너무 재밌었어요 직접 커스텀하는 맛이라 더 특별하게 느껴졌어요! 재밌는 추억 만들고 가요😁😁😁', 89, 13, 'GOOD', SYSTIMESTAMP);
