INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '작년 겨울에 타코야끼 만들기 하러 왔었는데 그때 너무 아늑하고 좋았어서 또 왔어요❣️ 생각보다 철판 아이스크림 만드는데 힘이 들어가지만 좋았습니다🤣 넣을 수 있는 과자 재료도 많아서 굿이애여 담에 또 새로운 컨셉이 생긴다면 방문할래용', 2, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '연인과 실내 이색데이트로 엄청 좋아요. 직접 만들어 먹어서 더 맛있고 만들면서도 재밌어요. 오늘 비와서 덥고 습한데 시원하게 아이스크림 만들어먹기 딱 좋았어요! 여름 데이트로 추천하고 싶어요.', 26, 3, 'GOOD', SYSTIMESTAMP);
