INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '남자친구와 홍대 이색데이트로 강츄!!! 생각보다 말기가 어려워서 재밌었어요!! 겨울에 타코야끼할때 꼭 오고싶었는데 여름에는 철판아이스크림 너무 맛있고 재밌었어요!! 올 겨울에는 꼭 타코야끼하러 올게요!!', 119, 20, 'GOOD', SYSTIMESTAMP);
