INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '아이랑 함께 할거 찾다가 예전 여행가서 이거 아이스크림을 먹어본 기억이있어서 직접해봤는데 어려우면서 재미있고 맛도 너무 맛있어요😀', 83, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '친구랑 놀러왔는데 재밌는 체험이었어요~~ 아무래도 코타츠라서 자리가 아주 편하지는 않아요ㅋㅋㅋ 그래도 특이한 경험이네요. 타코야키는 맛있어요! 토핑도 적절하게 사용할것만 있어서 좋았어요~ 갠적으로는 소스 하나 추가해서 뿌링클+치즈 듬뿍 먹으면 맛있습니다😋 토핑도 콘치즈 잔뜩 넣어서 먹으니 좋았어요~', 31, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '타코야끼 만드는 곳인 거 알고 있었는데 철판아이스크림 출시 됐다니 남자친구랑 방문했어요~! 운 좋게 다른 손님 없어서 여유있게 도란도란 얘기 나누다 가네요 ㅎㅎ 은근 70분 다 채워서 아이스크림 3개 만들었답니다❤️ 가성비 짱!', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '아늑하고 귀엽고 재밌는 도란도란!!! 친구랑 왔다가 너무 좋아서 가족이랑도 재재방문했는데 올때마다 너무 좋은 추억을 쌓고 가는 거 같아요!!!! 잘먹고 갑니다🩷🩷🩷', 94, 22, 'GOOD', SYSTIMESTAMP);
