INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '가게 안에 인테리어도 너무 예쁘고 감성있어서 데이트 장소로 완전 강추 !! 아이스크림 만들기도 너무 재밌고 토핑도 되게 풍부해서 오히려 남아요ㅋㅋㅋ 재방문할 의사 100퍼 !!', 67, 15, 'GOOD', SYSTIMESTAMP);
