INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), 'n번째 방문했는데 항상 사장님이 너무 친철하게 대해주셔서 감사했어요 ㅎㅎ 타코야끼도 너무 너무 맛있었는데 여름용으로 철판 아이스크림이 시작됐다해서 또 와봤는데 말해머해 너무 맛있었어요 썸타거나 커플들이 이용하기에 너무 좋은거같아요 담에도 또 올게요 ❤️', 63, 12, 'GOOD', SYSTIMESTAMP);
