INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '겨울에 타코야끼 만들 때도 왔었는데 시즌 바뀌고 철판 아이스크림 만들 수 있는 게 너무 신기하고 좋았어요!! 직접 아이스크림 만드는 것도 너무 재밌고 파는 거 보다 너무 맛있어서 깜짝 놀랐어요!! 새로운 꿈을 찾아주셔서 너무 감사합니다', 68, 12, 'GOOD', SYSTIMESTAMP);
