INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '정말 재밌는 경험이 됐어요!! 직접 해보니까 영 쉬운 일이 아니네요.....ㅜㅜ 아이스크림은 여러가지를 섞기 보다는 최대한 본연의 맛을 느끼는게 짱인듯! 딸기 베이스 맛있었음!!🥰🥰 이색데이트로 추천!!!👍👍👍', 125, 21, 'GOOD', SYSTIMESTAMP);
