INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '넘 신기하고 토핑도 짱 많이주셔서 맛있게 만들었어요!!!!🥹💕💕💕 가게 이름처럼 도란도란 이야기나누면서 힐링타임 보냈습니다~ 겨울에 타코야끼 만들러 또 올게요☃️💕', 35, 8, 'GOOD', SYSTIMESTAMP);
