INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '항상 예약이 차있어서 예약하고 가자! 해서 방문했는데 정말 가보길 잘했어요. 너무 재밌었어요!! 생각보다 반죽양도 많아서 한 세 번 정도 채워서 먹은 거 같네요ㅎㅎ 재료도 알차구, 새우만 추가해서 먹었는데 골라 먹는 재미도 있었어요. 무엇보다 코타츠에서 해먹으니까 진짜 아늑하더라구요ㅋㅋ 겨울에 다시 와보고 싶네요!', 25, 2, 'GOOD', SYSTIMESTAMP);
