INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '사장님도 친절하시고 이름 그대로 도란도란 귀여운 장소에서 맛난 타코야끼를 만들 수 있어서 이색적이고 즐거웠어요ㅎㅎㅎ 토핑도 여러가지 있고 처음엔 어려운데 계속 노하우 익히면서 만드니까 마지막까지 재밌게 잘 하구 갑니다!', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '처음방문했는데 사장님께서 친절하시고 아이스크림 재밌게만들어먹었습니다. 설명도 영상도 다 있어서 누구나 만들수 있어서 좋아요! 즐거운시간이었습니다 감사합니다~', 36, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아이랑 함께 즐거운 시간 보냈습니다~~~건강하게 아이스크림 만들어 먹는 거 같아 더 좋았어요~~아이도 너무 잼있어하구요~~~!!', 18, 9, 'GOOD', SYSTIMESTAMP);
