INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '생각보다 기대 이상으로 너무 재미있었습니다 !! 만드는 방법도 간단하고 설명 영상도 있고 너무 좋아요 ~ 다음에도 또 와서 하고 싶어요 🎶 맛나게 먹고 힐링하다 가요 ✨', 92, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '다코야끼 기대안했는데 반죽이 정말 맛있었어요...양도 많았고 주스도 넘 맛있었어요 코타츠안에서 시간가는줄도 모르고 만들었던것같아요', 108, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '이색데이트로 강추합니다. 비오는 날 장마때 방문하면 코타츠 안에서 재밌는 타꼬야끼 만들면서 이야기하고 맛있는 타꼬야끼 먹을 수 있어요! 심지어 이용시간도 넉넉해서 최곱니다', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '재밋게 타코야기도 구워 먹고 따끈따끈한 타코여키도 먹고 너무 즐거웠어요 직원분들도 엄청 친절하고 설명도 잘 해주시고 좋았습니다. 메뉴 추가에 벌칙 같은 메뉴도 있으면 재밌겠네요 ㅎㅎ', 36, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '마음대로 토핑 왕많이 넣을 수 있어서 좋아요 1시간 50분 아주 알차게 쓰고 나왔습니당 반죽도 맛도리고 쥬스도 맛있어용 처음 해봤는데 만들기 쉬워용', 72, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '넘 재밋어요ㅎㅎㅎㅎ 재능을 발견했어요 담에 또 올 것 같아용ㅎㅎ 설명도 친절하게 해주셧고 따로 영상도 있어서 어려움 없이 재밋게 할 수 있었어요!!!짱!!!😍😍', 67, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '미리 예약하고 방문한 타코야끼! 첫도전이었는데 성공! !  이것저것 취향에 맞는 재료를 넣어 색다른 맛을 맛볼 수 있는 이색적인 공간에 따뜻한 코타츠까지 ! 시원한공간에서 따뜻하게 만들어 먹을 수 있어서 즐거웠어요! 사먹는것보다 맛있었어요!! 타코야끼 먹고싶을 때 사먹지 않고 도란도란 얘기하면서 만들어 먹으러 와도 좋겠어요 !', 14, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '오늘 여자친구랑 ‘도란도란’에서 철판 아이스크림 만들기를 체험했어요. 둘 다 처음이라 시작할 땐 살짝 어색했지만, 금세 웃고 떠들면서 금방 분위기에 녹아들었답니다. 아이스크림이 굳어가는 걸 보면서 직접 긁고 돌돌 말아 만드는 과정이 생각보다 재미있었어요. 평소에는 사 먹기만 했던 아이스크림을 직접 만들면서 오히려 더 특별하게 느껴졌고, 무심코 지나쳤던 단순한 디저트가 색다른 추억이 되었네요. 커플 체험이나 친구들끼리 소소하게 즐기기에도 딱 좋은 공간이었어요. 다음엔 다른 토핑도 도전해보고 싶어요! 추천합니다 :)', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '남자친구랑 기념일 데이트 하러 왔는데 넘 재미있게 만들다가용ㅎㅎ (근데 젤리는 아이스크림 만들때 넣지마세요... 딱딱해져서 못씹어요ㅠㅜ)', 35, 3, 'GOOD', SYSTIMESTAMP);
