INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '너무 재밌는 시간 보냈어요!!! 매장도 너무 깔끔하고 , 친구 집 놀러온 분위기 나서 좋네요ㅠㅠ 재방문 의사 100퍼! 담에 또 올게요 :)', 38, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '타코야끼체험 해보고싶었는데 여기 코타츠까지 할 수 있어서 너무 좋았어요!! 넘나 이색적인것👍🏻😝 이런 체험 좋아하는데 만족합니듀😆♥️ 내 스타일의 타코야끼라니 히히 만족만족', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '색다른 체험을 연인과 함께 하고 싶다면 강추합니다! 사장님도 친절하시고 재료도 너무 다양해서 재밌게 놀고 먹고 갑니다~ 겨울에 타코야끼 체험도 너무 기대됩니다', 44, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '겨울에 타코야끼 만들러 오고 싶었는데 못 왔어서 아쉬웠거든요ㅠ 여름엔 철판 아이스크림 하신다고 하셔서 왔어요! 첫 판은 만들기 좀 어려웠는데 2번째 판부터 잘 만들 수 있었어요:) 여름 이색데이트로 추천합니다🍦', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '와 정말 재밌어요 마치 제2의 직업을 찾는거와 같이 즐거운체험을 할수있습니다 살짝팁은 욕심부리지말고 적당히정당히 토핑넣으면 맛나게 만들수있습니다 저흼 역심이 많아서 많이많이 했어요ㅜ 한 3판정도 만들수있습니다', 95, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '아이와 홍대 나들이 나왔다가 들렸어요. 이담해서 아이랑 데이트하기 좋아요. 철판 아이스크림 맛도 좋아요. 아이도 즐겁게 체험했답니다.^^♡', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '초등학교때 유튜브로 봤던 철판아이스크림!! 진짜 진짜 어릴때 많이 해보고 싶었는데 지금 성인돼서 하고 있네요ㅠㅠㅠ 진심 재밌습니다! 나중에 타코야끼도 하러 가고 싶어요!', 5, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '세가지맛으로 총 70분동안 철판아이스크림 만들 수 있고여 토핑도 다양해서 재미있게 만들었습니다! 맛있고 은근히 양이많아서 잘먹었습니당🩷', 42, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '남자친구랑 오랜만에 이색데이트 잘 하고 갑니당ㅎㅎㅎ 타코야끼 직접 만들어먹는 게 이렇게까지 맛있을 줄 몰랐어요!! 새우랑 떡을 넣는 게 되게 쫄깃하고 맛있더라구요ㅎㅎ 덕분에 시원한 음료수도 마시고 재미있게 놀다 갑니다! 처음 온 건 데도 만드는 게 어렵지 않았어요~!', 15, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '너무 재밌고 맛있는 철판 아이스크림 만들기! 처음 보면 양이 별로 안많아보일 수 있는데 먹다보니 양이 진짜 많았어요 최고최고!!', 15, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '타코야끼 직접 만들어볼 수 있어서 신기해요 특별한 데이트 코스로 추천합니다 생각보다 만드는게 어렵지 않고 바삭한 타코야끼를 먹을 수 있어서 맛있어요!!!', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '여자친구랑 철판 아이스크리 만들고 왔어요! 컨셉 완전 독특하고 어렵지만 시간 가는줄 모르고 만들었네요ㅎㅎ다음에 또 와서 타꼬야끼도 만들고싶어용', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '아늑하니 데이트 하기 좋아요! 너무 맛있게 먹고 가요 철판아이스크림 만드는 건 처음인데 너무 재밌었어용 사장님도 너무 친절하세요~!', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '직접 만들어서 먹으니까 재미있고 더 맛있어요! 코타츠도 따뜻하고 노래도 잔잔해서 분위기가 정말 좋네요. 처음에 주시는 반죽만으로도 충분하니까 반죽 추가는 하지 마세요.. 저도 알고 싶지 않았음 흑흑', 74, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '휴가 나와서 여자친구랑 새로운 데이트를 하고 싶어서 홍대 근처를 찾아보다가 겨울에 도란도란에서 타코야끼 만들었던 기억이 떠올라 찾아보니 여름엔 철판 아이스크림 만드는 게 있더라구요 유튜브나 인스타에서 볼 땐 되게 만드는 게 쉬워보였는데 막상 해보니 어렵습니다 ㅋㅋ 덕분에 즐거운 데이트를 할 수 있었습니다. 여자친구가 되게 좋아하네요. 🫡', 29, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '제가 만든 다코야끼가 맛있을줄 몰랐는데.. 진짜 너무너무 맛있었어요ㅜㅜ 재미도 있었구요..!! 직원분도 친절하시고 가게 분위기도 아늑하고 좋았습니다😗☺️', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '너무 재밌고 맛있어요!🐙남자친구랑 기념일이라 한달 전쯤부터 예약하고 왔는데 너무 잘 온 것 같아요ㅎㅎ 이색데이트로 좋습니당! 매장도 아늑하고 귀엽고 코타츠 너무 따뜻해요ㅎㅎ 직원분들도 친절하시고 재방문 의사 있습니다♥️', 51, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '생애 첫 타코야끼! 재밌어요!! 토핑 듬뿍듬뿍 넣고 안 터지게 굴리는 재미가 쏠쏠 합니당 두 판 하고도 반죽 조금 남네용 둘이 와서 한 판씩 구워먹었습니다 아직 날이 조금 쌀쌀한데 가게 내부가 따뜻하고 아늑해서 분위기도 좋아요 :) 그리고 타코야끼 맛있습니당', 27, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '은근 어렵네요! 하다보니 요령도 생기고 맛있어요 세가지 베이스에 토핑!! 토핑은 쪼금만 넣고 얇게펴야 잘말리네요 철판 아이스크림 궁금했었는데 재밌게 만들고 맛있게 먹었어요', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '남자친구와 이색 데이트 하고싶어 방문했어요! 주말이라 2달 전쯤 예약했던 것 같습니다! 아늑한 곳에서 도란도란 얘기하면서 타코야키 구워먹는 재미가 너무 좋아요 ㅠㅠ 만들기도 어렵지 않고 하다보면 금방 실력이 좋아집니다 ㅎㅎ 그리고 맛있어요!! 이색 데이트코스로 강력 추천해요!!', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대 이색데이트로 넘넘 추천합니다 !! 타코야끼는 24알 정도 나오는 분량인데 반죽도 토핑도 충분해요 옥수수 들어가는 게 넘 맛있고 토핑을 내 마음대로 가득가득 넣어서 먹을 수 있다는 점이 넘 좋았답니당 ㅎㅎ 코타츠도 있어서 따숩게 데이트할 수 있는 것도 좋았구 무엇보다 타코야끼가 넘 마싯어요 .. ㅠㅠ 생각보다 만들기 쉬워서 넘 재밌게 데이트 하다 갑니다 .. 💗 다음에 또 올게요!! >,<', 58, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '진짜 엄청난 똥손인데 친구랑 너무 재밌게 만들다가 왔어요!! 하다보면 스킬이 생겨서 쉽더라구요!! 꼭 한번 와보세요❤️ 맛있고 재밋어요🤭 남자 사장님도 너무 친절하셔서 기분 좋게 놀다가 갑니다~~', 30, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '철판아이스크림 만들기 체험은 여기서만 해볼 수 있는것 같아서 예약하고 왔는게 토핑도 다양하게 준비해주시고, 매장도 청결해서 잘 놀다 갑니다 ㅎㅎ', 29, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '처음 만들어보는데 재료도 다양하고 만드는게 너무 재밌었어요! 토핑도 다양해서 꾸미는 재미도 있고 더운 여름날씨에 재밌게 놀았어용 💗 데이트코스로 강추입니당 😘😘', 39, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '생일날 타코야끼 만들기 하려고 예약 대기타구 드디어 입성했어요! 코타츠 넘 따숩고 포근하고 타코야끼 만들기도 생각보다 넘 재밌네요! 무엇보다 음악 플리가 너무 제 취향이라 좋았어요💖 다음에도 지인들 데리고 와야겠어요💗💕', 19, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '똥손이라 망햇긴 한데 맛은 잇엇어용!!!!!🔥🫰🏻 한번도 해본적 없엇는데 해보게 되서 너무 재밌엇어용 한번쯤 해보시길 추쳔드립니당 😘', 26, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '철판아이스크림을 만든다는 특별한 경험을 할 수 있고 내가 만든 아이스크림을 먹을 수 있어서 좋다. 인테리어도 예쁘고 데이트하기에 좋다.', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '처음 만드는 거라 어려워서 몇 번 실패했지만 그래도 마지막은 잘 나와서 다행이에요 :) 맛있었고 양도 많아서 배불러요! 재밌게 잘 만들었어요 다음에 겨울에 와서 타코야키 만드는 것도 해보고 싶어요', 81, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '재밌고 맛있어요!! 타코야끼 처음 만들어봤는데 설명도 친절하게 해주시고 재료도 맘대로 조합해서 넣을수있어 좋았습니당 치즈추가해서 콘치즈소시지 해보세요 짱맛', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '철판아이스크림은 처음 만들어 보는데 처음엔 좀 어려웠고 두 번째부터 잘 만들었어요! 재료도 많고 너무 맛있어서 즐겁게 보내다 갑니다٩( ''ω'' )و', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '직접만든 타코야끼 맛있었고 딸이랑 좋은추억 만들고 돌아왔어요~~^^ 분위기도 좋고 그날 눈비가 내렸는데 코타츠 밑에 두다리 쭉 뻗어  따뜻하게 몸이^^ 타코야끼를 직접 만들어보고 먹어보니 사먹는 맛보다 만들어서 먹는 재미가 쏠쏠했네요  만들기 바빴지만 ㅎㅎ 훌쩍큰 딸이랑 함께 홍대에서 데이트하며 만들어온 타코야끼 식구들이랑 도란도란 나눠 먹었네요~~^^  여름이 기다려 지네요.', 8, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구랑 놀려고 당일예약했는데 정말 후회 없이 재밌게 놀았어요!! 생각보다 만들기 힘들었는데 그거 마저 재미있고 양이 생각보다 많아서 배부를 정도🥰 겨울에 타코야끼 만들러 또 오고싶어요❤️', 37, 8, NULL, SYSTIMESTAMP);
