INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '더운 날에 사랑하는 사람과 시원하게 데이트하게 좋아요 사진도 잘 나오는 조명이라 사진찍고 놀기도 좋은 장소 같아요 짜짜가 찾아줘서 더 재미있었어요🧡', 91, 22, 'GOOD', SYSTIMESTAMP);
