INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '도란도란 예약 너무 힘들어요ㅜ ㅜㅜ운좋게 전날 11시 자리가 남아서 후다닥 예약하고 왔어요!!!!!완전 굿굿!!! 레모에이드 맛있구!! 짝궁이랑 같이 다코야끼 만들어 먹는데 재료도 넉넉하고 만드는법도 큐알로 친절하게 안내 되어있어서 첨인데도 어렵지않게 다코야끼 성공했어요!!! 담에 또 오고 싶어용>=<', 67, 13, 'GOOD', SYSTIMESTAMP);
