INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '철판 아이스크림을 만들 수 있는게 너무 신기했고 구비된 여러 토핑들과 과자들 덕분에 더욱 더 맛있는 아이스크림과 함께 무더운 여름에 시원하고 재밌는 경험 했습니다!!', 12, 4, 'GOOD', SYSTIMESTAMP);
