INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '3인 가족이 송대 나들이로 방문했습니다~! 주말은 예약하기 힘들다고 초6인 아이가 그런던데 진짜 운이 좋아서 몇번 검색 중에 예약 취소가 생겼는지 예약 시간이 생겨서 방문했어요~!^^♡♡ 럭키비키!! 크림 소다가 예쁘게 나와요~ 반죽과 소스가 맛있어서 잘 만들어도 맛있고 못 만들어도 맛있었어요~~ ㅎㅎ 아이가 신나하면서 만들었는데 3인기준 세판 구웠는데 마지막에는 장사할 수 있을것 같다네요~^^;; 잘 먹고 갑니다~~~♡♡♡', 81, 15, 'GOOD', SYSTIMESTAMP);
