INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '연인과 아이스크림 처음 만들어 보는데 다음엔 타코야끼도 꼭 하고 싶어요! 3번 먹었는데 실패작이 없었어요! 함께 만드는 재미 처음 느꼈어요 담에 또 오겠습니다!', 104, 21, 'GOOD', SYSTIMESTAMP);
