INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '사장님도 너무 친절하시고 타코야끼 너무너무너무 맛있었어요,, 진짜 두번세번 또 오고 싶은 맛집임미다 양도 많아서 식사하고 오면 못 먹을 거 같아용', 9, 10, NULL, SYSTIMESTAMP);
