INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '사장님도 엄청 친절하시고 만드는 재미도 있어서 시간이 후딱 갔어요!! 이색데이트로 추천드려요 재밋게 만든만큼 맛도 너무 맛있어서 간만에 너무 행복했어요!!', 121, 22, 'GOOD', SYSTIMESTAMP);
