INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '오늘은 의외로 손님이 많지 않았어요. 저희 일행은 시나몬 티와 아아를 택했는데, 아아 컵이 참 예쁘더군요. 옆 테이블 손님이 마시는 수박 주스도 참 맛나보였고요. 직원 분들의 친절함은 원래 정평이 나있죠.', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '테라로사. 이름은 수없이 들어서 모든 것이 완벽할 줄 알았지만  #와이파이 존이 너무 형편 없었던 곳. 좌석 내 콘센트존과 비 콘센트존이 나눠져 있고 콘센트존에 앉았는데 와이파이가 안잡히는 아이러니. 다시는 업무 보러 올 일은 없겠지만 매장 매니져,대표님은 이글 보시면 와이파이존 손 꼭 보셨으면 좋겠습니다. 와이파이 1도 안잡혔습니다.', 34, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'WIFI');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '서교동에 이렇게 큰 카페가 있네요 테라로사 강릉 여행시 가던곳이였는데 서교동에 테라로사 카페가 있네요  널직널직 하고 좌석도 많고 좋네요', 58, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '하우스 주스 수박이 마시고파 차 타고 방문했어요. 하나, 기대보다는... 뜨거운 토요일의 점심 이후 시간대라 그런지 만석이었어요. 인근 서관면옥에서 냉면 먹고 오신 분들이 많은 듯. 직원 분들은 이 바쁜 와중에도 친절함을 유지하네요.', 16, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대 테라로사는 처음와봤는데 인테리어도 멋있고 커피가 진짜 맛있음 근데 민트레몬에이드? 이건 진짜 돈아까웠어요 ㅋㅋㅋ 홍초 마시는 느낌', 33, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '에티오피아 구지함벨라를 참 좋아했는데, 시즌이 바뀌면서 단종된 게 아쉽지만, 써머블랜드부터 새로 들어온 싱글까지 또 다른 원두를 접해볼 수 있어서 흥미로운 테라로사. 늘 맛있는 커피 감사합니다.', 48, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '집 앞 건물에  바로 테라로사가 있어서 서울 올때마다 필수 방문 코스입니다 언니가 확실히 테라로사 커피가 맛나다고 좋아했어요 디저트는 뒤에 더 주문해서 나눠먹었어요 테세권이라 좋네요', 40, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '누디뜨홍대 건물을 와보고 싶었는데, 마침 테라로사가 있어서 점심 후 급 방문. 여기 테라로사는 미술서적 코너를 공간할애해서 꾸며 놓았네요. 커피는 기호에 따라, 근데 피칸파이가 상당히 맛나는것 같아요. 제 취저~!', 10, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '오늘 테라로사에 멕시코 커피 이벤트가 있어 한번 다녀왔습니다. 멕시코 커피는 흔하게 접할수 없는 커피라 호기심도 있었고 과거 멕시코 커피를 마셔 보았을때 그리 감흥이 있거나 임팩트가 없었던 것으로 기억이 있어 기대가 되지는 않지만 세월이 많이 흘렀고 변화가 있었나 하는 궁금증에 오늘 테라로사에 들려 보았습니다. 컵 노트는 다음과 같았습니다. "호두의 고소한 풍미와 당밀의 은은한 단맛이 조화로운 커피" 이고 제 느낌과 정확히 일치 했읍니다. 전 오히려 곡물의 단맛으로 표현하고 싶네요. 맛있는 멕시코 커피를 마시게 되니 그동안의 편견이 사라진것 같습니다. 재료 소진 이전까지 방문 추천드립니다.~', 37, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '테라로사와서 tea는 처음인데 포트로 나와서 너무 좋았어요.^^  처음온 친구들이 케이크가 너무 맛있다고해서 괜히 뿌듯했네요. 잘 쉬다 왔습니다.', 40, 1, 'GOOD', SYSTIMESTAMP);
