INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '바로 옆 서관 면옥과 패키지로 이용하는 편입니다. 진지한 대화를 나누기엔 다소 시끄럽지만, 커피가 맛있고(잔도 예쁘죠), 내외 공간이 주는 특유의 질감이 좋아 애정합니다.', 15, 5, NULL, SYSTIMESTAMP);
