INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대 서교동쪽에 주차 가능한 카페 찾다가 들어갔어요 지하에 주차하면 1시간 주차지원해줘요 달달한 커피는 메뉴가 별로 없고 드립커피 종류가 다양하고 많아요 디저트류도 다 맛있어 보였어요 아메리카노는 산미가 있는 맛이었어요 매장이 넓어 답답하지 않고 쾌적합니다', 18, 5, 'GOOD', SYSTIMESTAMP);
