INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '가까운 곳에 테라로사가 있어서 좋아요 일요일인데도 아침부터 북적거립니다 6월 1일부터 뉴크롭 1+1행사를 해서 온두라스랑 코스타리카 원두도 구매했어요 아아의 양이 적어서 아쉽긴하지만 맛은 최고!', 35, 8, 'GOOD', SYSTIMESTAMP);
