INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '좌석이 넓고 인테리어가 멋있어 분위기가 좋습니다 한쪽이 책으로 가득한데 막상 읽을 수 있는 책은 별로 없어 아쉬웠습니다 커피 맛이 제 취향은 아니었습니다', 9, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대지나가다가 테라로사  있길래 테라로사 커피도 먹고싶고해서 호기심에 들어왔어요  서점식 카페로 매장이넓고 인테리어가 멋지네요 라떼랑 아메리카노 마셨는데 아메리카노는  신선하면서도 끝맛이 산미가 있어 산미 좋아하시는 분들은 좋아할듯요 저는 라떼가 진해서 더 맛있었어요', 14, 6, 'GOOD', SYSTIMESTAMP);
