INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대에 이리 조용한 🤫  분위기를 누릴수 있는 곳이 있다니~~ 너무 좋았어요. 주차도 편했고 커피도 ☕️ 분위기있게 마실수 있었어요. 한켠에는 책이 쭉 📚 📖 있어서 책냄새도 나네요. 한번 슥 둘러보기 힐링!', 28, 8, 'GOOD', SYSTIMESTAMP);
