INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피도 맛있고, 티도 특이하게 맛있습니다. 소리의 울림만 없다면 이야기하기도 좋은곳일듯한데, 약간 아쉬워요! 그래도 재방문 의사 있습니다.', 44, 6, NULL, SYSTIMESTAMP);
