INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '강릉테라로사 디저트를 기대하고 가긴했는데 이것도 맛있었어요! 상품판매존이 잘되어있어요! 손님이 많았지만 번잡스럽지않아 좋았어요! 잠깐 쉬러갈때 좋을것 같아요!', 54, 11, 'GOOD', SYSTIMESTAMP);
