INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '디져트도 맛있고 카페가 넓어서 너무 좋았어요. 인테리어도 너무 흥미로웠고 책들도 많아서 훑어보기 좋았어요. 실론시나몬라테 추천합니다!', 36, 10, 'GOOD', SYSTIMESTAMP);
