INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '새해맞이 이벤트로 카페라떼와 카드를 선물로 받았어요. 기분 좋게 마시다 갑니다. 휴일이라 만석이였어요! 참고로, 레몬치즈케이크는 생각보다 상큼한 맛이 아닌 달달한 맛이였어요.', 6, 2, 'GOOD', SYSTIMESTAMP);
