INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '커피는 테라로사 노을공원점이 더 진하고 맛있는게 솔직한 평입니다 호두파이는 완전 싱싱해요 밖에 정원뷰도 좋고 서점도 있어 분위기는 좋아요 다만 층고가 높아 소리가 울려서 좀 시끄럽긴해서 귀에 이어폰 꽂고 음악듣는걸 강추합니다', 9, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '테라로사를 굳이 설명할 필요가 있을까? 맛과 분위기, 인테리어, 쾌적함 등 모든 면에서 빼어나다. 홍대서교점은 입점해 있는 건물 자체도 너무 멋있다. 근처에 온다면 방문하길 강추~!!!', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '넓고 도란도란 얘기하기 좋아요. 커피 원두가 여러 종류라서 고르는 재미가 있는데요, 저는 거의 산미적은 멕시코랑 파나마 원두 픽이에요.', 8, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '일단 내부 인테리어가 너무 잘되어있어서! 책을 읽거나 일을 하기 좋았습니다! 커피는 라떼랑 아메리카노가 메인인것 같아요! 달달한게 땡겨 초코들어간 음료 시켰는데 일반 초코라떼가 아닌 시큼한 초콜릿 맛이라 더 달게 드시고 싶으시다면! 설탕 스틱 하나 다 넣고 드시는걸 추천해유!!', 34, 3, 'GOOD', SYSTIMESTAMP);
