INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '가격대비 식사와 디저트 커피 퀄리티가 높습니다 특히 매장과 화장실이 깨끗하고 일하시는분들도 센스가 좋으세요 식사 후 자리정리를 알아서 다 해주시고 디저트를 주셔서 좋았어요. 나폴리탄과 엔초비 화이트라구 는 꼭 드시길..', 45, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '나폴리탄과 오무라이스 맛있게 먹었어요 커피도 맛있습니다 종업원분들이 친절하시고 음식이 빨리 나와서 기분좋게 머물다가요 또 방문하고싶어요', 24, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '서교동 2층 건물, 잔잔한 일본감성을 즐기기 좋은 킷사텐 카페🍨 일본감성 카페로 유명한 수택이 서교동으로 이전! 2층 건물에 숨겨진 아지트느낌 가득한 공간으로 아기자기한 감성과 일본틱한 소품으로 채워져있고, 전보다 더 넓어져 웨이팅도 덜할 것 같아요 수택은 킷사텐 카페로 나폴리탄, 야끼소바 같은 점심, 저녁으로 먹기 좋은 음식들과 메론소다, 과일 사와, 쇼추 등 일본의 마실거리들을 판매 중! 일본감성을 한껏 느끼고 싶다면 방문해보세요👍', 31, 9, 'GOOD', SYSTIMESTAMP);
