INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '*저랑 부정적인 딴 글 지워서 글케 썼는데 아니래요!! 싹안지움ㅎ 소비자공익 공유를 위해 작성했습니다. 단순 비방 목적이 절대 아닙니다. 1. 운영방식 : 웨이팅을 미리 걸어놓지도 못하게 웨이팅을 위한 웨이팅을 하게 했음. 웨이팅이 사라져야 웨이팅을 열어준다는데, 다른 사람이 나중에와서 등록하면 어떡하나 전전긍긍하면서 추운데 밖에서 한시간을 기다리게 했음. 캐치테이블은 도대체 왜 사용하시는건지..? 가게만의 편의를 위해서인건지 궁금했습니다. 2. 맛 : 가격에 비하면 가격이 비싸서 맛이 별로고 가격 생각안하면 그냥그랬다고 느꼈어요. 타코야끼는 그냥 타코야끼에요. 타코야끼 트럭 아저씨거가 더 맛있어요. 분위기랑 비주얼만 좋았어요. 이렇게까지 갈곳이었는지 의문이 들었고 직원 응대도 능숙하지 않았다고 느꼈습니다.', 26, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '인생맛집ㆍㆍ 먹어본 나폴리탄 중 제일 맛있어요 자꾸 생각나는맛ㆍ. 으앙 직원분들도 친절하시고 공간 자체도 아늑해서 편히 먹고 쉬다가욧!! 채고', 5, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '매장 이전하시고 넓어지고 쾌적해져서 너무 좋아요.. 좌석수가 많아져서 웨이팅이 없을 줄 알았는데 저희 들어오고 바로 웨이팅 생김 ..!🫨 나폴리탄이랑 함박스테이크 너무 맛있어요 …. !! 푸딩은 그냥 말안해도 이미 유명해서 …🫶 매장이 눈오면 더 예쁠거같아요 ☃️☃️☃️', 46, 5, 'GOOD', SYSTIMESTAMP);
