INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '동화 같은 곳이예요! 무화과 파르페 하신다길래 후다닥 혼자 달려와서 먹어봤어요 크리미한 걸 좋아하신다면 추천해요🥰 엄청 크리미하고 많이 달지 않아요! 핸드폰 없이 매장 내에 있는... 일본의 온갖 빵을 소개한 듯한?? 책을 읽었어요 매장이랑 진짜 잘 어울려요... 노래는 조금 큰 편이 있어요 노래가 커서 혼자 여러 생각하면서 놀 수 있었어요 노래에는 귀여운 브라스 소리가 들리고 입에는 무화과와 피스타치오 크림이 가득하고 문 밖엔 밥 먹으러 온 고양이가 사람을 불러 밥 먹고 가고 책은 너무 귀엽고 가게엔 눈을 끄는 어항과 갖가지 귀여운 오브제들이... 혼자 와서 너무 좋은 추억 만들고 가요! 힐링 제대로 했어용 혼카로 추천합니다아', 18, 2, 'GOOD', SYSTIMESTAMP);
