INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '합정역 근처에서 디저트 먹고 싶어서 방문했는데 너무 맛있어서 깜짝 놀랐어요.. 진짜 맛있고 분위기 및 감성 만점입니다.. 추기로 커피도 시켜먹었는데 커피 맛도 좋네요.. 플러스로 직원분들이 너무 따뜻하고 친절하십니다 힐링하기 딱 좋아요..🫶', 33, 5, 'GOOD', SYSTIMESTAMP);
