INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '파르페가 먹고 싶어서 갔다가 배가 고파서 음식 시키고 디저트로 파르페 먹으려고 했는데 배가 불러서 음식만 먹고 왔어요 ㅋㅋㅋㅋ 나폴리탄이랑 야끼소바 둘 다 맛있게 먹었고 타코야끼가 겉바속촉 스타일이에요! 눈이 그려져있어서 너무 귀여워요 ㅎㅎ 블루소다크림은 소다맛 탄산음료라 생각하면 되는데 아이스크림이 있어서 크리미해요. 다음엔 디저트 먹으러 가봐야겠어요 :)', 50, 0, NULL, SYSTIMESTAMP);
