INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '대기 10분정도하고 들어갔어요~ 파르페 맛있고 매론소다도 양 많고 좋아요!! 길냥이가 밥 먹고 가는 공간도 있습니다~ 다음엔 푸딩도 먹으러 오고 싶어요:) 바닐라 아이스크림를 맛있는걸로 사용하시는거 같아요!', 71, 15, 'GOOD', SYSTIMESTAMP);
