INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '너무 맛있어요.. 푸딩이 진하구 완전 제취향이예요.ㅠㅠ 진짜 맛있었어요. 제가 먹어본 푸딩중 탑이예요. 집근처면 정말 좋을텐데.', 39, 7, 'GOOD', SYSTIMESTAMP);
