INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '운좋게 바로 들어가 착석했다아 우리 이후로 8팀이나 웨이팅이 있었다 후훗. 이곳의 특징은 만화에 나올법한 알록달록한 음료 그리고 푸딩이다 🍮😍🍮💖🍮🥰🍮 말차라떼도 푸딩도 밀도가 높다 진하다 차음료도 향이 강하게 나와 개성이 느껴지는 까페', 491, 86, 'GOOD', SYSTIMESTAMP);
