INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '너무 맛있었어요! 직원분들도 넘넘 친절하시구! 파르페 좋아하는데 잘하는집 못찾아서 힘들었는데 진짜 맛있었어요🍓❤️ 다음에 또 꼭 갈거에요🤤', 98, 24, 'GOOD', SYSTIMESTAMP);
