INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '새로나온 메뉴라고 하네요 하야시오무라이스와 양송이스프입니다 스프에 빵도 같이 나오더라구요 맛있습니다 스프파는곳이 잘없어서 아쉬웠는데 자주 올것같습니다 간단히 스프와커피마시기도 좋고 식사하기도 좋네요', 21, 4, 'GOOD', SYSTIMESTAMP);
