INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '수택 음식과 디저트는 말모죠..✨💗 처음 오픈 했을 때부터 단골집인데 늘 변함없이 맛있고 분위기도 넘 좋습니다🍮🤍🤍 (더 맛있어진 것 같기도..) 낮에도 이쁜데 밤에도 분위기 넘 예쁩니당 왕 추천!!▫️▫️▫️', 0, 7, 'GOOD', SYSTIMESTAMP);
