INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '나폴리탄 먹고 싶었는데 달달하고 살짝 매콤하니 역시 맛있었어요 ㅎㅎ 금요일 점심에 방문했는데 자리 완전 널널했어요 ! 가게 내부도 귀엽고 좋았어서 다음에 푸딩이랑 파르페 먹으러 또 오고 싶네용', 82, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '진짜 맛있어요.. 그래놀라 넘 좋아하는 사람으로서 여기 프라페 진짜 먹어본 곳 중에 제일 취향저격이었어요.. 강추강추 ♥ !!!! 또 가고 싶네요🤤💕', 17, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '타코야키 너무 귀엽고 ㅠㅠ 푸딩이 진짜 찐찐찐맛집이에요..! 아이스크림과 바나나브륄레랑 같이 나와서 같이 곁들여먹으니 넘 맛있더라구요 합정역 2번출구 바로 앞이라 접근성도 좋더라구요 역시 인기있는 카페는 이유가 있더라구요 후후 ••😸', 28, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '너무너무 맛있어요… 8팀 대기, 약 1 시간정도 기다렸는데 일본에서 먹은것보다 맛있는거같아요🥹 눈도 즐겁고 입고 즐겁고! 여행온 느낌 느끼다 갑니당', 44, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '2024 01.01 첫 디저트! 딸기 파르페 + 바나나 브륄레 푸딩 딸기의 상큼함과 크림의 부드러움 아이스크림의 달달함과 셔벗의 새콤함 거기에 그래놀라의 씹는맛도 더해져 비워지는게 아쉬워... 라고 생각이 든다. 푸딩은 표면에 코팅된 설탕이 빠그작! 소리를 내며 달달한 아이스크림과 함께 녹아내리는데 이때 몽글몽글한 푸딩이 혀에 가볍게 눌리면서 시럽과 섞이는데... 입가심 바나나에도 설탕 코팅이 되있어 나름 청각적 즐거움도 들어있다. 너무 단거만 먹어서 시킨 사이드 타코야끼에 얼굴이 그려져 있는게 귀여웡 밑에는 둥지처럼 양배추와 가쓰오부시가 소스랑 섞여있어 중간중간에 짠맛으로 입속 정리(?) 하며 디저트 타임을 즐겼다.', 28, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '매장이 키치해요 .ᐟ 입이 심심해서 동생이랑 지나가다 오므라이스에 소다 두 잔 시켜서 먹었는데 달고 맛있었습니다 메뉴 하나만 주문이 가능한 곳이라 더 좋은 것 같아요', 86, 13, 'GOOD', SYSTIMESTAMP);
