INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '파르페랑 다른 디저트들 비주얼도 좋도 맛도 좋아요 가게 분위기도 좋고 따뜻해서 좋았습니당 근데 좌석 운영이 좀 미숙하신 거 같았어요 단체손님 좌석은 한정해두고 단체석에 2인손님도 받고 단체손님은 아예 웨이팅의 의미가 없는 느낌? 그래도 음료랑 음식이 맛있었습니당', 55, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '지난 추운날 대기 길어 포기하고 왔어 오늘은 꼭  먹으리라 결심하고 왔더니 여전히 대기시간 길었어요. 하지만 맛이 있어서 그 모든 수고로움이 싸악 가시고 또 가고 싶단 생각이 듭니다.', 101, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '맛있고 예쁜 음식들, 일본 감성 뿜뿜하는 인테리어가 수택의 포인트입니다. 카모메 식당에 놀러 간 것 같은 느낌이어요. 다만 바빠서 그런지 직원 분들이 친절하진 않으셔요 ㅠㅠㅠ 그래도 비주얼과 맛 모두 만족스러운 집입니다!', 31, 2, 'GOOD', SYSTIMESTAMP);
