INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '볼로네제랑 오므라이스 먹었는데 맛있어요 바테이블 조금 불편 ㅠ 하지만 가격이 착해서 좋고 직원분들 친절하셔서 좋습니다 재방문 200%', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '여기 나폴리탄 미쳤어요….. 가시면 꼭 드세요 제 최애 나폴리탄집입니다…일본은 못가는데 일본 느끼고 싶다하시면 무조건입니다,, 직원분들도 다 너무 친절하시고 재방문 3번 째인데 늘 다른 음식들도 디저트도 맛있게 먹고 기분 좋게 나오는 곳이예요🥹 주말에 가면 웨이팅이있지만 기다려서 먹어도 절대 후회하지 않는 곳입니당💕', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '바나나 브륄레푸딩 푸딩 되직?하고 쫀득 맛있어요. 가성비는 모르겠으나 맛있고, 인테리어 아기자기 귀여워요. 한번쯤은 오기 괜찮은 곳.', 67, 11, 'GOOD', SYSTIMESTAMP);
