INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '밥이랑 디저트 모두 즐길 수 있는 곳,, 킷사💓 나폴리탄이랑 오므라이스 맛있어요! 파르페는 아는 맛이였고 푸딩은 탱탱한 푸딩이었어요 맛있어요ㅎ.ㅎ 공간 아기자기하고 좋아용', 18, 7, 'GOOD', SYSTIMESTAMP);
