INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '오랜만에 다시 찾아왔습니다 ~ 음식은 여전히 너무 맛있어서,,, 조금의 대기쯤이야~ 바 테이블 새로 생겨서 앉아봤는데 이제 편하게 혼밥할 수 있어서 너무 좋네요 ◡̈ 집이 근처라면 맨날 퇴근 후 수택 와서 혼밥과 시원한 맥주 한잔할 것 같아요~!! 매장 분위기도 너무 아늑하고 음악들도 너무 귀여운 것 같고,,, 수택 넘 좋아요🥹', 23, 1, 'GOOD', SYSTIMESTAMP);
