INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '강아지 데리고 갔어요. 강아지 데리고 가면 간식을 서비스로 주나봐요. 아주 좋더라구요. 여러개 시켰는데 바나나 푸딩, 블루크림소다, 딸리 파르페, 타코야끼 이렇게 시켰어요. 파르페는 10,000원이 넘는 가격이라 사악한데 맛은 그냥 그랬어요. 생긴게 너무 이뻐서 홀린 듯이 시킴. 딸기 양이 가격대비 많지는 않고 그냥 떠먹는건데, 아래에 깔린 부분은 너무 달아서 못 먹었어요. 타코야끼는 ㅇㅈ!! 바삭하니 맛있고 뭣보다 너무 귀여웠어요 ㅠ 아래에 깔린 가쓰오부시 뇸뇸 같이 하시면 됩니다~ 블루소다도 아이스크림 녹기 전까지는 시원하니 맛있고 녹으니 달아서 못 먹겠더라구요. 바나나 푸딩은 정말 맛있으니 강추~! 바나나랑 푸딩, 아이스크림의 조화가 아주 좋습니당. 전체적으로 일본 분위기 나서 아주 마음에 들었어여.', 32, 2, NULL, SYSTIMESTAMP);
