INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '바나나에 크림브륄레처럼 설탕까지 녹여서 이빨 썩을 거 같은 맛이에요ㅋㅋㅋ..푸딩은 꾸덕하고 진하네요. 파스타는 면이 두꺼운 편이고 꾸덕해요. 가라아게도 맥주안주로 딱이네요.', 23, 2, NULL, SYSTIMESTAMP);
