INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '전부터 가고 싶어서 저장했다가 드디어 방문했는데 왜 이제서야 방문했는지 ,,, 일단 매장이 너무 귀엽고 아기자기해요! 일본 여행 온 기분이 들었어요 ㅎㅎ 파스타랑 덮밥 시켰는데 음식도 귀엽고 맛있고 다 하기,, 꼭 또 다시 방문할 거예요! 식사 외에도 커피랑 음료 디저트 술까지 판매해서 언제든 편하게 방문하기 좋아요 ㅎㅎ 사장님들도 너무 너무 친절해요! 아 이제껏 먹은 나폴리탄 중에 제일 맛있었어요 :)', 61, 17, 'GOOD', SYSTIMESTAMP);
