INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '요기 진짜 디저트 맛집입니다 ㅜㅜ ♡ 카페 찾아다니는게 소소한 취미인데 소품 하나하나 예쁘고 아기자기하니 일본 감성나서 무척 좋았어요 ㅎㅎ 디저트랑 커피도 맛있어서 커플 데이트나 여자끼리 가기에 무척 좋을 카페! 달다구리한 걸 좋아하지만 자극적이게 달기만 한 건 싫어하는 제 입맛에 딱이어서 너무 좋았어요. 진짜 진짜 최고 밥때문에 다른 메뉴들 맛 못본게 아쉬웠던 ㅜㅜ 다음엔 다른 디저트 먹으러 재방문 할고에용 ㅎㅎ', 80, 14, 'GOOD', SYSTIMESTAMP);
