INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '분위기도 너무 아기자기하고 파스타 같은 음식도 팔고 디저트도 너무 맛있어서 또 오고 싶은 곳이에요~ 아지트 같은 느낌이라 너무 좋아요', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '음식이 전체적으로 자극적이지 않고 심플합니다 너무 맛있게 잘 먹었고 커피도 좋았습니다. 주차는 힘들어 보여서 저희는 근처 메세나폴리스 주차장에 주차하였습니다. (걸어서 5분거리) 차 가지고 오실 분들은 참고하셔서 주차하시면 될 것 같습니다', 0, 1, 'GOOD', SYSTIMESTAMP);
