INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '맛있어요 ㅠㅠ 한입 먹어보고 너무 맛있어서 사진 찍을 생각두 못하고 다 먹어버렸어요😂😂 자리도 편하고 테이블 간격도 넓어서 좋고 매장도 쾌적하고 다들 너무 친절하셔서 좋습니다 :) 🥰', 79, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피는 약간 연한편이에요.산미는 없어요.깔끔한 편이에요 케잌은 생크림아니에요.진한 버터느낌나는 크림맛이에요.딸기잼이 있어  약간 상큼해요 케잌과 아메리카노는 잘 어울려요 1층, 2층도 있어서, 편하게 얘기할수 있어 좋아요', 44, 5, 'GOOD', SYSTIMESTAMP);
