INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '홍대 ‘커피랩로스터리’에서 아메리카노 한 잔 했는데, 진하고 깔끔한 맛이 아주 좋았어요. 내추럴한 우드 톤 인테리어에 조용한 분위기가 마음에 들었습니다. 직원분도 친절하셔서 기분 좋게 머물다 왔어요.', 36, 7, 'GOOD', SYSTIMESTAMP);
