INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '아담하지만 커피가 맛있는 카페. 대화하기 좋고, 수박주스 굿. 이번엔 아메리카노로 했지만 다음에 크렘 므 시나몬도 시도해보고싶네요.', 33, 2, 'GOOD', SYSTIMESTAMP);
