INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '더운 여름날 시원한 카페에서 좋은 시간 보냈어요. 1, 2층인데 2층은 꽤 자리가 많고 전체적으로 어두워서  더 시원한 느낌이에요. 음료와 케이크도 맛있게 먹었네용', 50, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '😍👍👍👍딸기 그득한 딸기라떼도 감동인데 디저트 케익이 너무 맛있어요!!! 케익 시트 너무 촉촉하고 많이 달지도 않고 혼자서 두개 순삭해버렸어요;;; 다음에 또 올게요😍👍', 30, 6, 'GOOD', SYSTIMESTAMP);
