INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '여기서 직접 로스팅도 하시나봐요! 드립커피 마셨는데 너무 맛있어요 쿠키도 딱 제가 좋아하는 스타일! :) 카페 분위기도 좋고 야외테이블이 있어서 혼자와서 즐기기 좋네요. 직원분도 친절하세요 자주 와야겠어요-!', 13, 0, 'GOOD', SYSTIMESTAMP);
