INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '주변에 종이잡지클럽인가..? 거기 가려다가 오픈을 안했길래 더워서 돌아다니다가 문득 보인 카페가 커피에 진심처럼 보여서! 무작정 들어갔습니다 원두 종류도 세분화되어있고 제 입맛에 맞는 원두로 아메리카노 먹을 수 있었어요. 한쪽에서는 드립커피도 파시더라고요. 근데 어딘가 익숙해서!! 집 와서 찾아보니까 이번 2024 커피 엑스포 참여하셨더라고요😆 저 그때 커피랩스 드립커피 이벤트로 받았었거든요😽👍🏻 다시 만나뵈어서 너무 반가웠어요 히히💗 잘 쉬었다가 가요!', 15, 5, 'GOOD', SYSTIMESTAMP);
