INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '친구랑 밥먹고 찾아왔는데 사장님도 엄청 친절하시고 커피 맛도 너무 좋아요 ㅎㅎㅎ채광과 뷰도 좋고 다른곳에선 먹어볼수없는 핸드드립도 먹어볼수있어서 더더 좋았어요👍', 38, 10, 'GOOD', SYSTIMESTAMP);
