INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '직원들이 불친절까진 아니지만 미묘하게 까칠해요. 1층 앉았는데 통유리 밖으로 바리스타들 다 나가서 담배피는거 보고 바로 먹던 커피 버리고 싶었어요.', 7, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대 최고 가성비 카페. 스벅보다 싼데 스벅보다 맛있고 편한듯요. 2층은 뷰도 좋고 짱박혀있기 좋아요. 젤 중요한 거, 화장실 깔끔합니다', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '거리두기 4단계 기준 2층 9시반 마감 1층 9시50분 마감 화장실 남녀 분리 온수 딜레이없이 틀자마자 뜨겁게 나옴 화장실 깨끗하고 물비누와 핸드크림 비치되어 있음 음악 국힙나옴 비엔나커피 평범하고 가성비 좋음 비엔나커피 크림 아주 뻑뻑하고 단단한편(두껍게 올려주심) 커피 산미 중간 커피 탄맛/쓴맛이 신맛보다 강함 (악평아님 유식한말로 머라하는지모를뿐) 꽤 양이 많음 저녁먹고 가면 일이나 과제하는 사람보다 술한잔하고/데이트 마무리로 오는사람 많음 = 콘센트 경쟁률 낮음', 28, 10, 'GOOD', SYSTIMESTAMP);
