INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '매운음식 식사 후 달달하고 개운한 디저트가 땡겨서 빙수 집 찾다가 분위기 좋아보여서 들어왔어요. 빙수 주문했는데 팥이 한나도 안 달고 담백하고 우유맛도 찐하고 너무 맛있어요. 빙수 강추요~~ 아.. 양갱이도 파는데 보자기 포장으로 예쁘세 선물하기 좋을거같아요.', 69, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '저는 팥을 너어어어무 좋아하는데요! 입구에서부터 펼쳐진 양갱에 정신을 못차리겠더라구요! 완전 너무 예쁘게 해놓고 팔아요. 선물로도 넘 좋을 듯. 메인은 팥빙수는 말해뭐합니까. 괜히 맛집이 아니었어요. 진짜 우유얼음은 완전 꼬소한 우유맛이 진하게 나는 것이 일품이었구요! 팥....팥 진짜 맛있어여. 진짜로. 팥만 줘도 퍼먹을 수 있을 것 같은 맛. 더운 날 시원하게 먹고 왔습니다:)', 64, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '마트에서 파는 양갱만 먹어본 사람이라 양갱은 달기만 한 것 이라는 인식이 있었는데 금옥당 양갱을 맛보고 엄청 달지도 않고 은은한 단맛과 토핑의 조합이 정말 맛있더라구요!! 보자기 포장이나 케이스 포장도 고급지게 잘 되어있어서 상견례 선물로 샀습니다ㅎㅎ', 128, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '팥빙수 제대로 먹고싶다면 여기로~~~ 가격대비 양이 적어보이지만 팥이 진심이고 너무 달지 않아 좋고 시원하고 좋아요~ 커피가 드롭커피인데 진하고 맛있네요 강추!', 14, 8, 'GOOD', SYSTIMESTAMP);
