INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '금옥당 팥빙수 정말 맛있어요. 우유로 된 빙수가 적당히 달고 부드럽고, 팥은 고급지고 건강한 맛이에요. 기본적으로 팥이 적게 들어있는 편은 아니지만, 팥을 몹시 좋아하는 남편을 위해 팥추가도 했어요. 다양한 맛의 양갱도 구입할 수 있는데, 포장이 각기 색다르고 예뻐서 선물하기 좋을 것 같습니다.', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '팥이 맛있음. 팥 전문점답게. 팥빙수 먹어봤는데 은근 양이 많고 팥도 부족하지 않음. 안에 앉을 자리는 생각보다 많진않음. 대신 그만큼 예쁘게 포장된 양갱들이 많음. 낱개도 파니까 하나 먹어봐도 좋음!', 266, 78, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '달지 않은 단팥의 맛이 좋고 잘 갈린 얼음도 좀 연유맛의 느끼함이 있지만 시원해요. 다만  주차할 공간이 없는게 큰 문제에요. 자주 오기 어렵겠어요.', 30, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '팥빙수 진짜 진짜 진짜 맛있어욤👍🏻✨ 분명 홍대에 있는데 가게 들어가는 순간 홍대 아닌 것 같은 평온함. 매장도 시원하고, 맛있는 디저트까지. 쉬어가기에 딱 좋은 곳이에요.', 96, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '빙수포장하는데 이미 주문하고나서 주문이 밀려서 오래 기다려야한다고 알려주시질않나 자리에서 기다리는데 다른손님 앉아야한다고 자리 비키라 하질않나 너무 불친절하네요. 적어도 양해를 구하거나 사과라도 하셔야되는거 아닌가요? 장사 똑바로 하세요', 81, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '부드러운 양갱이라 나이 좀 있는 어르신들 선물용으로 좋아요. 양갱도 다양한 맛이 있어서 구성 다양하게 만들수 있어서 좋고 선물 포장 박스랑 보자기도 다 고급스러운 걸로 있어서 한번에 준비 가능해서 편해요.', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '팥죽에 옹심이가 두개라서 아쉬웠지만 달지않고 담백해서 맛이 좋았어요 중간중간 견과류가 같이 씹으면 더 고소해져요 양갱이는 단맛이 인위적이지않고 맛이 다양해서 골라담기 좋았어요', 5, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '생딸기빙수 현수막에 이끌려서 방문했어요. 생딸기빙수(1만8천원)주문했는데,싱싱한 딸기가 가득 들어 있어서 좋았어요.우유 얼음과 딸기의 조화는 말모죠.너무 맛있어요.딸기 좋아하시는 분들은 꼭 방문해 보세요^^', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '올해 설 명절 선물은 금옥당 양갱으로 했어요! 무엇보다 100% 국산팥으로 만듬 수제양갱이라 믿음이 가고 보자기로 예쁘게 포장 구성이 너무 예쁘더라고요ㅎㅎ 원래는 부모님껏만 사려다가 6구 구성도 있어서 지인 선물 2개 추가해서 구매했습니다🙂', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '무더위를 시원하게 날려 줄 팥빙수 정말 깔끔하게 맛나요. 양갱은 가공 식품에 길들여져 맛이 조금 빠지게 느껴지지만 분명 맛있어요', 9, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '프랜차이즈인지는 모르겠고 개인적인 생각이나 고급 브랜드인 것 같습니다. (양갱이가 개당 4천원꼴이면 저렴한 가격은 아니지만 그만큼 가치가 있겠지라고 생각합니다.)', 27, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '딸기 철이 곧 간당간당한 것은 알지만 빙수인 걸 감안하더라도 애들이라 이렇게 파신 건지...🥲딸기를 주로 쓰는 업인 사람으로 안 좋은 건 즉시 폐기를 하는데 많이 물렁해도 쓰네요. 맛도...딸기 맛은 보시나요? 분위기 양갱 맛있어요', 11, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '기본에 충실한 팥맛집이에요.ㅎㅎ 팥빙수랑 팥양갱이 찐하고 적당히 달아서 맛있네요! 오랜만에 왔는데 그대로에요. 아이스 드립커피 양이 작아서 좀 아쉬웠지만 향도 좋고 맛있었어요.', 2, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '예전에 자주가던곳. 사람 많은편. 빙수시간 좀걸림. 오랜만에 갔는데 팥이 너~무 꾸덕함.양갱수준됐음. 예전같지 않았음. 재방문 아쉬우면 할듯..', 79, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '인테리어도 멋있고 서울 빙수 둘이서 1만 1000원짜리 먹었는데 양이생각보다 많았어요. 적당히 단맛에 우유 빙수에 달콤함도 느껴졌구요 담아나오는그릇도 정갈하고요 인테리어가 일단감각적이라 맘에들었습니다', 66, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '부모님 선물로도 유명한 금옥당의 홍대지점입니다. 주말 오후 1시쯤 가니 자리가 많이 남았습니다. 아주 정갈하게 갈은 우유얼음과 건강하게 달달한 팥이 올라간 기본팥빙수가 이 집의 시그니처입니다. 찹쌀떡도 2개 올라가는데 정말 쫄깃하고 맛있습니다. 먹다보면 안에 팥이 한번 더 있어서 가성비가 정말 좋습니다. 복숭아빙수도 비주얼이 좋아서 여러 명이시면 꼭 시켜보세요. 가게 안은 쾌적하며 모두 푹신석입니다. 인테리어가 한옥스럽게 멋져서 사진도 잘 나옵니다.', 82, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '비오는 일요일 저녁에 식사를 한후 디저트 가게를 찾다가 금옥당에 들렀어요. 딸아이가 시킨 서울빙수 역시나 넘 맛있었고, 남편이 주문한 아아 한모금 뺏어마시곤 바로 뜨아와 양갱을 주문한 저. 우린 각자의 취향대로 맛있게 먹고 왔답니다. 올 여름은 빙수 생각날때 금옥당에 일부러 들러야겠어요~양갱도 너무 달지않은것이 선물용으로 딱인거 같구요. 여기 커피도 좋습니다^^', 47, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '팥빙수는 금옥당이 최고..🫠👍🏻 카운터 봐주시던 단발머리 직원분 정말 친절하시고 예의있게 대응해주셔서 감동받고 갑니다,, 사장님 월급 올려주세요👍🏻', 17, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대에서 진또배기 빙수 찾으시면 금옥당 추천드립니다. 홍대 웬만한 카페가면 1인 1메뉴인데 여기는 빙수 하나만 시켜도 되고 공간도 아늑하고 꽤 넓어서 대화하기에도 좋았어요! 기본 팥빙수 시켰는데 팥도 적당히 달고 빙수 안에도 넉넉하게 들어있고, 우유얼음도 곱게 갈아져있어서 정말 맛있게 잘먹었어요!', 88, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '많이 달지않고 부드러운 우유팥빙수💙 *접근성- 상수역에서 가까워요 *주차- 근처 공용주차장 이용 *맛- 우유팥빙수 주문 우유,팥,떡 옛날빙수 스타일이지만 맛은 옛스럽지 않은. 우유얼음은 우유향이 많이나는 편이고 고소하며 부드럽게 녹아내려요. 팥도 단맛이 강하지 않아 좋았고 맨위에 떡도 말랑 쫀득해서 팥이랑 같이 꼭 먹어줘야 해요! 크기가 큰편은 아니지망 디저트로 먹기에 적당해요. 금옥당은 전체적으로 단맛이 강하지 않아 좋아요! (지극히 개인적인 후기입니다)', 35, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '금옥당 팥빙수 너무 맛있어요!! 우유빙수인데 우유맛도 진하게나고 팥도 많이 안달아서 진짜 맛있!!! 여기 딸빙좋아하는데 빨리 딸기의 계절이 오길🍧', 46, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '서울빙수 너어어어어어무 시원하고 맛있다!!!!!!! 팥은 적당히 달고 고소하면서 담백하고 맛있고 목에서 넘어갈때 우유 얼음(?)이 사악 녹으면서 예술입니다 1인 1빙 무조건 가능', 44, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '우연히 지나가다가 상호가 보석가게 같아서 들어가본 곳인데 양갱 맛집이었네요. 덕분에 달달한 수제양갱과 팥빙수 맛있게 먹었어요.', 82, 18, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '이런 팥의 식감이 고스란히 느껴지는 옛날 팥빙수가 너무 먹고싶었는데 진짜 맛있어요!!! 우유 얼음 중간에 또 팥이 들어있어서 넉넉해요ㅠ', 16, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '금옥당이야 팥으로 유명하죠 양갱도 맛있도 빙수팥도 좋습니다 밥먹고 커피마신후 후식먹으러 갔습니다 맛있게 먹었습니다 우유기본빙수에 밭이 가득올라갑니다', 72, 15, NULL, SYSTIMESTAMP);
