INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '상수동나들이갔다가 생딸기빙수광고보고들어갔어요 생딸기가 빙수 겉에 뿐 아니라 안에도 들어있어 좋았어요 양갱도 국산팥맛100%사용해서인지 안달고 맛있어요', 31, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '둘이 디저트로 먹기 적당해요~ 팥이 많이 달지 않아 좋았구요. 놋그릇이라 빙수가 천천히 녹아 마지막까지 맛있게 먹었어요 내부는 생각보다 아담해요', 60, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '팥이 맛있는 곳은 빙수가 맛있을 수밖에 없어요!! 너무 만족하면서 먹었습니다. 고운 우유빙수에 단듯 달지 않은 팥이 참 잘 어울립니다~ 여름날은 금옥당 필수예요~', 73, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '믿고 먹는 빙수. 정확하게는 팥 맛집🥰 빙수 시키면 팥 추가는 필수입니다. 매년 최소 3번 이상은 가는 거 같아요. 또또또간집. 이 근방에서 팥빙수는 여기 이길만한 곳이 없다고 봅니다. 수정과 정말 찐~하고 고명 이것저것 많이 들어가서 든든합니다ㅎㅎ 오미자는 오미자 맛😋', 33, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '빙수 심하게 달지 않아 먹기에 좋았습니다 2명이 먹기에 충분했다고 생각해요 다음번에 또 방문하고 싶어요 팥양갱, 흑임자양갱 포장해서 가져갔습니다 겉 포장지 디자인이 예뻐서 버리지 않고 집에 가지고 있어요 양갱이라 제 생각보다 달기는 했네요😅 가격은 착하지 않아 종류별로 다 드시려면 고민 많이 하셔야 할거에요', 5, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '여기는 양갱맛집인데 빙수 먹으려고 방문했어요! 딸기철 막바지라 그런지 달지는 않았지만 생각보다 비싸지 않은 금액으로 깔끔하게 먹기 좋았어요~ 양갱 맛집이다 보니 남녀노소 누구나 즐길 수 있는 카페 같아요!', 77, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '양갱도 맛있지만, 수정과와 딸기빙수가 너무 시원하고 좋았어요. 가격대는 있지만, 일반 프렌차이즈 방문하는 것보다 훨씬 만족스러웠습니다.', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '공연보러왔다가 벚꽃구경하며 걷다가 아이들이 다리아프다고해서 들어왔어요! 딸기빙수 맛있네요, 아이들이 딸기만 먹었지만🥲 빙수속에도 딸기가 좀 들어있네요 👍🏻 커피양은좀 적은듯해요...', 41, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '너무 더워서 지나가다 들렀는데 애들은 빙수 어른들은 커피마셨어요 빙수도 커피도 넘 맛있네요 빙수의 얼음은 고급진 우유맛이 고소하고 달콤해서 계속 숟가락을 꽂게되는 맛이고 커피는 향이 고소해서 일단 코가 즐겁고 한입 쭉 빨았는데 입안가득 고소함이 퍼져 넘 맛있네요 분위기도 좋네요', 41, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '가격이 매우매우매우 비싸서 이 돈이면 연양갱이 몇개야? 라는 생각이 자연스레 들지만 그래도 특색있는 양갱이 많고 맛도 있어서 종종 먹어요😊', 81, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '팥빙수 넘 맛있고 팥이 안달고 맛있네여 ~ 찹쌀떡 이런것도 팔면 좋겠다 생각했어요 ~ 위에 있는 고명이 넘 쫀득하고 맛있어여 ~ 담에 팥죽먿으러 가야겠오요 ~~', 43, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '팥양갱, 통팥, 대추, 곶감, 단호박 총 5종류 양갱 골라봤습니다 맛이 다양해서 좋고 어른들한테 선물하기 좋을것 같아요 매장 직원이 친절했습니다. 단팥죽과 딸기빙수도 맛있을거 같아 재방문 의사 있습니다 제가 찾던 양갱집이네요', 119, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '밤양갱 노래에의해 특수를 누리는 것 같지만, 사실 유명해져서 개인적으론 아쉬운 곳 입니다. 나만아는 집이고 싶었던 곳 입니다.', 5, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '현수막에 생딸기 빙수 비주얼이 너무 마음에 들어서 먹어봤어요. 양은 혼자서도 충분히 먹을 수 있을 정도인 것 같습니다. 딸기 제철이 아니라서 딸기 자체는 새콤한 맛이 강하고 과육도 단단한 편이었지만 연유 뿌려서 먹으니 달달함에 새콤함이 어우러져서 나쁘지는 않았습니다. 만약 딸기 제철에도 계속해서 판매한다면 또 먹어보고 싶어요!', 12, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '매장에 앉을 자리가 없어 대기하다 양갱만 사서 나왔네요 ㅎ 매장 내 분위기가 편안하고 인테리어가 좀 독특합니다. 양갱은 단 맛이 거의 느껴지지 않았어요. 가성비가 좋은 건 아닌데.. 건강 간식으로 좋을 것 같아요', 43, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '선물하려고 구입했는데 포장지도 고급스럽고 좋습니다. 맛은 아직 안봤지만... 근데 실온 3시간이면 기본적으로 아이스팩포장이 되어 나오면 좋겠네요. 추가요금말구요ㅠ', 68, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '사장님(?)께서 정말 친절하셨어요!ㅎㅎㅎ 어른 선물인지라 걱정이 되어 많은 질문을 드렸음에도 불구하고 하나하나 자세히 설명해주시고 추천해주셔서 넘 감사했습니다☺️', 185, 41, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '양갱과 오미자 차, 수정과 등 전통 한국식 음료와 디저트 잘 하는 곳 어르신 모시고 함께하기 좋고 양갱은 특히 패키지가 이뻐서 선물용으로 좋습니다 받으시는 분들 참 좋아하셔요 사진에 못담았으나 서울빙수(팥빙수), 수정과, 오미자 차 추천합니다', 5, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '일반 빙수가 맛있었던 기억이 나서 딸기빙수 먹어봤는데 딸기는 역시 철이 아니라서 그런지 많이 달지않고 셔요. 그래서 연유 뿌려서 먹는게 낫고 얼음자체가 맛있어서 그 맛으로 먹으면 괜찮습니다. 그런데...앉아 먹는 것 주문하는 곳과 양갱주문하는 곳이 다른데 한참 기다려야지만 응대해주십니다. 직원분들 지나가면서 주문 기다리고 있는것 보셔도 잠깐 기다리라는 말씀 하실법도 한데 쳐다만 보고 몇 분이나 그냥 휙 지나가셔서 서비스 측면은 좀 그러네요.', 38, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '팥빙수랑 양갱이 찐 맛집이에요!! 서울빙수는 우유빙수에 팥도 엄청 듬뿍 들어가있는데, 달지도 않고 맛있어요~ 호두양갱이는 호두가 콕콕 박혀있고 요것도 달지않아서 부모님이나 어른분들께 선물하기 좋을 것 같아요.ㅎㅎ', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '갈 때마다 품절이던 딸기빙수가 비오는 저녁에 방문했더니 남아있었어요 새콤달콤한 딸기 빙수네요 연유 좋아하지 않아 뿌리지 않고 먹었는데 충분히 달고 맛나요 사이드로 주는 연유대신 팥선택 할 수 있으면 좋겠어요', 74, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '상수오면 항상 들르는 금옥당. 이젠 남치니도 이곳 매력에 빠져서 더더욱 자주 갑니다. 시그니처인 서울빙수만 먹다가 남치니가 딸기빙수 먹고 싶대서 처음 먹어봤는데 이 또한 미쳤더군요 ㅠㅠ 빙수 안쪽에도 딸기가 많이 숨어있어서 감탄하며 먹었어요 ㅠ 금옥당 사랑해요❤️', 31, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '가게 이름은 바뀌었으나 맛은 변함없습니다. 여태까지 먹어본 빙수 중 제일 맛있습니다. 팥이 적지 않습니다. 이층으로 되어 있습니다. 먹다보면 속에 팥이 또 있습니다. 자꾸 생각나는 맛입니다.', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '계절에 따라 빙수나 쌍화차(?) 마시러 가곤합니다. 오랜만에 갔더니 동그란 떡(?) 메뉴가 없어지고 양갱만 있어서 조금 아쉬웠어요.', 26, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '팥빙수 진짜 맛있어요...! 가격에 비해 양이 작아서 아쉬워요ㅠㅠ 1인1빙수 할수있을거같아요 근데 팥이 너무 맛있어서 또 납득됩니당', 20, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '예쁜 양갱들의 천국😍😍😍 아버님 선물로 구입하고 나는 쌍화차 주문 노른자가 없어서 쫌 서운했지만ㅋㅋㅋ 단맛없는 찐건강맛 쌍화차^^ 직원분들도 다 친절친절👍', 88, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '맛이야 당연히 있어야하는거고, 1. 테이블이 텅텅 비어있는데 왜 밖에서 대기를 시키는지 모르겠어요. 일부러 테이블 3개씩은 비워두나봐요. 2. 주문은 카운터에서 하라고 왜 안내하지않는거죠? 유료주차장에 주차까지하며 찾아왔는데.. 재방문의사 없네요. 빙수집이야 많으니.', 26, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '금옥당 서울빙수야 말할 것도 없이 제가 너무너무 좋아했던 빙수였는데 아니나 다를까 딸기빙수가 출시했더라구여!!! 이렇게 딸기가 큼지막한 빙수는 처음이에요.. 딸기 자체로도 달콤 새콤한데 너무 새콤한가? 싶으면 연유소스에 절여진 얼음이랑 같이 먹으니까 혼자서도 완빙 가능하드라구여.. 연유도 시중에서 파는 달기만한 소스가 아닌것 같아요!! 딸기는 겨울에만 맛있게 먹을 수 있는 줄만 알았는데... 요근래 먹었던 빙수 중에 단연 최고네요.. 매장 분위기도 너무 좋고 직원들도 다 예쁜 웃음이 광대에 올라가 있어서 빛이 났어요✨정말 친절했구요!  직원들의 따스한 응대와 고즈넉한 분위기,노르스름한 조명이 저를 아늑하고 기분좋게 만들어주네요 ㅠ 다음엔 평일 일찍와서 이 분위기를 독점하고 싶어요!', 28, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '지나가다 눈에 띄어 들어가본 양갱점~ 먹고 싶은 양갱은 많았지만 냉장보괸해야 된다고 해서 두개만 ㅜㅜ 배가 부른 상태에서도 두개 순삭!! 적당한 달달함에 식감도 좋았어요~ 매장분들도 친절하시고, 다음에 또 들릴께요~', 79, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '추워서 들어갔는데 인테리어가 독특(옛날 다방분위기?) 하고 따뜻했어요. 드립커피 4000원인데 산미있지만 부드럽고 오미자차도 맛있네요.', 8, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '딸기빙수는 포장이 안 된다고 해서 서울빙수를 포장했어요. 친절하게 잘 포장해주셨고 보냉재도 잘 넣어주셔서 시원하게 잘 먹었습니다. 팥이 넉넉히 들어 있는데, 우유얼음에는 살짝 달콤한 맛이 돌고 팥은 달지 않아서 정말 맛있었어요.', 27, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '토요일 저녁 알바인지 직원인지 불친절합니다 교육이 필요해 보여요 손님이 들어왔는데 소리지르듯이 응대하더라구여 저한테도 그러구요 원래 그런 스타일인지 모르겠지만 마지못해 일하는 느낌이었습니다 양갱이 맛있어서 참았지만요', 103, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '동지라서 단팥죽 먹고 양갱도 사봤어요. 양이 적어보였는데 그릇이 깊어서 만족스럽게 먹었습니다. 호박씨와 잣이 씹혀서 식감도 좋고 많이 안 달고 팥맛이 좋았어요. 양갱은 종류가 무척 다양했는데 패키지도 예쁘고 인위적인 단맛이 아니라 어른들께 선물하면 좋을 것 같아요. 직원분도 추천 친절히 해주셔서 좋았습니다.', 85, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '독특하고 맛있는 양갱을 접할 수 있어요😄 제주 말차 양갱, 라즈베리 양갱 먹었는데 너무 맛있었어요 😭 음료는 다양하지 않아서 쌍화차를 마셨는데 감기 기운 있는 분들한테 후회하지 않을 선택이에요👍🏻🍵 어린아이 빼고 다 마실 수 있을 것 같은? 추천합니다 ㅎㅎ', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '아직 안먹어봤는데 너무 궁금하네요ㅎㅎㅎ 맛있을 거 같아요!! 인테리어도 너무 예쁘고... 은사님이나.. 어른들께 선물할 때 너무 좋을 것 같아요', 81, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '팥이 진짜 맛있어서 팥빙수가 더 맛있게 느껴졌어요 양갱도 종류가 많고 맛도 비주얼도 좋아서 나중에 고마운 사람들께 선물할까 싶네요', 73, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '어르신, 외국인 선물용으로 완전 좋아요 요 근래 선물할 일이 많아서 양갱 자주 구매하는데 받는 분들마다 모두 맛있고 특색있다고 좋아해요 매장 직원분들 늘 친절하고 매장 청결해서 좋구요', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '진짜 맛있는 정갈한 팥빙수 드시고 싶으시면 완전완전 강추해요!! 그리고 양갱도 맛있고 종류도 다양해서 선물할 때 너무 좋을 거 같아요!! 어른들께 선물할 때 너무 좋아하실 거 같아요!! 포장도 이뿌게 해주시는거 같아서 넘 좋은거 같아요 추석에 선물 뭐할지 고민하신다면 추천쓰💛', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '호기심에 들어갔는데 양갱 비싼 가격에 놀랐으나 그냥  나오기 쨍피해 두개 겟했습니다~ㅜㅜㅋ손바닥보다 작은 양갱 2개가 7100원. 하지만 맛은 있네요...', 125, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '부모님 추석 선물로 양갱세트 구매했어요! 선물해드린 거 사진을 못찍어서 매장에서 찍은 사진이라도 올려요 ㅠ 보자기 포장해서 선물하면 고급져보이고 좋아요 양갱도 많이 달지 않아서 맛있다고 하셔서 뿌듯했어요🤭💖', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '공영주차장 가는길 우연히 본 금옥당 웨이팅 해야하는 가게인줄 모르고 갔네요 십분정도 기다렸고 더워서 양갱보단 빙수가 인기있는 듯. 팥빙수가 많이 달지도 않고 담백하니 맛있어요!', 4, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '추석 선물로 어른들께 드릴 양갱을 샀습니다! 예전에 양갱을 먹어봤을때 많이 달지 않았고 맛이 다양하고 포장도 깔끔해서 선물하기 좋겠다고 생각하고 있었어요~ 선물로 드리니 포장부터 너무 깔끔하다고 좋아하셨고 맛도 있다고 좋아하시네요~~', 16, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '낮에 너무 더워서 팥빙수먹으러 방문했다가 웨이팅이 있어서 양갱이만 사들고 나왔어요 🥲 주문하니까 냉장고에서 꺼내주셨고 4시간 안에 차갑게 먹으라고 조언해주셨습니다! 저희는 나오자마자 골목 걸어다니면서 바로 먹었어요 ㅎ 슈퍼에서 파는 양갱이보다 훨씬 안달아서 특이했어요! 안에 호두가 오독오독 씹혀서 식감도 좋았습니다 👍 양갱이 선물세트도 판매 중이라 어르신들 선물에 좋을 거 같습니다! 다음에는 꼭 팥빙수 먹으러 다시 와볼래욥 📍견과양갱(소) 3,5', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '커피... 너무 맛있네요 왜죠? 팥... 적당히 달아서 칼칼(?)하지 않고 고소하고 너무 좋아요... 1인 1팥빙수 가능할꺼 같아요', 106, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '스승의 날을 맞이해서 선물 드리기 위해 6구 세트로 2개 구입했어요~ 토요일 6시 넘어서 도착해서인지 인기 있는 양갱들은 다 품절이더라고요😭 ✔️포장해 주시는 게 너무 고급스러워서 선물하기 딱 좋은 거 같습니다:) 저는 그냥 포장만 해서 1세트당 1,000원이었는데요. 살펴보니 포장비를 더 내면 고급스러운 보자기(?)에 넣어서 주시는 거 같더라고요~😊', 1, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '나름 유명한 맛은 다 먹어봤는데 제 입맛에는 너무 별로네요ㅎ 음,, 좀 덜 단 팥앙금을 굳은 상태로 먹는 그런 기분이었다고 해야 할까요? 팥 맛이 강한데 싱겁고?(알갱이도 씹힘) 다양한 맛과 믹스된 느낌이 썩 좋지 않았어요 선물용으로 구매하는 경우를 제외하고는 굳이 이 돈 주고 사먹어야 하나 싶은,,? 수제 양갱이 원래 이런 맛인지 몰라도 저는 돈 아깝다는 생각이 들었다며(´•̥-•̥` )', 90, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), 'Green tea 양갱은 식감이 죠금 써걱써걱 했어요 Milk tea 양갱은 식감도 good~ 맛도 good~ 추천 드립니다^^ 드립 coffee 향이 좋아요 No 산미~^^', 75, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '길가다 수제단팥죽이라고 해서 포장해서 집에 와서 먹었는데 제 입맛에 맞아 좋았어요 너무 안달고 직접 만든 정성이 느껴지는 맛이었어요 양갱도 라즈베리로 하나 사 먹었는데 포장이 너무 이뻐서 나중에 어르신들께 선물할 일 생김 주문할까 해요 양갱도 적당히 달아 좋았어요', 53, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '매장직원분들 늦지않은시간 입장했지만,퉁명스럽게 응대 ㅜ 남자분  긴머리 묶고 ,그손으로.....ㅜㅜ 디저트가게는  친절해야할듯', 37, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '적당히 달달한 통팥과 얼음의 조합이 빙수의 정석 같았어요. 팥빙수 너무 맛있었어요!!!! 올 여름 가기전에 꼭 한번 더 먹기로 결심했어요. 그리고 그동안 식당에서 후식으로 마셨던 오미자는 오미자가 아니었어요. 진짜 오미자의 매력을 여기서 찾았네요.  여기 오미자가 찐입니다.', 50, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '선물용으로 6구짜리 사고 먹으려구 흑임자 1개 샀는데 고소하고 생각했던거보다 많이 달지는 않아서 맛은 괜찮았어요! 식감은 제스타일은 아니였던... ㅎㅎㅎ 비싼편이라 내가 먹으려고 사는거보다 선물하기에는 고급져보여서 좋은거같아요!', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '우유로 만든 빙수에 팥이 풍성하게 올라가서 기본맛에 굉장히 충실한 맛있는 빙수에요! 기존에 있던 팥빙수 가게에서 상호명이 바뀐 듯? 양갱도 판매하구 빙수만 판매하지 않는 컨셉으로 변신~하지만 빙수맛과 레시피는 그대로이네요', 48, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '급 빙수가 땡겨서 가장가까운매장이어서 방문함 가격대비 맛은 쏘쏘~직원들 어리버리하고 자기들끼리 얘기하느라 응대늦고 2번은 안감', 10, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '빙수는 맛나다… 다만 여직원이 불친절 할뿐 이런 불친절 한 직원 처음 봄 그러나 빙수가 맛나서… 그  직원 없는 날 가고 싶다', 60, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '양과 맛에비해 가격 진짜 사악해여 …. ㅋㅋㅋㅋㅋㅋ 인테리어도 예쁘도 해서 한번은 가볼맘 하지만 매장이 너무 작으니 코로나때는 피해서 가세요', 23, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '매장이 10시까지라고 해서 9시에 왔는데 한 테이블 외 손님도 없었고, 주문하기도 전에 9시 20분에 나가셔야된다, 빙수만드는데 10분이 걸리는데 괜찮냐고 물어서 기분이 많이 나빴네요. 먹지말라는건지.. 나가라는 건지.. 이럴거면 그냥 9시까지 영업하시는게 어떠실지.. 9시까지 하시면 또 8시부터 그러시려나.. 금옥당 좋아하는데 서교점은 다신 안올것같네요.', 35, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '이건 진짜 달지 않고 넘넘 맛있는 곳이에요.어른도 아이도 모든 연령대가 좋아할 맛입니다. 엄마와 시댁에도 선물해도 손색하나 없었을 만큼 맛있었어요 ㅎ', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '극강의 부드러움과 적당한 단맛과 고소한 단팥. 첫 방문에 극상의 만족감을 느끼다! 다만! 가격이 좀 사악해서 별 하나는 슬쩍 빼봅니다.', 22, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '오늘 날씨가 더워서인지 매장을 방문했을때 이미 손님이 너무너무 많았어요 그럼에도 직원분들응대가 너무 친절하셔서 기다리는시간도 기분이 좋았습니다 :) 첫번째 방문때 떡이 소진되어 못먹었었는데 그걸기억하시고 오늘은 넉넉히 주셔서 더 맛있게 먹었습니다. 리뷰를 작성하기전에 남겨진 리뷰를 쭉읽어보았는데 제가 받은응대를 생각해보면 불친절하셨다고 적혀있는 리뷰들이 와닿질 않네요ㅜㅜ 너무 잘먹고가요 !', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '두번째 방문이였습니다.역시나 불핀절하더군요 오늘은 빙수에 들어가는 떡이 조기소진 되었다는 말을 하는데,우선 죄송하다는말이 먼저 아닌가요?그냥 빙수에 떡이 다 떨어졌다는말만 합니다. 그래서 그럼 가격이 좀 더 싼가요? 라고 물어보니 그냥 아니랍니다.그래서 그럼 뭐가 더 있나요?라고 물어보니 그제서야 팥을 더 준다는말을 매우 퉁명스럽게 하더군요.제가 뭐 구걸하러 왔나요?일단 그것도 참고 주문후 착석을 하니 금방 나왔습니다.정말 하얀색 갈은얼음위에 팥이 조금있길래 이게 팥을더준건가 싶어서 휘저어 봤더니 안에 정말 한숟가락도 안되는 반숟가락정도 가 있더군요.돈 만원 그래요.물가상승률에 비하면 쌀수도있고 비쌀수도 있습니다.뭔가 농락당한느낌이였구요.결국 빙수에 반은 팥이 부족해서 남기고 왔습니다.불친절+최악', 109, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '빙수에 들어가는 소스와 팥 모두 너무 달지 않고 담백해서 정말 맛있게 먹었습니다. 직원분들도 매우 친절하시고 잠깐 구경하려고 본 양갱도 친절하게 설멸해주셔서 몇개 먹어봤어요!', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '너무 더워서 우연히 빙수가 보여서 웨이팅 기다리고 들어갔는데 주문할 때 이것저것 친절하게 물어봐주셔서 감사했고 팥빙수가 맛있네요 양갱도 안달게 맛있어서 잘 먹었습니다!', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '설 선물로 구입했어요. 흑임자는 빨리 품절되니 미리 준비하는게 좋습니다. 서비스에 관해 악평이 있던데 저도 한마디 하자면 직원들이 손님에게 과잉 친절할 필요는 없지만 그렇게 무뚝뚝할 이유도 없지 않나 싶은 생각이 듭니다. 딱 그 정도의 응대니까 서비스에 대한 기대가 없으면 실망도 덜 할것 같아요. 분위기와 양갱만 보고 가세요.', 12, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '#팥빙수 에 우유얼음은 적당히 달아서 팥 없이 먹어도 달달하니 좋습니다. 위에 얹어진 팥 외에도 중간에 팥이 더 들어가 있으니 아끼지 말고 먹어도 됩니다.', 73, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '수제 양갱 선물용으로 좋을 것 같아서 구매했어요. 서비스에 대한 리뷰 보고 친절함은 기대하지 않았지만 직원의 응대가 좀 미숙하고 성의가 없다고 느꼈어요. 손님 응대만 좀 더 신경써주시면 정말 좋을 것 같아요..!', 50, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '빙수 맛있어요 특히 팥!!!! 통팥이라 씹는 식감도 살아있고 많이 달지 않아서 좋아요 다만 빙수얼음 자체에는 단맛이 없어서 빙수얼음만 먹기엔 밍밍하지만 팥이랑 같이 먹으면 궁합 굿 팥이 진짜 맛나서 추가해서 먹었어요 그리고 찹쌀떡보단 양갱이 더 맛있구요 찹쌀떡도 백미보단 흑미가 더 맛있습니다. 아 그런데 너무 시끄러웠어요ㅎㅎ 특히 바로 옆자리분들 너무 크게 웃고 떠드셔서 아쉬웟다는', 81, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '팥빙수 우유얼음이 너무 곱고 부드럽고 팥도 너무달지않고 맛있어요 그리고 핸드드립커피 한입먹고 깜짝 놀랄정도로 부드럽고 향이좋아요 (사실 기대안하고목말라서 시킨건데 더맛있응)', 4, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '양갱이 많이 달지않고 맛있어요. 내돈으로 사먹기에는 후덜덜하지만 선물용은 포장도 예뻐서 괜찮ㅎㅎ #금옥당서교점 #금옥당 #선물용양갱 #수제양갱 #홍대수제양갱', 22, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '근강한 팥 맛. 몇 자리 제외하고 내부 공간이 너무 다닥다닥 붙어 있지만 빙수가 맛있네요:) 양갱 시식을 할 수 있는데 할머니 생각이 나요.', 68, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '팥빙수 맛집 예전에 옥루몽?있었던거 같은데 빙수가 비슷했어요 양갱이랑 찰떡도 궁금해서 먹어봤는데 빙수가 제일 맛있습니다 제 기준에서 양갱은 좀 짰어요', 46, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '처음 방문한 거라 어색해하고 있으려니 먼저 다가오셔서 친절하게 일일이 설명해주셨어요! 양갱 고르는 데 시간이 좀 걸렸는데도 불편한 기색 없이 웃으며 기다려주셨어요. 이튿날 다른 지점도 방문했었는데 홍대점 서비스가 훨~씬 좋았어요. 또 갈 거예요! (구입한 양갱은 총 다섯 집에 선물 보냈는데 모두 반응이 좋았어요!😁)', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '#홍대 #팥빙수 #양갱 옥루몽이 브랜드 바껴서 금옥당으로 운영돼요. 연희동에 1호점 있구 홍대와 인사동에 매장 있어요. 팥빙수 9천원에 팥추가하면 2천원이에요. 카페 분위기 조용하고 양갱 살 수 있어요', 2, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '선물하려고 샀는데 패키지가 너무 예뻐요! 근데 홈페이지 세트가격이랑 실제로 가서 산거랑 가격이 달라요  양갱 낱개가격으로 다 계산하시더라구요! 분위기도 좋아요', 2, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '#금옥당 원래 그 자리에 있던 다른 이름의 팥빙수를 먹으러 간 거였는데 이름이 금옥당으로 바뀐 가게가 들어선 것 같아요. 홍루몽이었던가요 그 가게 이름이.. 팥빙수는 맛있으니 리뷰는 패스하고, 양갱이 많이 달지 않아서 너무 좋았어요. 괜히 먹고 또먹고 싶어지는 매력적인 맛 ㅠ 어르신들도 좋아하실 거 같아요.❤ 굳이 흠을 찾자면 좀 비싼 게 흠이랄까요..', 86, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '금옥당 서교점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '차가운걸 안좋아해서 팥빙수는 잘 안먹게돼는데, 맛집이라고해서 간곳~~  올~~  은근한 단맛에 손이가는 ㅋ 팥이랑 연유, 우유, 떡만 있는 조촐하고도 품위있어보이는 ㅋ 암튼 맛집, 추천요', 33, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '일 때문에 홍대 왔다가 주차되는곳 검색해서 왓어여! 창가 자리 제일 좋아하는데 남자분들이 다들 핑퐁으로 가방을 놓고 있어서… 차라리 제일 모퉁이 구석 자리에 앉아 집중 하자! 콘센트 있는 모서리 벽자리 선택 ㅋㅋ 일도 하고 공부도 하고 회의도 하고 휴식도 취하고 정말 다양한 사람들, 분위기 ! 매력적인 곳이네요. 넓고 좌석도 다양하고 많아서 좋아요. 저녁때 되니까 자리가 여유로워지네요.', 20, 0, 'GOOD', SYSTIMESTAMP);
