INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대 한복판에서 주차할 수 있고 콘센트 많은 카페...? ㄹㅇ 귀함... 안티구아 짱맛이고, 화장실에서 따신 물이 나온다! 실내가 쬐끔 추움... 그치만, 다들 커피덕 하세요... 그럼... 20000...', 13, 4, 'GOOD', SYSTIMESTAMP);
