INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대의 카공을위해 태어난 카페느낌… 음료도 맛나고 디저트도 저렴한데 고급짐 커피는 산도가 약간 느껴지고 향이 색다름 그래서 더 좋았음 초코슈도 이색적인 맛이라 특별했음 그리고 주말인데 생각보다 자리 많음 강추합니다 👍', 70, 18, 'GOOD', SYSTIMESTAMP);
