INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '주차가 편리해서 너무 좋았어요!!! 홍대입구 바로 앞인데 주차가 무료에요ㅠㅠ 드립커피도 맛있네용ㅎㅎㅎ 주말 오전에 갔는데 오전시간 할인도 되고 콘센트도 많고 너무좋아옹ㅇ🙂', 78, 18, 'GOOD', SYSTIMESTAMP);
