INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아이스 아메리카노가 4500원이라고 나와있는데 영수증 보니까 5000원. 아무설명 없고 메뉴판에 찾아봐도 왜 500원이 추가로 붙은지 모르겠음. 남자분 굉장히 불친절함.', 88, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '와 여기 너무 맛있는데요?드립이랑 쿠키랑 찰떡궁합이네요:)  ㅎㅎ 우연히 지나가다 들어왔는데, 단골각이네요 :) 드립 원하는맛 딱 입맛에 맞아서 좋고, 가성비 좋아요', 6, 8, 'GOOD', SYSTIMESTAMP);
