INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대앞이라 카공족이 많은 거 같은데 사장님이 엄청 친절하시다. 공간도 넓고 가장 맘에 드는 건 커피랑 아인슈페너가 진짜 너무너무 맛있다는 점, 그리고 주차 공간이 많고 무료다. 쓸데없이 발렛비 받아가는 요원들도 없고 해서 합정에 일이 있을 때 항상 홍대까지 가서 아인슈페너를 먼저 마시던 미팅 후에 찾아가 마시고 온다. 아인슈페너 완전 강추임. 조카 다섯이랑 사촌부부랑 8명이 가 만족하고 돌아왔다. 쿠키랑 슈크림도 먹어볼만 하다.', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
