INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '우선 홍대인데 주차할수가 있어 좋습니다. 매장도 넓고 단체로 앉을수 있어요 커피는 산미가 좀 있는듯하고 디저트 종류도 좀 있어 자주 들릴듯 합니다.', 52, 15, 'GOOD', SYSTIMESTAMP);
