INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '1.음료가 매우 늦게 나옵니다. 1잔당 2분이라는 말은 완전 거짓말을 합니다. 2.고객의 질문에 매우 불친절하게 응대합니다. 3.제가 경험한 최악의 커피숍입니다', 2, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '친구랑 근처 카페 아무곳이나 간거였는데 아인슈페너가 너무 맛있었어요🥺 크림은 묵직하고 달달해서 취저였어요💜 커피에서는 신맛이 안났는데 커피거품(?)에서 신맛이 나서 살짝 으잉?했어요', 46, 4, 'GOOD', SYSTIMESTAMP);
