INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '일적으로 만날 일이 있어 홍입 근처로 카페 찾는중에 주차 가능+ 대화하기 편안한 분위기 인것 같아서 방문했어요. 가격 나쁘지 않고(뜨아4,000원, 페퍼민트 티3,500원) 책상 넓직한 곳 많아서 여러명 대화하기에도 또는 문서작업이나 공부하기레도 적격이네요. 잘 머물다 가요.', 22, 6, 'GOOD', SYSTIMESTAMP);
