INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍입 1출이랑 가까워서 좋아요. 아인슈페너가 정말 맛있습니다. 쓴 커피 못 먹는 제게 딱이었어요. 샷 조절도 되고요. 테이블이랑 의자가 편해서 대화 나누기 좋았고 공부하시는 분들도 많이 보였습니다.', 66, 14, 'GOOD', SYSTIMESTAMP);
