INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '공원뷰도 너무 힐링되고, 분위기도 좋아서 신촌역 카페 호기심 너무너무 좋았어요 ^^ 수박주스도 부드럽고 시원하게 마시기 딱 좋았고, 카페가 너무 좋아요 💕 공간도 편하고, 세련되고 디저트도 맛있었어요  💓직원분도 엄청 친절해요 😍 기분좋게 커피마시고가요 ^^ 👍', 46, 6, 'GOOD', SYSTIMESTAMP);
