INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '서강대역 (경의중앙선 - 단일역) 출입구 앞에 있는 카페인데, 건물이 통으로 전체가 하나의 카페입니다. 이름은 카페호기심~~ 일단 카페 층마다 다른 인테리어인데, 저는 4층을 가장 좋아해요. 4층에 올라가면 층고가 가장 높고, 통유리로 된 창의 view가 너무 멋져요. 오래전 기차가 다니던 길을 경의선 숲길로 만들었는데, 그 길가에 있어서 정말 뷰가 끝내 줍니다. 거기에 가장 중요한 커피맛은 기본으로 너무 좋고, 메뉴도 너무 새로운 것들이 많아요. 간단한 디저트용 메뉴는 물론 크로와상 샌드위치도 아주 맛있습니다. 강추에요. 오늘 저는 바닐라빈 라떼 커피 주문했는데, 달달함 향이 넘 좋아요.', 89, 12, 'GOOD', SYSTIMESTAMP);
