INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '주변에 약속 있어서 남는 시간 작업하러 왔는데 서치해본것보다 실제 와서 분위기도 좋고 조용하고 집중하기 좋은거 같아요 원두도 고를수 있고 디저트도 맛있어보여서 다음에 또 할 일하러 와야겠어요:) 진자 좋아하는 분위기의 카페를 오랜만에 찾아서 기분 좋은 하루에요🙂', 28, 6, 'GOOD', SYSTIMESTAMP);
