INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '이름부터 궁금해지는 카페 호기심 경의선 숲길 따라 산책하다 보면 보이는 큰 건물이 통으로 이 카페인데, 층마다 분위기가 달라 좋은 날 지인들과 놀러오기도, 조용히 공부하기도 좋습니다 커피도 디저트도 맛있어요 ✨✨👍🏻', 4, 6, 'GOOD', SYSTIMESTAMP);
