INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '비 오는 오후, 신촌 골목길을 걷다 ‘호기심’이라는 이름에 이끌려 들어갔습니다. 잔잔한 음악과 따뜻한 조명, 창밖으로 떨어지는 빗방울 소리까지 더해져 무심히 들른 공간이 뜻밖의 안식처가 되었어요.', 50, 0, 'GOOD', SYSTIMESTAMP);
