INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '장소가 쾌적하고 멋진 뷰를 가진 카페 호기심! 처음 생겼을 때 부터 종종 오고 있는데 올때마다 만족도가 높습니다. 작업하기에도 친구랑 편히 방문하기에도 좋아요!', 43, 1, 'GOOD', SYSTIMESTAMP);
