INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '서강대역 바로 앞에 위치한 대형 카페입니다. 각층마다 다른 컨셉으로 꾸며져 있어요. 특히 3층은 작업하기 좋은 공간이에요. 커피도 맛있습니다.', 35, 3, 'GOOD', SYSTIMESTAMP);
