INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '커피 넘 맛있구 작업 집중 잘 되는 피서지 같은 카페입니당ㅎㅎ🏝️ 경의선숲길 산책하다가 보고 느좋 카페인 것 같아서 와봤는데 역시 넘 좋네요! 또 올게요😚', 10, 4, 'GOOD', SYSTIMESTAMP);
