INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '작업하기 좋은 조용한 카페 호기심! 서강대역 근처에 있는데 건물 전체가 카페입니다 차분하고 조용한 분위기라서 작업하기에 좋아요 커피도 맛있고 바스크 치즈케이크도 대존맛🤭 꼭 드셔보세용', 13, 9, 'GOOD', SYSTIMESTAMP);
