INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '신촌 근처 제 최애 카페! 까눌레랑 너츠 휘낭시에가 정말 맛있어요. 디저트 안 좋아하는 남자친구도 반한 맛! 작은 4층 건물을 통으로 써서 넓고, 공부하기 좋은 좌석, 편하게 이야기하기 좋은 좌석 모두 있어서 좋아요🥰🥰', 39, 9, 'GOOD', SYSTIMESTAMP);
