INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '1층부터 4층까지 건물 통창뷰에 한번 그림처럼 이쁜 디저트에 또 한번 반하는 호기심 카페 전면이 공원× 탁트인 뷰가 있어서 오브제 같은 의자에 앉아 힐링하고 가요 담번에는 일찍와서 티그레 도전! 홍대 데이트 센스있는 원픽!', 11, 1, 'GOOD', SYSTIMESTAMP);
