INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '카공하기 너무 좋은 곳이에요! 매장이 정말 넓고 독특하면서도 차분해요 디저트도 정말 맛있어서 앞으로 단골 하고 싶은 카페예요💖 매장이 아주 넓고 대형 카페이다 보니 자리 없을 거라는 걱정은 안하고 오셔도 될 것 같습니다 ㅎㅎ', 74, 18, 'GOOD', SYSTIMESTAMP);
