INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '연세병원 방문으로 들려본곳인데 아무생각없이 들어왔다가 너무 좋아서 기분이 좋아요 ㅎㅎ 디저트도 맛있고 예뻐요 평화롭고 다 좋네요 ㅎㅎ', 2, 1, 'GOOD', SYSTIMESTAMP);
