INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '신촌, 서강대 근처에 있는 넓고 쾌적한 카페 호기심 4층까지 있어서 자유롭게 이용 가능해서 좋네요. 커피와 음료 그리고 디저트까지 개성있고 특별하네요. 아이스크림 좋아해서 아포카토 먹었는데 맛있어요.', 29, 5, 'GOOD', SYSTIMESTAMP);
