INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '경의선숲길 서강대역 방향으로 걸어가다보면 보이는 구름다리의 끝에 있는 카페 호기심!! (신촌연세병원 바로 옆이에요.)  서강대역 바로 앞이라 찾기 쉬운 카페입니다. 지하(베이킹랩)부터 4층까지 건물 통으로 카페라서 층층마다 분위기는 조금씩 다르게 꾸며놓으셨어요. 저는 2층부터 4층까지 모두 이용해 보았는데, 오늘은 아이와 학생들을 데리고 가느라 남자화장실이 있는 2층에 자리를 잡았습니다.^^ 특히 새로나온 티그레를 먹어보기로 했는데요. 평소 먹던 휘낭시에들보다 조금 더 겉은 단단바삭하고 씹는 맛이 있었어요. 특히 레몬가냐슈는 레몬즙을 넣어 만들어  상큼한 맛이 제 스타일이었어요. 역시 아이들은 초코릿 가냐슈 곁들인 초코티그레에 엄지척!! 색다른 분위기와 커피, 디저트를 맛볼 수 있어서 애용하는 카페예요.^^', 31, 3, 'GOOD', SYSTIMESTAMP);
