INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '디저트 베이커리 왕국 : 서강대역 카페 호기심 선물용 디저트들과 음료, 카페 분위기까지 총망라한 네이버 클립 선물용 디저트가 고민될 때 오기 좋은 카페 추천! ✅ 1-4층 홀 ✅ 선물용 디저트 고민될 때! 티그레, 바스크케이크, 티라미슈, 스콘, 휘낭시에 선물세트 판매 중! ✅ 합리적인 가격으로 판매되는 음료! 하지만 맛있다!', 74, 13, 'GOOD', SYSTIMESTAMP);
