INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '아침일찍 맛있는 커피와 샌드위치를 먹을 수 있는 근사한 카페가 역 근처에 있어서 너무 좋으네요! 경의선 종종 이용하는데 자주 올꺼 같아요👍', 16, 9, 'GOOD', SYSTIMESTAMP);
