INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인테리어가 층마다 다르고, 디저트 대 존맛이예요 엘베있어서 이동도 편한데, 음식올려놓을 공간도 마련해주셔서 너무 좋더라구요. 4층 대형카페가 서울에 있는게 너무 신기하고 좋았어요~', 118, 22, 'GOOD', SYSTIMESTAMP);
