INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '인테리어도 예쁘고 감성 넘치는데다 디저트랑 커피도 맛있어요🫶🏻 티그레 처음 먹어보는데 휘낭시에랑 비슷하면서도 견과류가 씹혀서 식감이 더 마음에 들었어요!! 레몬티그레 특히 아바라랑 잘 어울려요🤍 층마다 분위기가 다른데 3층은 작업하기 좋은 분위기였어요! 4층이 제일 마음에 들었는데 자리가 없어서 못 앉아서 아쉬워요🥺 홍대 가면 꼭 또 갈 거예요!! 대만족🫶🏻🫶🏻', 67, 15, 'GOOD', SYSTIMESTAMP);
