INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '통창으로 햇살이 가득 들어와서 분위기부터 너무 좋았어요. 카페라떼는 부드럽고 고소했고, 아메리카노는 깔끔하고 산미 적당해서 맛있게 마셨어요. 전체적으로 조용하고 따뜻한 느낌이라 혼자 오기도, 둘이 와서 이야기 나누기도 좋은 공간이에요.', 68, 11, 'GOOD', SYSTIMESTAMP);
