INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '산책하다 빵 냄새가 너무 좋아서 들렀는데 역시나 디저트가 너무 맛있네요. :) 까눌레와 휘낭시에가 특히 맛있었어요. 경의선 숲길에 올때마다 들릴것 같아요!', 35, 10, NULL, SYSTIMESTAMP);
