INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '호기심 커피도 맛있지만 말차라떼도 맛있어서 종종 마시러 옵니다🌱 단 녹차라떼 맛 아니고 찐 말차라떼 맛이에요! 날이 흐려도 뷰가 좋은 통창 카페입니다🤗', 16, 3, 'GOOD', SYSTIMESTAMP);
