INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '티그래가 예술! 커피원두 그윽~~밀크티까지 완소급! 1층부터 4층까지 아우르는 서강대역대형베이커리카페에서 여유롭게 힐링했으요~~🫶😘', 96, 23, 'GOOD', SYSTIMESTAMP);
