INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '서강대역 바로 앞에 있어서 위치가 좋았어요! 층마다 좌석 느낌이 모두 달라서 골라 앉는 재미도 있더라고요! 뭔가 분위기 좋은건 제일 꼭대기 창가 자리!! 저는 작업할거라 3층 갔는데 콘센트도 많고 자리도 넓어서 좋았슴다! 음료도 모두 맛있고 티그레? 처음 먹어봤는데 바삭촉촉해서 맛있게 잘 먹었어요!!👍🏻', 75, 15, 'GOOD', SYSTIMESTAMP);
