INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '경의중앙선 서강대역 바로 앞에 있습니다. 주차는 공영주차장 이용하시면 저렴하게 이용 가능하고, 여러 층이 있어서 자리가 많아요. 사람들도 많지만 조용해서 집중도 잘 됙ㅎ 개방감도 좋고 인테리어도 멋집니다. 티그레 진짜 맛있으니까 같이 주문하셔서 드셔보세요 ㅎㅎ 서강대역 카페 호기심 강추드립니더~!', 46, 10, 'GOOD', SYSTIMESTAMP);
