INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '바스크 치즈 케이크랑 바닐라빈라떼를 먹었습니다! 케이크가 맛있고 바닐라빈라떼 맛이 좋아요😀 바닐라빈라떼는 오트밀크로 바꿔먹었는데 오트랑도 잘 어울렸어요:)', 24, 0, 'GOOD', SYSTIMESTAMP);
