INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '경의선숲길 산책하다 들르기 좋은 큰 카페입니다! 통창이라 2~4층 다 뷰가 좋고 테이블, 의자들도 깔끔해요~ 주말 아침에 방문했는데 아직 자리 여유로웠어요 (저녁에 지나가며 봤을 때는 손님이 많더라구요!) 커피와 휘낭시에가 맛있습니다 👍🏻 탄맛이나 산미가 강하지 않은 밸런스 좋은 라떼였어요!', 55, 11, 'GOOD', SYSTIMESTAMP);
