INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '대박 좋아요. 신촌에 이런 좋은 카페라니 층수도 많고 혼자 카공하기에 좋은 창가쪽 자리도 있고 일단 디저트랑 식사대용 빵이 있어서 공부하면서 끼니떼우기도 좋고 예쁘고 쾌적하고 너무 좋아요!!', 88, 15, 'GOOD', SYSTIMESTAMP);
