INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '카페이름이 호기심 이길래, 정말 호기심에 들러서 빵을 사려고 들어갔는데 휘낭시에가 먹음직 스러워서 구입했어요. 정말 맛나네요. 촉촉하면서도 겉 토핑도 바삭한 것이 맛있네요', 71, 11, 'GOOD', SYSTIMESTAMP);
