INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '커피가 고소하면서 진하면서 넘 맛있고 소금빵도 겉에 바삭하고 담백한 맛이어서 넘 맛있고 시나몬 휘낭시에도 달달한 맛이어서 너무 맛있어요~!! 통창으로 되어있어 창밖을 바라보는 재미가 있고 카페에 있기만 해도 시원해서 좋고 인테리어가 현대적이고 예술적이면서 돌담같은거로 인테리어를 해놓으니 힐링이 되는 기분이어서 너무 좋았어요~~^^', 21, 4, 'GOOD', SYSTIMESTAMP);
