INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '조용하고 노트북 작업하기 좋은 카페네요. 집중도 잘되는 분위기에 노래까지 잔잔하고 좋아요. 커피도 맛있고 디저트 종류도 다양해서 종종 노트북 작업하러 올게요.', 35, 9, 'GOOD', SYSTIMESTAMP);
