INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '잠깐 시간 때우려고 들렸는데 디저트 너무 맛있어요! 까늘레도 겉바속촉에 휘낭시에도 넘 맛있음!! 나중에 티그레도 먹어봐야지~~', 44, 8, 'GOOD', SYSTIMESTAMP);
