INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대 근처에 넒고 조용한 대형카페가 없었는데 여기가 딱 그런 분위기라 너무 좋아요~ 안에 엘레베이터가 있어서 이동도 쉽고 4층 전부 카페입니다! 디저트도 다양하고 직원분들도 친절하세요.', 40, 5, 'GOOD', SYSTIMESTAMP);
