INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '호기심카페 4층에 앉았는데 통창으로 뷰를 보며 눈오는날,비오는 날에 와서 커피 마셔야겠다 생각했어요 디카페인 커피 맛도 괜찮네요 의자가 편하고 아늑했고 티그레 넘 예쁘고 바삭바삭했고 유자맛 티그레 완전 취저네요.', 78, 16, 'GOOD', SYSTIMESTAMP);
