INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '<카페 호기심> 집 근처라 산책하면서 인테리어가 너무 멋있어서 궁금했던 카페예요 통건물 카페인데 날이 좋아서 분위기가 너무 좋았어요! 채광도 좋고 인테리어도 요즘 스탈로 좋은데 휘낭시에가 너무 맛있어요 ㅠㅠ 빠삭하고 고소하고 진짜 넘 맛있어서 울동네 구움과자 맛집으로 인정,,!! 커피도 너무 맛있고 밤슈페너도👍🏻👍🏻 공간도 넓고 수다떨기도, 공부하기도 분위기 좋아서 경의선숲길 산책하다가 종종 들려야겠어요~', 40, 9, 'GOOD', SYSTIMESTAMP);
