INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '우연히 들어간 카페가 너무 마음에 들어서 찜까지 했어요..! 매장인테리어가 너무 예쁘고 해가 다 들어오는 통창이라 오전에 갔는데 짧은 시간이지만 힐링하고 왔어요. 다음에 꼭 다시 방문하고 싶을 정도로 나오기 아쉬웠던 곳입니다. 2~4층까지 좌석이 있고 사장님도 너무 친절하셔서 기분 좋았어요. 리뷰 남기고 싶다고 하니 휘낭시에까지 서비스로 주셔서 아침에 기분좋게 하루를 시작할 수 있었네요. 잠봉뵈르 퀄리티도 너무 좋고 맛도 신선했어요. 디저트류도 아기자기 하게 종류가 다양해서 선물하기도 좋겠더라구요. 사장님께 약속드린대로 조만간 꼭 다시 방문할게요ㅎㅎ 역근처 카페 찾으신다면 너무너무 추천드립니다~~', 22, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
