INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '여기 소금빵 휘낭시에 맛있어서 몇번 먹으러 왔었는데 이번에  케이크 먹고 눈 띠용!! 진정한 바치케 맛집 왜이리 부드럽지?????? 커피랑 먹으니 더 맛나더라구요 얘기 하기 좋고 선곡도 훌륭한 신촌힐링카페 👍', 29, 6, 'GOOD', SYSTIMESTAMP);
