INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '신촌에 이정도 규모의 대형카페가 있는것을 이번에 알았어요! 디저트 종류도 많아서 무엇보다 맘에 들었는데 글루텐프리래요:) 카공하기도 좋고 조용히 대화하기 너무 좋은곳이라서 저장해뒀다가 재방문 예정입니다!', 33, 2, 'GOOD', SYSTIMESTAMP);
