INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '카페 분위기도 너무 좋고 조용해서 편하게 대화 나누거나 노트북 하기도 좋아요!! 디저트까지 다양합니다👍🏻🥰🥰 4층까지 있는데 좌석도 다 느낌이 달라서 멀리 여행 온 기분입니다!! 날씨 좋을 때 또 오려구요!', 85, 16, 'GOOD', SYSTIMESTAMP);
