INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '경의선숲길 다니면서 가보고 싶었던 카페인데 드디어 방문해 봤는데, 커피 너무 맛있네요.. 👍👍 인테리어도 넘 예쁘고 티그레 겉바속촉이에요. 직원분도 친절하고 넘 맘에 드는 카페입니다.', 21, 10, 'GOOD', SYSTIMESTAMP);
