INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '건물 4층을 통으로 쓰고 있는 호기심 카페는 각 층마다 컨셉에 있어요 3층에는 공부하기 좋고 2층엔 대화하기 좋고 4층도 아주 멋져요  커피 정말 맛있지만 디저트도 훌륭합니다  정말 정말 맛있습니다  분위기 있고 멋진 카페 호기심 자주 올 거 같아요 휘낭시에 선물용으로도 너무 좋아요 😀😃😄', 110, 26, 'GOOD', SYSTIMESTAMP);
