INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '산책할때마다 궁금했었는데 첫 방문 ! 솔티드 카라멜 라떼 6,000 얼그레이 라떼 6,500 직원분들 친절하시고 디저트도 다양해요! 매장 인테리어도 너무 깨끗하고 이야기하기 좋아요!', 43, 1, 'GOOD', SYSTIMESTAMP);
