INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '바스트 치즈 케이크 존맛탱이에요..❤️ 치즈가 완전 부드러워가지고 입에서 녹습니다 친구는 오미자 에이드 시켰는데 기냥 원샷 때렸어요ㅋㅋㅋㅋ 아이스 아메리카노 고소한 맛으로 시켰는데 이것도 맛있네요. 매장이 2층 3층 4층 다 앉을 수가 있어 가지고 일층에서 주문후 올라오면 됩니다. 4층이 천장도 잘 보이고 통창도 있어서 4층에 앉았는데 친구랑 자주 올 것 같아요.재방문 의사 있습니다😘☺️💖', 35, 1, 'GOOD', SYSTIMESTAMP);
