INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '지나가는 길에 보면서 늘 가보고 싶었던 카페 방문! 사람이 꽤 있었음에도 조용하고 차분한 분위기가 너무 좋았어요. 커피맛도 괜찮고 베이커리가 너무 맛있네요👍 창가에 혼자 앉아 커피 마시기 너무 좋아요. 동네니까 자주 방문해야겠어요', 40, 4, 'GOOD', SYSTIMESTAMP);
