INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '디저트부터 음료까지 완벽하고 서울 대형카페 중 손에 꼽힐 정도로 좋음 :) 가격도 아주 적절하게 책정되어 있으며 글루텐프리 베이커리가 있고 맛도 좋음! 자세한 블로그 리뷰는 여기! https://m.blog.naver.com/qkrrudcnr/223729683385', 122, 26, 'GOOD', SYSTIMESTAMP);
