INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '4층까지 있어서 넓고 쾌적해요 ••• 공부하기도 좋은데 감성 챙기기도 너무너무 좋음 🤍🤍 이 동네에 이런 곳이 있을 줄은 몰랐네용 대학생들도 많이 와서 공부하고 직장인들도 많이 오는 듯 합니다 그리고 휘낭시에 !!!!! 🤍🤍 부모님 선물하기 딱 조으네요 •••', 116, 22, 'GOOD', SYSTIMESTAMP);
