INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '닭가슴살 샌드위치도 너무 맛있고 자리도 많아서 대기 없이 바로 입장할 수 있어 너무 좋았습니다!! 다음에도 또 근처 올 일 있으면 방문 예정입니다:-)', 34, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '신촌대형카페! 대형이제만 섬세한 서비스와 조용한 카공분위기 #카페호기심 대학생들이 많고 외국인들도 많은 카페 #피낭시에맛집 #디저트맛집 #커피맛집 #피낭니에선물 하기에 너무좋은 구성 💕 #신촌카페추천 #카페라떼맛집', 6, 0, 'GOOD', SYSTIMESTAMP);
