INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '카페 분위기도 너무 좋고 넓고 쾌적해요~ 아메리카노와 밤슈페너, 티그레3종 먹었는데 티그레 정말 깊고 진한맛으로 너무 맛있고 음료도 디저트랑 잘 어울리고 맛있어요! 자주 갈거같아요!', 125, 24, 'GOOD', SYSTIMESTAMP);
