INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '🌟서강대신촌대표카페🌟 진짜 서강대생들 부럽다 바로앞에 호기심카페있어서... 디저트 비쥬얼 대박입니다 발렌타인데이때 남자친구와방문했는데 진짜개쩔탱JMT (낮에방문하면 더 다양한종류 디저트있을듯) 카페도큰데 분위기도좋아서 완전 느좋카페 분좋카카페그자체 콘센트도 낭낭해서 노트북가지고 카공하기도넘 좋았어요💕💕 담에또올꺼임...(말차라떼존맛)', 32, 1, 'GOOD', SYSTIMESTAMP);
