INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '신촌 호기심 카페 커피와 공간의 특별한 조화 층별 매력을 품은 마포구 대표 카페, 호기심 서강대 역 명소, 감각적인 인테리어가 돋보이는 호기심 카페 일상과 여유를 담은 마포구의 핫 플레이입니다 4층, 각 층마다 다른 매력의 공간 1층: 첫인상의 고급스러움 블랙 컬러와 심플한 디자인, 그리고 곳곳에 배치된 돌 인테리어 요소가 현대적인 감각을 살립니다. 입구부터 세련된 분위기를 느낄 수 있습니다. 2층: 모임에 최적화된 안락함 넉넉한 소파 좌석과 은은한 조명으로 친목 모임, 데이트에 완벽한 공간을 제공합니다. 따뜻하고 편안한 분위기로 대화를 즐기기 좋습니다. 3층: 노트북 작업 공간 조용하고 환한 환경에서 집중할 수 있는 공간으로, 넓은 테이블과 전원 플러그까지 완비되어 있습니다. 학생', 25, 0, NULL, SYSTIMESTAMP);
