INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '위치가 너무 좋고 낮엔 공원뷰, 밤엔 야경이 멋져요 다이어트 바스크치즈케잌이라니 감동이었어요 디카페인커피도 있고 녹차라떼 진하고 맛있었어요 무엇보다 베이커리 퀄리티가 좋고 인테리어가 멋져요', 28, 7, 'GOOD', SYSTIMESTAMP);
