INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '서울 4층규모 대형카페에 깔끔하고 인테리어도 예뻐요 💗 글루텐프리라는점이 너어무 맘에들고요 휘낭시에 진짜 너어무 맛있어요 🍞👍 매장4층에서 직접 원두도 볶으셔서 그런지 커피도 맛있구, 사진도 잘나와요 🥹✨️🫶 마포에서 이런 좋은 카페 알게되서 넘 좋네용! 자주 갈것같아요 :)♡🍀', 22, 3, 'GOOD', SYSTIMESTAMP);
