INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '생딸기 프레지에 진~짜 맛있습니다 ㅎㅎㅎ 가게두 넘 이쁘구 깨끗하구 분위기 있구 최고에요!!! 3층 사진인데 엄청 조용해요 ㅋㅋㅋ 평일 오후는 독서실 같은 분위기. 주말은 좀 시끄러울 수도 있을 거 같네요 ㅎ 조용히 와서 근무하거나 공부해도 좋을 거 같아요!!', 4, 2, 'GOOD', SYSTIMESTAMP);
