INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '첫눈온날 방문 눈내리는 뷰 넘 예쁜거 아닌지... 전면 통창이라 진짜 스노우볼에 들어있는 줄 알았당...😣🧊❄ 레몬케이크 넘 굿이고 티라미슈도 부들부들 맛있움 카페인 약빨이 너무 잘받아서ㅋㅋㅋㅋㅋㅋㅋ디카페인 아니면 못먹는데... 여기는 원두 3가지 중에 디카페인도 있어서 바로 골랐당 모둔 카페에 디캎페인 있었으면!!!! 전에 왔을때 쑥이랑 얼그레이 휘낭시에도 먹어봤는데 여기 베이커리는 실패가 없음 짱추천', 6, 6, 'GOOD', SYSTIMESTAMP);
