INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '휘낭시에 가격도 싼데 짱 크고 넘 맛있어요 게다가 글루텐프리라서 밀가루 못 드시는 분들도 부담없을 듯 합니당! 창이 훤하게 뚫려있어서 너무 쾌적하게 공부하다갑니다 ㅎㅎ', 35, 5, 'GOOD', SYSTIMESTAMP);
