INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '집근처에 이렇게큰 카페가 있어서 너무 행복해요 ㅠ게다가 라떼도 맛있어요. 매번 디카페인 먹는데 꼬숩고 좋아요. 원래도 시크한 느낌의 카페라 좋았는데 요즘 크리스마스 시즌이라 예쁘게 꾸며놔서 더 예뻐졌네요. 😆😆', 59, 11, 'GOOD', SYSTIMESTAMP);
