INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '눈오는 날 혼자 라떼 마시고 작업하러 왔는데 커피도 정말 맛있고 전체적으로 통창 공간이라 넓고 답답함 없어서 정말 좋았어요ㅎㅎ 카페 불모지인 광흥창에 이렇게 좋은 카페라니! 앞으로 자주 들르게 될 것 같습니당 좋은 시간 잘 보내고 가요!!', 68, 18, 'GOOD', SYSTIMESTAMP);
