INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커피 외에 말차라떼도 맛있습니다! 휘낭시에도 사치스러운 맛이에요 ☺️ 주말/공휴일에는 역시 사람이 많네요, 숲길 산책하다 들르기 좋은 공간입니다 🍵', 65, 16, 'GOOD', SYSTIMESTAMP);
