INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '근처 카페 중 가장 좋습니다. 커피 너무 맛있고 빵도 전문 베이커리보다 맛있어요. 분위기도 조용하고 좋습니다. 많이 왔는데 올 때마다 직원 분들 항상 너무 친절합니다. 가까운 데 이런 카페가 있어 행운이에요.', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '카페 호기심이 서울 대형카페중에 TOP3안에 들어갈 대형카페인거 같아요~! 매장이 넓은것도 그렇고 4층건물에다가 모든층이 통창으로 되어있어서 개방감이 너무 좋고 보기만해도 시원하네요~ 게다가 돌담으로 인테리어를 해놓으니 마치 제주도에 있는 건만 같은 기분이 들어서 너무너무 좋아요~~! 의자가 다양한 의자종류가 있어가지고 골라서 앉는 재미가 있고 특히 쇼파형 의자에 앉아봤는데 푹신푹신하고 계속 앉는 내내 정말로 편안했어요! 커피하고 미니레몬 케익하고 휘낭시에를 같이 먹어보니 조합이 잘 어울리고 커피가 진한맛이었어서 맛있었고 미니레온 케익,휘낭시에도 부드러워서 너무 맛있었어요~! 다른 베이커리들도 진열해놓은게 너무 예뻤네요~ 장시간 머물기 매우 좋은 카페고 재방문 의사 완전 100%입니다!!👍👍', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
