INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '집 근처에 이렇게 뷰 좋고, 쾌적한 카페가 있어 카공할 때 애용합니다💻🩶 커피도 맛있고, 디저트가 진짜.. 맛있어요.... 가격이 막 저렴한 편은 아니어도 적립이 나름 높은 비율로 돼서 너무 잘 활용하고 있어요!!! 자주 가다보니 정말 애용한답니다💚 다만,, 아쉬운 건,,, 손님들이 가고 나서 빈자리가 정리되는 모습을 제대로 본 적이 없어요. 남은 자리에 물기가 묻어있기도 하고 디저트 부스러기가 있는데 매번 직접 치우고 앉았답니다. 그리고 빈 컵이랑 쟁반이 자리를 차지하고 있는데도 결국 안 치워지더라구요. 바쁠 때는 어쩔 수 없다 생각해도 1층 내려가보면 직원분들이 충분히 살필 수 있는 여유가 있어보였었어요..! 너무 좋아하는 카페인데 손님들이 머물고 간 자리 정돈에 좀 더 신경 써주시면 좋을 듯 합니다!', 82, 13, NULL, SYSTIMESTAMP);
