INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '딸기라떼가 딸기과육이 살아있어서 너무죠으다 스콘이 너무맛있어서 죠으다 쵸콜렛휘낭시에는 초코가찐하니 깊은맛이나며 안에는 초코케잌느낌이나며 정말 진하게 맛있어요ㅎ 분위기 너무좋고 직원분들 친절하셔여ㅎ https://m.blog.naver.com/miracle12378/223719109166?afterWebWrite=true', 13, 6, 'GOOD', SYSTIMESTAMP);
