INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '여기 카페 휘낭시에가 제일 맛있어요!!!😀 카페라떼도 맛있어서 올 때마다 주문합니당~ 겉바속쫀 휘낭시에를 비싸지 않은 가격에 즐길 수 있어서 넘 좋아요🪽', 45, 5, 'GOOD', SYSTIMESTAMP);
