INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '음악과 인테리어가 너무 좋은 서울대형카페네요! 교외까지 안 나가도 되니 너무 좋아요~ 음악이 잔잔해서 책 읽기도 좋고, 노트북할 콘센트도 있어요! 층마다 인테리어가 달라서 골라서 보는 재미가 있어요. 직접 볶은 원두와 직접 만든 베이커리가 너무 맛있어요!', 84, 14, 'GOOD', SYSTIMESTAMP);
