INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '건물 전체가 카페여서 자리 잡기 좋았고, 통창으로 경의선 숲길을 조망하며 이야기 나누기 좋았습니다~ 커피와 휘낭시에도 맛있었습니다:)', 14, 0, 'GOOD', SYSTIMESTAMP);
