INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '무엇보다 통창의 느낌이 좋아요 직장근처라 점심에 방문해 여유가 없었지만ㅎㅎ 창밖보며 멍때리기도 좋고, 뭔가모를 여유가 느껴지는 까페라애용합니다 휘낭시에  맛있고 커피도 괜찮은데 커피양은  좀 적은듯 ㅎㅎ 분위기값😉', 48, 8, NULL, SYSTIMESTAMP);
