INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '친구랑 저녁먹고 커피마시러 신촌대형카페호기심 방문했어요! 여기 분위기도 난리나는데 커피랑 디저트맛이 넘사벽입니다,,, 무려 4층건물이라 좌석도 많은데 인테리어도 멋져서 사진맛집이에영ㅋㅋㅋ 일하시는분들도 모두 에너지넘치고 친절하셔서 신촌 최애카페에용><🩷🩷 *업체로부터 서비스를 제공받았지만 솔직하게 작성한 리뷰입니다*', 30, 1, 'GOOD', SYSTIMESTAMP);
