INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '다크초코 티그레 화이트초코 티그레 레몬가나슈 티그레 반해버리는 맛!! 서강대역 느좋카페와서 커피와 산느라피치 마시며 행복했어요^^', 6, 2, 'GOOD', SYSTIMESTAMP);
