INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '4층까지 있고, 다양한 의자와 테이블이 다양하고 인테리어가 예뻐용 ~ 자리두 편안하고 널찍해서 공부하기도 좋고 조용히 대화하기도 편한 자리입니당 디저트랑 음료도 맛있어요 🍓', 3, 4, 'GOOD', SYSTIMESTAMP);
