INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '이근방에 이런 규모의 카페는 처음인데 분위기에 감성에 디저트까지 전부다 잡은 커피숍은 처음입니다. 직원분들의 친절한 응대에 감동이에요🥹 바디감 좋은 아메리카노와 휘낭시에를 먹었는데 다른것도 궁금해져서 재방문 예약이에요.!!', 41, 0, 'GOOD', SYSTIMESTAMP);
