INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '서강대 늦게까지 여는 카페 찾아왔는데 대형카페 + 디저트맛집으로ㄷ 단골 예약입니다❣️✨ 카페가 뷰도 멋있고 글루텐프리 휘낭시에가 진짜 맛나서 신촌구움과자 맛집이네요! 4층까지 건물을 통으로 쓰는데 엘베가 있어서 이동하기도 편하구~ 직원분들도 다 친절하셔서 혼카페하기 진짜 좋아용 ㅎㅎㅎ 강추 ㅎㅎㅎㅎ', 50, 0, 'GOOD', SYSTIMESTAMP);
