INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '채광이 잘 들고 집중하기 좋은 환경이라 좋아요!! 커피랑 스콘 둘다 맛있습니당!! 신촌 서강대역근처 대형카페 찾는다면 추천해요!!', 70, 12, 'GOOD', SYSTIMESTAMP);
