INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '서강대 가까이에 있는 호기심카페! 일단 4층까지 있어서 노트북 좌석부터 편하게 있을 수 있는 좌석까지 많구요 여기 소금빵 그냥 믿고먹어야해요 바삭하고 쫄깃 ㅠㅠ 오미자차 정말 좋아하지만 파는곳 없는데 여기는 오미자차도 있고 빵 너무 맛있어서 친구 선물해주려 휘낭시에 선물세트도 구매했어요! 포장도 예쁜 백에 넣어주시니까 더 맘에들어요 🎁🎁', 36, 7, 'GOOD', SYSTIMESTAMP);
