INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '와 이렇게 멋진 대형 카페가 있군요! 층마다 살짝 다른 인테리어도 멋지고! 무엇보다도 글루텐프리 휘낭시에도 맛있어요! 😊 글루텐프리라서 더 안심하고 먹을 수 있어요~ 커피도 원두가 고소해서 정말 마음에 들었고! 디저트류도 가득한데, 식사 대용으로도 가능한 샌드위치까지 있어서 좋아요~ 카페에서 나오면서, 샌드위치까지 추가 구입했네요 😊', 13, 4, 'GOOD', SYSTIMESTAMP);
