INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '넓고 깨끗해서 작업하기에 딱 입니다. 특히 커피도 완전 꿀맛…위에 로스터리가 있어서 그런지 더 믿음직스러워요. 신촌 카페 가실 일 있으면 여기 가십쇼들', 77, 13, 'GOOD', SYSTIMESTAMP);
