INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '층마다 다른 분위기가 넘 매력적이고 데이트, 소개팅, 친구들이랑 오기에 좋아요! 특히 3층은 카공하거나 작업하기 좋아서 여기는 앞으로 65754번 더 올거 같네요 ㅎㅎ 글고 휘낭시에 겉은 바짝하고 속은 부드러어서 맛있으니까 꼭 드세요!', 30, 4, 'GOOD', SYSTIMESTAMP);
