INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '카페 분위기도 좋구 커피원두도 종류가 3개정도있어서 선택하기도 넘 좋았어요~ 베이커리류 가격도 적당한거 같아서 이후에 재방문의사 있습니당', 24, 7, 'GOOD', SYSTIMESTAMP);
