INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '클래식 휘낭시에 2,500원 너츠 휘낭시에 3,000원 초코 휘낭시에 3,500원 미니 레몬 케이크 3,500원 ㄴ선물 박스 2,000원 디카페인 아이스 아메리카노 5,000원 초코 라떼 6,000원 휘낭시에가 모두 글루텐프리인데, 너어어어무 맛있어요!!👍 기본 휘낭시에 자체도 겉바속쫀이고, 버터 풍미 가득이라 아주 맛있고, 너츠, 초코, 레몬은 위에 토핑(?)이 정말 듬뿍이에요!! 아아랑 아주 찰떡쓰✨️ 선물 박스 포장도 깔끔해서 선물용으로 딱이고, 친절하고, 대형카페라 넓어서 좋아요. 👇더 자세한 후기는 아래 블로그 참고해주세요~ :) https://m.blog.naver.com/PostView.naver?blogId=jjxd_road&logNo=223687911555&navType=by', 0, 9, 'GOOD', SYSTIMESTAMP);
