INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '딸아이와 데이트 잠봉뵈르샌드위치 먹으러 왔다가 "에쏘프레소 문경" 완존 맛나네요 소금빵도 너무 맛나구요 휘낭시에도 고민하다가 초코로선택 맛나요 정말 재방문 의사 100프로에요', 9, 4, 'GOOD', SYSTIMESTAMP);
