INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '데이트목적뿐아니라 3층은 스터디존도 콘센트랑 너무 잘 되어있어서 다음번엔 공부하러도 와야겠어요 카페 엄청 크고 좌석도 편한 소파부터 다양하게있어서 데이트하기두딱 ㅠㅠ 인스타 사진 백만장 찍어갑니다', 8, 7, 'GOOD', SYSTIMESTAMP);
