INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '디저트랑 음료가 맛있는 분위기 좋은 카페예요! 글루텐프리라 건강하게 먹을 수 있는 디저트인데도 맛있고 커피랑 밀크티도 맛있어요! 층마다 분위기가 달라 이색적이고 쇼파가 편해서 좋아요', 67, 14, 'GOOD', SYSTIMESTAMP);
