INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '지나가다가 배가 정말 너무 고파서 소금빵만 포장해왔습니다. 뷰도 좋아보이고 외관도 멋있었는데 시간이 없어서 머무르지 못한 게 아쉽습니다. 가격대가 좀 있는 편인데, 소금빵은 다른 빵집이랑 가격대가 비슷했습니다. 바삭하고 부드럽고 짭짤한 소금빵의 정석이었습니다. 다음엔 매장에서도 한번 먹어보고 싶습니다.', 32, 7, 'GOOD', SYSTIMESTAMP);
