INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '추천 받아서 방문했어요✨ 음료 종류도 커피, 티 다양하고 인테리어도 너무 이쁘네요 ☺️ 수다 떨 수 있는 공간, 혼카페 공간도 있어서 자주 와야겠어요 🤍', 11, 6, 'GOOD', SYSTIMESTAMP);
