INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '달달한 티그레에 아메리카노 조합 아주 좋아요, 말차라떼는 저어 마시라 해서 그대로 했는데 말차의 진한 맛이 잘 올라왔어요 :)', 31, 5, 'GOOD', SYSTIMESTAMP);
