INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '커피는 기본적으로 너무 맛있었고, 특히 디저트가 정말 맛있었어요!!🥹 겉은 바삭하고 속은 촉촉해서 한 입 먹을 때마다 너무 행복하더라구요ㅎㅎ 카페 내부는 통창 유리로 되어 있어서 창 밖 경치를 보며 커피 마실 수 있고, 분위기도 아늑하고 편안해서 전반적으로 분위기, 커피, 디저트까지 모두 만족스러웠어요. 직원분들까지 너무 친절하셔서 다음에 또 오고 싶어요!!☺️☺️', 82, 15, 'GOOD', SYSTIMESTAMP);
