INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '겉에서 봤을 때 너무 이뻐서 나중에 와봐야겠다고 생각했는데, 생각했던 것보다 더 좋네요 🥹 휘낭시에도 겉바속쫀이랑거 너무 맛있고 특히 쑥 휘낭시에 너무 맛있어요!! 아메리카노랑도 잘어울려요! 4층까지 있는데 층마다 분위기도 다 달라서 혼카하거나 데이트하기에도 좋을거 같아요!!', 11, 3, 'GOOD', SYSTIMESTAMP);
