INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '4층까지 있는 서울대형카페입니다 카공하기, 모임, 수다떨기 더 좋은 곳이고 디저트는 글루텐프리로 만들어져 건강하고 맛있습니다 *해당 리뷰는 식사권을 제공받아 솔직하기 작성한 리뷰입니다*', 14, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '서강대역이랑 신촌역 근처에 이렇게 큰 카페가 있는지 몰랐어요! 더 일찍 생겼다면 시험기간에 많이 갔을거같아요! 커피도 맛있고 베이커리 메뉴도 간단히 먹기 좋아요~ 층별로 분위기가 좀 달라서 2층은 대화하기 좋고, 3,4층은 공부하거나 과제하기 좋아요 ㅎㅎ 커피향도 너무 좋았어요! 근데 라떼 잔에 손잡이 있으면 더 좋을거같아요. 컵 컬러는 너무 예쁜데 약간 사약먹는거처럼 커피를 마시게 되는게 아쉬운…🥲', 41, 5, 'GOOD', SYSTIMESTAMP);
