INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '처음방문했는데 커피도 디저트도 너무 맛있었어요. 창밖의 비오는 풍경도 운치있었고, 따뜻한 미소로 친절하게 안내해주신 매니저님 덕분에 기분좋은 오후 시작했습니다~ 자주 이용하게 될것같아요^^', 3, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '매장 넓고 서강대역 앞에있어서 교통도 너무 편해요! 친구들이랑 약속잡기 너무 좋은 장소!! 좌석도 편하고 디저트도 다 너무 맛있어서 공부하기도 너무 좋아요! 공부나 일하시는 분들 많더라구요!! 다음엔 소파자리에서 책 읽으러 올거에요💓💓', 42, 3, 'GOOD', SYSTIMESTAMP);
