INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '적당히 차분한 분위기에 작업을 하거나 책을 읽어도, 지인과 수다로 시간을 보내도 좋습니다!! 티그레 추천하는 메뉴구요💕💕 큰 창으로 바깥 구경도 하면서 여유롭게 즐겼어요😆', 15, 5, 'GOOD', SYSTIMESTAMP);
