INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '혼자 방문했습니다. 휘낭시에 4구를 시켰는데 글루텐프리임에도 불구하고 바삭 쫀득 진짜 맛있어요 💙 건물 전체가 다 카페이고 층마다 분위기가 달라서 좋았습니다. 통창이어서 뷰도 좋고 커피도 맛있어서 재방문하고싶어요!', 74, 14, 'GOOD', SYSTIMESTAMP);
