INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '베이킹부터 로스팅까지 모든 것이 이뤄지는 카페☕️ 글루텐프리의 베이커리도 다양해요! 휘낭시에 맛집인데 바치케도 꾸덕하니 맛있는 아메리카노도 고소한 맛이 강해 베이커리들과 너무 잘 어울리더라구요😋 층마다 분위기도 다르지만 3층은 스터디하는 분위기가 강해 공부하기에 좋은 카페', 50, 6, 'GOOD', SYSTIMESTAMP);
