INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '캐러멜너츠스콘 먹어봤는데 견과류 많고, 겉이 바삭한게 너무 맛있어요!! 경의선숲길 산책하면서 통창으로 보이는 인테리어가 멋있어서 한 번 와본건데, 예상 외로 디저트가 너무 맛있어서 조만간 또 방문할 것 같네요!! 고소한맛 아메리카노도 산미 싫어하는 제 입맛에 너무 잘 맞아서 맛있게 마셨어요!😆', 7, 7, 'GOOD', SYSTIMESTAMP);
