INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '4층 건물이 전부 카페라니요..!! 서울에 이런 대형카페 너무 좋습니다~ 여기 휘낭시에... 제 인생 휘낭시에입니다!!! 진짜 너무너무 맛있어요!! 먹고 집에갈때 또 사갔어욬ㅋㅋㅋㅋㅋㅋㅋ 근처에 대학교가 많아서그런지 학생들도 많았는데 스터디하기에 분위기도 좋았습니다👍🏻', 24, 3, 'GOOD', SYSTIMESTAMP);
