INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '처음 가오픈 할때부터 궁금했는데 계속 사람이 많더라구요. 소금빵 먹어보고 싶었는데 이제 안하신다는 건지 품절인건지 없었어요. 디카페인 좋아하는데 맛있어요~~자리 간격 좋네요. 자주 올게요.', 6, 7, NULL, SYSTIMESTAMP);
