INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '서강대역 근처 대형카페… 통유리여서 뷰도 너무 좋고, 작업이나 공부하기, 수다떨기도 좋음..!!! 노슈가 바스크치즈케이크와 글루텐프리 휘낭시에가 진짜 너무 맛있어용..🥹💖 날 좋을 때 가면 정말 힐링 가능 !!! 당장 가보셔요들..,,, 맛난 디저트들과 너무 좋은 시간 보내고 왔습니당', 9, 10, 'GOOD', SYSTIMESTAMP);
