INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '2024년 마지막날인 12월 31일에 방문했는데요😙 층별로 인테리어 컨셉이 다 달라 너무 신선했어요 ㅎㅎ 휘낭시에도 종류가 엄청 많아서 고르는 데 은근 재밌었어요ㅎㅎ 골라온 것들도 하나같이 다 맛있더라구요!! 커피도 너무너무 고소해서 휘낭시에랑도 잘 어울리고 완전 최고 >.<♡ 서강대역 바로 앞에 있어서 찾기도 너무 쉽고 데이트 장소로 카공 장소로 완전 추천드립니당😇🤍', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
