INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '신촌에서 4층 규모의 초대형 카페 발견! 😍 오픈한지 얼마 안 되어서 엄청 쾌적하고 깨끗하더라고요. 다들 어디서 오픈 소식을 듣고 온건지 사람도 정말 많고, 베이커리 메뉴도 맛있어 보이는 게 정말 많더라구요. 저는 글루텐프리 제로슈가 바스트치즈케이크랑 소금빵을 주문해서 먹었는데 너무 맛있었습니다 🤩 분위기가 너무 좋아서 작업하러 오는 학생들도 많은 것 같던데 저도 다음에 책 읽으러 오려구요!☺️', 1, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
