INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '새로생긴 곳이라고 들어서 방문했어요. 주차공간이 있는 이렇게 좋은 곳 찾기 쉽지 않은데 주차공간도 4대나 가능하고, 만차시 근처 공영주차장도 합리적인 가격에 이용가능해 좋아요. 커피도 맛있고 베이커리 류들이 진짜 대박입니다. 곧 밥을 먹어야하는 상황이라 다양한 디저트를 경험하지 못한게 아쉬울 정도ㅜ 다음에 또 와서 이것저것 시켜먹을 계획이에요!', 29, 5, 'GOOD', SYSTIMESTAMP);
