INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '여기 제가 진짜 좋아하는 카페예요...🩵🩵 음료도 맛있고 커피도 고소하게 맛있는 곳이라 좋아해요 원두도 고를 수 있는 것만으로도 다양한 선택지가 있는 거 같아서 마음에 듭니다🩵 게다가 진짜 좋아하는 휘낭시에..! 여기는 다양한 맛으로 나와있어서 매번 새롭게 시도할 수 있어서 좋아요👍', 79, 18, 'GOOD', SYSTIMESTAMP);
