INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '인테리어도 근사하고 통창이 진짜 멋져요. 바로앞에 공원있어서 초록초록한데 옆에 운동하는분들 도 보이고 뭔가 되게 뿜뿜되는 곳. 저도모르게 창멍하게 되네요. 거기다 디저트도 글루텐프리라서 더 좋고 음료도 맛있어요', 0, 2, 'GOOD', SYSTIMESTAMP);
