INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '눈어겨보다가 와봤는데, 생각보다 안에 아늑해요. 3,4층은 노트북하기 좋고 조용합니다. 디저트도 생각보다 다양해서 휘낭시에 샌드위치류도 있어요!!', 14, 9, 'GOOD', SYSTIMESTAMP);
