INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '신촌역 서강대역에서 가까운 대형카페에요! 휘낭시에는 글루텐프리 (쌀가루) 로 만들어져 아토피 걱정이 있는 분들도 접하기 쉬울 것 같고 겉바속촉 그 자체! 매장 내부와 선물 포장 세트 모두 고급스러워서 선물하기도 좋을 것 같아요', 41, 8, 'GOOD', SYSTIMESTAMP);
