INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '인테리어도 독특하고 지나가다가 많이 봤는데 통풍유리로 되어있어 내부도 보이고 시원한 느낌이라 좋아요!! 다양한 휘낭시에 맛볼수있어서 좋은것같고 다이어트 바치케가 있어서 다음에도 먹으러 와보려구요!', 40, 10, 'GOOD', SYSTIMESTAMP);
