INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '치즈케이크가 너무 먹구싶어서 찾다가 와본 카페 ! 인테리어도 매우 깔끔하고 디저트 종류도 매우 많음 바스트치즈케이크도 시켰는데 너무 맛있었어요 - 카밀커피와 스트로베리 밀크티를 시켰는데 둘다 입맛에 잘 맞아서 좋았습니다 ✨🤍 대형카페라 자리도 매우 많지만 사람도 엄청 많아서 예약하고 가시는걸 추천드려요 ~!', 40, 7, 'GOOD', SYSTIMESTAMP);
