INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '친구 추천으로 온 곳인데 분위기가 너무 좋고 음료랑 디저트 다 맛있어서 다음에 또 오고싶어요… 😚 직원분들도 너무 친절하시고 좋아요! 카공하기에도 좋을 것 같아요 ㅎㅎ', 66, 15, 'GOOD', SYSTIMESTAMP);
