INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '경의선숲길에 이렇기 분위기 좋은 대형 카페가 있는지 오늘 처음 알았어요! 건물 전체가 호기심 카페더라구요. 감각적인 외관+층마다 다른 인테리어라 구경하는 재미도 있었어요. 커피는 고소, 상큼 중에 고를 수 있고 다양한 에스프레소 메뉴들도 있어요. 저는 커피랑 딸기라떼를 시켰는데 둘 다 맛있었답니다. 바스크치즈케이크 맛집 잘 없는데 오늘 찾았네요! 꾸덕꾸덕 맛있어요ㅠㅠ 잠시 일하기에도 너무 좋은 분위기였어요. 들리시면 꼭 모든 층 인테리어 구경해보시길 바라요. + 바로 밖은 경의선숲길인데 힐링되는 뷰랍니다. 통창으로 바깥 풍경 보시면서 힐링하실 분 호기심 카페 추천드려요. 저는 다음에 친구랑 경의선숲길 산책하다가 자주 들릴 예정이랍니다. 소금빵 매니아인데 맛있는 크랙 소금빵이 있어서 두개 포장해가용😊💖', 90, 15, 'GOOD', SYSTIMESTAMP);
