INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구들이랑 방문했는데 소문대로 인기가많아서그런지 디저트는 품절된게많았는데 다행이도 샤인머스캣 케이크남아있어서 먹었어용 너무꿀맛이고 주차도 가능하고 이주변에 이런 대형카페가 있었는지몰랐어요 또올거같아요 추천드려요👍', 1, 1, 'GOOD', SYSTIMESTAMP);
