INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '(협찬♡)이지만 솔직하게 뷰도 좋고 탁트인 전망과 편안한 자리에 하염없이 멍때리고픈 카페예요 휘낭시에도 겉바속촉 찐이고 음료도 맛있어서 평일에 연트럴파크의 풍경즐기기에 최고였습니다', 6, 3, 'GOOD', SYSTIMESTAMP);
