INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '일단 집 앞이라 너무 좋구요 엄마랑 왔는데 북적대지않고 아늑해요 음료와 디저트 또한 훌륭합니다 아늑하고 음악에도 신경을 엄청 쓰신 티가 나네요 너무 좋아요. 엄마랑 같이 왔는데 마음에 쏙 드신대요', 5, 1, 'GOOD', SYSTIMESTAMP);
