INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '서강대역카페 중에 가장 크고 쾌적한 곳입니다. 음료도 다양하고 가격도 착해서 좋았어요 카포카토 진짜 맛있으니 다들 한번씩 시도해보시길 카카오크림 아이스크림은 맛없을 수 없는 조합!! 휘낭시에도 종류별로 있어서 먹어보고싶은데 솔드아웃이라 담에 가서 먹어보러구여 쉬폰케이크도 달달하니 ㅇ맛맀습니다!!', 17, 6, 'GOOD', SYSTIMESTAMP);
