INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '디저트와 음료 모두 맛있고 분위기도 너무 좋아요! 카페가 총 4층 건물이어서 매우 넓고 쾌적하고, 작업하기도 좋습니다. 가장 좋은 점은 이렇게 맛있는 휘낭시에가 글루틴프리라는거! 소금빵도 넘 맛있었어요💛 앞으로 단골이 될 것 같아요오 ㅎㅎ', 50, 0, 'GOOD', SYSTIMESTAMP);
