INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '직원분 넘나 친절하시고 여기 티라미수 진짜 맛있어요 자연광 가득이라 사진도 잘나오고 3층은 공부하기에 좋고 2층은 얘기나누기 좋더라구요~ 나중에 휘낭시에랑 바스크케이크 먹으러 또 갈게요!', 99, 19, 'GOOD', SYSTIMESTAMP);
