INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '경의선숲길 새로 생긴 대형카페!!! 3층은 카공하기에도 잘되어있어 좋아요 조용하구 ㅎㅎㅎ 디저트랑 샌드위치, 핫미초 먹었는데 다 맛있구 달달하니 스트레스 싹 풀렸습니당 😆😆', 40, 6, 'GOOD', SYSTIMESTAMP);
