INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '빵순이지만 위랑 장이 약한 저는 요즘 글루텐프리 디저트에 관심이 많은데요. 신촌에 카페 호기심이라는 글루텐프리 디저트 카페가 있다고 해서 방문했어요. 근데 4층 규모 대형 카페라 쾌적하고 자리도 많아서 너무 좋더라구요. 층마다 다른 인테리어와 분위기도 인상적이였고, 아무래도 3-4층에는 학생 또는 직딩분들이 카공하거나 작업하기에도 딱 좋을 것 같더라구요. 게다가 맛있는 커피와 건강한 글루텐프리 디저트까지 ! 작업하면서 당 떨어질 때 디저트 먹어야되는데 글루텐프리라 양심도 챙길 수 있어요. (+휘낭시에 진짜 일반 휘낭시에 뺨칠 정도로 너무 맛있어요. 가신다면 꼭 드시길 ㅠ_ㅠ) 신촌, 경의선역 근처 카공하기 좋은 카페 찾으신다면 카페 호기심 너무 추천 드려요.', 42, 7, 'GOOD', SYSTIMESTAMP);
