INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '가는 길에 찍은 하늘 사진입니다 저 날 왕 추웟는데 카페 띠숩고 음료도 팩스어피치 티가 따숩고 맛낫어요ㅠㅠ 층별로 느낌 다른데 3층인가 2층이 노트북 하기 좋아서 사람이 꽉 차있었습니다ㅎㅎ', 15, 1, 'GOOD', SYSTIMESTAMP);
