INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '와 더위에 지친 몸과마음 편하게 쉬었습니다 밖에 나오기 싫었던 카페 4층까지 있는 신촌대형카페 샌드위치랑 소금빵, 휘낭시에 식사대용 베이커리부터 디저트까지~ 여기가 신촌의 중심이오', 9, 6, 'GOOD', SYSTIMESTAMP);
