INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '전면 통창이라 개방감이 너무 좋아요👍🏻 3,4층은 공부하기 좋고 2층은 대화하기 좋은거 같아요 커피도 디저트도 훌륭합니다:) 혼자 집중하고 싶을 때 종종 올 거 같아요', 21, 0, 'GOOD', SYSTIMESTAMP);
