INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '새로 오픈했다길래 방문했는데 기대했던 것보다 매장도 크고 깔끔해요! 샌드위치는 속도 알차고 빵도 쫄깃쫄깃 너무 맛있었습니다! 특히 저 크런치 초코휘낭시에는 앞으로도 계속 생각날 것 같아요 ㅎㅎ 또 하나의 브런치 맛집을 찾아낸 것 같아 기분이 좋네요^^ 아마 곧 유명해져서 오늘같은 여유로움은 못느끼겠지만 또 다시 방문할게요:)', 31, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '신촌역과 서강대 즈음에 분위기 좋고 조용한 카페가 생겼네요!! 건물 전체가 카페고 1층부터 4층별로 분위기도 달라서 인테리어보는 재미도 있어요!! 조용한층도 있어서 책읽거나 공부하기 딱 좋은거 같아요🥰 글루텐프리 베이커리 디저트와 샌드위치, 맛있는 음료 메뉴도 많아요👍🏻 브런치 모임하기도 좋아보여요~ 신촌역 호기심카페 추천이요👏🏻', 129, 21, 'GOOD', SYSTIMESTAMP);
