INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '지나는 길에 주차도 되고 깔끔한 외관이라 급방문했어요~ 직원분들 친절하시고 특히 휘낭시에가 맛나네요~ 집이랑은 거리가 있지만 또 지나는 길이면 방문해보겠어요~^^', 16, 1, 'GOOD', SYSTIMESTAMP);
