INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '카공을 자주 하는데 분위기가 좋으면 베이커리나 음료가 아쉽거나 베이커리가 맛있으면 분위기가 아쉬운데 여긴 둘 다 잡은 곳이네요..! 찐으로 자주 올 것 같은 카페예요ㅎㅎ', 60, 18, 'GOOD', SYSTIMESTAMP);
