INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '카페 인테리어도 너무 유닉하고 희낭시에도 글루텐프리여서 편안하게 너무 잘 먹었습니다. 커피도 직접 로스팅해서 그런지 고소하고 너무 맛있었습니다!', 49, 0, 'GOOD', SYSTIMESTAMP);
