INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '대형카페라서 자리도 많고 스터디카페처럼 카공 하시는 분들도 많았습니다 조용하고 층마다 분위기 달라서 너무 좋았던곳 …❤️ 구움과자와 제과류도 다 맛있으니깐 빙문해보세용', 37, 1, 'GOOD', SYSTIMESTAMP);
