INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '경의선숲길 산책하면서 인테리어도 넘 멋져서 꼭 와보고싶었던곳!!! 드뎌 친구랑 아점먹고 수다떨겸왔어요 ㅎㅎ 샌드위치두 음료도 깔끔하게 맛있고 무엇보다 너무 편안했던 카페ㅠㅠㅠ 인테리어 많이 신경쓰신게 느껴지고 의자도 넘넘 편하고 오전에오니 사람도 많이 없어서!!! 4층에서 뷰 보면서 편안하게 쉬다갈수있었오용ㅎㅎ 자주오고싶은..!', 13, 6, 'GOOD', SYSTIMESTAMP);
