INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '인테리어도 너무 예쁘고 창문 너머로 작은 공원이 있어서 푸릇푸릇한 뷰까지 갖춘 카페에요!! 글루텐 프리여도 맛있는 바스크 치즈케이크랑 휘낭시에(종류엄청많움) 외에도 다양한 페스트리와 디저트가 있는데다 커피도 맛있습니다! 샌드위치도 있어서 브런치카페로도 제격이에요 추천합니다 :)', 2, 10, 'GOOD', SYSTIMESTAMP);
