INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '오랜만에 분위기좋은 카페 찾아왔는데 2층 3층도 있는 대형카페라서 더 좋았어요!! 잠봉뵈르 샌드위치 맛있구 오미자에이드 신기해서 시켜봤는데 상콤하니 짱존맛임🩷🤍 아메리카노는 고소해서 맛있어요 잠봉뵈르에 피클도 나오는데 작아서 기엽당 했지만 얘가 치트키예요 같이 먹으니까 잘어울리네요 서강대역 바로 옆에 있어서 오기도 편하고 나중에 또 들릴 일 있으면 오려규요!', 40, 5, 'GOOD', SYSTIMESTAMP);
