INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '층마다 주는 분위기가 좋아요~ 커피도 맛있고 디저트도 맛있어요🤍  작업하기도 좋고 데이트 하러 오기도 좋은 공간 !! 잠봉뵈르 샌드 먹어보고싶었는데 다음에 와서 먹어보려구용 또올게요', 14, 1, 'GOOD', SYSTIMESTAMP);
