INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '호기심에 호기심에 왔다. 메뉴1: 클래식 휘낭시에 메뉴2: 크랙 소금빵 메뉴3: 레몬 케이크 추가: 아이스 아메리카노(디카페인) #휘낭시에 단단하면서도 쫄깃한 식감의 겉면과 폭신하고 깊은 단 맛의 속 #크랙소금빵 얇고 바삭한 겉면과 촉촉하고 고소한 속 - 치즈가 있는 듯 #레몬케이크 연한 단 맛을 주는 코팅과 상큼한 레몬향의 속 - @oz.d.ls -', 44, 7, 'GOOD', SYSTIMESTAMP);
