INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '신촌 홍대 넓고 쾌적한 대형 디저트카페입니다. 신촌에 이렇게 큰 카페가 생기다니!! 규모가 큰데 엘베가 있어서 이동하기 편하구요. 사람이 많긴 한데 은근 조용한 분위기에요.👍 커피랑 녹차라떼, 디저트 모두 맛있어서 더 만족입니다😋 커피원두 취향껏 고를 수 있고, 디저트 메뉴 종류도 많아요. 바스크 치즈케이크가 입에서 살살 녹구요. 휘낭시에도 겉바속촉으로 잘 구워졌더라구요. 달콤한 디저트랑 커피 먹으면서 편하게 쉬기 좋았습니다.🥰', 71, 14, 'GOOD', SYSTIMESTAMP);
