INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '서강대역쪽에 새로 생긴 엘베 있는 대형카페! 잠봉뵈르 샌드위치 한끼로 든든하고 바로 앞 공원뷰라서 답답하지 않고 좋아요 2층은 호텔 로비 분위기 고급스러웠어요 3층은 창문뷰쪽으로 1인석이 많아서 혼자 공부하는 분들도 많았고 대화하는 분도 있고 바로 옆 신촌연세병원이고 카페 건물에 주차도 가능하다니..신촌에서 주차라니 너무 좋아요', 7, 5, 'GOOD', SYSTIMESTAMP);
