INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '서강대역 나오자마자 4층 건물로되어있는 카페인데 글루텐 프리 디저트들로 구성되어있어서 건강하고 너무 맛있어요 인테리어도 깔금하고 직원분들도 정말 친절하게 응대해주셔서 기분이 좋아지네요 경의선숲길도 바로 앞이라 먹고 걷기 최고🙏', 121, 23, 'GOOD', SYSTIMESTAMP);
