INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '글루텐 프리 디저트를 파는 대형카페라니!!! 이런 곳 알게되어서 너무 좋네요 인테리어도 멋지고 뷰도 예뻐서 모임하기 좋을 거 같아요 글루텐프리 휘낭시에인데 맛까지 좋네요💖', 1, 4, 'GOOD', SYSTIMESTAMP);
