INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '오픈 후 애정하게 된 카페여서 자주 들리고 있어요. 커피도 맛있고 디저트도 훌륭합니다! 공간도 편안하고 힐링을 줘서 집이 바로 앞인데 여기서 노트북을 꼭 하고 싶어요 ㅋㅋ', 20, 6, 'GOOD', SYSTIMESTAMP);
