INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매장도 넓고 쾌적하고 좋고 친절하시고..💓 디저트랑 음료가 진짜 맛있어요..ㅎㅎㅎㅎ 미초라는건 처음 먹어봤는데 미숫가루+초코 조합인데 오묘하니 맛있어요ㅋㅋㅋㅋ남자친구는 최근에 마셔본 음료중에 제일 맛있대요', 53, 11, 'GOOD', SYSTIMESTAMP);
