INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '서강대역 카페 호기심 추천합니다! 공간도 넓고 쾌적해서 오래 머물기 좋은 공간이었고 음료와 디저트 모두 너무 맛났습니다 조용하고 뷰도 좋아서 카공할때 좋은 카페라 재방문 의사 있습니다 추천합니다 ㅎㅎ', 416, 39, 'GOOD', SYSTIMESTAMP);
