INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '#휘낭시에 시나몬, 카라멜 겉바쫄속촉 쌀가루 휘낭시에 #레몬케이크 산뜻한 레몬향의 폭신촉촉 케이크 #아메리카노 아이스, 상큼 순한 맛의 아아', 13, 9, 'GOOD', SYSTIMESTAMP);
