INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '통창으로 숲 뷰가 보이는 서강대 대형카페🌳 건너편 경의선 숲 뷰와 마포 일대의 광경을 바라보기 좋고 4층까지 있어서 앉을 공간도 많아요 로스터리 겸 베이커리 전문 카페로 이용되며 세 가지 원두의 커피와 쉬폰케이크, 소금빵샌드위치 등 먹을거리도 다양했습니다😁', 46, 2, 'GOOD', SYSTIMESTAMP);
