INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아이스라떼 녹진하고~ 신맛 없어서 좋네요~👍👍👍 휘밍시에 녹진한 맛이라 아메리와 라떼가 어율리는~ 직원분도 친절하시고~ 주말엔 브런치로 샌듸치랑 먹기에도 좋고 산책길에 있으니 다~ 좋네요', 77, 13, 'GOOD', SYSTIMESTAMP);
