INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '일단 뷰가 탁트여서 너무 좋구요,,, 도심 속 힐링 공간이예요!!!!! 커피도 생각보다 맛있어서 놀랐고, 샌드위치두 재료 한가득 양도 혜자예요🥹🥹 구움과자 선물 포장용으로도 제격입니다!! 휘낭시에 쫀맛🫶🏻🫶🏻 한적하고 차분한 분위기라 노트북 작업하기도 좋구 혼자 책 읽으러 와도 너무 행복할 것 같은 곳이예요. 동네에 이런 곳이 생기다니!!!! 자주 올 것 같습니다💘🔥💘', 83, 16, 'GOOD', SYSTIMESTAMP);
