INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '서강대역 신상카페 호기심 저장해뒀다가 다녀왔어요 2-3층 공간이 다른 컨셉으로 원하는 느낌따라 앉아서 조용히 시간 보내기 좋을 것 같아요 한산한 시간대에 방문하면 좋을듯 합니다 이색적인 시즌메뉴 음료도 맛있고 응대도 친절해서 신촌쪽 올 일 있으면 재방문 할 것 같아요:)', 17, 0, 'GOOD', SYSTIMESTAMP);
