INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '2주 동안 3번이나 올 정도로 공간도 커피도 완벽한 곳이에요🥹 할일 할때마다 오는데 집중도 잘되고, 음료까지 맛있어서 행복하게 있다가 갑니다...!! 앞으로도 자주 방문할게요 ㅎㅎ', 50, 3, 'GOOD', SYSTIMESTAMP);
