INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '커피도 맛있고, 웬만한 베이커리 전문점보다 빵 종류가 더 맛있어요. 빵이 냉장이 아니라 실온으로 바로바로 소진하는 듯 한데, 그래서 되게 빠작해요🥐 빠작빠작', 21, 8, 'GOOD', SYSTIMESTAMP);
