INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '신촌 휘낭시에 맛집입니다 제가 운래 휘낭시에를 좋아하는퍈은 아닌데 여긴 진짜 제대로네요 심지어 글루텐프리인데 맛있습니다 후기 길게 안남기는데 여긴 찐이라 남겨봅니다 !', 53, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '인테리어도 너무 예쁘고 분위기도 좋아서 신촌 데이트하고 좋은 카페갔습니다! 잠봉뵈르 샌드위치도 정말 맛있었어요! 나중에는 소금빵 먹으러 와보고 싶네요 :) 음료도 두개 모두 맛있습니당  인테리어와 음식 모두 만족스러운 카페네요!', 50, 1, 'GOOD', SYSTIMESTAMP);
