INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '신상카페  카페 이름부터 호감이 가네요   계란샌드위치  크래미샌트위치 소금빵 커피 모두 맛있네요 좌석도 편하고  조용하고  좋네요~~^^♡♡♡', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '주차도 가능한 카페 찾다가 발견했는데 4층짜리 카페라 넓고 분위기도 좋아요! 커피도 휘낭시에도 맛있구 뷰도 좋아서 단골각이에요💚 콘센트 있어서 노트북하기도 좋구, 주말이라 사람 많은데 평일엔 여유롭게 즐기기 좋을것 같아요😊', 8, 1, 'GOOD', SYSTIMESTAMP);
