INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '4층규모에 인테리어가 넘 멋있어서 시외에 있는 분위기 맛집 카페에 놀러온 기분ㅋ.ㅋ 그리고 아메리카노 정말 맛있습니다!!❤️완전 찐하고 고소한 고급 원두의 맛!! 4층에 갔더니 대형 로스터기로 직접 로스팅하고 계시더라구요! 카포카토도 풍미가 훌륭한 아이스크림을 떠먹다보면 아래쪽에는 깊고 진한 에스프레소가 있어서 대박 맛있어요.....❤️ 휘낭시에도 비주얼이 넘 좋아서 집에 포장해갔는데 요게 쌀가루로 만들어서 글루텐 프리래요!!❤️ 지하 1층을 통쨰로 빵을 만드는 장소로 쓰고 있을만큼 베이커리, 디저트에 진심인 카페답게 휘낭시에너무 맛있습니다! 층마다 엘리베이터로 이동 가능하고 모든 층이 통창이에용 서강대 카페중에 가장 넓고 뷰가 좋아서 스터디하기에도 딱 좋았습니다!', 3, 5, 'GOOD', SYSTIMESTAMP);
