INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '집앞에 새로생긴 카페인데 인테리어도 이쁘고 커피도 디저트도 맛있어요 직원분들도 친절하시고.. 산책하다 들려서 맛있는거 먹고 쉬다가기 좋은 곳이에요', 19, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '일단 디저트! 특히 휘낭시에 너무너머너무 맛있습니다☺️♥️ 카공을 워낙 좋아하는데 창문도 크고 뷰도 좋은데다가 음악도 잔잔해서 분위기가 너무 조아용🥺 그리고!! 이렇게 일찍 여는 카페가 잘 없는데 8시에 열어서 더더 좋은 것 같네용☺️', 121, 21, 'GOOD', SYSTIMESTAMP);
