INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '호기심 카페 근처에 살다가 너뮤 이뻐보여서 카공하러 왔는데 잔잔한 분위기에 경치가 진짜 이뻐요! 공간 자체가 넓다보니가 자리잡기도 편했어요! 카공하기 진짜 좋은 것 같아요!', 32, 7, 'GOOD', SYSTIMESTAMP);
