INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '어제 첫 방문 후 두번째 방문입니다. 이런 카페가 생겨서 너무 좋으네요~~ 베이커리류들 완전 고급지고 글루텐 프리입니다. 어제 마신 오미자도 맛있고요. 아아 아라 모두 맛납니다!! 어제 서비스로 주신 소금빵은 단연 엄지척이고👍👍', 125, 25, 'GOOD', SYSTIMESTAMP);
