INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '매장이 꽤 넓은데 분위기가 좋아요 !! 음악도 잔잔하니 좋구요 :) 아메리카노 고소하니 맛있고, 얼그레이 밀크티도 맛있어요 !! 혼자 와서 집중하기도 좋고 사람들과 함께 와서 이야기 나누기더 좋네요 ㅎㅎ', 48, 8, 'GOOD', SYSTIMESTAMP);
