INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '한산한 주변 거리에 다소곳이 솟은 건물. 입장했을 때부터 마음에 들었습니다. 2층이 인테리어가 인상적이었지만  빈 자리는 3층이 많아서 3층에 자리했습니다. 스트로베리라떼는 제겐 달지 않아 좋지만 풍부한 풍미는 없었어요. 베리 함량이 더 높았으면 좋겠어요. 장봉뵈르는 버터가 많아서 목에 쏙 삼켜져서 좋았네요. 그런데 잠봉이 조금만 더 있었으면 합니다. 카페이지만 제가 저녁이라 커피를 란 마셔서 카페로서 가진 진면목을 발견하지 못했습니다. 다음 방문 때는 커피를 꼭 먹어봐야겠어요. 근데 초코휘낭시에는 정말 맛았네요.', 45, 5, NULL, SYSTIMESTAMP);
