INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '음료가 너무 정성스럽고 맛이 부드러워요 달지않게 조절도 가능해서 좋았어요 휘낭시에도 쑥맛나는 새로움을 즐기고왔어요 등받이 의자가 좀 불편하긴해도 분위기도 편안했어요', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '신촌에 힙한 카페가 들어왔다고 해서 와봤는뎀 공간이 아주 나이스하구 쾌적해용 그리구 커피랑 디저트도 맛있어서 자주 올거 같아욤🫶🏻', 179, 34, 'GOOD', SYSTIMESTAMP);
