INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '이번이 두번째 방문인데 4층에 여러명이 앉을 수 있는 공간도 열려서 너무 좋았어요. 공간 자체가 너무 쾌적하고 조용해서 공부하기도 대화하기도 좋아요! 디저트도 맛있고, 가격 대비 퀄리티도 너무 좋네요 사장님도 항상 친절하게 대해주셔서 다른 곳 갈까 하다가도 오게 되는 곳입니다. 학생분들 많이 오셔서 대박났으면 좋겠어요', 25, 6, 'GOOD', SYSTIMESTAMP);
