INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '휘낭시에 먹고싶어서 방문했는데, 인기있는 맛은 품절이라 아쉬웠어요 ㅠㅡㅠ 다음에 다시 방문해서 꼭 먹어보려구요! 카공 목적으로 방문했는데, 3층 자리도 넒고 조용해서 좋았어요.!!', 24, 6, NULL, SYSTIMESTAMP);
