INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '숲길 지나칠 때마다 새로 생긴 카페라 궁금했는데 넘 좋아요!!  휘낭시에 종류도 다양하고 친절하시고 커피 원두도 다양해요!! 숲길 올 때마다 올게용🤭', 3, 0, 'GOOD', SYSTIMESTAMP);
