INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '매장인테리어가 너무 감각적이고깨끗해요 뷰도 대박적👍🏻 역 바로근처여서 접근성도 너무좋고 맛도 있어서 자주방문하고싶은 곳이예요오ㅎㅎㅎ', 14, 2, 'GOOD', SYSTIMESTAMP);
