INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '앞전에 밤 늦게 갔어요 가오픈기간 사장님? 으로 보이는분께서 휘낭시에 맛보라고 줬어요 존맛탱쫀둑꾸두닥꾸덕대존맛 그래서 사러 갔어요 너무 좋다 ❤️🧡💛💚💙💜', 3, 2, 'GOOD', SYSTIMESTAMP);
