INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '인테리어도 너무 멋지고, 커피랑 치즈케이크도 맛있는 카페랍니다 ㅎ 서강대역앞에 이렇게 넓고 멋진카페가 있는줄 몰랐어요 ^  친절한 직원분도 기분좋았던 곳, 추천해봅니다', 76, 12, 'GOOD', SYSTIMESTAMP);
