INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '서강대역 2번출구 앞에 새로 생긴 카페여서 와봤는데 베이커리도 모두 직접 만드신다고 하네요 디저트말고 샌드위치류도 있어서 식사대용으로도 좋습니다. 분위기도 좋고 뷰도 좋고 맛도 있고 사장님도 친절하시고 모두 완벽!🤟🏻', 27, 4, 'GOOD', SYSTIMESTAMP);
