INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '새로 생긴 카페가 있어서 와봤는데 너무 좋아서 단골될거같아요 :) 공간도 크고 넓고, 공간이 분리되어있어서 좋아요 채광잘들어서 더더더좋아요', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '동네 주민인데요 ㅎㅎ 혼자 카페 가는걸 좋아해서 이 동네 카페는 거의 다 가봤어요. 조용하고, 뷰가 트여있고, 커피랑 디저트가 맛있는곳을 좋아하는데 요기가 마음에 쏙 듭니다. 자주 올것 같아요. 테마를 제주도 현무암으로 잡으셨다고 잠깐 사장님이 얘기해주셨어요. 호기심 로고도 감각있고 보기 좋았습니다. 경의선 숲길 바로 앞이라 나무도 보이고, 하늘도 너무 잘보여요. 휘낭시에, 소금빵 다 맛있고, 커피도 조금 특이한 매뉴가 있어서 좋았어요 🥰 자주 올게요 ㅎㅎ 번창하세요', 26, 3, 'GOOD', SYSTIMESTAMP);
