INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '분위기가 너무 좋아요 편안하고 깨끗하고 인텔어도 깔끔하게 잘 되어있어요 에어컨도 시원하구 화장실두 깨끗하구 몰렀는데 매장도 넓네요 4층까지 있는데 사람 많아요!! 경숲길 중앙에 이런 카페 생겨서 좋아용 음료도 새로운 느낌인 것들도 많아서 하나하나 먹어보고 싶어요. 빵도 맛있어보이는데 15시쯤 왔더니 많이 팔렸네요!! 잘먹었습니다~~', 42, 0, 'GOOD', SYSTIMESTAMP);
