INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '직접 만들고 직접 로스팅한 베이커리와 커피여서 그런지 너무 맛있었어요~ 오픈이벤트 덕분이 더 좋았고 통창뷰가 너무 멋있었어요! 비오는 날 노트북 들고 방문 하고 싶어지는 곳이에요~', 21, 1, 'GOOD', SYSTIMESTAMP);
