INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '엄청 세련되고 통창에 앉아있기 딱입니당 커피 원두 정말 맛있어요 ㅎㅎ 만약에 집 근처라면 자주 오고 싶어지는 그런 카페 맛집입니당 ㅎㅎ', 45, 10, 'GOOD', SYSTIMESTAMP);
