INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '오픈하기 기다렸다가 처음 방문해보았는데 커피도 제가 좋아하는 진한 맛이고, 무엇보다 빵이 정말 맛있어요! 소금빵이랑 휘낭시에 모두 다시 먹어보고 싶은 맛이었어요~ 테이블 간격도 넓어서 쾌적한 분위기라 근처에 온다면  방문 추천드립니다!!', 20, 6, 'GOOD', SYSTIMESTAMP);
