INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '맛 위치 청결도 등에서 완벽한 카페!! 정말 좋아하는 곳이에요. 다만 요새 아쉬운건, 장사가 잘되면서 새로운 알바분들이 들어오시고, 그래서 그런지 매장 관리가 잘 안되는 느낌이에요ㅠ 사장님께서 리뷰를 보실진 모르겠지만 카페 광팬으로서 아쉬워서 남겨봅니다. 오픈 초반엔 음악, 온도관리등까지 완벽했는데 요새는 너무 시끄러운 음악을 볼륨 조절 없이 너무 크게 튼다던가, 더울땐 에어컨을 안틀고, 추운데 에어컨을 트는 등 매장관리가 잘 안되는 느낌이에요 😭 알바생분들도 미숙해서 주문실수, 누락이 잦고요… 하지만 여전히 맛은 좋고 다들 친절하십니다!!', 107, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '매장이 넓고 커서 너무 좋아요 뷰도 좋습니다 그리고 샌드위치 디저트 등 글루텐프리 디저트까지 있어서 너무 좋아요! 수박주스까지 있어 시원하게 즐길 수 있습니다', 9, 0, 'GOOD', SYSTIMESTAMP);
