INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '매장이 넓고 노트북 하기에도 괜찮은 카페예요! 이렇게 괜찮은 카페가 집 주변에 있었다니 자주 방문하고 싶습니다✨🥹 커피도 맛있고 디저트도 종류별로 많아서 너무 마음에 드는 곳이예요~', 49, 0, 'GOOD', SYSTIMESTAMP);
