INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '디저트도 인기 많아서 퇴근하자마자 가도 품절된 상품도 많고 인테리어도 1층부터 4층까지 각층마다  색 부터 가구,바닥까지  다다르게 예쁘게 꾸며놓아서 다 올라가봤어요~!~!', 29, 7, 'GOOD', SYSTIMESTAMP);
