INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '서강대 근처에서 디저트 선물할 일이 있어서 포장 이용했어요. 카페가 엄청 크고 깔끔하고 분위기도 좋습니다. 예쁘고 맛있는 휘낭시에 선물할 수 있어 좋아요. 다음에도 선물할 일 있으면 또 방문하고 싶고, 여유있게 들러 커피 즐기고 싶은 멋진 카페입니다. 직원분들도 다 친절하세요!', 116, 21, 'GOOD', SYSTIMESTAMP);
