INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '음료랑 소금빵이 너뮤넘무너무맛있어요 인테리어도 예쁘고 통창이라 사진도 잘나와요 오늘 한 일 중에 제일 잘한건 여기 카페를 온 것 !', 48, 8, 'GOOD', SYSTIMESTAMP);
