INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '휘낭시에 맛있어요‼️‼️‼️ 서강대역 바로 앞에 카페가 새로 생겨서 와봤어요 창가에 노트북 자리도 따로 있고 조용해서 4층 건물 대형 카페인데다가 조용해서 대화하기도 좋네요', 31, 9, 'GOOD', SYSTIMESTAMP);
