INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '집 앞에 생긴 카페 커피맛, 분위기, 친절함 뭐 하나 빠질 거 없어요 커피 한모금 먹고 고소한 풍미에 눈이 동그래졌어요 0.0 인테리어도 하나하나 신경쓴 티가 파파박 나고 오면 기분 좋아지는 카페가 집앞에 있어서 정말 좋아요 자주 자주 올게요!!', 57, 17, 'GOOD', SYSTIMESTAMP);
