INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '연남동가면 무조건 먹는다 품절아닌이상ㅎ 생타로버블밀크 찐짜맛있음 뭐라 설명해야하지 우유에 버블이랑 고구마랑ㅎ 고구마같기도하고 마 같기도 하구 여튼 먹어봐야 함 아 근데 많이 재고를 놓는거같지않아서 나만먹고싶음 ㅎ킼키킿ㅎㅎ', 38, 4, 'GOOD', SYSTIMESTAMP);
