INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '원래 밀크티 버블티 안 좋아했는데 여기 접한 후로 입트여서 1일 1버블티 하고싶어졌음,,ㅠ 연남동 올 때 마다 기회되면 마심ㅎ 그 날이 오늘^^! (당도100이 젤 맛있음ㅎ)', 10, 2, 'GOOD', SYSTIMESTAMP);
