INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '찐 밀크티맛인거같은데 ㅠㅠ 너무 입맛에 안맞아요...두유맛 당도는 꼭 50프로 이상넣어서 먹어야할듯요 그리고 제조시간도 오래걸리고... 위생이 별로에요...ㅠ', 61, 15, 'BAD', SYSTIMESTAMP);
