INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '본토의 맛에 매우 근접한 밀크티 입니다 근데 그 본토가 중국인지 홍콩인지 대만인지는 비밀 얼른 코로롱 잡고 여행 가고 싶다 😢', 25, 5, 'GOOD', SYSTIMESTAMP);
