INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '사워도우랩 잡곡통밀빵 올리브빵=아침의 낙❤️ 잡곡 통밀빵은 담백 구수하게 맛있고 올리브빵은 적당히 짭짤하고 산미도 좋아서 그냥 먹어도 올리브 오일 찍어 먹어도 맛있어요🥖', 124, 22, 'GOOD', SYSTIMESTAMP);
