INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '사워도우 랩 = 플레인 사워도우 맛집!!! 다른 빵들도 맛있지만 플레인 사워도우가 최애입니다😇 사실 처음에 브레이크타임이 있어서 흠..스러웠는데 먹어보고 바로 생각을 바꿨답니다 따흐흑 넘 맛있어요💖', 63, 17, 'GOOD', SYSTIMESTAMP);
