INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '오픈토스트로 먹기좋은 사워도우 찾고 있었는데 사워도우 중 베스트가 될 것같아요. 플레인이 오픈토스트에 쓰기 좋겠지만 사워도우의 산미 좋아하지 않는다면 고구마 사워도우가 좋은 선택?! 고구마가 꽤 많이 들어있는데 고구마가 부드럽고 달달해서 산미가 덜 느껴지는듯.. 통밀의 구수한 향이 좋았고 산미가 은은하면서 속도 부드러워서 더 먹기 좋았어요. 여러가지 재료로 오픈토스트 만드는 재미도 생길 것같아요.', 84, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '빵 정말 맛있어요! 사워 도우 좋아하는데 집 근처에 파는 곳이 없어서 여기 저기에서 사 먹어 보고 있어요. 근래에 먹은 사워 도우 중 독보적이에요👍 11시반쯤 갔는데 포카치아는 안보였고 플레인, 통밀 사워도우 사왔어요.', 45, 2, 'GOOD', SYSTIMESTAMP);
