INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '식단 때문에 건강한 통밀빵집 찾다 발견 매장에서 먹는 건 불가능 무조건 픽업 빵도 아주 큼직하고 통밀 좋아 하는 분들은 딱일 것 같다! 계란 올려서 먹어 보고 뭐 요거트도 올려서 먹어 봤는데 너무 잘 어울림! 식단 하는 동안은 종종 갈 것 같다!!👍🏻👍🏻👍🏻', 28, 4, 'GOOD', SYSTIMESTAMP);
