INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '제주도 컨셉으로 다양한 음료와 차를 파는 공간입니다. 먼저 정말 제주도스럽게 꾸며놓고 특이한 인테리어가 가장 눈에 띄었어요! 차세트 하나와 제주햇살스무디를 시켰는데 음료도 너무 맛있고 차세트는 다과와 함께 나와서 좋았습니다. 다만 공간적으로 느낌을 주려고 하니 막상 앉을만한 곳은 그렇게 많아보이지는 않았네요. 그래도 포토존도 있고 인테리어가 너무 예뻐서 잘 구경하면서 쉬고 왔습니다~', 29, 3, 'GOOD', SYSTIMESTAMP);
