INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '3월 한달동안 방탈출과 카페를 함께 즐길 수 있다구요?! 소문을 듣고 홍대 온김에 당일 예약해서 방문했습니다! 카페 지하1층이 진짜 펍처럼 아늑하게 꾸며져있어서 기똥차더라구요. 신기했습니다!! 다음에도 카페만 즐기러 올 법한 것 같습니다. 잘 먹었숩니다~~~ 개인적인 추천메뉴 : 제주초당옥수수 아이스크림!', 5, 5, 'GOOD', SYSTIMESTAMP);
