INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '제주 컨셉의 카페에요! 일단 넓고 내부 인테리어도 너무 예뻐서 좋았어요 ㅎㅎㅎ 직원분들도 친절하시구 제가 시킨 라떼 (시그니처 라떼인데 이름이 기억 안 남) 도 맛있었습니당~~! 2 층까지 있어서 넓어서 홍대에서 놀다가 가기 좋아요 웨이팅 없었구 자리 많았어요 돌하르방 디저트는 양갱이었어요!! 추천합니당', 13, 3, 'GOOD', SYSTIMESTAMP);
