INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '우연히 열려있는 카페를 찾은건데, 너무 맛있고 분위기도 좋아서 다음에 또 오려구 저장해놨어요 ◡̈ 그리고 티세트랑 귤빛찬란 추천합니다 ~~ 티백도 사가려구요~', 21, 7, NULL, SYSTIMESTAMP);
