INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '평소에 방탈출을 좋아하는데 카페에 방탈출이 있다고해서 궁금해서 방문했어요~ 다른 방탈출과 비슷한 퀄리티에 저렴한 가격으로 이용할 수 있어서 데이트 장소로 딱이에요!☺️ 제주도 컨셉으로 이루어진 내부 인테리어가 깔끔하고 제주 초당 옥수수 아이스크림과 푸딩이 너무 맛있었어요!! 추천!!!🥰', 2, 5, 'GOOD', SYSTIMESTAMP);
