INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '음료랑 디저트가 정말 맛있고 제주도 컨셉도 충실해서 너무 예쁘고 앉아만 있어도 좋은 카페입니다! 방탈출도 정말 재미있고 막히면 힌트도 있어서 기분 좋게 즐기기 좋았습니다. 매우 추천합니다😄', 31, 1, 'GOOD', SYSTIMESTAMP);
