INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '예약한 시간보다 일찍 도착했는데도 친절하게 맞아주셔서 감사했어요😍☺️😍 카페에서 놀다가 방탈출 예약한 시간에 맞게 할 수도 있고 서비스 뽑기도 하고 넘넘 잼있었습니다! 방탈출도 생각보다 퀄리티가 좋아서 기억에 남아요ㅋㅋㅋㅋ 근처에 오면 또 재방문의사 있구요, 친구 끌고 올만 합니다! 추천!', 68, 12, 'GOOD', SYSTIMESTAMP);
