INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), 'ᴍ ᴇ ɴ ᴜ 코지밀크티(★7900) + 곶자왈크림라떼(7900) + 귤빛찬란(8500) // 코지밀크티 라벤더 향 진짜 향긋하고 최근 먹은 밀크티 중에 제일 맛있었어요ㅠㅠ 강추,, 그리고 귤빛찬란! 위에 올라가 있는 귤이 건조(?)귤이라 부셔서 먹는 건데 진짜 질감이 신기해요.. 상큼하고 부담없이 먹을 수 있는 디저트였습니다아 매장 트리 정말 크고 예뻐요', 2, 9, 'GOOD', SYSTIMESTAMP);
