INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '트리와 함께 사진을 찍고싶어 방문했습니다 생각보다 사람이 없었고, 지인들도 모르는 곳이라고 하더라고요 그래서 여러 사람들에게 트리 이쁜 곳이라고 홍보를 ㅋㅋㅋㅋㅋ 눈이 왔던 날이라 혹시나하고 갔는데 너무 이쁜 사진들 찍을 수 있어서 좋았습니다 음료도 맛있어요 추워서 따듯한 차를 시켰는데 달달하니 좋더라고요 다음에도 눈 오는 날 낮에 방문해서 다른 느낌의 사진이 찍고싶네요 ☺️ ※사진 도용, 불펌 금지입니다※', 37, 6, 'GOOD', SYSTIMESTAMP);
