INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '조카가 방학이라 홍대나들이 나왔다가 디저트 맛집이라 소문 났다며 온 삼다코지 카페예요 인테리어도 제주도 느낌물씬 나고 디저트들은 다 예술작품처럼 먹기 아까울 정도로 멋지더라구요 커피도 기대이상에 맛이라 모처럼 힐링받았어요', 44, 8, 'GOOD', SYSTIMESTAMP);
