INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '제주 바다에 버려지는 부표를 모티브로 삼다수 병뚜껑과 플라스틱으로 만든 키링 체험 미디어 전시와 함께 아이들과 함께 오면 넘 좋은 전시 입니다 제주 음료를 맛 볼 수 있어서 그 부분도 좋아요 곶자왈 라떼 맛있네요', 8, 1, 'GOOD', SYSTIMESTAMP);
