INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '건물 자체가 굉장히 넓은데, 각 층의 군데군데마다 다른 느낌으로 구성을 잘 해놔서 너무 좋았어요. 그렇다고 정신 없거나 산만한 느낌이 아니라 신경을 정말 많이 쓴 것 같았습니다! 그리고 말차라떼 존맛탱! 디저트들도 너무 예쁘고 각각 스토리가 있어서 다 먹어보고 싶었어요. 연말이라고 대형 트리를 밖에 설치해두셨는데 너무 예쁘더라구요 또 방문하고 싶은 곳이었어요', 111, 21, 'GOOD', SYSTIMESTAMP);
