INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '카페가 추구하는 바가 확연히 보이는 곳이였어요 ! 겨울에 잘 어울리는 크고 예쁜 트리도 좋았고 각 음료마다 맛있게 마시는 방법과 소개글이 담긴 종이도 주셔서 즐거웠습니다 :>', 53, 11, 'GOOD', SYSTIMESTAMP);
