INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '돌고돌아자원순환 기획을 통해 다양한 모습으로 우리 주변에서 가깝게 접할 수 있다는 것을 알게 되는 계기가 되었다. 삼다수 삼다코지에서 마련한 이번 이벤트를 통해 리사이클링으로 키링 만드는 체험(무료)과 함께 크리스마스 분위기 물씬 풍기는 곳에서 특별한 시간을 갖게 해 준 삼다수ㆍ삼다코지 관계자 여러분 감사합니다.👍😍', 38, 9, 'GOOD', SYSTIMESTAMP);
