INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '키링이벤트가 떠서  만들겸 카페에 방문했어요 진원분들도 친절하시구 컨셉도 독특해요  음료랑 디저트도 제주도 컨셎에 맞고 맛있어요~  음료에 사용하는물과얼음은 삼담수 사용한다고 해서 신기해여', 8, 4, 'GOOD', SYSTIMESTAMP);
