INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '초당옥수수 크림라떼 개미쳤어요🤭 진짜 너무 너무 맛있어서 싹싹 긁어먹었습니다. 이 작은 게 7900원이라니 비싼데도 매일매일 먹고 싶어요. 삼다코지 지금까지 3-4번 정도 방문했는데 제일 맛있었어요. 남자친구 먹이고 싶어요😘', 33, 1, 'GOOD', SYSTIMESTAMP);
