INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '초당옥수수푸딩, 제주햇살스무디, 귤빛찬란, 곶자왈크림 라떼 먹었는데 하나같이 독특한 향과 맛과 식감이어서 맛있었습니다! 비주얼도 너무 예쁘고요 ㅎㅎ 다음에 꼭 다시 올거에요!!', 87, 12, 'GOOD', SYSTIMESTAMP);
