INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '여러가지 환경 관련 체험을 많이 해봤는데 아이가 되게 재밋어했어요 원하는대로 만들수있고 빨리 진행이 되고 맛있는 후식도 먹으니 최고라고 하네요! 카페 이용하는 좌석이 많이 없는 점이 조금 아쉽긴 하지만 도심에서 아이와 환경 체험을 할 수 있어소 좋았어요 다음에도 또 했으면 좋겠어요', 76, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '많이 기대하고 갔던 카페인데, 옥수수 아이스크림이 생각하고 갔던것보다 너무 적었습니다.. 다른 리뷰들보면 탑처럼 쌓아올려주기도 하는것 같던데 알바생들마다 스타일이 다르겠지만, 어느정도 균형은 맞춰주셔야 할거같아요.. 편하게 앉을 테이블도 별로 없었고, 여자화장실은 휴지가 없다니까 다른층 화장실가라고 말씀하시고 여러모로 아쉬웠습니다 근처에 살면 올수도있겠지만, 찾아올것같지는 않아요', 8, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '키님DIY 체험으로 예약해서 왔는데 분위기 좋아요~~ 제주를 옮겨다 놓은 듯... 제주여행을 다시 느끼고 돌고돌아 제주삼다수 체험 감사합니다 삼다코지 분위기 내맘에 쏙~~ 저장 크리스마스 트리 너무 멋져요 차도 맛나요', 13, 8, 'GOOD', SYSTIMESTAMP);
