INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '삼다수 키링 이벤트 신청해서 갔는데 생각보다 알차고 미디어관 너무 예뻤구요!! 경품으로 분리수거통 정말 너무 좋네요 ㅎㅎ 밖에 트리 진짜 맛집인정...', 35, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '삼다수에서 좋은 행사가 있어서 참석 버려진 프라스틱으로 만든 재료들로 나만의 키링만들기 게다가 무료입니다 아이들과 함께하기 좋은 삼다코지👏🏿👏🏿👏🏿', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '분위기가 아늑하고 대화하기 좋은 공간이에요! 제주도 컨셉의 카페로 ’삼다수‘를 이용한 커피를 마셔볼 수 있어서 새롭고 신기했어요. 산미가 조금 있음에도 불구하고 맛있게 커피 마셨습니다. 담에는 디저트 먹어보려고요!', 37, 6, 'GOOD', SYSTIMESTAMP);
