INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '귤을 건조시켜서 아이스크림이랑 같이 먹는 디저트였는데 너무 멋있었어요! 엄청 신박했고 음료도 신기했어요!! 너무 맛있었습니다!', 26, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '외부 트리가 예뻐서 지나가다 들린 카페인데, 실내도 너무 잘 꾸며나서 좋았어요!! 뿐만 아니라, 차 세트 구성이 알차서 잘 즐겼습니다.', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '제주 컨셉의 카페라 정말 잠시 제주에 온 기분이 드네요! 음료와 디저트도 특색있는 메뉴가 많고 다양해서 좋아요! 공간도 각 층마다 컨셉이 있고요~ 평일 오후 조용한 분위기 잘 느끼고 갑니다! :)', 35, 4, 'GOOD', SYSTIMESTAMP);
