INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '재밌는 경험 재활용 플라스틱으로 제품(키링, 핸드폰줄)만들기 임영웅 포스터와 봉투 주던데 그건 패스... 공간 예쁘고 독특한 카페 친구랑 같이와야지..', 9, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '저번에 먹었던 우도아이스크림 먹으러 또 왔다가 직원분이 커피없는 말차라떼 신메뉴 출시됐다고 하셔서 먹어봤어요! 너무 달지않고 진짜 맛있어요:)', 38, 0, 'GOOD', SYSTIMESTAMP);
