INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분위기도 좋고 제주에 온 느낌 뿜뿜~ 커피와 삼다 댕유지차 주문해서 마셨는데 넘 맛있어요 :) 카페도 넓고 쾌적하고 이 곳만의 특색있는 음료 메뉴가 많아서 좋네요. 삼다 댕유지차 적당히 달면서도 특유의 은은한 향이 아주 좋아요!🫶 비 오는 날 운치 있게 카페에서 티 즐기기도 딱이고 카페 선곡들도 굿~ 다음에 또 오고 싶을 정도로 깔끔 센스 넘치는 카페입니다. 맛있고 음료 비주얼도 예쁜 게 많아요!', 52, 15, 'GOOD', SYSTIMESTAMP);
