INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '내부도 크리스마스분위기로 예쁘게 꾸며져있고 제주도 분위기도 물씬나서 감성 뽝 터져요!! 음료도 맛있고 시그니쳐메뉴도 맛있었어요ㅎㅎ', 3, 4, 'GOOD', SYSTIMESTAMP);
