INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '독특한 컨셉의 제주도 느낌 물씬 나는 삼다코지~ 더운 여름 너무나 시원한 동굴카페 좋더라구요 시원한 물소리 도 좋고 암실에 숨어있는 대형 돌하루방 보는 기분도 좋더라구요 제주도 우유와 제주특산 재료로 만든 음료디저트도 정말 맛있어요 여름 휴가 못가시는 분들 삼다코지에서 맛있는 제주 디저트 먹으며 휴가 기분내시면 좋겠네요 https://m.blog.naver.com/lovemi0701/223515543534', 4, 8, NULL, SYSTIMESTAMP);
