INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '마치 제주도에 온 것 같은 기분이에요! 아메리카노도 맛있는데 특히 우도땅콩아이스크림의 땅콩이 진짜 맛있어요! 우도에서 먹은 것보다 더 맛있네요! 돌하르방 양갱인데 이것도 특이한 식감이네요! 전체적으로 맛도 분위기도 좋았습니다☺', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '제주 분위기를 느껴보고 싶어서 방문 했는데 생각보다 더 분위기 깡패인 것은 물론이고 커피가 너무 맛있어서 놀랐어요. 로맨틱 제주 에이드도 달달하면서 시원하니 맛있고 우도땅콩 아이스크림은 실제 제주에서 먹은 것보다 더 맛있네요.☺️ 제주가 그리울 때 종종 방문 해야겠어요.🌴', 16, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
