INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '인테리어가 제주제주해요. 사진도 잘 나오고 찍을 곳도 많아요. 제주의 봄 차세트 주문했는데 상차림(?)이 정성스러워요. 우도땅콩 아이스크림도 진한 우유맛에 땅콩을 깔아주니 먹는 재미가 있어요. 여러종류의 좌석이 있는데 죄다 등받이 없는 돌로 된 의자라 많이 불편해요.', 59, 11, 'GOOD', SYSTIMESTAMP);
