INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '직원들 서비스가 최악이에요 여러명이 모여서 시끄럽게 떠들기만하고 일을 하는건지 놀러온건지 모르겠네요 교육 좀 똑바로 시켜주세요', 24, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '제주도 컨셉의 카페입니다! 인테리어가 멋지고 지하, 1층, 2층 이렇게 공간도 많아요. 근데 좌석? 의자?는 좀 불편한 듯 지하에는 폭포 인테리어도 있어서 시원한 느낌이 납니다. 지하는 외부 1층이랑도 연결되어 있어용 신기신기 아메리카노, 로맨틱 제주, 돌하르방 시켜 먹었는데 아메리카노는 고소해서 좋았고 로맨틱 제주도 달달하니 맛있었습니다. 돌하르방 양갱은 그 자체로는 그냥 그런데 크림이랑 과자 부스러기 같은 거랑 같이 먹으니 맛있어요! 모양은 진짜 돌하르방 모양이라 신기했음', 59, 16, 'GOOD', SYSTIMESTAMP);
