INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '전체적으로 도심 한복판에 이렇게 제주 테마 카페를 접할 수 있다는 점이 매력적으로 다가오게 되었는데요. 대체로 제주 특성인 암반석 그리고 제주 식물들고 꾸며져 있어 제주 감성을 끌어올려 주어 재밌었습니다. 또한, 부분부분 포토존이 있어 추억을 남길 수 있는 시간을 가질 수 있다는 점이 장점으로 느껴졌으며 음료도 단순한 음료가 아닌 제주 특성에 맞는 음료를 제공하여 다른 카페와 차이점이 있는 카페로 생각되었어요.', 35, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '자주 왔었는데 리뷰는 처음 써봐요! 우도땅콩 아포가토 너무 달달꼬숩!! 맛있어요ㅠㅠㅠ 녹담만설도 원래 녹차 별로 안좋아하는데 맛있게 먹었어요!! 매장도 넓고 깨끗하구 자주 애용하는 카페!! 일하시는 분들도 너무 친절하시구..🥹 특히 히피펌하신 직원분! 힙하시고 진짜 귀여우세요ㅠㅠㅠ 친절하시고!!', 117, 25, 'GOOD', SYSTIMESTAMP);
