INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '☆☆☆직원분들 응대☆☆☆ 제가 발을 헛디뎠는지 넘어지진 않았는데 계단 내려가면서 그릇 하나를 깨버리는 사고를 쳤는데 알려드리려고 내려가는 순간 이미 소리 들으셨는지 올라오셔서 괜찮냐고 다치진 않으셨냐고 먼저 물어봐주셔서 감사했어요 깨진 거 치울 테니까 그냥 가라고 하셨는데 정말 죄송했습니다....다시 한번 정말 죄송합니다 귤빛찬란은 건조과일 씹는듯한 식감이었는데 맛있었어서 또 먹고 싶은 메뉴였고 스무디는 갠적으로 별로였어요 맛이 독특하고 맛있긴 한데 바닐라맛의 약품 맛이 났어서 비추고 메뉴가 다양해서 재방문 하고 싶어요 재방문 때는 스무디 빼고 다른 걸로 주문할 것 같아요 •주문:카운터에서 주문하면 벨 주심 키오스크x 주문메뉴:제주햇살스무디,귤빛찬란', 32, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '인테리어도 멋진데 디저트부터 커피까지 다 너무 맛있었던 곳... 맛있다맛있다 연발하면서 먹었어요ㅠㅜㅠ 저는 지하에서 먹었는데 동굴ㅋㅋ같구 아늑해서 좋았어요 그런데 음식사진 예쁘게나오려면 1,2층에서 드시는게 좋을거같아요~ 인테리어도 예쁘고 메뉴도 다 맛있어서 좋았어요 귤빛찬란 디저트 진짜 강추입니다!! 최고', 480, 83, 'GOOD', SYSTIMESTAMP);
