INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '제주도를 워낙에 좋아하는 저희 눈에 딱. 들어온 대만족스런 카페를 발견해서 환호했지 모에요(˃̶᷄‧̫ ˂̶᷅๑ ) 조용히 아껴두고픈 카페🫶🏻,,', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '진짜 제주도스러운풍으로 잘 꾸며져있어요 층마다 다 다른 컨셉으로 되어있어서 골라앉으시기 좋을듯해요 디저트도 돌하르방 모양으로 되어있어서 힐링하기 좋을듯해요 굳굳', 12, 5, 'GOOD', SYSTIMESTAMP);
