INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '제주도컨셉의 카페라 넘 좋았어요! 디저트들도 제주도 느낌이라 좋았어요ㅎㅎㅎ녹차푸딩 진짜 맛있었어요! 아포가토도 맛있었어요. 내부 인테리어도 이쁩니다 사진찍으러 오시는분들도 많더라구요!  다만 테이블이 조금 불편해요..🥲', 37, 1, 'GOOD', SYSTIMESTAMP);
