INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '💕 귤빛찬란은 아이스크림인가? 빙순가? 싶은데 통귤도 들어있고 맛있는 귤가루? 도 들어있어서 감탄하면서 먹었어요🍊 💕 제주 햇살 스무디는 한라봉과 레몬, 바닐라 아이스크림을 함께 넣어 만든 스무딘데 부드러운 귤 쉐이크를 먹는 느낌이에요! 은은하게 새콤한데 전체적으로 밸런스 좋아서 완전 만족했어요🥰 💕 귤귤귤은 하귤,금귤,영귤 3가지 귤을 블렌딩해서 만든 찬데 귤 맛 제대로 느낄 수 있는 맛이에요😋', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '삼다수에서 주관한 히어로생일카페 방문했습니다~ 음료 및 디저트도 맛나고, 은은한 조명아래 임영웅의 등신대가 더욱 부드럽게 느껴지고, 센스있는 생일케익으로 눈으로만 봐도 절로 흐뭇했습니다. 직원분들의 밝고 친절한 모습에 감동 받았고, 다양한 공간에서 특별하고 하나뿐인 이벤트 잊지 못할거예요~💎 삼다수와 임영웅 그리고 영웅시대 오래오래 좋은인연으로 함께해요~ 생일카페 이벤트 감사했습니다 ^^', 106, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '임영웅 생일 이벵 예약에 성공하여 방문한 삼다코지 커피도 디저트도 모두 맛있어요. 광고모델과 팬들을 위해 준비해 주신 삼자코지 관계자 및 스탭 여러분께 감사함을 전합니다.^^ 다음 방문때는 차로 제주의 오감을 느끼고 싶어요.^^', 41, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '삼다코지🩵🩵 임영웅 가수님 생일카페 열어주셔서 감사합니다💙💙 직원분들 모두 친절하시고 안내도 꼼꼼히 잘해주신 덕분에 구경 잘하고 왔어요👍', 71, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '버스 & 전철 & 3번의 환승 & 도조15분까지 ~ 멀다면 먼 ~ 초행길이자만 설레이는 마음으로 상수동으로 go go 대기줄부터 -> 친절한 안내 -> 서로서로 도와주고 기다려주고 배려하는 마음으로 1시간의 일정은 눈깜짝 할 사이 지나가 버렸다. 즐겁고 행복한 하루였어요. 감사합니다 ^^', 50, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '제주도 여행 온 기분~!~!~!~!~!  분위기도 너무 좋구 음료도 다 독특해서 맛있고 예뻐욯ㅎㅎ 서울에서 만나는 제주 그 자체~!', 13, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '⭐️ 서울 속의 제주도   🌊 여행가고 싶은 날 가면 좋을듯해요! 돌하르방 양갱은 너무 귀여웠고 아포가토 정말 맛있었어요 2층 안쪽에 영상실 안에 들어가니 제주도에 온것 같은 느낌이 들고, 사실 입구부터 ‘제주구나’ 하는 생각이 듭니다ㅎㅎ 지하 내려가면 또다른 느낌의 바가 있는데 너무 예쁘고, 여름에 앉아있으면 물소리랑 공간때문에 더 시원할 것 같다는 생각이 들었어요!! 전체적으로 카페 인테리어가 훌륭합니당❤️', 25, 8, 'GOOD', SYSTIMESTAMP);
