INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '제주도 멋진 카페 온거같아요!!매장 내 포토존도 많고 메뉴도 특색있고 맛있어요ㅋㅋ사진 넘 잘나오네요. 특별한 날 특별한 시간 보내고 갑니다^^', 32, 7, 'GOOD', SYSTIMESTAMP);
