INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '제주도 느낌 낭낭한 카페입니다. 음료는 쫌 비싸긴 하지만 제주도 가는 대신이라고 치면 그럭저럭? 괜찮아요. 포토 스팟 곳곳에 있고, 식물 다 옮겨와서 그런지 제주도 가고 싶은 마음 달랠 수 있어요. 사진 찍으러 올 만한 장소.', 40, 3, NULL, SYSTIMESTAMP);
