INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '가수 임영웅 생일이어서 삼다수에서 오픈한 생일카페!! 아니 인테리어가 멋진거 아니예요!???? 들어가는 문도 손잡이가 현무암이네요!! 디저트도 먹기 아까웠어요ㅠㅠ 역시 삼다수💧💦', 18, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '33번째 임영웅 생일 이벤트 카페에 티켓팅 성공해서 다녀왔어요~ 역시 제주삼다수 👍 작은 소품 하나하나까지 세심하게 꾸며놓은 생일상과 멋진 임영웅 사진이 가득.. 그리고 생일케익까지 완벽그잡채 BGM으로 임영웅 노래까지~~ 귀호강, 눈호강 제대로 했습니다. 임영웅 팬이여서 행복한 하루, 임영웅이 제주삼다수 광고모델이여서 행복한 하루 보냈습니다. 감사합니다 건행ㄱ', 19, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '특이한메뉴가많고 지하1층,1층,2층공간이 다 다르게 매력있어요! 2층엔 포토존도 있습니다!! 다른메뉴들도 먹으러 또 방문하고싶네요!', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '음료가 대체적우로 맛있았어요! 시그니처 메뉴인 귤귤귤과 로맨틱 제주가 특히 맛있었습니다. 디저트로는 돌하르방 양갱을 주문했는데 정말 귀엽게 생겼고 맛은..양갱 좋아하면 드셔보세요!', 10, 8, 'GOOD', SYSTIMESTAMP);
