INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '사실 돌하르방은 정말 사진용으로 픽힌 거였는데 너무 맛있어서 놀랬어요! 흑임자 양갱 같은데 크림이랑 쿠키 같이 찍어 먹으니 진짜 맛있었어요! (전 양갱 별로 안좋아하는 사람인데도요..!!) 제주햇살스무디도 맛있었어요!!', 26, 2, 'GOOD', SYSTIMESTAMP);
