INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '인테리어가 예뻐서 음료 맛은 별로겠지 했는데 음료까지 맛있어요 ..! ㅠ_ㅠ 대박 ! 전반적으로 조명이 어두워서 감성적이에요 ~~~ 여기서 만든 모든 음료는 제주 우유를 사용한다고 해서 더 믿음이 가네요 ! 우도 땅콩 아포카토 먹었는데 너무 맛있었어요 >_<', 62, 15, 'GOOD', SYSTIMESTAMP);
