INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '녹담만설, 돌하르방 디저트 맛있어요!! 너무 달지 않고 양갱, 푸딩 탱탱한 식감도 굿 연예인 생일카페 행사로 바쁠 때 방문했는데 직원분들이 바쁜 와중에도 짱 친절하심 👍🏻👍🏻 홍대에서 제주도 감성 느낄 수 있는 카페로 추천해요', 81, 17, 'GOOD', SYSTIMESTAMP);
