INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어 너무너무 예쁘구 디저트도 특색있고 좋습니당👍 서울 속 제주💕 삼다수로 만들어졌다고 해서 더 좋아여 디저트들도 맛있구 초코도👍 디저트 포장이 안되가지구 아쉬울 정도!!', 37, 1, 'GOOD', SYSTIMESTAMP);
