INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '합정 지나다니며 카페 찾다가 우연히 발견했는데 인테리어 예쁘고 제주도 컨셉이 여행온 듯한 느낌이라 좋았어요. 우도아이스크림과 커피마셨는데 우도땅콩 아이스크림은 우유맛이 강한 우유아이스크림이니까 우유맛 싫어하시는 분들은 드시지 마세요. 저는 맛있게 먹었는데 우유맛 싫어하는 남친은 몸서리치더라고요😂', 72, 15, 'GOOD', SYSTIMESTAMP);
