INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대 근처 삼다코지 다녀왔습니다~ 제주 컨셉의 카페고요 평상시에도 인기많은 곳인데 트리장식을 예쁘게 해놔서 다시한번 다녀왔습니다~  지나다가 누구나 트리를 배경으로 사진 찍을수있어요~ 좋죠?^^ 메뉴도 다양하고 제주향 듬뿍나는 메뉴구성이고  다 맛이 좋아요~  어떤 메뉴를 선택해도 실패없습니다~ 제주귤도 맘대로 먹을수 있도록 준비되어있고요~사진보심 아시겠지만 부담없이 눈치안보고 가져다 먹을수있게 해놨답니다. 지하부터 2층까지 자리가 있고 넘넘 예쁜 곳입니다. 안그래도 인기 많은곳인데 대형 트리까지 해놔서 더 손님들 많아지겠어요~~  제가 리뷰하는곳은 아시죠? 왼전 분위기 좋으니 다녀와보세요~  강추합니다. 주차장은 따로 없고 골목에 ㅜㅜ 직원분들도 친절하시고 뭐하나 흠잡을곳 없는 카페에요~  홍대가신다면~!', 81, 18, 'GOOD', SYSTIMESTAMP);
