INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '제주도 분위기의 카페가 있다고 해서 홍대놀러와서 와봤는데 손잡이 부터 현무암손잡이 디테일부터 전체적인 분위기가 너무 좋고 디저트 조차도 돌하르방 디저트에 우도땅콩아이스크림 단짠단짠 맛잇어요! 사진찍기도 좋으며 제주도 가고싶었는데 그부분을 대리만족 시켜줄수 잇는 공간같아 너무 좋아용!ㅎㅎ', 49, 0, 'GOOD', SYSTIMESTAMP);
