INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대 근처 방문할일이 있어서 예쁜카페 찾다가 이색적일것 같아 방문했어요! 제주도 컨셉의 독특한 분위기가 인상 깊어 한번쯤은 와볼 만 한것 같습니다. 다만,의자가 생각보다 불편해서 수다떨기에 적합하지는 않아요🥲', 81, 14, NULL, SYSTIMESTAMP);
