INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '음료가 예쁘면 맛있고 인테리어가 멋져요. 가격은 좀 있는데 재료인 물과 얼음을 다 삼다수로 만들고 입구쪽에 가져가라고 제주귤을 놓아두어 비쌀만하다 생각합니다. 앉을 자리는 많지 않아 공간구성은 아쉽지만 좋았어요.', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '카페 인테리어가 예쁘고 지하에도 자리가 있어서 친구들이랑 조용히 앉아서 대화할 수 있었어요. 초코라떼가 부드럽고 위에 코코아가루가 뿌려져 있어서 예뻤어요. 우도 아이스크림도 아이스크림 자체로도 맛있고 땅콩을 묻혀서 먹는 것도 고소해서 맛있었습니당 지하는 약간 어두우니 부딪히지 않게 조심해야 될 듯', 35, 2, 'GOOD', SYSTIMESTAMP);
