INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '가게 웨이팅하는 동안 있으려고 지나가다 들린 카페인데 컨셉고 너무 좋고 디저트도 개성있고 너무너무 마음에 들었습니다! 디저트 세트가 가성비도 있는거같아서 자주 오고싶어요!!!💕💕💕', 43, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '우도땅콩 아이스크림 고소하고 맛있었어요ㅎ 외관은 벌써 크리스마스 분위기가 났습니다 내부는 2층과 야외가 있는데 포토존이 있어서 사진찍고 놀 수 있어요 귀여운 디저트도 많고 대화하기 좋아서 합정역 근처 카페로 추천합니다', 17, 3, 'GOOD', SYSTIMESTAMP);
