INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '상수역 카페찾아보다가 알게 됐는데ㅎㅎ직접 와보니 크리스마스 분위기에 너무 좋아요!❤️ 일요일인데 사람들이 많아서 야외 좌석에 앉았는데도 괜찮았어요! 다음에 제주도 생각날 때 한번 와보시면 좋을거 같아요!!', 47, 2, 'GOOD', SYSTIMESTAMP);
