INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '분위기가 독특하고 너무 좋아요 지하는 바 같은 분위기라 좋고 맨 윗층은 밝아서 좋아요 직원분들도 정말 친절하셨어요! 우도땅콩 아포카토는 주문 필수!! 재방문 하러 금방 올것같아요', 106, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '커피도 맛있었고 인테리어도 좋았습니다 실망스러웠던 점은 10시 20분에 아직 마감시간이 되지 않았는데 나가라는 듯이 가게 노래와 불을 다 꺼버려서 쫓기듯 가게를 나왔습니다 네이버 플레이스에 나와있는 운영시간도 맞지않고 알바생으로 보이는 여성 두분의 태도에 많이 불쾌했네요', 97, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '입구에 들어서자마자 제주도의 향기가 느껴지는 인테리어가 눈길을 사로잡아요.  음~제주~~♡♡ 대표귤과 녹차를 홍대에서 맘껏 눈으로 입으로 즐기다갑니다.', 39, 4, NULL, SYSTIMESTAMP);
