INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '카페 들어오면 제주도 느낌이 물씬 나요 홍대에서 1초만에 제주도로 온 것 같습니다 보통 카페에서 인테리어와 음료 두가지가 충족되기는 어렵다고 생각하는데 삼다코지는 두개를 모두 충족한다 생각했습니다 입구 앞에 귤을 두셨는데 귤도 정말 맛있었습니다 ㅎㅎ 음료도 특색있고 재밌어요 커피를 못드시는분들도 메뉴 선택지가 넓어서 오시기 좋을 듯 합니다 ㅎㅎ', 38, 6, 'GOOD', SYSTIMESTAMP);
