INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '카페 분위기 그리고 음료랑 디저트가 제주 컨셉이라 너무 신선하고 좋았고 너무 맛있었어요~ 특히 아이스크림이 땅콩이랑 너무 잘 어울렸어요 같이 있는 달고나도 맛있네용', 14, 10, 'GOOD', SYSTIMESTAMP);
