INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '곶자왈크림라떼, 이시보막걸리쉐이크 마셨는데 둘 다 맛있었습니다. 다만 가져가라고 놔둔 귤의 상태가 영 좋지 않습니다. 하얗게 곰팡이 핀 걸 보니 군침이 싹 말랐습니다.', 6, 3, 'BAD', SYSTIMESTAMP);
