INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '매장이 넓어서 쾌적합니다 제주도느낌 물씬 풍기는 시원하게 트인 돌과 풀과 물의 조화로운 인테리어가  맘에 들고요. 디저트도 귤, 녹차와 같은 제주도 특산물 모티브 위주로 나와있어요. 가격대가 저렴하진 않은데 공간을 즐기는 비용이라고 생각하니 괜찮은 것 같아요. 👍🏻', 110, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대에 이런 곳이 있다는게 숨은 보석같은 느낌! 홍대 속에서 제주도를 느낄수 있음 디저트가 신의 한수~ 보는재미, 먹는재미 짱!!', 75, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '약속  시간 텀이  생겨버려서  우연히  들어간  카페 제주  테마라 신기해서  두리번거리며  주문두  안하고 벙쪄있는데  알바언니가 차분히  기다려주시다 맛난 추천  음료랑 아수크림알려주셔서  시킴 음료받을때  맛난게  먹는  방법두  알려주심 완젼  감동 !!!!! 아스크림은  땅콩가루랑  너무  잘어울림 최애  아수크림  대버림 !!!! 곶자왈  크림 라떼는  우선  크림만  한수푼 ~ 넘  부드러움 빨대로  전체  잘 섞어서  먹으면  적당히  달고 끝에  커피맛이나  좋았음 !!! 내갠취 밀크티는  홍차맛이  강해서  좋았으나 맛은  좀  밍밍해서  아쉬웠음 ~ 우연히  드루왔지만  오랜만에  맘에드는  카페  찜함❤️', 93, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '트리가 매장 안, 밖 둘다 있어서 크리스마스 분위기 너무 좋아요 밀크티는 홍차 맛이 진하고 말차푸딩은 우유맛이 살짝 진한 말차푸딩입니다 크럼블?이랑 잘 어울려서 맛있어요', 25, 3, 'GOOD', SYSTIMESTAMP);
