INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '친구가 좋은 카페가 있다고 해서 같이 가봤는데 인테리어나 컨셉이 되게 좋았습니다. 메뉴도 예쁘고 맛있었는데, 직원이 한분 밖에 안계셔서 대기시간이 좀 길었습니다.', 68, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '인테리어도 멋지고 소소하게 챙겨주는 게 많아서 좋았어요! 커피도 차도 맛있었어요~~ 다만 지하 자리는 남자가 앉기는 불편해요(허벅지가;;)', 37, 7, 'GOOD', SYSTIMESTAMP);
