INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '제주컨셉 카페. 가격이 사악하지만 자리를 잘 잡으면 조용하고 전시관 느낌이라 좋아요~ 지하 동굴같은곳, 2층 주문하는곳, 3층 뷰가 이쁜?!? 그리고 에어컨 온도가 층마다 달라서 좋았어요 디저트가 맛있어요!! 또 방문할 가치가 있는곳이에요.', 31, 6, 'GOOD', SYSTIMESTAMP);
