INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '막걸리쉐이크랑 녹담만설 너무 맛있어요! 막걸리 조아해서 시켜봤는데, 술 맛이 넘 센것도 아니구 칵테일같이 너무 맛있어요.   ·  *  ˚ . 막걸리쉐이크에 같이 주신 핑거스낵도 짭쪼롬 & 꼬숩!', 22, 8, 'GOOD', SYSTIMESTAMP);
