INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '평일 월요일 바쁘지 않은 시간대에 방문했는데 직원분들 정말 불친절의 끝판왕이시네요.. 이렇게 예쁜 인테리어 해두고 누가봐도 일하기 싫은 알바생들때문에 손님을 잃을 것 같네요.', 65, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '서울 한복판에 있는 작은 제주도를 느낄 수 있었다. 밀크티는 향이 진했고, 저 스무디는 새콤했다. 와플은 생각 이상으로 맛있었고, 저 아이스크림 위에 있는 바삭한게 맛있었다.(아마 코코넛?)', 84, 12, 'GOOD', SYSTIMESTAMP);
