INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '분명 홍대인데 제주도에 온 느낌?! 야자수부터 동굴같은 느낌의 지하층이랑 모든 메뉴들이 제주도 컨셉이더라구요. 커피도 맛있고 공간도 넓직하고 쾌적했습니다. 새로 나온 잠봉뵈르 플레이트를 먹었는데 메뉴 구성도 좋고 플레이팅이 잘되어 보기도 좋았습니다~ 포토스팟이 여기저기 있어서 사진찍기도 좋았어요', 43, 7, 'GOOD', SYSTIMESTAMP);
