INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '🍊 귤빛찬란, 제주햇살 스무디 🍊 메뉴가 특색있고 좋았어요. 사진도 이쁘게 찍히더라구요 요거트랑 새콤달콤한 맛 좋아하시면 귤빛찬란 추천드려요!', 121, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '여기는 앉아서 뭘 먹으라는건지 내부에 편하게 앉을만한 자리가 하나도 없네요 인스타 사진 찍으라는 거같은데 그거에 기본 음료 8천원대에 디저트도 8천원대 ㅋㅋ.. 글고 메뉴 골때리게 써놓고 알바 메뉴고르는데 오래걸리니까 핸드폰 팍팍놓고 한숨쉬더니 수저를 설거지통에 던지기까지 하더라구요? ㅋㅋ 그렇게 돈벌기 싫으시면 알바를 왜하시지 정말 불쾌한 기억밖엔 없네요~', 79, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '제주도에 온 느낌이 들었어요. 가격도 제주라 아쉬웠지만 흑흑 독특한 컨셉에 살짝 갤러리에 온 느낌? 제주보리와플 맛있었고 음료는 조금 아쉬웠어요. 그치만 넓은 공간에 시원하고 대화 나누기 정말 좋습니다 🖤', 50, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '인테리어가 새미제주 느낌이라 항공비랑 숙소비 안내고 제주도를 느끼는 기분이듭니다. 물소리 들리고 돌들도 많아서 진짜 제주도 카페 온 기분이에요. 특색있는 디저트들도 귀엽고 제가 아이스크림 처돌이라 아이스크림 디저트가 많은 것도 좋습니다. 홍대에 이런 대형 카페 있기 쉽지 않은데 이걸 해낸 삼다코지.. 박수드립니다. 대응도 친절하셔서 기분 좋게 즐기다 갑니다. 평일에 오면 한적하고 좋아요! :)', 31, 8, 'GOOD', SYSTIMESTAMP);
