INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '또 먹어도 맛있는 귤빛찬란과 밀크티를 마셔보았어요~~! 디저트들이 특색있고 맛있어요! 주말엔 사람이 많고 자리도 없어서 못갔는데 평일 저녁엔 여유 있더라구요!', 22, 9, NULL, SYSTIMESTAMP);
