INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '제주도 컨셉의 카페. 삼다수에서 운영하는 플래그십스토어라고 합니다. 디저트류가 독특하면서도 맛있었어요. 2층은 냉방이 잘 안되는지 더웠고, 자리가 많거나 편한 곳은 아니었습니다. 사진 찍기 좋은 곳이라 그런지 여기저기서 셀카찍는 분들이 너무나고 많아 조금은 불편했습니다.', 3, 5, NULL, SYSTIMESTAMP);
