INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '아이유 생일 카페로 꾸며졌을 때 방문했어요 ㅎㅎ 아이유 덕에 알게된 카페인데 차+디저트가 진짜 일품이네요! 다음에 또 재방문할 의사 있어요!', 3, 10, 'GOOD', SYSTIMESTAMP);
