INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '일단 인테리어에 모든걸 쏟아뷰은 카페같아요 👏 인테리어 너무 이뻐서 진짜 제주도 온것 같은 느낌이었어요 음료는 평범 했고, 디저트는 맛잇었어요 대신 좌석이 너무 불편하고 좌석수도 별로없어요 ㅠ 진짜 좌석 너무 불편해요', 12, 7, NULL, SYSTIMESTAMP);
