INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '제주도의 바닷가가 일렁일거 같은 컨셉의 카페인데,, 진짜 나만 알고픕니다. 숨겨진 카페에요! 아메라카노도 향들이 진짜 많고 그럿습니다! 근데 좀 비싸서,, 분위기 낼 때 가기 좋을듯 👀🤍', 38, 9, NULL, SYSTIMESTAMP);
