INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '인테리어 독특해서 방문했어용!! 너무 이쁘고 제주감성 그대로 입니다ㅎㅎㅎ 음료도 종류 특이하고 맛있었어용:) 생일기념으로 방문했는데, 좋은 추억 남기게 해주셔서 감사합니다!', 129, 22, 'GOOD', SYSTIMESTAMP);
