INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '인테리어에 신경을 많이 써서 그런지 좌석이 많진 않습니다 그 점 참고하세요! 특별한 메뉴도 있고 특히 녹차 푸딩(녹담만설)이 너무 맛있어서 추천드려요! 다음에 가면 또 먹을 예정입니다 인테리어도 예쁘고 차, 커피도 맛있어서 다음에 또 가고 싶어요', 19, 7, 'GOOD', SYSTIMESTAMP);
