INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '가까운 곳에서 제주도를 느끼고 싶다면 여기로 오세요!! 입구부터 “여기 제주도야.”라고 말해줍니다. 그런데 인테리어 뿐만 아니라 디저트도 놓치지도 않았더라고요!!! 녹담만설은 예쁘고 그만큼 맛도 있었어요. 근데 귤빛찬란이 진짜 진짜 진짜 맛있어요. 보이는 것보다 더 맛있어요. 새콤 달콤 다합니다. 제발 다들 먹어주세요ㅠㅠ 저 때문에 끌려온 친구들도 모두 만족한 카페였어요. 추천추천💕', 33, 9, 'GOOD', SYSTIMESTAMP);
