INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '삼다수 제주컨셉의 카페로 한번쯤 가볼만한곳 같아요. 좌석이 많지 않고 2인 좌석이나 긴 테이블 형태들로 되어 있어요. 그리고 지하층은 핸드드립 같은데 거기도 바형태로 되어있었어요~ 전체적으로 톤다운된 인테리어 였고 음료가격은 7-8천원 이상정도.', 36, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '곶자왈크림라떼는 많이 달지 않고 마차 크림이 진짜 맛있었어요. 돌하르방은 양갱인데 조금 달았지만 너무 귀여웠고, 우도땅콩아이스크림은 땅콩맛이랑 아이스크림이 어우러져 너무 맛있었어요. 또 이 카페는 3층으로 되어있는데 지하층에는 어둡지만 고요한 분위기 약간 바같은 분위기였고 일층과 이층은  야외 빛이 예쁜 가구들과 어우러져 있어서 사진찍기 좋았어요. 인스타용 커피와 간식들로도 좋았지만 무엇보다 맛과 분위기가 좋아 재방문 하고 싶어요!', 50, 2, 'GOOD', SYSTIMESTAMP);
