INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '진짜 제주도 같이 귀염뽀짝 했어요 인테리어 이쁘고 사진찍을곳 많아요!! 갤러리 느낌도 났어여 깔끔하게 잘 해놓았어요 디저트 보기도 좋고 맛도 좋아요 돌하르방양갱 굿!!! 평일 저녁인데 한가롭고 여유로워요', 71, 16, 'GOOD', SYSTIMESTAMP);
