INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매장 인테리어도 인테리어였지만 개인적으로 따뜻한 곶자왈림라떼가 참 맛있었어요~ 조금 늦게가서 우도땅콩아보카도를 못 먹어본게 다소 아쉬웠다는~', 62, 17, NULL, SYSTIMESTAMP);
