INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '합정, 홍대 안에 제주도가 있네요! 제주 바닷가 카페를 그대로 가져다 놓은 느낌이에요ㅋ 티세트(제주 가을) 시켰는데 너무 아기자기하게 예쁘고 맛도 좋았어요~ 또 올게요!', 85, 13, 'GOOD', SYSTIMESTAMP);
