INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '시그니처 음료, 디저트가 있고 삼다수에서 진행하는 만큼 물과 얼음을 제주 삼다수로 제공해 너무 좋았어요!! 제주컨셉 너무 좋아요🍊', 15, 7, 'GOOD', SYSTIMESTAMP);
