INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '요즘 제주 여행가고팠는데ㅠㅠㅠ 여행다녀온 기분 인테리어 최고였음 특히 지하1층 와인바같았고 물소리 넘 좋더라고요 지인들에게 추천중❤️ 하르방은 맛이 제스탈은 아니었는데 귤빛찬란은 맛나용', 78, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '층마다 분위기가 달라서 좋아요 몇번 더 와보고싶은 느낌이고 디저트들도 단순한 느낌 아니고 재료는 심플한데 조화가 좋아서 시그니처 귤향 먹었는데 너무 맛있어요! 귤이나 레몬 오렌지 등 시트러스 과일 건조한건 많이 봤는데 과일 통채로 동결건조는 딸기외엔 처음봐서 신기했어요 식감완전 파사삭한데 바닐라 아이스크림이랑 먹으니까 너무 맛있어요 .. 로맨틱 제주 말그대로 진짜 컬러감이 로맨틱 ♥ 장미청 잘못하면 화장품맛 나는데 너무 달지도 않으니까 향도 더 잘 느껴졌어요 생수는 병으로 제공되고 판매도 하는데 판매시엔 티백이랑 같이 묶어서 판매하더라구요 바질티백? 궁금했음 지하는 천장이 물결모양이고 층고가 낮아서 오히려 더 물결이 잘 보이는 느낌? 덜답답', 76, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '제주 갬성 인테리어는 찬란하지만, 공간에 비해 좌석은 좀 비효율적이라는... 귤빛찬란, 이 구워서 튀긴듯한 환상적인 식감만큼은 절대 못 잃어ㅋ.', 30, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '시킨거 전부 다 맛있었구 특히 로멘틱제주가 진짜 너무 맛있었어요!! 마시자마자 순삭하게되는 맛이였어요..👍🏻 인테리어도 이쁘고 분위기도 좋아요!!', 18, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '제주에 진심인 삼다수가 운영하는 카페 삼다코지🌴 2층 건물로 핸드드립바, 포토존, 제주도를 느낄 수 있는 공간까지 다채롭게 공간을 즐길 수 있었어요 일반 카페에서 보지 못하는 메뉴들에도 눈길이 갔는데 모두 제주와 관련된 재료와 음식을 이용해 만들었고 물과 우유마저도 원산지가 제주도라고 써있었어요 서울에서 만나볼 수 있는 몇 안되는 제주컨셉 카페라서 색다른 경험을 즐기고 싶다면 추천하고 싶은 공간이에요🗿', 21, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '입구부터 실제로 제주도 온 것 같은 느낌이 가득했고 내부가 넓고 쾌적했어요! 문 손잡이가 현무암으로 되어 있고 지하공간에는 폭포를 연출해놓는 등 디테일이 살아있는 부분도 너무 좋았습니다. 다른 메뉴들도 너무 맛있었지만 특히 귤빛찬란 강추합니다. 말린 제주귤과 요거트의 조합이 환상적이었어요🧡', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '오~ 공간 디자인에 공을 많~~~이 드렸네요. 제주를 담으려고 층마다 다른 느낌. 지하 동굴, 지상 돌하루방, 디저트도 귤, 하루방으로 특색있게 준비하고~ 여러모로 눈이 즐거운 카페였네요. 디저트 귤빛찬란 말린 귤 아래 아이스크림. 딱딱한가 싶었는데 알알이 분리하고 먹으니 상큼하게 녹는 느낌. 아메리카노 성산일출. 진한 향, 맛이 괜춘. 이 모든 것이 삼다수로 만들었다? 삼다수 고민 좀 했네요. 좋았습니다.', 86, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '제주도에 온 것 같아서 기분전환하기에 너무 좋은 분위기 카페입니다! 분위기 뿐만 아니라 디저트도 색다르고 맛있어서 소개팅이나 데이트로 가기에 너무 추천👍 두번째에서는 귤빛찬란먹었는데 이전에 먹었던 돌하르방 양갱이 더 제 입맛에는 딱이었어요 근데 둘 다 맛있음 🫶🏻', 20, 10, 'GOOD', SYSTIMESTAMP);
