INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '재방문의사 100% 제주 사계절 티세트(겨울): 12,000원 제주 바질 블렌딩티(병): 1,500원(병사이즈 관계없음) 겨울 티세트는 동백꽃,백년초,허브 등을 블렌딩한 차로 상큼하면서도 입맛을 돋구어주는 차였음. 귤찹쌀떡은 너무너무 차가웠지만 새콤달콤한 맛이였고, 양갱들도 달지 않아 차와 곁들여 먹기 좋았음. 바질 블렌딩티는 동료들 선물용?으로 구매했는데, 물 용량 관계없이 티백 가격이라 동일함. 메뉴를 다 먹어보고 싶어 2번이상 방문할 것 같은 제주도 컨셉이 제대로인 카페!! 가격에 맞는 맛과 서비스라 정말 만족스러웠구요. 이벤트 중이라 커피드립백도 받았답니다.', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '제주도까지 가지 않아도 제주도 느낌을 물씬 느낄 수 있는 공간이었습니다. 삼다수에서 만든 곳인지 삼다수를 이용해서 만든 거라고 하네요. 공간 크기에 비해 앉을 수 있는 곳은 부족하다고 느껴졌어요. 따로 포토존이 있는 것은 좋았습니다. 음료랑 디저트는 아이덴티티도 확실하고 맛도 있었습니다:) 귤 가져가라고 박스도 있었는데 제가 갔을 때는 안 남아있어서 아쉬웠어요 ㅎㅎ 다음에 또 방문할 것 같아요!', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '삼다크림라떼 색다른 맛이여서 맛있어요!😉 그리고 다들 굴빛친란은 꼭 드셔보세요! 양에 비해 비싼게 흠이지만 너무너무 맛있어요😍 위에 귤이 과자처럼 빠삭하고 아래는 아이스크림인데 달달하고 아주 굿👍 아 그리고 겨울이여서 그런지 귤을 무상제공 해주더라고요!! 귤 너무 달고 맛있어...요...👍 만족스러운 카페예오', 8, 7, 'GOOD', SYSTIMESTAMP);
