INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '인테리어가 징짜 오져요! 서울 카페 많이 다녀봤지만 이런 스타일은 또 처음 ,, 🍊✨ 인테리어가 특별해서 재방문하고싶어져요!! 지하-1층-2층으로 되어있었구, 주말에 가니까 사람은 많았어도 웨이팅은 안했어요. 🧇🍨 디저트나 음료도 무난무난 괭찮았숨다! 커피도 조금 서비스로 내려주셨는데 친절하셔서 기분이 좋았어요 ☃️', 14, 0, 'GOOD', SYSTIMESTAMP);
