INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '인테리어도 예쁘고 곶자왈 말차크림이랑 푸딩 진짜 찐하고 맛있어요💚밀크티도 라벤더향가득💜 진짜 제주온것같이 힐링하고갑니다~~물도 얼음도 삼다수인점도 귯👍', 75, 12, 'GOOD', SYSTIMESTAMP);
