INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), 'Delivers feeling of Jeju! It presents some special kinds menus inspired from Jeju. Maybe, a little shortage of tables and chairs, but the place has a quite uniquely nice interior! Likely to revisit later again! :)', 72, 14, 'GOOD', SYSTIMESTAMP);
