INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '신상카페 찾았어요 제주도 분위기 물씬 겨울차세트와  크림라테 정말 정성스러운 차림상에 반해 계속 사진을 찍게되네요 사계절의 차를 다 맛보고 싶어지네요', 108, 19, 'GOOD', SYSTIMESTAMP);
