INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '들어서는 입구부터 제주도 느낌이 물씬 나서 좋았어요!🪨🪨 방문하시는 분들 지하 꼭 가보세요. 폭포도 있고 지상이랑은 또다른 분위기 입니다. 삼다크림라떼는 위에 크림이 고소하고 간혹 씹히는 댕유자가 커피랑 만나 새로운 맛이었습니다. 우도땅콩아이스크림은 아이스크림이랑 땅콩과의 조화가 넘 좋았어요! 디저트로 강추입니다. 제주도 가지 않아도 도심에서 제주도를 느낄 수 있어서 전체적으로 좋았습니다.', 35, 1, 'GOOD', SYSTIMESTAMP);
