INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '여기가 서울인가요 제주인가요? 컨셉만 제주도인게 아니라 메뉴 하나 하나 플레이팅&맛 모두 제주 그 잡채, 아니 그 이상이었습니다. 디저트 맛은 크게 기대 안했는데 쌉싸름한 녹차푸딩부터 동결 한라봉이 통채로 들어간 시원한 요거트, 양갱 모두 너무 맛있네요💓 재방문의사 10000%입니다.', 48, 2, 'GOOD', SYSTIMESTAMP);
