INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '지하에서 드립커피도 판매하길래 냅다 시켰어요! :) 평소 즐겨먹던 코케허니인데..  오늘 먹은 코케허니 향이 더 깊고 여운이 좋아서 또 갈 예정이에요 !! 남자친구는 커피를 전혀 몰라서 메뉴만 보던 중에 직원분께서 먼저 취향 물어보면서 추천해주셔서 원두를 고를 수 있었어요!! 잔 구성도 너무 이쁘고 원두에 대한 설명도 너무 좋았구, 인테리어도 너무 이뻤어요!! 다음에 또 가서 다른 원두도 선택해 볼 예정입니다!! :)', 3, 5, 'GOOD', SYSTIMESTAMP);
