INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '처음 외관을 봤을때 분위기가 너무 좋아서 기대가 됐습니다. 음료와 디저트를 시키면서 기대가 더 커졌는데 진짜 기대를 뛰어넘는 맛있는 디저트랑 음료에요 귤빛찬란은 귤의 상큼함과 아이스크림의 달달함의 조화가 뛰어나구 귤귤귤은... 말해뭐합니까 당장 드세요', 10, 10, 'GOOD', SYSTIMESTAMP);
