INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '제주도에 온 느낌이었습니다 🍊🍊 귤빛찬란 & 로맨틱제주 이름도 예쁘고 비주얼도 👍 맛도 👍 기분 좋아지는 카페입니다~ 추천!!', 12, 9, 'GOOD', SYSTIMESTAMP);
