INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '추천 디저트 귤빛찬란 꼭 드셔보세요~ 저는 너무 상큼하고 부드러워서 제 스타일 이었어요^^ 오늘 또 가고싶은 카페 디저트들 이었어요^^', 39, 2, 'GOOD', SYSTIMESTAMP);
