INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '제주삼다수 "삼다코지" 홍대카페 발도장 쿵!쿵! 홍대랑 상수 중간쯤 위치한 삼다수카페 11월 오픈한 핫플이라고 해서 방문~ 메뉴이름도 디저트도 맛도 이쁜 "귤빛찬란" 제주삼다수랑 제주우유랑 "코지밀크티" 그냥 고숩고 맛있는 "우도땅콩아이스크림" 라떼는 삼다크림라떼인가? 곶자왈크림라떼인가? 둘다 맛있네요~ 개취존중', 27, 6, 'GOOD', SYSTIMESTAMP);
