INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '롤링홀 근처 제주 삼다수 플래그십스토어 제주와 관련된 음료, 디저트가 가득한곳 다음엔 동굴 같이 느껴지는 공간에 핸드드립 커피 마시러 갈래요', 18, 1, 'GOOD', SYSTIMESTAMP);
