INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '예뻐요 :)  사진찍기 좋고 포토존도 있어서 인생샷 남길 수 있어요. 음료도맛있고 특히 물을 전부 삼다수로 사용한다 하더라고요 :)', 56, 13, 'GOOD', SYSTIMESTAMP);
