INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '개인적으로는 지하에서 핸드드립으로 드시는 걸 추천합니다. 핸드드립 정말 잘 내려주시고, 취향껏 추천과 원두에 대한 설명을 잘 해주셔요! 커피에 매우 열정적인 바리스타님이라는 느낌이 물씬 납니다', 11, 10, 'GOOD', SYSTIMESTAMP);
