INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '층마다 인테리어 너무 예쁘고, 제주도 컨셉으로 포토존도 구석구석 많아요! 그리고 음료도 예쁘고 맛있는데 특히 귤빛찬란 저 디저트 최고... 하나 더먹을까 고민하다가 담에 또 오려고 아껴놨어요', 120, 21, 'GOOD', SYSTIMESTAMP);
