INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '새로 생겼다길래 가봤는데 분위기 좋고 커피 디저트메뉴도 먹어볼만한게 많았는데 자리가 넓진 않네요.. 불편한 자리 ㅠㅜ 우도땅콩아포카토는 거의 아이스크림수준 ㅋㅋ 퍼먹고 에스프레소 부어서 아포카토로 먹었네요 굿', 9, 8, 'GOOD', SYSTIMESTAMP);
