INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '정말 제주에 온 것 같은 멋있는 인테리어와 커피, 디저트 모두 색다르고 이쁘고 맛있었어요! 제주 삼다수로 만든 음료라니 더 고급스러운 느낌이에요', 40, 2, 'GOOD', SYSTIMESTAMP);
