INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '아인슈페너처럼 크림 층 나눠진 음료를 좋아하는데 곶자왈크림라떼가 딱이었어요 우도땅콩아이스크림은 맛있긴한데 아이스크림이 너무 금방녹아서 아쉬워요 공간 너무 예쁜데(랑데자뷰 상위호환느낌?) 실내가 너무 더워요.. 11월인데 바깥좌석에서 먹었어요', 46, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '지하1층 핸드 드립 바는 천장고가 높지 않아서 다소 답답한 느낌이 들 정도로 지하 동굴처럼 조성되어 있어요. 1층과 2층도 제주도의 분위기를 담은 인테리어가 조성되어 있으나 다소 앉아서 차를 마실 공간은 협소했어요. 이번 방문에는 음료만 마셨었는데 다음에는 디저트도 먹어 봐야겠어요. 겨울 시즌 디저트도 추가 개발하면 더 좋을 것 같아요.', 47, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '삼다수랑 제주도 컨셉으로 콜라보한게 특이하고 적절했다고 생각합니당 벗, 제 기억에 노래가 시끄러웠던 것 같아용 주변에 사람들이 많은 것도 아닌데 말소리도 그렇고 전체적으로 시끌시끌 했슴니당 공간 특성상 그런건가 싶기도 하네요!', 75, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '인테리어가 미쳤어요. 많이 투자한 느낌이 납니다…. 화장실 핸드워시 너무 부드러워서 좋았고, 특이한 메뉴들이 많아서 재밌었어요. 와플이랑 땅콩아스크림 완. 맛.', 6, 5, 'GOOD', SYSTIMESTAMP);
