INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '콘치즈 스콘 너무 먹음직 스러웠는데요 , 이런 스콘은 처음입니다~!!!! 목맥히는 스콘은 이제 가라! 콘치즈의 촉촉함과 달콤함이 가미되어 맛의 밸런스가 잘 맞아 너무 맛있게 먹었던 콘치즈 스콘. 많이 달지 않고 퍽퍽하지 않아 아메리카노와 잘 어울릴만한 디저트 메뉴였습니다.', 61, 11, 'GOOD', SYSTIMESTAMP);
