INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '커피랑 스콘 모든게 완벽했던 합정 카페였어요! 위치도 딱 적당히 조용해서 편안하게 대화하기 좋았고 창가로 보이는 푸릇푸릇한 나무가 너무 예뻤어요 창가에서 커피에 스콘 한입하면 부러울 것 없는 주말이 완성됩니다 🍃☕️ 디저트 맛집 혹은 작업/대화하기 좋은 카페 찾는다면 로아프 하우스 추천드려요!', 19, 5, 'GOOD', SYSTIMESTAMP);
