INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '커피 디저트 맛있고 조용하고 아늑한 분위기까지 취향저격인 홍대 합정역 카페입니다.☺️ 맛난 디저트 커피가 있구요. 조용조용 한적한 분위기라 혼자와서 작업하다 가기도 좋아요. 초코스콘, 버터갈릭스콘이랑 커피 마셔주면 진짜 힐링 디저트 쵝오~!! 👍', 52, 15, 'GOOD', SYSTIMESTAMP);
