INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '새로생긴 곳이라고 하더라고요. 너무 쾌적한 공간이라 마음에 들었습니다. 롱블랙도 팔고요. 다양한 잎차를 우려 만든 디톡스 차도 흥미로웠어요. 공간이 너무 시원하고 좋았고 짙은 오더테이블과 키친쪽도 살짝 보이는데 너무 깔끔하고 멋졌습니다. 한 가지 아쉬운점은 사람이 많은 주말에 방문하기도 했지만 노출콘크리트, 스튜디오 구조라 그런지 대화 소리들이 자리에 있을 때나 주문을 할때도 직원과 소통이 어려울정도로 울려서 아쉬웠습니다.', 97, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '커피 원두도 선택할 수 있고 매장 분위기도 너무 좋네요 디저트도 종류가 많아서 취향껏 골라서 맛보면 좋을거같아요! 직원들도 친절하셔서 주말 오후의 시간을 잘 보내고 왔습니다~!', 17, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '합정역 새로오픈한 카페라서  방문 🥰비가와서 운치가있어요ㆍ공간도 넓고 깨 끗해요   대화 소통공간이라  뷰가좋고 창너머  나무들이 보여서 좋아요ㆍ 오늘 주문은 플랫화이트   자몽허니블랙티   라즈베리로아프케익 주문했는데 커피의향괸 맛이좋고 자몽허니블랙티는 달지않고 쌉쌀한맛이  취향제격🥰🥰커피와함께먹는 라즈베리로아프케익  완전  달콤하네요🧡❤️🥰', 1, 6, 'GOOD', SYSTIMESTAMP);
