INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '매장넓고 시원 통창이라 개방감있어서 좋아요 날씨 좀 시원해지면 테라스 좌석도 좋을것같아요~~ 유자민트 달지않고 깔끔한맛~~♡ 커피도 괜찮은편이고  스콘 맛있어보임', 23, 0, 'GOOD', SYSTIMESTAMP);
