INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '합정에 10시까지 하는 귀한 카페♥️ 심지어 자리도 넓고 디저트들도 하나같이 맛있어보임!! 아아메 아주 깔끔하고 디카페인인데도 맛있음!! 다음에는 말차라떼랑 맛있는 파운드케잌 먹으러 와야지..', 37, 6, 'GOOD', SYSTIMESTAMP);
