INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '로아프 슈페너 고소하고 크림이 맛있네요🫢 다음에도 너다😋 밀크티도 맛있었고, 라즈베리 로아프 케이크도 맛있었어요!! 주문할 때 번호표 가지고가서 자리에 놔두면 가져다주시더라구요!! 그리고 매장에 좌석이 많아서 좋았습니다! 노트북으로 작업하기에도 좋은 것 같아요!', 62, 18, 'GOOD', SYSTIMESTAMP);
