INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '우연히 들어왔는데 공간이 예쁘고 창도 넓어서 꽤 오래 앉아 있다 갔어요. 유자민트차도 적당히 화하고 달달해서 기분 좋은 여유를 즐길 수 있었어요. 추천합니다☺️💕', 78, 12, 'GOOD', SYSTIMESTAMP);
