INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '회사동료분과 또 방문했어요! 나중에는 노트북 가지고 일하러 오고싶어요 풍경이 너무 예쁨.. 직원분들도 친절해요 합정역이랑 가까워서 찾아가기도 좋어요 ㅎㅎㅎ', 90, 17, 'GOOD', SYSTIMESTAMP);
