INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '합정역 근처에 새로생긴 카페 로아프하우스 방문했어요! 내부도 넓고 테라스석도 있어서 여유롭게 이용할 수 있고 분위기도 너무 좋아요🙂 커피, 음료 메뉴도 다양하고 특별한 시그니처 디저트도 있어요👍🏻 올리브 살레 로프케이크 주문했는데 올리브향도 은은하게 나고 짭짤달달 넘 맛나요♥️ 로아프하우스 추천이에요🙂', 70, 16, 'GOOD', SYSTIMESTAMP);
