INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '부산에서 서울 놀러 갔었는데요!! 홍대 쪽에 놀러 갔다가 외국 감성 느낌이 뿜뿜하는 카페를 발견해서 남자친구랑 데이트하고 왔습니다:) 커피향도 너무 좋고 디저트 비주얼도 대박이더라구요! 위에 올라간 크림이 완전 부드러운 우유 생크림이라 더 맛있게 먹을 수 있었어요♡  라즈베리 잼도 가득 올려주셔서 달콤하게 즐길 수 있었습니다♡ 여행가서 힐링 제대로 하고 왔네요:)', 19, 8, 'GOOD', SYSTIMESTAMP);
