INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '합정역 근처에 위치한 노트북 작업 하기 좋았던 로아프 하우스, 주말 이른 시간이라 생각한 11시에 갔는데도 생각보다 사람이 꽤 많았어요. 테라스도 예쁘고 내부 인테리어 분위기도 좋아서 추천해 조용하다 보니 카페에서 독서모임 하는 사람이나 노트북 작업하는 사람이 꽤 많더라규요. 커피가 맛있고 조용해요', 26, 10, 'GOOD', SYSTIMESTAMP);
