INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '외국에 온 것 같은 이국적인 느낌이예요 창이 많아서 트여있고 좀 울리지만 대화하기 좋어요! 창밖에 보이는 나무 때문에 자연친화적 ㅎㅎ 노트북 하시는 분들도 꽤 있더라구요. 직원분들도 친절하십니다 ㅎㅎ 점심시간에 종종 올듯', 29, 10, 'GOOD', SYSTIMESTAMP);
