INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '공간이 크고 쾌적해요 ! 책상이 넓은 공간에 균일하게 놓여 있어 세트장 같기도 하고 새로운 느낌입니다. 커피와 디저트도 맛나고, 늦은 시간 방문하기도 좋았어요 !☕️☁️', 40, 6, 'GOOD', SYSTIMESTAMP);
