INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '신상카페라서 눈여겨보고 있다가 궁금해서 왔습니다. 홍대는 정말 잘하는 카페가 많아서 너무 좋아요💗 오늘 비가 와서 테라스에 앉지는 못했는데 내부 공간이 시원하게 넓어서 좋네요. 블랙과 원목의 느낌이 정갈한 인테리어였고 제가 갔을 때 흘러나오는 음악은 없었는데 공간이 크고 사람이 적당히 있어서 대화하기 좋았어요. 주문한 디저트🧁가 꽤 가격이 있어서 좀 놀랐지만 아이스크림 위에 올리브유라 맛있었어요! 커피맛은 기본형 고소한 맛으로 먹었는데 괜찮았어요~ ☺️', 27, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대 합정 상수 통틀어 주말 주차가 가장 편한 곳!! 5~6대 지하 주차장과 2~3대 측면 주차장이 주말에는 비어 있어요. 뺑뺑 돌다 우연히 들린 멋진 카페. ☕️ 의자도 편하고 공간도 넓고 모던하고 깔끔해서 키워드 5개가 아니라 10개 정도도 너끈히 찍어 줄 수 있는 공간이네요. 비가 부슬부슬 오는 날이라 목련 몽우리 터지는 넓은 창가에  앉아 여유 있게 따뜻한 차를 마시는 기분은 최고!! 정식 오픈하면 주말에 자리잡기 어렵겠어요. 유~~명해지기 전에 자주 와야지~~😊 😃', 85, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '넓고 쾌적하며 깔끔한 내부 공간 거기에 빈티지한 인테리어와 큰 창에서 들어오는 햇살까지 카페 이름처럼 느긋하게 여유를 부리기 정말 좋은 카페이다 커피 맛 또한 수준급이며 산미 있는 원두 선택시 1천원 추가되는게 살짝 아쉽지만 그래도 마셔보면 고개를 끄덕이게 된다. 남녀 분리된 화장실은 상당히 깔끔하고 카페 외부 건물 내부에 위치하고 있어서 오래 머무는 사람들도 걱정 없으며 무료 주차도 가능해서 주변에서 미팅을 하거나 노트북 작업을 하는 사람들 그리고 다른 사람들 신경 쓰지 않으며 커피를 마시며 시간을 보내고 싶은 사람들 모두에게 좋은 카페가 아닐까 싶다.', 111, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '합정역 주변에는 이렇게 세련된 분위기의 카페가 없어서 아쉬웠는데 취향저격❤️ 은은한 조명에 깔끔한 인테리어에 야외 테라스석까지 마포 아니고 외국 같아요😍 고소하고 달콤한 슈페너와 묵직한 로프 케이크가 특히 맛있네요💕', 16, 8, 'GOOD', SYSTIMESTAMP);
