INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '완전 느좋카페의 정석이에요!! 스콘도 너무 맛있었는데 흡입해버리느라 사진을 까먹었네요😅 밀크티에 샷추가했는데 밀크티 향이 진해서 너무 좋았어용 분위기도 좋고 인테리어도 너무 예쁘고 직원분들도 친절하셔서 또 방문하고싶습니당~', 21, 6, 'GOOD', SYSTIMESTAMP);
