INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '일단 야외테라스석 너무 낭만적이고요 ❣️❣️넓은 공간 안에 시원함과 통창으로 개방감이 카페에 들어서는 순간서부터 힐링 그 자체입니다 🍃🌿🌱 친구랑 작업하러 왔는데 집중도 잘되고 넘 좋습니다!', 43, 2, 'GOOD', SYSTIMESTAMP);
