INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '합정역 근처 혼자 시간 보내기 좋은 카페 찾다가 오게 되었어요. 벽 쪽에 붙어 있는 2인석들과 창가 자리 2인, 4인석이 혼자 있기에도, 수다 떨기에도 좋아 보였어요. 인테리어가 유럽풍이면서도 깔끔해서 취향이네요. 창도 깨끗해서 잘 관리하시는 게 느껴졌어요. 직원분도 친절하셨어요. 저녁 식사 전에 방문해서 디저트는 먹지 않았는데 다음에는 커피와 디저트를 먹고 싶어요 ^^ 말차 라떼는 텁텁하지 않고 부드러운 맛이었습니다.', 24, 1, 'GOOD', SYSTIMESTAMP);
