INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '주변이 커피 찐 맛집들인데 새로 생겼길래 방문해봤거든요. 주변 맛집들만큼이나 맛있고 메리트 있습니다. 특히나 공간들이 넓어서 좋아요', 2, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '말차라떼 정말 맛있었어요! 달지 않아 좋구 말차의 쌉싸름함과 우유의 고소함이 조화로와요 입안이 개운하게 마무리~ 멋진 공간과 잘 어울리는 한 잔이었습니다', 4, 0, 'GOOD', SYSTIMESTAMP);
