INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '지나가다가 분위기 있어보여서 갑자기 들어왔는데 해가 잘 들어오고 넓은 좌석이 편안해보여서 강아지랑 잠시 앉아있다 갔어요! 창이 크고 나무가 보여요.', 29, 2, 'GOOD', SYSTIMESTAMP);
