INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '커피 맛있어요! 산미있는 컬러링 블렌드 아이스 아메리카노와 산미없는 아이스 라떼를 마셨는데 둘 다 매우 깔끔한 뉘앙스로 떨어지는게 좋습니다. 특히 근방에 많이 없는 널찍한 인테리어가 아주 편안하네여… 주말 사람 많은 거 보고 나중에 들러야지 했는데 목요일 저녁엔 사람이 별로 없습니다. 독일 더반 떠올렸는디 내부 인테리어가 유럽느낌도 나고 좋습니다…', 39, 8, 'GOOD', SYSTIMESTAMP);
