INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '여기 혼자 차마시기도 좋은데 여러명이 오기도 넘 좋은 카페예요^^ 커피맛도 부드럽고 원두 선택도 가능해요. 테이크아웃시 할인도 해주시더라구요. 오늘은 디저트를 같이 주문했는데. 넘 맛있네요. 합정.홍대 나들이시 꼭 추천드립니다♡', 24, 10, 'GOOD', SYSTIMESTAMP);
