INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '블랙&화이트 톤의 카페를 찾고 있었는데 딱 감성에 맞는 카페를 찾아서 너무 좋았어요!! 음료도 맛있고 매장도 넓어서 합정 오면 자주 이용할 것 같아요', 8, 7, 'GOOD', SYSTIMESTAMP);
