INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '회사 근처에 카페가 큰 곳이 생겼길래 다녀와봤어요ㅣ😊🤎 일단 인테리어부터 공간이 큼직하고 넓더라구요. 아이스아메리카노도 맛이 세개라서 좋았구요!! 깔끔해서 많이 올 것 같습니당. 추천해요!!!  :)', 28, 5, 'GOOD', SYSTIMESTAMP);
