INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '분위기가 좋고 음료들이 다 맛있어서 자주 오게 돼요-! 커피 메뉴도 좋은데 음료들도 맛있어서 좋아요🌱 내부 인테리어도 편안하고 창이 넓어서 힐링이에요', 47, 1, 'GOOD', SYSTIMESTAMP);
