INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '따뜻한 햇살이 가득한 일요일 오후입니다.  향긋한 커피 향이 가득한 로아프커피숍에 앉아 여유를 만끽햄ㅅ 네요.  부드러운 음악과 편안한 분위기 속에서 잠시 모든 걱정을 잊고 쉴 수 있었어요.', 46, 0, 'GOOD', SYSTIMESTAMP);
