INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '케이크가 너무 맛있습니다 😭 커피 원두도 선택가능하고 디카페인도 맛있어서 좋았어요 매장도 넓고 따스해서 비오는날 방문하여 기분좋은 시간 보냈습니다 ㅎㅎ 직원분들도 너무 친절하셔요', 20, 5, 'GOOD', SYSTIMESTAMP);
