INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '라즈베리 로프케이크 주문했는데 비주얼이 너무 예쁘고 커피도 적당히 산미 있어서 너무 좋았어요 카페도 감성있고 편안해서 추천합니다~!!', 92, 25, 'GOOD', SYSTIMESTAMP);
