INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '다 좋은데 매장 안에 손님이 많을 경우, 웅웅거리면서 소음이 심한 편입니다. 그래서 전 들릴 때마다 야외 테이블에 앉죠. 직원 분이 좌석으로 음료를 갔다주시고, 화장실이 청결합니다. 제가 목격한 대부분의 경우 손님이 많았습니다. 연령 대도 다양했고, 인종 또한 그러했죠.', 69, 14, NULL, SYSTIMESTAMP);
