INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '평일 쉬는 날 근처 검색하다 새로운 곳이라 들렀습니다. 블랙과 우드톤이 굉장히 매력적인 곳이네요. 주변에 추천하고 종종 들릴게요~', 38, 1, 'GOOD', SYSTIMESTAMP);
