INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피도 맛있고 분위기도 좋아요.! 디저트도 맛있어 보여요. 주차자리가 남아 있어서 주차도 편하게 했어요. 스탭분들 친절하시고 다음에 또 방문하려구요', 54, 14, 'GOOD', SYSTIMESTAMP);
