INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '로아프 인테리어도 너무 예쁘고, 커피도 맛있고 친절하셔서 좋았습니다. 라떼를 시켰는데 라떼의 양도 적절히 크고 좋았어요. 요즘 카페들 양 적으면 실망스러울 때가 많은데.. 또 방문하겠습니다!', 50, 7, 'GOOD', SYSTIMESTAMP);
