INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '로아프 슈페너 너무 꼬숩고 깔끔해요~ 케익도 너무 달지않고 크림이랑 잘 어우러져서 맛있습니다~ 카페가 넓은데도 아늑한 분위기가 나서 매력적이예요! 또 갈게요~ 2호점 축하드립니다👍', 103, 24, 'GOOD', SYSTIMESTAMP);
