INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '집 부근에 새로 생긴 카페라 방문해 보았어요. 인테리어 덕분인지 호주의 어느 로스터리에 방문해서 여유로운 시간을 보내는 듯합니다. 원두를 선택할 수 있어 마음에 들어요.', 30, 7, 'GOOD', SYSTIMESTAMP);
