INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '합정에 커피맛집이 새로 생겼네요! 라떼 넘 고소하고 맛있어요🥹 케이크도 생크림이랑 퓨레조합이 미쳤어요! 빵은 촉촉하고 퓨레는 상큼 달콤한게.. 줄어드는게 아쉽네요 다른 디저트도 궁금합니다 ! 또 올게요 ☕️🤎', 75, 17, 'GOOD', SYSTIMESTAMP);
