INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '라즈베리 케이크 먹고 맛있어서 또 왔어요! 올리브 살레 케이크 궁금했는데 단짠단짠 넘 맛있네용 바닐라아이스크림에 올리브오일+소금 조합이 고급집니당 ㅎㅎ 빵에도 올리브가 콕콕 박혀있어요 올리브 극호로써 완전 제 스타일이에요 ! 잘먹었습니당 !!~', 33, 8, 'GOOD', SYSTIMESTAMP);
