INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '카야샌드위치가 맛있는 집인데, 친구때문에 와보았다가 지금은 제가 다른 지인들이나 친척들을 데리고 오는 카페가 되었습니다😂 친구가 수란을 못먹어서 이 날은 일반 카야샌드를 시켰는데, 싱가폴식 수란+간장에 찍어먹는 조합을 좋아하고 추천합니다!', 26, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '푸릇푸릇한 창밖 풍경이 보이는 2층 카페. 특색있는 싱가폴 음료와 디저트가 있는 이곳은 다른 곳과 대체할 수 없는 매력이 있는 곳이라 좋아요. 2번째 방문인데 디저트가 특히 맛있어요 ㅎㅎ 판단케이크도, 카야토스트도 아주 맛있습니다🥰🪴', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '밀크티랑 코코넛커피 모두 맛있었어요. 분위기도 싱가포르 느낌의 인테리어와 영상같은 것들이 재생되고있어서 독특했습니다. 다음 방문엔 디저트 종류들 맛보고 싶네요.', 112, 21, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '이렇게 뷰가 좋으면서 싱가폴현지 맛이 느껴진다는 특별한 카페가 있다는걸 몰랐네요🥹👍 정말 맛있게 먹었어요! 사장님들중 한 분이 싱가폴분이신것 같더라구요! 싱가폴 수상분들이랑 대사관 직원들도 싱가폴 커피랑 디저트 드시러 오시는  곳이래요! 싱가폴식 아침식사인 반숙계란+간장과 카야잼이 발린 토스트 세트는 꼭 드셔보세요! 처음에는 낯설었지만 한국인 입맛에도 잘 맞고 맛있었어요😋👍 반숙계란도 2개나😍 넣어주신답니다! 계란에는 단백질이 많은데, 단백질 보충도 되는 (그것도 계란 2개) 간단하면서도 건강고 가벼운 식사로 좋았어요 평소에 계란 1개도 챙겨먹기 힘드니까요! 커피도 싱가폴식 커피도 맛있게 먹었어요 무엇보다 뷰가 너무 좋아서🥰 영화같은 주말브런치를 즐길 수 있었어요 지인들 데리고 또 와보고싶어요😍', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
