INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '몰튼(라바초코?)랑 차절반인거 원앙 먹었는데 맛있었어요 또오고싶어요 라바초코는 밑에 고체연료있어서 따뜻하고 초코케잌이랑 바나나랑 뭐랑들어있는건데 신기하고맛잇어요', 16, 8, NULL, SYSTIMESTAMP);
