INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '남편이랑 싱가폴 여행이 생각날때마다 가는 카페에요 ☕️ 커피랑 카야토스트도 너무 맛있지만 큰 창문에 시원한 뷰가 맘에 들어서 가기도 해요~~ 저번에 갔을때 싱가폴 라디오? 유튜브? 같은걸 틀어놓으셔서 진짜 싱가폴에 있는거 같았는데 이번에는 그냥 뉴에이지 틀어놓으셨더라구요 ㅎㅎㅎ 계속 라디오 틀어주시면 더 재밌고 좋을거같아요 🤎', 41, 7, NULL, SYSTIMESTAMP);
