INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '홍대한복판에??????? 디저트 맛도리!!!!! 싱가폴 와있는줄 알았어요!! 안에 분위기가 그냥 현지에요!! 너무 자연스러운 오래된 현지카페느낌! 음료는 말할것도 없고 ㅠㅠ 토스트랑 초코들어간 디저트인데 너무 맛있어요!! 자주가면 살 많이 찔것같긴한데 ㅎㅎ 행복행복!! 또 들릴께용 ㅎㅎ', 68, 13, 'GOOD', SYSTIMESTAMP);
