INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '자몽의 상큼함과 아이스크림의 부드러움이 너무 잘어울렸던 빙수! 계속 생각나는 맛이에요. 나가면서 밀크코피를 포장해서 갔는데 달달하고 고소해서 좋았습니다', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '싱가포르 여행 이후 싱가포르 디저트가 아른거려서 찾다가 발견한 곳. 홍대를 열심히 돌아다녔어도 이런 카페가 있었다는 걸 몰랐는데 역사가 깊더군요,, 커피는 굉장히 진한 맛이고 코코넛코피는 과육도 씹히고 코코넛맛도 많이 나서 좋았어요. 커피의 미적지근한 온도가 좀 아쉬웠음ㅜ 반숙계란+카야토스트 아주 맛있습니다.. 싱가포르보다 식빵도 두껍고ㅋㅋ 카야잼+버터도 두껍게 발려있어요. 잼에서 코코넛맛이 많이 나서 전 만족. 반숙계란에선 비린내 안 나서 좋았어요. 판단 케이크,,,!! 사실 판단 관련 음식에서 판단 맛 잘 못 느껴서 재도전했는데 여전히 모르겠음.. 구수한 맛이 판단 맛인 거 같음. 굉장히 폭신폭신하고 부드럽고 맛있는 파운드케이크, 양도 많고 코코넛맛+과육 식감이 좋았어요. 코코넛처돌이의 행복 여기 있다', 24, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '판단 쉬폰. 촉촉이 아니라 축축이 아닐까 싶을 정도로 아주 보들보들하고 살살 녹는다. 크림도 맛있지만 좀 달아서 단독으로 먹기에는 크림 없는 쪽도 좋다. 튀는 맛은 아니지만 은은한 코코넛향과 극강의 촉축함으로 가족들을 홀렸다. 멀지만 재방문하고 싶다.', 20, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '정말 최고! 싱가포르 카페가 있어서 정말 좋고 이 가게를 발견하게 되서 정말 다행이에요~!! 앞으로 여기는 종종 방문할 예정입니다 😊 홍차도 커피도 온도가 알맞고 정말 맛있었어요 최고~☺️', 53, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '카야토스트가 먹고 싶을 때 가는 곳입니다. 하나만 먹어야지 마음 먹고 가도 매번 추가 주문해요.. 카야 토스트 넘 맛있습니다.', 39, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '근처에 갈일 있어서 두리번거리다 얼결에 들어간 곳인데요, 첨 먹어본 코코넛판단케이크 ㅡ 플레인으로 먹었는데 이거 요물이에요! 슴슴한 맛 같은데 계속 들어가요! 전 심지어 카스테라 같은 폭신한 식감 별로 안좋아하는데도.. 반했습니다ㅎ 카야토스트는 익숙한 맛이지만ㅡ단팥추가 해서 먹었더니 더 꿀맛♡', 44, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), 'If you''re craving Kopi-o or Singaporean snacks or dessert, this is the place! Came here for the 2nd time, kopi-o and yuan-yang taste like home. Had kaya toast and pandan cake on the previous visit and it exceeded my expectations. The owners are super nice and the food is house-made. Their homemade tang yuan is a gem. Worth a try! Will definitely come again!', 72, 13, 'GOOD', SYSTIMESTAMP);
