INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '여러 차례 왔었지만 올 때마다 밀크티와 떼씨를 헷갈려서(본인잘못) 제가 헷갈리지 않으려고 쓰는 리뷰 ! 카페 알바를 해본 사람으로서, 메뉴 설명만 봐서는 그 차이를 확실하게 알기 어려웠거든요. 밀크티도 홍차를 우유에 우려서 시럽 또는 설탕과 함께 만들어내는 음료로 알고 있는데 떼씨도 차에 우유를 농축해서 넣은 음료..라고만 적혀있어서..! 직접 먹어보고 판단하려고 둘 다 시켜놓고 비교 해봤어용 🫖밀크티 첫번째 사진이 밀크티. 육안으로 봤을 때도 확실히 색이 진하고 맛도 엄청 달아요! 베이스는 얼그레이 아니고 아쌈(정확하지 않음)류인 것 같아요. 달고 쌉싸름한 맛! 🫖떼씨 떼씨는 밀크티에 비해 더 무겁고 단맛이 현저히 적어요. 고소한 우유의 맛이 더 잘 느껴짐! 단 밀크티가 부담스러울 때 먹기 좋아요🤎', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '카페에 들어선 순간 싱가폴 여행온줄 알았어요ㅋㅋㅋ 분위기도 괜찮고 음료도 맛있고 특히 카야토스트 존맛!! 다음에 또 방문하고 싶네요 ㅎㅎ', 36, 3, 'GOOD', SYSTIMESTAMP);
