INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '크림판단케이크, 코코아 커피, 바나나망고주스 먹었어요! 제가 가본 카페들 중 음료와 디저트 둘 다 맛있는 몇 안되는 특별한 곳이었어요. 보통 카페가면 음료가 맛있으면 디저트가 별로고 디저트가 맛있으면 음료가 별로인데 이 두 마리 토끼를 모두 잡은 곳이 바로 디저트 머라이언!!!! 특히 싱가폴 케이크인 판단케이크 궁금해서 먹어본 건데 지금까지 먹어본 쉬폰 케이크 중 제일 맛있었습니다 😋 진짜 진짜 부드럽고 쫀쫀한 이 식감을 어디서도 맛본적이 없어요. 원래 크림 없는게 오리지널이라고 하셨는데 저는 크림 추가한 거 너무너무 만족했어요. 왜냐면 크림도 처음 먹거본 질감인데 넘맛... 사장님 오래오래 장사해주세여!!!!!!', 45, 6, 'GOOD', SYSTIMESTAMP);
