INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '🎈홍대에서 자리있는 카페 찾다가 우연히 발견해서 반한 싱가폴 카페 🎈싱가폴커피 존맛. 일반 아메보다 산미, 탄맛, 쓴맛 적고 깔끔한 스타일 🎈2번째 방문인데 홍대온김에 온 것도 있고 진짜 커피맛이 생각나서 재방문함', 22, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '첫방문이었는데 판단 케이크가 너무나 제 취향이었어요!!! 이럴 줄 알았으면 케이크 한 판 미리 예약할 걸 후회할 정도로 맛있어요. 크림 추가하지 않아도 맛있습니다. 별로 달지 않고 코코넛 특유의 식감이 판단 케이크의 맛을 더 살려줘요. 카야 토스트도 당연 맛있었고요. 아보카도 쉐이크의 맛이 궁금해서 이것도 시켜봤는데 괜찮았어요! 생전 처음 먹어본 맛이라 정말 신기한 경험이었답니다ㅋㅋㅋ 약간 느끼해서 달고 느끼한 것에 면역있는 분들은 한 번 쯤 도전해보셔도 나쁘지 않을 것 같아요~', 81, 17, 'GOOD', SYSTIMESTAMP);
