INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '야자수 음료 너무 맛있어요. 👍🏻 살면서 처음 느껴보는 극강의 부드러운 음료입니다… 밑에는 달콤한 팥? 시럽이 깔려있고 그 위에는 무겁지만 가벼운 크림 제형의 음료가 들어있는데요ㅡㅡ 전혀 느끼하지 않고 적당히 달콤한 맛인데.. 이거 말로 표현을 못 하겠네요.. 너무 맛있어요.👍🏻', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '주말에 홍대 사람 엄청 많아서 카페 4-5군데 돌다가 자리있길래 오게 된 곳이에요. 싱가폴 커피 판매하는 곳이라 생소하긴한데 사장님도 친절하시고, 이색 메뉴들이 많아서 좋았어요!! 코코넛 라떼가 겁나 진했다는거(처음에만) 제외하고는 분위기도 맛도 이색적이라 좋았습니당', 57, 18, 'GOOD', SYSTIMESTAMP);
