INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '항상 기웃대기만 하고 오늘 처음 가봤는데 완전 제대로 카페에 진심인 곳이었네요.!.!! 카야토스트 존존존맛이고 포멜로 빙수도 너무 맛잇고 커피도 맛잇었어요. 더더 다양하게 전메뉴 먹어보고 싶어요 재방문 완전완전 무조건!!', 1, 4, 'GOOD', SYSTIMESTAMP);
