INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대 온 김에 카페 검색하다가 특별한 싱가포르 메뉴들을 판매하고 있길래 방문했어요! 싱가포르 여행가서 먹었던게 생각나더라구요 😋  카야토스트 반숙에 찍어먹으니 꿀맛이고 코코넛 커피도 찐이었어요 🥥  조만간 또 갈거랍니다 🔥', 0, 0, 'GOOD', SYSTIMESTAMP);
