INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '싱가포르에 살면서 카야토스트 반숙계란이랑해서 많이 먹었었는데ㅜㅜ 추억의 음식을 한국에서도 먹을수 있어서 너무 좋았어요ㅠㅠㅠㅠ 최고', 37, 0, 'GOOD', SYSTIMESTAMP);
