INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '✅특이한 메뉴가 많음..너무 다양해서 고르는게 힘들 정도였음 ✅싱가폴 현지의 느낌이 나는 인테리어와 메뉴판이 인상적이었음(주인분도 싱가폴 분이신 것 같음!!) ✅블랙코피 푸딩은 진한 커피맛이 나는 약간 투명한 느낌의 푸딩이 밑에 깔려있고, 위에는 고소하면서 달달한 크림이 올려져 있어서 조화가 참 좋았고 맛있게 먹었음! (현지를 가본 적은 없지만 현지의 맛이 아닐까 싶었음) ❎가격은 전반적으로 약간 비쌈 ❎화장실은 별로니까 급한거 아니면 가지 마시길..!! 카야토스트와 밀크티 등 다른 메뉴들 먹어보기 위해서라도 재방문 의사는 무조건 있습니다!', 17, 1, NULL, SYSTIMESTAMP);
