INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '옛날 생각, 향수를 불러일으키는 공간. 그리고 그에 부합하는 아기자기한 디저트들과 음료들•°•°* 하나부터 열 가지 손과 공을 많이 들여서 깊고 진한 맛의 식음료들을 만드시는 것 같아요. 묘하게 마음이 놓이는 곳이라서 종종 들리고 싶어요', 45, 2, 'GOOD', SYSTIMESTAMP);
