INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), 'ㅠㅠㅜㅠㅠ너무맛잇어여 얇은카야토스트 찾다가 알게됐는데 신기한 메뉴도 넘 많고 카야토스트 미쳐미처~~!! 포멜로빙수도 넘마식고ㅠ단점은 메뉴 나오는데 좀 오래걸림 캬캬 다음엔 3개먹어야지~!!', 211, 45, 'GOOD', SYSTIMESTAMP);
