INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '카야토스트&달걀2개 세트 넘 맛있어요~~!! 담에 또 오고 싶은 맛😋 근데.. 코피C 는 조금 실망..ㅠㅠ 묽어서 싱거웠어요... 담엔 토스트랑 기본 코피으로 먹어봐야겠어요!', 34, 1, 'BAD', SYSTIMESTAMP);
