INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '푸딩 트라이플과 아보카도 쉐이크 맛있었어요!!!😋 아보카도 쉐이크는 밑에 흑당? 같은 것과 섞어 먹는 건데 아보카도랑 흑당이 꽤 잘 어울리더라구요. 사장님도 친절하시구요ㅎㅎ', 18, 3, 'GOOD', SYSTIMESTAMP);
