INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '특별한 맛도 아니고 메뉴도아닌데 한끼 밥값 수준이네요 걍 밥사먹겠습니다 외국음식이라면 스트리트푸드도 고급으로 가격 책정하는 태국식당이랑 같네요', 22, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '비도오고  카페에앉아 커피한잔의여유를  갖고싶어 합정카페 카페레터합정 방문🥰1층에 위치 넓은창과  조용한분위기가  혼자서도 여유롭게  시간보내기에 안성 맞춤카페이네요ㆍ 오늘에뉴는 바질에이드와 플랫화이트   크로와상주문했는데 커피맛도 향도좋고고소함이 크로와상과 찰떡조합🥰이고베이커리종류도 다양하고 빵이 다른곳보다 맛있어서  대만족🩵💙카운터근처에  굿즈도 판매하네요🥰에코백 머그컵  접시  빵포장해서 선물하기 좋은컨셉이네요ㆍ 직원분도 친절합니다 요즘은 자기만의 컨셉트있는곳이  인기가 있네요ㆍ 합정역 5분거리라  찾아가기 편해요😍', 9, 10, 'GOOD', SYSTIMESTAMP);
