INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '감성적인 인테리어가 너무 맘에 드는곳이에요.  크로와상 샌드위치는 바삭하고  속이 알차요. 한입 무는 순간 신선함이 입안에 가득하면서 너무 달지 않고 정갈한맛  그 맛이 딱~! 이였어요. 분위기 좋은 카페에서 고급진 향의 커피음료와 맛있게 먹을 수 있었어요', 9, 6, 'GOOD', SYSTIMESTAMP);
