INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '요즘 일이 힘든지 달다구리 디저트가 너무 땡겼는데, 친구랑 간곳에 따악 내스타일의 디저트들이 와웅!!!!!!!!!!!! 안에 내용물도 그득한것이 여기 내 단골집 될듯. 커피류도 맛있고, 디저트도 장난아닌곳, 직원분들도 친절하고 머물면서 이야기 나누기 좋은곳.', 55, 13, 'GOOD', SYSTIMESTAMP);
