INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '카페레터 좌석 예약하고 친구랑 다녀왔어요!  핫초코가 진하고 달콤해서 커피 못 마시는 분들도 만족하실 거예요 ㅎㅎ커피가 맛있어요 대신 핫초코로 극찬! 디저트 세트는 비주얼도 예쁘고 맛도 훌륭해서 디저트가 맛있어요! 빵이 맛있어요! 직원분들이 친절해요 사진 찍기 좋은 자리도 추천해주셔서 감사했어요! 조용하고 아늑한 분위기 덕분에 대화도 편하게 나눌 수 있었어요ㅎㅎ', 43, 2, 'GOOD', SYSTIMESTAMP);
