INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '디저트가 맛있으면 커피가 좀 떨어지는데가 많은데 빵도 최고 라떼는 완전 맛있고 커피도 원두 종류가 많아서 골라마실 수 있어서 좋았습니다 ! 아니 근데 샌디치에 누꼴라 잠봉 최고애요 소스도 맛있고 ㅎㅎ 1개 시켯다가 하나 더 시켜서 먹었어욬ㅋㅋ', 1, 5, 'GOOD', SYSTIMESTAMP);
