INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '지나다닐때마다 사람이 항상 많았던 카페였는데 , 그래서 궁금해서 방문!!빵 종류도 다양하고 가격도 나쁘지 않아서 아메리아노에 달달한 뱅오쇼콜라? 이거 시켜서 같이 냠냠 직원분들도 친절하시고 디저트 커피 다 너무 맛이었다.', 64, 18, 'GOOD', SYSTIMESTAMP);
