INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '커피 원두 직접 고를수있어서 좋았어요!! 빵이 진짜 맛있었어요. 소금빵 좋아해서 먹었는데, 가격도 좋고 맛도 bb!! 배불러서 이것저것 시키진 못했는데 담에 오면 다른빵도 꼭 여러개 먹어볼꺼에요~~직원분도 친절하시고 재방문 의사 뿜뿜~~', 84, 17, 'GOOD', SYSTIMESTAMP);
