INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '결이 살아 있는 페이스트리가 먼저 시선을 끌었어요. 초콜릿이 드리즐된 빵을 베어 무니 바삭함이 그대로 전해졌고, 아이스커피 한 모금 곁들이니 조화가 괜찮았어요. 나무 테이블 위에서 느긋하게 쉬어가는 기분이 들었네요.', 88, 11, 'GOOD', SYSTIMESTAMP);
