INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '겹겹이 살아 있는 크루아상 결이 먼저 눈에 띄었어요. 위에 올라간 크림이 깔끔하게 포인트가 되어 더 먹음직스럽게 느껴졌네요. 전체적으로 플레이팅이 정돈되어 있어서 베이커리 메뉴 즐기기 좋았어요.', 132, 81, 'GOOD', SYSTIMESTAMP);
