INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '진열대에서 아몬드 크루아상이 가장 먼저 눈에 들어왔어요. 겹겹이 살아 있는 결이 보여서 고르게 됐고, 빵 위에 아몬드 슬라이스가 듬뿍 올려져 있는 게 인상적이었네요. 매장 안에서 편하게 한 조각 맛보며 잠시 쉬어가기 좋았어요.', 70, 16, 'GOOD', SYSTIMESTAMP);
