INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '굿즈 코너에 티셔츠랑 에코백이 가지런하게 걸려 있어서 한 번씩 둘러보게 됐어요. 우드 소재 덕분에 전체 공간이 더 따뜻하게 느껴졌네요. 커피랑 브런치까지 여유 있게 즐기며 시간 보내기 좋았어요.', 30, 2, 'GOOD', SYSTIMESTAMP);
