INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '우드 테이블 덕분에 전체적으로 따뜻한 분위기가 느껴졌어요. 크루아상 위에 크림이 올라가 있어서 먹기 전에 먼저 시선이 갔고, 아이스 커피랑 같이 곁들이니 조합이 잘 어울렸네요. 한적한 공간에서 여유롭게 디저트 즐기기 좋았어요.', 5, 3, 'GOOD', SYSTIMESTAMP);
