INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '베이커리마다 식감이 달라서 하나하나 천천히 맛볼 수 있었어요. 샌드위치와 초콜릿 디저트 조합이 잘 어울렸고, 커피와 곁들이니 더 여유롭게 즐겼네요. 전체적으로 베이커리 구성이 알차서 만족스러웠어요.', 7, 2, 'GOOD', SYSTIMESTAMP);
