INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '따스한 햇살이 테이블을 비추는 오후, 조용히 앉아 여유를 즐겼어요. 디저트 한 조각이 깔끔하게 담겨 있어서 자연스럽게 포크를 들게 되더라고요. 차분한 분위기 덕분에 천천히 머물다 나오기에 좋았어요.', 91, 20, 'GOOD', SYSTIMESTAMP);
