INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '테이블 위에 빵이랑 아이스커피가 깔끔하게 세팅돼 있어 시작부터 기분이 좋아졌어요. 빵마다 겉모습이 뚜렷하게 달라서 고를 때 재미가 있었고, 음료랑 같이 두니까 조합이 자연스럽게 어울리더라고요. 디저트 먹으면서 끝까지 편하게 머물 수 있어서 만족스러웠어요.', 116, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '나무 테이블 질감 덕분에 전체 분위기가 한층 더 편안하게 느껴졌어요. 샌드위치 속 재료가 선명해서 한 입 먹기 전에 신선함이 먼저 느껴졌고, 라떼 위에 그려진 아트가 자연스럽게 눈을 끌더라고요. 조용한 공간에서 여유롭게 브런치 즐기기에 딱 좋았네요.', 42, 0, 'GOOD', SYSTIMESTAMP);
