INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '나무 테이블 위에서 여유로운 분위기가 느껴졌어요. 샌드위치 속 재료가 다양하게 어우러져 한 입마다 조화로웠고, 라떼 위에 그려진 아트가 자연스럽게 시선을 끌더라고요. 든든하게 한 끼 채우기에 부담 없었어요.', 1, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '야외 쪽 통창으로 들어오는 햇살이 정말 예뻤습니다. 넓은 창 덕분에 카페 전체가 환하고 시원한 느낌이 들었고, 바깥 풍경을 보며 커피를 마시니 마치 여행 온 듯한 기분이었어요. 사진 찍기 좋은 포인트가 많아 ''감성 카페''라는 이름이 딱 어울렸습니다. 🌿☕', 21, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
