INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '갓 구워낸 듯 따뜻한 빵이 접시에 담겨 나오는데, 보기만 해도 기분이 좋아졌습니다. 하나는 담백하고, 하나는 달콤해서 커피 없이도 충분히 맛있게 즐길 수 있었어요. 소박하지만 정성스러운 맛이 느껴지는 빵이었습니다.', 58, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '트레이에 가지런히 놓인 디저트랑 아이스커피가 딱 보기 좋았어요. 나무 테이블도 깔끔하게 정돈돼 있어서 한결 단정한 분위기로 느껴졌고, 디저트의 부드러운 식감에 커피까지 곁들이니 여유롭게 즐기기 괜찮았네요. 조용한 공간 덕분에 편하게 머물 수 있었던 점도 좋았어요.', 31, 9, 'GOOD', SYSTIMESTAMP);
