INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '야외 테라스 분위기라 한층 더 편하게 머물렀어요. 겉이 바삭하게 구워진 디저트라서 한입 먹을 때 식감이 또렷하게 느껴지더라고요. 초콜릿과 버터 풍미가 입안에 조화롭게 퍼져서 여유롭게 쉬는 시간이 자연스럽게 이어졌네요.', 75, 16, 'GOOD', SYSTIMESTAMP);
