INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '빵 종류가 다양해서 고르는 재미가 있었어요. 겉에 소금이 뿌려진 빵과 슈가파우더 올라간 크루아상이 각각 느낌이 달라 보여서 눈길이 갔네요. 깔끔하게 담아줘서 한결 정돈된 분위기였고, 나무 테이블 덕분에 한동안 편하게 쉬고 올 수 있었어요.', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '크루아상에 햄, 치즈, 채소가 골고루 들어가서 한 입에 다양한 조합이 잘 느껴졌어요. 겹겹이 살아있는 빵의 결이랑 신선한 재료가 어우러져서 씹는 재미가 있었네요. 나무 테이블 위에 담긴 플레이팅이 깔끔해서 더 기분 좋게 식사할 수 있었고, 먹고 나니 든든하게 배도 잘 채워졌어요.', 25, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '베이커리 위에 듬뿍 뿌려진 고운 가루 덕분에 한눈에 들어오는 비주얼이었어요. 깔끔한 테이블과 조용한 분위기가 잘 어울려서 잠깐 쉬어가기 좋았네요. 적당한 크기의 디저트라서 여유롭게 음료랑 같이 맛볼 수 있었어요.', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '유리컵에 담긴 파르페가 보기만 해도 신선하게 느껴졌어요. 진한 초코와 베이커리 조합 덕분에 한 번에 여러 가지 맛을 즐긴 느낌이었네요. 테이블 위가 넉넉해서 여유롭게 메뉴를 즐길 수 있었고, 디저트 구성 자체가 다양해서 다음에 또 새로운 걸 먹어보고 싶어졌어요.', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '베이커리 종류가 골고루 준비돼 있어서 고르는 재미가 있었어요. 디저트마다 조합이 달라서 먹는 재미가 쏠쏠했고, 접시에 담긴 플레이팅이 정돈돼 있어서 한결 깔끔하게 느껴졌네요. 커피랑 곁들여 먹으니 만족스럽게 마무리됐어요.', 360, 53, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
