INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '따뜻한 자연광이 크게 들어와 앉아 있는 내내 편안했어요. 창밖 풍경이 넓게 보여서 한참 바라보게 됐고, 나무 가구와 작은 식물들이 어우러져 분위기가 아늑하게 느껴졌네요. 디저트랑 커피 곁들이면서 조용히 쉬기 딱 좋았어요.', 42, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '나무 테이블의 결이 은근히 아늑하게 느껴져서 편안했어요. 빵 겉면이 반질반질해서 손끝에 질감이 잘 느껴지고, 모양도 정갈해서 시선이 갔네요. 아이스 커피랑 조용히 곁들이는 동안 한참 여유롭게 쉬다 왔어요.', 28, 0, 'GOOD', SYSTIMESTAMP);
