INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '야외 테이블에 앉으니 초록 잎 사이로 자연이 바로 느껴져서 좋았어요. 크루아상 샌드위치에 신선한 재료가 넉넉하게 들어가서 든든했네요. 라떼랑 아이스 커피 번갈아 마시니까 브런치로 분위기까지 제대로 챙겼어요.', 24, 6, 'GOOD', SYSTIMESTAMP);
