INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '베이커리 종류가 여러 가지라 고르는 재미가 있었어요. 접시에 담긴 플레이팅이 깔끔해서 식탁 위가 한결 정돈돼 보였고, 아이스 커피랑 시원한 라떼도 디저트와 잘 어울렸네요. 넉넉한 테이블에 앉아 여유롭게 시간 보내기 좋았어요.', 14, 2, 'GOOD', SYSTIMESTAMP);
