INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '테이블에 앉으니 여유롭게 주변을 둘러볼 수 있었어요. 파르페 스타일 디저트가 통유리잔에 담겨 있어 시선이 먼저 갔고, 과일 토핑이 깔끔하게 어우러져 입안에서 재밌게 느껴졌어요. 차분한 분위기 덕분에 브런치 시간 내내 편하게 쉬었네요.', 11, 2, 'GOOD', SYSTIMESTAMP);
