INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '이런 디저트 카페가 동네에 있어서 얼마나 다행인지 몰라요ㅎㅎ 촉촉한 빵에, 부드러운 라떼커피 크림이 입안에서 사르르 녹아요. 커피도 전문적으로 내려주셔서 향부터 맛까지 완성도가 높아요. 조용히 책 읽거나 데이트 코스로도 딱이에요.', 98, 23, 'GOOD', SYSTIMESTAMP);
