INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '진열대 앞에서 고르느라 한참 고민했어요. 빵마다 결이 살아 있어서 고유의 질감이 잘 느껴졌고, 플레이팅이 정돈돼 보여서 처음부터 눈길이 갔네요. 머그잔에 커피 담아서 여유롭게 쉬기 좋았어요.', 7, 10, 'GOOD', SYSTIMESTAMP);
