INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '테이블이 넓어서 혼자 앉아 여유롭게 샌드위치와 커피를 즐길 수 있었어요. 샌드위치 속 재료가 넉넉하게 들어가 한 끼로도 충분하다는 생각이 들었고, 조용한 분위기 덕분에 천천히 머무르며 쉬어가기 좋았네요.', 51, 12, 'GOOD', SYSTIMESTAMP);
