INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '야외 테이블에 앉으니 자연광이 들어와 분위기가 한층 더 편안하게 느껴졌어요. 초콜릿이 듬뿍 올라간 베이커리랑 아이스 커피 조합이 잘 어울렸네요. 여유롭게 디저트 즐기기에 딱 좋은 시간이었어요.', 0, 5, 'GOOD', SYSTIMESTAMP);
