INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '여러 가지 좌석이 마련돼 있어서 취향 따라 고를 수 있었어요. 창가 쪽에 앉으니 자연광이 넓게 들어오고, 바깥 풍경도 한눈에 보여서 분위기가 편안하게 느껴졌네요. 주변이 조용해서 대화에 집중하기 좋았고, 전체적으로 깔끔하게 정돈된 실내가 인상적이었어요.', 28, 3, 'GOOD', SYSTIMESTAMP);
