INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '트레이 위에 깔끔하게 나온 브런치 구성이 한눈에 들어와 만족스러웠어요. 크루아상 샌드위치 속에 햄, 치즈, 토마토가 한 겹씩 어우러져서 먹는 내내 재료 조합이 잘 느껴졌네요. 원목 테이블 덕분에 편안하게 머물 수 있었고, 아이스커피랑 곁들이니 천천히 여유를 즐기기 좋았어요.', 90, 13, 'GOOD', SYSTIMESTAMP);
