INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '나무 테이블에서 여유롭게 머무를 수 있어서 좋았어요. 라떼 아트가 예쁘게 올라가 있어 한 번 더 눈길이 갔고, 크루아상 샌드위치 속 채소랑 토마토가 신선하게 어울렸어요. 초코 베이커리까지 곁들이니 각각의 조합이 잘 맞았네요.', 17, 2, 'GOOD', SYSTIMESTAMP);
