INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '진열대 앞에서 한참 고민하다가 베이커리 종류가 다양해서 고르는 재미가 있었어요. 겉이 반짝이는 디저트부터 담백한 느낌의 빵까지 선택지를 직접 비교하며 즐겼고, 조용한 공간 덕분에 앉아서 천천히 디저트와 커피를 함께 마무리할 수 있었네요.', 116, 23, 'GOOD', SYSTIMESTAMP);
