INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '빵을 하나씩 집어 먹으면서 결이 살아 있는 식감이 달라서 비교하는 재미가 있었어요. 초콜릿이 입에 먼저 닿아 기분 좋았고, 마지막에 아이스커피로 깔끔하게 마무리하니 여유로웠네요. 테이블이 넓어서 빵이랑 커피 즐기기 편했어요.', 57, 16, 'GOOD', SYSTIMESTAMP);
