INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '크루아상 샌드위치 안에 토마토랑 채소가 넉넉하게 들어 있어서 한입 먹을 때마다 신선함이 느껴졌어요. 초코 크루아상은 위에 토핑이 올려져 있어 달콤하게 즐기기 좋았고요. 우드 테이블 덕분에 전체적으로 차분하게 머무를 수 있었네요.', 39, 8, 'GOOD', SYSTIMESTAMP);
