INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '우드 트레이에 정돈된 빵과 음료가 단정하게 담겨서 보기 좋았어요. 빵 겉면에 결이 살아 있고, 초콜릿 장식이 눈에 띄어서 자연스럽게 손이 갔네요. 아이스커피와 함께 천천히 즐기니 조용하게 머물기 딱이었어요.', 37, 7, 'GOOD', SYSTIMESTAMP);
