INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '카페 분위기나 테이블 구성도 너무 예쁘고 디저트며 브런치며 감각이 딱 제 취향이었어요 음료도 쓴맛 없이 부드러워서 좋았구요 가게 전체가 무드있고 센스 있어서 눈이 계속 갔어요 사진 잔뜩 찍어서 친구들이 어디냐고 난리였네요ㅋㅋㅋㅋㅋㅋ', 30, 0, 'GOOD', SYSTIMESTAMP);
