INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '진열대에 각기 다른 베이커리가 가지런히 놓여 있어서 고르는 재미가 있었어요. 층층이 살아 있는 크루아상 비주얼에 먼저 눈이 갔고, 직접 골라 트레이에 담으니 더 특별하게 느껴졌네요. 겉면 결이 살아 있어 보기만 해도 식감이 기대돼서 만족스러웠어요.', 28, 0, 'GOOD', SYSTIMESTAMP);
