INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '테이블이 깔끔하게 정돈돼 있어서 바로 편안해졌어요. 주변도 조용해서 아이스커피랑 크루아상 여유롭게 즐기기 좋더라구요. 디저트랑 커피 조합이 부담 없이 잘 어울렸고, 오랜만에 조용히 쉬다 온 느낌이에요.', 28, 1, 'GOOD', SYSTIMESTAMP);
