INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '우드톤으로 꾸며진 공간 덕분에 자연스럽게 기분이 차분해졌어요. 접시와 컵이 깔끔하게 놓여 있어서 더 기분 좋게 시작했네요. 크루아상 샌드위치는 결이 살아있어 씹는 재미가 있었고, 라떼가 부드럽게 마무리해줬어요.', 43, 1, 'GOOD', SYSTIMESTAMP);
