INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '여러종류의 크로와상이 있어서 하나씩 맛보고있는데 이 크로와상이 저에겐 딱 맞네요 매우 맛있고 커피도 맛있고 여러모로 좋았숨미당><', 24, 0, 'GOOD', SYSTIMESTAMP);
