INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '책읽기 좋은 공간이라 가끔 오게됩니다 디저트종류도 많아 중간에 맛나보이는 빵골라서 먹어주며 책읽다보면 시간 훌쩍가네요 가끔시끄러운곳 벗어나서 나만에 시간 찾을 때 오게되는 그런공간이랄까요^^', 24, 8, 'GOOD', SYSTIMESTAMP);
