INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '매장 아주 잘 꾸며놓고 분위기가 좋아요! 다양하게 먹을 것도 많고 빵이 많아서 좋았어요 브런치로 먹으로 가도 무방할 정도로 맛있고 최고에여!', 67, 12, 'GOOD', SYSTIMESTAMP);
