INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '빵이 하나같이 나 먹어봐요!! 하며 나에게 달려드는 기분 ㅎㅎ 가게 들어서면 빵냄새랑 카페 특유의 냄새가 코를 콕콕 자극한다 ㅠㅠ 기분좋아!! 카페도 깨끗하고 이것저것 시켜서 배부르게 먹음.', 21, 2, 'GOOD', SYSTIMESTAMP);
