INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '1층에 있는 인테리어예쁜 카페에요~ 커피도 빵들도 맛있어요^^ 음악도 좋네요~ 인기많은곳이라 사람이 많아요 그래도 분위기 좋습니다 추천해요^^', 71, 13, 'GOOD', SYSTIMESTAMP);
