INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '분위기가 너무 편안하고 좋아보여서 홀린듯이 들어왔는데 역시나 유명한 카페였네요ㅎㅎ 빵도 맛있고 커피랑 밀크티도 맛있어요. 비 오는 날 방문해서 더 분위기가 아늑한 느낌도 들구요. 디저트 맛집이던데 다음에도 와서 이것저것 많이 맛봐야겠어요🖤', 44, 1, 'GOOD', SYSTIMESTAMP);
