INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '큰 창으로 자연광이 들어와서 공간이 환하고 쾌적했어요. 여러 그룹이 여유롭게 대화 나누는 분위기라 오래 머무르기 좋았네요. 베이커리 진열대에 디저트랑 샌드위치가 다양해서 고르는 재미가 있었고, 커피 한 잔 하면서 여유롭게 시간 보내기 괜찮아요.', 51, 15, 'GOOD', SYSTIMESTAMP);
