INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '브런치 먹고 싶었눈데 예약된다구해서 찾아왔어용! 점심은 여유롭게 먹고싶었는데 딱 분위기도좋고  쾌적하더라구요 ㅎㅎ 다음에 또 오려구요^^', 12, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '처음 방문했는데 인테리어가 넘 예쁘고 매장 안이 너무 깔끔해서 놀랐어요. 테이블, 의자, 바닥까지 정리정돈이 잘 돼있더라고요. 샌드위치도 맛있고 무엇보다 직원분이 친절하게 응대해주셔서 좋았어요🌿', 55, 11, 'GOOD', SYSTIMESTAMP);
