INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '라떼가 고소하고 부드러워서 커피가 맛있어요!  함께 나온 크루아상은 겉은 바삭하고 속은 촉촉해서 빵이 맛있어요ㅎㅎ디저트도 정성스럽게 만들어진 느낌이 들고 전체적으로 퀄리티가 좋더라구요! 직원분들이 친절해요—자리 안내부터 설명까지 세심하게 챙겨주셔서 감사했어요! 인테리어도 예뻐요 사진 찍기 좋은 포인트가 많아서 SNS 업로드 각이에요!', 0, 8, 'GOOD', SYSTIMESTAMP);
