INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '방학한 애들이랑 같이 홍대 나들이 왔는데 저번에 직원이랑 왔었던 카페레테 왔구요 넓어서 일단 좋고 디저트맛집이라 애들이 빵순이 빵돌이인데 크로와상과 각종 빵들을 잘먹네요 흐뭇해요', 9, 4, 'GOOD', SYSTIMESTAMP);
