INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '트레이에 깔끔하게 놓인 빵들이 한눈에 들어왔어요. 초콜릿이 코팅된 크루아상과 앙버터 조합을 번갈아 먹으니 식감 차이가 확실히 느껴졌어요. 여유로운 분위기에서 천천히 즐길 수 있어서 좋았네요.', 16, 6, 'GOOD', SYSTIMESTAMP);
