INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '유리잔에 담긴 디저트가 색감도 산뜻해서 먼저 손이 갔어요. 큼직하게 올라간 과일과 체리가 한입마다 식감을 다르게 해줘서 질리지 않더라구요. 커피랑 곁들이니 브런치로 마무리하기에 딱 좋았어요.', 42, 7, 'GOOD', SYSTIMESTAMP);
