INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '얼음 가득한 음료에 다양한 토핑이 올라가 있어서 한 입마다 씹는 재미가 있었어요. 테이블에 앉아 천천히 즐기다 보니 자연스럽게 기분이 환기됐네요. 가볍게 쉬어가기 딱 좋았어요.', 23, 2, 'GOOD', SYSTIMESTAMP);
