INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '원두를 선택할 수 있는 점이 좋은 것 같아요. 커피도 맛있고!! 샌드위치랑 빵도 먹을 수 있는 점도 너무 좋아요. 샌드위치는 일찍 와야 먹을 수 있는 것 같으니 다음 번에는 일찍 오려고요ㅎㅎ', 20, 6, 'GOOD', SYSTIMESTAMP);
