INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '나무 테이블 덕분에 전체 분위기가 편안하게 다가왔어요. 빵이랑 아이스라떼 조합이 담백하게 어울려서 기분 좋게 쉬어갈 수 있었네요. 조용한 자리에서 혼자만의 시간 보내기 딱 좋았어요.', 77, 14, 'GOOD', SYSTIMESTAMP);
