INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '합정 들렀다가 카페 하나 찍었는데 여기가 찐이었어요 브런치 묵직하게 먹고 디저트는 깔끔하게 음료도 안 질리고 맛 괜찮더라구요 화려하진 않아도 딱 내 스타일!', 31, 0, 'GOOD', SYSTIMESTAMP);
