INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '나무 테이블에서 크루아상 하나를 천천히 맛보며 주변의 녹음이랑 분위기가 잘 어우러졌어요. 빵 겉면 결이 또렷하게 살아 있어서 자꾸 시선이 갔고, 공간이 자연스러워 편하게 머물다 올 수 있었네요.', 19, 4, 'GOOD', SYSTIMESTAMP);
