INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '오랜만에 친구랑 애들 맡기고 나왔는데 여기 괜찮더라구요 브런치 먹으면서 수다 떨기 좋았고 디저트도 깔끔해서 기분 좋았어요 음료까지 싹 마시고 둘이 분위기 탔다죠^^', 6, 10, 'GOOD', SYSTIMESTAMP);
