INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '선반에 진열된 소품들이 아기자기해서 눈길이 갔어요. 화분이랑 조명이 어우러져서 전체적으로 따뜻한 분위기가 느껴졌어요. 여유롭게 앉아서 디저트랑 커피를 즐기기 딱 좋았던 공간이에요.', 43, 4, 'GOOD', SYSTIMESTAMP);
