INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '샌드위치랑 디저트 크루아상 조합이 보기만 해도 든든했어요. 플레이팅이 깔끔해서 식사 자리가 한결 정돈된 느낌이었고, 커피 한 모금 마시니까 전체가 조화롭게 잘 어울렸어요.', 10, 10, 'GOOD', SYSTIMESTAMP);
