INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '브런치 즐기며 책 읽고 싶을 때 가는 단골이에요 디저트도 자극적이지 않고 음료는 종류 다양해서 고르는 재미가 있어요 테이블 간격은 좀 가까운 편이긴 한데 조용한 시간대엔 꽤 아늑해요 따뜻한 느낌의 조명도 맘에 들어요', 14, 7, 'GOOD', SYSTIMESTAMP);
