INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '유모차 끌고 가도 무리 없는 구조였고 테이블 간 간격도 여유 있어서 편했어요 디저트도 부담 없고 브런치는 담백해서 아이랑 같이 나눠먹기도 좋더라구요 음료도 과하지 않게 맛있고 무엇보다 화장실에 세면대 있어서 완전 합격입니다 ㅋ', 96, 20, 'GOOD', SYSTIMESTAMP);
