INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '합정 나들이 중 우연히 들어간 감성 카페였는데 분위기 대박… 사진 찍기 좋은 자리도 많고 디저트랑 브런치가 하나같이 다 예뻐요 음료도 향긋해서 오래 앉아있기 좋았고요 사람 많을까 걱정했는데 의외로 한적해서 너무 만족했어요!', 86, 14, 'GOOD', SYSTIMESTAMP);
