INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '브런치랑 디저트도 감성 그대로고 음료는 향이 깊어서 마음까지 따뜻해졌어요 내부 인테리어도 깔끔해서 친구들이랑 와도 좋겠더라고요 합정에서 조용히 힐링하고 싶을 때 추천하고 싶은 곳이에요 💛', 62, 15, 'GOOD', SYSTIMESTAMP);
