INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '결이 살아 있는 크루아상을 칼로 썰 때마다 바삭한 소리가 났어요. 겉면이 잘 흩어져서 접시에 작은 조각들이 자연스럽게 남더라고요. 조용한 분위기 덕분에 천천히 먹으면서 생각 정리하기 좋았네요.', 55, 15, 'GOOD', SYSTIMESTAMP);
