INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '푸릇한 식물 인테리어가 먼저 시선을 끌었어요. 크루아상 샌드위치가 접시에 보기 좋게 담겨 있어서 한입 먹기 전에 기분이 좋아졌네요. 베이커리와 브런치 조합이라 든든하게 즐기기 딱 좋았어요.', 16, 7, 'GOOD', SYSTIMESTAMP);
