INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '레몬마들렌은 레몬향이 거의 없는 수준이라  솔직히 그냥 그랬구 우유크림크로와상 이놈이 ㅈㅉ 미친놈입니다,,,,커피도 맛있어요 매장 넓고 쾌적하고 아주조흠~~~!!  우유크림크로와상이 너무너무 맛있다 진짜,,,우유크림이 너무 찐하고 꼬소하구 크로와상은 바삭하구,,,,,,🥹💛💛💛', 33, 3, 'GOOD', SYSTIMESTAMP);
