INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '도쿄 골목에서 마주친 감성 카페 느낌이랄까요  인테리어가 너무 예쁘고 커피도 진해서 취향 저격이었어요. 가만히 앉아있기만 해도 힐링되는 그런 곳!', 18, 9, 'GOOD', SYSTIMESTAMP);
