INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '우연히 지나가다가 사람도 많고 분위기도 좋아보여서 들렀어요! 근데 너무 먹음직스러운 베이커리들이 많고 좌석도 많고 좋더라구요 그리고 창도 커서 밖에 보기도 좋았어요 산미 안좋아하는 친구랑 제 입맛에 커피도 너무 좋았습니다!!!! 빵은 말뭐말뭐.. 근데 주말이라 사람이 많아서 대화하려면 있는 힘껏 얘기해야하는 어려움이 있지만 그건 어느 카페나 마찬가지인거 같아요 아므튼 너무 좋습니다!', 98, 21, 'GOOD', SYSTIMESTAMP);
