INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '아몬드 크로와상 때문에 계속 오게되는 곳😊😋 벌써 세번째 방문!!!! 카페도 조용하고 아늑한 분위기라서 대화하기 좋은 곳😊😊😊 커피도 맛있고 베이커리 종류도 많아서 빵순이는 행복🥰', 35, 8, 'GOOD', SYSTIMESTAMP);
