INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오후 3시쯤 합정역 근처에서 미팅을 마치고 들어간 카페, 햇빛이 찬란하게 비추던 빵들이 너무 영롱해서.. 점심도 굶었겠다 빵 4개를 냅다 주문했습니다. (퀸아망, 초코 커스터드 뺑스위스 등) 퀸아망은 겉바속촉이 미쳤습니다. 바삭한 코팅이 입안에서 사각사각 부서지면서 안에는 부드럽고 촉촉해요. 행복사... 뺑스위스는 초코 커스터드 크림이 너무 달지 않고 적당한 단맛이 납니다. 아니 근데 진짜 잘 구우셨네.. 사진만 봐도 을매나 빵을 잘 구웠는지 보이실까요? 이 베이커리 카페... 조명, 온도, 습도.... 한마디로 정말 낭만적이네요.. 담에 근처로 미팅나오면 꼭 재방문 하겠습니다!', 31, 8, 'GOOD', SYSTIMESTAMP);
