INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '디저트 종류도 엄청 많고 매장 내부 분위기도 아늑하니 예뻐요🥰 플랫화이트 커피 고소하니 맛있구 밀크티도 달달하니 완전 맛있어용😊', 61, 14, 'GOOD', SYSTIMESTAMP);
