INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '조용히 생각 정리하거나 책 읽기 좋은 카페였어요. 사람 많지 않아서 여유롭고, 커피도 정성스럽게 내려주시는 느낌! 담엔 노트북 들고 또 가려구요 :)', 28, 0, 'GOOD', SYSTIMESTAMP);
