INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '요즘 유행한다는 에그마요 소금빵, 저도 한 번 먹어봤어요 >_< 기대 많이 했는데 진짜 괜찮더라구요ㅎ 일단 소금빵은 기본적으로 버터 풍미가 진해서 고소하고, 에그마요가 안에 가득!!! 잘먹구갑니다', 85, 13, 'GOOD', SYSTIMESTAMP);
