INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '지나가다 카페 분위기도 좋아보이고 커피도 맛있어 뷰여서 들어왔는데 역시 제 생각만큼 분위기도 커피도 다 좋은곳!! 오랜만에 합정왔다가 좋은카페 발견해서 기부니가 좋아졌어요>.<❤️', 53, 14, 'GOOD', SYSTIMESTAMP);
