INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '커피랑 빵을 시켰는데 빵이 너무 맛있어요🥹🥹🥹 패스츄리랑 크로아상 겹겹이 너무 바삭하고 맛있고...배불렀는데 너무 맛있어서 크로아상 더 먹었어요 소금빵도 따뜻하게 데워주셔서 맛있게 먹었습니다.', 31, 4, 'GOOD', SYSTIMESTAMP);
