INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '모임 끝나고 언니들이랑 우르르 들어갔는데 브런치부터 디저트까지 전부 다들 칭찬 일색ㅋㅋ 음료도 다들 한 입씩 돌려마시며 맛 비교했잖아요 여기 괜찮다고 단톡방에 바로 공유함ㅎㅎ', 117, 25, 'GOOD', SYSTIMESTAMP);
