INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '합정역 디저트 카페 카페레터는 다양한 번을 커피와 함께 곁들여 먹을 수 있어요. ​ 미니 크로와상과 크렘 브륄레 라떼는 달콤하고 부드러운 맛이 기분 좋게 만들어줘요. ​ 추가로 주문한 무화과 크림치즈번은 무화과가 듬뿍 들어있어 씹는 식감이 매력적이에요. ​ 합정역에 다양한 디저트 카페가 있지만 연애편지 쓸 때의 감성을 담은 카페레터는 편안한 공간과 맛있는 디저트를 원하는 분께 잘 맞는 곳이라 추천해요!', 46, 8, 'GOOD', SYSTIMESTAMP);
