INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '제가 두바이초콜렛, 딸기, 마차 좋아하는데 와,,, 셋 다 있더라고요😆 그래서 시켰는데,, 와우 SEXY FOOD~ 조용한 분위기에 아늑한 공간이라 들어왔다가 장소 저장할 정도로 맛있어서 아주아주 만족스러웠답니당😘', 360, 97, 'GOOD', SYSTIMESTAMP);
