INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '여기 인테리어 너무 예뻐요. 사진 찍기 좋은 스팟 많아서 친구랑 셀카 백 장 찍은 듯ㅋㅋ 분위기도 따뜻해서 겨울에 가면 더 좋을 것 같아요.', 17, 9, 'GOOD', SYSTIMESTAMP);
