INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '크로와상 샌드위치에 바질이랑 토마토랑 치즈 들어있어요! 고급지게 어우러지는 맛이라서 기억에 남네요 커피랑 조합도 좋고 브런치로도 양이 넉넉해서 좋았네요❤️', 41, 4, 'GOOD', SYSTIMESTAMP);
