INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '디저트가 맛있고 내부가 예뻐서 핫한 카페에요. 딸기 초코 페스츄리는 초코크림이 있는데도 빠쟉빠쟉해서 맛있어요! 스콘은 라즈베리잼이 완전 킥🫶🏻', 44, 6, 'GOOD', SYSTIMESTAMP);
