INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '페스츄리로된 디저트 너무 좋아하는데, 페스츄리번 안에 다양한 크림들이 가득해서 너무 맛있었습니다😊. 보늬밤이나 무화과번 같은 경우에는 가을에 먹으면 딱이라 가을 디저트로 제격이었어요☺️☺️', 0, 2, 'GOOD', SYSTIMESTAMP);
