INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '스카치밀키커피랑 베리치즈케이크번을 시켰는데, 스카치밀키는 컵 주변에 사탕 스카치 가루같은게 발라져있어서 달콤하니 맛있었고, 베리치즈케이크번은 자르기는 어려웠는데, 먹을땐,,, 넘 좋았어요,,🥺💕 치즈랑 ㅂ라즈베리 잼? 조합이 넘 맛있었습니다!!', 78, 16, 'GOOD', SYSTIMESTAMP);
