INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '건물 외관도 깔끔하고 카페 인테리어 모던해서 발길이 가는 곳이에요. 고소한 원두 선택해서 아아 마셨는데 커피 넘 맛나고 빵이 예쁜데 맛까지 좋아서 만족. 편안한 분위기라 가끔 들를듯 해요.', 61, 18, 'GOOD', SYSTIMESTAMP);
