INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '집에서 먼데도 자주 오는 카페에요. 디저트 너무 취저라 올때마다 포장 잔뜩해가요~ 딸기올라간 디저트는 아이가 너무 좋아해요 💜 아이랑 오기도 좋고 데이트 하기로도 좋은 곳 같아요', 46, 9, 'GOOD', SYSTIMESTAMP);
