INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '친구와 함께 두바이 초콜릿 디저트 헌팅하러 왔습니다. First stop으로 합정에 있는 카페 레터! 두바이 초콜릿 Connoisseur 감정가인 제 친구도 인정하는 맛이에요! 피스타치오를 정말 맛볼 수 있어요! 분위기도 정말 cozy & calm이라서 꼭 또 오려고합니다 ^^', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '디저트랑 커피가 너무너무 맛있어요!!! 추천받고 온건데 진짜 너무너무 맛있네요! 나중에 합정오면 여기 또 올 것 같아용!!!!!!!!!', 10, 6, 'GOOD', SYSTIMESTAMP);
