INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '인테리어가 이쁘고 생각보다 크기는 컷습니다!! 한층만 있기는 한데 사진찍기 넘 좋아요! 그리고 디저트들이 다양해서 다 먹어보고싶습니당 ㅎㅎ', 15, 0, 'GOOD', SYSTIMESTAMP);
