INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '카페레터 카페 인근에서 친구랑 셀프사진관에서 사진찍고 바로 이카페를 발견했어요. 외관상 보기에 대형카페 인거같아서 그점이 맘에 들어서 들어왔어요. 근데 아아도 너무 맛있고 디저트도 최애디저트가 팔구요.. 어.. 무엇보다 사장님이랑 직원분들이 너무 친절하세요 저희가 들어올때 2인좌석이 다 만석이라 3인이상 좌석도 사장님께서 그냥 저희가 말하기도 전에 바로 먼저 말해주셔서 너무 감사했어요❤️ 잘먹고 잘 쉬다 갑니다~💗 그리고 사장님 잘생겼어여 훈훈해요', 38, 6, 'GOOD', SYSTIMESTAMP);
