INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '케이크 달달하고 고소하고 맛있어요! 엄청 달지않아서 좋았네요😋 인테리어도 예쁘고 엄청 깔끔 청결하고 커피 원두도 3가지라 취향껏 선택할수있어서 좋았습니다🤎맛있게 잘 먹고 갑니다!', 47, 2, 'GOOD', SYSTIMESTAMP);
