INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '디저트 예뻐서 안 시킬 수가 없었어요! 내부 인테리어도 너무 예뻐요 아늑하고 따뜻한 분위기! 카페 로고도 예쁘고.. 어느 하나 안 예쁜 것이 없는 감성 돋는 따스한 카페입니다 :)', 56, 15, 'GOOD', SYSTIMESTAMP);
