INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '조카와 함께 방문했어요👶🏻 혹시 노키즈존인지 들어가기 전에 여쭤봤는데 친절하게 자리 안내도 해주시고 아주 좋았습니다!! 카페도 넓고 쾌적하고 시원하고 맛도 좋아요👍', 24, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '맛있어요! 원두도 선탹할수있어서 좋았습니다! 무화과랑 고민했는데 저 번도 맛있었고 전체적으로 아우러져서 좋았습니다. 다음에는 무화과 먹으러 오려구요! 아쉬운건 다른분들은 안그런거 같은데 제꺼는 크림이 흐르고 안에가 단단하지않아서 먹기는 조금 힘들었어요..!', 63, 12, 'GOOD', SYSTIMESTAMP);
