INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '카페 검색하다가 찾은 카펜데 디저트랑 커피가 너무 맛있어요!!!!!!!!!!! 분위기도 좋고 무엇보다 두바이 초콜릿 번이 있어서 신기했어요..편의점에서 먹은 두바이보다 훨씬 견과류 향도 많이 나고 맛있어요ㅜㅠㅜㅜㅜ', 95, 24, 'GOOD', SYSTIMESTAMP);
