INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '느낌 좋은 카페 찾아서 왔는데~ 제가 생각한 것 보다 훨씬더 느.좋 카페였습니다.💕 커피,음료,베이커리 다 맛있지만 이 카페에서 단연 제일 최고인건 사장,직원분들 입니다. 진.짜. 느. 좋 그. 자. 체', 34, 4, 'GOOD', SYSTIMESTAMP);
