INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '지나가다 창문으로 보이는 분위기에 끌려 들어오게 되었어요 ! 우드톤의 빈티지한 느낌을 좋아하는데 새로 카공할 곳을 찾게 되어 좋아요 👍🏻 아메리카노 원두 종류를 고를 수 있어 좋고 빵도 겉바속촉 맛있게 먹었습니당 매장이 넓어 상쾌하고 창문이 통유리창이어서 작업하다 집중력 떨어지면 멍 때리기 좋아요 ㅋㅋㅋㅋ 집 근처에 새로 정착할 곳이 생겨서 좋숩니당 자주 올 거 같아요 !😊', 22, 7, 'GOOD', SYSTIMESTAMP);
