INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '라떼랑 디저트 다 너무 맛있어요. 라떼 기준치가 높은데 라떼에서 견과류의 고소한 맛이 나면서도 산미가 좋았네요. 디저트도 맛있고 분위기도 좋아요. 강추합니다!', 72, 14, 'GOOD', SYSTIMESTAMP);
