INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '가게 분위기가 너무 예쁘고 평일 오후에 왔는데 홍대 사람들 여기 총집합이었어요 그만큼 핫플🌟 디저트가 특히 미친맛ㄷㄷ 홍대 자주오는데 다음에 다른친구들 데리고 또 올거같아요!!', 10, 7, 'GOOD', SYSTIMESTAMP);
