INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '바닐라라떼 맛집이네여 느끼하지 않아고 고소해서 좋아요 좌석 널찍해서 갑갑하지 않고요 여름에 추운 곳 많은데 기온이 아주 적당합니다 분위기 포근 노래 편안 친절과 맛 까아쥐…', 16, 3, 'GOOD', SYSTIMESTAMP);
