INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '자주 지나다녔던 거리에 새로 오픈한 카페같아 외관이 예뻐서 들어오게 됐는데 인테리어가 예쁘고 빵 메뉴가 다양합니다. 예쁜 물품들도 판매하시는거 같아요☕️', 92, 21, 'GOOD', SYSTIMESTAMP);
