INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '매장도 엄청 깔끔하고 친절하셔요!!! 커피도 엄청 맛있고 원두도 선택할 수 있어서 좋았어용 ㅎㅎ 두바이 초콜릿 번도 먹었는데 식감도 좋고 맛있아요! ! 담에 다른 빵 먹으러 또 와야겠아요 ~~', 14, 6, 'GOOD', SYSTIMESTAMP);
