INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '인테리어가 예뻐요🌷 자리도 넉넉해서 좋습니다. 종류가 많아서 고르기 힘들었는데 무화과 크림치즈번이랑 크로와상 커피 넘 맛있어요ㅎㅎ', 41, 10, 'GOOD', SYSTIMESTAMP);
