INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '우선은 직원분들이 너무 친절해서 기분이 좋았습니다. 매장도 이쁘고, 특히 두바이초콜릿이 너무 맛있었어요. 덕분에 즐거운 하루 보낼수 있을것 같습니다.', 60, 17, 'GOOD', SYSTIMESTAMP);
