INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '벌써 세번째 방문 크로와상 라떼 두번먹고 (안먹으심 후회해여) 아메리카노 그리움 먹는데 산미없이 탄맛없는 시원한 아아 채고채고', 3, 7, 'GOOD', SYSTIMESTAMP);
