INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '몇년만에 홍대 나갔는데 역시나 토요일 오후엔 사람이 참 많네요. 그 와중에 커피빈 2층에서 4층까지 자리 많아서 잠시 쉬어가기 너무 좋아요!!', 27, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '2/8 토요일 아침에 출근전 방문 했어요. 1. 네아버페이로 결제 한다고 미리 말씀드렸는데 캐셔 직원분이 잘 몰라서 다른 직원에게 물어보고 알려주시더라고요 . 시간이 너무 오래걸려요ㅠㅠ 그렇다고 결제가 밀린것도 아니고요... 손님은 저 혼자인데 응대가 너무 버벅거리세요.. 교육생이면 옆에서 계속 백압해주셔야하는데 안해주시는건지 본인 일이 바쁘신건지 ㅠ 그리고 평소 제공되눈 우유 온도보다 뜨겁게 부탁드렸는데 그냥 미지근한물에서 살짝정도였어요 어우ㅠ 출근 해야해서 빠른요청부탁드렸고요ㅠ 안된다면 취소할 생각이었어요..ㅠ 응대가 아쉽습니다;', 28, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대치고 매장이 커서 좋아요! 층층이 사람이 많긴 하지만~ 그래도 키오스크가 층마다 있어서 편하고 홍대에서 만남할때 위치가 좋아서 종종 이용해요 그리고 비싸더라도 커피가 맛있습니다..👍🏼', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '사진은 못찍었지만 번잡한 홍대에서 커피를 마실 수 있는 곳 중 하나에요 ☕️ 화장실이 4층에 있는걸로 봐서는 4층까지 좌석이 있는 것 같아 좌석이 많아 좋은 것 같아요👍🏻커피도 맛있고 직원분들도 친절하시고 가격도 나름 합리적인 느낌이라 개인카페보다 쉬어가기 좋을 것 같아요~', 22, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '커피빈 매장이 많진않은데 믿고먹는 브랜드의 커피전문점이에여~동네에도 있어서 자주가고 늘 먹는 메뉴들이 있는데 참 맛이 괜찮다고 생각들어요ㅋㅋ 오늘은 비도오고 출출해서 스프까지 먹었는데 몸을 뜨끈하게 해주고 좋네요', 68, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '쇼핑하고 더워서 카페에서 쉬려고 했는데 홍대역 근처 카페 사람 너무 많아서 ㅠ 찾다 찾다 커피빈 계단 올라는게 귀찮지만 그래도 운좋게 빈자리 있어서 음료랑 베이글주문 쌀베이글이라 먹어도 속이 더부룩하지 않아요 ^^ 따뜻하게 데워서 크림치즈 발라먹으면 진짜 맛있으니까 추천', 13, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '확실히 매장이 넓고 늦게까지 하다 보니까 사람들이 많이 몰리는 것 같습니다 하지만 모든 사람이 수용가능할 정도로 많이 넓습니다. 총 3층 짜리 카페 입니다. 또한 음료도 되게 빠르게 나오고 자리도 금방금방 비워 쓰다 보니 1층 자리도 금방 나더라구요! 남자 친구랑 퇴근하고 잠깐 얼굴 볼 때 잠시 여기서 얼굴 보고 이야기 하기 좋습니다☺️ 여름엔 에어컨도 빵빵하고. 겨울엔 히터도 빵빵하고. 항상 신세 잘 지고 있습니다. 사라지지 말아 주세요.', 11, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '네이버 주문 했는데 확인 안해서 주문 후 15분후 내려가니 확인을 못했으니 10분만 기다려달라해서 기다림. 15분 후에도 안나와 다시 내려가 문의하니 전후사정도 안묻고 또 기다리라 함. 모든 고객이 30분씩 기다리는거냐고 했더니 그때서야 음료 제조 들어감. 결국 주문 이후 30분 지나서 음료받음. 이럴거면 네이버 주문은 막아놓지. 4층에서 대체 몇번이나 왔다갔다 한건지...최악임.', 122, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '위치 좋은 커피빈 매장입니다. 커피빈답게 음료도 맛있습니다. 다만 사람이 너무 많아서 크게 붐비고, 키오스크 줄이 너무 긴 경우가 많습니다. 부득이하게 직원에게 주문하면 퉁명스러울때가 많아서 조금 아쉽습니다. 아마 너무 바빠서 사람에 치여서 그러신가봐요.. 아마 지사나 매장 차원으로 피크타임때 직원을 충원해야하지 않나싶습니다..', 54, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '모처럼 방문했던 커피빈 홍대입구역점 넓고 깔끔한 매장, 대화하기 좋은 편안함, 딸기요거트 왜케 맛나지? 요거트가 너무 진하지 않고 딸기가 많아~~♡ 오오~', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '해피이브닝 할인받았어요 ㅋ 평일 주말 상관없이 오후 6시 이후부터 할인되요 고기에서 🔥맛나고 치즈도 넉넉하게 들어있어서 쭈욱 늘어나고 고소했어요 🤤😆 고기 꽤 크고 양 많아요!! 추천드립니다~~', 53, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대입구역 9번 출구 앞이라 가까웠어요~ 키오스크도 있고 주문 받는 곳도 있었어요~ 2, 3, 4층까지 있더라고요~ 4층은 단체석 같았고요~ 층마다 키오스크 있으니 더 편리~ 갑자기 비가 와서 약해질때까지 기다렸다가 지하철역으로 가니 우산 없어도 굿굿굿~^-^', 12, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '첫째와 둘째가 홍대에 가고싶은곳이 있다하여 같이 놀러와 데려다주고 와이프와 막내와 셋이는 따로 커피빈으로 방문했어요. 화장실이 4층에 있어서 약간 불편하지만 자리도 많고 깨끗하고 편하게 쉴 수 있었어요.', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '겨울신제품 퓨어피넛초코렛아이스블렌디드와 뱅쇼먹었어요 근데 퓨어피넛초코렛은 초코렛맛은 거의 안나요 메인은 땅콩음료니 참고해쥬세요', 45, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '사진 못찍어서 아쉬운데 맛있었어요 매장도 넓어서 화장실도 좋았고 얼음물도 잘 구비되있고 냅킨도 넉넉히 구비되있어서 편리했습니다', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '근처 볼일 있어 잠깐 방문. 바닐라 라떼 아이스/덜 달게/오트로 변경. 커피빈은 역시 바라쥬😍😍 다른 카페와는 달리 잔얼음이라 좋아열. 커피가 더 맛있는 느낌쓰? ㅎㅎㅎㅎ 위치답게 외쿡인들 많음.', 107, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '무료음료쿠폰은 키오스크에서 주문할 수 없게 되어있었어요 그렇지만 쿠폰혜택이 좋네요 사이즈 상관없이 제조음료라면 뭐든 가능합니다 캐러맬 아이스블랜디드 먹었는데 달다구리 캐러맬 맛이 찐~하게 느껴졌습니다', 113, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '생각보다 자리가 많이 남는데 소리가 울려서 시끄러움 자리는 좋음 지하철도 가깝고 누군가 만나거나 헤어지기전에 이야기나누기 좋은 장소정도', 97, 20, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '일반 가격으로 구매했다면 만원이 훨씬 넘는 가격이지만 해피이브닝가로 구매하니 만원도 안되는 가격으로 구매했어요!! 😆 직화불고기 브리또 생각보다 맛있었어요 불맛도 많이 나고 고기도 섭섭치않게 풍성하게 들어있고 치즈도 약간 들어있지만 따끈따끈하게 데워진 상태에서 먹으니 치즈도 쫙쫙 늘어나고요 탄단지 밸런스 샐러드는 오리엔탈 소스가 베이스고 메추리알 3개 토마토 2개 치킨 등등이 들어가요 보기좋게 야채와 따로 분리되어있구요~ 의외의 다크호스 두부면이 들어있는데 생각보다 맛있어서 놀랍!! 🤩 쫄깃한 식감이었습니다 홍대역점은 금토만 23시까지네요', 45, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '바닐라빈 크림 콜드브루 바닐라빈이 콕콕 박혀있어 고급져 보이고 달달하니 맛있는 커피였습니다~ 커피빈 얼음은 고드름같은 느낌이라 아삭아삭하고 맛있네요 😆', 39, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이야기 할 공간이 필요해서 방문했어요. 많은 사람이 이용하는 곳이긴 하나 테이블 지저분하고 전반적으로 관리 안 되는 느낌이라 아쉬웠어요. 커피 맛은 좋아요', 80, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '꼭 커피빈 가면 마시는 바닐라라떼, 점심 못 먹은 날 두유로 옵션 선택해서 마시면 든든해서 좋아요 항상 바쁜 지점이지만 음료 퀄은 떨어지지 않습니다', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '주문은 키오스크로 할 수 있어요. 사람이 많지만 회전율이 비교적 빠르고 좌석도 편안했어요. 화장실도 넓직하니 깔끔. 그리고 빨대는 이제 제공이 안된다는데 몇 분은 빨대를 꼽고 음료를 마시더라고요. ??', 30, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '직원 불친절...뭐 하나 물어봤다고ㅋㅋㅋㅋㅋ표정 다 보이고, 빨대는 이제 미제공인지 뭔지 다른분들은 꽂고 마시더라고요 대충 마시고 나왔습니다~ 역이랑 가까운건 말곤 없네요', 123, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '3층짜리에 빈 테이블 없이 사람이 너무 많은데 알바를 너무 적게 쓰는 느낌임 트레시박스나 홀 관리 하나도 안되고 키오스크에 진동벨도 없어서 요청해야 채워줬음 그래도 음료는 잘 나왔고, 응대객이 많은 만큼 알바분들도 엄청 힘든티를 팍팍 내셔서 고객으로서 기분이 좋진 않았지만 이해가 되었음 매장 마감 전에 따로 알림이나 고지없이 마감시간 되자마자 나가라는 방송이 나와서 당황함', 44, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '요즘 커피가 너무 비싸다 옛날에는 스타벅스가 비싸다고 생각했는데 이제 다 커피가 거기서 거기구나 🚰·̫🚰 하지만 없으면 안대지이😍', 83, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '작업하기에도 친구들과 이야기를 나누기에도 좋은 곳이에요! 층수가 많아서 넉넉하게 좌석이 있는 점도 좋구요 ㅎㅎ 하지만 엘베가 없어서 조금 불편하기도 해요ㅠㅠ', 19, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '마라탕 먹고 입가심으로 아이스라떼 한잔! 근데 벌레들이 너무 날아다니고 창밖에 조명 때문에 창문에 엄청 붙어있는 벌레들... ☹☹☹', 28, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대입구역 근처에 있는 커피빈 매장. 건물 2,3,4층을 통째로 쓰고 있어서 건물이 넓고, 4층에는 단체나 카공족들이 이용하기 좋다. 다만 화장실이 4층에 하나 밖에 없는 게 좀 불편하다.', 45, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대에 갔다가 급히 쏟아지는 비를 피해 들어갔어요~ 직원분들 너무 친절하셔서 기분이 좋았어요. 오랜만에 방문한 커피빈..맛있게 바닐라라떼 먹고 나왔네요 딸이랑^^', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카페 공간에 오래 머무르고 싶을 때 커피빈 자주 가요! 스타벅스보다 상대적으로 덜 붐벼서 좋은 듯... 디카페인 되는 것도 맘에 들어요:) 아침이면 식사빵 메뉴 할인하는데, 맛있고 꽤 배불러서 종종 갈 것 같아요!', 9, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '따로 요청 안드려도 센스있게 티백 꺼낼거 챙겨주셔서 좋네요 감사해요 :) 손님도 많이 없고 매장 분위기도 전반적으로 차분해서 좋아요', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '진짜 회사 근처에 있으면 매일 이용하고 싶은 디스코플래닛이에요. 골목에 있는 것이 정말 아쉽지만, 점심 먹고 시간이 남으면 가능한 가려고 해요. ☺ 모든 음료가 3,500원인데요, 퀄리티도 맛도 좋아요. 냥이🐱(언니) 보면서 힐링하기도 해요. 🤗 손에 힘이 없어서, 궁둥이 팡팡 못해줬지만... 귀 쫑긋쫑긋 거리는 모습이 정말 너무 예뻐요.😍 이번에도 망고 스무디 마셨는데요, 마지막까지 맛있게 잘 마셨습니당.😋', 24, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '많은 분들이 이용하고 계셔서 시간이 많이 걸릴 줄 알았는데요, 생각보다 빨리 나와서 좋았어요. 진짜 회사 근처면 매일 오고 싶은 곳이에요. 망고 스무디에 너무 꽂혀서 ㅜ.ㅜ😭 매일 올 수 있으면 다양한 음료를 맛보고 싶은데요, 가끔씩 오니 늘 최애 😍 스무디만 마시네요. 😑', 45, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '음료가 저렴해요!! 흑임자치즈케이크 존맛탱이에요 꼭시키세요 흔하지 않은 맛!! 양이 좀 적은데 음료가 저렴하니 괜찮쓰~~ 케이크 진짜 둘이서 순삭했어요. 하나더시키려다가 저녁먹어야해서 참았어요. 또 올 것 같아요!! 고양이도 있는데 엄청 똥똥해요 너무 귀여워❤️', 80, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
