INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '치즈케이크 너무 맛있어요! 퀄리티 좋은 치즈케이크라서 물리지않고 맛있게 먹을 수 있어요 인절미 라떼 처음먹어보는데 역시 맛있네요 고양이도 너무너무 귀여워요...', 10, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
