INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '여기 음료랑 디저트 항상 믿고 먹어요 진짜 여기만한 카페 없음... 왕짱대박강추!!!!! 엄한 가게 가서 어중간한 음료나 디저트 먹지 말고 무조건 여기 오세옴...S2 분위기도 아주 좋아요 네이버 사진에 있는 사진과 다르게 실제로 와보면 트렌디하면서 빈티지함이 공존하는!!  노래도 센스 있고 느낌 좋음!! 아무튼 넘 좋아서 구구절절 남겨봅니다 맛있는 디저트랑 음료 팔아주셔서 감사합니다 사짱님!!!', 15, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '팥빙수도 나왔다고 해서 먹어봤는데 그렇게 달지 않고, 우유쉐이크랑 잘 어울려서 맛있었어요!! 그리규 오늘은 고양이 언니가 위에서 께어있어서 인사하고 귀여워요', 60, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '간만에 왔어요. 여전히 분위기 좋고, 음료 가격도 착해요.👍🏻 종류가 다양한데, 늘 마시는 것만 먹네요^^ 😋 오늘은 얌전히 쉬고 있는 냥이🐈 "언니"~ 회사에서 가까우면 좀 더 자주 오고 싶은 곳이에요. 담에는 다른 음료도 도전해봐야겠어요,', 2, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '오랜만에 언니 보러 왔어요! 신메뉴 나왔길래 먹어봤는데 여름에 잘어울리는 맛이었어요 언제나 실패없는 곳입니다.. 제가 제일 좋아하는 카페예요 정말로 추천합니다..!!!', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '초코바스크치즈케이크 6,500원 아이스 카페라테 3,500원 아이스 딸기라떼 3,500원 이쁜 고양이가 있어서 좋아요 또왔어요 좋아 고양이가 내 옆자리에 와주면 정말 좋겠어요.', 130, 23, NULL, SYSTIMESTAMP);
