INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '고양이!가 있어요! [주문] 크림라떼, 초코바스크치즈케이크 사장님이 친절하시구, 주문하면 가져다주세요! 꾸덕꾸덕한 초코바치케(Decoration.체리와 크림)와 크림 잔뜩 올라간 크림라떼! bar 자리도 있어요! 자리가 은근 넓어요! (단체좌석 8명, 4명, 2명 테이블, bar 좌석) 콘센트는 술 있는 곳 좌석 밑, bar 자리 발 밑에 있는 것 같아요! 음악[ playlist]도 너무 좋아요!', 124, 23, 'GOOD', SYSTIMESTAMP);
