INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '언니냥이가 너무 귀여워용 😍 음료도 이것 저것 먹어봤는데 다 너무 맛있어요 ㅎㅎ 음료 다 마시고 집 가는데 인사해주는 이쁜 냥이🥹💛', 2, 9, NULL, SYSTIMESTAMP);
