INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '망고스무디에 계속 빠져 살아요.ㅜㅜ 코코아의 달달함이 마지막까지 빨대까지 빨게 하는~😋 냥이 녀석 볼 겸, 식탐도 채울 겸 종종 가는데요, 회사 근처면 더 자주 갈 것 같아요. 모든 음료 3,500원!!! 정말 좋아요.☺', 77, 11, NULL, SYSTIMESTAMP);
