INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '원래 가려고했던 카페가 휴무날이라 가까운 곳에 있는 아무 카페나 가자~ 하고 들어왔는데 음료가격도 너무 싸고 매장도 예뻐서 좋았어요!! 그리고 넘 귀여운 고양이도 있더라구요 ㅠㅠ 요즘 프랜차이즈 아니면 이 정도 가격의 음료 마시기 어려운데 맛도 있어서 다음에 홍대 올 일 있으면 또 이용할 것 같아요! 좌석도 편하고 음악도 좋아서 잘 이용하고 갑니다~~', 220, 27, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '와 여기 카페지만 있을게 다 있어요 낮에는 소소하게 라떼 한잔 먹고, 저녁먹은 다음에는 위스키랑 케이크 한잔으로 즐거운 시간 보냈습니다. 보드게임도 있는데 친구랑 같이 와서 하루종일 시간 떼우기도 너무 좋아요!! 잘 놀다 갑니다 :)', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '디카페인 아아로 마셨고 초코 바스크 치즈케이크도 같이 주문했습니다. 아아도 맛있지만 초코 바스크 치즈케이크가 진짜 꾸덕하고 맛있어요! 직원분도 친절하시고 고양이도 귀여워서 재방문 의사 있습니다 왕추천', 111, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '☕️🍰 음료도 깔끔하고 디저트도 전부 맛있어서 한 입 먹을 때마다 감탄 😋 가격은 또 너무 착해서 “이래도 돼?” 싶은 가성비 천국💸 자주 오고 싶은 카페✨', 37, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '초코바스크치즈케이크는 처음 먹어봤는데 꾸덕하고 완전 맛있어요....🥺 커피 향도 너무좋고 진해서 조합이 좋고 오늘도 언니는 귀여워요☺️', 17, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '음료 전메뉴가 3500원에 콘센트도 많고 자리도 넓어서 카공하기 최고에요! 디저트는 블루베리바스크치즈케이크를 먹었는데 정말 맛있습니다..👍 이 카페의 시그니처인 고양이 ‘언니’도 올 때마다 볼 수 있어서 너무 좋아요.', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
