INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '음료가 너무 너무 저렴하고 너무 너무 맛있어요!!!👍👍👍👍👍👍 디저트도 너무 너무 맛있어서 완전 강추합니다!!!🧡🧡 카페에 보드게임도 있어서 친구들이나 연인과 오면 좋을 것 같아요!!! 대화하기 좋은 분위기여서 홍대카페를 간다면 무조건 여기로 다시 올 것 같아요!!!💯', 35, 10, 'GOOD', SYSTIMESTAMP);
