INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '진짜 자주오는 카페인데 공부하기도 대화하기에도 좋고 음료 전메뉴가 3500원이여서 편하게 와서 마시기 좋아요! 좌석도 편한 좌석들이 많아서 안장있기 좋고 고양이도 너무 귀여워요~', 5, 7, 'GOOD', SYSTIMESTAMP);
