INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '제대로 호객행위를 하고 있는 냥이🐱 녀석~ 그냥 지나쳐 갈 수가 없어요 ㅠ.ㅠ😭 따사로운 햇살아래 저렇게 예쁘게 쉬고 있으니... 심쿵💘 아인슈페너도 망코스무디도 맛나요. 냥이 🐈 녀석 덕분에 힐링하고, 입도 호강했어요.😋', 52, 12, 'GOOD', SYSTIMESTAMP);
