INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '작업이 정말 잘 되는 집 근처의 애정하는 카페! 집중이 필요할 때마다 종종 왔었는데 리뷰는 처음 씁니다 맨날 커피만 마시다가 유자요거트스무디가 눈에 들어와서 마셔봤는데 좋네요💓 너무 달지 않고 적당합니다. 그래두 치즈케이크랑 먹기엔 커피가 좀 더 맛있긴 하지만👉👈 담엔 고양이도 보고싶어용 +) 꼬앵님은 카운터쪽에 계셨답니다... 예전에 왔을 땐 창가쪽에서 꺅꺅 하며 뵈었던 기억이 있어서 안 계신줄 알았구만유..😸', 59, 17, 'GOOD', SYSTIMESTAMP);
