INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '진짜로 음료가 하나하나 다 너무너무 맛있어서 만2년 동안 자주 오는 단골인데욧 크로플이 얼마전에 나왔다고해서 먹었는데 아 진짜 진짜 서교동 동교동 망원동 다 합해도 여기가 제일 맛있어요 진짜진짜로 그리고 귀여운 언니가 있어서 있는동안 항상 행복하게 있다가 갑니닷', 78, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '딸기 요거트는 처음 먹었어요. 역시 맛있어요. 딸기도 많이 들어있고, 달달구리해서 정신이 번쩍 들어요^^ 요거트라도 종류에 따라 조금씩 달라서 골라 먹는 재미가 있어요. 3,500원에 입이 즐거웠네요.', 12, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '또 왔어요. 지난번에 마신 망고스무디를 잊지 못해서^^ 오늘은 기분이 좋은지, 냥이 녀석도 나와 있었어요. 궁디팡팡 해주시는 분이 계셨는데요, 이 녀석이 얼마나 좋아하던지... 보기만 해도 힐링됐어요.😆 아인슈페너도 넘나 맛있다고 하네요.🤗 3,500원 착한 가격에 다양한 음료를 맛볼 수 있어서 좋아요. 아늑한 분위기라 솔직히 있으면 나가고 싶지 않아요.🤗', 52, 18, 'GOOD', SYSTIMESTAMP);
