INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '맛있는 커피가 필요할 때 종종 찾는 곳입니다. 커피가 항상 맛있고, 디저트와 페어링이 완벽한 곳입니다. 귀여운 고양이도 있으니 꼭 추천드립니다ㅎㅎ', 81, 11, 'GOOD', SYSTIMESTAMP);
