INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '종종 오는데 오랜만에 와서 케익까지 냠냠 엄청 맛있습니다.. 자두에이드를 파는 카페가 별로 없는데 자두에이드 마시러 여기 꼭 오게 되는 것 같아요! 귀여운 고양이도 있고 조명도 은은해서 매우 편안하고 매력적입니다! (커피도 마싯서요)', 40, 2, 'GOOD', SYSTIMESTAMP);
