INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '두번째 방문이에요! 저번에 너무 커피가 맛있고 고양이도 귀여워서^___^ 또 방문했구… 디저트는 처음 먹어봤는데 초코바스크치즈 케이크가 정말 맛있어요ㅠㅠ💗☕️ 이 꾸덕하고 옹골찬 맛… 초코가 먹고 싶은데 치즈도 먹고싶은 날… 최고의 맛입니다 또 방문할 것 같아여', 2, 3, 'GOOD', SYSTIMESTAMP);
