INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '잠깐 쉬다 갈 곳을 찾다 우연히 발견했어요 인테리어에 이끌려 들어왔는데 가격도 요즘 물가에 비해 너무 저렴하고 음료 디저트 모두 맛있어서 감동했어요 커피도 그냥 튀는 신맛이 아니라 맛있는 향과 산미가 느껴지는 커피였습니다 돈쭐나십쇼 사장님…', 57, 13, 'GOOD', SYSTIMESTAMP);
