INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '음료랑 바스크 치즈 케이크를 시켰는데 케이크가 입에서 살살 녹고 맛있습니다ㅠㅠ!그리고 커피좋아하는 친구도 커피가 정말 맛있다고 했습니다 우연히 찾은 행복이네요', 14, 2, 'GOOD', SYSTIMESTAMP);
