INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '최근에 갔던 카페 중에 단연코 최고였던…🥺 우선 음료랑 디저트가 너무x99999 맛있어요ㅠㅠㅠ 특히 티라미수 라떼는 먹는 순간 천국을 경험할 만큼 황홀한 맛입니다…😵😵 브라우니랑 치즈케이크 둘 다 정말 맛있어서 오랜만에 제대로 힐링하고 갑니다⭐️⭐️💓 고양이도 완죠니 귀여워요!!ㅎㅎㅎㅎ 10점 만점에 10000점 드립니다😍', 48, 3, 'GOOD', SYSTIMESTAMP);
