INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '전에 올리려다 못올려서 오늘 올려보아용!!^^ 종종 산책을 하며, 지나가던 길이여서 한번 와봐야지 하다가 술 주문한거 찾으러 갔는데 술 주문량이 많다보니 남자 사장님이 신경써서 같이 챙겨주셨던 모습이 기억에 남았어요. 그리고, 여자 직원분도 친절해서 좋았습니다. 음료 테이크아웃 해서 먹었는데 (민,초) 가격도 너무 착하고 ,너무 맛있었습니다. 또 고양이도 보러가야지 하다가 오늘 지인들 음료 사다주러 핕빙수 쉐이크 테이크 아웃 하러 방문했어요. 들고간 케익을 한손에 들고, 또다른 한손에 음료 캐리어까지 드니깐.. 문열 손이 모자랐는데 (음료까지 직접 가져다주시고,) 문까지 열어주셔서 감사했습니다. 🙏 친절하신 매너에 곧 또 방문하겠습니다. 음료 너무 맛있었습니다.👍', 8, 0, 'GOOD', SYSTIMESTAMP);
