INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대에 이런 카페가 있다니 놀라워요~! 이제 홍대오면 여기만 올거같아요 맛도 좋고 직원분도 친절하시고 고양이도 있습니다... 최고❣️', 34, 4, 'GOOD', SYSTIMESTAMP);
