INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '카페 분위기가 너무 좋고 대화하기 너무 좋습니다! 커피랑 케이크도 가격도 저렴하고 너무 맛있습니다! 비와서 잠깐 들어왔는데 너무 좋은 곳 발견하고 갑니당 히히', 40, 9, 'GOOD', SYSTIMESTAMP);
