INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '음료랑 디저트 다 맛있는데 가성비도 좋아요! 특히 망고스무디가 정말 맛있어요 다른 카페 가면 6천원은 받을텐데 여기는 3500원이에요. 분위기도 좋고 자리가 편해서 공부하기에도 친구랑 놀러오기에도 좋아요~', 26, 2, 'GOOD', SYSTIMESTAMP);
