INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '서교동 홍대 커피맛집. 디스코플래닛. 원두도 직접 로스팅하시는 젊은 사장님. 늘 꾸준하게 성실하게 커피 한가지만 고집하시네요. 저는 늘 카페라떼. 하루의 일상을 채워줍니다. 계속 번창하시길 바래요 ^^', 79, 16, 'GOOD', SYSTIMESTAMP);
