INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '카페 종류 다 3500원이란게 믿기지 않을 퀄리티입니다요😲 바치초케도 넘 맛있고 사장님 남는게 있으실까 걱정될 정도,,, 술 종류도 넘 다양하고 고앵이와 분위기도 지대 좋아요🥵', 37, 2, 'GOOD', SYSTIMESTAMP);
