INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '친구가 알려줘서 알게 됐는데 이젠 제 아지트가 됐어요>.< 여기 음료 맛 없는 게 없음 진짜로. 근데 디저트도 맛있고 고냥이도 넘 얌전하고 착해요 귀여워요.. 최고의 플레이스임 모두가 알았으면 좋겠는데 사실 저만 알고 싶어요', 12, 9, 'GOOD', SYSTIMESTAMP);
