INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '아인슈페너 맛집입니다.. 커피 별로 안좋아하는데 여기 아인슈페너 마시러 와요(물론 넘나리 기여븐 냥이 때문도 있움…) 솔직히 여기 음료 다 맛있구 매장 넓고 사람도 많이 없어서 아지트 같고 사장님도 너무 친절하심..여기 알기 전으로 돌아가고 싶지 않아요..', 47, 9, 'GOOD', SYSTIMESTAMP);
