INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '커피가 맛있어서 맨날 가는데 야무진 디저트 메뉴 생겨서 좋아요. 가격만 비싸고 성의없는 디저트들 많은데 여긴 옹골차고 정성스러워요 ㅠㅠ', 39, 8, 'GOOD', SYSTIMESTAMP);
