INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '초코 치즈 바스크 케이크, 기대 이상으로 훌륭했습니다. 진한 초콜릿의 풍미와 부드러운 치즈의 조화가 인상 깊었으며, 촉촉하고 밀도 있는 식감이 만족스러웠습니다. 음료도 가격에 비해서 말도 안되는 퀄리티입니다. 위스키도 판매하시는 것 같은데, 다음에 와서 마셔보겠습니다.', 78, 11, 'GOOD', SYSTIMESTAMP);
