INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '전메뉴가 3500원! 홍대 한복판에 이렇게 좋은 카페가 있는 줄 몰랐네요. 그리고 뭐니뭐니해도 카페를 가장 완벽하게 만들어주는 건 언니냥이!!', 50, 5, 'GOOD', SYSTIMESTAMP);
