INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '대화나누기도 좋고 다들 직원분들 너무 친절하시구 커피 맛도 좋아요!! 가격이 다 3,300원이라 이런곳이 어디있나요ㅠㅠ 그리고 젤 좋은건 고양희 언니가 있다는거 ㅎㅎ (고양이 이름이 언니에요)', 118, 25, 'GOOD', SYSTIMESTAMP);
