INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '카페 냥이 언니. 손님들한테 인기 엄청 많구요~~ 순하고 이쁜 아이에요 제 노트북 올라와서 무한 채팅 중! 오랜 단골이고요 이제사 리뷰 쓰네요 가성비 분위기 친절 최고 사내 복지보다 좋은 곳 디스코플래닛 영원하라!', 33, 10, 'GOOD', SYSTIMESTAMP);
