INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '프로미스나인 박지원 생일카페에 다녀왔습니다. 이 카페는 요거트집 답게 요거트가 너무 맛있습니다. 꼭 요거트 메뉴를 드시길 추천드립니다. 키오스크에 아티스트가 나와서 주문할때 행복합니다. #프로미스나인 #fromis_9 #fromis9 #박지원', 50, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '프로미스나인 백지헌 생일카페에 다녀왔습니다. 요거트 맛있으니 꼭 드셔보세요 🍧 #프로미스나인 #fromis_9 #fromis9 #백지헌', 38, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '맘에 든 요거트아이스크림 카페 .. 🤍 요거트 상큼하고 달고 샤베트인데 부드러워서 맛있구 과일 신선해서 좋았습니다 심지어 블루베리 냉동 아닌 곳 처음 보는데 정말 맛있어요 분위기도 좋아서 홍대에서 잠깐 들려서 쉬고가기 좋은 곳 🫶🏻', 63, 17, 'GOOD', SYSTIMESTAMP);
