INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '프로미스나인 이서연 생일카페 다녀왔습니다. 매장은 협소한 편이었지만 키오스크에 아티스트의 사진이 나와서 주문하면서 너무 즐거웠네요 🍀', 3, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '초코쉘에 치즈크럼블 조합 진짜 맛있어요🩷!! 술 먹고 후식으로 딱입니다🥹🩷 요거트아이스크림도 너무 시지않고 맛있어서 그릭요거트 포장해가보려구요~!!', 49, 7, 'GOOD', SYSTIMESTAMP);
