INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '집사들이 설명을 잘해 주시고 얘기를 많이 해서 좋았습니다.특히 집사들이 동물 캐릭터가 있어서 이해가 쉬었당!! 그리고 다음에 동생하고 같이 오고 싶가는 생각이 들었습니다.', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '휴... 각박한 서민 체험에 지쳐 베스티아 가문의 저택에 귀가하였습니다. 집사님들께서 유쾌하셔서 숨 돌릴 시간도 없이 웃고 있었답니다~☺️ 앗 입꼬리가 귀에 걸려서 내려오질 않네요 이거 손해배상 청구하러 다시 가야 할 것 같아요..! 절대 집사님들이 멋있으셔서 다시 가겠다는 것은 아니고 정말 손해배상 청구하러 가는 겁니다 ㅜㅜㅜ 테이블 담당해 주신 신지 집사님 견습 집사님이셨는데 저희 테이블 잘 챙겨주셔서 감사해요옹~~ 🐧✨ 발렌타인🦜집사님 성대모사 장인이십니다! 또 쿠로🐍집사장님 레오🐱집사님 하쿠🐉집사님 레서판다집사님 성함을 못 들은 집사님들도 모두 잘생기셨고 친절하셨어요:) 다음 귀가 때 최저시급 열심히 벌어서 푸딩을 가져가도록 하겠습니다🍮 그때까지 퇴사하지 마시고 번창해 계시길💪', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '늦게 나마 쓰는 리뷰!! 까먹고 지금써요..허허 친구랑 진짜 고양이로 컨셉에 충실하게 갔는데ㅋㅋㅋ다들 엄청 좋아해 주셔서 친구가 엄청 좋아했어요! 너무 즐거웠고 다음에는 1층 수인쪽으로 갈려구요!😉😂😂', 25, 10, 'GOOD', SYSTIMESTAMP);
