INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '10년지기 칭구들이랑 같이 홍대 대저택을 방문했어욥 처음에 들어갈 때부터 환영해주시고 자리 에스코트부터 마지막에 나갈 때까지 친절하게 대해주시고 심심하지 않게 대화도 걸어주셔서 너무 즐거웠습니당 특히 쿠로집사님이랑 사진도 찍고 라이브쇼도 보았는데요 진짜 진짜 너무 잘 하셔서 넘나 감동 받았습니당 첨엔 시큰둥했던 제 칭구들도 너무 감명받아서 아직도 감동에서 헤어나오질 못하고 있어요 ㅎㅎㅎㅎㅎㅎ 일상에서 받은 스트레스를 단 한시간만에 날려버릴 수 있다니 여긴 엄청난 곳인거 같아욥 담에 또 칭구랑 약속 잡아서 다녀오기로 했어요 여러분 꼭 한번 다녀오시고 집사님들 라이브쇼도 꼭 관람하세요 ㅎㅎㅎㅎ 강추 대박 강추 ㅎㅎㅎ', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '정말 행복가득 ..😄 갈때마다  항상 웃음꽃피고갑니다 저는 손이 꽝손이라 루시집사님께서 뽑아주심... 2등!   해삐해삐  체키도찍구 집사님들이 항상 잘해주시고 놀아주셔서 감사해요😝 다음엔 큼..1 ..등을 노려볼게요🤩', 7, 6, 'GOOD', SYSTIMESTAMP);
