INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '친구랑 신선한 체험좀 할겸 다녀왔는데 너무 재밌었어요 낯을가려서 많이 즐기진못했는데 집사님들이 다들 친절하시고 낯가려도 말걸어주시려고 다가와주셔서 그나마 적응했습니다ㅋㅋㅋㅋㅋ 다음에 또 방문하려구요 디저트들도 꽤나 다양하고 맛있었습니다 재밌게 즐기다갑니당~~', 5, 3, 'GOOD', SYSTIMESTAMP);
