INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '공쥬들하고 살다살다 새로운 경험을했다 예약하지 않으면 들어갈수 없는. 곳 혼자라면 몰랐을 경험이지만 너무 사악하게 요즘 젊은 세대들의 돈씀이 헤프다는 생각이들었다 지극히 개인적인 생각 임 한번의 경험으로 족한 다시는 안갈거 같은 마음 ~~세명이서 10마넌 넘는 커피값은 비싸군이다', 80, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '동물계 집사들이 안내와 함께 처음 가본 집사카페 집사들이 다 멋지고 잘생겼어요~! 진짜 부자집 아가씨가 된기분!! 한번쯤은 가봐도 될거 같아요!', 7, 6, 'GOOD', SYSTIMESTAMP);
