INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '외관부터 화려해서 시선을 사로잡는 장소에요 대저택인 만큼 인테리어도 화려하고 퀄리티 좋습니다 디저트도 맛있었고 집사님들도 친절해요😃 집사님들 중에서 레오집사님이 말 잘 걸어주시고 재밌으셔서 기억에 남았어요🐱', 34, 1, 'GOOD', SYSTIMESTAMP);
