INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대도 가보고 여기도 간건데 저는 개인적으로 대저택이 인테리어가 더 화려하니까 더 좋았어요~! 사진찍기도 좋고 아주 만족입니당', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '한국에 집사카페가 들어왔다는 소식을 듣고 경험해보고싶어서 예약 후 방문하였습니다. 연남에만 있을때에는 들어온지 얼마 안되서인지, 매장이 작아서인지 예약하기 어려워 매번 실패하곤 했는데 대저택이 생긴 이후로 어렵지 않게 예약했네요. 16시 예약하여 15시 52분 가량 도착하였습니다. 먼저 도착 할 경우 예약시긴까지 밖에서 대기하는 시스템이며, 시간이 되면 줄 서서 노크 후 입장합니다. 그 이후에는 다들 알다시피 집사분들의 환대를 받으며 자리 착석 및 주문을 하면 됩니다. 방문 시 운좋게 집사분들 라이브쇼를 두번이나 관람하였네요. 1층은 동물컨셉의 집사분들 (00분 기준) 2층은 뱀파이어 등의 컨셉을 가진 집사분들이 계시니 (30분 기준) 취향에 따라 선택하면 될 것 같습니다 꽤나 재미있는 경험이었어요^^', 37, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '할로윈 기념으로 방문했는데 제발 가세요 제발 루치펠 죽기전에 가셔요 집사님들 너무 착하시고 묻지도 따지지도 말고 일단 가보세요 ㅠ 가보면 제가 왜 이렇게까지 하시는지 알게될 수도 …', 28, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '드디어 쿠로님과의 체키를 찍었습니다 하울님 발렌타인님 레오님 정말 정말 사랑하옵니다 그리고 아이작님 오랜만에 뵈서 그런지 더 멋있어졌네요', 126, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '쿠로쇼 너무 조았습니다~ 너무 특별한 경험이였고 다음에 또 집사님들 보러 가겠습니다ㅎㅎ 그와중에 쿠로님 너무 귀엽고 매력 뿜뿜이에요♡♡♡', 2, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대 처음가는 동생이랑 특별한걸 해보고 싶어서 검색하다가 픽한 루치펠 대저택! 오픈하자마자 들어갈 수 있었고 모두 친절하셨어요 다만 시간이 끝나갈즘에는 직원분들이 테이블로 잘 안오시더라구요 먹을거리도 다 치워놓고 뻘하게 앉아서 대기하다가 가방받고 나왔는데 그부분이 좀 아쉬웠어요 :) 그나저나 아이작 집사님이 제일 친절하셔서 기억에 크게 남아요🤭 다음에 또 뵙기를!', 49, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '릴스로만 보다가 이번에 처음 직접 방문해 봤는데 처음에는 되게 어색했지만 시간이 지나니 나름 적응해서 재밌게 즐기고 왔습니다😳저희가 따로 종으로 집사님들을 부르지 않아도 가끔 다가와 주셔서 말 걸어주셔서 여러 집사님들과 대화를 할 수 있다는 게 좋았습니다 다음에 서울 갈 일 생기면 또 방문할 것 같네요☺ 럭키 드로우 짱!! 인생은 한 방', 60, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '3번째 방문이고 4시간 30분 동안 귀가 했는데 너무 재미있었고 시간이 생각보다 빨리빨리 간것 같아서 조금 아쉽긴 했지만 너무너무 즐거운 추억을 남긴것 같아 다음에도 추억 남기러 또 갈것 갔습니다!!☺️❤️', 32, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '부산에 있는 집사카페도 가보고 여기도 방문했는데 저는 부산이 볼 거리도있고 재밌고 좋은 경험이었어요. 여기서는 추가 옵션(?)을 안하니 신경을 별로 안쓰는 느낌이었고, 손님은 앉아있는데 집사분들이 서서 아래로 내려다보며 별 대화랄것도 없이 인사정도 하며 지나가는 느낌이 정신없고 별로였어요. 가게 인테리어는 멋지고, 디저트도 먹을만은 했는데 여기는 애프터눈티세트가 필수여서, 솔직히 전체적인 감상은 돈아깝다는 느낌이었습니다.', 126, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '첫 방문이였는데… 굉장히… 즐거웠습니다… 잘생긴 집사님들이 여럿… 😵‍💫 신나서 막 막 얘기했는데… 혹시라도 무례를 저지르진 않았나 걱정되네오…🥹 나중에 체키찍으러 또 가고싶습니다… 루치펠 짱… 👍🏻', 17, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '호기심에 한번쯤 와보고 싶었던 집사카페에요 예약이 연남저택으로 검색해야 링크가 연동되서ㅠㅠ 리뷰쓸때 연남쪽으로 작성이 되었네요 대저택쪽에도 남겨둡니다😙 유튜브를 통해 보고 무척 궁금해져서 방문하였습니다 즐거웠지만 용기가 무척 필요한 경험이었어요😂 아쉬웠던부분은 카페 내 음악소리가 너무커서 집사분들이 열심히 해주시는 이야기들이나 자기소개가 중간중간 잘 들리지 않았습니다😢 차나 디저트 종류를 큰 기대 안하고 갔는데 생각보다 무척 맛있었어요! 방문 기념으로 뭔가 남기고싶어서 가장 많이 이야기를 나눈 집사분께 폴라로이드 부탁을 드렸어요 아기자기하게 무척 정성들여 꾸며주셨습니다☺️', 65, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '유튜브 보고 처음으로 가게 됐는데 아무리 내 자신이 E 85%일지라도 집사님들 앞에서는 극I가 되는 마법이 펼쳐집니다.😂 굉장히 컨셉에 충실하셔서 나도 이 세계관에 몰입해 서민 체험하다가 집에 방문한 아가씨가 되지 않으면 안 될 정도로 너무 열심히 하셔서 멋있으셨습니다… 👍🏻 진짜 훤칠하고 준수하셔서 굉장히 멋있다고 생각하기도 했지만 직업 정신에 감탄하느라 바빴어요. 다음에 가게 된다면 그땐 꼭 우아하고 교양있는 아가씨가 되어 제대로 몰입하는 사람이 되겠습니다ㅋㅋㅋ 🤣🤣🤣', 36, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '- 둘이가서 1시간 놀고 인당 3만원 나왔어요 - 로테이션으로 계속 돌아가며 여러 명의 집사님이 테이블에 들려서 조금씩 말 걸어주고 가세요! - 컨셉에 잘 스며든 집사님들이 있는 반면 본인도 현타오셔하시는 집사님들도 존재..ㅎ - 디저트 생각보다 맛있고,다양하게 나와서 좋았어요! - 두명의 i가 같이 가버려서 재밌으면서도 힘들었어요..ㅠㅠㅠㅠㅠㅜ 꼭 E친구와 함께 가세요!!!! i끼리가면 돈 아까워요..ㅎㅎ - 생각보다 샴페인 먹는 테이블도 있어서 신기했어요. 안그래도 비싼데 샴페인까지...? 샴페인 시키니까 집사님들이 더 케어 열심히 해주시고, 같이 술도 마셔주더라고요. 신기방기... - 이 날 다른테이블이 공연 결제하셔서 덩달아 노래1개, 춤1개 공짜로 관람했어요ㅋ개이득~', 13, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '월요일에는 혼자 2시간 동안 있었는데 처음 혼자 가는거라서 좀 많이 걱정했는데 집사님들이 말도 엄청 걸어주시고 해서 너무 좋았답니당!! 이제 혼자 잘갈수 있을꺼 같아요!!☺️❤️', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '1달만에 귀가했는데 집사님들 바쁘신데 오셔서 알아봐주셨어요 라이브쇼도 보고 너무 감사해요 다음 귀가때 뵈요 다음 귀가때도  기대기대', 15, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '루치펠 대 저택😆딸램과 가보았어요~~~ 처음인지라 아가씨와 공주님 호칭이 너무나도 어색해서 처음엔 계속 둘다 부끄부끄ㅋㅋㅋ특히 극E성향인 딸램이 그리 부끄러워 하는건 처음이였음~그렇지만 쿠로집사님과 다른 멋진 집사님들의 도움으로 너무나도 즐겁게 놀다 왔어요~딸램 1시간 진짜 금방간다고 계속 아쉬워하길래 다음에 한번더 오자 약속하며 아가씨와 공주님은 이만 외출하였습니다ㅋㅋㅋㅋㅋㅋㅋ', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '처음으로 집사카페를 가는데 다들 너무 잘해 주시고 친절 하셨어 즐겁고 행복한 시간 보내고 왔습니다~~ 다음에 기회가 되면 또 방문 하고 싶어요~~^^', 39, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '유명하길래 궁금해서 이미 한 번 와 봤었다는 친구 데리고 가 봤어요 생각보다 재미있었고 특이한 경험... 돌아가면서 자주 대화 걸어 주셔서 한 시간 금방 갔어요 제가 너무 표정 관리가 안 되어 가지고 ^.^... 힘들었으나 진짜 재미있었음〰️', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친구가 요기 일한대서 암것두 모르고 놀러간거라 넘 외지인이었네요;;; 저땜에 당황했던 직원분덜 미안해여..🫠 저를 너무 대접해주셔서 적응 못한 티를 왕창 내고 왔슴다 ㅎ 저는 그러고 있었지만 직원분들은 컨셉마다 잘 어울리시고 계속 말 걸어주셔서 즐겁게 놀다 왔어요✨️ 라이브쇼를 되게 자주 하는데 다들 다재다능하시더라구요~ 라이브쇼 보랴, 사진 찍으랴, 말하랴, 먹으랴 한시도 심심할 틈이 없었어요 ㅋㅋㅋ 심지어 노래 마저 놀이공원 그자체🎡 방문하실 분들은 집에서 충전 많이 하다가 가시길..ㅎㅎ 대문자 E인 저도 기가 빨려서 화장실에서 심호흡하고 다시 들어가고 그랫읍니다 하핫😅 하지만 인생에 다시 없을 경험 찐하게 하고 재밌었어요 도파민 터지는 느낌이랄까🎆', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), 'Outstanding service, stunning interior, and some of the best tea and desserts around. If anyone is looking for a place to escape the stress and burden in their life, then this is the place to go. The staff treat everyone with the utmost consideration and care, making all customers feel special. Would highly recommend trying their special menu to enhance the experience even more.', 87, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '저번에 첫 귀가하고 이번이 두번째 귀가입니다！ 솔직히 첫 귀가 때는 항마력이 딸리지는 않을까, 집사님들께서 대충대충 해주시는 건 아닐까 걱정도 했었는데 첫 귀가 날 너무 잘 대해주셔서 그 날 바로 다음 귀가 일정 잡았어요(//∇//) 두번째 귀가날도 변함없이 너무 친절하셨고 재밌고,다정하셔서 너무 감사했고 당연히 바로 세번째 귀가 일정도 잡을 예정입니다 (о´∀`о) 첫 귀가 날엔 카이엘,워커,제리,시로,레이 님이 계셨고 두번째에는 데이,카이엘,워커,제리,오니 님이 계셨어요 우연한 행운이 두번이나 찾아와서 감사하게도 저는 두번의 귀가 모두 담당 집사님은 제리님이셨구 항상 외출하자마자 다음 일정을 잡을 정도로 너무 잘 대해주셨어요,,٩(๑❛ᴗ❛๑)۶ 400자 안에 제 마음을 다 못 담는게 슬플 따름이네요,,,', 17, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '기대없이 갔는데 너무 재미있었어요!!（≧∇≦） 집사분들도 다 잘생기고 예쁘시고 심심할 틈없이 가만히 두시지않고 말걸어주셨어요 라이브쇼도 멋잇어요♪(*^^)o∀*∀o(^^*)♪', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '집사분들이 공주처럼 대해줘서 재밌었어용. 친구랑 같이 갔는데 오죠사마인 척 하려니까 웃기더라구요. 친구랑 같이 오는 이색카페로 추천합니다.', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '나는 내가 한 번만 갈 줄 알았는데 계속 생각나서 또 방문했음 ''w'' 확실히 평일이라 그런지 손님도 많이 없었는데 다른 손님이 주문했던 라이브 무대를 같이 봤었는데 도파민 터짐 ㄹㅇ 그날은 거지 이슈로 못 했지만 다음에 가면 나도 라이브 무대 해야지', 15, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '테라스에서 사진 찍고 싶었는데 비가와서 찍지 못했습니다...😢 연남저택을 2월에 친구랑 가봤었고 이번에 혼자 대저택을 가봤는데 혼자 가니까 좀... 심심했어요 저택이 커서 집사님들도 다 바빠보이셨고 2월에 갔을때보다 집사님들과 대화도 적게 나눴고 뭔가 굉장히 아쉬웠지만 구경하는게 나름 재밌었어요 2월에는 그림도 그려주시고 뭔가 많이 해주셨었는데 이번엔 바빠보이셔서 말 걸기도 좀 눈치 보이더라구용... 그래도 1층에서 집사님들 공연 하시는것도 두 번 보고 2층에서 혼자 사진찍고 놀다 왓슴다..', 19, 2, NULL, SYSTIMESTAMP);
