INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), 'Wonderful experience from start to finish. The charming staff were incredibly friendly and easy to talk to. It is always amazing to see the heart and effort everyone puts into making all of the customers feel like royalty. The desserts and tea are heavenly, and there is never a dull moment throughout the visit. Would highly recommend taking a photo with one of the butlers to keep as a souvenir.', 45, 7, 'GOOD', SYSTIMESTAMP);
