INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '원래 저희동네 지점을 가는데 저희동네는 사라져서.. ㅠㅠ 슬퍼하다가 상수에 있는걸 알고 바로 갔어요!! 역시나 블루베리잼은 역시 맛있고 베이글도 정말 맛있습니다(샌드위치는 통밀로 변경돼서 다이어트에도 좋을거같아요) 다들 강추드려요⭐️', 36, 7, 'GOOD', SYSTIMESTAMP);
