INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아침식사겸 점심을 간단히 먹고자 친구랑 샌드위치 집을 찾던중 우연히 발견했는데 매장이 너무 예뻐서! 오늘의 브런치는 여기다!!! 싶어서 들어왔는데 매장도 넓고 베이글샌드위치 종류도 많아서 고르는 행복이 있었던 곳...! 근데 비주얼부터 맛까지 모두 합격!!! 베이글만 시켰는데 얼음물까지 같이 주시는 사장님 센스에 한번더 반했던 곳💗', 48, 7, 'GOOD', SYSTIMESTAMP);
