INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '빵순이인뎅 다양한 베이글이랑 크림치즈 종류에 행복해요! 🥯🥯🥯🥯🥯🥯🥯🥯♥️ 잠봉뵈르 한입먹자마자 너무너무 맛있어서 감동받았어요 베이글도 부드러운데 살짝타잇고 버터향이랑 잠봉은 적당한 짠맛으로 홀그레인소스랑 녹아듭니다 🤤 저장해두고 브런치먹으러 와야겟어요', 20, 0, 'GOOD', SYSTIMESTAMP);
