INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '매장도 넘 깔끔하고, 베이글 샌드위치 넘 좋네요!!! 든든하게 한끼 먹기도 좋고~ 맛있어서 딱이에요! ㅎㅎ 자주 올게요~ 베어 넘 귀엽❤️', 62, 11, 'GOOD', SYSTIMESTAMP);
