INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '베이글이 먹고싶어서 방문했어오 가격도 좋고 베이글도 정말 맛있어요 직원분들도 친절하시고 매장도 넓어서 먹고가기도 좋았습니당 아침식사나 브런치에도 정말 좋을것같아요👍🏻👍🏻', 36, 6, 'GOOD', SYSTIMESTAMP);
