INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '브런치로 먹기 좋아요! 베이글 종류도 다양해서 골라서 베이글 샌드위치로 먹으면 좋습니다😍매장도 청결하고 직원분들도 친절하세요!', 26, 6, 'GOOD', SYSTIMESTAMP);
