INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '토요일 오전 아침식사를 위해 방문햇습니다 가격이 저렴하고 내부는 깔끔한 인테리어라서 좋네요 완전 재방문 의사 있어요! 저희는 치킨브레스트 베이글샌드위치 주문했고요 브런치를  원하신다면 추천합니다~', 9, 0, 'GOOD', SYSTIMESTAMP);
