INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '가볍게 브런치 느낌으로 베이글 샌드위치 먹으러 왔습니다 아침식사 대용으로 좋습니다! 화장실도 깨끗하규 사장님께서도 올 때마다 친절하게 잘해주세요 올 때마다 기분이 좋아집니다^-^!', 29, 1, 'GOOD', SYSTIMESTAMP);
