INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '합정 근처에서 이른 시간부터 여는 아침식사할 집이 있어서 와봤는데 메뉴 구성도 알차고 넘넘 맛있어요⭐️✨ 브런치 먹고싶었는데 베이글, 치아바타 샌드위치 다 존맛입니다.. 자주 올 것 같아요 그리고 물도 한컵씩 챙겨주시는 거 너무 센스 있으셔요..🥹🫶 잘먹었습니다!', 2, 5, 'GOOD', SYSTIMESTAMP);
