INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '베이글 샌드위치 먹으러왔어요 너무맛있어요 점저로 먹으러왔는데 아침식사나 브런치로 오면 더 잘맞고 좋을 것 같아요 언제와도맛있어요 짱', 31, 10, 'GOOD', SYSTIMESTAMP);
