INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '상수역에서 지나가다가 베이글 샌드위치가 보이길래 들어와서 먹었는데 양도 많고 속이 꽉차있어서 아침식사 대용이나 브런치로 먹기 딱인거 같아요!!! 진짜 맛있으니까 꼭 드셔보세요:)', 27, 2, 'GOOD', SYSTIMESTAMP);
