INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '우연히 들려본 상수역 베어글스!! 가성비.짱인 베이글 맛집입니다.상수역 바로 앞.. 넒은 메장이라 친구들 다 끌고 와도 될듯합니다..ㅋㅋㅋ 커피도 유독 맛납니다~`!!  발라먹는 크림치즈도 짱짱!!상수역 강추 맛집!!!', 45, 5, 'GOOD', SYSTIMESTAMP);
