INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '베이글 샌드위치 전에 먹고 맛있어서 이번엔 베이글만 사러 왔어요 ㅎㅎ 아침식사도 되고 브런치로도 든든하던데, 다음에 단체주문 필요할때도 요청드리려고요~ 무엇보다 항상 친절하시고 매장이 청결해서 좋습니다!! 베이글 맛집으로 강추요!!', 119, 19, 'GOOD', SYSTIMESTAMP);
