INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '요거트 스무디 맛있게 잘 먹음. 음료를 주문했더니? 재사용 가능한 컵으로 주심. 매장도 청결해서 머물기 좋고  메뉴도 간단한 식사나 마실 거리가 있어서 가까이 있으면 자주 가고 싶은 매장임.', 11, 10, 'GOOD', SYSTIMESTAMP);
