INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '잠봉뵈르 샌드위치 먹고 싶어서 들어왔는데, 베이글 샌드위치랑 샐러드 같은 브런치 메뉴가 많고 매장이 넓어 혼자 아침먹기에도 좋은 가게 같아요~ 홍대에서 가격 부담도 없고 깔끔한 가게 흔치 않은데 자주 올 것 같아요 ㅎㅎ', 17, 5, 'GOOD', SYSTIMESTAMP);
