INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '베어글스를 너무 좋아하는데 저희 동네는 사라져서… 상수역 올때마다 방문하고 있어요!! 통밀로 변경되고 크림치즈도 너무 맛있어서 와서 베이글 드시는거 추천드려요!! #아침식사 #브런치 #베이글샌드위치', 17, 2, 'GOOD', SYSTIMESTAMP);
