INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '근처 미용실 가기 전에 우연리 들린 곳인데 맛집이네요! 잠봉뵈르 너무 좋아하는데 맛있어요!! 커피도 맛집! 미용실 올때마다 들릴듯!', 54, 17, NULL, SYSTIMESTAMP);
