INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '오랜만에 홍대 나들이 갔다가 동네 주민인 친구가 베이글 맛집이라고 추천해서 갔는데 완전👍👍👍 일단 외쿡에 여행 온 듯한 인테리어에 베이글과 크림치즈가 다양하고 신선해서 좋았어요! 무엇보다 직원 분들이 너무 친절하셔서ㅎㅎ 수다왕창 떨고 나오면서 집에 가서 부모님과 베이글 파뤼하려고 한껏 질러버렸네요🤭🤗🥰', 101, 23, 'GOOD', SYSTIMESTAMP);
