INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '음료를 안시켰는데 물을 같이주셔서 너무 감사했어요 ㅎㅎ 아이스아메리카노 리뷰이벤트있던데 그냥 말씀안드렸어요 ㅎㅎ ㅋㅋ 대가없이 쓴 리뷰입니다 담에또올게요~', 41, 2, NULL, SYSTIMESTAMP);
