INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '와 여기 분위기 너무 좋고 친절해요 이런 곳이 더 많아졌으면 좋겠어요. 번창하세요. 너무 맛있고 특히 치아 버터 샌드위치가 진짜 맛있어요. 친구랑 대화하기도 너무 좋아요. 추천합니다.', 33, 5, 'GOOD', SYSTIMESTAMP);
