INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '브런치로 커피와 딱인 베어글스 방문했습니다 샌드위치류중에 베이글로 만든 잠봉뵈르를 제일 즐겨먹는데요 매번 포장하다가 이날은 매장에서 먹었는데 혼밥하기에도 매장이 넓어서 좋았어요! 굿굿!', 54, 15, 'GOOD', SYSTIMESTAMP);
