INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '잠봉뵈르는 너무 짜지도 않고 느끼하지도 않아서 너무 맛있게 먹었어요 ! 1인 세트 시키면 한끼 든든히 먹을 수 있어서 점심이나 아침 브런치로도 너무 좋을 것 같아요 🤍🤍 커피 향도 좋고 적당히 달아서 빵이랑도 먹기 좋았어요 ! 그리구 음악 선곡들도 좋아서 카페 분위기랑 잘 어울렸어여 그리구 카페 디자인이 잘 돼있어서 더 쾌적해보였던 것 같아여 :) 그리고 직원분들도 다들 너무 친절하셔서 먹는 내내 기분 좋게 먹고 간 것 같아요 !! 다음에 다른 메뉴도 먹으러 또 방문하겠습니다 ❤️', 80, 14, 'GOOD', SYSTIMESTAMP);
