INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대 올때마다 들르는 곳입니다. 베이글이 너무 맛있어요! 식감, 재료의 양, 재료의질, 커피의 향, 커피의 맛 어느 하나 빠짐 없이 맛있습니다', 35, 3, 'GOOD', SYSTIMESTAMP);
