INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '집에서 5분거리인데 그 돌아다니다보면 그 어느 매장보다 눈에 띄고 인테리어가 정말 예뻐요. 직접 안에 들어가서 보면 메뉴도 정말 맛있는게 많고 건강이나 웰빙? 같은 요즘 트렌드에 맞는 음료 구성도 잘 짜여진 프랜차이즈 같아서 자주 이용할 것 같습니다.!  대박나세요👏🏻👏🏻', 8, 5, 'GOOD', SYSTIMESTAMP);
