INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '초코베이글은 처음인데 너무 맛있어요 (●´౿`●) 크림치즈랑 조합이 좋습니다! 음료 없이 베이글만 주문했는데 물도 같이 주는 센스 있는 곳. 다음엔 샌드위치 먹으러 올게용', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '인테리어도 완벽하고 맛도 있는 트랜디한 카페에요! 상수,합정,홍대분들은 굉장히 좋아할 MZ저격이네여!! 집이 근처라 자저 이용할 것 같아요 너무 맛있어요 샌드위치 맛집!! #샌드위치 맛집', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '아침에 우연히 들어온 베이글집인데 너무 맛있네요~ 베이글도 먓있고 커피맛도 좋아요~  바질크림도 너무 맛있고 플레인도 맛있어요~', 46, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '브런치를 먹으러 상수역에서 가까운 베어글스 홍대점으로왔습니다. 베이글샌드위치로 유명한 곳에서 혼밥도 할수있고 조용하게 작업할수 있어서 좋아요 😀', 20, 6, 'GOOD', SYSTIMESTAMP);
