INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '리유저블 컵이라 매장에서 바로 테이크아웃 컵으로 옮겨닮지 않고도 갈수 있어서 좋네요. 베이글종류도 다양하고 크림치즈도 다양해서 골라먹는 재미가 있을거 같아요 자주 갈것 같습니다', 0, 10, 'GOOD', SYSTIMESTAMP);
