INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '혹시 레시피가 바뀌었나요...? 아님 제가 마감시간 가깝게 방문해서 그랬을까요...?ㅠ 그냥 빵처럼 먹어도 될만큼 부드럽고 쫀득한 베이글을 좋아해서 베어글을 자주 갔는데, 오늘 포장해온 베이글들은 약간 퍽퍽하네요ㅜㅠㅠㅠㅠㅠ 아예 레시피가 바뀐거라면 앞으로는 잘 안가게 될 것 같아요ㅠㅠㅠㅠ 아쉽.... 같이 구매한 블루베리크림치즈는 맛있어요!', 46, 3, 'BAD', SYSTIMESTAMP);
