INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '상수에 이런 곳이…!!!! 친구랑 카페 찾다가 친구의 적극 추천으로 방문 하였습니다 근데 이건.. 먹자마자.. 내가 이 친구랑 친구 하길 잘 했다는 생각이 드는 맛이었습니다 .. 샌디치 대존맛.. 여기 진짜 샌드위치 맛집이네요 🥹🥹 바질 베이글 추청추천 개추천 !! 친구랑 샌드위치 한 개에 음료 2개시켜 나눠먹었는데 어우 충분했습니다 !! 특히 소금슈페너라는 음료가 단짝이 기가막힌게 여기 시그니처인가봐요 여러분 꼭 드세요 꼭이요 !! 💕💕', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '곰돌이가 넘 귀여워요 매장도 넓고 인테리어도 이뻐요! 그리고 젤 중요한건 샌드위치 존맛탱ㅜㅜ 샌드위치맛집이에요 베이글 그냥 먹어도 맛있는데 샌드위치는 더 맛있음..사장님도 짱 친절하심!!!', 54, 15, 'GOOD', SYSTIMESTAMP);
