INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '오랜만레 모펀카페 방문했습니다. 근데 인테리어랑 구조가 많이 바꿨더라구요! 더더 좋은 것 같아요! 깔꿈하고 넘 이뻐여. 늘 제가 좋아하는 웹툰이랑 콜라보해줘서 얼마나 감사한지.ㅠㅠ그리고 포카 받는거 너무 친절하게 알려주셔서, 감사하고 미안함이 들더라고요 ㅠㅠ 사전에 보고 올걸 ㅠㅠ3~4 번 틀려서 ㅠㅠ 결국 도움을 많이 주셔서 포카 받고 왔습니다. 너무 친절하시고 너무 좋은 추억이었어요! 감사합니다.!!', 42, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '에반게리온 전시를 보고 AK플라자를 전부 둘러봤을 때 본 카페 였어요! 브라우니가 정말 달달하고 맛있었습니다>< 귀여운 캐릭터 카드도 주셔서 좋았어요^^', 5, 1, 'GOOD', SYSTIMESTAMP);
