INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '강아지는 건드리지 마라 콜라보 카페 방문했었습니다💗 공간 구성이 알차고 스페셜 메뉴도 맛있었어요! 한번 더 가고 싶었는데 기간이 끝나서 아쉬웠어요🥹', 86, 18, 'GOOD', SYSTIMESTAMP);
