INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오프트랙 이밴트는 05/09일에 시작했는데 오늘 (05/13일) 대부분의 굿즈는 품절입니다. 아쉽지만 분위기도 좋고 음료수와 디저트도 맛있어요. 오늘 매장에 방문해봤더니 사람이 많지 않아서 즐거운 시간을 보냈어요. 조용하고 예쁜 공간이네요.', 47, 6, 'GOOD', SYSTIMESTAMP);
