INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '겉바속촉의 폭신한 식감이 살아있는 다쿠아즈의 신세계를 만날 수 있는 홍대디저트 맛집 카페장쌤, 리뉴얼한 매장 공간이 아늑하면서 조용한 분위기라 친구모임이나 데이트로 방문하기에도 좋고 혼자 방문하는 카공족들이 오기에도 불편함이 없어보였다. 겉면의 파삭함이, 속안의 촉촉함이 일품인 다쿠아즈는 카페장쌤의 시그니처메뉴로 꼭 주문해 맛보길. 한입 베어무는 순간 입안에 필링맛이 가득 퍼지는데 너무 달지 않고 필링 또한 느끼하지 않아 다쿠아즈를 잘 모르는 사람이나 단 것을 선호하지 않는 사람도 맛있게 먹을 수 있을 듯! 망고를 먹을지 고민하다 선택한 체리쇼콜라, 부드러운 초코크림과 빵시트의 촉촉함, 적당한 단맛의 조합이 좋았고 전체적으로 재료 본연의 맛이 그대로 살아있어 다른 메뉴들도 궁금해 꼭 재방문하고 싶은 맛집🍰', 127, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
