INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대에서 애착하는까페입니다 케이크와 다쿠와즈가 주력메뉴이고 커피와 음료 다 맛있어요 전체적인 톤이 아이보리인데 우드테이블어서 들어오면 아늑한 느낌의 카페입니다 다쿠와즈 종류가 정말 다양해요 폭신하고 크림도 맛있습니다 선물용 포장도 가능합니다 케이크는 부재료를 아낌없이 쓰는 타입이예요 딸기도 체리도 듬뿍듬뿍 들어 있어요 그리고 사장님이 정말 친절하십니다 홍대 올때마다 놀러올께요❤', 48, 2, 'GOOD', SYSTIMESTAMP);
