INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '매장은 많이 바쁜데 사장님이 혼자 하고 계셔요 🥲 정신없으실텐데 친절히 응대해 주셔서 감사했습니다 그와중에 디저트가 너무 이쁘고 알차서 계속 눈이 가더라구요 맛도 다양하고 속재료도 듬뿍 들어있는 점 맘에 들었습니다 선물용으로도 딱이에요!', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '어쩌다가 오게되었는데 너무 맘에 들었어요 들어오고 얼마안있어서 자리 다차서 조금만 늦게왔으면 자리 없어서 못먹고 갈뻔했어요 서비스로 주신 쿠키도 맛있고 케익도 맛있었어요 다쿠아즈도 궁금해서 사먹어봤는데 이것도 맛있어요 디저트 맛집이예요 너무 맛있게 먹고 갔어요', 42, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '와 여긴 안 오면 손해입니다. 진짜 가격도 착한데 장난아님 근데 찾기 힘들어요 보석같은 곳입니다. 찾을려면 지도보고 해당 건물의 입구 바로 위를 쳐다보십시오 1.5층에 위치해있을겁니다. 여기 안오고 다른 지역갈바에 여기서 하루종일 놀고 집가십시오 레전듭니다. 굿', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '정말 너무너무 맛있어요 🥺❤️ 서비스로 쿠키?도 주셨는데 진짜... 너무 맛있음!! 아아도 맛있어요... 사장님도 매우매우매우 친절하세여!!!!! 대화하기도 좋은 장소!!..', 76, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '여기 진짜 전부터 와보고 싶었는데 여태 미룬 시간이 아까울 정도로 진짜 좋았어요 디저트도 맛있고 라떼도 맛있어요 말차 좋아하는 사람들 여기 추천해요 그리고 사장님이 빨대 깜빡하셨다고 서비스로 다쿠아즈 주셨는데 너무 고맙고 미안했어요 ㅠㅠ 또 올게요!', 102, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '이제 홍대에서 일을 안 해서 잘 못 가다가 최근에 가서 다쿠아즈들 사재기 ㅋㅋ 늘 맛있고 실망 없는 카페예요 ㅎㅎ 더 챙겨 주려 하시는 천사 사장님도 최고 😊 오늘은(4/12) 친구 카드로 결제해서 영수증 리뷰는 못 쓰네요 ㅜㅜ 3월에 간 결제내역도 여태 계속 오류로 안 뜨다가 확인해 보니 이제 떠서 늦게나마 남겨요! 늘 잘 먹고 있습니다 감사합니다 🩷', 19, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대에서 딸기케이크가 먹고싶을 때 마다 오는 카페에요. 케이크 종류는 다 맛있고 다쿠아즈도 괜찮아요. 커피도 괜찮은데 밀크티는 다른 곳보다 연한편이에요. 카페도 예쁘고 마음에듭니다!', 21, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '케이크 예약후 픽업갔는데 제가 실수로 날짜를 잘못 써서 착오가 생겼습니다. 다음날 바로 쓸 케이크라 멘붕왔는데 너무나 친절하게 좀 기다리면 새로 만들어주시겠다고 하셔서 마침 더웠던 차라 커피 마시면서 기다렸습니다. 요새 커피가 다 연하게 느껴지는데 카페장쌤 커피는 진했고 서비스로 주신 쿠키도 맛있었고요. 케이크야 뭐 두말하면 잔소리죠 ㅋㅋㅋ 선물했는데 대체 이거 어디 케이크냐 미쳤다 소리 들었습니다. 그렇게 많이 달지 않고 쌉싸름한 초코맛이 딸기와 어우러져 다이어트 따위는 내일로 미룬 채 정신없이 퍼먹게 하는 맛입죠 ㅋㅋㅋ 딸기시즌 끝나기 전에 꼭 한 번 더 와서 프레지에 우유케익 초코케익 다 시켜놓고 먹방 한 번 찍어보고 싶어집니다. .', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '빵순이가 10년 넘게 좋아하는 단골집입니다. 그렇게 오래가도 안 질리네요. 우유 케익은 담백하고 퓨어한 맛, 프레지에는 진하게 향긋한 맛 매력이 달라 딸기철이 행복해요. 다쿠아즈도 세젤맛!!', 81, 18, 'GOOD', SYSTIMESTAMP);
