INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '일이 있어서 빠르게 포장해서 갔는데, 매장에서 이것저것 케이크를 다 골라먹고 싶은 곳입니다. 레몬 요거트 케이크는 정말 적당히 달달하면서 산뜻하고 상큼함이 요거트크림과 어우러져서 잘 들어가네요.', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '다쿠아즈 맛있습니다. 빵 부분도 부드럽고 필링도 넉넉하네요. 제주말차 엄청 꾸덕하고 향도 진해요. 망고치즈는 치즈라기보다 버터 같은 식감인데 망고향은 생각보다 약합니다. 매장이 협소한데 테이블이 많아서 거의 술집급으로 시끄럽더라구요. 공기도 텁텁한 느낌.. 테이크아웃 추천합니다.', 0, 9, NULL, SYSTIMESTAMP);
