INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오분만에 케이크 순삭.... 서비스로 주시는 쿠키도 너무 맛있어요ㅠㅠㅠ 재방문의사 500%!! 사장님도 바쁘신데 친절하세요 ><', 31, 1, 'GOOD', SYSTIMESTAMP);
