INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '정말 오랜 시간 좋아한 장쌤입니다. 사장님 안 계실 때 갔는데 응대가 엉망이었습니다. 너무 불친절해서 맛있는 다쿠아즈 사고도 기분이 안 좋네요.', 97, 22, 'BAD', SYSTIMESTAMP);
