INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '사장님도 인상이 너무 좋으시고 디저트도 진짜 맛있어요..🥹🥹 망고케이크가 아직도 입안에서 아른거리는 것 같아요🤤 홍대나 연남동 갈일 있으시면 가시는 걸 추천 드려요:)', 37, 2, 'GOOD', SYSTIMESTAMP);
