INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '카페 웨이팅 굉장히 오랜만인 것 같아요 크림이 산뜻하고 맛있어요 ! 서비스로 주시는 사브레 쿠키도 맛있네여 한 번 가보실만 합니다', 24, 10, 'GOOD', SYSTIMESTAMP);
