INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '얼마간 휴식기 가진 후에 재오픈한 카페장쌤에 오랜만에 가봤어요ㅎㅎ 다쿠아즈 먹어보고 맛나서 부모님댁에도 택배(네이버주문😎)로 보내드렸었는데 맛있다고 하셨던 곳입니당 다쿠아즈도 맛있지만 쉭세와 케익, 쿠키 등의 종류도 맛있어요ㅎㅎ 이번엔 마들렌도 먹어봤는데 맛있더라구요.. 전부 달달한데 느끼하진 않고 재료들 듬뿍 들어간 맛이에요 살짝 바뀐듯 여전한듯 간만에 가보니 반가웠습니다ㅎㅎ', 24, 7, 'GOOD', SYSTIMESTAMP);
