INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '빵의 도시 대전에서 놀러온 지방인 입니다! 우선 정말 운이 좋게도 딱 한자리 남았을때 들어와서 바로 자리를 잡을 수 있었고 콘센트가 좀 있는거 같더라구요 덕분에 여행하는데 불편함이 없었습니다! 사장님께서 바빠보이시지만 굉장히 친절하셔서 조용히 머물다 갑니다👍🏻아 그리고 케이크 진짜 맛있어요 사실 다쿠아즈는 제가 많이 먹어보진 않아서 객관적으로 비교해서 말씀은 못드리지만 많이 달지않고 맛있어요!! 폭신 달콤 꾸덕느낌! 글고 케이크는 많이 먹어본 대전빵순이로서 대존맛입니다 크림도 딸기도 시트도 매우매우 상태가 좋아서 1분만에 먹었어요 촉촉하고 딸기는 단단하고 크림은 가벼운데 진하고 입에 넣자마자 녹더라구요 홍대 다시 놀러오면 다음엔 엄청 사갈거에요 오래오래 장사해주세여!!', 106, 24, 'GOOD', SYSTIMESTAMP);
