INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '이야기 하기 좋아요 분위기 좋고 딸기우유케이크 진짜 맛있어요 다음에 홍대 오면 여기 또 올게요 사장님 정말 친절하시고 테이블까지 직접 가져다주셔서 대접받는 기분들어요 매장 전체적으로 깨끗하고 인테리어도 좋아요 방문하는 길에 소품샵도 귀엽고 기분 좋게 구경했답니다 다음엔 다쿠아즈 사먹으러도 올게요', 5, 5, 'GOOD', SYSTIMESTAMP);
