INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '다쿠아즈가 종류별대로 많아서 뭘 고를까 고민될 정도였어요 크기도 큰데 크림도 진하고 꼬끄도 부드럽고 맛있네요 나중에 선물용으로 사도 좋을거같아요 프레지에 케이크도 바닐라빈이 많이 들어있었고 크림이 부드러웠어요 피칸바도 제가 견과류 좋아해서 호기심에 사봤는데 맛있네요! 사장님도 친절하셔서 제 기억에 남는 카페가 될 것 같아요 ㅎㅎ 나중에 또 방문할게요:)', 49, 1, 'GOOD', SYSTIMESTAMP);
