INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '학생때부터 홍대가면 자주가던 카페였는데 역시나 디저트는 항상 맛있군요,, 서비스로 주시는 쿠키는 너무 부드럽고 사르르 녹아여 케이크도 완전 추천,,', 34, 6, 'GOOD', SYSTIMESTAMP);
