INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '저의 최애. 10년 넘게 먹고 있는 빼빼로입니다. 이 시즌에만 만날 수 있어 더 귀하고 푸근하니 맛있어요. 인절미 다쿠아즈도 사랑이고! 피스타치오 쉭세도 좋았습니다. 장쌤은 진리💝', 13, 3, 'GOOD', SYSTIMESTAMP);
