INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '너무너무 맛있어요…❤️❤️❤️❤️❤️❤️ 디아망도 입에 넣자마자 사를륵 녹고 다쿠아즈도 퐁신하니 정말 맛있어요! 추천합니당 호', 50, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '혼자서 모두 운영중이신지 사장님이 매우 바빠보이셨지만 너무 친절하시고 디저트 케이크도 맛있었어서 다 이해가능 >_< 서비스로 쿠키과자? 까지 주셨는데 너무 귀여워요 ㅎㅎㅎ 주말에 방문했는데 카페는 큰 편이 아니라 잠깐 대기가 필요했어요~ 아늑한 카페로 제기준에는 추천입니다.', 16, 6, 'GOOD', SYSTIMESTAMP);
