INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '홍대 반지하에 있을 때부터 단골이에요!! 그동안 리뉴얼로 계속 못 가고 있다가 이번에 선물용 쿠키 사러 오랜만에 방문했어요!! 여전히 친절하신 사장님을 보니 기분이 좋았어요!! 쿠키도 진짜 맛있었어요', 65, 17, 'GOOD', SYSTIMESTAMP);
