INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '사장님..제발 .평생 카페 해주세요🥹 다쿠아즈 여기서만 먹어요 디저트 너무너무너무 맛있고 사장님도 짱 친절하세요 홍대 갈 때마다 꼭 들릴 예정입니다!!', 5, 1, 'GOOD', SYSTIMESTAMP);
