INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '밥 먹고 근처 카페 찾아보다가 후기가 좋아서 갔는데 너무 좋은 선택이었어요!! 기본 서비스로 나오는 쿠키도 맛있고 가을황도우유케이크 존맛탱.. 다쿠아즈도 맛있어요... 아메리카노도 디저트랑 너무 잘 어울리고!! 생각보다 매장이 넓고 화장실도 내부에 깨끗하게 있어서 좋습니다... 사장님도 짱 친절하심👍🏻👍🏻', 47, 9, 'GOOD', SYSTIMESTAMP);
