INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '이곳은 나만의 아지트이자 만인의 아지트 카페장쌤 모든 메뉴가 기본 이상의 맛이 보장되어있기 때문에 추천드립니다. 선물용으로도, 그냥 내가 먹는 디저트로도 모두 좋아요!', 73, 18, 'GOOD', SYSTIMESTAMP);
