INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '다쿠아즈 두종류와 라떼를 시켰는 데 쿠키도 같이 주셨어요! 음료와 함께 즐기면 된다고 설명해주셨습니다😊. 쿠키 퀄리티가 높아서 사먹어야할 것 같았지만ㅎㅎ 맛있게 잘 먹었어요. 해외에 사는 데 제가 가본 어느 곳도 카페장쌤의 다쿠아즈만큼 맛있지 않아서 한국 들어올 때마다 꼭 들립니다🌸 또 방문하겠습니다🫶', 50, 10, 'GOOD', SYSTIMESTAMP);
