INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '사람이 많아서 매번 못 앉았던 인기많은 카페인데 비가 와서 그런지 자리가 있었어요~!! 케익도 다쿠아즈도 짱맛 특히 바닐라빈 케이크 진심 강추합니다.... 크림은 바닐라향 가득하고 아래 시트는 바삭바삭해요😍💕', 55, 14, 'GOOD', SYSTIMESTAMP);
