INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 최고의 딸기 케이크 집 🍰👏🏻👏🏻 작년 크리스마스때 처음 먹고 반한 후 벌써 3번째 재구매에요 ㅋㅋ ㅜㅜ 다른 딸기케이크 먹어도 여기를 잊을 수가 없어요🥹 엄~~~~~청 촉촉해서 앉은 자리에 한판 뚝딱 했네요 🤤 너무 맛있어요 , 사장님도 엄청 친절하시구 .... 오래오래 남아주셨으면 좋겠네요, 💗💗', 1, 8, 'GOOD', SYSTIMESTAMP);
