INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '프레지에 막바지라고 하셔서 다녀왔어요. 프레지에는 가족을 위해 포장했고 웨딩 임페리얼과 바닐라 무스 덕분에 행복한 혼자만의 시간을 보냈습니다😊', 82, 12, 'GOOD', SYSTIMESTAMP);
