INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '진짜진짜 맛있는 다쿠아즈!!! 선물용으로도 좋아요! 맛도 다양해서 골라먹는 재미가 있고요ㅋ 오늘 홍대점가서 사왔는데, 9개만 샀는데 집에 와서 보니 사장님께서 2개나 더 주셨더라고요!!🥰 진짜진짜 감사해요오!!!! 친절히 박스에 담아주시고오!! 진짜 최곱니다.', 230, 73, 'GOOD', SYSTIMESTAMP);
