INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '저번에 매장에서 레몬 요거트 케잌 조각으로 먹고 반해서 올해 생일 케이크는 장쌤에서 예약 했어요!!!(칭구야 케잌 선물 넘 고마버🥹👍💛) 픽업하고 잠깐 딴길로 새서 놀다가 케잌 옆면 레몬색 크림이 쪼끔 녹아서 흘렀는뎅(스불재)ㅋㅋㅋㅋㅋ 맛은 처음 먹고 감동한 그대로였어요! 요거트의 부드러우면서 은은하게 시큼한 맛 + 레몬의 상콤한 향기 + 입안에서 사르르 녹아 없어지는 크림 + 겉 코팅 크림에 콕콕 박힌 바닐라빈 + 보드랍고 촉촉한 시트까지!!! 환상의 하모니랍니다🍋🍋🍋 디저트류 별로 안좋아하시는 엄마두 맛있게 드셔서 넘 뿌듯했네요!🥰❤️❤️❤️ 디아망, 다쿠아즈 전부 맛있으니 다들 꼭 드셔보시길!!!😋😋😋', 49, 0, 'GOOD', SYSTIMESTAMP);
