INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '옛날부터 좋아하던 곳이었는데 딸기 프레지에 맛이 변한것 같아요... 빵 비율이 줄어들고 뭔가 더 달라진것 같아요 많았을때가 더 맛있었어요 아쉬운 마음에 리뷰 남깁니다 아아랑 다른케이크는 여전히 맛있었어요!', 34, 5, NULL, SYSTIMESTAMP);
