INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '두 번째 방문. 쿠키를 저만큼이나 같이 주시니 굉장히 혜자! 저거 어엄청 맛있음! 혼자 시간 보내기에도 좋고 친구랑 조용히 얘기 나누기에도 좋은 공간. 게다가 매번 친절하시다.', 19, 1, 'GOOD', SYSTIMESTAMP);
