INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '장쌤 처음 방문해봤는데 완전 최고 짱입니다! 제가 지금까지 살면서 먹어본 디저트 중 탑3에 들 정도로 맛있어요. 화욜날 갔는데 너무 맛나길래 그 주 금요일에 또 갔어요. 저 일주일도 채 안되는 시간동안 장쌤에 10만원 넘게 쓴 것 같아요..ㅋㅋ 케이크 다쿠아즈 모두 짱짱 맛있어요! 저 혼자 다쿠아즈 열개 먹을 수 있을 것 같아요ㅠㅠ 장쌤 최고❤️❤️', 11, 2, 'GOOD', SYSTIMESTAMP);
