INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '여러번 방문했었는데 매번 친구가 계산을 한번에 해줘서 영수증 리뷰는 처음이네요! 언제나 보장된 퀄리티의 맛있는 디저트가 가득한 곳이라 홍대에서 애정하는 카페들중 하나랍니다! 겨울이니 딸기 프리지에 먹고싶어서 방문했는데 레몬 요거트 케이크에 더 뿅가서 훕입했어유ㅎㅎ 다쿠아즈도 퐁신퐁신허니 맛있구~ 사장님은 항상 친절히 응대해주시고 서비스도 잘 챙겨주셔서 너무 좋아요!🥹🥹🥹🫶🫶🫶❤️❤️❤️', 34, 5, 'GOOD', SYSTIMESTAMP);
