INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '다쿠아즈 종류가 다양해서 좋은곳..!인데 이번엔 프레지에가 맛있다는 소식에 찾아감. 기대를 너무했나 프레지에랑 딸기푸딩은 무난했고 딸기 다쿠아즈 맛있었다🍓', 116, 20, NULL, SYSTIMESTAMP);
