INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대 다쿠아즈 1등 ..! 너무 친절하셔서 올때마다 기분 좋아여 요기 다쿠아즈 종류는 사실 뭘먹어도 맛있어서 ㅎㅎ 선물하기도 좋아요 !!', 26, 7, 'GOOD', SYSTIMESTAMP);
