INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '디저트에 일가견이 있으신 분께서 만드신 것 같습니다. 피스타치오 베리 다쿠아즈도 케이크도 너무 맛있었어요! 다쿠아즈는 먹고 또 포장구매 했답니다. 블루베리 스무디도 블루베리가 굉장히 많이 들어간 게 느껴지는 생블루베리 맛이었어요. 정성스러운 디저트에 감동하고 갑니다.', 31, 7, 'GOOD', SYSTIMESTAMP);
