INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '파블로바 포장이 안되서 레몬요거트케이쿠와 프레지에 포장했습니다. 프레지에 크림이 커스터드 크림인 것 같은데 맛있네요. 레몬요거트케이쿠는 레몬향은 진한데 신 맛이 안나서 커피에 먹기 좋았어요.', 40, 3, 'GOOD', SYSTIMESTAMP);
