INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '와! 왘!! 여기 진짜 개미친 다쿠아즈 맛집!! 살면서 다쿠아즈는 늘 그닥 맛있다 못 느껴본 사람인데요, 제가 지금까지 먹은 다쿠아즈는 다쿠아즈가 아닌거로 정의하기로 했슴다,, 진짜 미친 다쿠아즈에요. 맛이 다양해서 고민하다가 피스타치오베리로 주문했는데, 크림이 하,, 너무 달지 않으면서 다쿠아즈의 그 뭐랄까 바삭하면서도 퐁신한 느낌이랑 아주 찰떡으로 우아하게 어우러져요,, 홍대 오면 필수 코스임다 이제 딸기케이크는 비쥬얼이 쏘핫하죵?? 근데 생크림이 너무 적어서 제 스탈은 아닌거루,, 그치만 비쥬얼이 너무 강력하니깐 완전 용서됨니당,, 사장님 혼자서 운영하시느라 바빠보이시는데 그 와중에 친절을 잃지 않으시는,, 감둥,, 조용하게 방문하기 좋은 카페에요. 집 근처에 없다는 사실에 그저 눈물을,, 주륵', 13, 2, 'GOOD', SYSTIMESTAMP);
