INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '원래 멀어서 네이버로 주문해서 먹었었는데 이사와서 직접 왔습니다 역시나 너무 맛나요 다쿠와즈의 킹왕짱가게 근데 딸기프레지에 뭐죠..? 완전 맛나요 ㅠㅠㅠㅠ', 13, 10, 'GOOD', SYSTIMESTAMP);
