INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '항상 프레지에를 사는편인데 이번주는 초코바나나와 샤안버스캣이더라구요! 제가먹을거면 샤안을 골랐을텐데 생일케이크라서 한참고민하다 초코바나나를 골랐어요 ! 받은분도 대만족 저도대만족! 우유랑 먹었는데 커피랑 먹어도 맛있었을것 같아요!!', 8, 10, 'GOOD', SYSTIMESTAMP);
