INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '직원분이 너무 친절하시고 일정금액 쓰면 꼭 서비스를 주시더라구요 매번 너무 감사한데 또 서비스도 너무 맛있어요 다쿠아즈 정말 맛있는 곳인데 받은 쿠키도 맛있어서 다음엔 쿠키 사볼거예요!', 23, 1, 'GOOD', SYSTIMESTAMP);
