INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '서울살이 할때 맛있게 먹었던 곳인데 본가 내려왔을때 종종 생각나서 서울오면 꼭 들리는곳 중 한곳이예요 매번갈때마다 사장님도 친절하시고 한결같은 맛과 분위기 너무 좋아요 자주는 못가지만  오래오래 자리 지켜주세요💓', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '홍대갈때마다 들르던 다쿠아즈맛집 카페장쌤 간만에간 홍대나들이라 다녀왔지요😋😋 여전히 친절하시고 여전히 맛있고 여전히 기분좋아지는 맛입니다:)', 11, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '지금 자리로 옮기기 전, 얼추 10년 전부터 친구랑 종종 가던 곳이에요. 예전에도 디저트 참 맛있었는데 요즘엔 더 다양해졌네요. 선물로 왕창 사는 김에 같이 간 디저트 잘 모르는 친구도 먹어보라고 몇 개 사줬더니 너무 맛있다고, 앞으로 피스타치오를 자기 최애 맛으로 삼겠다고 감격했어요. 영업 성공해서 뿌듯합니다ㅎㅎ 사장님께서 살뜰하게 챙겨주시고 포장도 예쁘게 해주셔서 선물도 잘 했어요. 선물용으로 사느라 제가 먹을 건 못 샀지만ㅠㅠ 조만간 들러서 저 먹을 것도 몇 개 사려구요!! 사장님 번창하세요😄😄', 104, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '포장으로 샀어용!역시 다쿠아즈 맛집이에요!! 선물할것이라고해서 아이스팩까지 되게 꼼꼼하게 이쁘게 포장해주셨어요!감동이에요!또 와야즁!!', 84, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '제 친구가 추천해 줘서 마감 시간 가까이 갔는데, 정말 너무 친절히 대해주시고 포장도 어찌나 잘해주셨는지 엄청 흔들면서 집에 가지고 왔는데 한개도 한흐트러 졌어요! 맛도 ㅠㅠㅠ 제가 원하던 생크림케잌 맛이고 과일도 엄.청. 싱싱하네요. 사장님의 친절함과 맛의 감동으로 제 외국사는 친구 마지막날을 빛내주셔서 정말 감사드립니다. 번창하시기를 응원할게요!!! 🙇‍♀️🙇‍♀️', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '다쿠아즈 맛집이라고 추천받아서 선물용으로 20개 구매하러 갔습니다! 근데 사장님께서 보냉백 포장도 그냥 해주시고, 요청하지도 않았는데 서비스도 왕창 주시고ㅠㅠ 집에 와서 풀러보고 너무 놀랬어요. 죄송+감사한 마음으로 한 입 먹어보는데 진짜.... 대존맛.... 필링이 진짜 하나같이 맛있어요.... 정신줄을 부여잡고 두개에서 멈췄는데 순간 선물안주고 제가 다 먹고싶었습니다... 다음에 또 갈게요 사장님.... 알러뷰', 30, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '대체불가 다쿠아즈!!! 선물용으로 아주 좋아용~ 선물용으로 구입하면서 제가 먹을 것도 샀습니다 ^^ 샤인머스켓 정말 톡 터지면서 살살녹아요 넘 맛있어요 글구 캬라멜헤이즐넛도 존맛. 빨리 딸기철이 왔음 좋겠네요 장쌤딸기다쿠아즈 얼른 먹고싶어요♥️', 31, 1, 'GOOD', SYSTIMESTAMP);
