INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '너무 너무 사랑하는 카페 ••• ₍ᐢɞ̴̶̷ ·̮ ɞ̴̶̷ᐢ₎ ♡ 사장님도 친절하시고 분위기도 아늑하고 사랑스러워요! 다쿠아즈로 유명한 걸 잘 알고 계실텐데 저도 한창 카페 장쌤 다쿠아즈에 빠졌을때는 매주 6개 세트로 사서 먹었답니다 .. 요새는 건강을 위해서 자제하고 있지만요. 또 저는 커피를 먹지 않는 터라 논커피 메뉴를 유심히 보곤 하는데 다른 카페에서는 잘 판매하지 않는 마리아쥬 프레르 티를 보유하고 계세요! 커피 말고 다른 음료를 드시고 싶은 날이면 꼭 한번 맛보시길 추천드립니다 ㅠㅜ  여름이라 복숭아 요거트 케이크가 나왔다길래 헐레벌떡 달려가서 구매했어요! 오래 오래 그 자리에 있어주세요♥', 129, 20, 'GOOD', SYSTIMESTAMP);
