INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '밀크티케이크, 샤인머스켓 다쿠아즈랑 커피로 먹었어요. 커피도 디저트랑 먹기 좋고 디저트도 하나하나 다 맛있었어요. 케이크는 엄청 부드럽고 다쿠아즈도 과일이 있어서 그런지 상큼하고 좋았어요', 17, 9, 'GOOD', SYSTIMESTAMP);
