INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '지인 선물용으로 포장하는 곳이에요 맛, 퀄리티 , 비쥬얼 다 보장된 곳이라 가끔씩 가는데 사장님 너무 친절하셔서 갈때마다 행복합니다 오래오래 영업해주세여~>___<', 34, 0, 'GOOD', SYSTIMESTAMP);
