INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '많고 많은 홍대 카페들 중 세 손가락 안에 들어요 아진짜쮼맛탱…😻 밀크티쇼콜라랑 딸기생크림케이크 모두 크림이 진하고 안 질리고 감동적인 맛이에요 카페 분위기도 너무 포근포근하구 계속 머물고 싶은 장소랄까 . . 쵝오😻👍🏻', 10, 4, 'GOOD', SYSTIMESTAMP);
