INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '제일 좋아하는 다쿠아즈 맛집✨️🩷 예전엔 홍대 자주 가서 종종 사먹곤 했는데, 집이랑 회사 멀어지고 자주 못 가는 게 아쉽네요ㅠㅠ 그래도 여전히 인생 최고의 다쿠아즈 맛집💕', 72, 18, 'GOOD', SYSTIMESTAMP);
