INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '💓프리지에 딸기케이크 먹으러 달려간 곳 🍰🍓 프리지에 케이크는 명성답게 큰 딸기가 콕콕 박혀있고 바닐라?슈? 크림이 가득해요! 빵보다 크림이 더 많아서 퐁신퐁신하고 그때 딸기가 씹히며 입안이 싸악 정리되는데 케이크 한판은 무조건 쌉가능🥹 끄앙 너무너무 맛나요💕 오레오 다쿠아즈도 쫀득달달🤟🤟 무슨 맛을 먹어도 맛있을 꼬끄😋 아메는 스벅 맛이에요! 산미없이 살짝 탄맛. 아 쿠키 서비스 헤헤 짱 좋음🍪 테이블 크고 좌석간 간격도 넓어서 정말 대화하고 친구들이랑 간단히 초 불기 좋아요!! 우디우디한 인테리어도 예쁨🤎 다만.. 주문하면 사장님이 좌석까지 서빙해주세용🥹 카페에서 일하시는 분이 오직 사장님 한분이라 너무너무 바쁘신데도 서빙까지 하시니 살짝 로드가 걸리긴 하시는 것 같긴해요!', 10, 4, 'GOOD', SYSTIMESTAMP);
