INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '감동해서 구매 후에 바로 리뷰 남겨요.. 궁금한 맛 여쭤보다가 다른 걸로 구매했는데 궁금하셨던 거 한 번 먹어보시라며 덤으로 하나 더 챙겨주셨어요… 원래 가던 다쿠아즈 집이 있었는데 인스타 공지로 휴무를 해서.. 여기 디저트가게로 처음 와봤는데 앞으로는 여기로만 오려구요ㅎㅎ 감사합니다 사장님 맛있게 먹을게요! 번창하세요 :)', 38, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '딸기 프레지에 미니 사이즈 샀는데 둘이 먹기 딱 좋았어요! 예쁘고 맛도 너무 좋았어요! 리뷰에 다 맛있다고해서 기대하고 먹었는데 정말 맛있네요!!! 커피 시켰는데 쿠기도 같이 주시고, 케이크에 귀여운 곰돌이 초랑 다쿠아즈도 주시고 감사합니다:) 케익이랑 디저트 종류도 많아서 다음에 가서 다른 것도 또 먹을려고요! 사장님 항상 건강하시고 오래 장사해주세요:)', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '사장님 감사합니다.. 사랑합니다.. 천년만년 팔아주세요ㅠㅠ 디저트들 미치도록 맛있어요ㅠㅠㅠ 다쿠아즈 : 천국에 온 기분드는 부드러운 빵? 에 쫀득하고 재료 아낌없이 들어간 크림!! 🤎얼그레이🤎가 진짜 미쳤어요.  너무 맛있어서 바로 다쿠아즈 4개 더 포장했습니다ㅠㅠ 밀크티 보틀 : 2잔 나올 정도로 양이 많아요! 향이 최고 미니 딸기케이크 : 안에 들어간 크림이 바닐라빈 듬뿍 들어간 크림이에요ㅠㅠ 딸기도 듬뿍!! 그리고 사장님이 너무 친절하셔요ㅠ 서비스도 챙겨주시고, 케이크 샀더니 귀여운 곰돌이 초도 챙겨주셨어요!!! 자주 오겠습니다! 번창하세요 :)', 34, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '여기 다쿠아즈 너무 맛나요. 친구집에 갈때 주려고 퇴근길에 세트 골라 담아가요. 예쁘게 포장해주셔서 더더 기븐좋고 서비스로 딸기 다쿠아즈도 주셨어요. 사장님 센스 갈때마다 기분 좋아요! 케익도 여기 엄창 맛나요!! 완전 강츄', 5, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '자주 오던 곳이었는데 항상 낮에가다가 저녁때갔는데 여자직원분이 계셨어요 남자사장님은 정말 친절하셨는데 혼자 바쁘신지 응대가 아쉬웠습니다 디저트는 맛있어요', 36, 9, NULL, SYSTIMESTAMP);
