INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '다쿠아즈 맛집에서 선물하려고 샀어요~ 포장도 이쁘게 해주셔서 안에 내용물 사진은 못 찍었지만 맛있을 거에요. 딸기 다쿠아즈 먹어봤는데 정말 맛있었거든요 ^^ 거의 문 닫을 시간에 가서 걱정했는데 친절하게 대해주셨어요. 감사합니다~', 57, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '항상 맛있어요 ㅎㅎ 살때마다 서비스 주시고 사장님이 너무 친절하시고 센스도 짱짱 ㅜㅠ 짐이 있었는데 넣고가라고 쇼핑백따로 챙겨주셨어여 감사합니다~! 홍대 카페중에거 최고 마싯는 장쌤 ㅠㅠ', 28, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '카페장쌤 미니프리지에 진짜 갓성비에요!! 2만원 이하 딸기케이크에 이런 싱싱하고 달달한 딸기에, 생크림이랑 커스타드크림 진짜 고급지고 맛있어요! 순식간에 흡입했어요🤤', 124, 22, 'GOOD', SYSTIMESTAMP);
