INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '레몬요거트 케이크 정말 촉촉하고 사르르 녹아요 상크한맛 케이크 별로 안좋아하는데 여기 케이크는 맛있었고 다쿠아즈도 맛있어용 :)', 86, 15, 'GOOD', SYSTIMESTAMP);
