INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '💬  다쿠아즈의 근본!!!! 🍽  다쿠아즈 3.5 / 음료 5~6천원대 📍  공항철도 홍대입구역 인근 👥  남자친구랑 📅  토요일 오후 2시 (웨이팅 15분) ⭐️ 5.0 - 주관적 별점 : 장쌤, 오래오래 장수하세요 🥹', 99, 22, 'GOOD', SYSTIMESTAMP);
