INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '또 들른 카페 장쌤… 딸기 프레지에 시작했는데 안 가볼 수 없죠..빵 시트 안 좋아하시는 분들께 적극 추천.. 딸기 좋아하시는 분들께 적극 추천.. 그냥 드세요… 맛나요… 다쿠아즈는 말모…', 38, 10, 'GOOD', SYSTIMESTAMP);
