INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '산딸기 에이드라는 메뉴도 특색있고, 딸기 케이크가 정말 맛있었어요. 딸기도 달고 케이크 크림도 우유 생크림맛이어서 더 좋았어요.', 33, 3, 'GOOD', SYSTIMESTAMP);
