INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '예전부터 눈여겨봤던 디저트 집인데 세상에 !!! 다쿠아즈 왜이렇게 맛있나요ㅠㅠㅠㅠ딸기 다쿠아즈 먹고 너무 놀랐어요!! 원래 딸기 디저트에 대해서 큰 기대가 없었는데 여기건 너무 맛있어서 인기있는 프레지에도 꼭 먹으러 와야겠어용!! 다쿠아즈 가격도 괜찮고 맛도 정말다양해요!~! 고르는게 넘 재밌었구 사장님?도 너무 친절하셨어요~~', 77, 18, 'GOOD', SYSTIMESTAMP);
