INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '크앙 추천 받아서 저장해두고 찾았었는데 휴무일에 딱 걸려서 헛탕치고 오늘 드디어 와봤는데 음료도 맛있고 디저트도 맛있고 친절하셔서 기분 좋은 휴식시간이었고 다쿠아즈 마들렌 좋아해서 자주 올 거 같아요 밀가루가 들어가지 않는 다쿠아즈 신기해용 :)', 51, 15, 'GOOD', SYSTIMESTAMP);
