INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '딸기덕후가 인정한 딸기케이크맛집! 너무 맛있어서 잊지않고 또 왔어요! 항상 만족하는 맛! 역시 맛있어요 신선한 딸기에 생크림, 바닐라빈 들어간 크림까지!!! 넘 맛있어요 ㅎㅎ', 64, 12, 'GOOD', SYSTIMESTAMP);
