INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '통딸기가 들어있는 딸기케이크🍰 위는 생크림 안은 바닐라크림인데 엄청 달달한 케이크 맛있어요~ 포장했는데 고정이 잘 안된건지 케익이 쓰러져있었어요.. 넘어진 모양이 요상해서 담을때부터 쓰러진건지 모르겠지만.. 포장에도 신경써주시면 좋을 것 같습니다~', 34, 3, NULL, SYSTIMESTAMP);
