INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '항상 친절하시고 디저트는 언제나 맛있구요. 하나 사러 가서 두개 사게 되는… 딸기시즌이 시작되었어요! 꼭 딸기 프레지에 드셔보세요 추천 추천', 41, 5, 'GOOD', SYSTIMESTAMP);
