INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '빼빼로데이 기념해서 직장동료들에게 선물했습니다~ 저도 처음 먹어보았는데, 엄청 맛있더라구요! 특히 막대과자가 정말 맛있어요~ 사진을 다 찍지 못해서 아쉽지만ㅠㅠ직장에서도 다들 맛있다고 난리였어요ㅠㅠ!! 빼빼로데이 아니어도 또 먹고 싶어요….ㅎㅎ', 61, 18, 'GOOD', SYSTIMESTAMP);
