INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '다쿠아즈 종종 포장해서 집가서 먹고 그랬는데 카페 이용은 첨이네요 ㅎ 커피도 맛나고 다큐아즈 역시 쵝오 복숭아요거트케이크 굿굿!! 짱맛 jmk 망고푸딩도 맛나영 ㅎ 전반적으로 만족 ㅎ 음료들도 다들 굿굿 ㅎ', 18, 7, 'GOOD', SYSTIMESTAMP);
