INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '먹고 가려면 사람없는것 같으면 안치웠어도 사장님께 물어보지 말고 자리부터 맡아야 하더라구요 테이블 많지 않은데 사람 많으면 감당이 안되시는듯 합니다 기다려달라는 말만 하시고 앉아도 되냐는 질문하려던거는 차단하셔서 먼저 왔음에도 뒷손님들께 자리도 뺏기고 마냥 서서 10분간 기다렸네요 디저트 맛은 좋았어요 먹고갈거였는데 덕분에 포장해서 먹었네요 열심히 일하시는 것 같은데 손님대응에 익숙치 않으신것 같아요', 42, 5, NULL, SYSTIMESTAMP);
