INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '복숭아 티라미스 너무 맛있게 먹었어요ㅠㅠ 크림도 진짜 부드럽고 복숭아 잼?이랑 궁합 최고예요. 서비스로 내어주시는 쿠키도 진짜 맛있어요. 카페장쌤 디저트는 다 맛있지만 개인적으론 다쿠아즈보다는 케이크 종류가 더 맛있어요. 카페 공간은 소리가 살짝 울려서 막 조용히 시간 보내기는 힘들지만 디저트가 맛있어서 다 용서됩니다!', 22, 5, 'GOOD', SYSTIMESTAMP);
