INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '리뷰 쓸 생각 없었는데 너무 맛있어요... 특히 샤인머스캣 왜 더 안샀지 싶을 정도로 필링이 진짜 잘어울려요... 그런데 다른 후기들 보니까 다른 디저트도 맛있대요... 또 가야겠어요🤣🤣', 42, 0, 'GOOD', SYSTIMESTAMP);
