INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '진짜 사장님 넘 친절하십니다ㅠㅠ 넘 좋아요 그리고 다쿠아즈 진짜 세상 최고 맛있어요,,, 저는 원래 맛있어도 갔던 카페보다 새로운 카페가는 걸 더 좋아하는데 여긴 벌써 4번째? 간 것 같아요 다른 디저트도 다음에 도전해볼거예요! 바닐라빈크림라떼?도 진짜 맛있습니다,,,! 다쿠아즈 다 맛있지만 그 중에는 피스타치오딸기가 진짜 갈 때마다 먹는 저의 원픽이예요,,,', 82, 13, 'GOOD', SYSTIMESTAMP);
