INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '케이크, 다쿠아즈 등 맛있는 디저트가 많아요. 여름 복숭아철에는 복숭아가 들어간 디저트가 진짜 맛있습니다. 홍대입구에서 멀리사는게 너무 아쉬울 정도..! 홍대오면 들리는 곳 중 한 곳이예요', 23, 4, 'GOOD', SYSTIMESTAMP);
