INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구 추천받아 갔는데 선물받은 기분이었어요 디저트도 정말 맛있고 가격도 싸요 여기서만 먹을 수 있는 디저트들이 많아서 눈 돌아가서 엄청 샀어요 또 갈거예여 다쿠아즈 존맛탱임', 472, 70, 'GOOD', SYSTIMESTAMP);
