INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '디저트 최애 맛집입니다..다쿠아즈 여기보다 맛있는곳 아직 못먹어봤구요,, 이외에도 다양한 디저트 천국입니다 ㅠㅠ 배달로도 자주 시켜먹는 단골집이에용', 87, 18, 'GOOD', SYSTIMESTAMP);
