INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '인생다쿠아즈집입니다❤️🧡💛💚💙💜 지금까지 먹어본 다쿠아즈 중에 장쌤 다쿠이즈가 가장 맛있어요~ 폭신폭신하고 필링도 가득해서 기분전환이 최공❤️ 저희 부모님이 빵을 싫어하는데, 카페 장쌤 디저트는 너무 맛있다고 좋아하세요💕 앞으로도 오래오래 영업해주세요❤️‍🔥❤️‍🔥', 58, 13, 'GOOD', SYSTIMESTAMP);
