INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '저 진짜 반지하에 있을때부터 자주 갔던 카페에요. 일년정도 일 때문에 자주 못갔었는데… 역시 케이크도 쿠키도 다쿠아즈도 모두 여전히 맛있어요.', 28, 3, 'GOOD', SYSTIMESTAMP);
