INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '내사랑 카페장쌤 맛있는 디저트와 따스한 분위기 그리고 친절한 사장님이 있는 홍대 디저트 카페입니다 여기는 정말 계속 방문예정이에요 ㅎㅎ', 30, 1, 'GOOD', SYSTIMESTAMP);
