INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오늘 카페장쌤에서 혼자 힐링하고간 사람이에요:) 홍대에 볼일이 있으면 꼭 들려서 쿠키와 디저트를 사가는 편인데 오늘은 시간이 남아서 먹고왔어요 남은거 포장해달라고 말씀드렸더니 세상에나,, 집에와서 알았어요ㅠㅠ 남자 사장님ㅠㅠ 항상 갈때마다 친절하게 맞아주시고 말씀도 엄청 친절하게 해주세요~~ 오늘도 카페장쌤에서 감동받고 갑니다💗', 48, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '이번이 5~6번째 방문인데요 처음엔 다쿠아즈가 맛있다고 해서 찾아간건데 여기는 진심 숨겨진 푸딩 맛집이에요😭😭😭 여기만큼 맛있는 푸딩은 본 적이 없.. 피스타치오 다시 나왔대서 먹어봤는데 왜 여태 안먹었는지 후회되는 맛이구요 사장님도 너무너무 친절하세요!! 다만 아쉬운 점은 바닐라빈 크림 라떼가 테이크아웃이 안된다는 점ㅠㅠ 저처럼 포장만 해가는 사람은 조금 아쉽더라구요 원래 리뷰같은거 잘 안 적는데 여기는 더더 흥했으면 해서 적어봅니다💕💯', 5, 10, 'GOOD', SYSTIMESTAMP);
