INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '디저트가 맛있어요 내부가 좁아보였는데 6팀 정도는 수용가능한것같습니다. 분위기도 좋고 사장님도 친절하세요 직원없이 사장님 혼자 운영하셔서 음료가 나오는데 조금 시간이 걸리는건 감안하셔야할것같아요', 40, 6, 'GOOD', SYSTIMESTAMP);
