INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '제가 대학생 때부터 다니던 곳이에요! 몇 년 전에 사장님께서 홍대 역이랑 가깝게 가게를 옮기신 뒤로, 포장도 자주하고 있어요ㅋㅋㅋㅋ 여기 디저트는 전부 맛있으니 취향인 걸루 꼭 먹어보세요!', 98, 20, 'GOOD', SYSTIMESTAMP);
