INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '카페장쌤 디저트 너무 맛있어요!! 특히 다쿠아즈🩵 너무 꾸덕하지도 않고 가볍고 달기도 적당한 그맛! 다른 디저트도 맛있지만 다쿠아즈는 진짜 최고예요 ㅎㅎ', 49, 5, 'GOOD', SYSTIMESTAMP);
