INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '다쿠아즈 맛집이라고 해서 인천에서부터 달려왔어요! 카페가 작고 아담해서 좌석이 많이 없더라구요ㅜ 어쩔수없이 다쿠아즈만 포장해서 나왔는데 너무 아쉬웠어요 저는 개인적으로 말차 다쿠아즈가 당도도 적당하고 녹차 특유의 쌉싸름한 맛이 있어서 취향에 맞더라구요!', 28, 5, NULL, SYSTIMESTAMP);
