INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '지인의 추천으로 다녀왔어요. 친구도 사다주고 제 것도 사왔는데 다쿠와즈 넘넘 맛있네요. 좋은 재료로 정성껏 만드신것 같아요. 정말 맛있게 먹었습니다. 그리고 장쌤이신것 같은 분도 정말 친절하세요. 다쿠와즈 사며 넘 행복했습니다. 감사합니다.^^', 1, 2, 'GOOD', SYSTIMESTAMP);
