INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '다쿠아즈맛집이라고 들었지만 제가 이곳에서 가장 맘에드는건 딸기우유푸딩이네요! 물론 프레지에도 맛나요! 요새 딸기는 새콤한딸기라서 단케이크랑 시너지가 좋아요!딸기도 듬뿍들어있고요!^♡^', 43, 1, 'GOOD', SYSTIMESTAMP);
