INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '크리스마스 때 케익 주문하고 다쿠아즈도 구매했는데~~! 둘 다 너므너무 맛있네요.. 다쿠아즈는급하게 먹느라 ㅠ 사진이 없는데 케이크 픽업하면서 구매해서 그런지 1개 더 서비스로 넣어주셨습니당 감사합니다!!!!!! 정말 집만 가까우면 자주 먹고 싶을것 같아욯ㅎ 나중에 또 예약할께요!!!!', 30, 10, 'GOOD', SYSTIMESTAMP);
