INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '진짜 다쿠아즈가 제대로예요 밤말차케이크도 너무 너무 맛있고 사장님도 친절하시고 1인 운영 매장이라 조금 웨이팅이 있어도 서비스도 주시고 친절하시고 정말 왜 사람들이 꾸준히 배달로 디저트 시켜먹는지 알거같아요 너무너무 맛있어요', 98, 26, 'GOOD', SYSTIMESTAMP);
