INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '여기는 나만 알고 싶은 곳이랄까. 꺼내다 딸기 위치가 망가졌지만 그것마져도 추억이됐던 딸기가 상큼하고 아주 듬뿍 들어있던 예쁘고 맛있는 딸기 케이크예요🍓', 24, 5, 'GOOD', SYSTIMESTAMP);
