INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '딸기메뉴를 정복할려고 먹어보았습니다! 제 입맛에는 좀..느끼..? 제누아즈가 진짜 얇게 깔려있고 그위로는 무스일까요?크림일까요.. 딸기에 찍어먹으면 괜찬지만 딸기가 사라지고 난후에는 ㅎ..', 20, 3, NULL, SYSTIMESTAMP);
