INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '다른거 먹으러 갔는데 다쿠아즈 맛집이라고 하는 이유를 알고 옴 디저트 전반적으로 다 맛있는데 다쿠아즈는 와!! 진짜 맛있다 소리 나오게 맛있음 추천!!', 101, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '디저트 맛집 !! 디저트 하나하나 손길이 많이 간게 눈에 보일정도로 아기자기 하고 예쁩니다. 밀크티도 적당히 달고 맛있었고 산딸기 에이드는 탄산러버인 저에게 조금 미적지근한 탄산이었어요. ㅜ.ㅜ 건더기가 새콤달콤하니 그건 좋았습니다 추가로 먹은 푸딩도 맛있었어요', 42, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '여기 리뷰 남기려고 네이버 리뷰 시작했네요..! 집에서 약 한시간 반 거리인데 다쿠아즈 먹고 싶을 때마다 찾아가는 맛집입니다. 카페장쌤에서 다쿠아즈 먹고 나니 다른 곳에서는 못 먹겠어요ㅠㅠ... 밀가루가 들어있지 않아서 그런지 겉에 꼬끄?는 구름처럼 사르르 녹고 필링은 대체로 쫀득합니다. 오늘로 네 번째 방문인데 이제야 리뷰쓰는 게 죄송할 정도네요.. 정말 홍대 가면 꼭 방문해야 하는 곳,, 홍대 갈 일 없어도 다쿠아즈 먹으러 가야하는 곳,, 제가 갔을 땐 모두 남자 사장님이 계셨는데 남자 사장님 정말 친절하세요!!! 선물용도 아닌데 예쁘게 포장해주셔서 감사합니다! 조만간 보냉가방 들고 또 갈래요ㅠㅠ', 44, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '맛있어 보이는 디저트가 너무 많아 한참 고민했습니다. 와.. 너무 맛있어서 빨리 다른 것도 먹어 보고 싶어요ㅠㅠ 바닐라무스는 첫 맛은 아주 부드러운데 밑에 바삭한 부분까지 먹으면 또 색다른 맛이 나요.', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '디저트 이것저것 포장해왔는데 남자사장님 정말 친절하시고 디저트도 짱맛있어요~! 다맛있어보여서 고르느라 힘들엇어용 !! 감사합니다', 9, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '항상 만족스러운 케이크와 구움과자를 먹을 수 있는 곳. 코로나 이후 직접방문은 오랜만이라 먹을 수 있는건 부지런히 먹고왔다. 배불러서 오늘은 다쿠아즈를 섬렵하지 못한게 좀 아쉽네 ㅜㅜ', 11, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '다쿠아즈 맛집! 최소 다섯번째 방문이에요! 기념일에 선물하기에도 너무 좋고 그냥 먹어도 너무 좋아요. 서울에서 이곳만큼 다쿠아즈 맛있는곳 없어요ㅠㅠ 저번에는 아르바이트생 분이 너무 냉랭하셔서 기분이 조금 그랬는데 오늘은 사장님이셔서 너무 반가웠어요ㅎㅎ 언제나 친절하신 사장님 덕분에 또또 기분이 좋아졌네요ㅎㅎ', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '더블바닐라파운드 4,500원: 달달하면서 예상대로 정말 맛있어 재구매의사 있어요. 강력추천! 우유푸딩 4,000원: 샤인머스켓이 예쁘게 정돈된 모습이 아니라 아쉬웠지만, 이동하면서 흩어졌을 수도 있고 맛이 좋아 괜찮았어요. 첫번째 수저에서 조금 돈이 아깝다고 느꼈는데 먹을 수록 푸딩 자체가 맛있던 제품이에요.', 42, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '밀크티 케이쿠 진짜 인생 케이쿠..... 다쿠아즈는 말해 뭐하나요.... 다섯시 넘어서 가니까 품절된 게 많아 아쉬웠어요ㅠㅠ 그러니 꼭 일찍 가세용....😋', 104, 25, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '예약 전화 할때 기본 매너가 없어서 기분이 많이 상해 픽업은 지인 보냈는데 지인마저 그분에게 말씀을 왜 그렇게 하시냐고 하고 나왔다네요. 케이크 예약 주문과 픽업 할 때 기본적인 대화 몇 마디 나눴을 뿐인데요. 남자 직원분 평소 말투나 단어선택이 그러신 것 같은데 평소 성향은 성향인거고 생판 모르는 남남 사이에 최소한 기본 예의는 지키시길. 첫 구매였는데 다시는 구매하지 않을거에요.', 20, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '비싸도 맛있어서가요! 홀케이크 레터링 부탁드렸는데 알겠다하시고 찾으러 갈때도 레터링 맞으시죠? 하셔놓곤 열어보니 그냥 쌩케이크.. 레터링 흔적도 없어서 어이없고 황당했지만 그냥 먹었네요..', 22, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '이것은 첫번째 간 날 리뷰 ~! 확실히 두번째 갔을 때보다 일찍 가서 품절된 다쿠아즈는 두세개? 정도 였고 마카롱이나 다쿠아즈는 새콤한 맛 좋아하는데 이 날은 카시스치즈가 남아있어 맛 볼 수 있어 좋았습니다! 지금까지 먹은 다쿠아즈 중에 제일 맛있었어요 완전 퐁신퐁신', 31, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '다쿠아즈 맛있어서 이틀 연속 간 곳입니다 .. 이번에도 선물 드리려고 10개 샀는데 선물 받으시는 분도 포장 보고 좋아하실 것 같아요 ! 사장님께서 서비스도 주시고 ㅠㅠ 맛도 좋고 또 안갈 수가 없는 곳입니다 곧 또 가겠습니다 사장님 ~!', 44, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '다쿠아즈 (피스타치오베리, 카시스치즈) 케이크 맛있어요. 저번에 전화로 1호케이크 예약 가능한지 물었더니 알바생인지 남자분 1호 안되고 바쁘다며 짜증내며 끊으셔서 좋은평은 어려움..', 3, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '저번에 와서 먹어보고 맛잇어서 또 왓어요 수박에 오미자 먹었었는데 오늘은 수박에 딸기우유 먹어보려구여 조만간 복숭아 먹으러 와야겟어영 다른데도 먹어봤는데 냉동이라 ㅜㅜ 달화채 다시 찾게되네요 사장님 넘 친절하세요🫶🏻', 129, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '더운 여름 먹기 딱 좋은 시원한 화채~  과일도 다양하고 딸기우유 베이스 오미자 베이스 선택해 먹을수있어 넘 좋네요 요거트 아이스크림도 판매하고 있어 부담스럽지 않게 친구들과 먹을 수있네요 매장도 넘 이쁘고 메뉴도 다 맛있어서 넘 좋아요 인생 사진도 건지고 맛난 화채 요거트도 먹을수 있으니 홍대 데이트 나들이에 무조건 들러보심 좋겠네요~^^', 82, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대근처 엄청 넓은 카페가 생겼는데 자리도 많고 🍉 화채랑 그릭요거트, 요거트 아이스크림, 과일, 커피까지 다양하게 즐길 수 있어서 좋네요! 👍 수박화채 먹었는데 딸기우유 베이스 너무 맛있어요❣️ 수박 키위 블루베리 키위 등 모두 생과일이라 신선하고 달콤해요😋', 99, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '반쯤 먹고 찍은 사진입니다. 양 진짜 많아요. 귀여운 개인 그릇주셔서 덜어서 먹어요. 달화채+딸기우유베이스 추천합니다 ㅠ 과일종류 다양해서 진짜 맛있어요!! 매장이 항상 청결하고  친절하신 것 같아요♡', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), 'N번째 방문! 달화채 앓이 하다 재방문 했어용 저희동네엔 왜 없는걸까요 멀리서 왔어요 달세권에 살고싶어요 🥲 엄청 더웠는데 시원하고 달달하고 신선한 과일들로 무더위 이겨내고 갑니당🫶🏻  역시 달화채🩵🩷🩵🩷 사장님도 왕친절하세요! 잘먹었습니다 또 올게요🩵', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '빙수-화채-빙수  도장깨기중 ㅎㅎㅎ 과일이 신선하고 푸짐해요! 가성비 좋고  매장분위기도 좋아서 이동네 올때마다 들르고 있어요!', 17, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '더운 여름 달화채 홍대점 다녀왔어요!! 집에서 해먹으면 번거로울 수 있는 화채를 더 다양한 과일과 들화채만의 시그니처 베이스 딸기우유와 함께 시원하고 맛있게 먹을 수 있어서 더위를 날릴 수 있었어요!! 커피와 그릭요거트 등등 다양한 메뉴도 판매하고 있고 대형카페라 공간도 넓직해서 좋아요!! 무엇보다 새벽까지 운영해서 늦은시간에도 갈 수 있다는게 정말 좋은 점이더라고요!! 달화채 홍대점 추천합니다:)', 32, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '진짜 줜나 마싯슴!!!! 여기 맛있는데 멀어서 파주 점 다녀 왓는데ㅠㅠ 진짜 파주점도 여기도 사장님 친절하시고 마싯서여유오오ㅠㅠㅠㅠ ❤️❤️❤️ 오늘도 넘 맛나서 전도 하러옴…❤️❤️ ‼️‼️샤장님 제발 저희 동네도 달세권 해주세요ㅠㅠ‼️‼️', 49, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '새로 오픈한 곳인가봐요^^ 키위+그릭요거트 5,500원인데 양도꽤되고 꾸덕꾸덕 맛있네요🥝👍🏻 무엇보다 키위한개가 통채로 들어가는데 그래놀라와 조합도 좋고 맛있어요:) 매장도 깔끔, 넓고 시간보내기 좋았어요😊', 102, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '저녁에 카페 가면 커피 마시기도 뭐 하고 먹을 게 없었는데 생과일 화채랑 Greek 요거트 아이스크림 와방 먹을 수 있어서 넘 좋음 시간도 엄청 늦게 갔는데도 늦게까지 해서 홍대에서 한잔 하고 디저트 겸 해장 겸 먹으니까 딱 임 과일이 완전 싱싱하고 달고 그린 요거트 요새 한 소금만해도 막 6000 원씩 겁나 비싼데 여긴 Greek 요거트도 많이 주고 겁나 비싼 골드 키위랑 파인애플 생과일도 막 들어 있음 가성비 미쳤음홍대에 이런 보석 같은 곳이 생기다니 이제 홍대에서 술 마실 때 필수코스 매장도 엄청 넓어서 단체로 오기도 좋음 몸에 안 좋은 아이스크림 이런 거 아니고 생과일이랑 그린 요거트여서 저속노화 트렌드에 딱 맞음 딱 좋음 복숭아도 통조림 같은 거 아니고 생과일 오미자베이스 최고!', 127, 26, 'GOOD', SYSTIMESTAMP);
