INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '과일이 달고 양도 푸짐해서 넘넘 맛있어용( ᐢ• 0 •ᐢ ) 딸기우유 베이스라니 색다른데 달달하니 잘 어울리고요ㅎㅎ 음료도 진하니 맛있네용!! 오랜만에 맛있는 화채 먹어서 좋았습니다ദ്ദി◍•ᴗ•◍)', 7, 3, 'GOOD', SYSTIMESTAMP);
