INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대에 아이랑 산리오 구경 및 미니소 구경 왔습니다 지나가는 길에 홍익대도 구경하고 과일 먹고 싶다고 해서 검색해서 왔는데 친철하시고 맛 있있구여 매장도 넗습니다 ~~ 아이가 다음에 또 오자고 날리네요 ^^', 5, 1, 'GOOD', SYSTIMESTAMP);
