INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '새벽 늦게 갔는데 여자사장님이 너무너무 친절하셨어요ㅠㅠ♡ 늦은시간인데도 너무 상냥하게 대해주시고 메뉴설명도 잘해주셔서 너무 감동이었어요♡♡ 얼굴도 예쁘시고 사람이 너무 예쁘신 분인 것 같아요! 매장 대박나시고 항상 좋은일만 가득하시길 바랍니다🥰❤️', 119, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '달화채!! 길 걷다가 좀 쉬려구 카페에 갔는데 새벽까지 하더라구요!! 바나나 그릭요거트 먹었는데 양도 엄청 넉넉하구 맛있았어요 꿀이랑 조합 굿!! 그리구 직원분 넘 친절하세요~!!👍', 23, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '강추드리고싶은 곳...!! 사장님이 친절하시고 영업시간도 길고 매장 내부도 깔끔하고 넓고 귀여운 분홍컬러에요! 메뉴도 정말 다양하고 무엇보다 과일이 듬뿍 아낌없이 들어가있어요!! 화채도 맛있고 초품바 요거트 아이스도 넘넘 맛있어요! 모든 게 다 좋았어요🥰', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '커피랑 요거트아이스크림 주문했는데 둘 다 너무 맛있어요~! 초코쉘이랑 키위, 오렌지, 후르트링도 추가했는데 양도 많고 넘 맛있었습니다. 매장, 테이블도 넘 깨끗해서 좋아요 또 방문할게요!!', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친구따라 왔다가 제가 완전반했어요 홍대신상카페 달화채 여기 완전 이쁘구요 딸기달빙수 너무맛있어용 생딸기가 가득 빙수에 그릭요거트아이스크림까지 달달한 디저트에 기분업♡ 담엔 화채도 먹으러와야겠어요 매장도 넓고 직원분들도 완전 친절하세요 과일빙수 러버분들 완전반할듯요 단골각입니다', 29, 1, 'GOOD', SYSTIMESTAMP);
