INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아기자기한 인테리어가 기분이 산뜻해짐 과일빙수먹엇는데 둘이 먹기에 양이 넉넉하고 과일도 신선하고 망고도 너무 맛잇어요~ 경기도에서 빙수먹으러왓어요 주차가능 ㅎㅎ 잘 먹고 갑니당', 3, 5, 'GOOD', SYSTIMESTAMP);
