INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '화채 먹고싶어서 찾아보고 왔는데 너무 맛집을 찾았어요!!!ㅠㅠㅠㅠ 화채 양 짱 많고 망고 빙수도 너무 맛있어요!! 완전 더위 날려버리는 맛..또 올게요💕', 53, 15, 'GOOD', SYSTIMESTAMP);
