INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구랑 빙수먹으로 또 왔어요! 역시 홍대 빙수 맛집! 다음엔 화채 먹으러 와야겠어요 매장도 넓고 쾌적해서 사람들이 꽤 있어도 편하게 있었어요! 화장실도 깨끗하구 직원분들 너무 이쁘시고 친절합니당~!!', 76, 18, 'GOOD', SYSTIMESTAMP);
