INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '아이스크림 먹고 싶어서 기본요아+그래놀라 조합으로 먹다가 과일이 너무 먹고 싶어서 하나 더 시켜먹었어요ㅋㅋ과일 싱싱하고 정말 맛있어요>< 다음에는 친구랑 같이 와서 화채도 시켜 먹고 싶어요!! 인테리어 예쁘고 넓고 쾌적해서 편하게 먹고 가기 좋습니🍓😋', 49, 3, 'GOOD', SYSTIMESTAMP);
