INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '날이 훅 풀려서 홍대 가다가 딸기빙수 먹고 가요. 빙수도 생각보다 크고, 딸기도 많이 올라가서 좋고, 딸기청 들어간 시럽? 같은 것도 나와요. 사진엔 없지만 오픈이벤트로 홍시샤벳도 주셨어요ㅎㅎ 매장 엄청 넓고 조용하고 직원분들도 엄청 친절하십니다!', 43, 9, NULL, SYSTIMESTAMP);
