INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '늦게까지 하는 곳 찾아 시험기간에 방문했는데 공부하기 좋았어요. 종종 공부하러 오려구요 사장님 친절하시고 예쁘세요 수박주스 갈증해소 되는 맛 인위적인 단맛도 안나고 너무 맛있네요', 18, 8, 'GOOD', SYSTIMESTAMP);
