INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '제가 요아정 엄~~~~~청 좋아하는데 🤤 여기만큼 구성차게 주신 곳은 없었습니다.. 그리고 자몽도 너무 좋아해서 추가해서 먹었는데 너무 맛있어요.🤤🤤 자몽도 귤락도 하나하나 다 제거해서 주십니다.. 엄청난 정성… 마치 외갓집 할머니 댁에 온 기분이었습니다 다들 오지마세요 저만 갈래요😜😚😚', 69, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '요거트아이스크림에 벌집 큐브치즈조합은 맛이없을수없는 기본템👍👍👍👍👍 건강하게 다이어트?중인데ㅋㅋㅋㅋ 그나마 양심찾아서 하하하 달화채 홍대점 맛있고 짱친절합니다😀😀', 26, 8, 'GOOD', SYSTIMESTAMP);
