INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '해도 뜨겁고 시원한 빙수가 땡겨서 아빠가 찾은 카페로 따라 왔습니다 저희가 시킨 건 오색 달빙수!! 달달하구 맛있어여 다음번에 화채도 먹어보려구여 사장님도 친절하시구 잘 먹다 갑니다ㅎㅎ', 31, 1, NULL, SYSTIMESTAMP);
