INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '팝핑보바 첨 먹어봣는데 식감이 신기하고 맛있었어요 화채를 제 돈 주고 사먹은건 첨인거 같은데 넘 맛잇어요 담엔 딸기우유맛 도전해봐야겟어용 조만간 또 오겟어요 해삐', 29, 1, 'GOOD', SYSTIMESTAMP);
