INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '주메뉴는 화채 빙수이지만 겨울 메뉴도 있어요(옥수수 호빵 고구마). 초코쉘 요거트 아이스크림도 시킴. 오픈 기념으로 홍시슬러시도 주시네요. 위치는 밴드공연장 스페이스한강 건너편입니다.', 42, 2, 'GOOD', SYSTIMESTAMP);
