INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '일단 카페 엄청 넓고 깨끗합니다! 음료수도 맛있어요ㅎㅎ 덥고 추운 날 쉬어가기 딱 좋아요 화채랑 빙수 아이스크림도 있습니다 여름에 다들 한 번씩 와보세요!', 7, 7, 'GOOD', SYSTIMESTAMP);
