INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '전에 먹었던게 생각나서 홍대 오랜만에 왔는데 또또 방문입니당!! 빙수가 우유 얼음인데 전보다 더 맛있어진거 같아요 얼음만 퍼먹어도 될정도로 넘 맛있어요😭 과일도 넘 신선하고 달고 너무 맛있어서 따로 주신 소스 하나도 안붓고 다먹었습니당🍓 그리고 위에 아이스크림 바닐라 맛인거같은데 뭔가 마시멜로우 맛도 나고 완전 고급 아이스크림 먹는 느낌으로 너무 맛있어서 아이스크림만 따로 먹고싶은 맛이었어요 다음에 홍대오면 또또또 재방문 의사 있습니당!', 1, 5, 'GOOD', SYSTIMESTAMP);
