INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '걷다가 너무 힘들어서 들렸는데 너무 시원하고 맛있었어요!!  과일들도 신선해서 맛있어요 😻😻 그리고 넘 친절하세요! 화채집은 잘 없는데 시원하게 맛있게 먹구 갑니다!!', 11, 6, 'GOOD', SYSTIMESTAMP);
