INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '빙수가 땡겨서 급하게 알아봐서 왔어용 늦게까지 하는게 너무 좋고 과일도 싱싱하고 너무 맛있어요 다음에 재방문 의사 있습니당!!다음엔 다른 빙수도 먹으러 올게용', 24, 0, 'GOOD', SYSTIMESTAMP);
