INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '라떼 진하고.. 고소해요.. 과일 싱싱하고.. 요거트도 맛있습니다. 오늘 하루 종일 피곤했는데.. 달달 충전으로 혈액순환되네요~^3^/', 106, 19, 'GOOD', SYSTIMESTAMP);
