INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '매장도 너무 청결하고 시원하고 최고입니다. 여름에 밖이 너무 더운데 시원한 화채랑 빙수 먹고 쉬었다가기 너무 좋아요♡ 자주 방문하겠습니다🥰', 9, 10, 'GOOD', SYSTIMESTAMP);
