INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '여기는 정말 모든 지역에 생겼으면 좋겠어요 잠실에서 이게 먹고싶어서 지하철을 타고 올 정도로 진짜 맛있고 딸기우유 베이스나 과일이나 전체적으로 정말 맛있고 홍대 최고의 카페입니다 절대 사라지지 말아주세요 제발요ㅠ', 12, 5, 'GOOD', SYSTIMESTAMP);
