INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '망고빙수 퓨레 너무너무 맛있어요 !!🥭 초코쉘은 완전 요아* 그 자체 !! 가족이랑 방문해서 즐거운 시간 보냈습니다 ~~ 사장님 번창하세요 ~ (오픈 이벤트로 받은 홍시샤벳도 달콤하고 맛있더라고요ㅠㅠ👍🏻)', 10, 2, 'GOOD', SYSTIMESTAMP);
