INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '커피 너무 맛있구, 매장도 넓어서 오래 머물며 비지니스 회의했네요. 새벽 3시까지 운영하신다고 하니 오랜시간 작업하시거나 모임장소로 완전 추천합니다.', 12, 1, 'GOOD', SYSTIMESTAMP);
