INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '과일이 듬뿍 더운날씨에 시원한 화채먹으니 시원하니 최고네요 재료가 가득 들어서 배부른 기분! 달달한 딸기우유 베이스라 누구나 좋아할맛', 127, 26, 'GOOD', SYSTIMESTAMP);
