INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '집근처에 과일집이라니… 심지어 화채가 팔다니 화채 진짜 좋아하는데 정말 너무 행복해요 음료도 팔고 요거트아이스크림까지 팔아요ㅠ 매장이 크고 깨끗해서 여러명이서 와도 좋을거같아요! 자주 이용할 것 같숩니다🫶🏻', 334, 93, 'GOOD', SYSTIMESTAMP);
