INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '파주 야당에서 대박맛집이 홍대에도 오픈 하셨네요. 화채의 신세계를 홍대에도 널리 펼쳐 주세요..ㅋ 개그맨 양세형씨 건물 이라네요..ㅎㅎ 오픈 축하 드리고 자주 먹으러 올게요~', 44, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '수박화채에 오미자 추천드립니다😍 가게도 너무 예쁘구 깔꼼해서 조만간 또 갈거같네요 그땐 딸기우유 베이스로 먹어보께여 히히 사장님 번창하세영💕', 10, 4, 'GOOD', SYSTIMESTAMP);
