INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '딸기빙수먹으러 왔다가 화채파는거 보고 노선틀었습니다 ㅋㅋㅋ 이런 스타일 화채는 처음인데 처음에는 빙수먹는 느낌들다가 나중에는 화채먹는 느낌 1석2조 개이득', 414, 53, 'GOOD', SYSTIMESTAMP);
