INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대 데이트 하다가 여자친구가 화채 먹구 싶다 해서 포장해왔어요 사장님 너무 친절하시구 오픈 이벤트로 홍시샤벳두 주셨어요 여자친구가 과일 좋아해서 조만간 또 갈 예정입니다.👍', 23, 4, 'GOOD', SYSTIMESTAMP);
