INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '2층 3층 모두 분위기가 좋아요~!! 좌석마다 매력이 있어서 좋았습니당 ㅠㅜ 요런 느낌 다른 지역에도 많으면 좋겠더라구요 데이트하는 분들도 많구 작업하러 오시는 분도 있고 무튼 최고👍🏻', 8, 2, 'GOOD', SYSTIMESTAMP);
