INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '연남끝자락이긴한데 그만큼 올만하네요! 2층3층으로 나뉘어져 있고 인테리어도 너무 좋고, 무엇보다도 이 단호박치즈케이크 꼭 드셔보세요…단호박 진해서 너무 맛있네요!!', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '가게가 넓고 쾌적해서 좋았어요! 근데 그게 전부에요.. 여자 직원분이 매우 불친절해서 다시 오고 싶진 않네요 ㅎㅎ 아래 후기 보니 비슷하게 느끼신 분들이 있는 것 같은데 개선이 필요해보여요. 반면 사장님은 엄청 친절하게 응대해주시더라고요. 그치만 구매할 땐 여자직원분이 계산기 앞에 있던 데 마주치기 싫어서 안갈듯요  ㅠㅠ', 128, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '요 몇주동안 서너번 정도 방문한 것 같아요. 올겨울 내내 제 최애 연남동 카페였습니다! 2층, 3층 분리되어 있는 것도 너무 좋고 인테리어도 아늑해요. 단호박 케이크도 맛있고 아메리카노도 쓰지 않고 적당한 산미와 향이 너무 제취향이어서 반했어요. 가게가 아담하고 예뻐서 그런지 사진 찍으러 오는 분도 많으신 것 같아요. 저랑 친구가 앉은 자리 옆에서, 자리 없고 음료도 없는 분들이 진짜 거의 한시간동안 포즈 취하면서 서로 사진찍어대서 좀 짜증나고 신경쓰였던 일도 있긴 했지만... 그만큼 이 카페가 좋은 카페라는 방증이겠죠. 재방문의사 완전 있음.', 48, 9, 'GOOD', SYSTIMESTAMP);
