INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '단호박바치케!! 단호박 향이 세서 치즈맛은 좀 약한데 맛있었어요! 커피도 맛있구 화장실도 카페 내에 있어서 너무 좋았어요 화장실에 비누도 있어요ദ്ദി ˉ͈̀꒳ˉ͈́ )✧', 2, 7, 'GOOD', SYSTIMESTAMP);
