INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '생각나면 오는 곳이고 커피맛잇고 책 읽기 좋아서 오는데 여자 직원 좀 말튜 ? 친절하지않네용 ㅋㅋㅋㅋㅋ 본인이 계산 이상하게 해놓고 ㅋㅌㅌㅌ 저희한태 여기 보고  금액 확인 하시면 돼용 이러시고 ㅋㅋㅌㅌ 어쨋등 ㅋㅋㅋ 저번에도 약간 불친절 하시더니 맨날 똑같은 말 하셔서 이해는 한다만 ㅋㅋㅋ 이해하고 자주 오고 잇어요 ㅎㅎ', 36, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '분위기 따뜻하고 조용히 얘기할 수 있어서 좋았어요! 매장은 2, 3층에 있고, 리뷰에 많이 있듯 단호박치즈케이크가 부드럽고 넘넘 맛있어요🤤', 84, 18, 'GOOD', SYSTIMESTAMP);
