INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아메리카노 별로 안 좋아하는데도 뭔가 맛있어서 다 마셨어요! 향이 정말 좋았어요. 단호박 바스크 치즈 케이크도 넘넘 맛있습니다👍🏻 부드럽고 고소해요. 무엇보다 카페 분위기가 정~~~말 좋더라고요. 인테리어도 예쁘고 뭔가 여기서 작업을 하면 좋은 영감을 가득 얻어갈 것 같은 느낌? ㅎㅎ', 13, 2, 'GOOD', SYSTIMESTAMP);
