INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '콘셉트가 있는 카페. 1층만 있는데 예쁨. 화장실 깨끗함!!! 종이가 많이 사용되는 건 맘 아프지만 일단 예쁨 사장님 친절하심🌹 커피 맛있음. 산미 없고 취향임🥺🫶🏻', 37, 3, 'GOOD', SYSTIMESTAMP);
