INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '생각보다 내부가 좁네요!! 운좋게 한 테이블 남아있어서 웨이팅 없이 들어갔어요😍 쾌적하고 대화하기도 편안한 곳이었습니다. 다만 화장실은 공용이니 참고하세요', 30, 6, NULL, SYSTIMESTAMP);
