INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '예전부터 꼭 가보고 싶었던 카페였는데 기대 이상으로 좋았어요!! 카페 분위기도 좋고… 케이크랑 커피도 대만족입니다. 고소한 아메리카노랑 단호박 바스크 치즈 케이크 완전 맛있어요☺️ 공휴일이라 자리 없을까봐 걱정했는데 자리가 있어서 정말 다행이었어요! 다음에도 또 갈 것 같습니다.', 75, 17, 'GOOD', SYSTIMESTAMP);
