INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '조용한곳을 찾아서 갔는데 좋았어요. 가정집을 개조했는데 2개층이라 자리도 넉넉하고 분위기가 좋아요. 연남동 끝에 있어 주변도 조용하고 커피도 맛있어요.', 41, 3, 'GOOD', SYSTIMESTAMP);
