INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '1부터 10까지 전부 마음에 들었던 브라운하우스 .. ♥ 환친자들이라 환연3 X 사전미팅 장소가 연남동이라는 거 알고 냅다 달려왔어요 ㅎㅋㅎㅋㅎ 곳곳의 인테리어들이 전부 취향이었고 소품 하나하나 신경쓰신 게 잘 느껴졌어요. 커피를 잘 못먹는데 브라운커피 연하게 먹으니 딱 좋았어요. 맛있어서 5분만에 후루룩.. 또 올래요 사진도 왕 잘 나와요🤸‍♂️', 379, 71, 'GOOD', SYSTIMESTAMP);
