INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), 'Super liked the interior and all the details they have inside! 디카페인 아인슈페너 (decaffeinated einspanner, ice only) tasted great, the cream was so smooth; 클래식 버터바 (classic butter bar) was good, but really so sweet! The atmosphere is super cozy! I liked a lot also the lamps around! A super cool cafe, good for work and study! 🫶🏻', 33, 7, 'GOOD', SYSTIMESTAMP);
