INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '평일 저녁 방문했습니다. 매장 인테리어는 좋았으나, 직원분이 주문 받으실 때 손님을 보지도 않고 귀찮은 듯 응대하는 점이 다소 불편했습니다. 과한 친절을 바라는 것은 아니지만 그런 모습이 몇 번 반복되어 다음 방문이 꺼려지네요..!', 68, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '단호박 바스크 치케랑 아아메,, 그리고 근사한 트리와 함께 할 수 있어서 너무 행복했습니다! 2-3층이라 근방에서 그나마 웨이팅이 적은 것 같아 좋았어요 잘 먹고 쉬다 갑니다~!', 1, 2, 'GOOD', SYSTIMESTAMP);
