INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '분위기가 진짜 좋아요. 매장도 2,3층 이렇게 있어서 넓고 편해요. 패션후르츠 에이드는 너무 달지 않고 적당하게 상큼달콤해서 좋았어요. 단호박치즈케이크가 진짜 맛있습니다.(최고) 단호박 맛이 엄청 진해서 놀랐어요. 단호박 좋아하시면 무조건 드셔보세요.', 7, 6, 'GOOD', SYSTIMESTAMP);
