INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '층별로 구조랑 인테리어가 달라서 맘에들었어요!! 테이블이 많아서 노트북작업, 대화하기도 좋았습니다! 그리고 버터바 좋아해서 버터바 시켰는데 특별한 맛은 아니였어용,,,🙃', 86, 12, NULL, SYSTIMESTAMP);
