INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '디카페인 콜드브루 먹고 싶어서 방문했어요 끝맛에서 느껴지는 다크초콜릿의 씁슬한 단맛이 좋아요 라즈베리 머시기 케이크도 먹었는데 이건 무슨 맛인지 잘 모르겠어요 차분한 분위기에서 도란도란 얘기하기 참 좋아요', 23, 7, NULL, SYSTIMESTAMP);
