INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '시그니처 라떼도 맛있고 산미있는 커피 좋아해서 레이지모닝 원두 너무너무 맛있었어요! 연남동 가면 또가고싶은 카페랍니다!:) 가게 분위기도 너무 시끄럽지 않아 대화하기 좋았어요', 11, 0, 'GOOD', SYSTIMESTAMP);
