INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친구가 데려가준 커피 맛집✨ 나만 몰랐던 곳이라, 일요일 오후에 사람이 엄청 많더라구요. 하마터면 웨이팅할뻔💦 그만큼 분위기가 좋고, 데이트하기도 좋은 카페에요! 조용한 평일에 오면 더 힐링할 수 있을 것 같아요 ㅎㅎ', 50, 3, NULL, SYSTIMESTAMP);
