INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '사진보다 실제로 보는게 더 예쁜 공간이에요! 연남에서 좀 떨어진 곳에 있어서 조용했고 책 읽거나 노트북 작업하러와도 너무 좋을거 같아요 ㅎㅎ', 11, 7, 'GOOD', SYSTIMESTAMP);
