INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어의 느낌에 9시쯤와서 그런가 바처럼 갬성이 짙었다..🔥 시간에따라 다른 갬성인거 같다 브라운커피 - 쌉쌀하면서 달달하니 괜츈하였다 사장님두 정말 친절하시고.. 나긋한 목소리도 메뉴인가요..ㅎㅎ👍🏾', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '편해요. 주말이라 사람 많아서 이층은 처음 이용했는데 이층도 편해요 좋아하는 가구 구경하는 재미도 있고 ~ 직원분도 친절하시고 ~ 커피도 맛있고 ~ 아배부르다 연남오면 브하 ~', 3, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '2층 3층 있는데 2층은 좀 아늑한 분위기 였고 3층은 채광 좋고 대화하기 좋더라구요!!인테리어랑 분위기가 좋았고 사진이 진짜 잘 나와요!!햇살맛집이였어여ㅎㅎ🫶🏻', 39, 3, 'GOOD', SYSTIMESTAMP);
