INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '따뜻한 카페가 없나 찾다가 온 곳이예요 채광이 좋아서 공기가 훈훈하고 햇살이 따스하게 감싸는 공간입니다🌿✨ 커피를 안좋아하는데 시그니쳐메뉴인 브라운커피가 너무너무 맛있네요! 🥰 단호박치즈케익도 정말 매력적인 맛이예요🌷 2~3층을 전부 사용하는데 각층마다 화장실이 있고 화장실에 비데가 있어 엉덩이가 따뜻해요! 또 올게요🍀🙂', 12, 10, 'GOOD', SYSTIMESTAMP);
