INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '공간이 넓고 좌석이 다양해요(?) 인테리어가 감성적이고 멋집니다. 같이 온 친구들이 의자 훔쳐가고싶을정도로 탐난대요ㅋㅋㅋㅋㅋ 브라운커피 크림 쫀득달달(?)하고 맛있어요. 좌석이 좋아서 그런지 오래 머무르고싶네요. 창문이 군데군데 있어서 날씨 좋은날 사진도 잘 나올 것 같아요.👍🏻', 53, 17, 'GOOD', SYSTIMESTAMP);
