INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '치즈케이크(7500~)지나가다 구매 맛은 적당한 단맛과 꾸덕한 치즈맛이 조화로운 맛! 커피는 못 마셨지만 향이 좋아 재방문 예정. 사장님 친절하십니다. 특히 인테리어가 모던한데 공간이 주는 매력이 있는곳으로 층별로 다른 분위기로 하셨다고 함. 카페는 2층부터이니 참고하세요~', 30, 4, 'GOOD', SYSTIMESTAMP);
