INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '인테리어 너무 멋져요 ..! 인테리어랑 잘 어울리게 인센스를 피우신건지 ? 암튼 향도 너무 취저구여 귀여운 굿즈들도 있고 머그도 너무 이쁘규 … 치즈케이크도 맛있어요 ㅠㅠ 담엔 꼭 단호박 치즈케이크 먹어볼래용', 15, 0, 'GOOD', SYSTIMESTAMP);
