INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '깔끔하고 세련된 인테리어가 취향저격! 디저트도 딱 내 스타일. 부드럽고 달콤. 차분한 직원 분의 응대도 너무 맘에 듭니다! 또 와서 다른 메뉴 먹어봐야겠어요.', 43, 8, 'GOOD', SYSTIMESTAMP);
