INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '분위기가 좋아서 자주 생각나는 곳. 2층과 3층으로 나누어진 공간이 매력있어요. 커피맛은 무난한 편이지만 단호박치즈케이크가 맛있었습니다.', 31, 0, NULL, SYSTIMESTAMP);
