INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '힙하면서도 아늑한 느낌이라 좋았어요 :) 시그니처 브라운커피도 맛있었습니다 근데 사장님이 옆테이블분들한테 카메라 셔터소리 난다고 하시더라구요.. 독서실도 아니고 커피마시면서 공간을 즐기러 온 카페인데 저까지 기분이 좀 그랬네요 ;', 29, 2, NULL, SYSTIMESTAMP);
