INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '복주머니 마카롱 너무 귀여워요ㅠㅠ👛 애플망고랑 딸기 들어있는 롤 생겼길래 먹었는데 진짜 존맛이에요🤍 벌써 3번째 갔는데 완전 만족..🫶 딸기랑 체리 들어있고 초코크림 조합인 거 생겼던데 담에 그거 먹으러 재방문 해야겠어욤 항상 친절하시구 1시간 정도 기다렸지만 대만족', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '저번에 먹어보고 너어무 맛있어서 동생 생일 때 사주려고 다녀왔어요🩷 오픈 10분전에 갔는데 앞에 10명 정도 줄 서있었구 주문 후 10~20분 기다렸다가 받아왔어용 맛별로 다 먹어보고 싶어서 사왔는데 진짜 다 맛있어서 취향에 맞게 드시면 될 것 같아용 전 크림치즈가 맛있었습니다👍 직원분들 다 넘 친절하셔서 더 좋아요🤍', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '후르츠롤크레이프 + 아아 + 자몽블랙티 •v• ㅤㅤ 후르츠롤크레이프 진짜 맛있었어요!!! 과일도 다양하고 엄청 많아서 순삭하고 피스타치오딸기롤까지 먹었습니당,,,, 저는 후르츠롤크레이프가 더 맛있었어욥! 매장이 너무 작아서 웨이팅이 30분정도 했던 것 같아요!', 97, 25, 'GOOD', SYSTIMESTAMP);
