INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '웨이팅 한 20분 정도 해서 들어갔어요 매장 안은 조금 좁지만 계속 해서 손님들이 들어오더라구요 분위기는 조금 어수선했지만 케이크 맛은 맛있었어요! 과일도 신선하고 크림도 맛있고!', 13, 8, 'GOOD', SYSTIMESTAMP);
