INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '디저트가 맛있고 매장은 좁은데 대화하기 좋았습니다. 사장님도 친절하시고 처음 방문이었지만 좋은 기억으로 남을 것 같아요. 나중에 또 방문해보고 싶어요.ㅎㅎ', 41, 1, 'GOOD', SYSTIMESTAMP);
