INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '롤크레이프에 과일이 많이 들어 있어서 생각한 것보다 물리지도 느끼하지도 배가 과하게 부르지도 않았어요ㅎㅎ 딸기로 할까 후르츠(제철과일)로 할까 고민했는데 후자로 하길 잘했단 생각이 ㅎㅎ 과일 전부 달달해서 좋았고, 조개롱은 크기가 커서 그런가 잘라 먹기 진짜 힘들더라구요😅 커피는 그으으렇게 맛있는 편은 아닙니다!', 49, 6, NULL, SYSTIMESTAMP);
