INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '화려하다 화려해ㅋㅋ 연남동 처음인데 가격에 여러번 놀래며 다닌다.. 아무튼! 포장했는데 처음에 세워서 넣은 것 같은데? 집에 오니 누워있네..!?....  매장서 먹자.', 52, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '중딩 아이  서울로 디저트사러가는걸 평소에도 좋아해요. 수학여행간김에 디저트를 한가득 사가지고 왔네요.ㅎㅎ 맛있대요.ㅎㅎ 잘먹었습니다.  디저트때문에 서울로 이사가자고 할판이예요.ㅎㅎㅎ', 24, 7, 'GOOD', SYSTIMESTAMP);
