INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '<주문한 메뉴> - 아이스 아메리카노 5,000원 - 아이스 바닐라 카페라떼 5,800원 - 초코딸기케이크 롤크레이프 8,800원 인스타에서 롤크레이프 보고 맛있어 보여서 다녀왔는데, 매장이 생각보다 협소하더라구요 .. 😅 그래도 날씨가 좋아서 테라스에서 먹었어요 🙋🏻‍♀️ 크레이프에 딸기도 달달하고 커피도 무난하게 맛있었어요!', 100, 26, NULL, SYSTIMESTAMP);
