INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '유튜브보고 못참고 찾아간곳인데 ㅎㅎ 진짜 실물도 최고였어요..🙊🔥 제가 선택한 후르츠롤크레이프는 생각보다 맛이 막 특별하진 않았지만 그래도 여러가지 과일을 함께 맛볼 수 있어 좋았고 마카롱은 크림이 조금 느끼한 편이었지만 비주얼만큼은 최고였어요 ㅎㅎ👍 낮에 사러가서 좀 늦게 먹을 수도 있을것같다 하니 보냉신경써주시고 친절하게 응대해주셔서 넘 감사했어요 ㅎㅎ 결국 중간에 못먹고 밤에나 먹었는데 멀쩡해서 맛있게 잘 먹었네요🥰 다른 메뉴도 맛보고싶은곳..👍💗', 67, 12, 'GOOD', SYSTIMESTAMP);
