INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '1.5floor 저번에 처음 먹고 잊을 수 없어서 왕복 2시간 넘게 걸려서 사왔어요 아직 집 가는 중이지만... 맛있게 먹을께요ㅠㅠ', 26, 3, 'GOOD', SYSTIMESTAMP);
