INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '인스타에서 사진보고 킵해둔 곳이에요! 빨리 소진되는 것 같아서 걱정했는데 요새는 낭낭하게 만들어 두시는 것 같아요! 주중 저녁 8시쯤 갔지만 종류별로 있었어요! 포장 전문인지 테이블은 정말 간이테이블로 2개 있어요! 매장에서 취식하려면 웨이팅을 감수해야해요. 롤크레이프는 많이 달지 않고 적당해요! 포크가 플라스틱이라서 크레이프가 잘 안뜯겨서 찢어 먹어야해요ㅎㅎ 마카롱도 맛집이였어요!', 75, 14, 'GOOD', SYSTIMESTAMP);
