INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '📍포장 전문 매장이라 매장 내 테이블이 협소하고 테이블이 두개라서 금방 자리가 찹니다-! 앞에 한팀 있고 20분정도 웨이팅 후에 앉았습니다 📍전날 인스타에서 미리 예약하면 담날 시간 지정해서 픽업 가능하더라구요! 참고해주세요🥰 👉🏻8800원짜리 과일 가득한 롤크레이프라니 원래같았으면 비싸다며 뒷목잡고 넘어갔을 가격인데 친구랑 먹으면서 ‘와 이정도면 진짜 저렴하다’만 남발하며 허겁지겁 먹어 해치웠습니다 다 먹구 하나 더 사서 포장해갔네요 기념일에 꼭 여기서 잔뜩 포장해서 가려구요ㅜㅠ과일이 보이는 곳만 있는게 아니라 아주 가득 차있어요 정말 최고의 케이크 마카롱도 저렇게 크림이 많은데 하나도 안느끼하고 꼬끄도 쫀득하니 맛있었어요 👉🏻인스타 안보고 가도 친절하게 잘 설명해주십니다-!ㅎㅎ', 61, 14, 'GOOD', SYSTIMESTAMP);
