INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '매장은 깔끔하지만 테이블이 2개 밖에 없어요 하지만 테이크아웃 하면 아메리카노가 할인 돼서좋구요.ᐟ 포크도 챙겨주셔서 날씨 좋은 밖에서 맛있게 먹었어요', 46, 3, 'GOOD', SYSTIMESTAMP);
