INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '진짜 비주얼도 최고고 맛도 최고입니다! 1시 오픈이라 1시50분에 갔는데도 이미 상품들이 많이 빠져있고, 케이크는 제가 포장 기다리는 사이에 다 완판....이런곳을 이제야 알다니....!', 22, 4, 'GOOD', SYSTIMESTAMP);
