INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '커피는 맛있어요~ 가게는 좀 작아요. 디저트는 마카롱밖에 없는데 생각보다 맛은 그닥... 비주얼이랑은 예뻐서 마카롱 좋아하는 사람들한테 선물로 주기는 좋은거 같아요~', 4, 0, NULL, SYSTIMESTAMP);
