INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '다양한 디자인중에서 골라서 당일에도 가능한 레터링 케이크를 가성비있게 주문할 수 있어서 너무 좋았어요! 사장님도 친절하세요 :) ♥️', 18, 2, 'GOOD', SYSTIMESTAMP);
