INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '예약을 못해서 당일 케이크로 구매했는데 현장에서 넘 예쁘게 레터링 해주셔서 좋았어요! 벌써 여기서 3번째 구매입니다ㅎㅎ 케이크 디자인도 폰트도 넘 이뻐요!!', 39, 10, 'GOOD', SYSTIMESTAMP);
