INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '항상 레터링 미니 케이크 필요할 때 연락하는 곳!!!!!!! 당일 주문 가능해서 너무 좋고 케이크도 딱 적당한 크기에 맛있기까지해요 ㅎㅎ 또 올게영 ><', 49, 7, 'GOOD', SYSTIMESTAMP);
