INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '친구 생일 케이크 주문 했어요! 전날 부탁드렸는데, 빠르고 친절하게 안내해주셔서 너무 좋았습니다! 원하는대로 디자인 나와서 너무너무 맘에 들어요 💝', 29, 2, 'GOOD', SYSTIMESTAMP);
