INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '벌써 3번째 주문인데 캐릭터 너무 귀엽고 맛도 있어요.. 홍대 앞이라 찾기도 편해요!!! 그리고 무엇보다 당일케이크 고정디자인이 완전 귀여워요~!!!!', 24, 3, 'GOOD', SYSTIMESTAMP);
