INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '친구 축하기념으로 케이크해줬는데 너무 귀엽고 깔끔하게 잘 해주신거같아요! 디자인 항상 맘에 듭니다! 여러케이크집 먹어봤지만 여기가 적당히 꾸덕하고 안에는 부드럽고 너무달지않아 맛있습니다~후식으로 너무좋아요! 여러번 사먹었는데 리뷰를한번도 안써봐서 리뷰남겨봅니다~열번 사드세요~!', 42, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '백일 기념으로 도시락케이크 주문했는데, 커스텀이 안 되어도 예쁜 디지인이 정말 많아서 좋아요~!! 케이크 너무 귀엽구 사장님도 정말 친절하십니다 ☺️', 16, 7, 'GOOD', SYSTIMESTAMP);
