INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '친구 생일이라 급하게 주문했는데 당일 가능한 디자인들이 따로 있었어요 ! 귀여운 디자인들 넘 많고 친절하신 사장님 덕분에 좋은 하루 보냈네요 ㅎㅎ 크리스마스 케이크도 종류 많아서 또 주문하고 싶어요 다른 가게들 다 찾아보고 여기서 주문 한건데 완전 만족 입니당 :)', 43, 6, 'GOOD', SYSTIMESTAMP);
