INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '케이크 말씀드린 느낌 그대로 제작해주셨어요 🥹🫶🏻🫶🏻🫶🏻 시트도 촉촉하고 넘 맛있어서 친구들이랑 한 입 먹자마자 큰 사이즈로 할 걸 후회했답니당 ㅠㅠ 다음엔 1호로 주문 할고에요!! 🤍🤍🤍', 63, 12, 'GOOD', SYSTIMESTAMP);
