INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '당일에 급하게 예약했는데 친절하게 받아주셨습니다ㅠㅠ 케이크 너무 예뻐요.....다음에 또 주문제작해야할 일이 있으면 다른 디자인으로 꼭 주문할게요!!!! 감사합니다 🥹❤️', 63, 15, 'GOOD', SYSTIMESTAMP);
