INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '케이크 🎂 너무 아기자기하고 예쁘고 카톡 예약도 친절하게 잘 받아주셨어요!! 사진보다 훨씬더 화사한 색감이라 굉장히 귀여워요. 기념일에 케이크집 찾을 때 하시면 너무 좋을 것 같아요!', 67, 17, 'GOOD', SYSTIMESTAMP);
