INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대에서 여러 도시락케이크 주문해봤는데 저는 여기가 제일 친절하고 맛있었어요!!!! 주문하고서도 색상이나 디자인 에 대해 많이 물어봐주시고 원하는 느낌을 너무 잘 캐치해주셨어여~ 사장님이 초도 서비스로 주셨어요ㅎㅎ감사합니당💕 다음 기념일에도 또 올게요!!!', 90, 13, 'GOOD', SYSTIMESTAMP);
