INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '원하는 디자인으로 너무 예쁘게 만들어주셔서 대만족이에요~  다른 어떤 곳보다 솜씨도 좋으시고, 잘 만들어주시는 거 같아요! 매번 이용할 때마다 감탄합니다. 원하는 디자인 있으신 분들에게 강추해요!!', 14, 2, 'GOOD', SYSTIMESTAMP);
