INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '급하게 주문했는데도, 사장님이 친절하게 응대해주시고 예쁘게 제작해주셨어요!!!!!!🥹 그림도 글씨도 너무 귀엽구 예쁘구  무엇보다 맛있어요!💗💗 덕분에 달콤한 기념일 보냈슴닷🫶🏻', 8, 3, 'GOOD', SYSTIMESTAMP);
