INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '전 날 밤새고 예약 시간보다 늦게 갔는데 직원분들이 친절하게 이해주시고, 케이크도 주문 부탁드린대로 예쁘게 해주셨어요❤️ 다음에 또 이용하고싶어요😚', 24, 1, 'GOOD', SYSTIMESTAMP);
