INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '특별히 엄청 맛있다정도는 아니지만 평범하게 맛있고 요즘 물가생각하면 가격도 괜찮 작지만 종류도많고 알차네요 갠취로는 아오이토리보다 괜찮았네요 종종 들릴만한곳', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '나도 드디어! 야끼소바빵! 샀는데 나는 못먹어봤다 나중엔 혼자 몰래 다녀와야지 ㅠㅠ 생각보다 빵 종류도 많고 미니소금빵 짱귀💙', 39, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '야끼소바빵이 일단 일본에서 먹은것보다도 맛있었어요. 꼬마소금빵(1800)도 바로 나온거 사와서 바로 먹었는데 맛있었구요. 데리ㅑ끼 샌드는 소스가 많아 짭잘했지만 맛있어요. 다른 빵도 다 맛있을 듯해요', 83, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '한국에서 이렇게 맛있는 바게트를 먹을 수 있다니 정말 감동적이에요. 쿠리노키 바게트, 크렌베리&호두 바게트, 올리브 치아바타 다 다르게 맛있어요. 프랑스 안부럽습니다.', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '너무맛있어요! 꼬마소금빵 멜론빵 쿠마빵 마요에그 다 취향입니다 :) 진짜 일본분이 하시는 곳이라서 확실히 달라요! 합정 빵집으로 추천해요', 61, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '우연히 방송보고 방문했어요. 새우카츠버거는 정말 일본 스타일이에요. 새우패티도 새우가 많이 들었고 또 안에 양배추가 입안을 깔끔하게 해줘요. 타마고샌드는 가성비 짱입니다. 푸딩도 너무 달지 않고 맛있어요. 거리가 있지만 또 방문하고 싶어요.', 39, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '이번에는 야키소바빵(이건 항상 먹어요~), 다마고샌드(이것도 자주 먹어요~)에 처음으로 아몬드 크로와상을 먹어봤는데 이것도 정말 맛있어요~~ 새로운 것을 하나씩 먹어 보려고 고른 건데 정말 맛있었어요~^^ 다음에는 또 다른 빵에 도전~!!', 0, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '지난번엔 직장동료가 사다줬고, 오늘은 퇴근길이라 한번 가봤는데.. 저도 모르게 3가지나 담았네요 ㅋㅋㅋㅋ 지난번에도 느꼈지만 앙버터 좋아하는지 몰랐는데 늘 먹게되는 앙꼬버터빵과 소금빵.. 넘 맛있어서 또 골랐구요~ 소금빵도 작고작은 바게트같은 느낌이 좋았어요^^ 그리고 맛있다는 아몬드 크로와상도 한번 먹어보려고 샀는데.. 한조각 맛만 본다는것이 그만.. 버스정류장 도착하기전에 다 먹어버린..ㅋㅋ 달지않아서 그런가봐요^^ 문 닫을때가 되어 그런지 마블식빵인가요? 2조각을 주셨어요^^ 이것마저도 맛있네여~~~^^', 17, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '야키소바빵이 특이해서 방문했는데 정말 야키소바랑 핫도그빵을 같이 먹는 느낌이에요~ 소금빵은 엄청 질기고 딱딱한 편입니다! 가격대비 빵 자체는 괜찮은 편이지만 예상 가능한 맛이라 재방문은 안할거 같아요!', 126, 20, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '야끼소바 빵이 유명한데 오후에 가면 없어서 오늘은 아침에 가서 살 수 있었습니다. 커피와 함께 먹으니 한 끼 식사가 되네요^^ 역시 맛있습니다. 하나만 사기 아쉬워서 다마고샌드(달걀빵)과 고구마밤빵도 샀는데 이것도 아주 맛있어요~ 가격이 조금 있기는 하지만 여기만의 독특한 빵이어서 사 먹을 만합니다~', 34, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '지난 여름에 가봤었고 오랜만에 재방문했어요. 간식빵과 식사빵이 다양하고 야키소바 빵, 카레빵, 에그 마요, 메론빵 같은 일본식 빵도 몇가지 있는데 에그 마요는 좀 아쉬웠어요. 지난번에 먹었던 새우 카츠 샌드가 맛있어서 재구매! 부모님의 간식으로 좋은 밤맛 단팥빵도 추가!', 32, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '지나가다 들렀는데 알고보니 유명한 것 같더라구요 빵이 담백하고 고소하게 맛있어요! 직원분들도 친절하시구요 주변에 일 있으면 또 방문하려구요', 79, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '기대안하고 산건데.. 너어무 맛있어요!^^ 사실 일본빵집이라 시그니처빵은 야끼소바빵인가? 그런데.. 전 특이하게 앙꼬버터빵이랑 소금빵 샀어요.. 앙버터를 이렇게 좋아했었나? 싶게 요즘 빵사면 계속 앙버터를 사게되는데 살짝 보드라운 바게트빵 속에 앙꼬랑 버터가 들어가있는데 진짜 엄청 부드럽고 달콤한것이 너어무 맛있어요ㅠㅠ 소금빵도 그냥한번 시켜봤는데.. 이건 확실히 바게트처럼 바삭한데 짭짤하고도 고소한맛이 일품입니당♡ 가격이 싼만큼 크기는 작지만, 그래도 가격이 너어무 맘에드니까 크기가 적당한 너낌^_^)/ 아몬드 패스츄리도 맛잇다던데.. 다음에 도전해봐야겠어용ㅎㅎ', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '존맛탱 ㅠㅠ 야키소바빵이 일등일줄알았는데 보통이었고 생강 좀 듬뿍 올려주심 좋을듯 새우카츠버거가 일등이구요 다움은 고로케샌드, 다마고샌드요 바닐라푸딩도 존맛 하 ㅠㅠ 카레빵도 사올걸 후회함 담에 또 갈거에요 직원분들 친절하고 아아도 갠춘 😽', 21, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '메론빵 달달파삭하니 너무..맛있었어요..ㅠㅠ. 크림메론빵의 크림이 달지않으면서 바닐라빈이 콕콕 박혀있어서 달달한 메론이랑 조화가 좋았습니다!!매장도 예쁘구.. 친절해서 좋았어요♡', 82, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '야끼소바빵 새우카츠버거 카레빵 등등 사왔어요. 평일 여섯시 좀 되기 전에 갔는데 다시 구워서 채우신건지 사고싶은거 재고가 다 있어서좋았어요', 70, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '따끈한 소금빵이 그리워서 왔어요. 줄서서 먹던곳인데 가게는 고객은 없이 매장은 텅비고 바게트 소금빵이라 딱딱하다느는데. . 아구가 아풀정도로 딱딱. 이런빵이었나? 좀 이상하네요ㅠㅠ', 42, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '야끼소바빵이 여기 시그니처 메뉴라 추천받아 먹어봤어요 야끼소바와 빵이 의외로 잘 어울려요 새우카츠버거 진짜 맛있어요 추천합니다!', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '개인적으로 야키소바빵이랑 바닐라 푸딩이 👍 샌드 종류도 맛있고 스콘도 2000원 대여서 부담없이 살 수 있어요🍀 소금빵도 있는데 나온지 조금 지나서 그런지 딱딱했지만 맛있었어요!! 망원 가게되면 한번 쯤은 가보세요🍥🍥 중심가에서 조금 떨어져 있지만 엄청 멀지는 않구 길찾기도 쉬워요👊🏻 요런 제과점은 앉는 곳이 없는데 여긴 앉을 수 있는 곳도 있어서 좋았구 커피 가격도 착해서 빵이랑 같이 먹어도 부담 없어요!!', 90, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '소금빵이 바삭해서 너무 좋았어요. 치즈 루스틱, 야키소바빵, 타마고샌드 등 여러 종류를 샀는데 자극적이지 않아서 맛있었습니다^^', 60, 15, 'GOOD', SYSTIMESTAMP);
