INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '요새 빵값이 워낙 비싸서 여기 빵은 싸게 느껴질 정도에요!! 대신 크기가 큰 편은 아니지만 합리적인 가격에 맛있는 빵이 종류별로 진짜 많아요!', 44, 2, 'GOOD', SYSTIMESTAMP);
