INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대 아오이토리에 있던 제빵사분이 독립해 나와 하는곳이다 보니 비슷한 빵들도  꽤 있어요.. 딱 일본현지 빵집의 인테리어와 분위기고 가게가 좁지 않고 공간이 쾌적합니다... 가성비도 괜찮고 빵맛도 좋은 일본식 빵집입니다.. 이 집 빵중에는 한때 일본에서 엄청나게 유행했던 소금빵도 있지만 저는 개인적으로 밤크림프랑스와 밀크크림프랑스를 강추합니다..^^', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '팥 식빵을 처음 구매했는데, 요건 그냥 먹어야 하는 빵인가 보다 . 땅콩쨈이랑 샌드위치 햄을 올려서 먹어봤는데 별로 어울리지 않았다.', 36, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '구입한 7종빵 모두 평균적이었구요, 특히나… 야끼소바빵에 초생강채… 초생강채 못먹는 전 한입 베어먹고 네… 뱉었어요; 타 빵집 야끼소바엔 생강채가 없어서 방심했습니당 (초생강채 못먹는 1인은 눙물한가득…;)', 97, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '판매되는 모든 빵이.... 정말정말 엄청 맛있습니다 개인적으로 치아바타 올리브랑 무화과 크림치즈는 정말 10개씩 사먹고 싶어요', 30, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '빵 맛있어요 그자리에서 포만감을 중시하는 분이라면 새우카츠버거 추천입니다 야끼소바빵도 일본에서 막어봤던 그맛인데 너 맛있는것 같기도 하구 **치즈루스틱 제 원픽이에요 집에와서 오븐에 살짝 돌려먹었는데 겉은 빠삭하고 속은 부드럽고 짭쪼롭합니다', 119, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '앉아서먹고갈공간도있고좋습니다! 오픈시간도빨라서좋아요ㅎㅎ그래서더일부로일찍방문합니당ㅎㅎ새벽출근이라카페연곳찾기힘든데 회사랑15~20분걸어와야하는곳이지만 종종 올게요~~!ㅎㅎ 치킨샐러드미니도4천원 넘 합리적가격! 시오빵도미니있어서 좋고ㅠㅠ 시오빵진열없어서시무룩할뻔했는데곧나온다고갓나온걸로주셨어요ㅎㅎㅎ 오픈주방이라청결할거같고좀더신뢰가갑니당ㅎㅎ 평일아침종업원분 외국인이신데 친절하시고 잘알아들으세요!ㅎㅎ(한국서좋은경험하시길)', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '소금빵 좋아해서 들른 쿠로노키 제빵!! 꼬마 소금빵은 역시 듣던대로 하드 소금빵이라 겉은 바게트 같고 안은 부드럽다. 오래 두고는 못먹겠지만 입천장 까지는 바삭함 좋아하는 분이라면 추천! 유산지가 바로 기름이ㅎㅎ 역시 이래야 소금빵이지🤭🤭 점약도 있어서 소금빵만 먹으려 했으나 타마고샌드 지나칠수 없지ㅜ ㅜ다른 야채는 없는 에그마요지만 난 이게 젤 좋더라 더럽🥰🥰', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '일단 소금빵이 맛있고요. 바게트도 고소하고 맛있어요. 특히 코리노키바게트가 구수하고 바삭하면서 맛있습니다. 잠봉붸르만들어먹으면 진짜 맛있어요', 68, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '소금빵이 먹고싶어서 갔는데!!!! 다른 빵들도 엄청 많고 다 맛있어요!!!! 야끼소바빵이 유명하긴 한데 저희는 밤크림빵, 타마고샌드, 치아바타올리브, 꼬마소금빵, 아아, 아이스라떼 시켜먹었어요! 밤크림빵이랑 치아바타올리브 왕추천이에요! 밤크림이 고소하고 빵 자체가 맛있어요! 치아바타는 올리브가 그린, 블랙 다 풍성하게 있어서 향이 좋아요! 소금빵은 겉은 바삭하고 속은 쫠깃해서 계속 먹고싶어요..ㅋㅋㅋ 추천! 타마고샌드는 그냥 soso에요! 다음엔 다른 빵들도 먹어볼래요!! 사장님이랑 직원분도 친절하세요!', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '평일 오후 5시 좀 넘어서 방문 했는데 알바생이 너무 불친절 합니다. 포장 안되어 있는 크루아상에서 기름이 묻을거 같아서 다른빵처럼 비닐포장(무상) 해달라고 했더니 기름 안 묻는다고 종이에 담았다가 종이에 바로 기름 묻는거 보더니 그제서야 비닐에 담아주는데 도데체 그게 그렇게 못 마땅 한건가요.. 크루아상에 버터가 얼마나 들어가는데 기름이 안묻는다는건지.. 알바생들 시급에서 비닐값 빠지나요? 그리고 알바생들 빵 교육좀 시켜야 할거 같아요 알바들이 빵에 대해 아는게 없어요.. 물어봐도 본인들도 모르는듯.. 빵은 맛있어 보이네요', 9, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '초코빵 비싸 보였는데 안에 초코칩도 있고... 진심 너무 맛있어요 소금빵은 식은 채로 먹었을 땐 너무 질겼는데 에프 돌리니까 미쳤어요 담에 또 갈게요 ♡', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '한번도 이런 나쁜글 남긴적 없는 너무기분 나빠 남겨요. 일주일에 최소1회는 가는데 알바가 바뀐건지 맨손으로 빵 봉지에 담아주는거 보고 놀랐어요. 본인 먹을것도 아니고 판매하는빵 썰어 달랬더니 맨손으로잡아서 봉지에 담고 지금 맨손으로 담은거냐니 너무당당하게 네 합니다. 기분나빠서 취소해 달라니 사과도 없음 정신없이 가방에 빵담고 집에와서 보니 소금빵 비닐에도 안담겨있음 사진보시면 통에 기름잔득 묻은거 보이시죠. 비닐은 넣어줬는데 다른물건 꺼내며 빠져서 그런거다 제실수다 네 100번양보해서 그렇게 생각할수 있겠지만 빵 맨손 이건아니다 싶네요. 사장님 보시면 영수증 날짜 확인해서 cctv꼭 확인해보세요. 여기가면 외국인 여자분이 늘친절하셨는데 아쉽네요.', 56, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '꼬마소금빵4개,밀크크림프랑스,치아바타올리브,야끼소바빵 이렇게 구매했어요 소금빵이 먹고 싶어서 검색하고 처음 갔어요! 소금빵은 기존에 먹던거랑 다르더라구요..?겉바속촉을 기대했는데…음 존 메마른 식빵 느낌..?원래 이런건가요~? 크림빵도 그냥 크림 조금 들어간  크림빵.. 치아바타는 그래도 맛있었어요!', 30, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '전부 존맛 입니다 ㅠㅅㅠ 명란바게트 아다섯글자 보다 맛있었어요 뜯자마자 불향 대박 암튼 다 맛있어요 제빵사님도 친절하시고요 첫방문이였는데 구매한 빵 6개 다 만족! 앞으로 매번 가고 싶네요!! ㅠㅠ', 38, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '일본 스탈의 기요미빵들 ㅎㅎ 귀엽지만 제취향은 아니라서.. 전 다른 빵 구매!! 명란빠게트,새우카츠버거 맛나보여서~~ 식사류 빵들도 많이 있어요 가격대도 저렴한 편^^ 맛있으면 또 가려구요~', 38, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '맛있어요. 갈때마다 다른 종류로 구매합니다. 가격부담이 적어서 이것저것 사기 좋아요. 크기가 작은편이여서 물리지않고 먹을 수 있어요. 크기 또한 가격을 생각하면 괜찮다는 생각이 듭니다.', 73, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '야키소바빵 나쁘지 않지만 큰 특징은 없고, 미니소세빵도 그냥 아는 맛.. 소금빵 최애빵인데 사자마자 먹었는데도 너무 너무 딱딱해서 턱 나가는 줄 알았어요. 겉바속촉정도가 아니라.. ㅠㅠ 후기 읽어보니 비슷하게 느낀 분들이 있네요. 뭔가.. 집에 가서 다시 데워먹던가 해야될 거 같은..ㅠㅠ', 9, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '아직 다른 빵은 못먹어봤는데 마요에그 맛있어요!(정신 없이 먹다가 사진 찍었습니다) 다음에 근처 지나면 또 갈 의향 있어요ㅎㅎ', 320, 68, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '아오이토리랑 메뉴가 겹친다했더니 거기 수석셰프님이 나와서 만들었다고 하네요! 진짜 재료는 듬뿍 존맛탱에다가 장바구니 물가는 일본현지 반영이니,,^^ 거의 종류별로 쓸어왔는데도 가격 저렴해요. 재방문의사 300%', 44, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '맛있어요. 예약한 식당이 시간이 남아서 지나가다가 점심 식사하시고 식당에서 나오시는 회사원분들이 모두 우르르 빵집으로 들어가길래 따라 들어갔구요, 대성공이었습니다. 제 앞에서 매대에 있던 초코빵을 모두 집어가신 회사원분 덕분에 맛있는 메론빵 먹을 수 있었어요.', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '맛집이라고 갔다가 실패하고 돌아오는 길에 만난 찐맛집... 치쿠와 빵은 처음 보는데 와 여기 너무 맛있어요 ㅠㅠ 가까우면 매일 갔을텐데 너무 아쉽습니다', 47, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '저의 원픽 치즈루스틱❤❤ 그다음 치쿠와빵, 콘치즈 치아바타 이렇게 3가지 빵들 너무 맛있고 진짜 개좋아요 빵사러 왕복2시간인데 무조건 가능ㅎ', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '아끼소바빵 소금빵 사고팠는데 오픈직후엔 안 나와있더라구요 ㅜ 핫도그 든든마밌고 멜론빵 아몬드크로와상도 추천이요~ 명란바게트는 비려서 비추', 41, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '메론빵 일본에서 사먹던 바로 그맛이에요!!! 기본 메론빵, 말차 메론빵, 초코칩 메론빵 셋 다 넘 맛있어요 ㅎㅎㅎ 합정 갈 때마다 메론빵 데려올게용>_< 소금빵은 오후 5시에 가니 없어서 못 먹었어요 ㅠㅠ 소금빵도 많이많이 만들어주세요!!', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '리뷰는 처음인데 4번째? 방문인것같아요ㅎ 신대방쪽에 사는데 꼭 합정까지 지하철 타고 가서 사는 빵집! 저렴한데 맛은 미친수준! 계속 팔아주셨으면 좋겠고, 치즈 루스틱, 콘치즈치아바타가 제 원픽들❤', 115, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '흔치 않은 일본식 빵을 먹을 수 있는 빵집이에요. 최애는 에비카츠버거, 야키소바빵, 말차메론빵, 오렌지쇼콜라, 유자단팥빵인데 오렌지쇼콜라랑 유자단팥빵은 꼭 드셔보세요. 둘다 향긋하니 너무 맛있어요. 특히 유자단팥빵은 빵피도 너무 쫀득하고 특이하게 흰색앙금이 들어있는데 유자향이랑 너무 잘 어울려요. 매장이 아오이토리에 비해서 아늑하고 깔끔한 느낌이라 좋았고 빵구경하기에도 더 편했던 거 같아요.', 202, 69, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '한번가면  적게 사올순없는곳... 푸딩... 하.. 이건 천상계에요.. ㅜ 초코소라빵...그동안먹은건  가짜여쒀.. 완전JMT 식빵,시오빵,아니...   뭐하나 맛없는게 없어요', 47, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '시오빵, 멜론빵 너무 맛있어여!! 야끼소바빵은 첨엔 잉??? 먹다보면 아~왜인기있는줄 알겠다 베이컨에피는 별루였어여...베이컨이 넘 조금든 느낌...', 16, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '가격대비 속이 엄청 빵빵하고 맛있어요ㅠㅠ 야끼소바빵은 쪼금 셔서 별로였는데 에그샌드위치 명란바게트 마들렌 전부 맛있어요 !!!!!', 24, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '빵은 맛있어 보이는데 점장/매니저분이 알바생분을 너무 하대해서 듣는 제가 기분이 안좋아지더라구요 손님앞에서까지 그러시는건 좀 아닌것 같습니다', 11, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '일본식 🍞가게였어요. 빵 종류도 메론빵 카레빵처럼 (호빵맨친구들) 일본식!! 사장님께서 친절하셨습니다🤗 🥖 명란바게트 : 명란바게트를 처음 먹어보는데, 명란을 아낌없이 얹으셔서 단면 위가 주황색이었어요ㅋㅋ 첫입에 너무 짜게 느껴졌는데 커피랑 먹다보니 계속 땡기긴 함. 🍛쿠리노키 카레빵, 🥚타마고 샌드 : 가족이 먹고 맛있었다함. 🍤🍔새우카츠버거  : 제입맛에는 쏘쏘. 새우튀김이랑, 계란샐러드, 그리고 안쪽에 야채샐러드? 같은게 있어서 다양한 맛이남. 내용물이 많으니 먹을때 밀려나서 따로따로 먹게되기도 했지만, 속재료끼리 조합이 엄청 좋은건지는 모르겠어요ㅎㅎ 참깨빵에 참깨가 가득한건 좋았음. 🌽 콘마요 : 맛있었음 🐻 쁘띠모카밀크 : 곰돌이 모양이라 귀여웠지만 한입에 먹었어요 ㅋㅋ 안에 초코크림?잼?있음', 20, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), 'ㅎㅎ가까운 곳에 이런 맛있는 베이커리가 있어서 행복해요 ~❤️지나다니며 생각만 하다가 첫방문했는데,앞으로 자주 갈것같네요 ㅎㅎ 새우카츠버거 정말 맛나요😍', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '두 번째 방문입니다! 올해 슈톨렌을 처음 알게되서 어디서 살 수 있는지 검색하다가 알게 되었습니다. 올해 세 군데에서 슈톨렌을 먹어봤는데 개인적으로는 쿠리노키 슈톨렌이 제일 취향이었습니다💖 다 먹어서 또 사러왔어요! 베이커리마다 슈톨렌은 개성이 다양해서 개인 취향에 따라 맘에 드는게 다 다를 수는 있는 것 같아요^^ 다른 빵들도 넘 맛있어보여요!(오늘 산 러스크 정말 최고네요👍👍👍) 마지팬?이 들어가도 더 흥미로울 것 같습니다ㅎㅎㅎ 메리크리스마스!', 55, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '하얀 눈이 소복소복 쌓인 것 같은 독일의 전통 빵 슈톨렌! 슈거파우더에 하얗게 덮인 모습이 보자기에 싸인 예수의 형상을 닮았다 해서 stollen 슈톨렌 이란 이름이 붙었다는군요. 무게가 묵직하면서 부드러운 식감에다 계피 향도 나고 다양한 향들과 견과류, 독특한 풍미 크리스마스를 기다리며 매주 한 조각씩 잘라먹는 빵이라 얇게 썰어 먹는다고 합니다.', 46, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '메뉴 : 초코소라빵, 멜론빵, 미니소세지, 꼬마소금빵,쿠리노키카레빵 1. 일본식 빵을 파는 것 같습니다 2. 가게안에서 빵과 커피를 먹을 수 있는 공간이 있습니다. 3. 주차는 주변 주차장에서 히는것을 추천드립니다. 4. 주변을 지나갈 일이 있다면 구경삼아 방문드리는것을 추천합니다', 18, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '꼬마소금빵 그냥 먹으니 조금 질겼어요. 약간 데워서 커피랑 먹으니 꿀맛👍🏻 새우카츠버거도 조금 데워 먹으니 프랜차이즈 새우버거 저리가라네요. 새우버거가 얼마더라...', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '오후에 계신 점원 분 너무 센스 넘치세요 ㅠㅠ 커팅도 예쁘게 해주시고 물티슈도 물어봐주시고요!! 기분 좋은 구매 경험이었습니다', 120, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '항상 맛있게 먹는편. 바게트는 처음 사봤는데 다른곳보다 부드럽지만 개인적으로는 구멍 빵빵뚫린 빠삭한 맛으로 먹는편이라 조금 아쉬움', 31, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '아직 문 연지 얼마 안 됐지만 이미 단골입니다^^ 지금까지 여러 빵들 사먹어 봤지만 정말 다 맛있더라고요. 그 중 갠인적으로 강추빵은 카레빵, 치쿠와빵, 유자안금빵, 멜론빵...등 진짜 예술임. 빵 종류도 정말 다양하고 저 일본에 20년 이상 살다 온 사람이고 지금까지 한국에서 일본인 주인이 하는 빵집 빵도 많이 먹어봤지만 이 가게가 지금까지 맛도 빵 종류 다양성도 최고인 것 같아요!', 8, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '아몬드크로와상 ❤️ ㅠㅠㅠㅠ여기 후기에 일본에서 먹은 멜론빵보다 맛있다는 글 봤었는데 결제해주신 제빵사 분이 일본 분이셨어요 ㅋㅋㅋㅋ', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '외쳐 갓몬드크로와상! ㅠㅠㅠㅠㅠ! 제빵사님 손보험 들어주세요 ❤️❤️❤️ 우리 집 옆에 200호점 생기게 소문내고 다닐거에여어어어아 아 그리고 가격도 파바보다 훨씬 착하고요 훠얼씬 맛있고 아침에 들어가면 제빵사님들이 안에서 밖에 흘끔 보시는 것도 귀여우시고요 여성 점원분 따스하게 맞아주시는 분위기도 좋고 엄청 친절하세용 진심으로 번창했으면 좋겠어요', 27, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '빵 12개 샀는데 하나같이 다 맛있어요. 막 나온 소금빵 넘 맛있어요 ㅠ 나오면서 남편이 다음주에 또 오자고 하네요 흐흐. 유자단팥빵 맛있다는 리뷰 보고 샀는데 유자 앙금이 너무 맛있고, 베이컨 에피 집에 오는 동안 한개씩 뜯어먹었는데 남편이 너무 좋아해서 양보했어요ㅋㅋ 빵들이 다 담백하고 너무 맛있고 명란바게트도 먹어본 곳 중에는 젤 맛있네용. 소금빵만 먹어봐도 잘하는 빵집 이구나 싶음 !! 친절하셔서 더 좋아요', 53, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '동네에 일본풍 빵집이 생겨서 좋아요😆 빵 다 맛있고 특히 말차소라빵 맛있어요..찐이에요 근데 계산해주시는 분이 너무 느려서 오래기다려야해요ㅜ ㅜ 나중에 더 손님 많아지면 두분이서 하셔도 좋을거같아요!', 37, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '집근처라 3번정도 갔어요 주말이나 늦게가면 빵이 없어요 대부분 맛잇어요 가격괜찮고 사이즈는 작은편인데 그게 좋아요 무식하게 큰빵 밥맛떨어짐', 50, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '단팥빵이랑 오렌지쇼콜라빵 두개를 먹었는데 생각보다 평범했어요. 이른 아침에가서 빵 종류도 많이 없어서 좀 아쉬웠어요. 다음에는 빵이 많이 있을때가서 다른거 먹어봐야겠네요.', 20, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '슈틀랜 맛 동일   치아바타는 살때마다 빵맛이 다름   새우가츠빵 음십을 빵에  믹스하는건 먹기도 번거로운듯 하지만 가츠맛 자체는 나쁘지않음', 59, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '생생티비보고 퇴근후달려감 일단치아바타는 내스탈 쫀득쫀듯 살살녹음 딸기크림빵은 남스탈 소보루와공갈빵의중간사이 크림이 거의 없음ㅜ 남은 소금빵과 슈틀랜 오랜지 머시기 낼 시식', 40, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '겨울이지만 썸머라떼(only ice) 왜냐면 아이스크림이 올라가는 라떼라 그렇습니다. 분위기도 좋고 커피도 맛있고 다음에 또 갈래요!! 🎄트리도 인상적이었어요 :)', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '예쁜 사장님과 예쁜 디저트..🤍 가보고 싶은 곳에 저장 했었는데 이제 온게 후회될 정도로 너무 좋았던 곳이에요🥹 사장님 미모만큼 성격도 너무 좋으시고 음료도 디저트도 엄청 맛있어요!! 이젠 가보고싶은 곳이 아닌 꼭 와야 할 곳으로 저장 해야겠어요 :)', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '핸드폰 배터리가 다 되서 아쉽게 사진을 못찍었네요. 커피 맛있구요. 밀크티도 맛있었어요. 청소년들과 같이 갔는데 마땅히 먹을 만한 음료가 없었는데 아포카토를 아이스크림으로 바꿔주시는 센스가 너무 좋았어요 ^^', 76, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '전체적으로 직원분들 분위기가 어수선 했습니다. 원두가 문제인건지 머신 퀄리티에 비해 커피 맛은 다소 아쉬웠습니다. 화이트(산미)로 선택했는데 후미가 없다시피 한 맛이났습니다', 50, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '두번째 방문! 그때도 바닐라크림라떼가 맛있어서 이번에도! 역시 맛있고 리필 아메리카노까지 받을수 있다니 넘 감동!아메리카노도 맛있어요~고소한거 추천! 직원언니들도 다 예쁘시고 좋아용', 1, 6, 'GOOD', SYSTIMESTAMP);
