INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '크림 카푸치노 맛있어요! 크림 세덩이가 부드럽고 맛있어요! 커피에 바로 녹지 않아서 크림도 따로 즐길 수 있습니다. 크림카푸치노, 크림라떼 둘다 플레인, 모카 등 안에 커피도 고를 수 있어서 특히 좋네요. 날씨가 더워져서 곧 에어콘을 틀어줬으면 좋겠습니다...! 또 방문하고 싶습니다.', 8, 3, 'GOOD', SYSTIMESTAMP);
