INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '주말에 오면 항상 만석이라서 못 갔었는데 좀 일찍 오니까 여유롭네요. 통창이라 분위기도 좋고 , 커피맛이 너무 제취향 . 커피 맛있다고 했는데 진짜 맛있음 !!', 11, 2, 'GOOD', SYSTIMESTAMP);
