INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '벌써 3번째 방문 ! 근처 올 때마다 들르는 것 같아요 ◡̈ 직원분들 친절하시고, 아아로 리필 되는게 너무 좋아요 뷔릴레라떼 생각나서 자꾸 오게 됩니다🤤 레몬에이드는 상큼~하고 에그타르트 보들보들하니 맛있어요🥧', 34, 7, 'GOOD', SYSTIMESTAMP);
