INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '오버트 합정 들어가자마자 진짜 커피향과 빵 냄새가 너무 좋아서 설렜는데, 진짜 실제로 커피, 크로와상, 에그타르트 다 너무 맛있어요! 사장님도 너무 친절하시고 인테리어도 멋져요! 합정역 카페 오버트 강추💓', 70, 16, 'GOOD', SYSTIMESTAMP);
