INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '차가운 크림과 따뜻한 커피가 섞이며 입안에 들어오는게 크림라떼 맛집이네요. 에크타르트도 괜찮았고요~ 다 마시면 아메리카노 1회 리필도 가능해서 시간 보내기 좋습니다.', 11, 9, NULL, SYSTIMESTAMP);
