INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매일 마시는 아이스 아메리카노, 산미가 싫어 블랙원두만, 테이크아웃 할인에 스탬프 쿠폰 모으는 재미까지, 일상 커피생활이 즐겁다', 42, 7, NULL, SYSTIMESTAMP);
