INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '크로와상 플레이트 너무 만족했어요! 크림과 아이스크림, 바나나 그리고 갓 구워서 따뜻한 크로와상까지 한입에 와—앙하면 천국이에요🥹✨️✨️', 84, 11, 'GOOD', SYSTIMESTAMP);
