INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '합정역 커피맛집 음료 다 마시면 아메리카노로 리필가능! 디저트도 맛있고 커피도 맛있어요 감성카페♡ 저는 크림카푸치노가 취향이었어요 디저트도 크로와상플레이트 추천~ 합정 감성카페로 좋아요^^', 97, 24, 'GOOD', SYSTIMESTAMP);
