INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '커피가 맛있어요!!! 평일 점심시간에 사람이 와아 하고 몰렸다가 사라지는 마법을 볼 수 있습니다 ㅋㅋㅋ 매장도 깔끔하고 좋아요!', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '유명한 감성카페인 만큼 깔끔한 인테리어로 되어있더라구요~ 아메리카노랑 밀크티 마셨는데 둘다 맛있었습니다! 빵은 바삭함보다 꾸덕한 식감이 기대와는 조금 달랐지만.. 그래도 만족스러운 카페였어요', 180, 85, 'GOOD', SYSTIMESTAMP);
