INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '커피 사진을 안찍었네요. 디카페인 커피에 오트밀크까지 캐리해서 좋았어요. 조용했고 깔끔해서 작업하거나 책읽고 싶을 때들려도 좋을 것 같아요.', 41, 3, 'GOOD', SYSTIMESTAMP);
