INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '오버트 약수점만 이용하다가 합정점은 처음 방문했어요!! 플랫화이트는 역시 너무 맛있었어요 카페는 생각보다 작지만 그래도 좋아요!! (너무 시끄러운 분들이 오시면 울리는게 단점)', 38, 5, NULL, SYSTIMESTAMP);
