INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '커피 디저트 모두 꿀맛이었던 오버트합정 𖤐 메뉴판부터 맛집 냄새가 솔솔나서 주문했는데 역시나 직감이 맞아부러따 ٩(ˊᗜˋ)و 뷔릴레커피가 너무 먹고싶었는데 아쉽게도 테이크아웃은 안돼서 크림커피 바닐라로 시켰는데 와.. 보통은 크림 커피 분리되어 있어서 빨대 움직이면서 먹어도 살짝 따로노는 느낌 나는데 여긴 아님 너무 시원하고 고소하고 달달함 이건 한번 더 무조건 먹으러 와야할 맛임 !! 디저트도 진짜 괜차늠 크루아상 쇼콜라 에그타르트 다 먹어봤는데 빵잘알이 인정한 꿀맛이었음 특히 크루아상 결대로 찢어지는게 완벽.. 테이크아웃 했더니 저렇게 뚜껑에 귀엽게 써주셨다 ෆ', 0, 9, 'GOOD', SYSTIMESTAMP);
