INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '오전 8시부터 밤 10시까지 꽤 오래 운영하구 노트북으로 과제하기 편해서 좋아요! 아메리카노도 리필가능하고 커피맛도 좋습니다! ☺️', 34, 9, 'GOOD', SYSTIMESTAMP);
