INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '합정에 생겼길래 너무 반가웠어요 크로아상 위에 크림이 진쨔 넘넘 맛있어요ㅠㅠㅠㅠㅠㅠ 가오픈 중이었는데 나중에 재방문의사 백프로!!', 45, 2, 'GOOD', SYSTIMESTAMP);
