INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오타쿠카페로 방문했는데 분위기가 chill하고 좋네요...🩵🩷 잘 즐기다 갑니다. 생각보다 콜드브루 커피와 쿠키도 맛있었어요😊', 28, 2, 'GOOD', SYSTIMESTAMP);
