INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '여기 커피 맛집 스팀 맛집이에요 그래서 핫라떼, 핫초코 모두 맛있어요 👍🏻 원두도 엔트러사이트 원두 사용하더라구요. 조용한 분위기어서 담소 나누기도 좋고 주변에 작업 하시는 분들도 많더라구요. 편안하게 커피 즐기다가기 좋아서 애정하는 카페입니다~', 17, 3, 'GOOD', SYSTIMESTAMP);
