INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '집 근처라 지나가다가 크리스마스 트리보고 우연히 들어갔는데 분위기 맛집 찾은 느낌!! 타이밍 좋게 다른 손님분들 들어오기 전에 사진 많이 찍었네용ㅎㅎ 아메리카노는 사진을 못찍었지만ㅠ 고소하고 깔끔하게 맛있었어요! 이거 쓰면서 예전 리뷰 보니까 박스테이블만 있어서 불편하다고 되어있던데 제가 갔을땐 대형테이블이랑 2인 테이블들이 많았고 자리마다 콘센트가 다 있어서 노트북이나 아이패드 작업하기 좋아보였어요! 시끄럽지도 않고 테이블 많고 커피맛있구 = 그림쟁이들에겐 최고의 카페...굿굿 앗 그리구 테이블마다 무드등? 전구? 너무 귀엽습니다 ㅋㅋㅋ! 커피 마시면서 그림그리러 자주 올거같아요~~❤️❤️', 40, 8, 'GOOD', SYSTIMESTAMP);
