INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '작업할만한 공간찾다가 우연히 들렸는데 직원분들도 친절하시고 디저트도 맛있네요 콘센트도 많고 테이블도 편해서 작업하기 좋았습니다 다음에 또 들릴게요 !👍🏻', 342, 49, 'GOOD', SYSTIMESTAMP);
