INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '올해 첫눈을 맞으며 합정에 분위기있는 카페가 있어서 와봤는데 맛도 너무좋고 인테리어가 너무 이뻐서 사진찍기도 좋네요! 분위기있는 음악과 느낌있는 커피와 디저트,, 추천입니다!!', 36, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '일단  공간이  넓어요  조용하고  커피는  재  입맛에는  스*벅스보다  맛나요 ^^  인테리어  깔끔해서  사진  잘나와요  요즘  🌲 도  이쁘네요 ^^', 2, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '서교동에서 편안하게있을만한 카페를 못찾았었는데 분위기도 아늑하고 커피도 맛있어서 너무 좋았어요! 원두도 종류별로 맛볼수있어서 좋았어요 저는 산미있는게 좋아서 파블로 네루다 마시고 친구는 히스토리 미스터리 마셨어요 테린느 처음먹어봤는데 맛있네요 다음에도 또 방문할게요', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '깔끔하고 정갈한 인테리어가 인상적인데. 테이블이 박스형이라.. 노트북으로 작업할때 너무 불편함. 책 읽기도 불편함.ㅠㅠ 그냥 조용히 커피만 즐긴다면 조용해서 좋을듯. 넓고 쾌적', 58, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '여자 화장실을 남성분이 사용하시네요. 남자 화장실이랑 여자 화장실이 다른 층에 있고 비밀번호도 다 다른데 여자 화장실에서 남성분이 나오더라고요? 화장실에 카메라도 설치한 건 아닐까 불안하더라고요. 남여 화장실 비밀번호도 다른데 굳이 여자 화장실 비밀번호를 보고 여자 화장실에 들어온 게 소름 돋고 불편했어요.', 72, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '와이파이 연결이 안되네요 직원 문의하니 원래 불안정 하다고 합니다 여기 온 이유가 노트북으로 업무보러 왔는데 인터넷 연결 안되니 황당하네요. 업무나 인터넷 연결 중요한 분들에게 추천할 곳은 못되는 것 같습니다. 직원분은 잘못 없어서 더 모라고 하진 않았고 매장관리 이런식으로 하지 마시길 바랍니다 한국인 뿐 아니라 외국인들도 많이 오는데 개선 부탁드립니다.', 308, 51, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '매장이 그렇게 바쁜것도 아니었습니다 제가 음료 포장을 했는데 영수증 출력을 안했습니다 화장실 비밀번호가 영수증에 있는줄 모르고요. 그리고 나중에 비밀번호를 물어봤는데 짜증스럽게 응대를 하더라구요. 매장교육을 이런 식으로 하나요?', 0, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '화장실이 너무 더러워요 화장지도 자주없고 세면대쪽은 아예 청소를 안하는지 물때와 곰팡이가 막 있고 바닥도 곰팡이 군데군데. 그냥 쓰레기 청소만 하는듯. 환기도 안되서 곰팡이가 더 많나봐요. 화장실 바닥이랑 세면대 변기 등 깨끗하게 청소 좀 하세요.', 30, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '매장이 넓어서 옆 사람들의 대화가 신경 쓰이지 않아 너무 좋아요. 창 밖으로 거리가 보여 좋네요. 화장실 비번은 없었으면 더 좋을 듯 합니다.', 42, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '2.3.4층이 할리스매장인데 4층이 뷰가 젤  좋긴합니다. 근데 좀 덜시원해요. 앱에서 복합결제가 안되서 직원분께 문의하니  포스에서 해결해주셨어요. 친절한 응대  감사합니당~', 0, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '알바생 교육좀 똑바로 시키세요; 물티슈 달라 부탁했는데 말 안하고 손짓으로 옆으로 가라하고 빨대 하나 더 달라했더니 눈 똑바로 쳐다보면서 빨대 툭 던져주는데ㅋㅋㅋㅋㅋ 외국인 손님도 많은 곳인데 교육 좀 똑바로 시키세요 같은 한국인으로서 부끄럽네요 웬만하면 이런 리뷰 안다는데 공익을 위해 답니다 삭제하거나 블라인드 처리 하면 소비자 보호법으로 신고합니다', 23, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '할리스~블랙 아리아 마시며 힐링중 영수증 출력없이 카톡으로 주문 확인 했는데 ㅜ 화장실 비번  직원에게 물어 보니 넘 불친절하게 영수증에세 보라고  짜증스럽게  말해서 무안 했어요  ㅜ바쁜 시간도 아니어서 .....뷰좋고 다 줗은데 ......여튼 힐링 하고 갑니다.', 50, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '청소안되어있고 주문전 화장실 비번 절대 안알려줌(일행이 있어서 조금후 주문하겠다고 하는데도…) 결국 하나 먼저 주문하고 화장실 비번 받고, 일행꺼 추후 주문. 유도리 없고 딴데보다 맛도 없음', 8, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '대기자도 없었는데 아메리카노를 12분지나서 받아보기는 처음이네요. 그리고 표면장력 테스트 하는것도 아니고 커피를 너무 가득넣으셔서 가져가면서 다 흘렸습니다…일하면서 핸드폰을 아예 안할수는 없겠지만 일할땐 일에만 집중해주셨으면 합니다.', 15, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '2층과 3층이 있는데 역시 주말이나 공휴일에는 자리 잡기가 힘듦... 키오스크로 빠르게 주문은 가능하나 사람이 많아서 메뉴 나오는데는 시간이 좀 걸림. 점원분들은 힘들실텐데도 모두 친절해서 좋음!', 105, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '개인일정 끝나고 커피 마시러 들렸는데 다행히 사람 없을시간대에 와서 책 읽다가 쉬는데 점심 지나니까 번화가라 그런지 사람이 금방 많아짐 오늘은 바닐라딜라이트 조졌음 ㅋ ㅋ', 24, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '근처 놀러왔다가 잠시 쉬고 싶어 들른 할리스♡ 2,3층에 위치해서 한적하고 깨끗해요! 3층은 에어컨도 꺼두고 2층으로만 손님이 모이게 해놨더라고요 그래서 더 정리가 잘되는 느낌. 테이블 간격도 넓고 쉬다가기 좋아요 커피도 맛있었어요', 130, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '주말에 노답- 직원이 넘 부족한건지. 외국인들도 많은데. 다 먹음 음료 치우지도 않도 한가득에 음료 오래걸림. 매장입구에 얼음컵 쏟아진것 몇시간 방치. 그나마 화장실은 양호했음.', 53, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '주문이 밀려있던 것도 아닌데 아메리카노 두잔 나오는게 진짜 쥰~~~~~~~내 오래 걸렸구요 알바생은 많은데 농땡이 치는거 다 보이구요 아메리카노 연하게 타달라고 포스기에 찍었는데 안해주셔서 그냥 “제가” 물타서 연하게 마셨습니다 ㅋㅋ 이렇게 모든게 별로인데는 첨이네용ㅋㅅㅋ 그래도 나름 프렌차이즌데 ㅋㅅㅋ', 4, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '연트럴파크점이라고 영수증에 뜨네요.  3층 건물에 밖이 시원하게 보이는 할리스.   좌석도 특이하게 모여 앉게 해두었어요. 공부하는 사람도 많고 모임하는 사람들도 많고 자유로운 분위기. 애플망고 치즈케이크 빙수에는 코코낫이 바삭바삭 들어 있어 맛나네요.', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '새로 출시된 아리아 딥라떼 강추입니다. 입안에 맴도는 커피향이 너무 좋아요. 라떼인데 바디감이 느껴집니다. 아리아 아메리카노도 좋은데 딥라떼는 더 맛있네요.', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '1인 망고빙수를  2개 시켰는데  두개 양이  보기에도  차이가  난다고 하니  무게 재서 한다고 하는 말뿐... 참  여러곳  망고빙수를 먹어봤지만 참  어설픈  망고빙수였네요 두번은 먹으러  안갈듯 ...', 111, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '연트럴파크를 바라보며 마시는 커피 너무 좋아여. 날씨까지 완벽하네요🤩🤩🤩 프리미엄 아메리카노 주문했는데 적당한 산미가 있어요.', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '실망스러운 점이 있어 리뷰 남깁니다. 6월 28일 늦은시간에 할리스 홍대거리점을 방문하였습니다. 키오스크 주문을 통하여 10시 정각에 커피와 티를 주문하였고 몇분 뒤 음료를 받고 3층에 앉았습니다. 그런데 10시 8분경 점원분께서 올라오셔서 매장이 10시 30분에 문을 닫는다는 말씀을 하셨고, 잠시 뒤 10시 15분에는 이제 테이블을 치워달라고 말씀을 하셨습니다. 매장 운영시간이 30분밖에 남지 않았는데 키오스크에도 해당 정보가 뜨지않았고, 주문을 하고 음료를 받는 순간까지 어떤 점원분도 저희에게 이를 고지하여주시지 않아 이해가되지 않았습니다. 또한, 매장 이용시간이 적지만 남았음에도 일찍 테이블을 비워달라고 말씀하셔서 많이 불편한 매장이용이었습니다. 이런 일이 번복되지 않았으면합니다.', 14, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '뷰 좋은곳에 자리잡은 할리스! 매장도넓고 크고 청결해서 자주자주 들리는 곳이에요ㅎㅎ디카페인커피도 할리스가 제일 무난한거 같아용', 7, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '연남 할리스 처음 오는데요 좌석도 편하고 의자도 푹신한게 사람들 떠드는소리도 크게안들려서 좋아요 한라봉 티도 적당히달고 좋습니다', 117, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '할리스 쿠폰있어서 들렸는데 매장도 크고 깔끔하고 좋아요~ 무엇보다 화장실도 남녀별로 층 나눠져있구 여자화장실도 2개인데 따로 1개씩있어서 개꿀^,^🌟🌟 커피랑 디저트도 맛있네용~~! 홍대 오면 자주 이용할게요🙌🙌', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '2층 테라스 너무 이쁘고 앉고 싶었는데 사람이 너무 많아서 테이크아웃하고 앞에있는 공원 벤치에서 마셨어요 담엔 테라스 꼭 앉아보고싶당...', 62, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '매장은 안친절해요 ㅎㅎ 그럴수밖에 없는게 그 넓은 매장에 직원 1명 있어요.. 키오스크로 주문해야합니다. 케익은 맛있었어요~ 기본 딸기 케이크 추천합니다', 71, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '홍대문화예술관광특구 모뉴먼트 옆에 자리한 할리스 대형점. 2~4층 모두 할리스라 좌석 정말 여유로워요. 사람 피해가며 걸어야 하는 바깥 세상과는 다른 이세계의 기분이라 좋아요..', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '사람이 많아서 음료가 밀린 건 어느정도 이해하는데 카페 모카 위의 휘핑이 다 녹아서 흐드러질 때까지 방치한 건 조금... 주문받은 순서대로 받는 거 아니었나요? 왜 커피 먼저 만들어서 다 망쳐놓는지...ㅠㅠ', 47, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '사람 개많고 알바 완전 힘들어 보였어요. 매장 크기에 비해 알바생 수가 적어서 화장실이랑 매장 관리가 거의 안 되는 느낌.. 음료랑 케이크는 맛있었습니다.', 14, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여기 매니저님인지 그냥 직원인지 모르겠는데 유니폼에 명찰도 없고 너무 불친절하네요. 키오스트 주문이 주라고 해도, 현금결제 하려고 포스기 앞에 서있는데 … 손님이 있는지 없는지 신경도 안쓰고, 주문 받는데 어떤 음료요~? 이러고 ㅋㅋㅋ 뜨거운 음료 트레이에 올려주지도 않고요. 매장에 지인이 방문했는지 큰소리로 박장대소 하고..ㅋㅋ.. 저뿐만 아니라 다른 손님한테도 (무슨 문제인지 모르겠지만) 훈계하는 듯한 말투로 다음엔 안된다 어쩐다.. 듣고 있는 내내 불편하네요.. 기본적인 서비스가 안되어있습니다..', 14, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '2층부터 4층까지 알바 1명이 다 책임져야하는 시스템이니, 주문도 빠르게 못돌아가고, 쓴컵은 안치운채 그대로있고, 화장실청소도 안되어있고. 악덕사장 그 자체입니다. 가지마세요', 10, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '바빠서 음료를 30분 후에 찾앗는데 다 녹앗다며 남자 담당자분께서 다시 만들어주셨어요 ㅠㅠ 바쁘신 와중에 괜찮다고 했는데도 ㅠ ㅠ 너무 감사합니다', 9, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대 돌아댕기다가 다리가 너뮤 아파서 구냥 우연히 들어갔는데 매장도 크고 넘 좋아요 ㅎㅎ 창가자리 앉아서 밖에 구경하면서 맛난 아아 먹으며 쉬니까 천국이었어용 ㅎㅎ', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '매장직원이  매장에서 판매안되는 메뉴가 키오스크에서 주문되는지 안되는지도 모르고 있네요 물어보고까지 주문했는데 없다고해서 다시 주문하고 직원교육이 미흡한듯...', 8, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '오늘 들렀던 음식점과 가까이 있어서 갔는데 코로나 때문에 좌석은 3, 4층만 운영되고 있어요. 모처럼 지인들과 대화 즐겁게 잘~ 나누다 갑니다^~^ 그리고 3층 추워서 말씀드렸더니 바로 히터 하나 더 켜주셨어요ㅋ 여러분 추위에 떨지 마세요!', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '매장은 괜찮은데 직원분이 화장실 물을때 주문할때 눈한번 마주쳐지지않을정도로 썰렁하고 나온 음료는 물론 진동벨 울려갔지만 덩그러니 놓여있고 직원은 저멀리 반대편에서 자기일만. 음료들고오니 내가 놓은 진동벨만 덩그러니.  로봇같았음.', 9, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '알바가 너무 예의와 서비스가 별로네요  평일 오후 여자 알바생 이었는데 주문하려고 카운터 앞에 갔는데 응대도 없고 귀찮은듯이 응대하고 커피 다 만들고 진동벨 받지도 않고 커텐뒤에 앉아서 핸드폰하면서 커피마시고 있더라고요 교육 부탁드립니다 기분이 매우 언짢네요', 15, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '프렌차이즈 커피 중 할리스 커피를 제일 좋아해요. 단 홍대거리점은 3개의 층으로 되어있는데, 2•3층 좌석이 좁고 다닥다닥 붙어있는 느낌이라 불편해요.', 85, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대거리점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '커피랑 케익은 잘먹었습니다. 하지만 알바생 교육 좀 다시하시죠. 금일14:55이용했네요. 주문받는데 잘 안시켜본 음료라 버벅대면서 옆에 남자친구거 물어보고 민트초코할리치노 말했는데 대뜸 음료 사이즈 말해줘야한다면서 버벅거리니까 말끊고 휘핑올리냐고 묻는데..가르치세요?  기분나빠서..커피는 저 멤버쉽있어서 사이즈업했는데 아니 그런건 주문받을때 손님한테 먼저 물어봐야하는거 아닌가요? 교육생같던데요? 오랜만에 할리스가서 기분망치고 왔어요. 단골아닌이상 민트초코할리치노에 휘핑빼고 주시고요, 바닐라딜라이트 아이스 작은사이즈에 저 맴버쉽있어서 그란데로 사이즈업해 주세요라고 주문하지 못할수 있잖아요? 사이즈는 어떻게 해드릴까요 먼저 물어보는게 맞지 사이즈 말씀해주셔야거든요는 아니죠 그렇지 않나요?', 18, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '고민하다가 초코케이크로 골랐는데 초코가 엄청 진하고 엄청 달았어요,,^_ㅠ 그래도 디저트 맛있고 좌석도 많고 화장실도 깨끗해서 좋아하는 카페입니다ㅎㅎ', 270, 30, 'GOOD', SYSTIMESTAMP);
