INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '이곳의 장점은 일찍 문을 연다입니다 근처에 엄청 유명한 돈까스 집인 이츠야는 아침 9시부터 대기를 걸어놓을 수가 있어서 대기 이름 올리고 문연 카페 찾다가 왔는데 아까 이츠야 대기 걸어놓은 사람들 얼굴 보여서 ㅋㅋㅋㅋ 웃음이 나왔다는', 2, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '기본이 안되있음 ㅈㄴ불친절함 어떤걸로 드실래요?하고 작은거요했더니  어떤 맛이요?하면서 짜증 ㅈㄴ 나는 표정으로 고객을 노려봄ㅋㅋㅋ  처음오는 고객이 어떤 것이 맛인지 사이즈인지 어떻게암ㅋㅋㅋ 글씨는 콩알만하게 써놓고 알바인지 사장 아줌마인지 모르겠는데 기본부터 배워야할듯;;;;', 30, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '드롭탑 홍대점의 겨울 신메뉴 - 따뜻한 겨울간식: 드롭탑의 겨울 메뉴는 따뜻한 간식으로, 특히 겨울철에 어울리는 다양한 옵션이 있습니다. 이곳의 간식은 맛뿐만 아니라 비주얼도 훌륭하여, 먹기 전에 사진을 찍고 싶어지는 매력이 있습니다 [1]. - 뱅쇼 밤밀크티: 뱅쇼는 풍미 깊은 레드와인에 달콤한 과일과 캐모마일 티가 조화롭게 어우러진 음료입니다. 이 음료는 논알콜로 제공되어, 누구나 부담 없이 즐길 수 있습니다 [3]. 방문 경험 - 분위기: 드롭탑 홍대점은 아늑하고 편안한 분위기로, 친구들과 함께 오기 좋은 장소입니다. 특히 겨울철에는 따뜻한 음료와 함께하는 시간이 더욱 특별하게 느껴집니다. - 서비스: 직원들은 친절하고, 메뉴에 대한 설명도 잘 해주어 선택하는 데 큰 도움이 되었습니다.', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '22:30에 2층 마감이라고 안내해서 다들 짐 싸서 내려가는 중에 불 꺼버리고 짐 가지러 올라갔는데 깜깜해서 플래쉬 켜고 가방 찾아왔네요… 1층 내려와서 자리 음료 쏟아져있어서 닦아 달랬더니 잠시만요 하고 끝까지 안 닦아주시고 제가 닦았는데 알바생인지 직원인지 너무 불친절하신 거 같아요 개선 부탁드립니다', 50, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '수박유자크러쉬3, 수박주스1 주문했어요 4명이서 수박류만 시키는 광기 ㅋㅋ 크러쉬는 어릴때 먹던 슬러시처럼 머리기 띵~하는 맛 ㅋㅋ 더운데 열도 식히고 맛나게 먹었어요 ㅎ', 118, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '아이와 같이 와서 저는 미리 주문 하려고 했었고 친구가 아이 데리고 화장실 가려고 했는데 직원이 불친절 하게 설명해 줘서 기분 좋게 왔었는데 기분이 별로네요~', 19, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '매장은 너무 쾌적하고 좋았는데..ㅠㅠㅠㅠ 직원분들이 너무 일하기 싫으신 티를 너무 내셔서 좀 안좋았어요 기분이.. 다른 직원분 일하실때 다시 올게요', 68, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '주말에 걷고 걷고 걷다가 겨우 발견한 카페..ㅎㅎ 위치가 좀 번화가와는 떨어져 있어서 그런가 사람들이 많이 없었어요~ 안 쪽 자리는 에어컨 빵빵 더운 날에 더위 식히기 좋았어요. 남편이 음료를 쏟는 바람에 직원분들 고생시켜서 죄송했습니다! ㅠㅠ', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '더운날 마실 것을 찾아 카페에 왔는데 막 “친절하지는 않음. ” 카페 분위기는 좋음, 그렇지만 종업원의 태도가 불친절 하면 사실 앉는 순간부터 나갈 때까지 기분이 안좋았음. 오늘 기분이 안좋으신지 모르겠지만 좀 더 기분 좋게 대해주셨으면 했음.', 3, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '처음 이용하는 매장인데 체인이겠죠? 더운데 문 다 열려 있고.. 딸기 생크림 케익이 딸기쨈 생크림 케익이라 놀램.ㅋㅋ 식빵 사서 딸기땜 바르고 생크림 덮으면 될걸...ㅎㅎ', 46, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '제가 홍대가 일터인지라 드롭탑 다닌지도 몇년 됐는데요 이번에 초저녁에 알바로 50대 중반으로 보이는 어딘가 안색어두운 단발머리 마른 아줌마가 새로 오셨나봐요(원래 계신 어머님 두분 아님) 기존 젊은 알바생분이 옆에서 일 알려주시더라구요 (근데 알려주는데 대답도안하고 기존 알바생분 뒤돌으니까 표정 살벌해져서 째려보던데요..) 문제는 제가 평소처럼 커피마시러 방문했는데 들어가자마자 인사도없이 위아래로 저를 훑어보더니 카드를 휙 뺏어가듯이 가져가고, 대답도 무시하고 정말 이런적 처음이라 굉장히 불쾌했네요 .. 무슨 안좋은일이 있는지; 그걸 왜 밖에 타인한테 표출하세요 아줌마ㅠ 홍대만 아니었어도 저도 참는성격이 아니여서 폭발했을거에요.. 기본적인 예의좀 지키세요 제발', 13, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '올 때마다 중년 여자분 빼고는 단 한번도 친절한 적 없는 곳 어쩜 모든 알바들이 웃으면서 응대하는 법이 없네요 몇년째 한달에 10회정도는 어쩔수없이 오는 곳인데 참 .. 직원교육이 시급한듯 합니다 탈색머리 통통뚱뚱한 여자분 늘 일하기 귀찮은 표정에 오늘은 하다하다 다른 여자 알바까지 제가 친구도 아니고 “ 먹고가요? ” 이러고 있네요 .. 저도 알바 안 해본 거 아닌데 손님한테 먹고 가요? 라고 하는 경우는 처음이네요', 41, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '직원분들이 일하기 싫어하세요ㅋㅋㅋㅋㅋ 허니브레드 크림이 이렇게 납작한거는 처음보네요ㅎㅎㅎ 음료는 밍밍하고 빵은 달기만 해요~ 직원분이 아이스랑 핫 구분 못하시고 음료 다 쏟으면서 주십니다ㅎㅎㅎ', 15, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '10여년 전에 근처에.사무실이 있었을때 자주애용했었는데 여전히 그 자리에 있어서 반가웠어요. 커피도 그대로네요. 잘 쉬다.갑니다.', 124, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '애들은 탕후루 사주고 어른들은 커피한잔ㄱㄱㄱ 지나다가 조용한 곳 에서 커피한잔 했습니다. 커피맛 좋았고 1시간동안 잘 쉬다 갑니다^^', 86, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '사람이 정말 정말 많아요! 그런데 음식은 꽤 빨리 나오고 커피가 굉장히 고소해요! 출출해서 시켜본 쿠키가 의외로 너무 맛있어서 기분이 너무 좋았답니당! 알바생 분들,, 정말 빡세보이시던데,, 힘내세용', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '오전 11시에 하루가 시작되는 홍대에서 가장 부지런하게 오전 9시에 문여는 카페입니다 :) 조용하고 아늑하고 넓은 이층 넘넘 좋아용~~', 25, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대 갔다가 너무 지쳐서 쉼이 필요할때 보인 드랍탑^^ 넘 맛있져여!!! 팥빙수 맛집! 입니다^^ 동네에 드랍탑 없어서 이용 못해봤는데.. 홍대 드랍탑만 맛있는걸 까요?! 믿고 갈 수 있는 드랍탑!!!^^ 아이스아메도 독특하고 깔끔! 넘 맛있더라구요! 넘 맛나고 예뻐서 팥빙수 사진만 남겼네용;^^ 팥빙수 추천!!!', 1, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '스트레스 받는 일이 있어서 심야영화 보고 홍대로 넘어갔는데 저는 술을 안 마셔서 마땅한 곳 찾기가 진짜 힘들었거든요 근데 여기 제가 갔을때는 24시간 영업이었고 부부 두분이 운영하시는것 같던데 친절하셔서 좀 오래 머물다 갔어요ㅎㅎ 이곳 위치는 기억해둬서 다음엔 친구랑도 한번 방문하고싶어요ㅎ', 60, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '와... 오랜만에 방문했는데 매장 노래가 왜 이상한 노래들만 나오죠 불과 반년전엔 힙하고 좋은 노래들 많이 나왔는데 도저히 들어줄 수가 없어서 나왔어요 처음들어보는 한국 남자 밴드? 카더가x같은 대중적인 가수도 물론 나오는데 무슨 이상한 노래들을 자꾸 틀어줘서 머무는 내내 스트레스 받았어요 솔직히 말하자면 믹스가 너무 구려요 그래서 귀가 확 피로해져요 제발 예전 플리로 돌아와주시면 안될까요... 거의 매일 왔었는데 ...', 101, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '매장이 정말 넓고, 음악도 잔잔하고 조용하게 깔려서 좋아요 시간도 늦게까지해서 10시되서 허겁지겁 나갈필요가 없어서 참 좋습니다 :) 커피랑 음료도 너무 비싸지 않고 좋네요 :)', 74, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '앙버터쉐이크는 편의점 파란색 팥빙수컵 맛인데, 팥을 오래된 걸 쓰는지 인삼맛이 났어요.... 매우 비추합니다. 아포가토도 아이스크림이 고깃집 아이스크림 같아서 아쉬웠습니다. ㅠㅠㅠ', 14, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '22일 토요일 새벽 근무하시던 뉴에라 네이비 볼캡 쓰신 여성 알바분은 올 때마다 너무 불친절하시네요 손님들한테 인사 안 하는 건 너무 당연하고 새벽시간대라 피곤하실 건 알지만 주문하면 정말 귀찮아 죽겠다는듯한 표정으로 대답도 없이 툭툭 포스찍고 주문하는 사람이 오히려 눈치를 보게 만드는 재주가 있습니다 처음엔 그 날 하루만 그러신 줄 알았는데 올 때마다 그러시네요', 50, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '좌석이 편해서 오래 대화 나눌 수 있어서 좋아요 2충 창문이 다 열려있었는데 담배 냄새가 계속 올라와서 그 점은 불편했습니다 ㅠ', 30, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '돈주고 사먹는데 직원분 말투때매 기분 팍상했네요 일하기싫으신거 같은데요.. 화장실비번 한번더 물어봤다가 혼났네요ㅜ 옆에 있는 친구도 느낄정도..', 27, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '공영주차장 바로앞 카페라 딸아이 화장실 갈겸 아이스커피한잔 테이크아웃으로 사로갔어요  알바남자분이 피곤하신지 츤데레스탈이신가...^^? 접근성좋은카페자리는 맞아요 직원분들도 친절함이 좀 보이면 좋을거같다는생각하며 나왔네요', 97, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '공영주차장이 바로 앞에 있어서 주차하고  곧장 올라왔어요 자몽에이드가 맛있고 친구들과 얘기나누기 좋았어요 화장실도 넓고 깨끗했어요', 40, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '딥초콜릿카페라떼 시켰는데 밑에 시럽이 초록색이라서 뭐지?하고 섞어서 마셨는데 무슨 레몬맛이 나서 초코라떼 맞냐고 물어보니까 블루레몬시럽?이 들어간다고 설명해주시는데 그러면 사전에 레몬시럽이 들어간다고 설명해주셔야하는게 아닌지... 초콜릿맛은 잘 안나고 레몬맛만 나네요 메뉴도 네이버엔 (블랙)이라고 되어있는데 매장 메뉴판엔 블랙이라고 써있지도 않아서 당황스러웠네요', 56, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '친절하지 않습니다. 밤12시에 방문했는데 그시간에 일하시는 여자분 알바인지 직원인지 모르겠지만 저만 느낀게 아니라 옆에 있던 일행까지 느꼈네요 일하기 싫으신거 같은 느낌을요.', 10, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '빵도 쫄깃하게맛있고 크로플? 도 은은하게 달달하고 커피도 너무 쓰거나 신맛이나지 않아서 좋았습니다 아침 일찍 오픈하니 그 근처 볼일있을때 아침에 커피랑 빵으로 먹기 좋았네요! : )', 39, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '스트로베리포레누아는 마치 며칠동안 안팔렸던걸 먹은것처럼 퍽퍽하고 오래된 느낌이었음 ㅠ 한입씩 먹고 다 남겼는데.. 다른디저트 먹을걸 그랬나봐요..  매장은 크고 깔끔하고 좌석도 편하고 시원해서 좋았음', 55, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '매장이 2층까지 있고 굉장히 넓어서 대화하기 편한 곳입니다! 테라스도 있어서 시원한 바람도 만끽하며 휴식을 취할 수 있어요 선셋에이드 먹었는데 맛있게 당 충전 했습니당👍👍', 2, 0, 'GOOD', SYSTIMESTAMP);
