INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '드롭탑 케익 좋아해서 드롭탑 자주오는데 홍대점 매장 티 멤버쉽 할인 가능했는데 갑자기 안된다고 하네요 그리고 친절함이 조금 부족하네요', 37, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '선물받았는데 체리코코 1호 너무 예뻤고, 보냉백 추가하니까 여름인데도 상태가 오래 유지됐어요! 평소엔 조각 케이크만 먹었는데 홀케이크도 만족스럽네요.. 초콜릿 무스가 엄청 진하고 꾸덕했고 체리도 신선한 맛이었습니다!🍒💫✨️(초는 따로 구매한 거였습니다..!)', 71, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '한강 나들이를 가려는데 신메뉴가 마침 나왔길래 냅다 예약했습니다... 역시 기대를 저버리지않는 슬릿 케이크...ㅠㅠㅠ 산딸기 상큼! 한데 묵직 달콤한 피스타치오 크림이랑 쫀득하게 느껴지는 피스타치오 시트가... 정말 엄청났습니다... 너무 묵직한가? 싶으면 또 산딸기가 상콤달달하게 씹히고 크림이 너무너무 맛있었어요ㅠ... 나들이는 핑계고 사실 슬릿 신상 다같이 먹으려고 만남...ㅠ 맨날 여기 케이크 먹으려고 모임잡고 운동합니다... 뺀만큼 슬릿 케이크로 채우기.', 48, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '요거트망고복숭아케익인가 먹었는데 너무 맛있었어요.. 동물성 크림 최고ㅠㅠ 토마토바질에이드 먹었는데 이또한 맛있었음!!!!! 화장실 1개, 협소하고 불편하고 좌석은 아쉬워용', 7, 3, 'BAD', SYSTIMESTAMP);
