INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '세명이서 음료 3잔 케이크2개 먹었는데 너무 맛나서 케이크 2개 커피2잔 더 시켜먹었어요😊 케이크.. 복숭아 멜론 무화과 토핑 당연히 다 너무 맛났구요 속빵이랑 크림들도 좋은 재료 쓰시는지 아주 그냥 입에서 살살 녹아요 😭😭😭😭  그리고 커피도 산미가 있으면서도 고소하면서도 미묘한게 또 너무 맛나더라구요!! 강추합니다! 사장님도 넘이쁘고 바리스타 선생님도 너무 멋져요! 매번 잘있다 갑니다. 재방문의사 만퍼센트에요 ㅋㅋㅋㅋ 많은사람들에게 추천해주고프네요 🥰 아참 테린느도 강추에요!!', 18, 9, 'GOOD', SYSTIMESTAMP);
