INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '카페 인테리어가 심플한데 멋스러워요 커피도 맛있고 조각케익 종류도 많은데 맛있어요 메론케익 진짜 과일이 많이 들어가있네요 다른 케익도 종류별로 먹어보고 싶어요 ㅠㅠ 다음에  또 오겠습니당!!', 34, 2, 'GOOD', SYSTIMESTAMP);
