INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '맘 같아서는 케이크 종류별로 다 먹어보고 싶었는데 꾹 참고 하나만 먹었어요,, 넘무 맛도릥,,, 슬릿 케이크 도장깨기 하러 가야징,,, 심지어 커피도! 티도! 너무 맛있어요🥹', 12, 4, 'GOOD', SYSTIMESTAMP);
