INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '밖에서는 몰랐는데 매장이 안쪽까지 있어서 넓더라구요? 인테리어듀 예뻐서 좋았어요 앞쪽좌석은 그리편하지 않았지만 음료는 맛있었어요. 근데 직원분들이 친절하진 않네욥', 14, 5, NULL, SYSTIMESTAMP);
