INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '설화로즈 체리코코에 아이스커피로 골랐습니당 설화로즈는 원래 유명했는데 이번에 약간 바뀌면서 크기도 재료양도 더 늘었고 맛도 더 은은하게(?) 좋아진 느낌이에요..🫶🏻 요즘 케이크샵들 버터케이크도 비싼값에 제작해서 조금 아쉬웠는데 재료 아끼지않는 맛있는 케이크 맛보니 값이 전혀 아깝지 않아요.. 또 맛보러 갈 예정🍓🍰', 5, 10, 'GOOD', SYSTIMESTAMP);
