INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '주말 홍대 어디를 가도 사람이 많아 한참을 돌아다니다 발견한 카페. 모노톤한 인테리어에 조용한 분위기, 디저트까지 아주 만족스러웟어요🙂', 59, 12, 'GOOD', SYSTIMESTAMP);
