INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '제가 빵순이인데 원래 리뷰 귀찮아서 안올리는데 오늘 첨 먹어보고 진짜진짜 넘넘 맛있어서 리뷰 남겨요! 사진은 예쁘게 못찍었지만 산딸기와피스타치오케이크는 진짜 존맛, 피스타치오가 묵직할수 있는데 산딸기가 상큼하게 잘 잡아주고요 봄 꽃은 헤이즐넛 크림의 고소하고 달달한 맛이 금귤 상큼한 맛과 어울리면서 예쁘고 맛있고 다 해요, 둘 다 더워지는 요즘 날씨에 잘 먹을 수 있는 맛입니다! 원래 피스타치오류 들어간 케이크 좋아하는데 맛있는 곳 찾기 힘든 맛인지라 한입 먹자마자 대박 외치고 순삭했습니다ㅎ 가격이 저렴한 편은 아니지만 빵순이로써 싸고 맛없는 것보다 비싸고 맛있는거 먹자는 주의라 후회없는 맛이에요, 진짜 존맛이라 나만 알고 싶지만 장사가 잘돼야 가게도 오래가기 때문에,,^-^ 더 쓰고 싶은데 칸이모자라ㅠ', 58, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '추워서 들어간 카페였는데 생각보다 디저트들이 맛있어서 좋았어요! 딸기생크림케이크에 있는 딸기들도 다 신선했고 초코는 엄청 꾸덕해서 파베초콜릿보다 더 꾸덕한 초코를 먹는것 같았어요🫶 화장실도 깨끗하고 가게도 청결 했지만 안에있는 자리들이 너무 좁아서 옆테이블 분들과 밀첩한게 아쉬운것 같아요..ㅠ 그래도 직원분들도 멋있고 친절해서 또 가게될것 같아요ㅎㅎㅎ', 82, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '만년설 딸기로 만든 조각 케이크가 출시되어 방문했습니다. 가게 안이 생각보다 넓은 편인데 채광 좋은 좌석도 있고, 안쪽으로 들어가면 은은한 분위기의 어두운 조명이 있는 좌석들도 있습니다. 느끼하지 않으면서 달콤해서 물리지 않는 케이크를 좋아하는데 그런 느낌의 케이크였어요. 단 맛을 싫어하신다면 조금 달게 느껴질 수도 있을 것 같지만.. 건조 딸기의 상큼함이 달콤함을 약간 잡아줘 맛있게 드실 수 있을 것 같습니다.', 68, 15, 'GOOD', SYSTIMESTAMP);
