INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '와저는 디저트 덕후라 갔는데 커피 덕후인 친구가 그러는데 커피 머신도 엄청 비싼거라고 하더라구요. 진짜 커피도 디저트도 가격이 아깝지 않은 맛이에요. 인테리어도 매우 깔끔하고 고급 호텔에서 디저트 먹는 기분이였어요! 사장님? 점원분?도 정말 친절하시고 좋네요. 처음에 코 피어싱에 좀 겁먹었는데 매우 친절하게 응대해주셔서 제가 편견이 있었다는걸 깨달았어요', 8, 9, 'GOOD', SYSTIMESTAMP);
