INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '디저트 종류가 다 맛있고 세화로즈가 궁금해서 기대하고 갔었는데 품절이라 너무 아쉬웠어요😢 커피는 무난한 커피맛이었고 분위기가 힙하고 조용해서 좋았습니다❤', 19, 9, 'GOOD', SYSTIMESTAMP);
