INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '앞에 있는 우와 매장 기다리려고 들어갔는데 매장 분위기가 좋았어요. 식당 기다리려고 카페 이용하시는 분들이 많은거 같았어요ㅋㅋ', 52, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '디저트 맛집 티라미수 진짜 와… 🤦🏻‍♀️ 와중에 화장실도 세심하게 관리해 주시는 것 같았어요! 번창하세요 ❤️아, 인테리어 진짜… 너무 모던하고 고급져서 사진도 잘 찍고 갔습니다🌸🌸', 51, 15, 'GOOD', SYSTIMESTAMP);
