INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '인테리어가 깔끔하고 화장실이 일단 깨끗해서 마음에 듭니다. 그리고 여기 디저트 생각지도 못했는데 진짜 맛있네요..! 특히 에그타르트 강추', 106, 20, 'GOOD', SYSTIMESTAMP);
