INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '커피와 디저트는 맛있었지만 자리가 정말 많이 불편했습니다ㅠ 의자 자체가 불편하고, 일행과 나란히 앉아서 대화 나눠야 되는 구조라서 허리가 불편했습니다. 테이블 높이도 낮아서 디저트를 먹으려면 허리를 숙여 몸을 낮춰야 합니다. 이곳은 대화 짧게 나누고 헤어질 사람과 같이 가야 될 것 같아요. 그래도 매장 내 사람이 적다면 SNS 인증용 사진은 잘 나옵니다:)', 7, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '이번에 방문했더니 초코테린느 있길래 시켜봤는데 엄청 꾸덕꾸덕하고 찐-해요 존맛! 👍🏻 인테리어도 너무 멋있고 분위기도 좋은 곳 :)', 37, 3, 'GOOD', SYSTIMESTAMP);
