INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '오랜만에 서울 왔는데 역시 슬릿으로 이끌리듯 스르륵 하였어요 홍홍홍..♡ 최근 채식을 시작해서 최애 라떼 대신 오틀리라떼를 마셨습니다. 우유만큼 꼬숩지는 않지만 나름 맛있게 먹었어요.', 21, 6, 'GOOD', SYSTIMESTAMP);
