INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '집에서 가까우면 맨날 갈텐데 그저 아쉬울 따름... 커피맛이 내인생 탑쓰리 안에 들어감! 디저트마저 핵꿀맛!!! 카페 안에서 커피를 홀짝이고 있자면 아주 그냥 나도 덩달아 힙스터가 된 기분. 커피 한 잔에 힙스터라니. 꺄르륵~ 서울 갈때면 꼭 들르겠어요~~!!!', 4, 10, 'GOOD', SYSTIMESTAMP);
