INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '게이샤는 역시나,,👏 산미 안좋아하는 사람도 빠져드는 커피예요ㅜㅜ 게이샤 품종을 브루잉으로는 많이 봤었는데 아메리카노로는 처음봐서 매우 신기,,, 🫢 원두 고민됐는데 맛보기 해주시는것도 넘나 쵝오👍 나중에 고소한 원두 아메리카노도 먹어보고싶어요ㅎㅎ 피치브루랑 오렌지샷도 궁금해서 또 방문하려고용💓 커피러버에겐 넘나 행복,,,', 5, 3, 'GOOD', SYSTIMESTAMP);
