INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피가 정말 맛있어요. 사장님께서 커피에 대한 애정과 관심이 넘쳐 보이셔서 커피를 더 음미하며 먹을 수 있었어요. 입구 쪽에 드립 커피를 시음해 볼 수 있도록 비치해 두셨는데 원두에 대한 설명과 함께 직접 맛도 볼 수 있어서 좋아요. 다음에 가서 또 다른 커피를 마셔 보고 싶다는 생각이 들게 해 주는 매장 경험이었습니다!', 105, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '블루리본 카페라 샘플 원두 몇가지 시음코너도 있고 인테리어도 블랙&화이트로 깔끔해요. 2충 창가 테이블 자리 넘 좋네요. 차와 초코, 래몬티, 쿠키 다 맛있어요~', 78, 15, 'GOOD', SYSTIMESTAMP);
