INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '와...오늘 레드플렌트에서 커피가 뭔지 알아버렸네요. 그동안 그냥 커피만 먹고 다닌거네요 진짜 커피가 이런거구나..했어요 합정동에서 점심먹고 지나가다 들린곳인데, 최고의 선택이었네요 제가 오늘 마신건 레드커피 핫이었는데 처음 맛보는 맛과 향이었어요 보약마시는 느낌이랄까..한방울도 안남기고 다 마셨어요...조만간 다시 들릴게요 최고최고', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '커피의 특별한 매력이 있고 커피도 모르는 내가 먹어도 맛있어 좋았어요 2층에 조용한 자리도 있고 1층 2층 테라스도 있고 좋은 곳을 알았어요 커피에 대해 설명 해 주시는 것도 너무 좋았어요', 53, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '합정역 2번출구 나오면 안쪽 골목에 있는 레드플랜트 이층건물 인테리어 이쁜 커피가게 ☆☆ 저녁 육일집 들려서 저녁 식사후 저번에 망원시장 가면서 봐둔곳 생각나서 들려네요 RED PLANT 에스프레소 한잔 키호스크 애서 주문 했네요 커피는 중배전 고소한맛 주문 마셔 봤는데 진한 커피향 고소하고 맛나네요 ♡ 저녁에 커피한잔 생각나시면 근처에 오셨을때 한번 들려 보셔도 좋을듯요.. 음악 선곡이 커피가 당기는 잔잔한 Swing Jazz 커피&멍  멍때리기 최고 생각없이 커피n휴식 ♥♥ 에스프레소 doudle 5,400₩', 60, 16, 'GOOD', SYSTIMESTAMP);
