INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '직접 로스팅부터 하는 카페라 그런지 커피가 너무 맛있네요! 이번엔 특이한 게 궁금해서 사이공 마셨는데 다음엔 또 다른 메뉴를 마셔 보러 와야겠어요. 좌석이 많진 않아서 일단 2층 좌석부터 확보하고 1층 키오스크로 주문하시면 좋아요.', 7, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '합정에 잠깐 볼일이 있어서 가볍게 대화하려고 카페 들렀는데 의외로 분위기 좋아서 괜찮았어요~ 매장은 2층에만 좌석이 있는데 엄청 넓지는 않고 대화하는 사람들도 있고 노트북 작업하는 분들도 좀 있더라구요. 커피로 유명한 곳인데 저녁이라 저는 몽키바나나 한 잔 마시고 친구는 버터스카치 커피 마셨어요. 몽키바나나는 바나나+바닐라아이스크림 곱게 간 블렌디드인데 쫀득-찐득하니 헤비해서 맛있더라구요 ㅎㅎ 바나나 블렌드한 맛인데 바닐라 향이 조금씩 나서 괜찮았어요. 버터스카치는 약간 달고나커피처럼 카라멜커피 크림이 올라간 거였는데 유니크하고 맛있더라구여~', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
