INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '남녀 화장실 분리(1층 여자, 2층 남자), 1~4인 추천 6, 8인까지도 가능은 하나 테이블을 붙여앉거나 해야 함, 주차 불가능 커피는 맛있고 디저트 메뉴도 괜찮았어요 자리가 많지는 않지만 그래도 작지는 않아서 퇴근길같은 시간에는 넉넉히 앉을 수 있습니다  의자는 편한 거 반 인스타용 반이라 원하는 거 앉으면 될듯? 전체적으로 분위기도 좋고 커피도 맛있어서 다음에 또 들릴 의사 있습니다 다만 1층에서 2층으로 가는 계단은 조심해야 할 것 같아요 가파른데 높낮이가 일정하지 않아서 잘못하면 넘어질 수 있을 듯... 계단 폭도 좁은 편이라 한사람씩 올라가는 게 좋습니다', 77, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '이번에는 봄이니까(?) 아주아주 생각치 못한 조합으로 모험중입니다!! 근데 새롭네요~ 매번 느끼는거지만 마실때마다 신기방기한것이...이러다 단골되겠어욬ㅋㅋㅋㅋ 이미 단골일수도 있지만(?)!!요즘 엄청 그 맛이 생각남ㅋㅋ 아무튼 오늘도 감사드립니다^^', 27, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '합정역 근처 레드플랜트 ☕ 2층 구조라 계단이 꽤 가파르지만, 올라가면 조용하고 아늑한 분위기가 기다린다. 한쪽에는 다양한 원두가 진열되어 있고, 시음도 가능해서 커피 고르는 재미가 있음! 기본 라떼는 6,400원으로 저렴하진 않지만, 그만한 값어치 있음. 작년 KCRC 로스팅 대회 2등 수상한 사장님이 직접 셀렉한 커피들이라 믿고 마셔도 좋아요. 커피 좋아하는 사람이라면 꼭 한 번 들러봐야 할 곳!✨', 41, 1, 'GOOD', SYSTIMESTAMP);
