INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '저녁먹으러 가기전에 잠깐 들렀다가 테이크아웃했어요 당이떨어져서 오늘은 바닐라빈슈페너☕️ 달달하니 좋아욤 합정오면 꼭 들르는 커피맛집이에요 😎', 12, 1, 'GOOD', SYSTIMESTAMP);
