INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '진짜 미쳤어요 입안에서 커피가 춤을 춥니다 지인짜 맛있어요...... 커피가 살아있다 두유랑 잘 어우러져서 난리가 나네요 과장 없이 계속 들어가는 맛 근처살았음 통장 거덜났을 거 같네요 진짜 인생 라떼입니다 ㅠㅠ', 72, 17, 'GOOD', SYSTIMESTAMP);
