INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '간만에 왔어요. 커피맛은 여전히 좋아요.😋 레몬🍋티(맞는지 모르겠지만)는 너무 시큼한, 건강한 맛이었다고 해요. 대화하기는 좋았으나, 많은 사람들이 이용하니 좀 울리고 시끄러워요. 계단 위험하니 2층은 조심히 가셔야 해요.🤗', 27, 8, NULL, SYSTIMESTAMP);
