INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '너무 좋은 시간 보냈고 커피가 맛있었습니다. 예전부터 가보고 싶었는데 2025 KCRC 2등 했다는 소식을 접하고 드디어 방문했습니다. 산미 좋은 레드 오리진 에스프레소와 파나마 파카마라 브루잉 다 좋았습니다. 2층 매장이라 넓어서 작업하기 좋고 브루잉 바는 없지만 1층에 앉으면 대표님과 대화도 나눌 수 있습니다. (대표님이 계시고 여유로울 때만) 로링 로스터기를 사용했고 시네소 머신까지 멋있었습니다. 하리오 v60에 케맥스 필터 조합이 신기했습니다. (원두는 30g 정도 사용합니다.) 에스프레소에 설탕 말고 나중에 곁들여마실 우유까지 주셔서 신기하고 맛있었습니다. 개인적으로 정말 만족스러운 시간을 보내고 왔습니다. 현재 합정역 본점 말고 동교점과 마곡점까지 총 3개의 지점이 있다고 합니다.', 13, 2, 'GOOD', SYSTIMESTAMP);
