INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '앗 살짝 느낌이 바뀌었넹 !.! 바뀐느낌도 좋네요 커피버블밀크티 맛나요 밀크티가 더 진하면 좋겟어용 바치케랑 같이 먹으니 굿굿 아아는 테이크아웃 해갈거에용 여기 커피 맛이쏘😘 먼길 떠날때 필수 !.! 🧊🧊🧊🧊🧊', 30, 5, NULL, SYSTIMESTAMP);
