INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '브라질 원두 드립 시켰는데 설명도 잘해주시고 향이 너무 좋아서 계속 이야기햇엇어요 ㅎㅎ 사장님의 열정과 좋은 품질로 널리널리 잘되셧음 좋겟습니다!', 39, 6, 'GOOD', SYSTIMESTAMP);
