INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '편안한 분위기. 디카페인 아메리카노도 진한 맛이 인상깊었습니다. 꼬소한 향 뒤에 강하게 따라오는 산미까지 다양한 맛이 나서 좋았습니다. 주말에 편하게 커피 한 잔 하며 쉬기 좋은 느낌.', 8, 9, 'GOOD', SYSTIMESTAMP);
