INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '선물할 드립백 사러 갔다다 드립커피 한잔 💙♥️ 커피가 넘 맛있어요. 아직까지 여기 커피가 일등임.🤦🏻‍♀️ 드립백 여행가서 먹기도 좋구 원두도 구분되어 있어 선물하기도 너무 좋음 향이 넘 죠아 고급진 느낌ㅋㅋㅋㅋㅋ', 8, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '근처에서 밥먹고  눈에 보여 들어간 카페인데  맛있게 잘 먹엇어요!  직접 로스팅하는 카페를 개인적으로 좋아하는 편입니다 굳굳♡', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '커피도 진짜진짜 맛있지만 겉은 바삭하고 속은 쪽득보들한 까눌레도 진짜 너무 맛있구요 초코카스테라위에 얹어주시는 바닐라 가미된 생크림은 완전 최고 맛있습니다!!! 다음번에는 담아갈 그릇 가져가려구요>_< 제 생에 최고의 까눌레 + 생크림 이었습니다 👍', 10, 9, 'GOOD', SYSTIMESTAMP);
