INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '다양한 디저트와 직접 로스팅한 원두 친절한 사장님 여유로운 재즈 친구놈이 늦어서 기다리는 동안 역 근처에 보이는 카페에들어갔는데 이정도면 성공인거같다 부드러운 거품이 매력적인 카푸치노 고소하고 보슬보슬한 스콘에 딸기잼 가격도 괜찮고 추천할만하다.', 64, 16, 'GOOD', SYSTIMESTAMP);
