INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '사장님도 친절하시고 요즘 시국에 코로나 철저하게 관리하는 곳은 잘 못 봤는데 여기는 먹을 때 제외하고 마스크 착용해야 한다고 해서 좋았어요! 바스크 치즈 케이크도 맛있어요 :D', 34, 6, 'GOOD', SYSTIMESTAMP);
