INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '얼음이 녹아도 맛이 흐려지지 않고, 시럽을 몇 펌프 넣은 것 같은 (물론 한 방울도 넣지 않았고요.) 몰티한 단맛이 굉장합니다.', 73, 14, 'GOOD', SYSTIMESTAMP);
