INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '스벅커피만 줄창 먹다가 커피맛을 알게 해준 곳. 종종 생각나는 커피에 어울리는 과하지않은 직접베이킹한 디저트들. 회사건너편 우연히 인테리어에 눈길이 닿아 맛본후 지하도를 넘나들며 커피를 마십니다. 서비스는 맛으로 말하는 것이구요. 커피면 커피. 분위기면 분위기, 밝게인사해주는 직원들까지 좋습니다. 다만 위층 올라가니 커피마시지 않고 핸드폰보면서  마스크 벗고 앉아있는사람들 있더라구요. 요즘같은 난리통 직원분들 매장관리하려고 일일히 자꾸 올라와 마스크 써달라고 하는데도 안쓰고 니가뭔데식으로 쳐다봅디다.  개념좀 챙깁시다. 그게싫음 테이크아웃하시던가요. 내건강. 남건강 챙겨좋고 맛있는 커피 건강하게 먹어좋고 누이좋고 매부좋고 아닙니까?', 2, 2, 'GOOD', SYSTIMESTAMP);
