INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '츄러스+쵸코딥 주문했는데 맛있네요. 갓 구워 나와서 정말 뜨거워요. 쵸코딥에 찍어먹으려면 설탕양을 좀 줄이는것도 괜찮을것 같아요. 안에서 먹을 수 있는 매장이 작기는 하지만 메뉴가 메뉴인 만큼 유럽에서 먹는 분위기를 좀 낸다면 용기를 좀 신경쓰는것도 좋을것 같아요.  주차는 공영주차장을 이용해야할것 같아요. 화장실도 손님이 사용할 수 있는 화장실은 없어 보이지만 주변에 공용화장실이 찾아보면 있어요. 직원분들 친절하시고 실내에서 잠깐 쉬면서 먹기 좋았습니다.', 6, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '삼청동 산책 도중 들른 츄로101 삼청점. 블루리본 14년 연속 등재된 디저트 맛집답게, 즉석에서 튀겨낸 츄로스는 겉은 바삭하고 속은 쫀득했어요. 저희 부부는 시원한 바닐라 아이스크림과 바삭한 오레오가 듬뿍 올라간 시그니처 메뉴 오레오 아츄를 선택했는데요. 따뜻한 츄로스와 차가운 아이스크림이 어우러지며 입안 가득 퍼지는 달콤함이 정말 행복했답니다. 삼청동 데이트 중 달콤한 휴식이 필요하다면 꼭 추천드리고 싶은 디저트예요🍦💛', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '츄러스 좋아하시면 와서 한번 드셔보시면 좋을듯. 우선 식감이 지금까지 먹어봤던 츄러스들중 가장 바삭하고 갓나온 츄러스라 그런지 눅눅한 느낌이 전혀 없습니다 그리고 츄러스에 묻혀진 설탕과 시나몬 가루들이 적당히 달고 츄러스는 고소쫀득하여 배부른 상태였음에도 게걸스럽게 먹은것 같습니다 전 개인적으로 딥초콜렛을 찍어먹는것도 맛있었지만 단거 싫어하시면 그냥 기본 츄러스만 드셔도 맛있을 겁니다 츄러스가 광장시장 줄서서먹는 꽈배기집의 맛에서 바삭함을 더한 서양버전 꽈배기라고 보면 될거같습니다 다크초코 츄러스는 시나몬 가루 안뿌린 츄러스에 초코릿딥 에 푹 담갔다 뺀거같은 비쥬얼에서 알수있다시피 초코맛이 너무강해서 초코좋아하는 저한테도 약간 아쉬웠습니다 오히려 코코넛 츄러스가 코코넛 칩의 고소함 때문에 굉장히 맛있었어요', 122, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '다양한 맛의 츄로스를 맛 볼 수 있는곳. 갓 튀긴 따뜻한 츄러스를 바로 먹을 수 있어 맛있다. 홍대 갈때마다 찾아가 다른 맛 다 먹어보자며 도장깨기 도전 의식을 불러 일으키는 맛집으로 계속 생각나요. 당충전 하러 가기 좋은곳.', 2, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '누텔라커스터드츄러스 4,500원 연유츄러스 4,500원 홍대가면 항상 들르게 되는 츄러스 맛집! 주말이라 그런지 결제줄이 길었어요!🥹 그래도 주문하면 빨리 나와요~! 연유츄러스는 무난했구 누텔라 츄러스가 진짜 넘사벽입니당!!!! 꼭꼭 누텔라 츄러스를 1개 드셔야해요!!!🥰👍', 11, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대가면 늘 먹는 홍대 츄러스 맛집 츄로101 바삭바삭한 츄러스는 항상 맛있음 🤤🤤🤤🫶❤️ 늘 사람도 많은 곳인데 매장문을 보니 블루리본이 몇개여 ㅋㅋㅋㅋㅋㅋㅋㅋㅋ 근본 지켜지는 맛이다. 홍대 디저트 맛집 🤭❤️', 39, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '누텔라커스터드츄러스 4,500원 시나몬츄러스 3,900원 홍대오면 꼭 들르게 되는 츄러스집! 바삭하니 넘 맛있어용! 특히 누텔라가 찐찐 맛도리예용! 친절하고 좋아요~!🥰👍', 10, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '기름냄새 안나서 맛있어요 메뉴중 시나몬과 플레인이 있는데 시나몬이 우리가 알고있는 설탕있는 추러스입니다. 플레인은 설탕없어서 아이스크림이나 곁들어먹는용이니 참고바랍니다.', 2, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '츄로101 삼청점입니다 영수증 인증하니 홍대본점으로 나오네요 츄러스 사진 포커스가 안맞았네요 :) 츄러스 별로 안좋아하는 1인으로써 먹어볼만한 맛이었다 한번더 사먹을 의향이 있다 라는 평을 내봅니다 바로 반죽을 튀겨서 해주시다보니 요게 그리 맛있습니다 블루리본 보고 깜놀~ 맛있어요 주변에서 이것저것 맛난거 먹었어도 요거하나 포장해서 걸어가면서 드셔보는것도 꼭 추천드려요 bb!!!', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대에서 츄러스가 먹고싶을 때 찾는 곳이에요! 겉이 바삭하고 시나몬 설탕이 크런치하게 씹히지만 달지 않아 좋아요😊 평일에 방문하니 미리 튀겨놓은 츄러스를 받아 띠뜻하지 않아 아쉬웠지만 맛있었습니다👍', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '너무딱딱하지도 너무 빵같지도 않아 맛있었던 츄러스, 밥먹기에는 배부를 것 같고 뭔가 걸어다니면서 먹고싶을 때 추천. 외국인들도 많이 사가는 곳. 매장 밖 키오스크에서 주문하면 된다. 주문하자마자 바로 나와서 당황. 0초만에 나왔음. 순간 내가 시킨거 아닌 줄 알았다. 평일 오후 웨이팅 없이 이용.', 31, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '다양한 맛의 츄로스를 선택할 수 있는 츄로스 전문매장이네요. 주문 후 바로 제조해 주니 츄로스가 따뜻해서 더 맛있게 느껴지는 것 같습니다. 주말 북적이는 홍대 거리에서 많은 외국인들도 줄서서 사는 모습이 신기했어요.', 79, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대점 츄로원오원 <찐리뷰> 시나몬츄러스 3.900 매장 안에서 앉아서 먹을 작은 공간 있음! 주말에 왔더니 역시나 줄이 엄청 길었어요 ㅎㄷㄷ 속도가 굉장히 빨랐어서 길게 기다린 느낌이 아니라 좋았아요!! 길이도 짧지 않고 길어서 뭔가 기분이 좋았아요👍🏻', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '🍞2015~2025년 블루리본 카페 🍞갓 만든 츄러스 꿀맛 🍞매장 내 취식 자리 좁게 있음 (매장 취식시 1인 1메뉴 주문 필수) 🍞주차 불가 항상 홍대 한켠을 지키고 있던 츄러스101 문앞에 블루리본도 2015년부터 올해까지 붙어 있는걸 보니 찐맛집이겠거니 싶어서 한번 먹어보았습니당😋 다크초코츄러스(4500원) 길이도 넉넉하구요 바삭한 츄러스 겉면에 찐한 초코가 듬뿍 묻어 있어서 달다구리의 정석을 맛볼 수 있었어요!❤️ 길가다가 하나씩 물고가기에 부담없는 먹거리여서 지금까지 블루리본을 받아왔나봅니당👍 실패없는 길거리 간식을 드시고 싶다면 왕추천드리고 싶은 츄러스 집이에용!', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '남자 친구 보다 더 좋은~~ 츄로 원오원~🥰 블루리본 13년 연속등재~!!! 합정 맛집 탐방(?) 후 집으로 가는길에 마무리로 츄러스~~😉 시나몬츄러스랑 코코넛츄러스 선택~🍫🥥 따끈따끈하고 바삭바삭하고, 겉에 뿌려진 시나몬가루랑 설탕은 아작아작 향긋하게 씹히고~ 속은 뜨끈꾸덕쫀득한 갓 튀겨낸 츄러스는 역시나 JMT~👍 코코넛츄러스의 초코코팅은 perfect~!!! 아삭한 코코넛과 함께 브라우니 같은 식감은 역시나 JMT~👍 크림치즈츄러스랑 아몬드츄러스도 먹어봐야지~~ㅎ', 81, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '놀이공원에 가면 필수가 츄로스라고 하지만 전 갠적으로 너무 싫어했거든요ㅋㅋ 그리고 스페인에서도 엄청 유명한집에서 한참 줄 서서 먹었는데 맛 없어서 걍 나랑 츄로스는 안 맞는구나 싶었는데 이번엔 지인이 하나만 사서 먹는다고 해서 구경만 하려다가 한입 뺏어먹었다가 새로운 세상에 눈을 떴습니다!! 진짜 미쳤어요!! 전 앞으로 츄로스 먹게 된다면 무조건 여기서만 먹을거입니다. 겉은 바삭, 속은 살짝 폭신 밀가루 냄새 없고, 츄로스 특유의 향이 없고 초코찍어먹을려고 샀는데 안 찍어 먹는게 더 맛있는거 같았어욬ㅋㅋㅋㅋ 괜히 블루리본이 많은게 아닙니닷 무조건 강추예요👍👍', 87, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '삼청점인데 홍대로 뜨넹?!! 정독도서관 산책후 츄로스 궈궈~꽈배기맛인데 초콜릿딥 찍어먹으면 줜마탱^_^ 설탕 없이 달라그래서 찍어먹어도 맛있을듯!! 설탕 마니달당', 40, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대 관광객들의 핫플, 츄로101홍대본점 방문. 오전에는 사람들로 줄을 서는데 오후 1시 30분 방문했고 줄 없이 바로 주문. 따뜻한 츄로스 with coffee = heaven♡', 88, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대에서 달콤한 간식을 찾는다면 ''CHURRO101'' 강추~~ "better than a boy friend"라는 문구에 격하게 공감♡', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '우리동네에서 사라진 츄로101 홍대 나들이 오면 , 오래전 츄러스 먹으려 줄 섰던 기억에 들러서 먹게 되네요 동네 다시 생겼음 좋겠어요', 130, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '줄이 길어서 기대했는데 많이 아쉽네요 외국인들만 줄서있는 이유가 있었어요 시나몬 기본맛 주문하자마자 바로 준다고 해서 받았는데 데우지도 않고 차가운거 주셔서 씹어먹는데 이게 뭔가 싶었어요; 외국 여행객들한테 이렇게 주는 건 아니겠지 걱정되더라구요 가격도 기본맛이 4000원정도 하는데 이정도 퀄리티라면 비싼 가격이네요', 3, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '예전에 맛있게 먹었던 기억이 나서 지나가다 들렀습니다. 주말 저녁이라 줄이 꽤 있었는데 생각보다 금방 줄어들었어요. 10분 정도 기다려서 시나몬 츄러스 받았습니다. 따뜻하고 바삭하고 달달해서 맛있어요. 지나가다 별미로 먹기 좋습니다.', 10, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '나 눈물나 4,500원인 오레오 츄러스가 저 처음 무는곳에만 오레오맛나고 안에는 필링이 비어 있음 안믿겠지만 진짜임.. 넘 서운해', 18, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '블루리본이 많이 붙은 츄러스가게라 방문해보았어요. 따끈한 츄러스가 맛있었어요. 매장은 아주 작게 있지만, 매장이 있어서 잠시나마 쉴 수 있었어요. 오레오 추러스도 추천합니다. 많이 달지 않아서 맛있더라고요. 커피 기계 망가진 건 좀 아쉬웠지만, 다들 아이스크림이랑 먹더라구요. 그것도 좋았지만 좀 따뜻한게 필요한 날씨였어요ㅎㅎ 또 가고 싶은 곳입니다.', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '언제 먹어도 맛있는 길거리 간식👍 항상 이 자리에 있어서 좋아요.. 누텔라츄러스 완전 달디 달고 혈당쇼크 오는 맛😝 진짜 맛있어요 ㅋㅋ 사람 많은데 금방 나옴.. 갓 튀겨준 따끈한 츄러스 받을 줄 알았는데 식은거라서 아쉬웠지만 그래도 진짜 맛있게 먹었어요 밥 먹고 후식으로 먹으면 짱~⭐️', 85, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '아츄 오리지날로 먹었어요! 날이 추웠지먼 아이스크림+츄로스 조합 못잃어... 실내에 앉아서 먹을 수 있는 바테이블이 있어요. 넓진 않지만 잠깐 먹는 정도로는 괜찮습니다!', 21, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '꽉 깨물땐 바삭하고..말랑말랑하고..시나몬향이 나고.. 설탕처럼 달달하면서..혈당 치솟는 맛.. 바로 놀이동산 갔다올 수 있는 맛..!', 37, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '주문 기계가 작동을 안 해서 손님이 별로 없는데 기다려야 했습니다. 늦은 시간이라 그런지 몰라도 오래된 맛이고 뜨겁지 않았습니다. 조금 실망스러웠습니다.', 82, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '시나몬 츄러스, 누텔라 츄러스 먹었어요. 시나몬도 맛있었지만, 누텔라가 좀 더 부드럽고, 생각보다 막 달지 않아서 좋았습니다.', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '줄 엄청 서있고, 뭔 블루리본이ㅋㅋㅋ 7,8개? 있어서 예전부터 지나다니면서 봤는데 처음으로 사먹어봄. 아 맛남. 아 시나몬츄로 하나먹고 맛있어서 연유츄로 하나 더 먹었다. 똑같이 겉에 설탕 약간의 시나몬 뭍어있음. 연유가 액체연유라기보다는 끈적한 슈크림?같은 질감. 근데 바로 나와서 받아보니 안따뜻..피유.. 오히려 차갑다. 시나몬츄로는 나름 따뜻했음. 바삭 속은 촉촉 따뜻했음 맛있을텐데. 그래두? 맛있다!', 72, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '역사와 전통의 츄로스 맛집입니다. 사이즈가 크고 바로바로 만들어주며 시즈닝 골고루 넉넉하게 뿌려주니 맛없을수가 없습니다. 먹고 갈 공간은 매우 비좁으니 참고하세요.', 77, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '츄러스 좋아해서 이곳 저곳에서 많이 먹어봤어요 .오리지널은 나쁘진 않은데 필링이 들어간 츄러스는 좀더 익혀야 할것 같아요. 안익은 밀가루가 느껴져요.단거 좋아하지만 츄러스가 생각보다 많이 달아요.츄러스보단 아이스크림이 맛있었어요.', 48, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '지난번에 시나몬 츄로스 먹고 너무 감동 받아서 오늘 비가 온다는 핑계로 오레오 츄로스도 한번 사 먹어 봤는데 진짜 너무 맛있어서 행복했습니다…🖤 주문하면 바로 만들어주시기에 정말 맛있지만! 그래서 초큼 기다려야한다는 거..! 근데 오히려 사람이 많을 때 직원분들도 많아서 그런지 줄이 없을 때보다 메뉴가 빨리 나오는 것 같아요?!', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '항상 지나갈때마다 웨이팅이 있던 츄로101! 츄러스가 너무 먹고싶어서 다녀왔어요. 5분 정도 기다렸고, 츄러스가 바로 만들어지다보니 대기시간은 짧은 것 같아요 👍🏻 이렇게 바로 만들어진 따끈한 츄러스는 처음 먹어본 것 같아요 ㅋㅋㅋ 바삭하고 촉촉하고 달아요 ☺️ 시나몬츄러스 기본이 진리! 종종 간단디저트로 사먹을 것 같아요! 홍대 디저트 맛집 - 렉터스라운지: 테라스 작업하기 좋은 카페, 잠봉뵈르 👍🏻 - 퐁포네뜨: 딸기케이크 👍🏻 - 츄로101: 츄러스👍🏻', 8, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '사람들이 줄서서 먹길래 궁금해서 먹어봤는데 맛있어요😋 더운데 당떨어지고 음료가 먹고싶어 안에서 먹었는데 시원하고 맛있게 잘먹었습니다😂', 61, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '연휴 마지막날인 오늘의 홍대는 정말 정신이 없었다. 블루리본 가득 붙인 츄러스 가게가 있어서 홀린듯 주문하여 아이들 사줌. 맛있었고, 비쌌다. 다른 곳과 특별함은 없는듯.', 33, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '블루리본 13개 받은 홍대 츄러스 맛집 블루리본 받은 음식점들 맛이 꽤나 좋았어서 기대를 품고 오레오 아츄 주문했습니다 토요일 오후 5시 30분 대기 없었고 츄러스 5분 내외로 엄청 빠르게 나왔어요 츄러스 위에 오레오 가루를 묻힌? 뿌린 모습이더라고요 음 .. 솔직히 기대한만큼은 아니였어요 다른 리뷰러분들 사진보고 오레오 아츄 먹어본건데 오레오 가루가 어떤 분은 듬뿍 어떤분은 빈약 제 껏도 빈약 ,, 맛은 밀가루 츄러스에 쫀득하긴 합니다 아이스크림 양도 많고요 균일하지 않은 점이 좀 아쉽네요', 7, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '우연하게 지나가다가 아이스쿠림이 너무 먹고싶어 시켰는데 너무 맛있어서 깜짝놀랐던.. 추로101..💦 근데 7천원은.. 좀 창렬적인 가격같아서.. 항상 사먹으면서 좀.. 덜덜 떨긴함..', 26, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대 합정 망원 투어의 시작은 항상 이곳 츄로원오원에서 시작한다~~요즘 들어 츄러스 가게가 많이 생겼지만 내 원탑은 항상 요기, 요기 어때^^ 츄러스도 맛있지만 커피도 꼭 드셔보삼. 커피 맛 괜츈♡♡', 73, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '아침에 외국 관광객들이 줄을 서있길래 예상은 했지만 여윽시 맛있다. 갓 데운 따뜻한 츄러스를 쵸코딥소스에 푸욱~~~찍어 커피 한 모금과 먹으면 이거시 바로 소확행♡♡♡', 77, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '평일 점심때 갔는데 한팀 정도 대기했고 주문과 동시에 바로 만들어주시니까 따끈따끈 갓 나온 츄러스 정말 맛있어요! 오레오는 겉에 가루를 뿌려주신건데 따뜻한 츄러스랑 만나니 시즈닝이 약간 텁텁, 눅눅해지는 거 같아용 안에 크림도 너무 녹았구요 오레오는 겨울에 먹으면 더 좋을 거 같네용 어쨌든 시나몬이랑 오레오 둘다 맛있습니다😋 시나몬 다음에 또 먹으러 갈 거임', 2, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '츄러스 맛집이래서 바아로 찾아가봤습니다 ! 명색답게 주문하는 대기줄부터 정말 길더라구요 그리고 주문 후 매장에 들어가보니 약 13년 연속으로 블루리본을 받은 표시가 눈에 띄었습니다. 정말 엄청나더라구요 시나몬츄러스+초콜릿딥, 오레오츄러스 이렇게 2가지 메뉴를 주문 후 수령했습니다. 시나몬의 경우 맛은 일반적인 츄러스와 크게 다르진 않았지만 초콜릿딥과의 조화가 정말 좋았고 식감 부분에서 정말 만족스러웠습니다. 츄러스의 모양 자체가 이뻐서 모양대로 식감이 그대로 드러나는 게 가장 매력적인 부분이었어요. 그리고.. 오레오츄러스가 진짜 대박입니다. 살면서 먹어본 츄러스 중 가장 맛있었어요. 바삭하고 부드러운 식감에 내부의 앙금까지.. 정말 완벽한 디저트였습니다. 재방문의사 확실하게 있습니다 !', 24, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '일본 친구가 먹고 싶다고 해서 갔는데 맛있다고 하더라고요. 붙어있는 블루리본 갯수가 신빙성이 있었습니다. 맛있게 잘 먹었습니다!', 33, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아무생각없이 지나가고 있다가 블루리본이 엄청 많으 붙어있는거 보고 홀린듯 츄러스 하나 구입했습니다. 사전정보가 없어서 베스트메뉴인 오래오츄러스는 못먹어봐서 아쉽지만 누텔라 츄러스도 달달하고 쫄깃하니 존맛이었습니다. 츄러스 먹는데 3분도 안걸림. 내부는 협소하고 손님들이 하도 많아서 오래 앉아 있지는 못함ㅎㅎ', 105, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '블루리본 받은 츄러스 집이래서 삼겹살 먹고 배부른데도 기대하고 가서 포장해왔습니다 외국인분들한테 소문났는지 외국인분들이 엄청 줄 서있더라구요 그래도 잠깐 기다리면 바로 나와용 제가 얼마전에 츄러스로 유명한 다른 곳도 가봤는데 전 여기가 더 맛있더라구용.. 집에 포장해오느라 다 식었는데도 맛있었어요 갓 나온 츄러스 따뜻한 초코 소스에 먹으면 더 맛있었겠죠ㅠ 지나가면서 한번 먹어보는 것.. 추천합니다', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '메뉴가 상당히 많다. 본론부터 말하면 츄로스보다 시장도나스 느낌. 생각하는 추로스의 맛이 아니다. 과하게 푹신해서 빵같다. 초코는 많이 달지 않아 좋다. 생긴건 나무같지만.', 75, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '지나가다 우연히 들렀는데 블루리본 추로스 맛집이네요🥰 키오스크로 주문하고 기다리면 맛난 추로스가 딱! 기차에 들고 탈거라 비닐봉지 요청했는데 깔끔하게 잘 담아주셔서 좋았어요. 추로스 받을 때 100원 따로 내면 요렇게 담아주십니다 :-) 식고나서 먹어도 딱딱하지 않고 겉바속쫀 맛이 좋았습니다.', 2, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '와 이제껏 내가 츄러스라고 먹은게 뭐지?? 진짜 츄러스는 이런맛이구나 이렇게 겉은 바삭하고 속은 촉촉하고.. 진짜 너무 너무 맛잇다 와플 크로플 졸라 좋아하는데 츄러스가 최고다 미쳐따👍👍👍', 71, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '매번 줄서있는 츄러스 맛집이라길래 한번 먹어봤는데 츄러스 맛집 인정이에요 완전 겉에 바삭하고 기름기 많이 안느껴지는 맛이라 너무 맛있어요 시나몬이랑 다크초코 먹어봤는데 시나몬= 무난하게 아주 맛있고 다크초코= 달달한 초코 좋아하신다면 추천드리는데 매우 달아요 아아랑 같이 먹으면 좋을것 같아요', 120, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '오며 가며 먹기 좋은 맛이네요. 주문과 동시에 튀기기 때문에, 따뜻하고 부드럽고 바삭합니다. 설탕 안뿌리는 맛도 있으면 좋겠어요', 48, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '오레오츄러스가 너무 땡겨서 사먹어봤어요 아이스크림+오레오츄러스 해서 6000원이었어요 약간 비싼듯 싶긴 했지만 만족할 만한 맛이었습니다 외국인이 많아요', 45, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '츄러스 너무 맛있어요 아이스크림은 좀 밍밍한 맛이 없구요 카페 내부는 좌석이 있긴 하지만 매우 협소한공간으로 여유롭게 앉아 있다 갈 곳은 아니에요', 21, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '궁금해서 먹어봤어요 ㅋㅋ 항상 외국인들이 엄첱 서있길래 .. 젤 기대한 크림치즈맛은 제가 생각했던 맛이 아니라 약간 물같이 흐르는 제형으로 많이 달더라구요 연유맛이 오히려 더나았어요', 67, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '✨겉바속촉 환상적인 츄러스✨ 길거리 음식으로 찾아보기 어려운 츄러스! 놀이공원에서 먹는 맛과는 정말 180도 달랐어요 우선 직접 조리해서 튀겨주는 츄러스여서 그런지 겉은 바삭하고 안은 촉촉하게 너무 맛있어요! 시나몬 츄러스에 초코딥을 주문했는데 초코딥은 네스퀵을 엄청 진하게 우린 맛? 약간 다크 초콜릿의 쌉싸름함도 느껴져요 츄러스는 달달한 설탕에 계피향까지 완벽한 조합인데 거기에 초코딥까지 함께하니 진짜 환상 그 자체예요', 7, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '츄러스 바삭하고 맛나요~~ 근데 아이스크림은 그냥 그랬어요ㅎㅎ 밀도있고 부드러운 맥도날드 소프트아이스크림 같은 느낌 생각했는데 아니었어요ㅎㅎ 그래도 맛있습니다!', 6, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '음식은 맛있었는데 직원이 정말 불친절합니다 우산 우산통에 넣으라는 말을 하셨는데 불쾌하게 말씀하셨어요 그냥 참고 그러려니 하려고 했는데 말못알아듣는 외국인한테도 못알아듣는다고 엄청 짜증내면서 말씀하시고 외국인이라 못알아듣는거 알면서도 계속 한국어로 우산통에 넣으라고 말하시는거 보고 정말 깜짝 놀랐어요', 44, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '키오스크 결제하는데만도 줄을 꽤 서기는 했는데 그래도 결제후 츄로스 받기까지는 얼마 안걸렸어요 바로 튀겨주시는 시나몬츄로스 너무 맛있어요 :)', 112, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대 츄러스 맛집입니다. 다양한 토핑의 츄러스 많은데 특히 오레오츄러스가 제일 맛있는 듯 합니다. 크런치 종류는 초코가 너무 듬뿍 발라져있어서 많이 달더라구요.^^♡', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '츄러스 나오자 마자 뜨끈할때 먹으면 너무 맛있어요! 기본 시나몬 츄러스 맛있었구요, 웨이팅이 꽤 있었지만 금방 빠져서 구경하고 있으니 괜찮았어요^^', 65, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '주말에 가서 그런지 대기 줄도 여럿 있었고 매장에서도 먹을수 있는 자리가 있긴 하지만 좌석은 많진 않았어요! 그래도 다양하게 먹을수 있는게 많아서 좋았습니다!!', 50, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '직원들 서비스 상태가 너무 최악;;; 서비스업 종사하는 사람으로서 화나요ㅋㅋㅋㅋ 블루리본 많으면 뭐하나요 융통성이라곤 1도 찾아볼 수 없는 매장이었습니다. 밖에서 하나 시키고 휴지 때문에 잠깐 들어갔더니 뜬금없이 두 명이시면 하나 더 시켜야한다고 "추가주문 하실거에요??" 꼽주듯이 말하는 뉘앙스..불친절한 포인트가 너무 많았네요 아쉬워요', 32, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '진짜 이렇게나 불친절한응대 처음이네요.. 물 마시던 종이컵 하나 버렸다고 외부음식이니 쓰레기통에서 꺼내가라는게 말이되나요? 말투가 기분나빠서 쓰레기통에서 직접 종이컵빼서 밖에다 버렸습니다 매장내 쓰레기통은 왜해놓는건가요? 융통성이라고는 하나도 찾아볼수없는 최악의 가게네요 안좋은 리뷰쓴거 처음입니다~~', 26, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '선물용으로 잘 구매하였습니다. 외국분들도 많이 구매하시고. 앞에서 주문하시는 외국분께서 카드 결제가 안된다고 하시는데 멀리서 보니, 카드를 끝까지 밀어넣지 않고 적당히 넣고 마시더라고요 도와드리진 못했는데, 안쪽에서 직원분이 결제를 친절히 진행해주시더라고요 여튼. 주문하면 바로 튀겨주셔서 맛있게 잘 먹었습니다.', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대에서 밥먹으면 남자친구랑 후식으로 항상 누텔라추로스를 사먹습니다 한동안은 배달로도 먹구요 항상 누텔라가 흐를정도로 가득넣어주셔서 정말 좋아했는데 어느날부터 누텔라 양이 줄어든거같다 싶었어요. 이날은 혼자 두개먹으려고 누텔라추로스 두개를 주문했는데 첫입부터 누텔라 맛도 잘 안느껴지더니 두개다 밑에는 누텔라가 있지도 않더라구요…. 두개나 사먹을 이유가 사라졌습니다…. 다음에도 살때 저렇다면.. 누텔라 넣는 용량 자체가 바뀐거겠죠…?', 67, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '실물보고는 다크초코를 먹을까도 고민했지만, 원래 생각했던 누텔라랑 아바라를 골랐어요. 밥을 간단히 먹고 좀 허기질 때 먹으려고 미리 산건데 사고나니 따끈한게 한입만이라도 먹어봐야겠다, 했는데 한입 먹고나니 끊을수가 없더라구요. 아바라는 달지않아서 첨엔 아쉬웠는데, 달달한 츄로스랑 먹을걸 생각해보면 딱 적당한 것 같아요. 다만 안내를 잘해주셔야할 것 같아요. 키오스크발받침밟고 올라야함.대기 중 설명서 확인해서- 안으로가앞서포장은밖에서 받으란말에 인지했지만 밖이더워 내번호직전이불리면나가야겠다 생각했죠. 포장은 나가달라고 하길래 나보고그런건가 싶었는데 바라보니뚫어져라보면서 나가주세요를 연달아 얘기하더라구요.표시부분에 아바라가 놓이길래 보고있는데 저보고 번호이미불렀다고 짜증내네요.호출기?도 눈에안띄고 소리만 들려요', 34, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '개인적으로 저는 탕후루보다 츄러스가 더 맛있더라구요👍👍 짱맛 하나 혼자 먹기는 달아서 둘이서 나눠먹으니 적당한 당충전 이었어요', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '너무 맛있어요. 포장해와서 1시간 뒤에 먹었는데도 겉바속촉!! 시나몬도 맛있지만 안에 연유가 들어간 것도 맛있더라고요 다음엔 아츄에 도전할게요', 14, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '사람들이 줄 서서 사기에 궁금해서 그리고 놀이공원에서 먹었던 츄러스를 먹고 싶었어서 먹었는데 감성은 다를지언정 맛있게 먹었습니다😆 아이스크림과 츄러스 조합도 특이했지만 생각외로 잘 어울리고 잘 먹었습니다!', 56, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '맛있어용 가격은 뭐 ㅎㅎ롯데월드 급이에요 손님은 외국인들이 절반인듯. 알림판으로 번호 띄워줘서 좋아요 내부는 좁아서 밖에서 먹는거 추천드려요 맛은 츄러스 맛이에용 개인적으로 오레오 츄러스가 더 맛나요 !!', 29, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '추로스는 참 맛있어요 어떤맛이든 맛있을듯합니다 근데 사람들이 많아서 그런지 친절하시진않네요 거의 키오스크로 해결이라 말섞을일도 별로없는데 조금만 더 친절하셨더라면 더 기분좋고 더더 맛있게 먹었을것같아요', 25, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대에서 제일 가는 츄러스 맛집 ••• 아이스크림과 오레오 츄러스의 조화가 완벽합니다 츄러스는 무조건 오레오 츄러스 .... 최고 최고', 33, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대의 맛있는 츄러스 카페 👍 실내 공간이 협소해서 밖에서 먹어야 했지만 정말 맛있는 츄러스였습니다. 갓 만든 츄러스에 시나몬설탕 가득 묻히고 안에 누텔라를 넣어 주는데 따끈하고 달콤하니 정말 맛있었어요. 다음엔 아이스크림이랑도 먹어보고 싶네요! 누텔라츄러스 3,900원', 65, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '엄마와 먹었는데 완전 맛있아습니다! 아이스크림 츄로스는 밑에가 눅눅하고 아이스크림이 빨리 녹아서 아쉬었어여 다음에는 일반 먹으랴구 강추 입니당', 9, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대에서 간단하게 먹기 좋은 츄러스 맛집! 오레오츄러스 꿀맛이라 추천해요👍🏻 크림치즈츄러스는 요거트처럼 신맛이 강했어요! 매장 안에 먹을 수 있는 공간이 있어서 먹고가기 괜찮아요', 16, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '항상 홍대 지나갈 때마다 사먹어야지 사먹어야지 했는데 진짜 맛있네요! 오레오츄러스 먹었는데 다음엔 아이스크림 세트 먹어보려고요 :)', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대가면 항상 사람이 많았던 곳.. 바로 먹어서 그런지 괜찮긴하네요. 매장에서 먹는데.. 테이블이 좀.. 많이 지져분해서 셀프로 닦아서 앉음..', 31, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '오레오 크림치즈 연유 3개 시켰어요~ 필링쪽 반죽이 살짝 덜 익어있어서 아쉽네요 ㅠ.ㅠ 외국인 관광인들이 많이 찾는 것 같아요!! 기본부분이 잘 지켜지면 맛이 더 좋아질 것 같습니다', 40, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '츄로스는 진짜 둘다 맛있어요 초코, 연유 모두 맛있었습니다 가격이 사악하고 직원들은 모두 불친절했지만, 지나가면서 하나 사먹기 좋았어요', 4, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '갓 튀긴 츄로스 맛있었는데요.... 웨이팅일 정도로 사람많고 했는데 정작 받았을때 츄로스가 따뜻하진 않아서 놀랐어요...;; 너무 식혀주시는건 아닌지~ 아이스크림츄로스랑 초코딥소스+츄로스 같이 시켰는데 초코딥소스는 좀 씁쓸해서 별로였고 아이스크림은 괜찮았어요~~~', 90, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '인절미 아이스크림 추로스  먹었는데 추로스에 설탕이 없었어요. 초로스 자체는 달지 않았구 아이스크림 찍어 먹기에는 그닥이였어요. 아이스크림 자체는 맛있어요.', 34, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '인기 많은 츄러스집... 지나가다가 못 참고 먹었는데 반죽 넘 부드럽고 맛있어용 >_< 꺄아아아아 누텔라 츄러스인데 음 누텔라는 아니고 초코 소스이긴해여 근데 반죽이 다 함', 31, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '즉석에서 튀겨주는 츄러스집 찾기 힘든데,,,홍대에서 찾음. 츄러스는 맛있는데 아이스크림은 별로에요. 크림이랑 우유 많이 들어간 맥도날드st가 아니라 연유+얼음 아이스크림,,,', 106, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대 갈 때 마다 먹는 츄러스…진짜 너무 맛있고 연유는 최근에 생긴 건지 모르겠는데 계속 생각나는 맛이에요. 연유맛 강추!!!!!', 29, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '주의 !!!! 설탕 진짜 많이 뿌려요. 단거 별로 안좋아하시는 분들 미리 털어드세요. 시나몬 세트로 시켰는데 일반 슈가 추로로 줌.. 바쁜건 알겠는데 친절한것도모르겠고 비온 다음이라 건물에서 물이 뚝뚝 떨어져 맞음 ㅠㅠ 츄러스 가게가 괜찮은 곳이 주변에 없다보니 장사가 잘되는듯 ..', 4, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '이거 왜안먹어ㅠㅠ진짜 츄러스 너무 맛있어요! 근데 커피는 그냥저냥,,ㅎ 바닐라라떼가 너무 싱거웠어요ㅎㅎ그래도 츄러스먹으러 또갈꺼야ㅠ', 37, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '키오스크에서 포장주문을 눌렀는데, 포장 안해주시더라구요. 음.. 제 앞에 주문한 사람도 포장주문이었는데 그분한테는 해주셨거든요. 그래서 잊어버리신건가 해서 "저 봉투 좀 주세요" 라고 했더니 무슨 무리한 요구라도 받은 양, 알바의 표정이 너무 띠껍고 대답도 없네요~ 음식을 대충 틱 내미는거나 오갈때 아무런 인사가 없는 건 다들 마찬가지던데, 일부러 그런 알바들로만 뽑는건가 궁금하네요^^', 52, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '그냥 싸가지가 졸라 없습니다. 괜히 기분 나빠서 하는 말이 아니고 요식업 운영했던 사람인데 내 가게에서 알바가 저딴식으로 굴면 바로 짜른다. 진짜 괜히 하는 말 아니고 알바를 다시 뽑든 시급을 더 주던 브랜드 이미지 망치지 말길 바랍니다.', 35, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '아이스크림 츄러스 포장이 안되는 거면 키오스크에서 포장으로 선택이 안되게 하면 좋을 거 같아요. 포장하고 기다리는데 다 나오고 나서야 포장안되니 그냥 들고가라고 해서 당황했네요.', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '먹느라 바빠서 사진찍는걸 깜빡ㅜ 더운날엔 달달한 츄러스를 아이스크림과 함께~~ 딱이네. 맛있지만 제입맛엔 역시 너무 달아서 다 먹진 못하고 1개사서 3명이 나눠먹었어요', 30, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '평일오전(수요일)머리염색하고쌍수붓기있는분너무불친절하네요.픽업장소를 헷갈릴 수 있는건데 오른쪽에서기다리라고 고래고래 소리치는거보고 어이가없었어요.본인이 하대받던 인생이라고 남들도 하대취급하지말아야죠.자기멋대로 영수증 안주길래 받아와서 이렇게리뷰써요.여긴 올때마다 다른직원분들도 친절한직원을본적이없어요.본점이면뭐해요 서비스가관리가 이렇게 안되는데.. 아이스크림도 어찌나 싼티나는맛이던지 일반 부드러운 소프트아이스크림이아니에요.', 51, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '츄로101 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), 'The churros are freshly fried-crispy on the outside, a little soft inside, but the filled ones are a bit too sweet for my taste. Worth trying once if you enjoy this kind of dessert.', 42, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '매장 - 홍대, 합정, 상수역 사이에 위치 / 대형 베이커리 카페 / 새벽 2시까지 심야 운영 / 층별 인테리어 1층은 숲속, 2층은 캠핑, 지하는 동굴 느낌으로 꾸며져 있어 사진 찍기 좋은 포인트가 가득 음식 - 커피는 고소한 맛, 산미, 디카페인 중 선택 가능 /  베이커리는 당일 생산·폐기 원칙으로 신선도를 강조 / 소금빵: 기대 보다는 맛있었고, 영수증 리뷰시 소금빵 1개 증정 이벤트 있어요. 후기 - 넓고 감성적인 인테리어 덕분에 분위기를 즐기기에 좋은 곳 / 커피는 평균적이나 빵은 괜찮은 편이고 다양한 할인 혜택이 있어서 괜찮네요. / 홍대 근처에서 독특한 분위기 찾는다면 들러볼 만한 곳', 55, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '일산 카페 느낌의 대형스.러.운.카페가 홍대에 있네요~~^^ 일산만큼 큰 카페는 아니지만 홍대의 아기자기한 느낌과는 사뭇 다른 시원시원한 카페입니다~ 다음에는  소금빵 꼭 먹어보려구요~~^^♡ 복층 계단 올라와서 테이블있구~ 지하에도 테이블 많아요~ 그리고 젤중요한 커피!! 아인슈페너와 라떼 주문. 👍👍👍👍👍 커피 맛있어요~ 아인슈페너  크림 진짜 부드럽. 쫀쫀~^^ 라떼는 커피가 진해 전 좋더라구요^^ (카페인에 취약하신분은 좀 힘들수도??)', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대 소금빵 맛집이라 재고소진되는 경우가 많더라고요ㅜ 항상 저녁에 퇴근하고 오면 없어서 점심시간 짬내서 왔는데 젤 좋아하는 맛 살 수 있어서 너무 좋았어요 🫶🏻 카페도 이쁘고 크고 분위기도 좋아요 직원분들도 상당히 친절하세요 🥰', 72, 16, 'GOOD', SYSTIMESTAMP);
