INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대에서 놀다가 늦게까지 하는 카페를 알아보면서 자주 방문하는 카페입니다 !!! 케이크도 정말 맛있고 음료도 정말 많고 이번에 테이블이랑 의자 배치도 바꿔서 더 쾌적한 느낌이에요 !! 더운 여름 시원하게 보내다 갑니다 !! 다음엔 낮에도 와보고 싶습니당 !!', 10, 9, 'GOOD', SYSTIMESTAMP);
