INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '감각적인 인테리어가 분위기를 더해주고 빵 커피가 너무 맛있어서 좋네요 👍 홍대에 이런 카페가 있다니 이제 여기만 올 것 같아요 ☺️☺️', 30, 1, 'GOOD', SYSTIMESTAMP);
