INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '너무 맛있고 분위기도 너무 좋아요 !!! 소금빵 종류도 많구(우유크림 소금빵 도랐어요;) 케이크고 맛있어보이더라구요 ! 지하랑 2층 앉을자리 많구 분위기가 상반되어서 더 좋습니다 !! 꼭 와보세용 !!❤️', 12, 10, 'GOOD', SYSTIMESTAMP);
