INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '오랜만에 왔는데 역시 맛있고 분위가 좋더라구여 지하부터 야외까지 대형카페여서 자주방문하는 곳이에요~ 빵도 가성비있게 맛있어요!! 잘 먹구 즐기다가요~', 6, 10, 'GOOD', SYSTIMESTAMP);
