INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '완전 소금빵의 성지 .. 다양한 소금빵들이랑 다양한 케이크까지 ..!! @@ 눈돌아가네요 시간도 늦게까지해서 이야기하고싶은 사람들에게 딱인 곳이에요 ♥️😘', 12, 6, 'GOOD', SYSTIMESTAMP);
