INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대에서 분위기 좋은 대형 카페 찾는다면 더블유오앤을 추천해요. 지하부터 2층까지 층별로 다른 분위기를 가지고 있어서, 원하는 무드에 맞게 자리를 고를 수 있었어요. 2층은 따뜻하고 포토존 같은 분위기라 사진 찍기 좋았고, 지하는 차분해서 공부나 작업하기에도 괜찮았어요. 날씨 좋은 날엔 테라스 자리도 추천! 베이커리는 종류가 다양했는데 특히 소금빵이랑 레몬 페이스트리가 맛있었어요. 빵이 전반적으로 퀄리티가 좋아서 커피랑 같이 먹기 딱이에요. 커피는 산미가 있는 편이라 취향에 따라 호불호가 갈릴 수 있지만, 깔끔하고 상큼한 맛을 좋아하는 분들은 만족하실 듯해요.', 13, 8, 'GOOD', SYSTIMESTAMP);
