INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '두번째 방문입니다 : ) 1층 2층 다른 분위기가 참 매력적인 카페예요! 디저트, 베이커리도 종류가 다양하고 맛있어요! 카공하실 분들은 2층 자리 추천드립니다 ㅎㅎ', 2, 6, 'GOOD', SYSTIMESTAMP);
