INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '여기 큰애랑 겨울에 길 지나다 눈여겨 본 곳이예요🌸 오늘은 막둥이랑 근처에서 옷 쇼핑하고 쉬어갈 겸 들렀어요👣 마침 지나는 길목에 보여 이번엔 들어가보자 했네요🤗 1층에서 주문 후 화장실 들를 겸 지하로 내려갔는데 bar 느낌이 나더라구요^^ 무대도 보이고요~ 2층은 캠핑카페 🏕 분위기네요^^ 아이가 맘에 들어한 2층에 자리잡고 앉아 쉬면서 폰도 보고 음료도 마셨어요^^ 소금빵 3가지 종류는 집에 있는 아이들 주려고 따로 포장했어요🛍  여기 배경음악 신나면서 차분한 분위기라 아이도 박자 맞추며 발도 까딱거리고 , 손으로 무릎도 치며 즐기더라구요🎶💕🌿 덕분에 덩달아 엄마인 저까지 미소 짓게 되네요🫶🥰 진심 편안한 분위기예요✨️🤳👍🫶🌿 단, 거울은 광나게 닦아주시면 좋겠어요😅 난간 유리두요✨️그럼 더 빛날듯해요', 42, 1, 'GOOD', SYSTIMESTAMP);
