INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '요즘 인플루언서들 사이에서 자주 보이는 감성 카페 더블유오앤(W.O.N) 다녀왔어요. 세련된 인더스트리얼 무드에 우드톤 조명이 어우러져 사진이 정말 예쁘게 나오는 공간이에요📸 아메리카노는 고소하고 깔끔했고, 초코라떼는 진하고 달콤해서 디저트 없이도 만족도 높았어요☕🍫 공간도 여유 있고 좌석 간격도 널찍해서 대화 나누기에도 딱 좋았어요. 분위기, 맛, 사진까지 다 잡은 곳. 감성 충전하고 싶은 날 강력 추천해요✨ 한 번 가보면 왜 인플루언서들이 자주 찾는지 바로 알게 될 거예요!', 9, 7, 'GOOD', SYSTIMESTAMP);
