INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '주차도 가능하고 케이크도 촉촉하니 맛있구요 분위기도 되게 캠핑온 것 같아서 좋았어요 ㅎㅎ 시그니처 커피 맛있으니 꼭 드셔보세요!!', 26, 4, 'GOOD', SYSTIMESTAMP);
