INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '매장이 엄청 넓고 우연히 들어왔는데 특색있는 메뉴도 많고 쾌적하고 좋아서 자주 올 것 같아요! 특히 컨셉츄얼한 좌석이 많아서 특별해요!!', 19, 6, 'GOOD', SYSTIMESTAMP);
