INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '지하층이 분위기가 엄청 좋아요 ㅎㅎ 커피도 맛있고 녹차라떼도 안달고 맛있었습니다🤭합정 데이트 올 때 자주 들러야 겠오요 ㅎㅎ담엔 빵이랑 케이크도 먹어보고싶어요💙', 6, 6, 'GOOD', SYSTIMESTAMP);
