INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '매장 정말 크고 이뻐요 2층과 지하 컨셉이 너무 달라서 다양한 분위기 즐길 수 있어서 좋네요 메뉴도 처음 보는 것들 많아서 신기해요 자주 애용할거 같아요', 1, 4, 'GOOD', SYSTIMESTAMP);
