INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '지하 공간 분위기 너무 좋고 편한 쇼파의자가 있어요. 커피도 산미있는 커피 맛있고, 디저트고 맛있어요. 중심가 옆에 대형 카페여서 너무 좋아요', 85, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '인테리어도 이쁘고 커피랑 디저트 맛집이에요! 당충전 제대로 하고 가네요 말차콜드브루먹었는데 말차크림 쫀득하구 위에 코코넛칩 토핑 짭짤해서 단짠 제대로에요 다음에 또 오고싶어요!', 47, 9, 'GOOD', SYSTIMESTAMP);
