INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '1층은 카페 지하는 칵테일바 느낌인데 분위기가 완전 달라요 ! 취향껏 이용하면 좋을 것 같고 늦은 시간까지 운영하고 칵테일도 팔고 주차도 가능해서 추천합니다 ㅎㅎ 인테리어가 예뻐서 사진도 잘 나와요 >_< 🩷', 66, 16, 'GOOD', SYSTIMESTAMP);
