INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '근처에 이쁜 카페가 있다해서 방문했어요! 조금 늦은 시간에 왔더라도 다행히 디저트도 종류가 남아있어서 소금빵 겟 했습니다!! 따뜻한 잔에 주는 음료도 양이 많아서 조아요~~ 분위기도 좋아요 지하랑 지상이랑 분위기 달라서 둘다 추천드려요!', 46, 10, 'GOOD', SYSTIMESTAMP);
