INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '예전에 한번 방문했었는데 카페 분위기가 좋았어서 오늘 또 방문했어요. 오늘은 맘모스 치즈케이크랑 따뜻한 아메리카노 주문했는데 여전히 분위기도 좋고 빵이랑 디저트 종류가 더 다양해진 느낌이에요! 다음에 또 방문할게요:)', 92, 19, 'GOOD', SYSTIMESTAMP);
