INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '분위기가 넘사에요🫶🏻🫶🏻 지하1층으로 왔는데 bar가 있어서 그런지 카페가 아니라 바에 온 기분이 들기도 해요! 소금빵은 담백하니 맛있어요. 아인슈패너는 크림이 저한텐 살짝 달았어요! 그치만 커피가 너무 맛있어서 잘 먹었답니다. 홍대에서 분조카 + 맛있는 디저트 찾는다면 추천해요 :D', 49, 6, 'GOOD', SYSTIMESTAMP);
