INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '층별 인테리어가 다르고 분위기가 달라서 좋았어요. 소금빵도 종류별로 맛나보여서 고르기 힘들었는데, 4명이서 가서 각각 다르게 골라서 다양하게 먹어봤어요 👍 커피도 직접 로스팅하는 것 같은데 🤔  향도 정말 좋았답니다.', 6, 10, 'GOOD', SYSTIMESTAMP);
