INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매장이 엄청 넓고 지상이랑 지하랑 분위기가 완전 달라서 신기해요! 디저트 종류도 짱많음...🐷 근데 케이크는 좀 아쉬웠어용 ㅠㅠ', 77, 14, NULL, SYSTIMESTAMP);
