INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대카페 쟈주가는데 큰 대형카페는 여기가 최고인거같아요 ㅎ 주말에는 주차도 가능하고 낮에오면 한적하니 여유롭게 커피한잔하기 넘 좋은곳이네요 ^^ 빵종류도 다양하고 드랍커피 맛있어요. 지하는 바 느낌의 상당히 세려되고 예쁜 카페네요', 94, 22, 'GOOD', SYSTIMESTAMP);
