INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '홍대 분위기 최고 카페에요! 지하는 약간 어둡고 바 같은 분위기, 지상은 탁 트인 분위기이고 빵도 엄청 많아요! 시그니쳐 음료 맛있고 직원분들 친절하십니다. ㅎㅎ', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '남자친구랑 같이 왔는데 카페도 엄청 크고 분위기도 좋아요~~~ 지하는 자리도 소파라서 엄청 편해요! 케이크도 완전 맛있고 음료랑 커피도 맛있어요~~', 27, 7, 'GOOD', SYSTIMESTAMP);
