INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '커피도 시그니처 메뉴가 독특해서 좋았고 빵이랑 케이크들이 다 맛있어 보였어요! 매장이 넓고 쾌적해서 대화나누기 좋은 곳 같습니다 :D', 25, 7, 'GOOD', SYSTIMESTAMP);
