INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '커피맛 : 보통 케잌 : 보통 가성비 : 중하 서비스 : 불친절 혼자 카페가는걸 좋아하는 편인데 혼자가긴 안좋은 곳 바빠서 그런건 이해하는데 오늘 낮에 일하신 남자분은 뭔가 일에치여 대답에 궈찮음이 묻어있음.리뷰이벤트 한다는데 구조상 손님이 찾아가서 말해야하는데... (결국 못 받았음..??) 커피는 원두선택이 가능하긴 한데 그런거 치곤 원두의 맛을 살린건지는 의문이 들정도의 평범한 맛. 케익은 홍대 평균 가격에 평균적인 맛. 가성비는 떨어지는데 주변 상권이나 인테리어 생각하면 평균적인가격 같은데 인테리어가 호불호가 좀 갈림.', 40, 2, 'BAD', SYSTIMESTAMP);
