INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '인테리어도 너무 예쁘고 대형 카페라서 밝은 분위기, 어두운 분위기 모두 즐길 수 있어서 좋았어요:) 늦은 밤에 방문하게 되었는데 시그니처 커피도 맛있고 주차도 가능해서 만족합니다. 다음에 또 방문할게요😊', 36, 5, 'GOOD', SYSTIMESTAMP);
