INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '홍대 오시면 한번쯤 들려보시길 추천 드리는 카페예요 :) 시그니처 메뉴도 다양하고 디저트는 말모말모 눈이 너무 즐겁고 맛까지 보장되어 있어요❤️ 지하 매장은 어둡고 펍 같은 분위기에 계단 위 층은 캠핑 컨셉의 조용하고 아늑한 분위기라 어디에 앉을지 선택하는 재미도 있어서 좋아요! 늦게까지 영업하는 카페라서 부담없이 앉아있다가 가기 좋습니당 강추해요🫶🏻', 93, 23, 'GOOD', SYSTIMESTAMP);
