INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '카페 알아보다가 분위기가 좋아보여서 왔는데 소금빵 맛집이었네요!! B1/1/2층 있구 지하랑 1/2층이랑 분위기가 상반이라 반전있어서 재밌어요~! 커피맛도 맛있길 기대◡̈', 68, 16, NULL, SYSTIMESTAMP);
