INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '1층하고 지하하고 분위기가 달라요! 넓고 좋어요오🎀 몇 번 와봤는데 올 때 마다 좋아여..음료도 맛있고 빵도 맛있어요:) 소금빵은 당연히 맛있고 블루베리 페스츄리가 진짜진짜 맛있어요...제발 드셔보시길 🫐ㅎㅎ', 30, 10, 'GOOD', SYSTIMESTAMP);
