INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '지난번 방문 후 분위기도 좋고 커피도 맛있어서 또 왔어요. 커피도 원두 선택 가능한데 고소해서 맛있고 빵도 종류가 많아요. 분위기도 좋은 것 같아요 :)', 34, 10, 'GOOD', SYSTIMESTAMP);
