INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '정말 맛있어요. 분위기도 너무 좋고 원두도 고를 수 있어서 좋은 것 같아요. 사장님이 친절하시구 소금빵 종류가 엄청 많은데 맛 별로 고를 수 있어서 좋은 것 같아요. 전 피스타치오랑 잠봉 했는데 단짠이 아주 좋았어용 🫶🫶 또 오고싶어요', 37, 10, 'GOOD', SYSTIMESTAMP);
