INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '기분좋게 일요일 저녁에 공간이 이쁜 카페를 찾다가 방문 했습니다 디저트 고르고 계산 하려고 카운터로 갔더니 여자 직원분이 포스키앞에서 뭘 정리 하시는지 저희를 쳐다 보시지도 않으시고 그냥 기다리라고만 하시고 ㅜ옆에 계시던 남자 직원분이 도와 주시려다가 포스 뭘 잘못 누르셨는지 저희 앞에서 여자 직원분이 그분께 화를 ...저희가 다 혼나는거 마냥 눈치보였습니다 ㅋㅋ셋이가서 디저트도3개에 음료2잔 시켰는데 음료는 꼭 1인1음료를 해야 한다하고 이럴줄 알았으면 굳이 여기 안왔을텐데요 ;; 정말 기분 좋지 않은 응대를 받아서 다신 여기 안옵니다 지인들에게도 가지말라고 말리고 싶을 정도네요', 26, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '카페의 쾌적한 느낌이 너무 좋아요!! 빵도 여러종류 있고 커피도 괜찮아요. 인테리어가 정말 맘애들어요!! 잔디밭?이 꽤나 이쁩니다 ㅎㅎ', 27, 2, 'GOOD', SYSTIMESTAMP);
