INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '지인짜 좋아요👍👍👍👍 보통 홍대카페들은 오래 못 앉아 있게 의자가 불편한 경우가 많은데 쇼파자리, 일반자리 등 자리 구성이 다양하게 있어요. 음식들이 사알짝 단가가 있어도 먹으면 그런 생각 싹 사라져요!! 크림도 휘핑크림이 아니라 생크림이어서 크림이 많이 있어도 하나도 안 느끼하고 진짜 맛있게 먹었어요😋 커피도 원두 선택할 수 있고 음료도 진짜 다 맛있어요!!!👍👍 또 제일 좋은 게 위생적이에요✨ 빵에 다 케이스 씌워나서 위생걱정없이 먹을 수 있어요! 분위기! 맛! 위생! 뭐 하나 빠짐없으니까 꼭 와보세요!!👍👍👍⭐️', 8, 1, 'GOOD', SYSTIMESTAMP);
