INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 라운지'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '그냥 커피나 마시러 들어간건데 모두가 기타를 치고있고…. 공연을 보러 가는 곳인가봐요… 신기한 분위기라 친구들이랑 당황했어요 .. 그치만 다들 멋져보였습니다 ..', 72, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 라운지'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '음료와 디저트의 맛은 말할 것도 없이 훌륭하고요 매장 분위기가 정말 좋아요! 조용하고 차분하니 에너지 충천하고 갑니다! 그리고 음악 플리가 정말 좋아서 추천드려요🥰🥰', 8, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 라운지'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '크로플이 맛있어요! 음악다방이라 그런지 스피커 음질도 좋고 인디음악이 주로 나오는데 카페 분위기랑도 잘 어울려서 맘에 들어요ㅎㅎㅎ', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 라운지'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '새리를 직접 만나서 보고 가까이서 그녀의 노래를 들을수있어서 정말 행복한 시간 이었습니다. 앞으로도 이런기회가 많았으면 좋겠어요~', 61, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 라운지'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '오늘 로즈마일 님 공연 처음 보는데, 제가 좋아하는 밀크티(잉글리시 브렉퍼스트 베이스)도 아주 맛있었어요. 그분 공연도 기대 이상이었습니다.', 96, 26, 'GOOD', SYSTIMESTAMP);
