INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '젤라또 먹고 싶어서 급 방문 했는데 사장님도 친절하시고 맛있어요 ! 티라미수가 제 최애예요 👍👍 케이팝 데몬 헌터스에 나오는 호랑이 발바닥 아이스크림? 같은것도 있는데 소다맛 추천드려용😋', 353, 79, 'GOOD', SYSTIMESTAMP);
