INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대 젤라또 맛집은 진짜 무조건 여기🫶 매일매일 다양한 맛의 젤라또가 나오는데 진짜 다 맛있어요 사장님도 정말 친절하셔서 밥 먹고 후식으로 먹기 딱이에요 제 추천은 리조! 달달하면서 담백한게 딱입니다 사장님 번창하세요😍', 45, 6, 'GOOD', SYSTIMESTAMP);
