INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '언제 먹어도 맛있는 아라또!! 수박맛이 새로 나왔길래 먹어봤는데 진짜 시원한 생 수박 먹는 것 같아서 행복했어요 최고최고 😄👍👍👍', 47, 7, 'GOOD', SYSTIMESTAMP);
