INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '다 맛있어 보여서 고르기 너무 어려웠어요… 두 가지 맛 골랐는데 위에 스푼으로 다른 맛도 맛보게 해주신 거 너무 센스 짱짱😍 다음에는 다른 맛 도전하러 올 거예용', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대에서 여기가 젤라또 제일 맛있어요 🫶 무슨 맛 먹을지 고민돼서 사장님께 핑크슈크림은 무슨 맛인지 여쭤봤는데, 바로 맛보기 스푼으로 한 입 맛볼 수 있게 해주셨어요🥹 진짜 사장님 정말 친절하세요 냥발도 아삭하고 시원해서 슬슬 더워지는 날씨에 진짜 딱입니다 저는 리조 맛이 최애였는데, 오늘 먹고 핑크슈크림이랑 얼그레이에도 입덕했어요😍😍 다들 꼭 방문해보시길!!!', 65, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '너무 맛있는 디저트였어요!! 사장님께서 센스도 있으셔서 맛보기 스푼에 다른 맛 주셨어요!! 사장님 많이 파세여~~^^ 냥발 토핑도 시원하고 맛있어요!!', 77, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '서울 여행하면서 젤라또 먹고 싶어서 왔어요 맛도 여러가지 있고 다 맛있어 보여서 고르는데 시간이 좀 걸렸는데 그 시간이 아깝지 않은 맛이었습니다!!! 정말 맛있어요😋', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '너무 귀엽게 만들어서 주시고 딸기랑 초코가 맛있어욯ㅎㅎㅎㅎㅎㅎㅎ 그리고 늦게까지 해서 너무 좋네요 안에 자리 조금 있어서 앉아서 먹고 갈 수도 있어요', 120, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '사장님과 직원 분이 너무 친절하십니다. 이것저것 여쭤봐도 엄청 친절하게 답변해 주세요. 그리고 더워서 둘 다 과일맛으로 주문했는데 진짜 과일 먹는 것 같아요. 복숭아가 특히 맛있어서 다음에 또 오려고요!', 81, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '리조 젤라또를 좋아해서 다녀왔는데 달달하니 맛있어요 쌀도 적당히 씹히네요 서비스로 냥이 발바닥 주신 것도 너무 귀여워서 아이가 좋아하네요 다음에 또 올거 같아요', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '예전에 지나가다가 더피를 발견했는데 오늘 와서 먹어보네요!! 너무 귀엽고 제가 좋아하는 패션후르츠까지 있어서 너무 좋았어요!! 친구들이랑 놀러올때마다 방문할것 같아요!', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '사장님 정말 친절하세요!! 젤라또도 너무 맛있어요👍🏻 스푼에 맛보기로 주신 멜론 맛이 너무 맛있어서 다음에 또 올 것 같아요🍨', 89, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '생일 카페로 왔었는데 너무 맛있어서 두번째 방문이에요!! 젤라또도 정말 맛있는데 새로 나온 냥발은 맛있고 너무 귀여워요ㅠㅠ💕 재재방문 하겠습니다!! (하룰랄라 가요🪽)', 56, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '케데헌 보시냐고 여쭤보셔서 봤다하니 블루냥발이! 저게 서비스였어요 최고다ㅠㅠㅠ 맛도 맛이지만 서비스 좋아서 더 즐거웠네요 감사합니다', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '아이랑 홍대 나오면 꼭 들르는곳이예요!! 젤라또 아이스크림두 맛있구 더피 발바닥두 넘 귀엽구 사장님두 친절하시구 넘 좋습니다!! 꼭 드셔보세요~^^/', 86, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '사실만 작성합니다 쭈꾸미 먹고 아이스크림 땡겼는데 젤라또가 눈에 들어왔습니다 초코+딸기요거트+콘으로 주문했습니다 아이스크림 받고 나와서 한 입 먹고서 쎄했습니다 젤라또라고 하기 민망할 정도로 부드러운, 녹은 상태였기 때문입니다 딸기요거트는 매장에서 나오자마자 녹아서 흐르기 시작했고, 초코는 그나마 상태가 나았지만 30초 뒤부터 녹아내려 콘을 잡은 제 손으로 뚝뚝 떨어졌습니다. 여자친구와 저는 위에 있는 딸기 요거트를 최대한 빨리 해치웠지만, 손에 떨어지는 초코에 기분이 너무 안 좋았고, 녹아서인지 기분이 안좋아서인지 맛있다고 느끼지도 못했습니다 그래서 매장에서 역으로 가는 길에 넓은 광장에 있는 쓰레기통에 버리고 역 화장실에서 손을 씻었습니다 제가 방문한 오늘만 그랬을 수도 있겠지만 앞으로 다시는 안갑니다', 30, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아이스크림이 너무 맛있습니다. 저희가 프랑스와 스페인 여행했을때 젤라또 자주 사먹었는데, 현지서 먹는맛과 비슷했어요. 아이랑 맛있게 먹을수있어 좋았고, 가격도 비싸지않아 좋았습니다. 다음번에 재방문의사 있습니다. 강추하고 갑니다. (아이들이 감탄하며 먹네요. 순삭이라고^^)', 29, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '사장님이 진짜 너무너무 친절하세요~🥹👍 원래 리뷰 쓰는거 귀찮아서 진짜 안하는 편인데 여긴 정말 강력 추천합니다 무엇보다 젤라또 진짜 맛있고 맛도 매번 다르게 나와서 골라서 먹는 재미가 있어요 진짜 일주일에 한번은 생각남🫶 사장님 부자되세요 사랑해요😍😍', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '매장 생긴 이후로 매주 가는 저의 맛집 😋 동물이 먹어도 될 정도로 찐 과일로만 만들어서 맛도 좋고, 건강에도 좋더라구요 겨울에 먹어도, 여름에 먹어도 좋아요 👍💕💕💕', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '진짜 맛있는 아이스크림이에요. 재료 본연의 맛이 정말 잘 살아있고 그리 달지 않아서 좋습니다. 사장님께서 재료를 진짜 잘 살리시는 것 같아요. 호텔 뷔페 아이스크림보다 맛있어요. (real) 다음에 또 들릴 예정입니다. 👍👍', 22, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '사장님이 젤라또에 진심이셔서 주기적으로 맛이 업데이트 되는 곳 참외, 수박, 맥주, 복분자, 방울토마토 등등 🍧리조 _ 우유 베이스에 쌀알이 톡톡 씹혀 마치 밥을 먹는 듯한 느낌이 들었어요 아이스크림을 씹으며 먹을 수 있다니!! 저의 원픽은 리조 🍧로투스 _ 로투스 과자 맛을 그대로 젤라또로 옮겨온 맛, 함께 주는 로투스 과자와 먹으면 당충전 제대로! 꺄륵 행복해지는 당충전 🍧얼그레이 _ 공차 타로 맛이 딱 연상되어요 보라빛깔인게 신기합니다. 달달한 맛 🍧제주감귤 _ 여기서만 맛볼 수 있는 유니크한 맛이 아닐까요? 귤맛이 느껴지는 주황빛 젤라또 🍦포토리뷰 시, 귀여운 고양이 발바닥 모양의 토핑을 주신답니다 🍦편하게 먹으라고 위생 손장갑 주시는 센스! 맛보기 하라고 한 스푼씩 다른 맛 얹어 주셔요', 22, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '아이스크림 가게 찾다가 느낌이 꽂혀서 들어왔는데 너무 맛있게 잘먹었습니다 ㅎㅎㅎㅎ 개인적으로 쌀 들어간게 맛있더라구요, 맨위에 살포시 올려주신 로투스맛? 그거 진짜 맛있었어요  단거 좋아하는 입장에서 그건 진짜 불꽃놀이 같은 즐거운 맛이었어요', 61, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '초코, 리조, 망고, 녹차+딸기 다 맛있었어요 ! 하이디하오 훠궈랑 가까워서 훠궈먹고 입가심으로 굿 ! 늦은시간까지 영업해서 좋았습니다! 사장님도 친절하시고 귀여운 피규어들도 많았어오 ㅎㅎ', 19, 3, 'GOOD', SYSTIMESTAMP);
