INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '젤라또가 이렇게 재밌는 음식이었다니🤗 ❤️젤라떼리아 아라또❤️ 홍대역에서 조금만 가게 구경하면서 걸어가다보면 금방 나와서 엄청 접근성이 괜찮더라고요ㅎㅎ 홍대에서 밥먹고 디저트 먹고싶은데 어디로 가지?? 홍대에서 예쁘고 맛있는 디저트 먹고싶은데 어디로 가지?? 👉 젤라떼리아 아라또~~~~~ 사장님이 진짜 작정하고 많이 퍼주셔서 이러시면 너무 오예😄😍 2가지맛이 5천원??! 대박이에요~~~ 홍대에서 이런 가성비맛집을 발견하다니!!! 게다가 맛있기까지해요❤️ 맛도 다양하고 각자 맛볼 수 있게 맛보기스푼도 흔쾌히 해주시고~~~ 냥발또도 우유랑 딸기맛이 진하게 잘났어요~~ 서비스로 스푼에 다른 맛도 잔뜩 올려주셨어용ㅎㅎ 진짜 대박이에요 다음에 또 오려고요! 홍대오면 백퍼 생각날 거 같은 집🤗', 24, 3, 'GOOD', SYSTIMESTAMP);
