INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '귀염뽀짝한 젤라또 가게가 있다는 소문을 듣고 방문했습니다. 우선 가게 인테리어가 넘 귀여웠어요!! 무엇보다 젤라또를 엄청 많이 담아주시더라고요… 위에 토핑이랑 맛보기 다른 맛도 같이 올려주셔서 좋았어요!!!!! 👍🏻 넘 맛있게 잘 먹고갑니다 :D', 16, 4, 'GOOD', SYSTIMESTAMP);
