INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대젤라또맛집 젤라떼리아 아라또에서 두가지맛 젤라또 세 컵이랑 냥발또 2개 맛보고 왔어요! 친절하신 사장님 혼자서 운영하시는 가게인데 다양한 맛의 과일 재료 듬뿍 들어간 젤라또를 맛 볼 수 있는 곳입니다 데이트 마무리코스로 들리기 좋고요! 댕댕이랑 산책나와서 같이 간식 먹으러 잠시 들러도 좋아요! 과일맛은 물과 과일만 들어가서 댕댕이도 먹을 수 있어요~! 추석때는 흑임자 수정과 땅콩 밤과 같은 추석이 생각나는 추석스페셜 메뉴들도 준비중이라고 하시는데 진짜 젤라또에 진심이신게 팍팍 느껴지더라고요! 라즈베리 리쪼 황치즈 로투스 맛보고 왔는데 새콤달콤 씹는 식감 재밌는 라즈베리랑 리쪼 너무 취저였어요 짝꿍이 맛본 로투스랑 황치즈도 너무 맛있다고 한컵 더 먹고 왔네요 다음에 홍대 오면 꼭 또 들를거에요~~!', 45, 5, 'GOOD', SYSTIMESTAMP);
