INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '사장님과 좋은 기회로 이벤트도 진행 했는데 내돈내산으로 계속 사먹을 정도로 넘넘 맛있어요 젤라또 두가지 맛을 5천원에?? 다들 꼭 사드세욘♡', 98, 22, 'GOOD', SYSTIMESTAMP);
