INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '진짜 너무 더워서 쓰러지기 직전에 들어갔어요ㅜㅜ 맛집 찾아가다가 중간에 쓰러질 것 같아서 들어간거라 많이는 못 시키고 둘이서 기력 회복할 정도로만 두가지맛 5000원짜리 시켰어요 근데 사장님 너무 친절하시고 젤라또도 특이한 종류가 많았어요!! 죠리퐁이랑 오레오 시켰는데 추석이라고 저렇게 추가 토핑을 마니 주셨어요!! 일단 죠리퐁맛 진짜 최고예요 너무 맛있어요 ㅜㅜ 그리고 추가로 주신 보리과자도 너무너무 맛있게 먹었어요 ㅜㅜ 줄줄이 손님들 계속 많이 오던데 원래 잘 되는 곳인 것 같아요 짱짱!!', 35, 6, 'GOOD', SYSTIMESTAMP);
