INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '들어가자마자 사장님께서 친절하게 맞아주시고 메뉴 설명도 해주시면서 한입 맛보기도 하게 해주셨어요!! 매장이 산리오로 꾸며져 있어서 산리오 좋아한다고 하니까 귀여운 산리오 스티커도 엄청 많이 주셨어요💗! 젤라또 양도 컵이 터질만큼 주셔서 엄청 맛있게 먹었습니다아!! 홍대에 올때마다 방문 하려구요 !! ㅎㅎ 꼭 가보시길 추천드려요˚₊·—̳͟͞͞♡', 15, 4, NULL, SYSTIMESTAMP);
