INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '고양이고 좋아하고 아이스크림도 좋아하는 딸내미 취향 제대로 저격한 젤라또 가게 지나가다가 눈에 딱 띄어서 들어갈 수 밖에 없었어요. 인테리어도 넘 귀염뽀짝해서 여기저기 사진찍고 재미있었어요. 냥발젤라또 토핑도 넘 맛있어요!!😋😋', 23, 6, 'GOOD', SYSTIMESTAMP);
