INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사장님 친절하심에 무조건 재방문할 거예여 -! 맛도 맛있지만 양두 넘치도록 담아주시고 한분 한분 응대하시는 모습이 참 좋으셨어여 번창하셔유🍀', 409, 81, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '시원한 게 먹고싶어서 찾아보다가 온 곳인데 젤라또 너무 맛있어용 .. 🥹 오레오랑 밥맛 먹었는데 둘이 잘 어울리고 쌀알 씹히는게 예술이에요 ₊˚⊹♡ 완전 추천합니다 사장님도 엄청 친절하셔요 담에 홍대 오면 또 방문할게요 번창하세요!!', 0, 8, 'GOOD', SYSTIMESTAMP);
