INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대, 연남동에서 꼭 한 번 먹어봐야 할 젤라또 맛집! 사장님이 젤라또에 진심이시고 정말정말정말 친절하세요! 궁금한 맛 있으면 맛보기 스푼으로 맛 볼 수도 있고 갓 새로 만든 젤라또가 있는 날은 사장님이 먼저 권해주세요. 양도 엄청 많고 재료 본연의 맛이 살아 있어서 씹히는 맛도 젤라또 맛도 예술입니다. 냥발또는 샤베트 느낌이고 적-당히 달아서 크리미한 젤라또와 정말 잘 어울렸어요! 저희 부부는 비 오는 날 가게 앞에 앉아서 먹었는데 정말 운치있고 여유로웠습니다. 과일맛이 진한 젤라또 맛집으로 추천드립니다!', 13, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '무더운 여름 길거리 헤매다 발견한 조그마한 젤라또집 여름에 과일류도 좋지만 티라미수 맛이 진짜 티라미수 그대로 젤라또화한 맛으로 맛있었다', 291, 79, 'GOOD', SYSTIMESTAMP);
