INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '우리 동동이 젤라또 포식하고 온 날❤️ 댕댕이를 너무나 예뻐해주는 사장님께서 강아지가 먹을 수 있는 젤라또 퍼주세요 👍 (우리 동동이 두컵이나 먹은 건 안 비밀) 젤라또 진심 너무 상콤하고 맛있어요🥹 완전 감동의 맛! 특히 과일류가 새콤달콤하니 제 입맛에 딱이었어요. 망고사고는 처음 먹어봤는데 요즘 10대들한테 핫한 음료이더라구요?! 달달한 망고 우유 느낌이라 술술 넘어가구❤️ 요즘 커피 줄이느라 커피 안마시고 젤라또랑 망고사고 먹었는데 완전 성공❤️', 22, 0, 'GOOD', SYSTIMESTAMP);
