INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '맛있는 디저트를 늦은시간까지 즐길수 있는곳! 주문즉시 잘라내는 망고와 진한맛으 젤라또까지 홍대에서 디저트가 생각날 땐 아라또죠 젤라또 위에 올라간 냥발또는 진짜 시선강탈 사진 찍기에 좋은 귀여운 인테리어까지 최고입니다.', 77, 13, 'GOOD', SYSTIMESTAMP);
