INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '더워서 가까운 매장 들어온건데 젤라또도 맛있고 올려주시는 데코들이 너무 귀여워요 저 냥발도 맛있는 하드같은 아이스크림이에요 다음에 또 생각나면 들를 것 같아요', 32, 8, 'GOOD', SYSTIMESTAMP);
