INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대 젤라또맛집 젤라떼리아아아아아아아라또💛 사장님 너무 친절하시고 귀여운 소품들이 한가득! 젤라또 먹고싶을때 무조건 여기로 와요! 사장님 적게 일하고 많이 버세요~!!🤑', 41, 2, NULL, SYSTIMESTAMP);
