INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '여러분 여기 젤라또 왕 맛집이에여!!! 그리고 과일맛들 진짜 맛도리니까 꼭 드셔보세용! 방토맛이 있다면 방토는 무조건 입니다ㅎㅎ 냥발또도 쫀딕~ 하니 맛있었어요><', 43, 7, NULL, SYSTIMESTAMP);
