INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '다양한 맛이 있어서 결정 장애가 왔을 때 사장님이 막 서비스로 조금씩 얹어주셔서 다양하게 먹고 왔어요ㅠㅠ 냥발 젤라또 까지,,,! 진짜 맛있구, 저렴한데 양도 많이 주시구 잠깐 앉아서 먹고 갈 수 있어용 ㅎㅎ 재치만쩜 쿨가이 사장님 또 봬요 !!😋🍨', 31, 10, NULL, SYSTIMESTAMP);
