INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '와 홍대아이스크림 맛집이에요 존맛🍦 스푼맛도 다른 맛으로 주고 과자도 올랴줘요 소금우유랑 얼그레이맛인데 컬러도 조화롭고 맛도 조합이 기가막혀요🩷', 2, 4, NULL, SYSTIMESTAMP);
