INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '인테리어 너무 귀여워용 고양이 피규어들이 여기저기 전부 제가 데려가고싶네요 ㅎㅋ 젤라또도 다크초코랑 쌀먹었는데 넘 맛있어오 쌀 씹히는게 이색적~ 블루베리랑 파인애플도먹었는데 블루베리가 건강맛이라 건강스타일 좋아하면 추천 술맛도 있다고 하시던데 넘 궁금 담에 오면 먹어봐야겠어요! 위에 올라간 고양이 발바닥 아이스크림도 맛있는데 기여운 느낌 디저트라 눈 호강하며 먹었어요 🐈', 75, 17, 'GOOD', SYSTIMESTAMP);
