INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '젤라또 너무 맛있어요! 맛 종류도 다양하고, 올려주시는 발바닥 토핑도 너무 귀여워요 가게도 깨끗하고 사장님도 너무 친절하시네요 !', 22, 5, NULL, SYSTIMESTAMP);
