INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '날씨 좋은 날 진짜 맛있게 먹었습니다!!갓나온 애플망고 너무 부드럽고 맛보기해서 확실히 제가 먹고싶은것들을 고를 수 있었어요!근데 사실 다 너무 맛있겠어서 고르기 어려운 게 함정.. 과일빙수파여서 애플망고랑 파인애플 먹어봤는데 파인애플은 과육까지 씹혀서 진짜 너무 맛있었습니다!!애플망고는 쫀득보다는부드러운 젤라또고 망고맛 진짜 제대로나서 너무 맛있게 잘먹었어요💖💖👍두개고르고나서 다른맛도 골라서 스푼으로 올려주시는데 그 점이 진짜 너무 좋은거같아요!!다양하게 원하는 맛 많이 맛볼 수 있어서 좋았습니다. 재방문 의사 매우 🔥🔥🔥있고 다음엔 로투스아니면 오레오 도전해보려구용', 113, 22, NULL, SYSTIMESTAMP);
