INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대에서 맛있는  아이스크림 먹고 싶어서 찾다가 발견한 홍대 젤라또 맛집이에요!! 다크초코랑 라즈베리, 패션후르츠가 특히 맛있었습니다!! 인테리어도 귀엽고 복권이벤트도 하고 있어서 데이트하기 좋았어요 ㅎㅎ', 52, 13, 'GOOD', SYSTIMESTAMP);
