INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대에서 먹은 젤라또 집 중 가장 친절하고 가장 맛있어요!!! 저 강아지 발바닥도 아이스크림인데 존맛.. 맛보기 스푼도 듬뿍 주시고 술종류 아이스크림도 있는데 이게 넘 존맛..다음에 매화수 먹어야지...홍대젤라또맛집 왕추천 ⭐️⭐️⭐️⭐️⭐️', 67, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '사장님 양을 정말 많이주세요!! ''남는게 있으실까?'' 생각이 들정도로 많이 주세요~ 2가지 맛을 골라야 하는데, 다양한 아이스크림 종류로 무얼 먹을까 고민하고 있었는데, 사장님께서 적극적으로 ''맛보기''도 있으니 다 먹어봐도 된다며 맛보기 체험으로 모든 맛을 다 먹어봤네요!! 이렇게 먹는데도 오히려 더 적극적으로 마음껏 먹어봐도 된다고 하시고!! 너무 너무 친절하셔서 감동했습니다!! 사장님께서 서비스로 1스푼 더 다른 맛도 주시고, 고양이 발바닥 아이스크림도 주셔서 정말 맛있게 먹었습니다~~!!😆😆 그리고 사장님 센스가 대박인게, 고양이 발바닥 아이스크림 편하게 먹을 수 있게 손가락 비닐장갑도 주셔요! 👍👍정말 손님을 생각하시는 디테일에 감동받고 갑니다~!! 모두들 여기서 꼭 젤라또 아이스크림 드세요~👏👏', 75, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '사장님 완전 친절하시고 맛 두가지나 서비스 주시고ㅠㅠ 5천원의 행복이에요ㅠㅠ 아이스크림도 서비스로 하나 주셔서 너무 잘 먹었네요 감사합니다', 48, 5, 'GOOD', SYSTIMESTAMP);
