INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '맛이 다양하고 제가 알던 젤라또 가격보다는 엄청 가성비가 대단해요!! 그리고 영수증 리뷰 남기면 귀여운 고양이 아이스크림도 주니까 꼭 참여하세요! 술이 섞인 메뉴도 있어서 신박하고 맛도 생각보다 어울렸어요!', 49, 0, 'GOOD', SYSTIMESTAMP);
