INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '음주 한바탕 즐기고 나면 아이스크림국룰! 생각치 않았던 바나나도 맛있었고 무엇보다 🔥음주 후 패션후르츠맛🔥 완전 맘에들어! 새콤해서 소화제 그자체👏🏻 사장님 정말 친절히 맞이해주셔서 감사했습니다!! 그리고.. 너무 신난바람에.. 소란스럽게 다녀간점.. 죄송합니다..🤣', 87, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대입구역 골목에서 넘 귀여운 젤라또 발견했습니다! 귀여운 고양이 발바닥 아이스크림까지 토핑으로 올려주시는 한 컵 가득 두가지맛에 맛보기까지 올려주셔서 좋았어요! 사장님도 친절하시고 젤라또 비쥬얼도 사진찍기 좋았어요', 9, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '사장님이 엄청 친절하고 유쾌하세요!! 고양이 모티브 인테리어와 데코들로 가득한, 고양이 좋아하시는 분들이라면 지나칠 수 없는 곳!! 젤라또 위에 올라간 냥발바닥이 포인트!! 냥젤리 모양과 입술, 바나나 모양의 데코 젤라또까지 너무 귀여워요ㅠㅠ 냥젤리 젤라또는 존예인데 맛도 있어요. 입에 넣는 순간 너무 상큼합니다ㅠ 입술모양은 라즈베리, 바나나모양은 바나나킥 맛이었어요ㅎㅎ 젤라또는 딸기, 수박, 초코, 리조 4가지 맛 먹었는데 4가지 맛 다 너무 맛있어서 순삭했네요. 여태 먹어본 젤라또 중에 젤 이쁘고 젤 맛있어요. 냥이들로 가득한 인테리어도 넘 이쁘고 다른맛들 먹으러 또 갈거에요. 홍대 데이트로 강추입니다.', 26, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대서 우연히 발견한 젤라또 아이스크림 맛집입니당👍 감귤&오레오 맛으로 먹었는데 둘 다 맛있었어요 고를때 고민을 많이 하니까 사장님께서 맛보기 스푼으로 맛보게 해주시고 너무 친절하셔서 리뷰를 안쓸수가 없었습니다…🫶 서비스로 냥발바닥모양 슈크림 빵도 주셔서 감사합니다ㅎㅎ🥰 친구꺼 먹어보니깐 쌀밥맛과 다크초코맛이 꾸덕하고 맛있었어서 다음엔 그걸 먹으러 가보겠슴당ㅎㅎ 번창하세요!!🙇‍♀️', 82, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '기대 이상으로 푸짐하고 토핑도 다양하게 듬뿍 올려 주셔서 좋아요 아치 생과일쥬스 얼린것처럼 상큼해서 건강한 맛을 즐길수 있어요', 84, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '쌀맛이랑 로투스맛을 주문했는데 위에 과자도 같이 올려주셨습니다. 쌀이 톡톡 씹히는 느낌이 일품이며, 다음에 와서 다른 맛도 골라볼 예정입니다.', 36, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '젤라또 컵 선택하면 2가지맛 맛볼 수 있어요 그리고 스푼에 다른맛 맛보기용으로 같이 주시는데 사장님 센스👍👍 하나는 오레오랑 리조 주문했는데 역시 맛있는 조합!! 다른하나는 레몬이랑 별빛청하했는데 둘이 섞어먹으면 상큼달콤', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '사장님도 친절하시고 젤라또도 너무 맛있었어요❤️ 진짜 나만 방문하고싶은 그런 편안한 젤라또집❤️ 라즈베리랑 패션후르츠 진짜 최고에요😍', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '젤라또 땡겨서 젤라떼리아아라또 방문했어용. 겨울이어도 젤라또 땡기면 먹어줘야되니깐*^^* 과일이랑 쌀맛 등 종류 다양했고 매장에 앉을 곳도 많아요! 조아용', 109, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대입구역에서 가까운 젤라또 가게 젤라떼리아아라또에서 참외&리조 먹었어요. 참외맛이 여름맛으로 딱 좋았어요. 건강하게 만든 거라 반려견도 먹을 수 있다고하니 강쥐랑 방문해도 좋을 것 같아요. 녹아내리는 콘 고양이들이 반겨주는 홍대 아이스크림 가게 아라또. 귀엽고 맛있어요.', 41, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구랑 젤라또 먹고싶어서 들렸는데..,젤라또 맛집이였음 귀여운 고양이 발바닥..,,아이스크림도 얹어주시고! 서비스로 맛보기도 해주시고! 사장님이 친절하시고 설명도 잘해주십니다! 귀여운 젤라또 먹으면서 수다떨기도 좋은 공간이 안밖으로 있고!! 종류도 다양하고 신기한메뉴도 많아서 더욱 좋아요!! 홍대에서 젤라또^^이집이쥬', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '젤라또 정말 맛있어요! 홍대 골목에 위치한 작은 젤라또 가게에요. 제가 워낙에 아이스크림을 좋아해서 자주 먹는데 아라또에서는 수박이랑 리쪼 추천합니다. (수박,딸기와 오레오,리쪼 먹었어요!) 젤라또 위에 귀여운 고앵이 발비닥 올려주는데 우유맛 나는 아이스크림이에요. 맛있어요. 수저로 먹기 불편하다며 사장님께서 손가락 장갑 챙겨주셔서 덕분에 잘 먹을 수 있었어요. 그리고 작은 미니콘도 올려주셔서 젤라또 올려 먹었더니 콘 아이스크림 됐습니당ㅋㅋ젤라또 종류도 많고 브랜드 매장에서 하는 것 처럼 맛보기 서비스도 하고 있어서 좋았어요. 근처에 식당이랑 술집이 많아서인지 늦께까지 영업하셔서 집에 가기 전 들르기 좋을 것 같아요!', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '다크초코랑 코코넛 맛 먹어봤는데 진짜 맛있고 양이 많아요!! 친구가 주문한 로투스 맛도 먹어봤는데 그것도 맛있어요!👍 그리고 사장님이 친절하세요 새로 만드신 핑크솔트 맛도 먹어보라고 주셨어요✨', 47, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '젤라또 좋아하는데 홍대에 이런곳이 있어서 넘 좋아요!! 냥발 아이스크림 귀엽고 맛있어요. 젤라또는 리쪼(쌀우유)맛이랑 복숭아맛이 진짜 맛있었어요!! 글고 재료를 진짜 아낌없이 넣으시는지 우유맛보다 재료본연의맛이 엄청많이났어요! 홍대 젤라또 맛집으로 추천해요~!', 91, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '사장님 너무 친절하시고 가게 너무 귀여워요ㅠㅠㅠㅠ 저 고양이 데리고 오고 싶다... 젤라또 다 직접 만드신다던데 진짜 시원하고 맛있었어요 이 더운날에 구세주ㅠㅠ 양도 엄청 많고 건강하게 먹을 수 있어서 아이랑 먹기에도 좋았어요!!', 12, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '저는 사과/리조에 황치즈 맛보기 같이 간 지인은 로투스/딸기에 패션후르츠 맛보기 먹었는데 언제나처럼 맛있고 쫀득하고 양도 푸짐합니다👍👍 특히 리조가 알갱이 씹히는 맛이 있어서 추천합니다!', 57, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대를 엄마와 함께 데이트 하고 있었는데 날씨가 너무 더워 방문한 아라또!! 홍대입구역 7번출구에서 가까워서 쉽게 찾아갈 수 있었습니다! 매장이 너무 시원해서 좋았어요❤️ 거기다 이렇게 귀여운 아이스크림 가게라니 ㅋㅋ 귀엽고 동물을 좋아하는 저는 안들어갈수가 없었네요ㅜㅜ!! 젤라또가 종류도 많았고 전체적으로 깔끔한 맛이라 너무 좋았어요!! 더위가 싹 날라가더라구여 ㅋㅋㅋ 애견동반도 가능해서 르네도 데려갔었는데 사장님께서 르네도 챙겨주셨어요 ㅠㅠ 너무 감사했답니다!! 강아지도 먹어도 괜찮은 아이스크림이라고 하셔서 먹여봤는데 너무 잘 먹더라구여 ㅋㅋㅋ 재방문 하겠습니다😆😆💕', 10, 1, 'GOOD', SYSTIMESTAMP);
