INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '젤라또 좋아해서 많이 먹는데 진짜 너무 맛있었어요!! 특히 과일 종류가 정말 과일을 먹는 것처럼 맛있고 달달해서 다른 메뉴들도 먹어보고 싶어요:)', 3, 7, 'GOOD', SYSTIMESTAMP);
