INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '젤라또가 너무 맛잇어욥 :) 저녁에 새로운 맛 나온다고 하셔서 하루에 두번 올 정도..ㅋㅋ 사장님의 개인 간식까지 올려주신 센슈🫶🏻 홍대젤라또맛집 인졍! 친절하신 사장님도 넘흐 조아욥! 매일 새로운 맛이 나와서 또 찾아오께욥 ♥️', 34, 0, 'GOOD', SYSTIMESTAMP);
