INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '사장님이 너무 친절하시고 유쾌하신데 젤라또 너무너무 맛있어요… 입가심으로 너무 시원하게 잘 먹었숩니다 ㅎㅎ 맛보기 찬스도 해주시고 체고십니다🩵🩵', 45, 0, 'GOOD', SYSTIMESTAMP);
