INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '맛있고 엄청 다양하고 사장님 진짜 친절하세요!! 종류가 많아서 맛이 너무 고민됐는데 모든 종류의 맛 맛보기 스푼 가능하다고 하시면서 막 주시는데 받는 제가 더 눈치보이는 ㅋㅋㅋㅋㅋㅋㅋ 젤라또를 진짜 좋아하셔서 가게차리신 느낌이에요!! 재밌으시고 친절하시구 맛도 엄청좋습니다👍 아 그리고 로투스랑 패션후르츠 제 원픽들입니다 특히 로투스🍪', 6, 8, 'GOOD', SYSTIMESTAMP);
