INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '사장님 왕 친절하세용! 엄청 양도많이 주시고 서브스도 왕왕 많이주세용 학원 근처라 자주올거같아요 번창하세용+가게 나가는길에 새똥맞은거 발견해서 기분 안좋았는데 상황대처 잘 해주셔서 기분좋게 넘어갈수 있었어요! 사장님의 밝은 에너지덕분에 오늘하루 기분 좋게 보낼수 있을거같아요', 130, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '사장님도 너무 친절하시고 고양이 발도 넘 귀여워요ㅎ...... 수업 들어가야 한다고 하니까 오디주 아이스크림 쫌 더 주셨는데 맛보기 스푼으로 먹어본 맛 다 너무 맛있었어요~~!!!!', 19, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '가게 인테리어 때문에 홀린듯이 들어갔는데, 너무 친절하게 응대해주셔서 즐거운 기분으로 아이스크림을 고를 수 있었어요! 맛보기 스푼으로 미리 맛을 볼 수 있는 점도 좋았고, 정한 2가지 맛을 제외하고 또 2가지 맛을 골라서 맛볼 수 있는 점도 너무 너무 좋았습니다 🥰 오레오 / 쌀소금 맛을 골랐는데 흔히 말하는 어른들이 좋아하는 단맛! 으로 인공적인 단맛을 안 좋아하는 저희 입맛에 딱 맞았어요 💕 젤라또는 맛도 맛이지만 식감으로 먹는다고 생각하는데 쫀득하구 부드러워서 ㅠㅜ 재방문 해야겠다 싶었답니다 다정하고 친절한 응대 감사했습니다~ 번창하세요🥺💕', 76, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '뇸냐리 귀엽고 뇸냐리 맛있어요! 친절하기도 하시고 근본 리쪼가 아주 맛도리에요! 맛 안본사람 없었음 좋겠어요! 늦게까지 해서 술마시고 아이스크림타임 완전가능!🤍💙갓벽 그 잡채..✨', 70, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '술마시고 지나가다가 매장이 환하고 예뻐서 들렸는데 사장님께서 너무 친절하세요..! 어떤맛 먹을지 고민하니까 맛보기스푼으로 맛보게 해주세요~~ 뽀또맛 맛있어요❤️ 맛이 매일 바뀐다는데 담주에 홍대오면 다시 들릴게요', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '쫀득하고!! 부드럽고!! 근데 또 로투쓰는 로투쓰대로 쌀이면 쌀대로 재료의 맛이 충실하게 나서 수제로 정성들여서 만드신 느낌이 나요! 맛은찐한데 순수젤라또다 라는 느낌이랄까.. 넘맛있어요! 🫢🧡', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '사장님 극엥쁘삐! 진짜 웃기시고 툭툭 던지시는데 웃기게 내리꽃혀요! 서비스도 좋으시고 맛보기가 맛보기 양이 아닙니다만? 진짜 아이스크림 잠깐 먹으러 간 건데도 웃겨서 계속 깔깔깔 했습니다!', 63, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '수제젤라또 느낌 팍팍 나요 친구랑 한 컵씩 먹었는데 맛마다 개성을 살려서 잘 만드신 것 같아요 사장님이 엄청 친절하시고 유쾌하시네요 ㅎㅎ', 14, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '예전에 맛있게 먹었던 기억이 있어서 재방문했어요! 다 맛있는데 개인적으로는 상큼한 계열이 시원하고 제일 맛있었네요((+누텔라가 진짜 적당히 달고 맛있어여 사장님도 친절하시고 가볍게 왔다가 대만족하고 갑니당:>', 82, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '리뷰만 봤을 땐 매장이 작아보여서 불편하지 않을까? 싶었는데 막상 와보니 왜 다들 극찬인지 알겠더라구요..! 그냥 넘 편안해지는 곳이에요 있는 것만으로 기분이 좋아지는...! 막 넓은 편은 아니지만 또 생각보다 엄청 좁지도 않고 눈치보이지 않아요 ㅎ.ㅎ 대화하는 분들도 있고 작업하는 분들도 있고 다같이 편하게 쉴수있는 카페인 거 같아요~ 음료와 디저트가 넘 맛있고 (특히 크림브륄레라떼 존맛 ㅠㅠ 디카페인이 안돼서 아쉬웠지만, 연하게 부탁드릴 수 있어 좋았습니다!) 나중에 혼자 쉬러 또 오고 싶어요 ㅎ.ㅎ 복작한 홍대에 이렇게 편안한 공간 감사합니다', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
