INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '시끄러운 곳이 싫어서 조용한 카페 찾아다니는 편입니다. 작업하시는 분들이 꽤 있어서 조용하니 아늑하고 좋아서 친구랑 도란도란 얘기하고 참 편안했습니다. 우연히 발견해서 들어갔는데 인테리어 분위기도 좋고 음료랑 디저트도 맛있어서 만족했어요.  단거 좋아하는 제 입맛에 메뉴가 딱이었어요. 단거 별로 안좋아하는 친구도 한 입 먹어보더니 맛있다네요', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '여기 커피가 너무 맛있는데 크림 올라간 커피종류들 다 맛있네요 종종 갈것같아요 너무 좋았습니당 카페 이용시간 정해져있습니다! 참고~', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '[혼자서 조용히 즐기는 카페] 제목은 혼자라고 쓰긴 했지만 2~4인 방문하셔도 좋은 것 같아요. 시간은 주말 2시간 평일 3시간인데, 그렇다고 예민한 느낌은 아닙니다. 서비스도 친절하시고 콘센트도 잘 구비되어있어서 오히려 잠시 홍대에 들린다면 여기서 아늑하게 작업하기 좋을 것 같습니다. 홍대 한 가운데 있고 공간이 엄청 큰건 아닌데 차분한 느낌이었고 책들도 소설, 비문학 모두 다 있어서 잠시 시간 보내기 좋은 카페라는 생각이 들었어요.', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
