INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '이름값 제대로 하는 분좋카☕️ 노트북으로 작업하시는 분들도 많고, 멤버십 제도도 따로 있는 것 같더라구요! 물론 저희는 밥 먹고 수다 떨 용으로 왔습니다만.. 작업하는 분들과 멀찍이 떨어저 앉아서 괜찮았어요😊 얼그레이 밀크티에 올라간 폼 달달하니 맛있었습니당 밀크티는 진하지만 얼그레이 향이 많이 느껴지는 편은 아니에요! 그치만 서비스로 작은 까까도 주시고... 전반적으로 감성 있는 공간이라 다음에 또 오고 싶은 곳입니다🥰', 2, 6, 'GOOD', SYSTIMESTAMP);
