INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '요즘 조용한 카페를 찾기 힘든데 너무 조용하고 분위기도 너무 좋더라구요!! 조명도 눈이 너무 편하고 나오는 음악도 크지도 않고 컨셉에 맞게 진짜 작업이나 과제하시는 분들도 너무너무 편하게 하시고 가시더라구요.! 그리고 책 읽는거 좋아하시는 분들도 정말 오기 좋을 것 같아요. 아 ㅋㅋ 사장님 키가 엄청 크신것도 새로운 캐치..2M 라고 하셔요 ㅋㅋㅋ', 18, 3, 'GOOD', SYSTIMESTAMP);
