INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '인기가 많은 곳이다보니 혼자 방문한게 아니라면 웨이팅.? 아닌 웨이팅을 해야되는 건 아쉽지만 분위기가 좋고 조용해서 잠깐 작업하기 편한 것 같습니다. 크림프렐레라떼 였나? 너무 맛있어용', 47, 2, 'GOOD', SYSTIMESTAMP);
