INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대에서 카공한다면 꼭 찾는 카페에요! 좌석이 많지 않고 또 작업하시는 분들이 많아서 회전율은 좋지 않은 편입니다 ㅠ 그런데 아기자기한 분위기와 편안한 음악 맛있는 음료가 정말 다하는 카페에요 작업실 강추입니다 🫶🏻', 39, 6, 'GOOD', SYSTIMESTAMP);
