INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '실라떼와 크림브륄레 라떼 먹었는데 각각 모카커피와 달고나라떼 같은 느낌이었고 맛있었어요😁 인테리어가 멋지고 늘어지기 좋은 분위기라서 좋았습니다👍 소파자리라서 더 그랬나봐요 ㅎㅎ', 57, 17, 'GOOD', SYSTIMESTAMP);
