INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '크림브륄레라떼 너무 맛있어요 !!!!!!💖 오랜만에 재방문했는데 인테리어도 더 이쁘게 바뀌고 아늑해서 책 읽고 싶은 욕구가 뿜뿜하더라구요ㅎㅎ 이번엔 노트북 작업하러 갔지만 책 읽으러 또 방문할게요! 😊', 46, 1, 'GOOD', SYSTIMESTAMP);
