INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '카페가 조용하고 ,책도 많이 구비되어 있어요 작업하거나 독서하기 딱이에여! 홍대에 이렇게 조용한 데가 있는 줄은 몰랐어여 ㅎㅎ 카페가 워낙 조용해서 수다 목적이신 분들은 다른 곳으로 방문하시길.!!', 46, 2, 'GOOD', SYSTIMESTAMP);
