INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '지나가다 우연히 들렀는데 조용하고 가게분위기도 너무 예쁘고 편해서 좋았어요! ㅎㅎ 혼자오기 너무 좋은 카페인것 같아요 디저트도 맛있었고 잘쉬다가 갑니다 ㅎㅎ!', 41, 7, 'GOOD', SYSTIMESTAMP);
