INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대입구역 근처에 작업하기 좋은 곳이 있다고 해서 들렸는데, 인테리어 멋지고 잔잔하고 집중도 잘됩니다! 간단하게 분위기 바꿔서 작업하고 싶으시면 추천드려요!', 4, 6, 'GOOD', SYSTIMESTAMP);
