INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '기분이 울적해서 혼자 카페에 왔어요 조용하고 책도 잔뜩 있고 노래도 적당하고 정말 기분좋게 있다갑니다 ! 아 그리고 제가 먹은 바닐라빈 라떼 중에 여기서 먹은게 제일 맛있었어요 따뜻하고 달달한 기분 좋은 맛을 경험하고 갑니다 ! 직접 말하려다가 이 편이 더 도움 되실것 같아서 ☺️❤️', 45, 5, 'GOOD', SYSTIMESTAMP);
