INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '평점 높길래 갔는데 일단 문 열자마자 너무 시원해서 행복했고 당폭발하는 음료와 디저트덕에 극락갔네요 길티플레져 엄청났지만 너무 맛있었음🩷', 52, 13, 'GOOD', SYSTIMESTAMP);
