INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '🔹메뉴추천 : 공일라떼 🔹개인적 의견 : 평점 4.98은 처음봐서 무의식적으로 들른 카페. 일단 분위기가 막 떠드는 느낌보다 노트북하거나 책읽는 사람이 많은 차분한 분위기! 음료도 양이 엄청 많아서 다른 카페에서 6-7천원 받고 코딱지만큼 주는 것과는 차원이 다름! 커피도 맛있음! 시그니처로 공일라떼 말고 씰라떼도 있어서 다음번엔 씰라떼 도전!😉 💚장길동의 맛도리로드💚', 11, 3, 'GOOD', SYSTIMESTAMP);
