INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '인테리어가 너무 제 취향이라 좋았고 공부하거나 작업하시는 분들이 많아서 저도 조용히 책에 집중할 수 있었어요 대화하시는 분들도 있었지만 조용한 분위기라 다들 소리를 크게 내지 않으셨고 화장실이 너무 어두워서 눈 감아도 모를 정도였어요ㅋㅋㅋ말차라떼는 쓴 맛이 거의 없고 달았어요 크림도 묵직하게 단 느낌 미니약과 별거 아닌데 서비스처럼 주시니까 묘하게 감동받았어요 저는 책을 따로 챙겨왔지만 배치된 책들이 많아서 담에 또 와서 책읽고 싶어요', 128, 26, 'GOOD', SYSTIMESTAMP);
