INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '오픈 시각 조금 이후에 방문했을 땐 사람이 거의 없었는데, 시간이 지날수록 사람들이 계속 오더라고요! 구석진 아늑한 곳에 자리 잡았는데, 햇살도 따사롭게 비추고 카페 공간 자체가 아늑하고 예뻐서 편안하게 머물다 왔어요 ☺️ 대부분 노트북이나 공부 등을 하시던데, 비치되어 있는 책들도 자유롭게 볼 수 있어서 다음 번에는 독서하러 가고파요!!', 40, 5, 'GOOD', SYSTIMESTAMP);
