INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '시간이 애매하게 남아 근처에 있길래 방문하게 되었습니다! 원래도 카페 찾아다니는 걸 좋아해 이름은 들어본 적 있는 곳이었어요. 우연찮게 방문했는데 인테리어와 음료 모두 너무 만족스러웠습니다😍 이름대로 작업실 같은 분위기입니다! 미드센츄리 스타일의 인테리어가 정말 맘에 들었고, 조용한 분위기라 공부나 작업하기에도 좋을 것 같다고 생각들었습니다. 의자와 소파가 골고루 있어 친구와 방문하기에도 적합하다고 생각했어요🫧 일행은 아메리카노a타입, 전 시그니처(씰라떼?) 메뉴를 주문했습니다. 시그니처 메뉴의 경우 한번도 먹어보지 못한 느낌이라 신선했어요. 같이 시킨 말차테린느?도 맛있게 먹었습니당🤗 그리고 서비스로 미니약과 주셔서 좋았어요오🍪 재방문 의사 있습니다!', 28, 7, 'GOOD', SYSTIMESTAMP);
