INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대에 대형 카페만 찾아 다니다가 급하게 네이버로 찾아 방문한 곳이었는데 생각보다 실내도 아늑하고 인테리어도 너무 예쁘고 사장님도 친절하시고 디저트까지 맛있어서 1번 더 오고 싶은 곳이었어요~~!!', 80, 17, 'GOOD', SYSTIMESTAMP);
