INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '길 지나가다 눈여겨 본 곳 미루다 이번에 처음 와봤지만 바로 마음에 들었다 카페 자체가 좋기보단 분위기와 책, 인테리어에서 나오는 뒤의 사람이 오히려 마음에 든 기분 소소하지만 자주 오게 될 것 같다', 126, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '인테리어 진짜 킹왕짱 예쁘고 음료도 겁나게 맛있고 사장님이 와서 어떻게 먹어야 하는지 설명해주시고 ㅠㅠ 진짜 땡큐베리감사티비였어요ㅠㅠㅠ 분위기도 너무 좋고 음악도 좋고 근데 시끄럽게 수다 떨만한 분위기는 아녔음… 다들 뭔가 컴퓨터로 타닥타닥하는 분위기예요.. 얘기하시는 분들은.. 한 두 테이블 ? 정도 있었던 걸로 기억합니다. 심지어 그분들마저도 엄청 조용조용히 얘기 나누심 아무튼 홍대에 이런 곳이 있었다는 걸 이제 알게 되다니 원통합니다요ㅠㅠ재방문 예정 !', 56, 17, 'GOOD', SYSTIMESTAMP);
