INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '혼자와서 카공하기에 너무 좋은 카페예요 밤고구마 음료가 고구마라떼에 밤 섞인 맛이라 진짜 너무너무 맛있어요..💗💗💗 천천히 마시고 싶었는데 순삭해버렸어요', 49, 1, NULL, SYSTIMESTAMP);
