INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '제가 알던 테린느는,, 이게아닌데,, 무스같은 테린느를 기대했지만,, 크림치즈 특유의 시큼함이 강하게 느껴지는 바치케를 먹는 느낌이었습니다,, 음료가 맛있어ㅓㅅ 기대했는데,, 살짝 아쉽네요,, 다쿠아즈 시킬껄,, 떼잉,, 그래도 조용한 분위기가 너무 좋았숩니다,,❤️ 대화소리보다 노래소리가 더 조용하게 잘들리는곳이라,, 서울에서 흔치 않은 카페인거같아요,, 다음에 작업할거 있으면 꼭 다시오께요,,❤️', 2, 8, NULL, SYSTIMESTAMP);
