INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '혼자 카공이나 작업하기에 좋아요 그래서인지 평일 2시인데도 자리 대부분이 차있어요 시그니처 라떼 맛은 평범해요 다쿠아즈 궁금했는데 포장이 안돼서 조금 아쉬웠어요', 10, 4, NULL, SYSTIMESTAMP);
