INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '조용한 카페 찾다가 들러봄. 아날로그 감성 그득한, 2층같지만 살짝 낮아 1.5층같은 카페. 종이책 진열과 각종 기물들, 가구들이 빼곡하면서도 답답하진 않은 구성이다. 혼자 가서 시간 보내기도 좋고, 잠깐 수다 떨러 가는것도 괜찮고.. 커피를 안마셔봐서 맛은 모르겠는것. 크림브륄레 라떼는 단가 좋아하면 추천그~', 49, 6, NULL, SYSTIMESTAMP);
