INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '차분하고 감성적인 느낌의 카페 찾다가 왔는데 분위기가 너무 좋고 깔끔해요 ..🤎 음료랑 디저트도 이쁘게 잘 나와서 사진 엄청 찍었어요 ㅋㅋㅋ!! 사장님이랑 직원분들도 다들 너무 친절하셔서 좋은 시간 보내다 갑니당 블랙자몽', 25, 7, 'GOOD', SYSTIMESTAMP);
