INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '공간도 좋은데 음료도 넘 맛있어요ㅠ 당충전 제대로.. 실라떼 먹었는데 마냥 흔한 초코(모카)라떼랑은 다르고 크림이 진짜 맛있더라고요..!! 일하기도 너무 좋고 진짜 왜 이제 와봤나 싶을 정도로 너무 좋았던 공간입니다:-) 기분전환하고싶을때 갈 곳이 생겼네요ㅎㅎ', 43, 2, 'GOOD', SYSTIMESTAMP);
