INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '제가 사랑니를 뽑아서 음료를 다 남기규 왔어요🥺 약속시간이 떠서 들렸다가 물고있던 솜 빼니까 피가 철철나서,, 먹을 수 있는줄 알았는데 공간만 빌려쓰고 왔네요 ㅠㅠ (혹시 사장님이 맛없어서 남겼나 오해하실까봐,,) 조용하고 혼자 작업하기 정말 좋은 곳이었어요 다음에 다시 방문할게요!', 30, 5, 'GOOD', SYSTIMESTAMP);
