INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '생각보다 공부하는 분위기의 카페였음! 크림브륄레 라떼가 시그니처여서 먹었는데 매우 달아서 끝까지는 못 마심 ㅎㅎ,, 단 거 그닥 좋아하지 않으시면 비추 블랙자몽에이드는 개인적으로 되게 맛있었음 강추', 55, 13, NULL, SYSTIMESTAMP);
