INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '인스타 보고 작업하기 좋다해서 왔는데 좀 많이 좁고 2인석 자리 앉으려고 봤더니 방석에 머리카랑 잔뜩 묻었고 좀 지저분해서 놀랬어요.. 너무 기대하고 와서 좀 실망이였어요,, 커피맛도 라떼 마셨는데 얼음이 녹을수록 얼음에서 냄새가 나네요…? 매장이 좁아서 청결에 더 신경써야할것같은데, 사람이 많이 오늘걸 보니 다 인스타 보고 오는것같더라구요. 솔직히 혼자 작업하기에는 좀 별로였어요 1인석도 굉장히 좁고,, 한번가고 안갈듯 싶네요;;', 48, 10, 'BAD', SYSTIMESTAMP);
