INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '라떼를 달달한 크림으로 해주셨는데 적당히 달고 너무 맛있었어요! 치즈케이크 위에 생크림이 굉장히 특별해요🤤 커피랑 디저트가 잘어울어지는 맛이였습니다!', 29, 5, 'GOOD', SYSTIMESTAMP);
