INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '카페 이름이랑 찰떡 평일이라 그런지 노트북들고 할 일하러 오신분들이 꽤됐고 차분한 분위기 씰라떼 생각보다 많이 안달고 크리미해서 맛있다 🌸', 0, 8, 'GOOD', SYSTIMESTAMP);
