INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '위드코로나가 되어서 늦게까지 하는 카페에 오랜만에 있으니 너무 좋아요..ㅜㅜㅜ 음료시키면 공짜로 주시는 과자들도 나무 이쁘고 인테리어나 음식 플레이팅 사진 되게 잘나와요', 8, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '사장님이 원두도 직접 다니면서 고르셨대요~ 너무 맛있어요~~ 같이 나온 스낵도 사르르 녹는게 너무 맛있어용! 코로나 좀 풀리면 맥주 한잔 마시면서 작업하기 너무 좋을것 같습니다! 굳굳', 7, 0, 'GOOD', SYSTIMESTAMP);
