INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '작업할때가 마땅한 곳이 없었는데.. 아지트를 찾았어요! 맥주를 마시면서 작업할수 있다니 좋아여!! 이번에 구스IPA 마셨으니 다음엔 스텔라 마시러 갈게요~', 27, 4, 'GOOD', SYSTIMESTAMP);
