INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '두번째 방문입니다. 간단히 맥주 한 잔 하면서 좋아하는 책 읽기에 딱 좋습니다. 카페 이름처럼 작업에 집중하기 좋겠어요. 아, 커피도 짱맛..🤤', 20, 5, 'GOOD', SYSTIMESTAMP);
