INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '여유롭게 커피마시면서 작업하다가 답답할때 맥주까지 한잔 할 수 있어서 너무좋네요.. 우연히 들러서 작업했는데 집앞에도 하나있으면 좋겠어요..ㅋㅋㅋㅋㅋㅋ 다들 작업하면서 맥주한잔씩 하는 분위기라 눈치안보고 마실수있어서 쬲..ㅠ', 69, 16, 'GOOD', SYSTIMESTAMP);
