INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '각 테이블마다 콘센트 있어서 일하기 좋고 인테리어도 예뻐서 일하면서 기분이 좋네요! 커피도 탄맛안나고 진짜 맛있어요~ 자주올게요!', 40, 3, 'GOOD', SYSTIMESTAMP);
