INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '프리랜서인데 상호명이 ''작업실''인 거 보고 끌려서 들어가봄. 집중이 매우 잘 됨. 가끔 자체퇴근 전 술 한잔 너무 좋음.. 신생이라 앞으로 더 좋아질 거 같아 기대되는 공간.', 48, 0, 'GOOD', SYSTIMESTAMP);
