INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '갬성있는 카페 찾고있었는데 맥주 마시면서 힐링하기 너무 좋았어요😆😆 홍대에 아지트 느낌으로 나만알고 싶은 카페지만 사장님이 친절하셔서 별점 꾹꾹하고 가요 ㅋㅋ', 20, 1, 'GOOD', SYSTIMESTAMP);
