INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), 'e71 에센스머신+sp2, 스코디2, 펄스 그라인더 조합 매장에는 페미니아 1구 머신도 있다 에스프레소는 추가금 없이 싱글 에티오피아로 변경 가능 설탕을 빼고 달라면 라빠르쉐 유기농 각설탕도 제공 예열이 잘 된 데미따세에 꽃과 과일 향미 가득 에스프레소 탄내 스모키 쓴맛 없이 설탕이 들어가면 후숙이 많이 된 푸룬주스나 블러드오렌지 같다 커피가 나오기 전 이태리 보르미로꼬 유리잔에 내어주는 냉수부터 친절에 친절을 더한 응대 오레아 드리퍼와 pk100 그라인더로 만드는 브루잉커피가 궁금하다 아시아나 브라질 없이 케냐, 에티오피로만 꾸며진 라인업이 좋다 어쿠스틱 리서치 같은 스피커에서 넘치는 저음외에는 아쉬운 부분이 없다 에스프레소의 퀄리티가 너무 좋아서 많이 놀람!!', 37, 2, 'GOOD', SYSTIMESTAMP);
