INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '음료도 너무맛있고 디저트도 진짜 맛있어요 사장님 두분다 너무 친절하시고 최애카페 될거같아요!!!!!!!!!🩷🩷🩷 합정카페는 항상 요기올거에용', 10, 4, 'GOOD', SYSTIMESTAMP);
