INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '정말 사랑스러운 공간이에요.. 🩵 항상 친절히 맞아주시는 사장님 덕분에 늘 기분 좋게 머물다 가요! 게다가 디저트와 음료들도 다 건강한 재료로 만들어주셔서 마음놓고 애용할 수 있어요... 🩵 자주 바뀌는 테이블 위 식물들 보는 맛도 쏠쏠합니다 ㅎㅎ 인테리어도 참 정갈하고 예쁜 시타커피 🩵 항상 감사합니다~~', 82, 18, 'GOOD', SYSTIMESTAMP);
