INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '시원한 커피 마시러 방문했어용 ! 사장님 두 분 다 너무 친절하시고, 음료랑 디저트도 맛있었어요 🤍 특히 바스크치즈케이크 .. 눈물 나오는 맛입니다 ,, 어어엄청 꾸덕하고 풍미 대박이에요 ㅠ_ㅠ 다들 시타커피로스터스 하세요 ..!', 48, 4, 'GOOD', SYSTIMESTAMP);
