INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '합정역 북적이는 역 근처를 벗어나 평온함이 느껴지는 주택가 사이 새롭게 자리 잡은 카페 시타커피로스터스 주민분들과 인근 직장인들의 사랑방으로 꾸준한 사랑을 받고 있는 카페 시타커피로스터스 바리스타로 오랜 시간 경험과 경력을 쌓으신 사장님께서 오픈을 하셨다고 선한 미소를 가지신 사장님과 오랜 시간 같이 근무하시던 직원분이 함께 있는 공간으로 3월 1일부터 차곡히 시타커피로스터스에서 추억을 만들어 가고 있다. 차근히 내부 공간의 변화도 가질 예정이며 몇 달 뒤에는 로스터기가 도착한다고하니 로스팅 하시는 모습까지 볼 수 있을듯하니 그 날이 기다리며 기대해본다. 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 34, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '밀크티, 예가체프 커피, 심지어 바나나푸딩 디저트까지 너무 맛있었어요!!! 가게도 감성적이라서 느낌 좋아요~ 다음번에도 방문하고 싶은 가게네요~~ 커피 종류별로 설명도 해주시고, 알고 먹으니까 더 맛있는 거 같아요!!', 10, 10, 'GOOD', SYSTIMESTAMP);
