INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '합정역 조용히 쉬어가기 좋은 카페 시타커피로스터스🪑 합정역 빌딩에 조용히 오픈한 동네 사랑방같은 카페로 은은한 베이지톤의 안락한 공간에서 시간을 보낼 수 있던 공간. 너티플랫화이트, 콩고물크림커피, 홍콩밀크티 총 세가지의 시그니처와 브루잉커피, 배치브루가 준비되어 다양한 종류의 커피를 맛보기 좋았던 카페였어요 콩고물크림커피는 진한 흑임자라떼 마시는 것 같아 평소에 곡물 들어간 음료 좋아하면 만족스러울 것 같습니다!', 41, 10, 'GOOD', SYSTIMESTAMP);
