INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '직원분도 너무 친절하시고 커피도 맛있어요!! 외부에도 자리 있는데 선선한 날에 꼭 자리 찜꽁하세욥 그냥 주택마저 분위기 있게 만들어버리는 자리입니다🥂🫶🏻', 34, 5, 'GOOD', SYSTIMESTAMP);
