INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '토요일 아이와함께 가족이 방문했습니다. 리뷰에서 인기많았던 밀크티와 스콘, 콩고물크림커피, 브루윙커피를 마셨어요. 정말 여기 음료 디저트 모무 미친맛입니다!! 커피는 정말 너무너무 맛도좋고 향도좋고 그어디에서도 마셔보지못한 원도였어요 사장님 추천픽 진짜 너무 킹정!!!! 평소 산미있는 커피좋아하시는 분들은 정말 꼭가보세요!!! 가고또가세욬ㅋㅋㅋㅋㅋ 스콘과 브루윙커피조합 진짜 최고였구요👍 평소 밀크티를 진짜좋아하지만, 당때문에 자주 많이 마시지못하는데, 여기밀크티는 달지않은데 너무 맛있어요. 그동안 마셨던 밀크티는 밀크티가 아니라 설탕티였나봐요 😭😭😭😭 여기밀크티는 당이 낮은데 맛이 너무좋아요 사장님이 마술부린밀크티에요!!!!!!', 78, 18, 'GOOD', SYSTIMESTAMP);
