INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '사장님 추천받은 콩고물크림👍👍 저당인데 왜 이렇게 맛있죠...??!? 적당히 달고 꼬소합니다☺️ 사장님도 친절하시구, 인테리어도 제가 좋아하는 우드톤에다가, 당연히 커피도 맛있고ㅠㅠ 그냥 다 최고입니다👍🥰', 6, 2, 'GOOD', SYSTIMESTAMP);
