INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '아늑하고 편안한 분위기에요! 음료가 맛있어서 추가주문해서 먹고 나갈때 한 잔 더 시켜서 먹었습니다. 또 직원분들도 정말 친절하십니다!', 28, 7, 'GOOD', SYSTIMESTAMP);
