INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '좌석마다 콘센트가 많아서 작업하기 좋고 의자도 편합니다! 커피도 양 많고 맛있어요! 디저트도 팔구요! 작업하거나 공부 하는 사람들 많아서 눈치 안보고 편하게 올 수 있을 것 같습니다 :)', 23, 2, 'GOOD', SYSTIMESTAMP);
