INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아지트로 삼고 싶은 카페 발견 일단 본론부터 커피가 진짜 맛있어요! 산미있는 원두 고소한 원두 둘 다 너무 제 취향이라 매일 가고 싶은 곳입니다 🥺 사장님도 정말 친절하시고 무엇보다 카페가 주는 분위기가 너무 좋아요 조용하면서도 흘러나오는 음악 덕에 적막하진않은 테이크아웃 할인도 되니 지나가다 맛있는 커피 마시고 싶으면 가보시길 추천드려요!', 29, 0, 'GOOD', SYSTIMESTAMP);
