INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '아침에 일찍 여는 작업하기 좋은 합정카페 매장이 고요하면서고 잔잔해서 좋았어요. 테이블마다 콘센트와 테이블스탠드까지 마련되어있어 집중하기 좋은 취향의 공간이예요. 사람이 많을때도 없을때도 모두 좋을것이 틀림없는 감도높은 카페입니다.', 58, 14, 'GOOD', SYSTIMESTAMP);
