INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '연차쓰는 날에 오기 좋은 카페☕️ 담택 웨이팅하면서 걷다가 발견 반쯤 이끌려 들어온 카페! 근데 음악도 인테리어도 다 너무너무 멋졌다 다음에 노트북 들고 올게요 작업이 잘 될 것 같아용💚', 28, 8, 'GOOD', SYSTIMESTAMP);
