INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '근처 미용실에서 머리하고 근처 돌아다니다가 우연히 발견한 카페 분위기는 차분하고 조용해서 혼자서 공부하는 분들도 많더라구요 다음엔 책 가져와서 시간보내보고 싶어요 커피도 원두 자체가 좋은지 커피맛도 좋았습니다 또 들를 의향 있습니다', 39, 2, 'GOOD', SYSTIMESTAMP);
