INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '무인카페라서 방문해서 커피랑 파운드케이크를 먹고 화장실을 이용하려고 영수증에 적힌 비번으로 누르니 비번이 틀려서 사용을 못했어요 새벽이라 홍대입구역도 문이 닫았고 화장실을 못 사용하니 너무 황당했습니다', 35, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '24시에 야간 무인매장이지만 음료나 빵도 많고 좌석도 괜찮아서 좋습니다 다만 밤에 누워 자는 손님들이 좌석을 다 차지하고 짐을 늘어놓고 개인 랩탑 스피커로 노래소리 틀고 그런게 짜증나네요', 31, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대입구역에서 멀지않은데 신촌넘어가는길이라서 그런지 조용하고 좋아요 오픈행사로 베이글이랑 소금빵을 저렴하게 판매하고 있더라구요', 58, 15, NULL, SYSTIMESTAMP);
