INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '베이커리 진열 된 곳에 뚜껑 하나 없이 그대로 진열해두셔서 벌레 앉아있더라구요 그래서 빵은 못 먹었습니다. 테이블도 안 닦여있어서 빵가루 다 떨어져있었습니다. 직원분들 태도도 별로였고 직원분들끼리 너무 시끄러우셨어요. 더운날 간단히 대화하고 가긴 괜찮은 장소입니다.', 26, 9, 'BAD', SYSTIMESTAMP);
