INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대입구역에서 발견한 커피 맛집! 고소 산미 원두 선택 가능하고 디저트도 다양한데 매일 만든다고 해서 더 맛있는 것 같아요. 소금빵도 진짜 맛있어보여서 다음에 밥 안 먹고 다시 방문할 예정. 좌석이 넓고 편안해서 대화하기 진짜 좋아요~', 43, 1, 'GOOD', SYSTIMESTAMP);
