INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대베이커리카페 찾다가 방문한 퍼스트커피랩!! 아니 베이커리류 너무 다 맛있어보여서 고르는데 힘들었습니다 ㅠㅠㅠ🤍✨🥹 유자크로아상 진짜 도라이..✨🤤 너무맛있습니다 전체적으로 인테리어도 예쁘고 공간도 넓어서 좋았습니다 ㅎㅎ 대신 사람들이 많아서 복작거리는 느낌은 있었지만 2층으로 올라가서 편하게 있다갔습니다 ㅎㅎ', 103, 26, NULL, SYSTIMESTAMP);
