INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '디저트 앵간하면 드시지 마세요 맛이 없으니까요 케이크 테이크아웃도 추천드리지 않습니다 왜냐하면 포장비용 천원이 추가되니까요 무인카페지만 직원이 계세요 하지만 없는 것이 나아보입니다. 마치 제가 불쾌하다는 듯이 대하시니까 차라리 안계시는 편이 좋을 것 같아요 불쾌했습니다. 디저트의 재고확인 또한 직접. 해야하는 시스템입니다 참고하세요 :)', 86, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '매번 지나갈때마다 눈독 들여놨던 카페 드뎌옴 ㅠㅠ 커피는 물론이고 디저트가 진짜 bb ㅜㅜ 사이즈도 진짜 큼 ㅋㅋㅋㅋ 커피 마시러 왔다가 식사하고 가요 ,,, 앙버터 크로와상 꼭 드세여 존맛탱', 23, 1, 'GOOD', SYSTIMESTAMP);
