INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '바깥 테라스 분위기가 아주 좋아오♥️ 인테리어 바뀌고 처음 와봄 오늘 비도 오고 많이 안더워서 딱 좋음 블랙 카카오라떼? 신기한 라떼임 진짜 진한 카카오 맛이라 좋아하는 분들 원츄 부페먹고 와서 빵은 패스😂', 4, 9, 'GOOD', SYSTIMESTAMP);
