INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피회사에서 직접 운영하는 곳이라 커피맛도 특별해요 주문한 커피와 베이커리를 들고 2층에서 즐겼어요. 새로 오픈한 2층은 루프탑이라 햇볕을 가릴수 있는 그늘막이 덮고 있어 왠지 분위기가 한층 포근하니 아늑해요. 베이커리로 에그타르트, 폴링러브마들렌, 옥수수크런치마들렌, 할라피뇨소세지크로와상, 블루베리데니쉬를 카페라떼와 즐겼어요. 홍대 베이커리 맛집 퍼스트커피랩에서 커피와 맛있는 빵을 함께 즐기니 맛도 있고 너무 행복한 시간을 보냈어요 또 방문해야지 ~!', 40, 0, 'GOOD', SYSTIMESTAMP);
