INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '크림브륄레아인슈페너 정말 너무 맛있어요!! 6천원이라 좀 비싸긴하지만 가격이 안 아까울 정도로 정말 맛있어요. 메뉴 자체도 유니크하고 맛도 정말 맛있어요. 근데 베이글은 좀 딱딱해야하는데 얜 그냥 찹쌀빵처럼 너무 말랑해서 별로였어요 눈 감고 먹으면 베이글인 줄 모를 정도..? 그리고 빵도 말랑한데 나이프가 너어어어어어어무 안 들어서 빵을 눌러 썰어야 해서 빵이 만신창이가 됐어요.. 그 외엔 다 좋았어요. 직원 분들 다 너무 친절하시고 공간도 깨끗하고 이쁘고 넓고 좋았어요', 13, 1, 'GOOD', SYSTIMESTAMP);
