INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대 루프탑 카페 찾다가 방문했는데 좋은 선택이었아요!!😀 뷰도 좋고 좌석도 많아서 쾌적했어요. 과일 음료로 주문했는데 맛있게 먹었습니다!! 빵 종류가 많아서 고민 많았는데 주문한 쪽파크림치즈 맛있습니다!! 추천입니다^^', 53, 17, 'GOOD', SYSTIMESTAMP);
