INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), 'A블렌드 아메리카노 사랑해... 매장에선 5천 원이라 약간 비싼 감이 있는데요, 테이크아웃하면 2500원이라서 아주 메리트있는 카페입니다. 자주 방문하게되는 그런 카페😉', 39, 10, 'GOOD', SYSTIMESTAMP);
