INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '커피가 맛있어서 자주 이용하는 곳이에요. 평소에는 빵 주문해도 직접 주문받아주셔서 평소처럼 빵먼저 골라 갔습니다. 오늘은 빵만 주문하려 가니 어차피 키오스크로 주문하라고 할거 제가 들어갔을 땐 아직 주문 밀리기 전이었고 들어서자마자 빵고르고 있는 모습 뻔히 보였을텐데 키오스크주문안내 먼저 했으면 좋을 뻔 했네요. 사람 많아 대기도 긴데 시간낭비 심했습니다.', 22, 4, NULL, SYSTIMESTAMP);
