INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '카페는 예쁜데 알바가 키오스크 주문 못하게 하면서 직접말해라거리고 그게 편할거다하는데 솔직히 내가 키오스크 편하다는데 왜 그러세요.... 태도 고치셨으면 좋겠습니다. 이분때매 오기 싫어져서요..', 47, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '원래 아아족인 제게 콜드브루를 맛들여준 남자친구때문에 맛들인 콜드부르를 마시게 됐는데.  이집 커피맛이 깔끔의 정점을 찍는 맛이네요. 중독될것 같아요. 베이커리도 같이 먹고 싶었지만 다이어트중인 제게 스멜과 비쥬얼들이 발길을 멈추게 했지만 후 하 후 하....일주일 뒤에 반드시 너희들을 다시 찾도록 하겠다... 카페 분위기도 정말 환하고 조용하니 친구들과 모임할때 꼭 참고하시면 좋겠어요~ 베뤼 강추!', 1, 1, 'GOOD', SYSTIMESTAMP);
