INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '커피맛이 신선하고 깔끔해요 원두도 산미 있는 거 고소한 거 선택 가능해요 아쉬운거는 샷이 하나들어가서커피양이 적어요 샷추가도 안 된다하시더라고요 테이크아웃할인이 되는데 출근할 때 한 잔 점심 때 한 잔 또   마시게 될 때도 있어요 마들렌 등 디저트 종류도 다양합니다', 49, 2, NULL, SYSTIMESTAMP);
