INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '커피와 베이커리 맛있어서 좋아하는 카페에요. 여기 에그타르트랑 마들렌도 맛있고, 크로아상 샌드위치 먹었는데 크로아상이 맛있어서 식감도 넘 좋았어요~', 45, 5, 'GOOD', SYSTIMESTAMP);
