INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '직원분들 친절하게 서비스 응대 좋네요~ 카페가 너무 예뻐요! 인테리어 구경 하고 왔어요! 2층 테라스도 있어서 좋고 커피 맛있어요', 32, 3, 'GOOD', SYSTIMESTAMP);
