INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '요즘에는 카페갈때 화장실도 중요하다고 생각하는데 카페 내부도 깔끔하고 화장실도 깔끔하고 청결했어용! 청결도 별 5개⭐️⭐️⭐️⭐️⭐️ 그리고 빵집처럼 빵 종류도 다양해서 너무 좋았습니당! 제가 좋아하는 소금빵도 많았구용 최고👍🏻👍🏻', 30, 8, 'GOOD', SYSTIMESTAMP);
