INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '크림브레레 너무 맛있고 친절하셔요 하지만 2층 테라스는 코드가 없고 와이파이가 잘 안 터져서 공부하기 좋은 곳은 아닌듯해요! 테라스는 넘  좋아요 지금 딱', 18, 9, 'GOOD', SYSTIMESTAMP);
