INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '마사지 받으러 가는 길에 홍대 쪽에 잠깐 들렸는데 시간이 애매해서 쉴 곳 찾다가 발견. 대형 프랜차이즈 아니라서 덜 번잡하고 너무 작아서 부담스럽지도 않은 적당한 규모... 잠깐만 있다 가야하는 게 아쉬울 정도', 43, 10, 'GOOD', SYSTIMESTAMP);
