INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '저녁 먹고 퍼스트 카페 들려서 아아 한잔 사마셨어요. 저는 산미를 별로 안좋아해서 사장님이 추천해주신 걸로 마셨는데 고소하고 맛있게 잘먹었습니다. 사장님 완전 친절!!!', 2, 9, 'GOOD', SYSTIMESTAMP);
