INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '트레저♡박지훈 생일 카페 겸사 다녀왔어용!!!!! 예전에는 매장이 좁다고 느껴졌었는데 지금은 공간이 좀 트여서 앉을 자리도 많아지고 넓어진 것 같아요 ㅎ 매장 방문하면 벽에 연예인들 싸인도 많고 공간 활용도 잘 되어있어서 생일카페 하기 좋은 카페인 것 같아요..♡ 다음에 또 갈게요🤤', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '이럴수가 사진을 지웠다니... 브라우니가 정말 달고 맛있었어요!! 음료도 맛있고 되게 습하게 더웠던 날 방문했는데 카페 내부는 안 습하고 시원해서 너무 좋았어요', 20, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '라떼 휘핑 크림 넘 맛있어요! 디저트는 달달하고 실내 아기자기하게 꾸며져 있어요~ 인테리어 화이트 톤으로 깔끔하고 화장실은 연두색 타일로 포인트 줬던데 예뻐요! (수원 행궁동)', 28, 0, 'GOOD', SYSTIMESTAMP);
