INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '''멜로망스 김민석'' 생일 컵홀더 이벤트로 간 곳. 울산에서 새벽 4시부터 준비해서 갔다. 선착 받으려고. 결국 선착도 받고, 실제 민석님도 뵈었고 앨범에 싸인도 받았고 내가 만든 빵도 드렸다. 여기 멜로우 제추청귤에이드 맛있고 직원들도 다 친절하시다!', 21, 8, 'GOOD', SYSTIMESTAMP);
