INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '개인적으로 좌석은 불편한곳 안좋아하는데(인스타 감성테이블 의자같은거 •••) 초코케이크였나 그게 진짜 맛있었어요 진짜 완전 생초코 느낌 그래서 그거때문에 재방문 의사있음', 71, 11, 'GOOD', SYSTIMESTAMP);
