INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '딸기라떼와 퐁듀를 먹었는데 딸기라떼는 청이 우유에 비해 너무 많았고 퐁듀는 문의했을 때와 내용물이 달라서 별로였어요ㅠ 추가 바나나가 얼마나 나오냐고 했는데 3-4조각이라고 하셨는데 한개(5-6조각) 나왔었음... 남겼어요ㅠㅜ', 84, 14, 'BAD', SYSTIMESTAMP);
