INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '발렌타인데이 맞이해서 남친이 좋아하는 초콜렛 퐁듀 먹으러 왔어요~ 분위기도 좋고 음료도 맛있고 초콜릿 듬뿍!! 너무 잘 먹고 갑니다~ 남친도 넘나 좋아하네요~', 19, 4, 'GOOD', SYSTIMESTAMP);
