INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '으아아아 너무좋아요 알바님 너무 친절해요 퐁듀도 맛있고 분위기도 엄청 좋아요!! 따뜻한 분위기에서 따뜻한 사람들과 함께하면 좋을 거 같아요 💭🖤💛🧡', 220, 74, 'GOOD', SYSTIMESTAMP);
