INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '앤톤 생카여서 레몬에이드(6000원), 칵테일(9000원) 샀어요! 피치 알코올 칵테일 샀는데 술맛 하나도 안 났어요ㅎㅎ 내부 데코 너무 예뻤구 특전도 다 알차고 귀여워서 좋았어요!!! 넘 행복했어요. 아기자기하고 귀여운 공간이어서 좋았고, 외부에 포토부스도 있어요. 대만족❤️❤️', 12, 9, 'GOOD', SYSTIMESTAMP);
