INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '가격은 정말 가성비 있는 음료로 생각되었으며 일반 저가 커피의 경우 단일 원두만 제공하는데 이곳 바나프레소의 경우에는 약간의 선택권이 있다는 점이 장점으로 다가왔습니다. 음료의 가격도 저가 커피 매장들과 비슷하지만 다양한 음료를 제공하고 있어 선택사항이 많다는 점이 좋았으며 합정역 바로 앞에 있어 접근성 또한 괜찮다는 생각을 하였습니다.', 89, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '커피 가격 저렴하고 맛도 괜찮아서 자주 애용하고 가끔 베이글 포장하는데(크림치즈 추가주문). 아주 가끔 크림치즈를 바를때 사용할 나이프가 빼먹을때가 있어용. 저도 학인했어야 했는데, 혹시 포장하시는 분은 꼭 셀프 확인하세용. 일하시는 분들 언제나 친절하셔서 방문할때마다 만족합니다 :D', 26, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '진짜 걷다가 너무 너무 너무 추워서 못 견디겠어서 들어갔는데 정말 따뜻하고 정말 아늑했습니다 음료도 빨리 나오고, 직원 분도 친절하셔서 기분 좋았어요 원래 얼죽아였는데 밀크티는 핫으로 갈아타려 합니다,,추워,,,', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '커피가 전자동식으로 나와서 가격이 다른곳보다 싼듯. 원두는 나쁘지않은듯하다. 뱅쇼는 뱅쇼원액과 물 그리고 시나몬스틱등 들어감.내겐 조금달다.', 108, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '굿!! 맞은편 메가보다 훨배 맛있음 ㅋㅋㅋㅋ 친절하기도 하고 !! 오픈타임때랑 마감타임 다 이용하는데 집 가까이에 있어서 너무나 감사해하며 지내고있음', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '핸드폰 배터리가 없어서 나오자마자 들어갔는데 충전하는 콘센트는 창가 자리밖에 없고... 창가 자리에 앉았는데 의자는 움직이지도 않게 고정되어 있고... 정말 불편했습니다', 36, 4, 'BAD', SYSTIMESTAMP);
