INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '햄치즈머핀에 무슨 일이…?! 너무 맛있는데요?! 커피도 맛있는데 디저트/베이커리 류도 최고입니다. 음료 겉면의 스티커에 날짜별 마음의 소리가 인쇄되어 나오는데, 고거 확인하는 재미도 있네요. 👩🏻‍🍳', 37, 3, 'GOOD', SYSTIMESTAMP);
