INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '친구들이랑 오랜만에 만나서 재밌는 거 하려고 찾아보다가 철판아이스크림 꽂혀서 왔어요!! 아이스크림 엄청 좋아하진 않는데 맛있어서 진짜 다 먹은..!!! 엄청 어렵지 않고 재밋게 했어요!! 아이스크림 세 판 만들어서 배부르게 먹고가욤!!🏄🏻‍♀️🍨🍦', 28, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '철판 아이스크림을 만들어볼수 있다고 해서 궁금해서 예약했어요! 생각보다 이쁘게 안만들어지고 어려웠지만ㅠㅠ 맛있고 넘 신기했습니다~ 과자들도 많아서 넣기도 하고 그냥 먹기도 했어요! 재밌는 추억 만들어갈수 있어 좋아요 :) 생각보다 70분이 빠르게 지나가네요~ 다음에 다른 친구들이랑도 또 와보고 싶어요!', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '철판아이스크림을 만들 수 있다는 카페가 있다고 해서 왔습니다 ! 평소에 철판아이스크림을 사먹을 때 가게 주인분께서 만들어주시는 것만 보다가 직접 하다 보니 잘 안되기도 하고 그래서 더 재밌었던 것 같아요 ! 좋은 추억 만들고 가요 ! 재밌었어요 감사합니다 💓', 10, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '우선 왜 시간을 70분이나 주나?? 싶었는데 그럴만한 이유가 있더라구요! 한판 만들때마다 먹어야 되기 때문! 기본 우유베이스 하나에 추가로 2개 베이스 더 선택 가능해서 총 3판의 철판아이스크림을 만들 수 있습니다! 이렇게 빨리 수제아이스크림을 만들어 먹을 수 있다는데 되게 이색적 이었습니당ㅎㅎ 앞으로도 번창하시고 오래오래 계셔주세요! 잘 놀다갑니당.', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '너무너무 재밌게 놀다 갑니다🥰 예쁘게 만들기 쉽진않네용 🤣 그래도 가이드도 알려주시고 여러 조합으로 만들 수 있어서 좋았어요! 기계도 금방 금방 돼서 1시간도 충분했어용 크크 재밌게 놀다가요🫶💕', 42, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '특별한 데이트 하기 넘 좋아요~~ 생각보다 달고 생각보다 맛있었고 생각보다 잼썻어요! ㅎㅎ 분위기도 정겨운 인테리어라 더 아늑한 느낌도 있어요 근데 벌써부터 타코야끼 자리가 마련되어 있던데 원하는 자리를 못앉아서 좀 아쉬웠어요 ㅜㅠ', 114, 22, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '철판아이스크림 만들기 해보고 싶어서 예약하고 왔어요٩( ᐛ )و 쉬울 줄 알았는데 생각보다 어려워서 당황했지만 막판엔 성공적으로 말아서 재밌었어요! 토핑 부수는 것도 스트레스 풀리는 느낌이었어요!! 재밌게 만들고 맛있게 먹고 갑니다~~', 110, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '도란도란 소소한 추억을 만들고 싶다면 추천! 어색어색 눈을 돌릴 만한 주제가 필요한 상대와 데이트를 해야한다면 추천!! 달콤달콤 아이스크림을 좋아 한다면 도란도란에서 아이스크림 만들기 추천합니다 ​ 13살 아들과 데이트 하며 왔지만 푸릇푸른 데이트 하러 오신 젊은이들을 보니 어릴적 데이트 하던 시절 생각 납니다', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '크림 종류도 3가지나 주시고 토핑도 엄청 많아서 양껏 만들고 먹고 갑니다!! 어디에서도 해 볼 수 없었던 철판 아이스크림 만들기 해봤는데 생각보다 롤 마는게 어려웠지만 너무 재밌고 맛있었어요~~ 다들 커피+우유에 보리과자 로투스 조합 해보세요 짱...👍 다음에 또 와서 만들어보려구요~~', 34, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '11살 아이와 함께했어요. 사장님이 친절하셨고 아이스크림 세 가지를 만드는데 토핑이 여러가지라서 다양한 레시피를 이용할 수 있어 더 즐거웠습니다. 생각보다 아이스크림 양이 상당하고 정말 맛있었어요!', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '이색데이트 즐기고 싶어서 예약했어요. 제가 앉은 자리는 레트로한 분위기라 좋더라고요.  철판아이스크림 만들기는 처음이라 이쁘게는 못만들었지만 재밌었어요 과자는 너무많이 넣지 않는 것을 추천드립니다 안 그러면 과자맛밖에 안 나요 ㅋㅋ', 21, 3, 'GOOD', SYSTIMESTAMP);
