INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '기념일이라 예약 후 방문 했습니다! 이색적인 데이트를 원하신다면 추천해요~좀 달긴 했지만 그래도 재미나게 즐긴 것 같습니다☺️ 겨울에 다코야키 만들러 오겠습니다', 31, 10, 'GOOD', SYSTIMESTAMP);
