INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '처음 해보난 이색 데이트였습니다! 매번 유튜브로만 철판 아이스크림 보고 해보고 싶단 생각 들었는데 재밌네요🥹 생각보다 만들기도 쉽고 아이스크림도 너무 맛있엇어요 다음에 또 올게요 :)', 12, 7, 'GOOD', SYSTIMESTAMP);
