INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '이색데이트로 잘 놀다 갑니다!! 과자를 많이 넣으면 생각보다 넘 달더라구요!! 양도 많아서 배불러요~!~! 시간도 순삭이라 시원하고 좋았오요!!', 72, 13, 'GOOD', SYSTIMESTAMP);
