INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '남자친구가 디저트를 좋아해서 방문하게 되었어요 노래 선정도 완전 저희 스타일이었고 좌식이어서 편하고 고즈넉하게 데이트했어요 꿀팁을 알려드리자면 조금 뭉쳤을 때 피고 하시는 게 좋아요 그리고 피고 빨리 마셔야 안 망쳐요!! 토핑 딸기 너무 맛도리였고 잘 놀다 갑니다💗🫶🏻', 40, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '유튜브로만 만드는거 봤는데 직접 해보니까 재밌는거 같아요ㅋㅋㅋ! 연인과 이색데이트로 하기에 좋은거 같습니당 특별하게 데이트 하기 오늘도 성공!! 만든건 야무지게 먹었숩니다~~~🩷😋🩷', 36, 7, 'GOOD', SYSTIMESTAMP);
