INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '인테리어가 너무 맘에 드는데 철판 아이스크림을 같이 만들어 먹울 수 있어서 너무 재밌었어요!! 데이트 코스로 와보기 딱 좋은거 같아요!!ㅎㅎ', 452, 62, 'GOOD', SYSTIMESTAMP);
