INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '친구랑 도란도란 2호점에 와서 재밌게 놀다 가요. 일단 가게 인테리어도 멋지고 이용시간은 도착시간으로부터 70분이라 철판 아이스크림 만들며 여유롭게 놀 수 있어서 좋았습니다.맛 2가지 + 과일 1가지 선택 가능하고 각종 토핑들이랑 우유는 기본으로 제공돼요! 애인이랑 이색 데이트로도 추천 드립니다.', 18, 2, 'GOOD', SYSTIMESTAMP);
