INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '데이트 코스로 너무 추천합니다!! 철판 아이스크림을 직접 해먹어보는 재밌는 추억 만들고가요! 원하는 재료를 넣을수도 있고 직접 해보며 먹고 웃느라 시간이 금방 지나갔네요!', 23, 2, 'GOOD', SYSTIMESTAMP);
