INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '이색데이트로 좋아요 철판 아이스크림을 예전부터 만들어보고 싶었는데 이번 기회에 제대로 만들어보니 랭갇보다 어려웠어요ㅠㅠ 다음번에 방문할 땐 모양을 더 잘 잡을 수 있을 것 같아요! 잘 놀다 갑니다', 1, 5, 'GOOD', SYSTIMESTAMP);
