INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '오랜만에 홍대와서 여름 지나가기전에 철판아이스크림 만들기체험 이색적인데이트로 완전추천이요!! 기본토핑도 많이 주시고!! 재미있게 잘놀다가갑니다~!!', 15, 1, 'GOOD', SYSTIMESTAMP);
