INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '원래 타코야키를 만들던 카페였는데 여름이라 철판아이스크림으로 바뀌었길래 방문했어요!! 같이 만들어먹으니까 너무 재밌고  맛있고 토핑도 다양해서 너무 좋았습니다!!! 만드는것도 많이 어려울까봐 걱정했는데 아이들도 와서 해도될정도로 별로 안어렵고 재밌게 할 수 있었던 것 같아요!!!', 27, 1, 'GOOD', SYSTIMESTAMP);
