INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이색적인 인테리어 디자인과 함께 남자친구랑 철판 아이스크림을 처음 만들어보는데 너무 재밌었습니다! 처음에는 어떻게 해야할지 몰랐지만 3번만에 성공했어용! 재밌있고 특색있는 데이트코스로 추천합니다~', 17, 9, 'GOOD', SYSTIMESTAMP);
