INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '겨울엔 타코야끼를 만들고 싶었는데 예약이 차있어서 못했는데 여름엔 철판아이스크림이라 좋아요!!!🍦✨ 시간적인 여유가 부족하다는 리뷰보고 걱정했는데 재밌게 만들다보니 생각보다 빨리 만들어져서 시간도 여유로웠어요~!!!☺️👍 이색데이트로 추천합니다!!!🍭👍', 28, 8, 'GOOD', SYSTIMESTAMP);
