INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '이색데이트로 철판 아이스크림 만들기 하러 왔는데 너무 재밌었어용! 토핑도 다양하고 푸짐하더라고요 베이스도 3가지나 있어서 여러가지 맛으로 먹을 수 있어서 좋았습니다 강추!', 16, 6, 'GOOD', SYSTIMESTAMP);
