INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '컨셉이 확실하네요 외갓집 좌식 ㅎㅎ 옛날 지압슬리퍼랑 자개장까지 ㅎㅎ 맨발입장이니 양말 조심! 70분 충분히 즐길수있어요 들어온 어른들 모두 즐거워하는것 같고 초등 어린이 물론 엄청 즐거워했어요 ㅎㅎ 보통 이런건 1회성이고 다시 안오는 경우가 다반사인데, 다음에 재방문할것같아요~ 생각보다 기술이 많이 필요합니다 예쁘게만들려면 토핑양을 아주적게~', 159, 28, 'GOOD', SYSTIMESTAMP);
