INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '처음 와봤는데 직접 만드는 재미도 있고 맛도 좋아서 데이트 코스로 딱 좋고 아이스크림 만드는 과정이 신기하고 직원분도 친절해서 즐겁게 체험했습니다.', 49, 0, 'GOOD', SYSTIMESTAMP);
