INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '철판아이스크림 맨날 유튜브로만 보다가 해보게 되어서 재밌었어요! 맛도 있고 토핑 완전 많아요ㅋㅋㅋ 근데 1시간 10분 정도밖에 안줘서 진짜 만들고 먹고 만들고 먹고 좀 바빠요...ㅋㅋㅋ', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '철판아이스크림 체험 너무 재밌게 했어요 둘이서 오면 총 세번? 할 수 있는데 두번 말아보니까 동그랗게 마는 감이 잡히네요 ㅋㅋㅋ 좋은 시간 보내고 갑니다', 26, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '아이들이 철판아이스크림 해보고싶다해서 이모의 깜짝선물로 예약하고왓어요ㅎㅎ 주차는조금불편하지만 아이들에게 좋은추억이 된거같아요 설명도잘해주시고 재료도깔끔하게 나와서 너무 좋아요 나가신분들 뒷정리도 깔끔하게 정리해주시는 모습에 믿고 또올수잇을꺼같아요ㅎㅎ', 42, 1, 'GOOD', SYSTIMESTAMP);
