INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '베트남에서 종종 먹어봤는데 막상해보니까 어렵고 기술이 필요한거같아요 ㅎㅎ 아이랑 방학때 즐거운걍험이었어요! 양도 많아서 배불러요', 69, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '내 입맛대로 코스텀할 수 있는 철판 아이스크림이라 너무 재밌고 맛있었어요😋 선택할 수 있는 토핑도 여러가지라 같이 고민하면서 더 즐거운 경험이 됐어요 ㅎㅎ 다음에 시원하게 철판아이스크림 만들고 싶을때 또 올게요', 29, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '철판 아이스크림을 직접 만들어볼 기회가 없었는데, 남자친구 생일에 같이 와서 특별한 경험을 해봐서 너무 좋았어요! 처음에 생각보다 요거트가 빨리 굳는데, 그렇다고 갑자기 아이스크림 기계를 끄시면 안 돼요! 다시 차가워지는 데 생각보다 오래 걸립니다 :) 즐겁게 잘 놀고 갑니다!!', 37, 5, 'GOOD', SYSTIMESTAMP);
