INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '되게 색다른 경험이었어요!! 옛날에 먹던 철판 아이스크림을 만들어서 먹는 경험이 되게 재밌고 애기들이랑 오면 좋아할 것 같아요!!', 0, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '부산에서 여행 오며 미리 예약하고 왔어요! 부산에는 없는 체험 할 수 있어서 좋아요 중딩,초딩 둘다 너무 재밌게 체험 했어요~~ 겨울에 타코야끼 만들러 또 올께요! 아이스크림 양 너무 많아요ㅎㅎㅎㅎㅎㅎ', 100, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '데이트 장소로 강추에요! 제가 오고 싶어서 왔는데 남자친구가 더 좋아하네요 ㅋㅋ 처음엔 어려웠지만 그래도 마지막엔 성공! 다음에 또 올게요~', 50, 10, 'GOOD', SYSTIMESTAMP);
