INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '너무너무 재밌었어요! 딱 처음 해볼때는 좀 어려웠는데 그 다음에 할땐 딱 감이 잡혀서 좀 예쁘게 만들어진 것 같아서 만족~😝 이색데이트로 늦여름 더위 날리기 좋은 것 같아요!!', 74, 18, 'GOOD', SYSTIMESTAMP);
