INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '재밌고 색다른 데이트였어요! 만드는것도 재밌고 재료도 많아서 꾸미는 재미도 있어요! 사장님도 친절하시고 색다른 데이트 재밌게 잘 놀고 먹고 갑니다!', 53, 14, 'GOOD', SYSTIMESTAMP);
