INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '분명 쉬워보였는데 막상 해보니 너무 어렵더라구요 ㅠㅠ ㅋㅋㅋㅋㅋㅋ 그래두 재밌게 했습니다 ..!!!! 사장님도 친절하시구 시원해서 너무 좋았어요 ~', 26, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '시간 가는 줄 모르고 재밌게 만들었어요! 직접 만들어먹으니까 더 맛있는 것 같고 토핑도 많아서 좋습니다😍 겨울에 다른거 하러 또 오고싶어요!', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '철판 아이스크림 체험 재밌어 보여서 갔습니다! 만들고 나니 아이스크림 엄청 먹었네요,,, 맛있고 체험도 잼썻어요,, 🤩그 돌돌 말리는게 생각보다 어렵더라구요 ㅋㅅㅋ .. !! 토핑거리도 많고 과자도 많이 주심!! 근데 양을 좀 줄고 가격을 낮춰듀 될거 같아요 ㅠㅠ!!!🥹 아이스크림 넘 먹어서 혈당 스파이크 옴,,,😇', 19, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '철판 아이스크림을 직접 만들 수 있다고 해서 방문했어요!! 직접 만드니 너무 재밌고 신기하고 그래서 더 맛있게 먹은 것 같아요! :)', 62, 13, 'GOOD', SYSTIMESTAMP);
