INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '특유한 컨셉이라 방문해봤는데 기대했던 것보다 훨씬 좋았어요 ! 아이스크림 만드는 게 어렵긴 했는데 다른데서 경험할 수 없는 거라 좋았고 인테리어도 친근한 할머니집 스타일이라서 편안하게 즐길 슈 있옸습니당 다음에 또 오려구요 ㅎㅎㅎ✧.ﾟ٩(๑>◡<๑)۶:｡♡ 그리고 아이스크림 넘 맛있어용', 105, 26, 'GOOD', SYSTIMESTAMP);
