INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '여자친구랑 여름맞이 데이트로 놀러왔어요! 철판 아이스크림을 직접 만들 수 있어 재밌습니다. 맛도 있구요! 근데 생각보다 잘 만들기 어려웠어요... 토핑은 조금 넣고, 좀더 얼려서 말아주세요. 요거트맛 추천합니다! 딸기랑 섞으니 맛있었어요 ㅎㅎ', 71, 11, 'GOOD', SYSTIMESTAMP);
