INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '너무 좋았어요 이런 폭력적인 날씨에 실내에서 그냥 아이스크림도 아니고 철판 아이스크림을 직접 만들어서 막을 수 있다니 정말 이색적이고 신기하고 즐겁고 기쁜 경험이었습니다 강추!!', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '철판 아이스크림 체험 진짜 재밌었어요! 재료 고르고 바로 눈앞에서 만드는 과정을 보니까 신기하고, 소리랑 퍼포먼스까지 보는 재미가 있었어요. 완성된 아이스크림은 부드럽고 달달해서 맛도 최고👍 분위기도 좋아서 데이트 코스로 딱 추천합니다! 맛있는 디저트 먹으면서 특별한 추억까지 만들 수 있어서 만족했어요.', 6, 6, 'GOOD', SYSTIMESTAMP);
