INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '예약하고 10분정도 일찍 왔는데 바로 입장했고 안에 에어컨 빵빵 틀어주셔서 좋았어요! 아이스크림 만들기는 생각보다 어렵고 운동이 되었지만 그래도 재밌었습니다 ㅎㅎㅋㅋㅋ 한번뜸 와서 데이트 해볼만한 곳..!', 52, 17, 'GOOD', SYSTIMESTAMP);
