INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '처음 만들어봤는데 역시나 처음부터 망했슺니다ㅎㅎ❤️ 근데 남자칭구는 처음부터 성공해서 약간 열받았지만 그래도 재밌었어요 다음에 또 올게요 아디오스', 53, 16, 'GOOD', SYSTIMESTAMP);
