INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '항상 예약이 꽉 차있어서 오기 어려웠는데 2호점 생기니까 너무 좋아요!!! 매장도 시원하고 쾌적해서 여름에 오기 최고인것같습니다 재밌게 데이트하기 좋은것같아요!!', 338, 68, 'GOOD', SYSTIMESTAMP);
