INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '첫 방문인데 감성이랑 맛 둘다 있어서 나중에 또 방문 예정입니다! 만들기는 조금 어렵지만 계속 도전하고 싶은만큼 너무 재미있었어요  도란도란 덕분에 여자친구랑 잘 놀다갑니다!', 48, 6, 'GOOD', SYSTIMESTAMP);
