INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '남자친구랑 이색데이트하러 방문했어요! 한번 만들어보고 싶었는데 생각보다 힘들었지만 너무 재밌었어요 ㅎㅎ 겨울엔 문어빵도 만들러 오고 싶어요..💕', 42, 5, 'GOOD', SYSTIMESTAMP);
