INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '토핑도 엄청많이 주시고 처음이라서 어려울줄 알았는데 가이드도 주시고 친절하세요!!재밌는 체험이었습니다!! 겨울에 타코야끼 만들러 또 올게요~~', 43, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '영상에서만 보던 철판아이스크림을 직접 만들어 먹어볼 수 있는 기회!! 친구랑 또는 가족이랑 만들어 먹는 재미!!! 여러가지의 재료와 베이스로 조합하는 재미!!! 더운 여름 시원한 실내에서 나만의 조합으로 재미있게 맛있게 즐겁게 철판아이스크림을 만들어서 여러가지 토핑을 올려 맛있게 먹어보세요^^ 즐거운 추억을 만들 수 있어서 좋았습니다!!! 만드는게 생각보다 재미있고 맛있었습니다!!', 43, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '여름에 실내 데이트로 딱인 것 같아요 너무 재밌었어요! 처음에는 조금 어려웠는데 하다보니까 쉬워서 계속 만들었어요!!🩷 데이트 코스로 추천합니당!', 61, 17, 'GOOD', SYSTIMESTAMP);
