INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '일단 너무 친절하시고 70분 내에 3판이나 만들 수 있어서 양이 진짜 많아요!! 하나하나 직접 꾸밀 수 있는 것도 너무 좋고 그리구 넘 맛있습니다..👍🏻 데이트나 친구들이랑 가면 이색적이고 좋을 것 같아용', 3, 9, 'GOOD', SYSTIMESTAMP);
