INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '더운 여름 시원한 공간에서 이색데이트 재밌게하구갑니당 아이스크림 말기 은근히 어렵더라구요 한 번 더 하면 더 잘할 수 있을거 같아요🔥', 30, 8, 'GOOD', SYSTIMESTAMP);
