INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '여자친구랑 처음 만들어봤는데 되게 재밌게 만들면서 놀았어요...!! 만드는데 흥분해서 정신차리고 보니 저런 사진만 있더라구요 ㅠ 그만큼 생각보다 훨씬 재밌습니다!! 다음에는 타코야끼 만들러 올게용', 226, 31, 'GOOD', SYSTIMESTAMP);
