INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '철판아이스크림 만들고 싶어서 예약했는데 생각보다 어려웠지만 직접 만들수 있어서 재밌었고 기본토핑도 많이 주셔서 여러가지 만들수 있어서 좋구 맛있었어요 이색데이트로 추천합니다', 32, 1, 'GOOD', SYSTIMESTAMP);
