INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '(홍대 근처 공룡빵공장 리뷰입니다) [주소 오류가 떠 신고] 아침용 빵 사러 급히 들른 곳인데 빵도 따끈따끈하고 맛있어 만족한 곳 감자 고로케: 3,000원 속에 든 감자 양도 많고 맛있다.', 15, 3, 'GOOD', SYSTIMESTAMP);
