INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '꿀토마토: 진심 너무 달지도 않고 신선한 토마토 주스 맛. 완전 맛있었어요 ㅋㅋㅋ 카이막: 생각보다.. 담백한 카이막 아이스페퍼민트: 티백이 아니라 입차 그대로의 깔끔한 맛이라 좋았어요', 79, 13, 'GOOD', SYSTIMESTAMP);
