INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '커피와 베이커리 모두 훌륭하고 종류도 다양해 방문할 때마다 새롭고 매장도 아늑해 편히 쉬다가기 좋다. 연희동에도 분점이 두 곳 있던게 그 매장들고 방문해보고 싶다 :)', 5, 7, 'GOOD', SYSTIMESTAMP);
