INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '필테랑 요가수업 중간에 공룡빵공장의 샌드위치를 점심대신에 먹는데 가성비도 좋고 든든합니다. 샌드위치를 사서 로렌드론으로와서 먹으면 맛있는 커피를 3천원에 할인받아서 같이편안하게 먹을수 있어요!^^', 41, 6, NULL, SYSTIMESTAMP);
