INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '지나가다 우연히 보고 들어간 카페. 인테리어도 맘에 들고 특히 커피 맛이 예술~ 점심 먹으러 가기전 잠깐 방문했던 곳이라 다음에 여유있게 와서 천천히 있다가야겠습니다^^ 완전 럭키비키!!!', 14, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '카이막은 첨 먹어봤는데 듣던대로 부드럽고 진한 지방 맛?색달라서 좋았음... 커피는 고소한 원두 선택했는데 스벅과 비슷한 느낌...', 53, 16, NULL, SYSTIMESTAMP);
