INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '까눌레 크기가 너무 작으면 도로 나가는 사람인데 여기는 크기도 적당한데다 식감이 부드럽고 깊은 맛입니다 그래서인지 부모님께서 더 좋아하셨어요.', 118, 23, NULL, SYSTIMESTAMP);
