INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '가게위치가 찾기 쉬웠고 까눌레 몇개 포장해가는데 직원분께서 친절하셨어요. 1층에는 사람들이 많은 편이었으며 까눌레 바닐라 맛이 인기가 있나봐요  저도 이거사러오긴했는데 다 떨어져서 모카맛으로 구입했어요 [하나당 2,800원] 당일에 먹었을 때 식감은 부드러운 편이었습니다 :]', 35, 2, NULL, SYSTIMESTAMP);
