INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '아침 먹으러 방문했는데 샌드위치 신선하구 맛있었어요!! 카페 분위기도 예뻐요❤️ 빵이 전체적으로 저렴한데도 퀄리티가 좋아요!! 특히 까눌레 맛집!!! 카스테라크림빵두 맛있어요ㅎㅎㅎ추천합니당!!', 16, 3, 'GOOD', SYSTIMESTAMP);
