INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '매장이 진짜 넓음 지하에서 키오스크로 주문 1층 테라스와 2층 매장으로 구분 매장은 통일화된 인테리어가 아니여서 뭔가 질서가 없는 듯하지만 오히려 대화를 편하게 나누기엔 더 없이 좋음 매장이 넓어 테이블 간격이 너무 좋음 너무 인스타감성의 카페보다 자주 가기 좋은 느낌 커피는 아이스를 아이스로 시키려다 핫으로시켜당황해 하니 흔쾌히 바꿔주셔서 너무 고마웠음 직원분들도 너무 친절', 46, 1, 'GOOD', SYSTIMESTAMP);
