INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '디카페인이 있어 너무 좋았어요. 추가금도 없네요~ 커피 진하고 맛나고, 시나몬이 들어간 크림커피가 시그니처 같은데 달달하니 너무 맛있네요! 직원분이 참 친절하셔서 기분좋고 먹고 갑니다~ 추천!!', 22, 0, 'GOOD', SYSTIMESTAMP);
