INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '직원분들 모두 쏘 친절하시구 음료도 진짜 맛있어요 😋 소금빵도 데워주셔서 맛있게 먹었습니다 ! 1층, 2층 다 넓고 좌석도 편해서 어디든 앉기 좋아요 ~~', 91, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '사장님 넘 친절하시고 커피 연하게 달라고 하니까 마시고 진한 거 같으면 말하라 하시고ㅠㅠ 빵이랑 음료 다 너무 다 맛있었어요 ^__^🍀✨✨✨✨🌵', 1, 6, 'GOOD', SYSTIMESTAMP);
