INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아침..이 아닌 점심 먹으러 들렀어요~ 앙버터 모카번 둘다 맛있구용 아아는 산미 없는거 했는데도 산미가 있어 초큼 아쉽.. 라떼 구수하고 찐하구 맛있습니댱😊', 21, 5, 'GOOD', SYSTIMESTAMP);
