INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '커피가 맛있어요. 디저트도 특별한 디저트들이 많아요. 사진을 못찾아서 올리지 못하는게 안타깝네요. 빵과 특별한 케이크들이 많아요.', 50, 1, 'GOOD', SYSTIMESTAMP);
