INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '내가 애정하는 카페!  커피맛 좋고 친절하고 아지트 같은 느낌! 사람들은 늘 많고 분비지만 2층도 있고,  일주일에 주3일정도는 방문하는곳!', 1, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '다 좋은데 사장님처럼 보이는 초록색 티셔츠 입은 분이 마스크 착용 안 하고 음료 내려서 조금 그랬어요 평소 다른 직원분들은 마스크 열심히 쓰시던데;; 요즘 같은 시기에 주의해주시면 좋겠어요 ㅜ', 78, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '집 주변에 있어서 지나다니다 궁금해서 와봤는데 분위기도 좋고 커피맛도 좋아서 자주 다니구 있어요😊 인테리어도 이쁘고 포근포근.. 편한 느낌 ~ 단 거 좋아하시는 분들은 크림브륄레라떼 추천!! 달달구리 짱 맛있습니당👍👍', 49, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '지나가다가 우연히 발견해서 들어갔는데 너무 만족하고 나왔어요 평일 오후라 사람이 적었는데 카페 분위기가 친구와 얘기하기도 좋고 독서하기도 좋은 분위기라 마음에 들었어요 또 인테리어도 이쁜데 흔하지 않는 느낌? 특히 주문한 딸기타르트가 진짜로 맛있었어요!! 지금까지 먹어본 딸기타르트중 가장 맛있었던 것같아요 인테리어도 좋고 디저트랑 음료도 맛있어서 다 너무 마음에 들어서 같이 간 친구랑 계속 여기 사장님 뭐하시는 분이냐고ㅋㅋㅋㅋ 다 너무 좋아서 감탄할 수도 밖에 없던 카페였어요 다음에 또 방문할 계획입니다ㅎㅎㅎ', 11, 4, 'GOOD', SYSTIMESTAMP);
