INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '또 한 번 찾은 공룡빵집~ 지난번에는 저녁에 가서 빵이 많이 남아 있지 않았는데 오늘은 드디어 성공했네요. ㅎㅎ 그중에서도 ‘구루미앙빵’이 이곳의 시그니처 빵이라고 하더라고요. 집에 가서 얼른 맛보고 싶습니다. ^^', 62, 12, NULL, SYSTIMESTAMP);
