INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '정말 어마어마한 가성비 맛집이네요! 빵와 디저트 종류만 50가지 정도 되는거 같네요 여긴 포장만 가능한 곳이어서 지나다 포장해 가시면 좋을 듯 합니다 1위 코믹연극 죽여주는이야기 추천 맛집~*', 24, 1, 'GOOD', SYSTIMESTAMP);
