INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '* 치아바타샌드위치 / 단호박깜빠뉴 샌드위치가 땅겨서 들렀는데 매장에 앉을 장소가 없어 망설였는데 …. 반전 가까운 곳에 있는 로덴드론 카페 이용하면 되요. 이집 커피가 맛있어 점심시간에 항상 붐비는 곳인데 빵영수증 보여드리면 1,500원에 아메리카노 마실 수 있어요. 커피 생각이 없어 그냥 앉아도 되냐 물었더니 믈론이고, 접시 포크 필요하시냐고 물으시네요~ 사진과 같이 단호박 어마무시하게 들어있어요. 샌드위치만으로도 충분히 배부릅니다. ㅎㅎ 편안한 장소에서 맛점했네요!', 44, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '빵이랑 케이크류도 저렴하면서 맛있어요!! 메론빵 크림은 메로나맛나면서 맛있고, 토마토바질크림치즈는 진짜 갈 때 마다 사요...! 최고!', 2, 0, 'GOOD', SYSTIMESTAMP);
