INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '깔끔하게 개별 포장으로 되어 있어요 베이커리에서 좀 더 가면 앉아서 차와 베이커리를 즐길 수 있는 카페가 있어요 빵도 맛있고 아담한 사이즈여서 커피하고 먹기 좋아요 카페 보다는 베이커리에 빵 종류가 더 많아요 치즈케이크 맛있고 말차 파운드케이크도 맛있었어요 담백하고 깊은 맛 ~ 단 가격은 조금 있어요 몇개 사니 훌쩍 금액이 , ㅋㅋ 로덴드론 베이커리 인데 영수증 상호명은 조금 달라서 맞나 싶었네요', 40, 3, NULL, SYSTIMESTAMP);
