INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '지나가다 매장과 케잌류가 너무 예쁘고 아기자기해서 들렀는데 호밀빵도 있고 잡곡콘식빵도 있어서 구매했는데 굿이에요 가격도 비싸지 않구요', 15, 0, 'GOOD', SYSTIMESTAMP);
