INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '넘 친절하세요~그래서 일단 기분이 넘 좋았습니다. 스콘 맛이 넘 좋네용~~ㅎㅎ 스콘 먹는방법까지 일일히 다 알려주시공 넘 만족스러웠습니다~감사김사', 41, 2, 'GOOD', SYSTIMESTAMP);
