INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '첨엔 코발트블루 색감이 예쁜 외관에 반해 들어갔는데 뜻밖에 숨은 맛집 벌써 몇번째 방문인지 ㅋ 하나하나씩 다 먹어볼테다 하는 마음 가짐으로 이번엔 큐빅레몬파운드 도전 예쁜것이 상콤하기까지~ 커피에 너무 잘 어울리는 디저트네요! 사장님도 친절해서 또 가게될듯~~~', 31, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '평소에는 시그니처라는 솔티드.. 뭐더라.. 가운데 버터가 든 빵을 먹어요. 오늘은 문 연지 얼마 안되서 가니까 그 빵이 나오기 전이더라구요. 그래서 프레젤과 레몬 마들렌을 먹었습니다.. 프레젤은 독일 것과 다르지만 빵 질감이 남달라서 좋고, 마들렌은 레몬향이 풍부해요.', 7, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '제가 먹어본 앙버터 중에 제일 맛있어요ㅠㅠ프레첼도 부드럽고 촉촉하고 버터도 통으로 들어가있는데 느끼하지 않고 딱 적당해요 !! 오늘 사서 가족이랑도 먹고 친구랑도 나눠먹었는데 다들 맛있다고 했어요 처음 지인 통해서 먹어보고 맛있어서 사장님께 말씀드리니 마들렌까지 서비스로 주시고 ㅠㅠ 너무 친절하셨어요 나중에 또 갈게요 🧡', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '종종 가는 빵집이에요! 시식을 할 수 있어 마음에 드는 빵을 수월하게 고를 수 있어서 좋아요👍 가격은 다른 빵집과 비슷한 편입니다.', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '기타 피크를 구입한 후, 전부터 분위기 있어보여 눈여겨 본 터라 방문해보았습니다. 여타 다른 곳들처럼 비싸기만 하고 퀄리티도 떨어지면 그냥 나오려고 생각했는데, 왠걸 기대하고 상상한 퀄리티보다 더 나은 퀄리티를 보여주는 곳이어서 빵을 구입했습니다. 그리고 대만족해서 리뷰할 곳을 사장님께 여쭤보고 글을 씁니다. 우선, 가격이 착하다 못해 환상적입니다. 저.... 빵처돌이거든요...? 심지어 기억력도 나쁘진 않아요... 그런데, 이 빵집은 제가 한참 빵을찾는하이에나 일때의 가성비로 팔고있더라고요...(최소로 잡아도 10년 전의 가성비에요....^^) 그리고 빵의 다양성과 그 하나하나의 퀄리티.... 무엇보다 우리나라빵들과 다르게 눈보다 입이 더 호강했습니다. 단골이 되고파요~^^', 51, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '동교동에 이렇게 아늑하고 좋은 카페가 있었다니..🛋️🤎 특히 티 아메리카노는 처음인데 너무 새롭고 맛있었어요! 페퍼민트의 시원함과 아메리카노의 고소함으로 같이 먹은 호두과자와 찰떡이었습니다 .. 🥜🤍 그리고 호두과자는 제가 먹어본 호두과장 중에 제일 최고였어요 💗 (사장님께서 직접 바로 만들어 주셔서 더 더 맛있었던,,) 특히 반죽이 넘 맛있어요 ..🤍 다음에 또 오께요오🙋🏻‍♀️', 26, 6, 'GOOD', SYSTIMESTAMP);
