INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '편안한 분위기 속 식후의 나른함을 씻을 수 있는 곳이에요. 시원한 캐모마일엔 사과시럽이 깔려있어 달콤하게 즐길 수 있어요. 말렌카는 달콤한 시나몬향이 잘 느껴지는 맛있는 케잌이에요. 사장님이 친절하시고 자리도 넉넉해 친구, 가족, 동료와 수다를 떨 수 있는 좋은 공간입니다.', 19, 3, 'GOOD', SYSTIMESTAMP);
