INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '호두과자를 사시사철 먹을 수 있는 귀여운 홍대 커피맛집!! 티아메리카노라는 독특한 메뉴가 있네요 작은 카페이지만 오히려 그래서 붐비지 않고 좋아요 틀어주시는 재즈가 좋아서 조용히 작업하고 싶을 때 종종 올 거 같아요~~', 15, 10, 'GOOD', SYSTIMESTAMP);
