INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '너무 더워서 들어온 카페인데 분위기도 너무 좋고 사장님도 친절합니다!! 티 아메리카노가 있어서 한번 시켜봤는데 차랑 커피 조합이 이렇게 좋을 줄이야!! 살구에이드에 들어간 살구청도 직접 만드신 건지 과육도 씹히면서 달달하니 좋았습니다💛🧡 다들 와서 티아메리카노 꼭 시켜보세요!! 추천합니다👏🏻👍🏻👍🏻', 15, 4, 'GOOD', SYSTIMESTAMP);
