INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '동교동에 이런 곳이..! 티아메리카노 끝맛이 너무 깔끔하고 맛있어요 ㅠㅠ 블랙피치 강추 호두과자도 앙금 실하고 호두알도 크고 바로 구워주셔서 더 맛있어요', 44, 4, 'GOOD', SYSTIMESTAMP);
