INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '남자친구와 연남동 데이트 중 아이테르 방문했는데요 매장이 넓지 않아 조용하게 시간 보낼 수 있었고 말렌카 꿀 케이크!! 호두 맛으로 먹어봤는데 달달하고 고소하니 제 입맛에 딱이었어요!', 39, 7, 'GOOD', SYSTIMESTAMP);
