INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '동교동에 위치한 아기자기한 카페♥️ 아메리카노가 정말 맛있었어요! 독특하고 ㅎㅎ 종종 생각날거같네요 말렌카 꿀케이크와 잘 어울렸습니다~~ 또 방문할게용 ㅎㅎ', 41, 0, 'GOOD', SYSTIMESTAMP);
