INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '매장이 너무 아기자기하고 예뻤어요! 호두과자, 수박쥬스, 티아메리카노 먹었는데 모든 메뉴가 다 성공적! 사장님 정말 친절하시고 아기랑 같이 왔다고 서비스로 아이스크림도 챙겨주셨어요~ 홍대에 이렇게 예쁜 카페가 생겨서 좋아요! 테이크아웃 하면 아아가 1800원이라 가성비도 최고예요! 커피 진짜 맛있었어요!! 다시 갈게요! 최애카페 등극✨', 88, 12, 'GOOD', SYSTIMESTAMP);
