INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '맨날 먹는 바닐라라떼 질린다면 한 번 씩 티 바닐라라떼 드시러 오세요~~ 이색적이면서도 맛있어요!!👍🏻👍🏻 인테리어도 이쁘고 아늑하면서도 좌석수도 적지 않고 디저트도 맛있어요~!!!', 128, 25, 'GOOD', SYSTIMESTAMP);
