INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '가게 분위기가 편안하고 아늑해서 좋아요~ 호두과자도 갓 만든 거여서 너무 맛있게 잘 먹었어요 티 아메리카노는 처음 마셔보는데 생각보다 맛있었어요✨ 데이트나 쉬어가기 좋은 카페예요😆🍀', 48, 8, 'GOOD', SYSTIMESTAMP);
