INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아이테르는 홍대역 2번출구에서 가까운 곳에 위치하고 있어요. 티 아메리카노를 다양한 맛으로 선택할 수 있고 시즌별 수박주스나 토마토주스를 제공하고 있더라구요. 조용한 분위기에서 대화나누기 좋은 장소에요. 대표 디저트 메뉴인 호두과자(5알)도 속이 꽉차고 바로바로 구워주시는 디저트로 제공되어 있어 더욱 맛있답니다. 홍대에 데이트하거나 연인과 잠시 머물다가는 곳으로 아이테르 들려보세요!♡', 47, 1, 'GOOD', SYSTIMESTAMP);
