INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '매장이 너무 아늑하고 좋아요🥹 혼자 시간 보내러 오기도, 친구들이랑 수다떨러 오기에도 너무 좋은 공간이에요. 인테리어가 제가 넘 좋아하는 우드톤 가득한 감성이 대박..💚 티아메리카노도 맛있고, 호두과자도 직접 만드시는데 진짜 호두 왕큰 거 들어가있고 너무 맛있어요💚', 28, 0, 'GOOD', SYSTIMESTAMP);
