INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매장 분위기가 너무 좋아서 방문했는데, 직원분도 너무 친절하시구 무엇보다 음료랑 커피가 너무 맛있어요!! 토마토주스 바로 토마토 갈아서 만들어주시는데 넘 맛있고 호두과자를 수제로 주문과 동시에 만들어주시는데 팥도 듬뿍 들어가있고 겉바속촉 넘 맛있었어요💕', 130, 25, 'GOOD', SYSTIMESTAMP);
