INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대입구역이랑 연남동 사이에 있는 카페 아이테르 다녀왔어요. 위치가 좋아서 접근성도 좋고, 전체적으로 아늑하고 조용해서 대화하거나 작업하기에도 딱 좋더라고요. 우드톤 인테리어에 살짝 이국적인 느낌도 나서 분위기가 진짜 포근했어요. 특히 들창 있는 외관 쪽이 완전 포토존! 날씨도 좋아서 바깥 자리에 앉아봤는데, 커피 마시면서 바람 맞으니까 너무 힐링이었어요. 저는 블랙피치 티 아메리카노랑 호두과자를 먹었는데요, 티 아메리카노는 진짜 신기한 맛이에요. 처음엔 익숙한 아메리카노 맛인데 끝맛에 은은하게 블랙피치 티가 퍼지면서 담백하고 깔끔한 느낌! 상큼한 티 향이 중간중간 올라와서 자꾸 생각나더라고요. 커피 좋아하시는 분들도 한 번쯤 꼭 드셔보셨으면 해요. 호두과자도 따끈하고 고소해서 커피랑 찰떡궁합!', 4, 6, 'GOOD', SYSTIMESTAMP);
