INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대에 아늑하고 귀여운 카페에요! 요즘같은 날씨 좋은 날 홍대거리 걷다가 방문하기 좋아요 💙 아이테르의 시그니처의 티아메이카노랑 티얼그레이를 시켰는데요. 티향이나서 깔끔하더라구요. ✨ 달달한 디저트로는 호두과자를 주문했는데요. 하나씩 집어먹기 너무 좋구요. 안에 팥도 너무 맛있어요. 간식거리로 딱이에요!💙💜 조용한 카페라서 한적한 시간 보내기 좋습니다!', 101, 19, 'GOOD', SYSTIMESTAMP);
