INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '티아메리카노 어디서도 맛보지 못한 신선한맛이에요..! 호두과자랑 궁합이 찰떡이라 놀랐어요 호두과자는 직접 만드시는지 기계알림음까지 나와서 깜놀ㅋㅋㅋㅋ 갓 나온 호두과자라 바삭바삭 안은 촉촉하고 시제품얼린거 아니라 진짜 짱 맛있어요~ 날 좋을때는 외부에 앉아서 커피한잔하면 힐링가득일듯해요><', 411, 51, 'GOOD', SYSTIMESTAMP);
