INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '여기 티 아메리카노 진짜 맛있어요 !! 라떼가 너무 마시고 싶어서 들어간 카페인데 티 + 아메리카노 시그니처 메뉴가 너무 궁금해서 시켜버렸습니다 ( ᐙ ) 원체 아메리카노의 쌉싸름함을 좋아하지 않아서 라떼를 먹는거였는데, 커피에 얼그레이 맛이 더해지니까 풍미가 너무 좋더라고요! 저와 같은 취향을 가지신 분들껜 얼그레이 티백 추천드립니다 :)', 108, 19, 'GOOD', SYSTIMESTAMP);
