INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '사장님도 너무 믓지고 친절하신데 커피가 예술이여용~ 구수한  국민간식 호듀과자도 맛있어서 좋네요 확실히 그래서 그런지 단골도 많은곳이라 옹기 종기 모이기 좋은 방앗간같은 곳인것같아요~ 오늘 맛있게 잘 마시고 갑니다~^^', 0, 2, 'GOOD', SYSTIMESTAMP);
