INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '여기서 맛 볼 수 있는 티아메리카노! 얼그레어로 선택해서 마셨는데 특별하고 맛있었어요! 음료도 맛있는데 호두과자 대박이에요! 천안 안 가도 되겠어요!:)', 78, 11, 'GOOD', SYSTIMESTAMP);
