INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '티 아메리카노는 거의 처음 먹어본 것 같은데 아메리카노 맛에 끝에는 얼그레이향으로 마무리되는 것이 식사 후 입가심하기 딱인거 같아요!! 호두과자를 사장님이 직접 구워주시는데 호두알이 실한게 들어있어서 넘나 맛나게 먹었습니다👍👍👍', 26, 10, 'GOOD', SYSTIMESTAMP);
