INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '티아메리카노 처음 먹어봤는데 아메리카노에 향긋함이 느껴져서 엄청 맛있더라구요 ㅎㅎㅎ  호두과자는 즉석에서 만들어주시는데, 바삭바삭하고 달콤해서 넘 맛있었구요! ㅎㅎ  카페 깨끗하고 사장님 친절하셔서 넘 좋았어용!!!', 78, 14, 'GOOD', SYSTIMESTAMP);
