INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '20250208 방문기 동생과 집 근처 카페인 아이테르에 방문했어요 우드톤에 쨍한 색감이 더해진 감각적인 인테리어에 생각보다 자리가 넓어서 여유롭게 커피를 마실 수 있었어요 티아메리카노(블랙피치) 딥바닐라라떼 , 호두과자를 주문했어요 티아메리카노는 먹자마자 오 내가 아는 아메리카노 맛이 아닌데? 라는 생각이 들었어요. 복숭아 아이스티향이 나는 아메리카노여서 이색적이었어요. 딥바닐라 라떼는 적당히 단 맛이 나서 가볍게 마시기 좋았습니다. 마지막으로 호두과자는 가게에 기계가 있어서 사장님이 직접 구워주시는데 바로 먹을 수 있어서 그런지 너무 맛있었고, 호두가 크게 한알 박혀있어서 고소했습니다. 아이테르 평일 주말에 여유롭게 커피 한 잔하고 싶을 때 추천드려요', 10, 6, 'GOOD', SYSTIMESTAMP);
