INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '다른데선 맛볼수없는 티아메리카노 정말 향긋하고 맛있네요!!!! 중독성 있는 맛이에요 바닐라라떼도 일반 시럽쓴맛이 아니라 진한 바닐라맛이라 좋아요 글고 무엇보다 호두과자 꼭드세여!!! 안에 팥 호두 가득차있는데 반죽이 진짜 맛있음 ㅎㅎㅎ', 62, 17, 'GOOD', SYSTIMESTAMP);
