INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '집 근처에 혼자 조용히 작업할 수 있는 분위기 좋은 카페가 있어서 방문했어요! 호두과자 주문하면 바로 만들어주시는데 넘 맛있었어용ㅎㅎ', 3, 0, 'GOOD', SYSTIMESTAMP);
