INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '티 아메리카노는 처음 경험해보는데 페퍼민트향이 너무 산뜻?해요 시원하고!! 그냥 아메리카노는 쓴맛에 잘못먹는데 호두과자도 너무 맛있구.. 티아메랑 조합 굿b 사장님도 친절하셔서 조아용', 27, 7, 'GOOD', SYSTIMESTAMP);
