INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '분위기 예쁜 카페 홍대 혼카페로도 넘 추천해요 🫶🏻 흔하지 않은 메뉴들 많아서 좋았구 캐모마일 사과티, 바닐라 티라떼 등 메뉴에 있어서 신경쓴게 느껴져요 캐모마일 사과티 존맛 .. 추천합니다 💖 호두과자는 수제라는데 그래서인지 평소 알던 호두과자보다 팥이 더 촉촉하고 많고 겉은 바삭해서 또다른 매력이라고 느꼈어요 말렌카 꿀케이크도 강추하시던데 담에 도전해보구 싶어요 또오고싶은 카페 ☺️', 11, 0, 'GOOD', SYSTIMESTAMP);
