INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '번잡한 홍대 인근에서 조용하고 아늑한 카페를 찾는다면 이곳임다... 아메리카노에 티백을 넣은 티아메리카노라는 메뉴를 판매하고 있는데, 처음엔 커피고 끝 맛은 은은한 차향이라 매력적이에요 주문하면 갓 구워주시는 호두과자도 든든하고 맛있었습니다', 22, 1, 'GOOD', SYSTIMESTAMP);
