INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '아늑하고 깔끔한 감각적인 인테리어 속에서 여유롭게 티 아메리카노 한잔과 디저트 호두과자와 함께 편하게 즐기다 갑니다 무엇보다 사장님이 너무 친절하시고 목소리가 너무 멋있으셨다는 :)', 46, 10, 'GOOD', SYSTIMESTAMP);
