INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '호둑과자 보이면 항상 한봉지씩 사먹는터라 바로 후식으로 시켰어욬ㅋㅋㅋ 맨날 고속도로에서 눅눅한 만들어진 호두과자만 먹다가 이렇게 바삭하고 달달한 바로 구워주는 호두과자 존맛탱~~~ 홍대카페로 추천드려요 역이랑도 가깝고! 티메리카노 엄청 끝이 깔끔하고 화한 느낌이라 고기 먹고 계속 생각날 맛이고 딥바닐라라떼 파우더라서 적당히 달달하고 맛있어요 추천이용', 133, 57, 'GOOD', SYSTIMESTAMP);
