INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '편안하면서 안락하고 힙한 느낌의 홍대카페네요. 호두과자 즉석에서 구워주시는데 통호두가 들어가서 진짜고소하면서 따뜻하고 달달해요. 티아메리카노 마셔봤는데 처음 마셨는데!!! 티와 아메리카노가 블렌딩되니 너무 맛나요?! 향이 진짜 좋아요! 홍대입구카페로 정말 좋네요. 특별한 티아메리카노 마시러 자주 오려고요! 내부에화장실도 있어서 편하게 이용하기 좋았어요!', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '티아메리카노 처음 마셔봤는데 페퍼민트 아메리카노 넘 맛있어요!! 호두과자를 파셔서 호두과자도 먹어봤는데 엄청 맛있어요..!!!🥹 호두과자 좋아하시는 분들 꼭 가보세용 주문 들어가자마자 바로 만들어주셔서 따뜻하게 먹을 수 있어요ㅋㅋ 사장님께서 너무 친절하셔서 기분좋게 방문했어요☺️☕️', 47, 4, 'GOOD', SYSTIMESTAMP);
