INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '생각보다 넓은 공간이고 소품하나하나 너무 귀엽고 이쁘게 꾸며져있었습니다! 호두과자도 바로 구워주셔서 따뜻하고 부드럽게 먹을 수 있었어요~😍 시그니처인 티아메리카노는 페퍼민트를 골랐는데 시원하면서 깔끔한 맛이 일품이었습니다👍🏻 이쁜 공간에서 맛있게 잘 먹고가요~!', 16, 3, 'GOOD', SYSTIMESTAMP);
