INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '사장님이 추천해주신 아이테르 시그니처 특별메뉴 티아메리카노 중 페퍼민트맛으로 마셨는데 진짜 맛있어요! 페퍼민트에 민트향과 아이스아메리카노 원두맛 조합이 좋아요! 그리고 직접 주문즉시 구워주신 호두과자도 따끈따끈한 빵 속에 가득한 팥앙금과 큰 호두가 맛있어요!👍 #홍대카페 #아이테르 추천해요☕️', 75, 15, 'GOOD', SYSTIMESTAMP);
