INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '연남 카페 아이테르에서 겨울 간식으로 제격인 호두과자로 힐링했네욥😋👍 아늑한 분위기에 조용하게 대화나누기에도 좋고, 시그니처로 티아메리카노는 처음 마셔봤는데 이색적이면서 맛있어요 재방문 의사 있습니당🤩👌', 65, 13, 'GOOD', SYSTIMESTAMP);
