INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '조용하고 아늑한 카페입니다! 사장님 너무 친절하시고 주문하자마자 바로 구워주시는 호두과자가 진짜 꿀맛👍 따끈따끈한 호두과자와 고소한 향의 커피를 같이 마시니 조합이 진짜 좋네요😆❤️', 76, 12, 'GOOD', SYSTIMESTAMP);
