INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '이곳만의 특별한 점은 아메리카 + 티의 조합 ! 저는 아메를 입에 대지 않는 사람인데 티 향과 맛이 쎄서 부담없이 가볍게 먹을 수 있었어요 ◡̎ 겨울의 묘미 호두과자 진짜 부드럽고 즉석으로 구워져서 짱짱맨 또 먹고파요. 꿀케이크도 진짜 맛도리에요 🎀💓 첫 방문인데 아늑하고 인테리어가 저를 사로잡았어요 ꗯ ⋆˳ ˚ ⋆  가을에는 외부에서 앉아서 차 즐기기 딱이에요 ㅎㅎㅎㅎ 집중도 잘 되어서 일 하기도, 데이트 하기도 좋은 곳인 듯 .. .•♥', 24, 8, 'GOOD', SYSTIMESTAMP);
