INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '인테리어도 감각적이고, 티 아메리카노 여기서만 맛볼수있어서 또 방문할거갓같요! 얼그레이향이 은은하게 나는 아메리카노 진짜 맛있어요 ㅠㅠ 말렌카케이크도 꾸덕하니 계속 땡겨서 순삭했답니다 추천드려요💕', 34, 2, 'GOOD', SYSTIMESTAMP);
