INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '갓 구운 호두과자..바삭바삭하고 맛있어요 너무 안달고ㅎㅎ 근데  뜨겁습니다 잘 불어드세요! 티아메리카노는 블랙피치로 시켰는데 쌉싸름한 커피랑 잘어울렸어요', 26, 1, 'GOOD', SYSTIMESTAMP);
