INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '집근처에 생겨서 분위기 좋아보여 갔다가 깜짝놀랐어요. 음료랑 디저트 존맛집 찾았습니다… 특히 페퍼민트 아아 미쳤어요. 이렇게 맛있는 조합인줄 몰랐습니다… 케이크도 맛있구 카라멜마끼야또도 정말 맛있어요. 조용하게 대화하러 가기에도 딱 좋은분위기에요 강추합니다', 26, 10, 'GOOD', SYSTIMESTAMP);
