INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '홍대 데이트나왔다가 들렸어요 커피가 땡겨서 들어왔는데 커피가 맛있어서 만족합니다 인테리어도 너무 예뻐요 감성사진 찍기 좋아요!', 85, 18, 'GOOD', SYSTIMESTAMP);
