INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대입구역 근처 카페 아이테르 방문했어요! 호주 스타일의 이국적인 인테리어가 너무 맘에 들어요❤️ 외관쪽 야외 자리가 있어 가을 날씨를 맘껏 즐겼답니다! 티아메리카노 얼그레이 / 블랙피치 / 페퍼민트 중 페퍼민트선택해서 마셔봤는데 시그니처답게 향긋하고 커피의 고소한 맛까지 색다르게 맛볼수 있었어요! 다른 곳에는 맛볼 수 없는 맛이라 정말 너무  맛있게 먹었습니당😃 딸기주스도 달콤하고 음료 맛집이었어요! 특히 수박주스가 유명해서 여름에 강추드려요! 🍉 💛말렌카 꿀 케이크💛코코아 맛 먹었는데 시원하게 먹는 케이크라고 설명해 주시더라고요! 시원할 때 먹으니  달달하고 꾸덕함이 더 느껴졌어요!! 최근 먹어본 디저트중 제일 맛있었어요💕', 20, 5, 'GOOD', SYSTIMESTAMP);
