INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '티아메리카노 처음 먹어봤는데, 오..! 신박하게 묘하고 맛있었어요🫶 먼가 쓰면 어쩌지했는데, 입안이 개운해지는 맛이랄까요? 함께 시킨 말렌카도 옴총 쫀독해서 계속 먹었음.ㅋ 🫣🫣👍👍🎀🫶', 14, 5, 'GOOD', SYSTIMESTAMP);
