INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '호두과자 맛집 팥러버는 행복합니다! 그리고 캐모마일 애플티! 감기에 짱 좋아요😆 감기걸려서 따뜻한 음료를 마셨는데 달달하고 따뜻하고 산뜻한 허브티에요!', 35, 0, 'GOOD', SYSTIMESTAMP);
