INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '티아메리카노 라는 특별한 커피메뉴가 있는 아이테르☕️ 매장도 쾌적하고 야외 테라스도 있어서 선선해지는 요즘 딱인 카페에요✨ 티아메리카노는 페퍼민트/얼그레이/블랙피치 3가지 티백 중 선택 가능한데 얼그레이로 시켜봤어요! 특이하고 너무 맛있어서 다음엔 민트맛도 먹어보고싶어요 꿀케이크도 달달하고 커피랑 너무 잘 어울리니 꼭 드셔보세요😋', 23, 7, 'GOOD', SYSTIMESTAMP);
