INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '분위기 좋은 홍대카페에서 특별한 티 아메리카노 마시니 오랜만에 힐링하는 기분이 들어 행복했어요~ 티 아메리카노는 3종류 선택할 수 있는데 저는 얼그레이로 마셨어요. 완전 맛있음!!! 말렌카 꿀 케이크는 처음 먹어봤는데 커피랑 완전 잘 어울려요. 티 아메리카노랑 케이크 조합 강력 추천!! 창문이 완전 개방되어서 바람도 시원하고 짱 좋아요.', 26, 4, 'GOOD', SYSTIMESTAMP);
