INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '대화하기 좋고 작업하기 좋은 아늑하고 포근한 카페에요👍 여기 티도 맛있고 커피도 맛있어서, 티아메리카노로 결정😘 꾸덕한 말렌카 케이크랑 같이 먹으면 궁합이 최상이에요! 적극 추천☆☆☆ 고요함이 넘넘 좋아서 자주 데이트하러 올게용💛', 75, 17, 'GOOD', SYSTIMESTAMP);
