INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '알렌커 꿀 케이크 호두 맛과 코코아 식감도 쫀득하면서 너무 맛있었고 수박 주스도 얼리지 않은 씨없는 생수박을 바로 갈아서 주시는데 너무 달고 맛있었습니다. 페퍼민트 아메리카노도 원두의 풍미와 산미와 페퍼민트가 잘 어울려서 밸런스가 좋았습니다. 카페 분위기도 잔잔한 음악과 창문이 열려서 너무 좋고 사장님도 친절하셔서 기분 좋게 시간 보내다가 갑니다. 홍대 연남동 근처 카페 재방문 의사 100프로입니다~!', 50, 10, 'GOOD', SYSTIMESTAMP);
