INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대 분좋카 찾아다니는 사람 꼭! 방문해보기 ✨✨ 녹색으로 포인트를 준 호주스타일의 인테리어로 편안하고 여유로운 감성이라 여자친구 데려가면 100프로 만족할거에요 🤗🤗 추천 메뉴는 아이테르 베스트 메뉴 티아메리카노와 꿀케이크 🤤', 11, 1, 'GOOD', SYSTIMESTAMP);
