INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '연남동 메인 골목은 복잡한데, 여긴 한가롭게 시간을 보낼 수 있어서 좋았어요❤️ 시그니처 티아메리카노랑 말렌카 꿀케이크그도 꿀맛! 여유롭게 시간보낼 연남동 카페 찾는 분들께 강추👍', 40, 10, 'GOOD', SYSTIMESTAMP);
