INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '티아메리카노 특이한대 넘 제취향이에요ㅜㅠ 아메리카노인데 살짝 티향이 나요! 산미 있는 건 아니고 진짜 과일 티향! 마누카케이크도 달달하고 호두 때문에 고소해서 넘 맛있었습니다◡̈', 109, 23, 'GOOD', SYSTIMESTAMP);
