INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '저렴한 가격에 맛있는커피를 파는곳을 찾았네요 조용하고 아늑한분위기에 자리도 넓직해서 좋고 티라떼도  특색있고 맛있었습니다 그리고 다른데서는  먹기힘든 말렌카 케이크까지맛있게 먹었습니다.', 21, 0, 'GOOD', SYSTIMESTAMP);
