INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '디저트 호두과자랑 꿀케이크 둘다 너무 맛있습니다👍👍 커피도 티아메리카노 블랙피치향이 좋아요ㅎㅎ 카페 분위기랑 노래선곡도 다 완벽해요😃', 31, 7, 'GOOD', SYSTIMESTAMP);
