INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대에서 친구기다리면서 조용히 책 읽을 편한 카페 찾아 왔어용🧡 아이테르 말렌카 꿀 케이크 진짜 맛있으니 다들 꼭 드셔보시는거 추천해요 !! (저는 호두 맛 먹었는데👍🏻👍🏻 담에는 다른 맛 먹어보려구여!! 티아메리카노도 마실때마다 입안이 상쾌해 지는 느낌이라 진짜 괜츈더라구요 다음에는 재택근무할때 찾아 오도록 하겠습니다 하핳✔️👍🏻', 5, 6, 'GOOD', SYSTIMESTAMP);
