INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대에 친구랑 놀다가 우연히 발견한 카페인데요, 다크우드에 녹색이 뽀인트인 인테리어가 예뻐요🥺🤍 케이크도 맛있고 커피도 꿀맛이네요(특히 라떼)✨ 창문도 독특해서 특히 밤에 테라스에서 먹으면 마치 유럽에 온듯한 느낌입니당👍 다들 휘황찬란한 홍대에서 휴식을 찾고싶다면 아이테르 카페 추천합니다🍀🍀 사장님도 알바생분도 선남선녀라 눈호강중,,😆✨ 번창하세요🤍', 12, 9, 'GOOD', SYSTIMESTAMP);
