INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대 근처에 이렇게 좋은 카페가 있는지 몰랐어요 ☺️ 정신없는 프렌차이즈 말구 이곳으로 오세용~~ 평소에 조용한 곳을 좋아해서 차분한 분위기에 조용하게 집중할 수 있는 곳을 찾아다니는데 내부도 깔끔하고 예쁘고, 조용해서 혼자 와서 할 일 하기 좋아요 ㅎㅎ 좌석마다 콘센트도 있어서 쉬는 날 혼자 쉬고 싶거나 노트북으로 할 일 있을 때 오면 정말 좋을 것 같아요!!  티 블랜딩해서 마시는 것을 좋아하는데 페퍼민트랑 블랜딩한 커피 마실 수 있어서 더 좋았습니당 ㅋㅋㅋ 케이크도 완전 맛있어여~~ 저처럼 티 베이스 아메리카노 좋아하시면 진짜 강추 !! 페퍼민트향과 커피향 같이 느끼니 행복해지네요 방문 추천드려용 😝', 48, 8, 'GOOD', SYSTIMESTAMP);
