INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '티아메리카노라는 시그니쳐 커피가 있았어용! 처음 도전해보는거라 기대가 아주 가득가득했는데 티랑 아메리카노랑 만나서 더 상큼한 느낌의 커피를 마실수 있었음!!!! 그냥 커피 써서 못 드시는 분들도 즐길수 있던거 같아서 좋은거 같아용 ㅎㅅㅎ 매장에 초록색 테이블이 넘 예뻤어요 •• 아이랍 그린맨 🌿 잘먹고 갑니다 총총 아 디저트도 마싯음요!!', 55, 17, 'GOOD', SYSTIMESTAMP);
