INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대에 데이트 하러 왔다가 발견한 곳입니다. 저는 콜드브루 라떼를 시켰는데 깔끔하고 시원한 맛입니다! 케이크도 너무 맛있고 여자친구가 먹었던 시그니처 티 아메리카노도 너무 맛있다그러네요! 데이트로 추천합니다', 15, 4, 'GOOD', SYSTIMESTAMP);
