INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '요즘처럼 데이트하기 좋은 날씨에 들리기 좋은 곳이네요~ 차도 맛있고 디저트도 맛있어요~!ㅎㅎ 동네가 너무 시끄럽지 않은 곳이라 혼자오기도 좋고 조용해서 데이트하기에도 좋아요', 2, 0, 'GOOD', SYSTIMESTAMP);
