INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '시그니쳐메뉴인 허니바닐라라떼 티아메리카노 초코말렌카까지 주문해봤어요! 너무너무 맛있게 먹었어요!! 티 아메리카노 페퍼민트로 시켰는데 시원하고 고소한맛으로 입이 너무 개운했어요 바닐라라떼도 너무 달달하고 부드러워서 좋았습니다 말렌카 코코아맛으로 정말 달콤하니 디저트로 좋더라구요👍', 10, 5, 'GOOD', SYSTIMESTAMP);
