INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '티 아메리카노가 시그니쳐라고 하셔서 먹어봤는데 굉장히 맛있었어요🫢 아메리카노에서 티 향도 느낄 수 있고 좋았습니당♡ 매장도 깔끔하고 넓고, 같이 온 사람과 이야기하기 좋은 곳이었어요! 다음에 또 오겠습니다~ 감사합니다~~', 46, 8, 'GOOD', SYSTIMESTAMP);
