INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '오랜만에 홍대 나들이 갔다가 방문한 곳인데 커피와 디저트가 진짜 맛있었어요🥰 티아메리카노가 신선하고 중독적인 맛!!! 개인적으로는 바닐라 블랙피치티가 아주 맛있었음ㅠ 꼭 드셔보시길..!! 너무 맛있어서 당황스러움;', 42, 2, 'GOOD', SYSTIMESTAMP);
