INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '페퍼민트티 아메리카노& 수박주스& 코코아 말렌카 꿀 케이크 먹었습니다!! 티 아메리카노는 아메리카노의 쓴맛 대신 페퍼민트의 깔끔한 맛이 확 느껴졌습니다. 티와 아메리카노를 섞어마신다는 것에 의문을 가졌었는데 너무 무안해질 만큼 맛있어서 아메리카노를 꺼려하시는 분들도 부담없이 시도해보셔도 좋을 것 같습니다 :) 수박주스는 직접 손질해서 보관하신 수박을 바로 갈아주시는데 다른 곳보다 훨씬 달달하고 수박의 신선함과 시원함을 동시에 느낄 수 있답니다 말렌카 꿀 케이크는 코코아 맛으로 골라봤습니다.  평소엔 코코아는 너무 달고 텁텁한게 싫어서 잘 먹지 않지만 한번 도전해보고 싶어서 선택했는데, 꿀이 들어갔음에도 지나치게 달지도 않고 끝맛도 깔끔해서 전혀 텁텁하지 않아 음료와 궁합이 완전 잘 맞습니다 !!!', 26, 5, 'GOOD', SYSTIMESTAMP);
