INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '디저트가 정말 맛있어요. 말렌카 꿀케이크는 처음 먹어봤는데 너무 제 스타일이에요. 꾸덕한 식감인데 과하지 않게 달달해서 맛있게 먹었습니다. 티 아메리카노도 색다른 느낌이라 맛있었어요.', 3, 1, 'GOOD', SYSTIMESTAMP);
