INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '시그니처음료인 수박주스와 티아메리카노 페퍼민트로 주문했어요! 아메리카노맛이 나면서 마지막엔 페퍼민트향이 확 오는데 너무 특이하면서 특별한 맛 ,, 💞🙂 그리고 말렌카 꿀 케이크가 진짜 미쳤어요!! 폭신폭신 식감에 차갑게 먹는게 더 맛있다는 사장님 말씀에 조금 기다렸다가 먹었는데 존맛 !!!!! 호두 안좋아하는 저도 남기지않고 다 먹었답니다 ㅎㅎㅎ 무엇보다 사장님이 너무 친절하시고 잘생기셨어요!!!!!!!!!!!! 카페 연지 얼마 안됐다고 하셨는데 꼭 대박나셨으면 좋겠어여!!!!!!!!!! 잘생긴 사장님 뵈러 또 갈게용 🙏🏻🙂', 66, 12, 'GOOD', SYSTIMESTAMP);
