INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '점심 먹고 지나가다 들어가봤어요. 원래 아이스아메리카노만 마시는데 사장님께서 시그니처라고 하셔서 페퍼민트 아메리카노 마셔봤어요!! 와 신세계네요~~점심 먹고 회사 들어가기 전 마시기에 딱이에요! 아메리카노 베이스 자체가 산미 없고 고소한데 거기에 페퍼민트가 들어가니 퀄리티가 확 올라가요! 추천 감사해요 사장님! 또 방문할게요', 83, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대 올 때마다 꼭 들러요 왜냐하면 1. 여기서 판매하는 티 아메리카노가 정말 맛있거든요 커피를 싫어하는데 여기는 커피와 티가 알맞게 배합이 되어서 향긋하면서도 되게 오묘한 중독성 있는 맛이에요 그래서 그냥 쓰고 탄 맛이 아닌 이 집만의 시그니처 메뉴라고 할 수 있는 정말 맛있고 향긋한 커피예요! 2. 사장님이 잘 생겼어요😍 무슨 같은 남자가 봐도 와 잘생겼다... 이 말밖에 안 나와요 사실 사장님 보러 여기 오는 것도 있어요ㅎㅎ (여자 좋아합니다ㅋ) 너무 맛있어서 허겁지겁 먹다가 다 처리하고 이제 찍네요ㅋㅋㅋ 같이 판매하는 말렌카 시나몬 케이크도 너무 잘 어울리니 꼭 같이 드셔보세요! 다른 분들도 꼭 여기 방문하셔서 드셔보시길 추천드려요🔥🔥', 34, 4, 'GOOD', SYSTIMESTAMP);
