INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '코지하면서 감각적인 카페예요 꿀케이크 좋아하는데 다른 곳보다 여기가 정말 맛있네요 오늘은 꿀케이크 먹느라 음료는 커피로 주문했지만 다음엔  수박주스를 먹어봐야겠어요 여긴 수박주스 맛집으로 유명한 곳이더라고요 맛있게 먹고 갑니다 또 올게요!', 53, 16, 'GOOD', SYSTIMESTAMP);
