INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '분위기가 너무 깔끔하고 예쁜 카페예요!!! 차분해서 이야기 나누기 좋은 공간이고 특히 티 아메리카노가 향긋하고 독특해서 추천합니당!!!💕', 1, 6, 'GOOD', SYSTIMESTAMP);
