INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '친구들 여럿이 오기 좋다 1-2층이라서 넉넉함 음료도 맛있음 제일 베스트 : 테이크아웃컵에다 줌 늦은 저녁시간에 가서 그런건지 원래 그런건지 모르겠지만 맨날 마시다 테이크아웃하는 사람으로서 정말 좋았습니당', 36, 0, NULL, SYSTIMESTAMP);
