INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '역시 첫방문 가격만큼의 만족감을 느낄수없었어요. 커피는 맛이... 2개 시킨 케익도 쏘쏘 그중에 얼그레이케익은 그래도 나쁘진않았지만...  그리고 매장에서도 1회용컵(종이컵)을 주시기에 좀 당황...', 36, 0, 'BAD', SYSTIMESTAMP);
