INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '그날 , 그 시간 , 홍대 ,,, 차 한잔을 들어가서 마시기에 우리는 인원수가 너~~~~무 많았습니다 ㅋ 그래도 운 좋게 카페를 찾았고. 이층에 우리들의 자리가 떡!!!!!하니 있었답니다. 그런데다 왠걸 커피 맛도 좋고 시킨 음료들도 다 만족스런 맛이라 행복했습니다.', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '아인슈페너 맛집이에요. 얼그레이케이크, 프레즐도 탁월한 선택이었어요. 매장에서 마시면 1000원 추가시 아메리카노로 리필돼서 리필도 했어요. 넓고 쾌적하고 창밖에 식물 가득이라 산뜻한 분위기에요. 오후되니 직원이 창문도 닫아주고 관리도 잘 되는 곳이에요.', 5, 2, 'GOOD', SYSTIMESTAMP);
