INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '커피가 정말 맛있고 직원분들도 다 친절합니다 콘센트 쓸 수 있는 자리가 많아서 노트북 사용하기 최고의 장소! 심지어 천원 내면 리필도 해줘요🥹 홍대에서 제일 좋아하는 곳이에요', 4, 8, 'GOOD', SYSTIMESTAMP);
