INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '이 카페는 넓은 테라스로 저의 마음을 사로잡은 곳이에요💘 이전에 가을쯤 친구와 왔을 때 좋았던 기억이 있어서 방문했어요:) 아쉽게도 추운 날씨 때문인지 테라스는 이용할 수 없는 거 같았고, 2층도 대관으로 이용불가했어요😭 음료와 시킨 디저트는 so so ~ ✔️Order menu is 아메리카노, 바닐라라떼, 카라멜라떼, 오리지널 프렌치 토스트를 주문했어요.', 35, 7, NULL, SYSTIMESTAMP);
