INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '합정 어반플랜트 식물로 건물전체가 둘러싸여진 게 너무 이뻐서 들어왔는데 문 들어서자마자 좋은 향기가 가득 퍼지고 진짜 직원분들이 이렇게 친절하고 환대해주시는 곳은 너무 오랜만이라 참 기분이 좋았습니다… ㅠㅠ 공간 둘러보는데 손이 안간곳이 없어보여요 다음엔 낮에 방문하고 싶네요 ! 커피도 너무 맛있네요 합정맛집 추천 ~ 🤗🪽', 70, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '너무 이쁩니다.... 오자마자 분위기 있고 ..그냥 대박 추천입니다💗 이렇게 분위기 좋은 데 있으면 맨날 갈 거 같아요 이정도 퀄리티에 가격까지 완벽한.. 무조건 재방문 할 거 같습니다🥹🥹 친구들이랑 또 오려구요... 합정맛집 !!', 88, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '커피 맛있구 음식도 괜찮습니다. 크림파스타 느끼해서 안 좋아하는데 이건 싹싹 긁어먹었어요. 샐러드랑 샌드위치도 양 많고 맛있습니다. 다만 좌석이 편한 편은 아니라 오래는 못 있을 것 같아요! 식물 좋아하는 분들이 가기 좋은 곳입니다. 합정 맛집이에요!', 55, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '식물카페를 좋아해서 한 번 와봤는데 입구부터 감동받아서 홀린 듯이 들어왔어요..🥺 실내 인테리어도 멋지고 식물이 많아서 정신도 맑아지는 기분이에요 ㅋㅋㅋ ˃̵͈̑ᴗ˂̵͈̑ ♥ 다음에 또 재방문 할게요!!', 50, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '#합정맛집 자연이 느껴지는 공간 인테리어가 브런치랑 너무 잘어울려요 😭 샌드위치도 너무 맛있고, 시그니쳐 음료도 너무 이색적이라 매력적인 곳입니다! 합정오실때, 분위기 있는 데이트 하기도 좋은 공간이예요:) 리뷰이벤트는 한테이블당 하나입니다! 사전에 공지하지 않으시니까 혹시나 참고하세요~! 그리고 리뷰한걸 보여주시면 그때 음료를 서비스로 주시니까 미리 시키시면 주문한 움료를 취소해주는 방식이 아닌 새로 음료를 하나더 서비스로 주시는 형태이니~~ 음식이랑 같이 드실분은 리뷰이벤트 후에 음료 사비스 받으세요~~!', 45, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '로제파스타는 미트소스 느낌이 나면서 맛있고, 깻잎파스타는 살짝 느끼하지만 향이 좋고 건강한 맛이라 싹싹 먹었어요. 깻잎파스타 바닥에 있는 오일에 빵 찍어먹으니까 맛있어요. 디카페인 아아는 메뉴에 없는데 주문이 돼서 다행이에요. 합정맛집!', 39, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '어반플랜트 합정에 오면 그린플로우를 추천드립니다 일단 플랜테리어로 가득한 곳에서 진한 말차향으로 입안가득 푸릇함을 채워보시면 이게 힐링아닐까요? 샌드위치까지 함께 브런치 타임 너무 좋았습니다 미팅이 있어서 왔다가 감성폭발했습니다 #합정맛집', 58, 13, 'GOOD', SYSTIMESTAMP);
