INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '분위기 좋고 음악도 어울리게 잘 트시네요. 분위기 갑 합정맛집 인정입니다. 부담스럽지 않은 가격으로 익숙한 브런치 메뉴를 즐기면서 햇볕을 쬐니 휴양지에 온 것 같이 여유있고 낭만적인 오전 시간을 보낸 것 같아요. #합정맛집', 45, 6, 'GOOD', SYSTIMESTAMP);
