INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '도심속에 식물원 같은 느낌. 밥먹고 우연히 들렸는데 커피도 맛있고 분위기가 너무 좋았어요. 책읽거나 작업하기에도 조용하고 편할 거 같아요. 루프탑 카페만큼 찾아갈 만한 카페 👍 #합정 맛집 #합정 카페', 113, 21, 'GOOD', SYSTIMESTAMP);
