INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '합정맛집 카페 어반플랜트  !! 원래도 자주오고 혼자도 오고 하는데 파스타도 맛있고 분위기도 너무 좋아요❤️  직원분들이 일단 너무 친절하시고 리뷰이벤트도 조금씩 다른데 좋은 이벤트도 많이하고 매장도 넓고 쾌적해요 ! 커피도 맛있습니다 🥰', 86, 16, 'GOOD', SYSTIMESTAMP);
