INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '합정역에 있는 곳인데 맛집이예요!! 세번째 방문인데, 오늘은 카페용으로 방문했습니다 ㅎㅎ 말차 티라미슈 맛있구 커피도 맛있네요. 식물이 정말 많고 엄마가 좋아해요 ㅎㅎ 라떼아트도 정말 이쁩니다 !! 자리도 넓고 분위기도 좋고 추천해요!', 72, 13, 'GOOD', SYSTIMESTAMP);
