INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '남편이랑 아기 낳기전에 마지막 데이트겸 들렸는데 분위기도 좋고 맛도 좋았어요!! 특히 남편이 깻잎 파스타 너무 맛있다면서 폭풍 흡입했네요 ㅎㅎ 식물이 많아서 공기정화 되는느낌이고 숨쉬기가 편안했어요 덕분에 잘 힐링하다갑니다🌿 합정맛집입니다 꼭 들려보세요!!', 47, 3, 'GOOD', SYSTIMESTAMP);
