INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '브런치 먹고싶어서 찾다가 왔는데 너무 맛있어요~ 들어오자마자 풀냄새가 나는데 너무 좋아요 숲속에 온 느낌이예요 분위기도 좋고 음식도 맛있고 합정에서 제일 분위기 좋은카페 같아요 완전 합정맛집입니다!! 여름에 오면 너무 좋은 공간 같아요! #합정맛집', 69, 18, 'GOOD', SYSTIMESTAMP);
