INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '카페 겸 메인이 브런치 집인 것같은데 저희는 식사후 방문한터라 커피에 디저트로 말차 티라미수만 먹었어요. 직원분들 매우 친절하시고(인사성이 특히 밝음ㅋㅋ) 카페 내부가 초록초록해서 정말 좋았어요. 아늑해요. 2층이나 1층 테라스쪽도 온실처럼 되어있어서 예쁜 좌석도 많은 것 같아요. 소개팅 장소 등으로 괜찮은 듯 보이는ㅋㅋㅋ 합정맛집으로 유명한거 같은데, 담엔 브런치 먹으러 와보려구요.', 5, 1, 'GOOD', SYSTIMESTAMP);
