INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '여기 분위기부터 음식까지 너무 만족스러웠어요. 🌿 초록 식물들이 둘러싸여 있어서 마치 온실 속에서 식사하는 느낌이었고, 파스타는 비주얼부터 식욕을 자극해요.합정 맛집이에요 ! 🦐 새우 바질크림 파스타는 바질 향이 진하고 부드러운 크림 소스가 면에 잘 배어 있었고, 탱글한 새우가 정말 신선했어요. 🍅 토마토 미트소스 파스타는 소스가 진하고 풍미가 깊어서 한 입 먹을 때마다 감탄하게 됩니다. 같이 나온 갈릭브레드도 바삭하고 버터향이 풍부해서 파스타와 찰떡궁합이었어요. 분위기 좋고 음식 맛까지 완벽해서 데이트나 모임 장소로 강력 추천합니다! 💚', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '합정맛집!!인증! 남친이 데이트 하고싶다고 해서 서치해서 데려와준 곳인데, 플랜트가 진짜 많아서 뭔가 되게 싱그러워요!보통 풀 많은 카페 가면 물냄새? 같은것도 나던데 여기는 그런냄새도 안나고 쾌적하니 좋아요! 커피도 맛있고 샌드위치 시켜먹었는데 맛있게 잘먹었어여', 80, 11, 'GOOD', SYSTIMESTAMP);
