INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '인테리어가 너무 예뻐서 구경하는 재미가 있어요! 합정 맛집이라고 해서 왔는데 음료도 주스 종류가 많아서 커피 못먹는 사람도 오기 좋은 거 같아요~ 식물이 많아서 구경하는 재미도 있고 인테리어도 너무 예뻐요~', 47, 5, 'GOOD', SYSTIMESTAMP);
