INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '임장하자마자 갖가지 식물들이 반겨줌과 동시에 합정동에서 경험하기 힘든 자연의향이 코끝을 간지럽힙니다. 음식 본연 자연의맛을 느끼며 매장에서 친절함, 쾌적함, 푸릇푸릇 인테리어까지 모두 느낄수 있습니다 회사동료,친구,연인,가족들과 방문하셔서 합정동에서남아프리카 케이프타운의 한 카페에 와 있는듯한 느낌을 느껴보시기 바랍니다 #합정맛집', 9, 10, 'GOOD', SYSTIMESTAMP);
