INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '안에 좌석도 많고 식물에 둘러쌓여 있어서 너무 분위기도 산뜻하고 또 오고 싶네요. 역시 합정맛집! 커피도 맛있고 샌드위치도 맛있어요👏🏻🌱🍀🌿🪴 #합정맛집 #합정카페 #합정어반플랜트 #합정식물카페 #합정브런치맛집', 8, 0, 'GOOD', SYSTIMESTAMP);
