INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '어반플랜트 합정역 맛집 검색해서 왔는데 생각보다 더 예쁘고 분위기도 좋아서 완전 만족했어요!! 많은 식물들이 있어서 대채롭고 색다른 곳같아요^^ 비왔는데 빗소리 은은하게 들리면서 친구랑 대화하기 넘 좋더라고요~~ 적극추천합니다~^^♡', 13, 9, 'GOOD', SYSTIMESTAMP);
