INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '길가다 우연히 발견했는데 초록초록 너무 예뻐요!! 매장도 넓고 도심 속 식물원안에 들어와있는 것 같아요 :) 앞으로 합정오면 카페는 여기만 올거같아요😆 직원분들도 친절하시고 커피도 맛도리에용👍 #합정맛집', 3, 9, 'GOOD', SYSTIMESTAMP);
