INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '꼭 한번 방문하고 싶었던 합정 맛집 어반플랜트 합정! 플랜테리어로 깔끔한 디사인에 맛있는 음식과 음료까지 모두 만족스러웠습니다! #합정맛집 #어반플랜트합정', 21, 10, 'GOOD', SYSTIMESTAMP);
