INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아인슈페너 생크림이 아주 맛있어요. 😃 조용하게 대화 나누기 좋은 장소 입니다. 식물의 향이 괜찮아요. 예전부터 들어와 보고 싶었는데, 직원들도 친철하고 좋습니다. #합정맛집 #합정카페', 75, 17, 'GOOD', SYSTIMESTAMP);
