INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '합정 어반플랜트에서 부라타 프로슈토 샌드위치랑 깻잎 새우 파스타를 먹었습니다~ 샌드위치는 부라타 치즈가 정말 부드럽고, 프로슈토의 짭조름한 맛과 잘 어울렸어요~그리고 빵이 쫄깃해요^^ 파스타는 크리미한 소스에 깻잎 향이 은은하게 퍼져서 느끼하지 않고 깔끔한 맛이었고, 새우가 탱글탱글해요. 음식뿐 아니라 식당 인테리어가 굉장히 세련되고 멋져서 분위기까지 만족스러웠습니다. 자연광이 잘 들어오는 공간에 식물들이 곳곳에 놓여 있어 힐링되는 느낌이었어요. 건강한 맛을 좋아하는 분들이라면 추천할 만한 곳이에요. 합정맛집이고 재방문의사 있어요~~', 7, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '서울을 벗어난 분위기로 친구와 만날 수 있어서 좋았습니다. 음식도 맛있고, 특히 직원들이 너무 친절해서 장소 선택을 잘 한것 같습니다. 다음에도 합정동에 오면 다시 이용해야 겠습니다. 합정맛집', 33, 5, 'GOOD', SYSTIMESTAMP);
