INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '제일 먼저 떠오르는 건 커피맛이 정말 맛있다. (신맛X. 쓰지 않고 고소하게 맛있다) 그리고 분위기 있게 세팅해주시고 얘기나누기 너무 좋다. 다음에 또 다른 친구들과 오고싶은곳', 0, 10, 'GOOD', SYSTIMESTAMP);
