INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '합정에 숲에 있는 듯한 느낌을 주는 카페 입니다~ 트라미슈가 맛 있고 아메리카노도 맛 있어요👍👍 도시 속에서 자연느낌의 카페를 찾는 다면 추천 드립니다~합정맛집으로 추천드려요!', 26, 6, 'GOOD', SYSTIMESTAMP);
