INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '선결제 후 자리로 가져다주심 베이컨크림파스타+치킨샌드위치 리뷰이벤트로 음료를 한 잔 주신대요 전 오렌지주스 고름 콜드프레스드라 펄프 많고 맛있어영 선결제 후 번호판 챙겨가면 자리로 가져다 주신대요 진동벨 주는 경우도 있더라구요 바쁘거나 하면 진동벨 픽업 쓰는듯? 매장 분위기가 좋네요 차분하고 옆테이블과 거리가 조금 좁아서 사람이 많으면 옆자리 대화에 참여하게 될 것 같지만 월요일 20시쯤 왔는데 사람 그닥 없고 좋았어요 카페 브런치메뉴도 많아서 카공하는 분들도 몇 분 보임. 다만 카공하기에는 어두워서 눈나빠질것같구요 ㅋㅋㅋ 데이트로 와서 조곤조곤 얘기하기 좋은 것 같아요 음악도 잔잔하고 이곳을 왜 몰랐지~ +)파스타도 괜찮은데 치킨샌드위치가진짜미핀놈이에여!!!!! 소스가대박 #합정맛집', 36, 0, 'GOOD', SYSTIMESTAMP);
