INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '아이와 함께오기 좋은 그리너리한 카페에요♡ 몇년전 친구와 왔던기억에 다시들렀는데 피톤치드(?)향과 청량한 시원함이 느껴지는 기분좋은곳입니다.커피도 맛나용', 73, 15, 'GOOD', SYSTIMESTAMP);
