INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '샌드위치와 커피 마셨는데 너무 맛있어요. 카페도 예쁘고 자리도 충분하고 좋습니다. 직원분들도 친절하세요. 음료는 직접 픽업이고, 음식은 자리로 가져다 주십니다. 그릇은 자리에 두고 일어나면 직원분들이 치워주셔서 편하고 좋습니다. 합정 맛집으로 추천합니다!', 14, 2, 'GOOD', SYSTIMESTAMP);
