INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '입구부터 내부까지 식물이 진짜 많아서 식물원 안에 있는 느낌.  풀냄새 나는 게 기분 좋고 냉방도 잘 되어있어요. 그리고 진짜인지 녹음인지 모르겠는데 매미소리까지 엄청 잘 들려요ㅋㅋㅋ 음식도 맛있고 자리도 넓어서 합정 들르면 다시 방문할 것 같네요. 합정 맛집 인정', 59, 16, 'GOOD', SYSTIMESTAMP);
