INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '친구들이랑 오랜만에 만나려고 왔는데 분위기도 너무 좋고 햇볕도 잘들어 이야기하기 너무 좋아요 ㅎㅎ 직원분들도 엄청 친절하고 인사도 함께 해주셔서 다음에 다시 올 것 같아요! #합정맛집 #어반플랜트', 3, 8, 'GOOD', SYSTIMESTAMP);
