INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '평일 저녁 7시 쯤에 왔는데 사람도 많이 없고 분위기도 더 좋았어요. 가게 전체가 식물로 되어있어서 식물 좋아하는 분들에게 매우 추천합니다. 음료도 맛있었고, 딸기라떼를 시켰는데 우유 또는 청을 기호에 맞게 더주신다고 해서 충격을 받았어요. 그린플로우 카피도 크림과 커피가 다 맛있다고 합니다. 너무 친절하시고 기분이 좋아져요. 합정 맛집이라 다른 사람들도 데리고 또 올래요!', 44, 6, 'GOOD', SYSTIMESTAMP);
