INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '평일 낮에 방문하니 웨이팅 없이 입장할 수 있어 좋았어요 ㅎㅎ 건강한 맛집 느낌+숲뷰 느낌이라 누구와 함께해도 편안하고 좋은 느낌! 맛있게 먹고 갑니다 😋', 43, 3, 'GOOD', SYSTIMESTAMP);
