INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '부모님이 분위기 좋은 카페를 좋아하셔서 고심하다 찾은 곳인데 부모님은 물론 저희도 만족했습니다^^ 말차라떼와 치킨 샌드위치, 크림 파스타가 특히 맛있었고요 그 외에도 모두 퀄리티 좋고 분위기는 물론 직원분들도 너무 친절하셔서 기분 좋은 식사였습니다 과연 합정 맛집이네요', 41, 4, 'GOOD', SYSTIMESTAMP);
