INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '생일이라서 기념으로 먹으러 왔는데 너무 친절하시고 시원하고 분위기도 너무 좋아요~~ 파인애플 쥬스 있는 곳은 처음봐요!! 공간분위기 최고 🫶🏻 오픈키친이라 더 믿음직 스러워요~~ #합정맛집', 60, 17, 'GOOD', SYSTIMESTAMP);
