INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '합정 나들이 왔다가 우연히 들렀는데 입장하자마자 식물들이 반겨줬어요!🍀🌿 매장에서 나는 은은한 풀내음도 좋고 음식도 신선하고 맛있습니다 :) 에이드도 너무 달지 않고 요청하니까 청도 추가해주시더라구요! 너무 즐거운 경험 하고 갑니다😆 #합정맛집', 7, 9, 'GOOD', SYSTIMESTAMP);
