INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오랜만에 합정에 왔는데 몸과 마음이 편안해지는 어반플랜트 합정에서 잘 놀았습니다ㅎㅎㅎ 커피도 맛있고 식물도 많아서 뭔가 더 좋았던 것 같아요. 합정동 맛집 인정, 분위기도 맛집 인정👍', 46, 3, 'GOOD', SYSTIMESTAMP);
