INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '활기차게 인사하면서 맞이해주셔서 들어오자마자 기분이 좋아지는 까페입니다. 인테리어도 너무 이쁘고 디저트도 짱맛입니다. 친구랑 즐거운 시간 보내다 가요ㅎㅎ합정 맛집입니당! 다음에 또 올듯!', 33, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '매번 올때마다 너무 예쁜 곳이예요! 잘 먹고 놀다 갑니당~!!! 역시 합정 맛집이예요~!! 직원분들 너무 친절하세요, 감사합니다', 21, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '지인 추천으로 처음 방문한 카페 도심속 이런 식물카레라니... 입소문 탈만한~ 식사 후 디저트와 커피 마시러 오기 너무나 좋다 역시나 합정맛집!!!! 사무실에서도 가까워서 자주 와야만 하는곳!!! 추천해준 칭구에게 무한 감사 ㅎㅎㅎ', 90, 17, 'GOOD', SYSTIMESTAMP);
