INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '합정 맛집으로 추천합니다! 샐러드 신선해서 좋고 파스타도 맛있네요! 잘드시는 남자 2명이면 메뉴 3개 시키는 거 추천합니다 ㅎㅎ 식물도 많아서 힐링하는 기분이 들어서 좋고 B1~2층 구조라서 좌석도 여유로워서 좋습니다!', 60, 18, 'GOOD', SYSTIMESTAMP);
