INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '음료도 너무 맛있고 분위기도 너무 좋아요오! 오랜만에 모이는 모임인데 즐거운 시간 보내고 갔습니다앙🤍 #합정맛집 #분위기맛집 #카페', 46, 9, 'GOOD', SYSTIMESTAMP);
