INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '저번에 한 번 왔다가 너무 좋았어서 또 방문했어용 식물에 둘러싸여서 브런치 먹으면 기분 짱조아짐♡ 샌드위치도 샐러드도 파스타도 다 마싯움!!! 합정맛집 찾으시면 와보세용', 60, 18, 'GOOD', SYSTIMESTAMP);
