INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '맛있고 분위기 좋아요~ 다음에 또 올게요! 합정 맛집 찾다고 온 곳인데 계속 올 것 같아요 ㅎㅎ 브런치 메뉴도 있고 커피도 맛있어요 화장실도 깨끗해요~', 28, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '날씨가 확 더워져서 기분 전환 할 겸 어반플랜트에 다녀왔어요. 도심 가운데 이렇게 식물이 가득한 곳이 있다는 건 기분 좋은 일 같아요. 조용해서 대화하기도 좋고, 혼자 집중하기도 좋은 공간이라 종종 이용합니다~ #합정맛집', 35, 8, 'GOOD', SYSTIMESTAMP);
