INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '오랜만에 동기들 만나서 어디갈지 고민하다가 왔는데 분위기듀 좋고 식물들도 많아서 넘 좋네용😋 에이드도 맛있구 커피도 잘 먹었어요 합정맛집 강추👍👍', 57, 16, 'GOOD', SYSTIMESTAMP);
