INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '음식은 사실 많이 기대안햇는데, 역시 합정 맛집으로 불리는 이유가 있네용 너무 맛있엇어요! 건강한 느낌이면 맛있기쉽지않은데 맛도 너무 좋았습니당 데이트장소로 완전 추천이에요', 44, 6, 'GOOD', SYSTIMESTAMP);
