INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '합정 맛집이라 벌써 5번째 방문인데 늘 올때마다 분위기도 좋고 숲에서 브런치 먹는 느낌이라 기분이 좋아요ㅎㅎ직원분들도 늘 친절하시고 음식도 맛있고 좋아요!!🫶 합정맛집 추천합니다💕', 5, 9, 'GOOD', SYSTIMESTAMP);
