INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '샐러드가 기대이상으로 맛있었고 페퍼민트티가 맛있어서 티백 어디꺼쓰시나 궁금해서 봤는데 그냥 어반플랜트라고 써있네요ㅋㅋㅋ 너무 맛있게 잘먹었습니다#합정맛집 #추천', 19, 8, 'GOOD', SYSTIMESTAMP);
