INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '여자친구가 친구들이랑 와보고 데이트때도 또 가고싶다해서 같이 와봤어요. 입구에 들어서자마자 싱그러운 식물냄새들이 너무 좋고 직원분들도 쏘 친절..😊 음식도 너무 맛있게 먹고갑니당. 여름 지나가기전에 한번 더 오려구요!! #합정맛집', 88, 16, 'GOOD', SYSTIMESTAMP);
