INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '합정맛집!!! 푸릇푸릇한 인테리어에 향긋한 식물향이 들어오면서 기분좋았구요. 음식도 너무 맛있고 분위기도 좋아서 만족스러워요!', 52, 16, 'GOOD', SYSTIMESTAMP);
