INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대 상수 합정 인근 까페 중에 실내 인테리어 단연 탑입니다. 실내에 식물과 화분이 한가득이라 힐링되고, 매장에 테이블도 많고 야외 공간도 많아요. 커피만 먹다가 파스타 샐러드는 처음 먹어봤는데 맛으로도 손색없네요. 무엇보다 브레이크타임이 없어서 애매한 시간에 식사하기 좋았습니다. 귯♡ #합정맛집 #홍대맛집 #상수맛집', 37, 2, 'GOOD', SYSTIMESTAMP);
