INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '분위기 좋고 음식도 맛있었던 합정 어반플랜트! 식물로 가득한 넓은 공간에서 여유롭게 식사할 수 있어서 너무 좋았어요. 브런치 메뉴부터 커피, 디저트까지 다 만족스러웠고, 합정에서 친구랑 데이트하거나 혼자 힐링하고 싶을 때 딱인 곳이에요. 합정맛집으로 완전 추천합니다 :)', 9, 2, 'GOOD', SYSTIMESTAMP);
