INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '합정역 근처 어반플랜트, 초록 인테리어가 정말 인상적이에요. 마치 식물원 안에 앉아 있는 기분이랄까. 레몬차는 은은하게 상큼했고, 토마토주스는 진짜 신선했어요. 깻잎파스타를 시켰는데 아직 먹기전이라 맛은 모르지만 인테리어에서 이미 만점이에요! 공간도 음식도 편안해서, 오래 앉아 있고 싶은 곳이에요. 자연스러운 데이트 분위기 원할 때 꼭 추천하고 싶어요.', 8, 5, 'GOOD', SYSTIMESTAMP);
