INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '자주 오는 곳인데 분위기가 너무 예뻐서 자주와요 직원분들도 너무 친절하시고 다 잘생겼어용 홍대쪽 올때마다 한번씩 옵니다 #합정맛집', 34, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '안녕하세요! 아늑한 브런치 카페를 찾다가 이렇게 예쁜 곳을 발견하게 되어 너무 기뻤어요. 음식, 분위기, 커피, 그리고 식물들까지 모두 완벽하게 어우러졌어요. 무엇보다도 음식이 정말 맛있었고 직원분들도 너무 친절하셨어요. 편안하고 즐거운 시간을 보내게 해주셔서 정말 감사합니다!:)))', 37, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '근처에 볼일이 있어서 지나가다거 우연히 향기에 이끌러 들어오게 됐습니다! 일반적인 카페, 음식점이 아닌 휴식이 가능한 느낌이 들었습니다. 그리고 합정 맛집입니다!!🙌🏻 식물들이 진짜!!! 많아서 안정감 또한 주었습니다! 마음에 드는 자리 골라서 앉을 수 있어서 또 좋았습니다.', 112, 19, 'GOOD', SYSTIMESTAMP);
