INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구가 합정 맛집이라고 저를 데리고 와줬어요! 시그니처음료와 케이크도 너무 맛있고 브런치 메뉴도 판매 하는데 다음에 다시 와서 브런치 메뉴를 먹어야 겠어요! 입구부터 꽃 향기 덕분에 아주 기분이 좋아졌어요 :) 다시 방문 할게요!! 😍', 26, 4, 'GOOD', SYSTIMESTAMP);
