INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기 정말 좋습니다 👍👍👍 플랜테리어 카페 좋아하시는 분들께는 정말 강추 입니다 👍 치킨 샌드위치 소스가 독특하고 정말 맛있었어요 ! 음식 비주얼도 좋습니다 ☺️ 사진도 잘 나오고 편하게 쉬면서 힐링 하기 좋은 곳입니다 ❤️', 29, 6, 'GOOD', SYSTIMESTAMP);
