INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '요즘 자연이 그리운지 플랜테리어 카페 장소 넘 가고싶었어요. 힐링하기 딱이었어요 음료 주문했는데 식사메뉴도 많아 좋아요. 합정 맛집 어반플랜트 또 오려구요', 81, 16, 'GOOD', SYSTIMESTAMP);
