INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '입구부터 범상치 않있던 어반플랜트 합정 ㅎㅎㅎ 초록초록한 감성에 힙한 느낌이 슬쩍 들어간 분위기가 독보적인 곳이에요!  자리도 넉넉해서 누구와 함께 하던, 뭘 하던 저절로 기분 좋아지는 곳입니다 💚 그리고 스탭분들도 다들 친절하셔서 기분이 한번 더 좋아졌어요💚 #합정맛집', 20, 7, 'GOOD', SYSTIMESTAMP);
