INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '두번째 방문했습니다! 식사 메뉴는 처음 먹어보는데 맛있었습니다 ㅎㅎ 녹차티라미수도 너무 달지 않고 커피랑 마시기 좋은 디저트였어요~! 다음에 또 방문하고 싶은 곳입니다 진짜 합정 맛집👍🏻', 22, 4, 'GOOD', SYSTIMESTAMP);
