INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '우연히 들른 카페인데 식물원 컨셉 인테리어가 특이하고 멋있어요 ㅎㅎ 실내에도 풀내음이 가득해요 🌿🌿 차분하고 조용한 분위기라 좋았어요 ! 다음에 또 올게요 :) 합정 맛집이에요 !', 17, 4, 'GOOD', SYSTIMESTAMP);
