INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오랜만에 찾아온 어반플랜트였는데 여전히 좋네요! 파스타도, 샐러드도, 샌드위치도 너무 맛있어서 먹는 내내 행복했어요☺️😋 함께 먹은 음료는 맛도 색깔도 최고~ 즐거운 시간 보내고 가요! 합정맛집 추천합니다👍👍👍😘', 83, 16, 'GOOD', SYSTIMESTAMP);
