INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '식물원에 온 느낌에 커피도 맛이 있고 좋습니다. 바리스타 분들이 프로페셔널 하구요! 도심에서 이런 식물원 카페에서 쉼을 얻어가네요 라떼도 맛나요 #합정맛집', 68, 14, 'GOOD', SYSTIMESTAMP);
