INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '샐러드 파스타 다 맛있어요 파스타는 먹느라 못찍었어요 합정맛집 추천입니다~~ 다음에 다른 메뉴도 먹어봐야겠어요 먹고 디저트도 시켰는데 티라미슈랑 딸기케이크 진짜 맛있어요! 커피원두도👍🏻', 50, 4, 'GOOD', SYSTIMESTAMP);
