INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '마치 식물원에 온 느낌의 파스타+샌드위치 합정맛집 들어가는 입구부터 식물들이 반겨줍니다. 오랜만에 브런치를 먹으려고 보다가 찾아낸 곳 합정역 상수역 사이에 있어서 거리가 좀 있지만 그만큼 가격도 착하고 맛있고 분위기가 좋네요. 오늘은 비가 추적추적 내리는 날인데 테라스석에 자리를 잡으니 천정창에 떨어지는 빗소리가 분위기를 더욱 감성적으로 만들어 줍니다. 지하는 아늑하고 감싸는 공간으로 1층은 식물원 같은 공간으로 2층은 시원한 공간감으로 어느 곳 하나 버릴 곳이 없네요 ^^ “부라타 프로슈토 샌드위치”는 잘 구운 빵과 새콤달콤한 샐러드가 너무 잘어울렸고 “신선한 깻잎 & 새우 파스타”는 바질,캣잎 패스토의 향이 너무 맛있고 신선한 느낌이라 제 기준으로는 이 집의 시그니처 라고 말하고 싶네요.', 86, 18, 'GOOD', SYSTIMESTAMP);
