INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '브런치 메뉴가 정갈하고 맛있었어요. 파스타도 소스가 진하고 깔끔해서 만족스러웠고요. 매장이 넓고 쾌적해서 식사하는 동안 편안했어요. 재방문 의사 있어요!', 50, 9, NULL, SYSTIMESTAMP);
