INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '유명하던 카페인데 드디어 와봤어요. 제가 좋아하는 초록초록 식물들이 가득해서 너무 아늑하고 햇빛이 편안하게 들어오는 2층 테라스 같은 공간도 너무 마음에 들어요. 주문 받으시는 여자 직원분이 너무 친절하셔서 좋았어요. ☺️ #합정맛집', 56, 15, 'GOOD', SYSTIMESTAMP);
