INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '예전에 정말 많이왔었는데 오늘 친구랑 추억여행 왔습니다 ~ 여전히 너무 초록초록하고 ~ 특유의 싱그러운향에 기분이 좋아져요 ~ 날이 너무 좋아서 유독 플랜테리어가 독보여요! 불빛도 제가 좋아하는 따듯한불빛이라 데이트하기에도 좋아요 ~ 강추합니다 #합정맛집', 89, 14, 'GOOD', SYSTIMESTAMP);
