INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '식물🍀🍀인테리어가 너무 예쁘고 시그니처 음료도 맛있었어요! 사진찍기도 엄청 좋았습니당~~ 음료뿐 아니라 브런치 등 식사 메뉴도 있어서 합정맛집 찾으시는 분들께 추천드려요👏 가족들이랑 와도 분위기 좋아서 강추합니다!', 25, 7, 'GOOD', SYSTIMESTAMP);
