INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '우연히 지나가다가 너무 예뻐서 방문하게 됐는데 넓고 쾌적하고 인테리어도 감각적이고 또 방문하고 싶어지게 되는 곳이에요! 음료도 커피도 맛있어요~ 즐겨찾기 해놓고 자주 찾아뵐게요^_^합정 맛집입니다~~! #합정카페#함정맛집', 34, 8, 'GOOD', SYSTIMESTAMP);
