INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '이직준비하면서 자소서도 쓰고 공부하려고 카페알아보고있었는데 합정맛집이라고 지인이 추천해줘서 방문했습니다고 지인들끼리 만났는데 매장도 넣고 집중도 잘되는 분위기라서 너무 만족하면서 시간보냈습니다. 합정카페맛집입니다🙂', 37, 8, 'GOOD', SYSTIMESTAMP);
