INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '리뷰 이벤트로 주시는 식물 받으러 왔어용용🤍 깻잎파스타 맛있어요!!! 자리도 편하고 분위기도 좋고 식물이 많아서 좋아요~ 어둡고 노란 조명이라 데이트하기도 좋을 듯! 2층에서 식사했는데 좋았어요! 합정맛집으로 추천 합니다!', 48, 4, 'GOOD', SYSTIMESTAMP);
