INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '플랜테리어 멋지고 음식도 신선하게 맛있어요. 오늘은 비즈니스 목적으로 혼자 왔는데요. 예전에 가족, 동료와도 왔었고 모임도 여기서 하고 싶네요. 애정하는 공간입니당 #합정맛집 #홍대맛집', 6, 6, 'GOOD', SYSTIMESTAMP);
