INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '우연히 검색해서 들어왔는플랜테리어 너무 멋지구요 비오는날인데 빗소리와 풀향기가 어우러져서 너무 좋았어요. 음식도 맛있었어요. 샐러드 푸짐하고 화이트크림파스타 꾸덕하고 맛있어어요!!', 12, 4, 'GOOD', SYSTIMESTAMP);
