INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '두번째 방문이에요 여전히 매장은 숲속에 들어온것처럼 예쁘고 기분이 좋아져요 음식도 예쁘고 맛있고 친구나 연인과 와서 즐기기 딱이에요 추천합니다!', 21, 9, 'GOOD', SYSTIMESTAMP);
