INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '여자친구가 식물을 좋아하고 생일이라 방문했어요~ 인테리어 멋지고 식물이 있어서 싱그러운 느낌이 드는 카페입니다 음료 맛있게 마시고 갑니다 다음엔 와서 아메리카노에 샌드위치 먹고 가야겠습니다^_^*', 6, 2, 'GOOD', SYSTIMESTAMP);
