INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '탄핵심판 선거날 첫째 딸이랑 데이트하러 다녀온 집. 오렌지부라타샐러드의 드레싱부터 산뜻하게 입을 사로 잡더니 이어서 나온 화이트크림 파스타의 고소한 맛과 김치라구파스타의 칼칼한 맛이 기가 맥힌 밸런스를 보여줬습니다. 식물이 가득한 내부 인테리어도 좋았고 서비스도 아주 훌륭했던 곳. #합정맛집', 18, 2, 'GOOD', SYSTIMESTAMP);
