INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '이미 3-4번째 방문입니다! 합정 오면 꼭 들리는 곳 입니다. 일단 식물이 많아서 초록초록한 인테리어와 들어오는 햇살이 좋어요~ 음식들도 신선하고 시그니쳐 말차 음료는 꼭 드세요!!(크림 +말차? ㅋ미쳣음) 선셋 음료는 신상까라인데 이것도 맛잇습미더 주말엔 자리 잡기 힘들긴한데 회전율 좋어서 금방 좋운 자리에 앉을 수 있었습니다 무튼! 데이트 + 친목하기 좋은 곳입니다 합정 맛집입니다', 12, 7, 'GOOD', SYSTIMESTAMP);
