INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '그린플로우!! 꼭 드세요 말차라떼인데 좀 덜 달고 아인슈페너 같은 크림이 올라가는데 엄청 쫀쫀하고 맛있어요😊 인테리어도 넘 예쁘고 평일 낮에 오니까 콘센트 좌석도 널널해서 ㅇ작업하기도 짱 좋을 것 같아요 음악 소리 크지 않아서 매우 좋아요!!! #합정맛집', 4, 5, 'GOOD', SYSTIMESTAMP);
