INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '리뷰보니 치킨샌드위치 많이 시켜서 저휘도 주문했는데 남편이 사진 찍자마자 바로 와구와구 ㅋㅋㅋ 맛집 인증ㅋㅋㅋ 맥주 땡기는 맛인거 함정입니다 그리고 궁금해서 시켜본 그린플로우. 달달하고 말차맛이 넘 맛있어요!! 합정맛집 인정!!조만간 또 오겠습니당', 6, 4, 'GOOD', SYSTIMESTAMP);
