INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '카페가 식물원같고 너무 예뻐요! 들어가자마자 식물향기가 퍼져서 기분이 진짜 좋아요! 근처에서 카페 찾다가 들어갔는데 커피랑 디저트 먹기에도 좋고 식사하기에도 좋아보여요!', 50, 4, 'GOOD', SYSTIMESTAMP);
