INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '입구부터 분위기가 너무 좋았어요 🩷💛 노래도 그렇고 완전 느좋 식물원 느낌 〰️‼️ 식물 냄새도 물씬 나용 ㅎㅎㅎ 평일 오후인데도 생각보다 사람이 좀 있었어요 ㅎㅎ 우연히 방문했다가 즐겁게 이용하고 갑니다 👍 #합정맛집', 68, 11, 'GOOD', SYSTIMESTAMP);
