INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '리뷰는 처음쓰지만, 두 번째 방문이예요. 모임으로 왔었다가 이번엔 가족들과 함께 왔어요~ 첫 인상이 초록초록에 아늑한 느낌이라~ 좀 오래 앉아 있다 가고 싶은 곳이었어요. 아이가 배고프다고 나오자마자 먹어버려 사진은 못 찍었는데, 크림 파스타가 고소하고 맛있었어요.  샌드위치도 맛있고, 깻잎 새우 파스타 독특했어요. 점심먹으러 온거라~ 오래 못 있는 게 아쉽네요. 다음엔 커피마시러 와서 놀다가고 싶어요.', 49, 10, 'GOOD', SYSTIMESTAMP);
