INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '맛,서비스,양 다 훌륭합니다🩵 부라타 프로슈토 샌드위치/깻잎 새우 파스타 추천드려요!!🩵🩵 무엇보다 좋은 건 식물이 아주 많아서 힐링된다는 점이에요 🩵', 24, 7, 'GOOD', SYSTIMESTAMP);
