INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '지나가다가 식물이 가득한 카페가 있어서 들어왔는데 안쪽으로 들어가니까 완전 숲속마냥 식물이 가득가득해서 신기했어용! 푸릇푸릇한 향도 나고 공간도 꽤 컸습니당 숨겨진 공간도 많아요 디저트도 맛나고 괜찮습니다! #합정맛집', 3, 6, 'GOOD', SYSTIMESTAMP);
