INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '엄마와 아이와 데이트 하기 위해 멀리서 찾아서 왔어요~ 식물 가득 가득 ~ 싱그러운 식물 향기와 함께 힐링 되는 기분이에요 ~ 역시 합정 속 멋진 장소!! 음식도 너무 맛있고 직원분들도 너무 친절하셔요~ 자주 방문 할게요~^^', 33, 3, 'GOOD', SYSTIMESTAMP);
