INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '카페 입구부터 식물로 둘러쌓여있고 향긋한 풀향기가 나서 좋았습니다. 다만 아인슈페너나 그린플래너 마실때 작은 티스푼 같이 주시면 좋을 것 같아요! 더운 여름날씨 시원한 커피에 잠시 쉬어갈 수 있는 합정맛집 카페로 추천합니다🍀', 23, 7, 'GOOD', SYSTIMESTAMP);
