INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '저번에 지나가다 여기 카페를 보구 다음에 꼭 와봐야지 했거든요!! 자연 좋아하시는 엄마랑 같이 찾아왔는데 생각보다 제가 더 취향 저격 당했습니다 😊 더운 날씨 상큼한 샐러드도 너무 좋았구요 특히 커피가 넘넘 맛있어요 합정 분위기 맛집 커피 맛집 어반플랜트~!', 25, 1, 'GOOD', SYSTIMESTAMP);
