INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '반려동물 동반 가능이라 저희 집 강아지랑 같이 방문했습니다! 가게 안까지 주변이 초록초록해서 너무 이뻤고 시그치너인 새우깻잎 파스타 진짜 특색 있고 맛있었어요👍🏻🥰 합정 브런치 맛집 인정합니당 점심시간 전인데도 사람 많고 활기차서 좋았습니다! 직원분들도 넘넘 친절하세요!', 48, 10, 'GOOD', SYSTIMESTAMP);
