INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '티라미수 오리지널 살짝 달면서 커피 맛이 향긋해요 음료도 맛있구요 👍🏻매장 안에 식물들이 많아서 상쾌하고 아늑해요 🌿 사진도 예쁘게 나와요 그리고 테이블 간격도 적당히 떨어져있어서 대화하기도 편했습니다 #합정 #합정맛집 #어반플랜트', 89, 17, 'GOOD', SYSTIMESTAMP);
