INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '도심 속 자연을 맡볼 수 있는 식물카페예요! 합정역 근처 숲속에서 힐링하는 기분이네요 매장 입구 드러서자 마자 아카시아 향이 코속을 마중나오네요 기분 좋은 향과 분위기 입니다. 대화 나누기 좋고 쉼하기 좋은 카페예요^^ 합정맛집입니다', 32, 1, 'GOOD', SYSTIMESTAMP);
