INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '공간 인테리어랑 식물들이 주는 독특한 느낌에 음악 선곡도 좋아요. 무엇보다 음식이 예상보다 더 맛있었어요… 샐러드도 페스토가 들어가서 감칠맛 나고 파스타도 다른 곳보다 진한데 후추 때문에 느끼하지 않아서 맛있게 먹었어요:)', 56, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '브런치 먹으러  합정 맛집 어반플랜트 방문했는대 식물이 많아 기분까지 상콤해지네요^^ 친절한 직원들과 음식 맛두 좋아요 🫶 #합정 맛집', 68, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '입구에서부터 나는 자연의 공기. 들어서는 순간 느껴지는 편안함. 더위를 단번에 시켜주는 음료까지.. 직원들의 친절도 한목합니다. #합정맛집 #인정 #재방문100%', 6, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '합정 맛집 어반플랜트♡ 분위기 맛집인줄 알았더니 파스타도 넘 맛나게 잘 먹엇어요 이제 날씨가 좋아지니 2층 테라스 자리 분위기잇고 넘 좋네요~ 직원분들도 얼마나 친절하신지...ㅎ 데이트도 친목 모임도 하기 좋은 어반플랜트에서 행복한 시간 보내고 가요~ 사징님 번창하세요!', 44, 10, 'GOOD', SYSTIMESTAMP);
