INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '초록초록 예쁜 공간에서 브런치 맛있게 잘 먹었어요! 샌드위치에 샐러드까지 같이 나와서 너무 좋았고 파스타도 꾸덕하니 맛있었어요😋', 32, 10, 'GOOD', SYSTIMESTAMP);
