INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '식물로 가득찬 인테리어도 너무너무 예브고 음악도 좋아서 친구랑 브런치 먹기 너무 좋았습니다🥰 음식도 너무 맛있었어요 다시 방문할것 같아요!! 합정맛집', 75, 17, 'GOOD', SYSTIMESTAMP);
