INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '두번째 방문이에요~! 원래 아는 언니랑 왔다가 너무 좋아서 엄마랑 같이 오게 되었어요 !! 음료가 정말 맛있고 분위기도 좋고 도심 속 식물원에 온 것 같은 느낌이 드네요 ㅎㅎ 음식도 다 깔끔하고 직원들이 친절해서 좋았어요 ㅎㅎ 재방문 예정입니다 👍👍', 24, 1, 'GOOD', SYSTIMESTAMP);
