INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '합정 맛집 어반플랜트 합정 플랜테리어 너무 예쁘고 분위기 엄청 좋아요 💚🍵 앞으로도 자주 오게 될 것 같아요 ☕️🍽️ 합정 디저트 카페로 어반플랜트 추천해요 😉👍🏻', 86, 11, 'GOOD', SYSTIMESTAMP);
