INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '#합정_맛집 아늑하고 직원분들이 명랑+발랄하셔서 카페의 청량하고 맑은 분위기에 잘 어울려요! 아인슈페너와 말차티라미수를 시켰는데 싱그러운 풀향이랑 나무향이 나는 공간에서 먹으면서 멍때리니까 마음이 편해지고 스트레스가 풀리는 기분이 들어서 좋았습니다 도심에서는 이런 공간을 만나기가 어려워서 늘 아쉬움을 가지고 있는데 친구덕분에 식물과 우드테마로 꾸며진 곳을 알게 되어서 즐거웠어요:) 다음에는 좋아하는 사람들이랑 와서 와인이나 파스타같은 식사도 하면서 보내고 싶어요 (*˙︶˙*)☆*°', 21, 9, 'GOOD', SYSTIMESTAMP);
