INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '합정 맛집이에요! 양도 많고 돌체라떼 너무 맛있어요! 크림 진짜 찐이에요^^ 매장 분위기도  좋고 직원분들도 친절하세요 또올게요☺️', 25, 2, 'GOOD', SYSTIMESTAMP);
