INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '분위기가 너무 좋아요. 직장 동료분들과 점심 식사겨무왔는데 조용하고 음식도 너무 맛있어요. 다만, 콜라 사이다가 없어서 조금 아쉬웠어요ㅠㅠㅠㅠ 그래도 같이 시킨 에이드들도 너무 맛있었습니다! 추천합니다~~~~ #합정맛집 #분위기맛집 #파스타맛집', 42, 10, 'GOOD', SYSTIMESTAMP);
