INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '저번에도 지나가다가 와보고싶었던 곳인데 오늘 친구덕분에 왔어요! 제가 식물을 엄청 좋아하는데 삭막한 도시에 이런 여유 가득한 곳이 있다니 가뭄에 단비같네요..ㅎ 사장님들도 엄청 패셔너블하시고 친절하셔요!!! 디져트로 딸기케이크를 시켰는데 촉촉한 딸기케이크.. 너무 달지않고 마싯어요!! 티 종류도 한눈에 보이니 센스만점..! 이곳은.. 합정맛집..! 나만 알고싶지만.. 추천드려요 ㅎㅎ', 12, 6, 'GOOD', SYSTIMESTAMP);
