INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '우연히 들어오게 됐는데 사장님도 너무 친절하시고 가게 분위기가 너무 좋아요,, 풀향 가득 나서 차분해지고 테이블도 커서 좋습니당!! 합정에서 분위기 좋은 카페 가려면 여기가 진짜 좋은 것 같아요!', 34, 4, 'GOOD', SYSTIMESTAMP);
