INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '합정역에 몇 없는 대형 카페! 푸릇푸릇한 식물이 많아서 좋아요. 가끔 힐링하고 싶을때마다 오는데 음료 다 맛있어요. 특히 아메리카노가 고소해서 제 취향이에요 😊 합정 맛집 어반플랜트 🌞', 30, 0, 'GOOD', SYSTIMESTAMP);
