INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '샌드위치 15000원 - good. 샌드위치치곤 좀 비싸네했는데 샐러드랑같이 푸짐하게 나옴 토마토쥬스 7000원 - 그럭저럭. 설탕이 1도안들어간맛이라 개인적으로는 좋았음. 개선했으면하는점- 발사믹소스를 별도로 담아주면좋겠음..나한텐 너무 많아서 짰고, 샌드위치빵까지 스며들어서 먹기가 불편했다. 가장좋은점 - 식물에 밟힐것같은 인테리어,푸짐하고맛있는 샌드위치 #합정맛집 #식물카페', 7, 8, NULL, SYSTIMESTAMP);
