INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '좋은냄새가 나는곳... 향기로 기억할듯.... 푸르른곳에서 푸르른 음식을 먹고... 태양같은 음료를 마시고... #합정맛집 맛나다!!!', 35, 1, 'GOOD', SYSTIMESTAMP);
