INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '어반플랜트는 언제나처럼 정말 훌륭해요. 아늑하고 은은한 분위기 그리고 크림이 들어간 샌드위치와 파스타도 정말 맛있었어요. 조용하고 분위기 좋은 곳에서 편안한 저녁 시간을 보내기에 완벽해요. 직원분들도 아주 친절하셨어요 :) #합정맛집', 49, 3, 'GOOD', SYSTIMESTAMP);
