INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '마치 화원에 온듯한 분위기도 좋고 식물들이 내뿜는 신선한 향도 좋아요~ 특히나 파스타는 최근 맛본 것들중 최고였어요~ 면 익힘 정도가 예술이에요~ 너무 맛있게 먹었어요^^  합정 맛집이에요~~', 104, 26, 'GOOD', SYSTIMESTAMP);
