INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '합정역 근처에 온김에 방문했습니다 직원 분들도 너무 친절하시고 냄새가 너무 좋아요....힐링하기 너무 좋은 공간 같아요👍 합정 맛집으로 추천합니다‼️', 25, 2, 'GOOD', SYSTIMESTAMP);
