INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '처음 왔는데 공간이 초록초록하고 너무 멋져요!  커피도 종류가 다양하고 맛있어요. 일하시는 분들도 친절하셔서 기분이 좋아지는 곳이었습니다. 또 오고 싶은 곳이에요 ^^', 96, 26, 'GOOD', SYSTIMESTAMP);
