INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '날씨가 우중충해서..선택한 “초록초록 어반 플렌트 ” 음악도 이국적이고 무엇보다 커피 너무 맛있네요..^^ 다음엔 브런치 먹으러 와야겠다는 ㅎ #합정 맛집 #뷰맛집 #커피맛집', 18, 1, 'GOOD', SYSTIMESTAMP);
