INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '합정 근처에서 제대로 된 카페를 찾았습니다 피톤치드 향이 나면서 힐링 되는 느낌이에요 앞으로 자주 여기서 시간 보내게 될 것 같아요! 아늑한 분위기에 카페를 찾으신다면 여기 꼭 방문해 보시는 걸 추천 드립니다👍 #합정맛집', 21, 10, 'GOOD', SYSTIMESTAMP);
