INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '1층은 풀향기가 너무 좋아요 음식들도 건강하고 샐러드도 싱싱하고 파스타도 너무 맛있게 먹었습니다 직원분들도 너무 친절해요 크림파스타 진짜 진하고 맛있어요 #합정맛집', 57, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '부모님이 서울에 오셔서 어디가지 깊은 고민끝에 친구 추천으로 방문했습니다 ! 부라타 샌드위치 / 딸기마스카포 꼭 드세요 ❗️ 두번 드세요 … plz 레알 찐 합정맛집 입니다 🙌🏻 그리고 무엇보다 카페에서 이런 서비스는 처음 느껴보는거같아요 !!! “ 좋은시간 보내세요 “가 너무 인상깊었고 덕분에 진짜 너무 좋은시간 보내고갑니다 !!! 🍀 사장님이 맛있고 음식이 친절해요 🍀 감사합니다 🙏🏻🔥🙏🏻', 83, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '합정와서 예쁜카페 찾다가 들어왔는데 공간이 너무예쁘고 식물이 많아서 식물원 온 기분이에요😊😊😊 레몬차도 맛있고 힐링하고 갑니데이 다음에 또 올게요!🤍🤍#합정맛집', 40, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '자연 친화적인 인테리어와 직원분들의 파이팅이 넘치는 공간이네요….. 기분이 좋아지는 공간에서 잘 머물다 갑니다 자연광도 예쁘게 잘 들고 식물들도 많아서 보기에 예뻐요 잘 머물다 갑니다 #합정맛집', 42, 6, 'GOOD', SYSTIMESTAMP);
