INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '푸릇푸릇한 식물에 둘러싸여 힐링받는 느낌으로 점심 즐길 수 있어서 좋았어요🍃!! 파스타도 토마토치킨 물리지 않고 맛있었고, 특히 깻잎 파스타가 생각보다 훨씬 색다르게 맛있었습니다🤍🥗!! #합정맛집', 45, 10, 'GOOD', SYSTIMESTAMP);
