INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '봄 기운이 완연해지면서 나들이 겸, 브런치 먹을 겸 왔는디 깻잎 페스토가 진짜 맛있어요!! 샐러드랑 샌드위치도 맛있고 식물원 분위기에서 여유 느끼면서 식사하기 너무 좋네요 아래층, 위층다 있어서 좌석도 여유로운것 같아요 ㅎㅎ', 66, 13, 'GOOD', SYSTIMESTAMP);
