INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '어반플랜트의 말차라떼를 마셔봤는데, 정말 맛있었습니다. 달콤하면서도 말차 특유의 진한 풍미가 잘 살아있어서 깔끔하게 즐길 수 있었어요. 말차의 쌉싸름함과 부드러운 우유가 조화를 이루며 끝까지 질리지 않게 마실 수 있었고, 당도도 과하지 않아서 디저트와 함께 즐기기에도 딱 좋았습니다. 말차를 좋아하시는 분들께 꼭 추천드리고 싶은 음료예요! 새롭게 찾은 합정맛집이에용👍👍', 31, 7, 'GOOD', SYSTIMESTAMP);
