INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '매장이 식물로 가득하고 노래도 좋아서 분위기가 좋아요!! 이런 분위기 좋은 곳은 보통 협소한데, 넓어서 너무 좋아요 ㅎㅎㅎ 너무 친절하시고 음료도 짱맛있었습니다. 청 들어가는 메뉴는 말씀드리면 추가로 더 넣어주신다 하셔서 너무 좋았어요 #합정맛집', 45, 4, 'GOOD', SYSTIMESTAMP);
