INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '분위기가 너무 편하고 아늑해요. 자연 좋아하시는 분들께 추천드려요. 공간도 되게 쾌적하고 직원분들도 너무 친절해서 덩달아 기분이 좋아지는 곳 입니다. 다음에 또 방문할 것 같아요😊🍃', 11, 4, 'GOOD', SYSTIMESTAMP);
