INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '와 풀냄새가 너무 좋아요..! 들어가자마자 향긋한 향에 정화되는 기분! 음료도 맛있고 다들 친절하십니다 히히 저는 재방문할거에요! 완전 합정 맛집!!😏', 22, 1, 'GOOD', SYSTIMESTAMP);
