INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '오랜만에 언니들이랑 만났는데 이런 좋은곳이 있어다니~!! 감탄스럽네요 입구부터 느껴지는 포레스트향이~ 너무 힐링되네요 맛도 좋고 분위기도 좋고~^^ 합정역에 올때마다 어반플랜트 들릴것같아요 굿굿!', 35, 4, 'GOOD', SYSTIMESTAMP);
