INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '들어오자마자 많은 식물에 감탄했습니다 향도 좋고 공간도 넓어 구경하는 재미도 있네요 물론 음료도 맛있었습니다 합정 맛집이에요ㅎㅎ', 26, 4, 'GOOD', SYSTIMESTAMP);
