INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '합정 맛집 어반플랜트에 왔어요^^케이크는 컵에 담겨 있어요. 원래 티라미수 케이크는 즉석에서 만들어 주는 거라고 들었는데 직접 만들어주시네요^^ 부드럽고 맛있어서 추천해요~~커피는 산미가 있어서 맛있어요. 부드럽고 거품도 풍부해요.', 72, 14, 'GOOD', SYSTIMESTAMP);
