INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '중딩 딸이랑 점심 먹을 겸 들렀는데 오렌지 쥬스가 아주 상큼하고 맛있었구요~ 바닐라 라떼 샷 추가해서 마셨는데 커피 맛집이라고 해도 손색없어요. 파스타 두 종류 시켜서 먹었는데 너무 맛있고 함께 주는 갈릭 브레드도 참 맛있었어요~', 20, 7, 'GOOD', SYSTIMESTAMP);
