INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '세상 마상에 이런 분위기 좋은 곳은 처음이에요 집 근처에 이렇게 좋은 카페가 있는 줄 몰랐어요 직원분들도 너무 친절하시고 커피도 너무 맛있어요 저만 알고 싶은 아지트 같은 느낌이랄까? 지금 스크롤 내리면서 카페 어디갈지 고민이면 여기 당장 오세요 당장. 안 오면 인생 절반 후회합니다 사장님 번창하세요 ~🌱', 75, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '카페가 너무 예쁘고 합정맛집 인정합니다! 음식도 맛있고 직원분들도 친절해요! 플랜테리어가 너무 예뻐서 기분 좋게 먹었어요~ 양도 많아서 배부르게 먹었습니다 짱~', 79, 15, 'GOOD', SYSTIMESTAMP);
