INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '예쁜 식물들로 인테리어가 되어있어, 편안하고 숲에 온 느낌으로 식사를 할 수 있어 너무 좋았어요. 특히, 깻잎 파스타가 다른 곳에 없는 특별한 메뉴라 좋았어요.~ 합정맛집 입니다', 49, 5, 'GOOD', SYSTIMESTAMP);
