INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '오랜만에 친구들과 만남인데 양도 많고 예쁘기도하고 맛도 넘 만족스러워요 맛집♡ 장소도 대화나누기 좋고 푸르름이 기분이 좋아요♡', 24, 4, 'GOOD', SYSTIMESTAMP);
