INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '데이트 혹은 친구랑 자주 오는 어반플랜트 식물이 있어서 너무 힐링이고 음식이 너무 맛있어요 아침에 브런치(?)로 깻잎파스타랑 어반치킨샌드위치 먹었는데 깻잎파스타 미쳤어뇨 꾸덕 너무 맛있게 다 먹었어요 어반플랜트는 합리적인가격에 음식이 푸짐해서 좋아요', 52, 13, 'GOOD', SYSTIMESTAMP);
