INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '식물이 많아서 그런가 분위기도 좋고 향도 좋아요! 너무 붐비거나 시끄럽지도 않고 외국 카페 온 느낌이네요ㅎㅎ음식도 맛있어용 합정맛집으로 추천합니다~~', 44, 10, 'GOOD', SYSTIMESTAMP);
