INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '#합정맛집 뷰가 너무 좋아요. 식물이 엄청많아 기분도 좋고, 건강도 좋아지는 기분이에요. 크림 파스타는 청양고추가 살짝 들어갔는지 느끼하지 않고 알싸하면서 맛있게 먹을 수 있어요. 귤 샐러드는 새콤하면서 달콤한 맛을 느끼기 좋고, 샌드위치는 빵이 딱 알맞게 구워져 고소하면서 든든하게 먹기 좋았어요!', 40, 7, 'GOOD', SYSTIMESTAMP);
