INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '카페 분위기가 정말 좋아요. 인테리어도 아늑하고 조용해서 혼자 책 읽거나 공부하기에도 딱이에요. 커피 맛도 훌륭하고, 디저트도 정성스럽게 만들어졌어요. 직원분들도 친절해서 기분 좋게 머물 수 있었어요. 다음에 또 방문하고 싶은 카페예요!합정 맞집!', 14, 6, 'GOOD', SYSTIMESTAMP);
