INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '브런치 카페로 정말 좋아하는 곳인데 맛있게 먹었습니다. 인테리어도 정말 멋져요. 항상 느끼지만 직원분들이 정말 친절해서 기분 좋게 나가는 거 같아요.', 32, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아이 데려다 주러 합정에 왔는데 우와~~  이런 카페가 있군요. 나도 모르는 사이. 유혹당하듯 들어왔네요. 마치 중세 귀족들 식물 정원에 모여 티 타임하는 기분?  피톤치드 나오는 고무 나무, 시페루스등 공기정화 식물로 가득. 날씨가 따스해져서 야외에서 커피도 마시고 즐거운 시간 이네요. *^^*~~', 12, 5, 'GOOD', SYSTIMESTAMP);
