INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '초록을 한껏 즐길 수 있던 공간!! 식물원이나 다름 없는 거대한 공간이었습니다!! 풀냄새 향긋하고 자연친화적인 인테리어까지! 맛있고 멋지고 완벽했어요ㅜㅜㅜㅜ 밤에 와도 예뻤는데 낮에 오면 더 예쁠 것 같아요!!! 친구와 일상 힐링 🌸합정 맛집🌸 연인 데이트 장소로 추천합니당 🤗🤗', 12, 8, 'GOOD', SYSTIMESTAMP);
