INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '주말 10시에 여는 곳을 찾아 온거였는데, 생각보다 분위기도 너무 좋고 음식도 맛있었어요 ㅎㅎ 특히 깻잎파스타? 맛있더라고요 ㅎㅎㅎ 오후 되니깐 사람들 많더라고요~ #합정맛집', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '어반플랜트 합정점은 처음인데 초록초록한 분위기부터 식물 향기까지 너무 좋아요ෆ 구석구석 공간을 둘러봤는데 조용하게 작업할 수 있는 곳도 있고 또 트인 공간에서는 친구들과 같이 이야기 나누기도 좋은 거 같아요!! 커피도 너무 맛남 ㅠㅠ #합정맛집', 4, 8, 'GOOD', SYSTIMESTAMP);
