INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '최근 합정에서 방문한 카페중에 제일 좋았던거같아요 카페 내부는 아늑하고 편안한 분위기로, 친구들과의 대화나 혼자 책을 읽기에 딱 좋습니다. 커피는 진하고 맛있으며, 디저트도 다양하고 신선해요. 특히 이 카페는 합정맛집으로도 유명해서, 많은 사람들이 찾는 이유를 알겠더라고요. 바리스타 분들도 친절하고, 카페에서 제공하는 음악도 너무 좋아서 마음껏 시간을 보내기 좋았답니다. 다음에 또 오고 싶은 카페로 강력 추천합니다!', 70, 12, 'GOOD', SYSTIMESTAMP);
