INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '네이버에서 검색하고 왔는데 인테리어와 분위기보고 너무 이뻐서 깜짝놀라고 친절한 직원분들 인사에 너무 기분좋았습니다 파인애플 쥬스와 샌드위치 샐러드 🥗너무 맛있게 먹었습니다 여태 먹었던 샐러드중 가장 맛있었어요!! 또 빵도 바삭폭신하니 너무 잘먹고 갑니다! #합정맛집 #카페맛집', 25, 1, 'GOOD', SYSTIMESTAMP);
