INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '여기!! 합정 맛집이에요!! 음식 진짜 맛있고 여기 들어오자마자 엄청 꽃향기 나요 식물이 진짜 많고 쾌적하고 좋습니다 담에 또 올게요🫶🏻🫶🏻🫶🏻🫶🏻', 5, 7, 'GOOD', SYSTIMESTAMP);
