INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '음식이 너무 맛있고(로제파스타 추천!!) 분위기도 너무 좋아요 야외공간도 좋고… 푸릇푸릇하고 향긋한 공간이에요 ☺️ #합정맛집', 23, 4, 'GOOD', SYSTIMESTAMP);
