INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '오늘로 2번째 방문이네요!! 오백년만에 합정나들이에 어반플랜트를 잊을 수 없어서 다시 왔습니다ㅎㅎ 여기가 브런치 샌드위치 전부 다 맛있지만 밥을 먹고 온 관계로 케이크에 음료 주문했어요ㅎㅎ 물론 케이크도 아쉬움하나없이 너무너무 맛있었습니다! 마치 식물원에 온것같은 인테리어 친절한 직원분들까지 최고에요👍🏻👍🏻 주변지인들에게도 마구마구 소문내고 있습니다ㅋㅎㅋㅎ 또 언제 합정에 올지는 모르지만 그때 또 올게요🫶🏻🫶🏻', 61, 15, 'GOOD', SYSTIMESTAMP);
