INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '들어오자마자 좋은 향기가 인상적이에요. 라떼도 맛있고 샐러드도 신선해요. 친구랑 조용하게 대화하기 좋네요. #합정맛집 #합정카페', 67, 14, 'GOOD', SYSTIMESTAMP);
