INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '마치 숲속 같은 분위기, 오래도록 정성껏 키운 식물들이 우리를 감싸주는 곳. 어반플랜트 합정에 집안 어르신들을 모시고 왔습니다. #합정맛집 내집 정원같은 편안한 분위기에서 어르신들이 두런두런 회포를 푸시는 모습을 뵈니 절로 얼굴에 미소가 지어집니다. 언제 들러도 편안하고, 좋은 추억이 쌓여지게 하는 어반플랜트합정입니다.', 130, 21, 'GOOD', SYSTIMESTAMP);
