INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '우연히 방문하게 되었는데 너무 햇살 맛집이라 행복했어요!☺️ 직원분들도 친절하시고 밝은 에너지로 인사해주셔서 행복한 에너지 받아가요! 창문밖으로 보이는 식물들과 햇살이 찰떡이라 너무 좋았던 시간이였습니다!🍀 #합정맛집', 18, 8, 'GOOD', SYSTIMESTAMP);
