INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '입구부터 향긋한 식물 향이 났는데, 음식도 맛있었어요!! 들어오는 순간 식물원느낌 나서 해외온 것 같구 좋았습니다 :> #합정맛집', 16, 9, 'GOOD', SYSTIMESTAMP);
