INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '공간이 넓고 선풍기 없이도 시원하고 좋네요 음식도 맛있고 커피도 맛있어요. 커피 산미 강한거 싫은 데 산미도 약하고 좋은 거 같아요. 개인적으로는 또 지인들과 올 거 같아요^^', 52, 16, 'GOOD', SYSTIMESTAMP);
