INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '매점 직원들이 너무 친절하십니다! 음료수 맛도 너무 좋고 매장 내에 식물들이 많아서 냄새가 너무 좋습니다. 분위기도 너무 좋아서 합정 카페 찾아서 올때 자주 들릅니다!!', 128, 24, 'GOOD', SYSTIMESTAMP);
