INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '식물로 꾸며진 실내가 넘 이뻐서 사진도 잘 나오고 음식도 깔끔하고 맛있어요. 소개도 많이 하고 담에 또 올께요~♡ 합정 맛집~최고최고', 83, 14, 'GOOD', SYSTIMESTAMP);
