INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '이렇게 초록초록한 곳이 있다는게 너무 좋았어요 비오는 날 왔는데 오히려 더 운치있고 쾌적했어요 그리고 음식도 맛있고 사진이 잘나와서 너무 좋아요 #합정맛집 추천해요', 20, 1, 'GOOD', SYSTIMESTAMP);
