INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '추운 날 카페를 찾다가 우연히 들어온 어반플랜트 겨울과 상반되는 푸릇한 봄이 확실히 보여서 힐링되는 분위기가 가득해요 커피도 너무 맛있고 케이크도 너무 맛있어요 그리고 매장 분위기도 좋아서 다음에는 브런치 먹으러도 와야겠어요❤️ 미리 봄을 느끼고 가서 행복했어요 커피맛도 분위기도👍🏻👍🏻', 38, 8, 'GOOD', SYSTIMESTAMP);
