INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '푸릇한 식물들이 잔뜩 있는 공간에서 먹으니 여행 온 듯 여유롭게 즐겼어요. 샐러드와 샌드위치도 맛있어서 기분 좋게 다녀갑니다. #합정맛집', 69, 16, 'GOOD', SYSTIMESTAMP);
