INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '최근에 알게 되었다가 완전 단골이 되어버린 작업 맛집입니다. 친구들이랑 적당히 노가리 까기도 좋고 혼자서도 많이 와요. 공간과 어울리는 음악이 나와 집중하기 진짜 좋습니다. 파이를 직접 만드신다는데 진짜 엄청맛있어요. 이상한 메뉴도 좀 있는데 한번 츄라이해보시는 것두..?.?', 43, 4, 'GOOD', SYSTIMESTAMP);
