INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '주말 6시쯤 방문했고 한 자리 남아있었습니다! 카페 분위기도 좋고 음료랑 디저트도 맛있어서 좋았어요  ◡̈ 강아지도 친절하게 반겨주셔서 감사해요🐾', 86, 17, 'GOOD', SYSTIMESTAMP);
