INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아지트 느낌나서 너무 편안하고 좋았어요. 즐길거리가 많은데 닌텐도 위에 드럼에 기타에~ 진짜 아지트같고 재밌는 공간이예요! 편안한 분위기라 혼자도와도 부담없고 친구랑오면 더 재밌읗것같아요. 음식들도 예쁘고 맛있었는데 특히 리치커렌트 릴렉서는 적당하게 기분좋은 단맛이라 또먹고싶어요! 커피젤리와 술젤리, 에그파이도 맛있다고 하는데 궁금해서 또 가봐야겠어요!', 33, 2, 'GOOD', SYSTIMESTAMP);
