INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '아늑한 작업실같은 분위기가 너무 좋아요! 나오는 노래도 이야기하며 쉬기에 딱 좋고, 한켠에 닌텐도 위도 있어 친구들과 놀 수도 있어요. 거기에 커피와 디저트, 칵테일까지 다 맛있어서 또 올 것 같습니다😄', 28, 5, 'GOOD', SYSTIMESTAMP);
