INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '언제나 아늑한 록집… 이번이 벌써 1n번째 방문인데요! 바질 향이 더욱 깊어진 록슈페너네용! 바질크림 듬뿍이라 마시면 산뜻하고 기분이 좋아지는 음료에여… 록집 최애 음료!! 오늘도 사장님만의 끝내주는 선곡 즐기면서 열심히 할 일 하고 갑니다~', 49, 8, 'GOOD', SYSTIMESTAMP);
