INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '상수에 이런 신상 카페 & 펍이 생기다니요!! 락 좋아하는 사람으로써 너무 취향 저격입니다 ✨ 노래는 물론이고 인테리어도 너무 좋아서 또 가고 싶어요. 상수역에 나만의 아지트 만들래요 ఇ', 12, 0, 'GOOD', SYSTIMESTAMP);
