INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '친구들이랑 라이딩하고 오게된 카펜데 아지트같이ㅜ편안하고 커피도 너무 맛있었습니당 인테리어도 편안하고 아늑한 느낌이어서 좋았습니다! 저녁에는 칵테일류도 파는데 나중엔 저녁에 칵테일도 먹으러 무조건 꼭 오겠습니다!!', 75, 17, 'GOOD', SYSTIMESTAMP);
