INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '밴드합주실에 아지트를 만들어 모이는 감성..?? 친구들이랑 오면 편하게 얘기나누기좋고 혼자와도 감성에취하기 딱 좋아용 버팔로윙이 너무너무맛있어용ㅠㅠ 이색인테리어 공간 너무 좋아용!!', 27, 10, 'GOOD', SYSTIMESTAMP);
