INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '사장님이 맛있고 메뉴가 멋져요💗..,,, 딱 멈무가 있을때 방문해서 강아지와 힐링하구 사장님의 쌈@뽕한 플리로 울고 왔습니다… 이곳은 진짜 유명한 카페 펍 맛집임🥹사랑해요', 32, 6, NULL, SYSTIMESTAMP);
