INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '여기 들어오자마자 인테리어도 아지트처럼 아늑하게 잘돼있어서 좋았어요! 음료도 너무 맛있고 사진이 엄청 잘나와요. 공간이 맛있고 커피가 친절해요 사장님 짱', 9, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '카페..? 인가..? 하고 들어갔는데, 음식도 맛있고 분위기랑 플리는 더 맛있었습니다. 아지트 느낌 낭낭한게 딱 제 취향이네여 앞으로 상수 올 일 있으면 자주 올게요!', 27, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '분위기 좋아보여서 들어갔는데 커피도 고소하고 파이가 진짜 맛있습니다😳 단쓴 조합에 딱.. 들어가는 순간 엄청 아늑하고 집같은 느낌에 음악도 좋아서 녹아들더라고요.. 편하게 놀다 갑니다!! 친구랑 가도 연인이랑 가도 좋을 것 같아요ㅎㅎ 갈때쯤 사장님께서 요리중이셨는데 냄새가 미쳤어요🥵 다음엔 음주하러 방문하겠습니다 !', 69, 17, NULL, SYSTIMESTAMP);
