INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '와우…에그타르트 먹어 본 것 중 여기가 최고였어요..🥹 바질아인슈페너 처음인데 왜 이렇게 맛있나요!! 분위기도 좋아서 다음에 또 올게요~~ (아메리카노도 맛있다는!)', 35, 9, NULL, SYSTIMESTAMP);
