INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '사장님이 너무 친절하시고 분위기가 너무 이쁜 카페입니다. 혼자오셔도 좋을 것 같고 사장님이랑 편하게 이야기도하면서 커피 술을 즐길수 있을 것 같습니다.', 33, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '상수 새로생긴 바/카페. 아늑하고 칵테일 맛있었어요😁 매장에 닌텐도 위가 있어서 친구들과 위스포츠도 했습니다. 버팔로윙의 익힘 정도는 적당했어요', 6, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '정말 멋진 밴드 교정, 그리고 밴드의 은은한 분위기와 정말 잘 어울리는 록집의 ROCK 디자인이 정말 최고의 하모니를 만들어냅니다', 40, 5, NULL, SYSTIMESTAMP);
