INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '친구랑 우연히 들어가게 된 카페겸 펍! 아늑한 아지트같은 분위기에다가 사장님도 친절하셔서 즐거운 시간 보내다 갑니다.!! 근처 오면 자주 들릴 것 같아요', 46, 9, NULL, SYSTIMESTAMP);
